// Function to perform DNS resolution for a given hostname using standard library functions
u_char* resolve_hostname(const char* hostname) {
  struct addrinfo hints, *res;
  int errcode;

  // Initialize the address info structure
  memset(&hints, 0, sizeof(struct addrinfo));
  hints.ai_family = AF_INET;
  hints.ai_socktype = SOCK_STREAM;

  // Perform DNS resolution
  if ((errcode = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
    fprintf(stderr, "Error: %s\n", gai_strerror(errcode));
    return NULL;
  }

  // Get the IP address from the first result
  u_char* ip = (u_char*) res->ai_addr;

  // Free the memory allocated by getaddrinfo
  freeaddrinfo(res);

  return ip;
}

// Function to read a configuration file and determine which text files to process
