class CipherContext {
public:
    virtual ~CipherContext() {}
    virtual void init(const string& cipher, const string& mode) = 0;
    virtual void encrypt(const vector<uint8_t>& input, vector<uint8_t>& output) = 0;
    virtual void decrypt(const vector<uint8_t>& input, vector<uint8_t>& output) = 0;
};

class AESCipherContext : public CipherContext {
public:
    AESCipherContext() {
        cipher.SetKeyLength(128);
        cipher.AutoKey();
    }

    void init(const string& cipher, const string& mode) override {
        if (cipher == "AES-128") {
            this->mode = CryptoPP::CBC_Mode<CryptoPP::AES>::Encryption;
        } else if (cipher == "AES-192") {
            this->mode = CryptoPP::GCM_Mode<CryptoPP::AES>::Encryption;
        } else if (cipher == "AES-256") {
            this->mode = CryptoPP::GCM_Mode<CryptoPP::AES>::Decryption;
        } else {
            throw std::invalid_argument("Unsupported cipher: " + cipher);
        }
    }

    void encrypt(const vector<uint8_t>& input, vector<uint8_t>& output) override {
        CryptoPP::CBC_Mode<CryptoPP::AES>::Encryption enc;
        enc.SetKeyWithIV(this->key, this->iv);
        enc.SetLength(input.size());

        SecByteBlock output_buffer(output.size());
        enc.Update(input.data(), input.size(), output_buffer);
        enc.Final(output_buffer);
    }

    void decrypt(const vector<uint8_t>& input, vector<uint8_t>& output) override {
        CryptoPP::CBC_Mode<CryptoPP::AES>::Decryption dec;
        dec.SetKeyWithIV(this->key, this->iv);
        dec.SetLength(input.size());

        SecByteBlock output_buffer(output.size());
        dec.Update(input.data(), input.size(), output_buffer);
        dec.Final(output_buffer);
    }

private:
