class FileCipherProcessor {
public:
    FileCipherProcessor(const string& input_file, const string& output_file, CipherContext* cipher_context) :
        input_file(input_file),
        output_file(output_file),
        cipher_context(cipher_context) {}

    void processFile() {
        ifstream file(input_file, ios::binary);
        ofstream out(output_file, ios::binary | ios::out);
        if (!file.is_open()) {
            throw std::invalid_argument("Failed to open input file: " + input_file);
        }
        if (!out.is_open()) {
            throw std::invalid_argument("Failed to create output file: " + output_file);
        }

        // Read the input file in chunks
        vector<uint8_t> buffer(1024 * 1024);
        while (true) {
            ifstream.read((char*)buffer.data(), buffer.size());
            size_t bytes_read = file.gcount();
            if (bytes_read == 0) {
                break;
            }

            // Encrypt/decrypt the chunk
            vector<uint8_t> encrypted(buffer.size() * cipher_context->cipher.MaxRounds());
            cipher_context->encrypt(buffer, encrypted);

            // Write the encrypted chunk to output file
            out.write((char*)encrypted.data(), encrypted.size());
        }
    }
private:
    string input_file;
    string output_file;
    CipherContext* cipher_context;
};

int main(int argc, char** argv) {
    // Validate command line arguments
    if (argc < 4) {
