    if (!file.is_open()) {
        cout << "Failed to open input file: " << input_file << endl;
        return 1;
    }
    file.close();

    // Validate output file path
    ofstream out(output_file, ios::binary | ios::out);
    if (!out.is_open()) {
        cout << "Failed to create output file: " << output_file << endl;
        return 1;
    }
    out.close();

    // Validate cipher and mode
    CipherContext* cipher_context = nullptr;
    if (cipher == "AES") {
        cipher_context = new AESCipherContext(mode);
    } else {
        cout << "Invalid cipher: " << cipher << endl;
        return 1;
    }

    // Process the file
    FileCipherProcessor processor(input_file, output_file, cipher_context);
    processor.processFile();

    delete cipher_context;
    return 0;
}
