// Define a struct to represent a semaphore
typedef struct {
    sem_t *sem; // Pointer to the semaphore
    int id; // Unique identifier for the semaphore
} Semaphore;

// Define an array to store all created semaphores
static Semaphore *semaphores = NULL;

// Function to create a new semaphore
Semaphore *create_semaphore(int id) {
    // Allocate memory for the semaphore
    semaphore = (Semaphore *)malloc(sizeof(Semaphore));
    if (!semaphore) {
        fprintf(stderr, "Error: Failed to allocate memory for semaphore\n");
        return NULL;
    }

    // Initialize the semaphore
    sem_init(&semaphore->sem, 0, 0);

    // Add the new semaphore to the list of created semaphores
    semaphores = (Semaphore *)realloc(semaphores, sizeof(Semaphore) * (num_semaphores + 1));
    if (!semaphores) {
        fprintf(stderr, "Error: Failed to reallocate memory for semaphore list\n");
        return NULL;
    }
    semaphores[num_semaphores++] = semaphore;

    // Return the new semaphore
    return semaphore;
}

// Function to delete a semaphore
int delete_semaphore(Semaphore *semaphore) {
    int i, j;

    // Find the index of the given semaphore in the list of created semaphores
    for (i = 0; i < num_semaphores; i++) {
        if (semaphores[i] == semaphore) {
            break;
        }
    }

    // If the semaphore was found in the list, remove it and free its memory
    if (i < num_semaphores) {
        // Remove the semaphore from the list
        for (j = i; j < num_semaphores - 1; j++) {
            semaphores[j] = semaphores[j + 1];
        }
        num_semaphores--;

        // Free the memory allocated to the semaphore
        free(semaphore->sem);
        free(semaphore);
    } else {
        fprintf(stderr, "Error: Semaphore not found in list\n");
    }

    return 0;
}

// Function to acquire a semaphore
int acquire_semaphore(Semaphore *semaphore) {
    // Acquire the semaphore
    if (sem_wait(semaphore->sem)) {
        fprintf(stderr, "Error: Failed to acquire semaphore\n");
        return -1;
    }

    return 0;
}

// Function to release a semaphore
int release_semaphore(Semaphore *semaphore) {
    // Release the semaphore
    if (sem_post(semaphore->sem)) {
        fprintf(stderr, "Error: Failed to release semaphore\n");
        return -1;
    }

    return 0;
}
