    cmd.arg("build").arg("--release");
    if target_arch == "x86" {
        cmd.arg("-Ctarget=x86-unknown-linux-gnu");
    } else if target_arch == "arm" {
        cmd.arg("-Ctarget=arm-unknown-linux-gnueabihf");
    } else {
        return Err(Box::new(UnsupportedArchitectureError));
    }
    if optimization_level == "0" {
        cmd.arg("-Copt-level=0");
    } else if optimization_level == "1" {
        cmd.arg("-Copt-level=1");
    } else if optimization_level == "2" {
        cmd.arg("-Copt-level=2");
    } else {
        return Err(Box::new(UnsupportedOptimizationLevelError));
    }

