                Some(plugin) => plugin,
                None => {
                    let start = Instant::now();
                    let res = fetch_compiler_plugin(dep);
                    let elapsed = start.elapsed();
                    cache.insert(dep, res);
                    if elapsed > Duration::from_secs(1) {
                        // Handle potential network failures
                        println!("Failed to fetch compiler plugin: {}", dep);
                    } else {
                        println!("Fetched compiler plugin: {} in {:.2} seconds", dep, elapsed.as_secs_f64());
                    }
                },
            };
            cmd.arg("-Cplugin").arg(plugin);
        }
    }

    // Generate assembly code
    let output = cmd.output()?;
    if !output.status.success() {
        return Err(Box::new(CommandError));
    }

    // Convert the output into a string and return it
    Ok(String::from_utf8_lossy(&output.stdout).to_string())
}
