function refreshDialogFields(fieldNames, resourceId, url) {
  // Iterate through all dialog fields and check for matches with the given field names
  let fields = document.querySelectorAll('[ng-model]');
  for (let i = 0; i < fields.length; i++) {
    if (fieldNames.includes(fields[i].getAttribute('ng-model'))) {
      // Send message to parent window indicating successful refresh of the field
      window.parent.postMessage({
        type: 'refreshed-field',
        data: {
          id: resourceId,
          url: url,
          fieldName: fields[i].getAttribute('ng-model'),
        },
      });
    }
  }
}
