  let isStopped = false;
  let serviceTimerId;

  function processIncomingData(data) {
    if (isPaused || isStopped) return;
    dataArray.push(data);
  }

  function handleServiceLifecycleEvents() {
    const lifecycleEvents = [
      'start',
      'pause',
      'resume',
      'stop',
    ];

    lifecycleEvents.forEach((event) => {
      if (event === 'start') {
        serviceTimerId = setInterval(() => {
          const data = retrieveDataFromStreamingSource();
          processIncomingData(data);
        }, 1000); // 1 second delay between retries
      } else if (event === 'pause') {
        isPaused = true;
      } else if (event === 'resume') {
        isPaused = false;
      } else if (event === 'stop') {
        clearInterval(serviceTimerId);
        isStopped = true;
        eventBroker.notify('service_stopped'); // notify external event broker
      }
    });
  }

