import java.io.*;
import java.util.*;
import java.util.logging.*;

public class FileProcessor {
    private static final Logger logger = Logger.getLogger(FileProcessor.class.getName());

    public static void main(String[] args) {
        List<String> filePaths = Arrays.asList("path/to/file1", "path/to/file2", "path/to/dir1/", "path/to/dir2/");
        Map<String, Long> fileTypes = new HashMap<>();
        long totalFileSize = 0;

        for (String path : filePaths) {
            try {
                File file = new File(path);
                if (file.isDirectory()) {
                    processDirectory(file);
                } else {
                    processFile(file);
                }
            } catch (IOException e) {
                logger.log(Level.WARNING, "Error processing path: " + path, e);
            }
        }

        System.out.println("Total file size: " + totalFileSize);
        System.out.println("File types distribution: " + fileTypes);
    }

    private static void processDirectory(File dir) throws IOException {
        File[] files = dir.listFiles();
        for (File file : files) {
            if (file.isDirectory()) {
                processDirectory(file);
            } else {
                processFile(file);
            }
        }
    }

    private static void processFile(File file) throws IOException {
        logger.log(Level.INFO, "Processing file: " + file.getPath());
        long fileSize = file.length();
        String fileType = getFileType(file);
        fileTypes.merge(fileType, 1L, Long::sum);
        totalFileSize += fileSize;
    }

    private static String getFileType(File file) {
        return file.getName().substring(file.getName().lastIndexOf(".") + 1);
    }
}
```']

