public class ThemeCache {
  private static final Logger logger = Logger.getLogger(ThemeCache.class.getName());

  // Directory for storing themes
  private String themeDir;

  // Cache for storing parsed PNG files
  private Map<String, BufferedImage> cache;

  public ThemeCache() {
    // Initialize the cache and theme directory
    this.cache = new ConcurrentHashMap<>();

    if (System.getProperty("user.dir") != null) {
      themeDir = System.getProperty("user.dir") + File.separator + "themes";
    } else {
      throw new IllegalStateException("Unable to determine the default theme directory");
    }

    // Initialize the cache with any existing themes
    try {
      for (File file : new File(themeDir).listFiles()) {
        if (file.getName().endsWith(".png")) {
          BufferedImage image = ImageIO.read(file);
          cache.put(file.getName(), image);
        }
      }
    } catch (IOException e) {
      logger.severe("Error initializing theme cache: " + e.getMessage());
    }
  }

  // Add a new theme to the cache and return it
  public BufferedImage addTheme(String fileName) throws IOException {
    if (!cache.containsKey(fileName)) {
      File file = new File(themeDir, fileName);
      if (file.exists()) {
        BufferedImage image = ImageIO.read(file);
        cache.put(fileName, image);
      } else {
        throw new IOException("Theme " + fileName + " does not exist");
      }
    }

    return cache.get(fileName);
