<?php
function updateUserPassword($userId, $newPassword) {
    // Validate input parameters
    if (!is_numeric($userId) || strlen($newPassword) < 8) {
        throw new Exception("Invalid input parameters");
    }

    // Validate password strength according to predefined criteria
    if (strlen($newPassword) < 12 || !preg_match("/[A-Z]/", $newPassword) || !preg_match("/[a-z]/", $newPassword) || !preg_match("/[0-9]/", $newPassword)) {
        throw new Exception("Invalid password strength");
    }

    // Update user's password in the local database
    $db = getDatabaseConnection();
    $stmt = $db->prepare("UPDATE users SET password = :password WHERE id = :userId");
    $stmt->bindParam(':password', $newPassword);
    $stmt->bindParam(':userId', $userId);
    $stmt->execute();

    // Asynchronously update the user's password in an external identity provider (IDP) and message broker
    $idp = getIdentityProviderConnection();
    $mb = getMessageBrokerConnection();
    $msg = json_encode(array("userId" => $userId, "password" => $newPassword));
    $idp->updateUserPassword($msg);
    $mb->sendUpdateUserPasswordMessage($msg);

    // Handle error conditions gracefully
    if ($stmt->errorCode() !== 0) {
        throw new Exception("Error updating user password in local database: " . $stmt->errorInfo());
    }

    // Ensure idempotency and minimize database locking during the update process
    $db->commit();

    // Record successful and failed attempts in a centralized logging service
    $logger = getLoggerConnection();
    $logger->info("Successfully updated user password for user " . $userId);
}
?>
