StateList* create_state_list(int *states, size_t num_states, FSA fsa) {
    // Check if the input array is valid
    if (num_states == 0 || states == NULL) {
        return NULL;
    }

    // Create a new state list structure
    StateList *state_list = malloc(sizeof(StateList));
    if (state_list == NULL) {
