    for (i = 0; i < num_states; ++i) {
        if (!fsa_has_state(fsa, states[i])) {
            fprintf(stderr, "State %d is not a valid state in the FSA\n", states[i]);
            free(state_list);
            return NULL;
        }
    }

    // Maintain the transition relationships defined by the FSA
    state_list->fsa = fsa;
    state_list->num_states = num_states;
    state_list->states = malloc(sizeof(int) * num_states);
    if (state_list->states == NULL) {
        fprintf(stderr, "Failed to allocate memory for the state list\n");
        free(state_list);
        return NULL;
    }
    memcpy(state_list->states, states, sizeof(int) * num_states);

    // Handle memory allocation failures gracefully
    if (state_list->states == NULL || state_list->fsa == NULL) {
        fprintf(stderr, "Failed to allocate memory for the state list\n");
        free(state_list->states);
        free(state_list);
        return NULL;
    }

    // Optimize memory usage by reusing existing memory structures when possible
