    if (num_bytes < MIN_MEMORY_SIZE) {
        num_bytes = MIN_MEMORY_SIZE;
    }
    void *ptr = malloc(num_bytes);
    if (ptr == NULL) {
        fprintf(stderr, "Failed to allocate memory for the state list\n");
        free(state_list->states);
        free(state_list);
        return NULL;
    }
    memcpy(ptr, state_list, num_bytes);

    // Implement thread-safe operations if necessary
    pthread_mutex_lock(&state_list->mutex);

    // Log the creation of the new state list
    log_event("Created a new state list from an FSA");

    return state_list;
}
