['```cpp
class DynamicOctree {
private:
    struct Node {
        int featureSize;
        int numLeafNodes;
        int dataCapacity;
        std::vector<Node*> children;
        std::vector<int> dataIndices;
    };

    std::vector<Node*> nodes;
    std::mutex mutex;

public:
    DynamicOctree(int featureSize, int numLeafNodes, int dataCapacity) {
        this->featureSize = featureSize;
        this->numLeafNodes = numLeafNodes;
        this->dataCapacity = dataCapacity;
    }

    ~DynamicOctree() {
        deleteAllNodes();
    }

    void insert(const std::vector<int>& data) {
        // Check if the data is valid and within the capacity limit
        if (data.size() != featureSize || data.size() > dataCapacity) {
            return;
        }

        // Find the node to insert the data into
        Node* node = findNodeToInsert(data);
        if (!node) {
            return;
        }

        // Insert the data into the node
        int dataIndex = node->dataIndices.size();
        node->dataIndices.push_back(dataIndex);
        node->children.push_back(new Node());
        node->children[dataIndex]->dataIndices.push_back(dataIndex);

        // Check if the node needs to be split
        int numData = node->dataIndices.size();
        if (numData > numLeafNodes) {
            splitNode(node);
        }
    }

    void delete(const std::vector<int>& data) {
        // Find the node to delete from
        Node* node = findNodeToDelete(data);
        if (!node) {
            return;
        }

        // Delete the data from the node
        int dataIndex = node->dataIndices.size();
        node->dataIndices.erase(std::remove(node->dataIndices.begin(), node->dataIndices.end(), dataIndex), node->dataIndices.end());
        node->children.erase(std::remove(node->children.begin(), node->children.end(), dataIndex), node->children.end());

        // Check if the node needs to be merged
        int numData = node->dataIndices.size();
        if (numData < numLeafNodes) {
            mergeNode(node);
        }
    }

    bool query(const std::vector<int>& data, int& result) const {
        // Find the node to query
        Node* node = findNodeToQuery(data);
        if (!node) {
            return false;
        }

        // Check if the data is in the node
        int dataIndex = std::find(node->dataIndices.begin(), node->dataIndices.end(), dataIndex);
        if (dataIndex == node->dataIndices.end()) {
            return false;
        }

        // Return the result
        result = node->children[dataIndex]->dataIndices[0];
        return true;
    }

private:
    void splitNode(Node* node) {
        // Split the node into two children
        Node* leftChild = new Node();
        Node* rightChild = new Node();
        std::copy_n(node->dataIndices.begin(), numLeafNodes, std::back_inserter(leftChild->dataIndices));
        std::copy_n(node->children.begin() + numLeafNodes, node->dataIndices.size() - numLeafNodes, std::back_inserter(rightChild->dataIndices));
        leftChild->children = std::vector<Node*>(leftChild->dataIndices.size(), nullptr);
        rightChild->children = std::vector<Node*>(rightChild->dataIndices.size(), nullptr);
        node->children[numLeafNodes] = leftChild;
        node->children[node->dataIndices.size() - numLeafNodes + 1] = rightChild;
    }

    void mergeNode(Node* node) {
        // Merge the node into its parent
        Node* parent = node->parent;
        if (!parent) {
            return;
        }

        int dataIndex = std::find(parent->dataIndices.begin(), parent->dataIndices.end(), node);
        if (dataIndex == parent->dataIndices.end()) {
            return;
        }

        Node* leftChild = parent->children[dataIndex - 1];
        Node* rightChild = parent->children[dataIndex + 1];
        std::vector<int> mergedDataIndices;
        std::copy(leftChild->dataIndices.begin(), leftChild->dataIndices.end(), std::back_inserter(mergedDataIndices));
        std::copy(rightChild->dataIndices.begin(), rightChild->dataIndices.end(), std::back_inserter(mergedDataIndices));
        parent->children[dataIndex - 1] = nullptr;
        parent->children[dataIndex + 1] = nullptr;
        parent->children.erase(std::remove(parent->children.begin(), parent->children.end(), leftChild), parent->children.end());
        parent->children.erase(std::remove(parent->children.begin(), parent->children.end(), rightChild), parent->children.end());
    }

    void deleteAllNodes() {
        for (Node* node : nodes) {
            if (!node) {
                continue;
            }
            deleteNode(node);
        }
    }

    void deleteNode(Node* node) {
        // Delete the node and its children
        for (Node* child : node->children) {
            if (!child) {
                continue;
            }
            deleteNode(child);
        }
        delete node;
    }
};
```']

