Here is an example of how to implement a resilient aggregation service in Node.js that processes a stream of numerical events asynchronously:
```javascript
const { EventEmitter } = require('events');
const { createServer } = require('http');
const { setTimeout, setInterval } = require('timers').promises;

class AggregationService extends EventEmitter {
  constructor(options) {
    super();
    this.options = options;
    this.runningTotal = 0;
    this.lastError = null;
    this.backoffStrategy = 'exponential';
    this.maxRetryAttempts = 3;
    this.retryCount = 0;
    this.logLevel = 'info';
    this.errorHandler = (err) => {
      console.error('Error in AggregationService:', err);
      if (this.lastError !== err) {
        this.lastError = err;
        this.emit('error', err);
      }
    };
  }

  async start() {
    const server = createServer((req, res) => {
      // Handle incoming requests and send responses
      if (req.method === 'GET') {
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ runningTotal: this.runningTotal }));
      } else {
        // Handle POST requests for data updates
        let event = null;
        try {
          event = JSON.parse(req.body);
        } catch (err) {
          this.errorHandler(err);
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'Invalid data type for event.' }));
        }

        if (!event || !event.value) {
          this.errorHandler(new Error('Missing value in event metadata.'));
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'Missing value in event metadata.' }));
        }

        const { timestamp, sourceSystemVersion } = event.metadata;
        this.runningTotal += event.value;
        console.log(`Received event with value ${event.value} and timestamp ${timestamp}.`);
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ success: true }));
      }
    });

    server.listen(3000, () => {
      console.log('Aggregation service started on port 3000.');
    });

    // Handle backoff strategy and retry failed operations
    const retry = async (fn) => {
      try {
        await fn();
      } catch (err) {
        this.retryCount++;
        if (this.retryCount <= this.maxRetryAttempts) {
          console.log(`Error in AggregationService: ${err}. Retrying...`);
          setTimeout(() => retry(fn), 1000 * Math.pow(2, this.retryCount));
        } else {
          this.errorHandler(err);
          console.log('Maximum number of retries exceeded.');
        }
      }
    };

    const handleError = (err) => {
      if (this.lastError !== err) {
        this.lastError = err;
        this.emit('error', err);
      }
    };

    // Handle network latency and potential timeouts
    server.on('close', () => {
      console.log('Server closed.');
    });

    const handleTimeout = async (res) => {
      if (!res.finished) {
        console.log(`Request timed out after ${res.timeout} ms.`);
        res.end(JSON.stringify({ error: 'Request timed out.' }));
      }
    };

    const handleNetworkError = (err, req, res) => {
      if (!res.finished) {
        console.log(`Network error occurred while handling request: ${err}`);
        res.end(JSON.stringify({ error: 'Network error.' }));
      }
    };

    server.on('timeout', handleTimeout);
    server.on('error', handleNetworkError);

    // Handle intermittent connectivity issues
    const handleDisconnect = (req, res) => {
      console.log(`Client disconnected from server while handling request.`);
      res.end(JSON.stringify({ error: 'Client disconnected.' }));
    };

    server.on('disconnect', handleDisconnect);
  }
}

const options = {
  backoffStrategy: 'exponential',
  maxRetryAttempts: 3,
  logLevel: 'info'
};

// Start the service with the specified configuration options
const aggregationService = new AggregationService(options);
aggregationService.start();
```
