int load_config(const char *file_path, struct configuration *conf) {
  // Open the configuration file for reading
  int fd = open(file_path, O_RDONLY);
  if (fd < 0) {
    syslog(LOG_ERR, "Failed to open configuration file %s: %s", file_path, strerror(errno));
    return -1;
  }

  // Read the contents of the file into a buffer
  struct stat sb;
  if (fstat(fd, &sb) < 0) {
    syslog(LOG_ERR, "Failed to read configuration file %s: %s", file_path, strerror(errno));
    close(fd);
    return -1;
  }

  char *buffer = malloc(sb.st_size + 1);
  if (!buffer) {
    syslog(LOG_ERR, "Failed to allocate memory for configuration file %s", file_path);
    close(fd);
    return -1;
  }

  ssize_t nread = read(fd, buffer, sb.st_size);
  if (nread < 0) {
    syslog(LOG_ERR, "Failed to read configuration file %s: %s", file_path, strerror(errno));
    free(buffer);
    close(fd);
    return -1;
  }

  buffer[nread] = '\0';
  close(fd);

  // Parse the configuration file contents using a config parser library
  struct config_section *sections = parse_config_file(buffer, nread);
  if (!sections) {
    syslog(LOG_ERR, "Failed to parse configuration file %s", file_path);
    free(buffer);
    return -1;
  }

  // Validate the configuration data and log any errors or warnings
  int num_errors = validate_config_data(sections);
  if (num_errors > 0) {
    syslog(LOG_WARNING, "Encountered %d error%s while validating configuration file %s", num_errors, (num_errors == 1) ? "" : "s", file_path);
  } else {
    syslog(LOG_INFO, "Successfully loaded configuration file %s", file_path);
  }

  // Update the configuration structure with the parsed data
  conf->file_path = file_path;
  conf->sections = sections;

  return 0;
}

int update_config(const char *file_path, struct configuration *conf) {
  // Open the configuration file for reading
  int fd = open(file_path, O_RDONLY);
  if (fd < 0) {
    syslog(LOG_ERR, "Failed to open configuration file %s: %s", file_path, strerror(errno));
    return -1;
  }

  // Read the contents of the file into a buffer
