  ssize_t nread = read(fd, buffer, sb.st_size);
  if (nread < 0) {
    syslog(LOG_ERR, "Failed to read configuration file %s: %s", file_path, strerror(errno));
    free(buffer);
    close(fd);
    return -1;
  }

  buffer[nread] = '\0';
  close(fd);

  // Parse the configuration file contents using a config parser library
  struct config_section *sections = parse_config_file(buffer, nread);
  if (!sections) {
    syslog(LOG_ERR, "Failed to parse configuration file %s", file_path);
    free(buffer);
    return -1;
  }

