  int num_errors = validate_config_data(sections);
  if (num_errors > 0) {
    syslog(LOG_WARNING, "Encountered %d error%s while validating configuration file %s", num_errors, (num_errors == 1) ? "" : "s", file_path);
  } else {
    syslog(LOG_INFO, "Successfully loaded updated configuration file %s", file_path);
  }

  // Update the configuration structure with the parsed data
  conf->file_path = file_path;
  conf->sections = sections;

  return 0;
}

void free_config(struct configuration *conf) {
  if (!conf) {
    return;
  }

  // Free any dynamically allocated memory for the configuration sections
  struct config_section *sections = conf->sections;
  while (sections) {
    struct config_section *next = sections->next;
    free(sections);
    sections = next;
  }

  // Free the configuration structure itself
  free(conf);
}

int validate_config_data(struct config_section *sections) {
  // Validate each section in the configuration data
  struct config_section *cur_section = sections;
  int num_errors = 0;
  while (cur_section) {
    // Check for invalid keys or values
    if (!cur_section->num_keys || !cur_section->values) {
      syslog(LOG_WARNING, "Invalid configuration data in section %s", cur_section->name);
      num_errors++;
    } else {
      // Check for duplicates and inconsistencies between keys and values
      int i = 0;
      while (i < cur_section->num_keys) {
        if (!cur_section->keys[i] || !cur_section->values[i]) {
          syslog(LOG_WARNING, "Invalid key-value pair in section %s", cur_section->name);
          num_errors++;
        } else {
          // Check for valid data types and values
          if (validate_key(cur_section->keys[i]) && validate_value(cur_section->values[i])) {
            syslog(LOG_INFO, "Valid key-value pair in section %s", cur_section->name);
          } else {
            syslog(LOG_WARNING, "Invalid key-value pair in section %s", cur_section->name);
            num_errors++;
          }
        }
        i++;
      }
    }
    cur_section = cur_section->next;
  }

  return num_errors;
}

int validate_key(const char *key) {
  // Check for invalid characters in the key name
  int len = strlen(key);
  if (len == 0) {
    syslog(LOG_WARNING, "Invalid key name");
    return 0;
  }

  const char *invalid_chars = " ,\t\n\r";
  for (int i = 0; i < len; i++) {
    if (strchr(invalid_chars, key[i])) {
      syslog(LOG_WARNING, "Invalid character in key name");
      return 0;
    }
  }

  return 1;
}

int validate_value(const char *value) {
  // Check for invalid characters in the value
  int len = strlen(value);
  if (len == 0) {
    syslog(LOG_WARNING, "Invalid value");
    return 0;
  }

  const char *invalid_chars = " \t\n\r";
  for (int i = 0; i < len; i++) {
    if (strchr(invalid_chars, value[i])) {
      syslog(LOG_WARNING, "Invalid character in value");
      return 0;
    }
  }

  return 1;
}
