    int plaintext_len;
    unsigned char *plaintext = NULL;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        ERR_print_errors_fp(stderr);
        return;
    }
    EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key->key, iv->iv);
    EVP_CIPHER_CTX_set_padding(ctx, 0);
    EVP_DecryptUpdate(ctx, plaintext, &plaintext_len, ciphertext, ciphertext_len);
    EVP_DecryptFinal_ex(ctx, plaintext + plaintext_len, &plaintext_len);
    EVP_CIPHER_CTX_free(ctx);
}

void sign(const unsigned char *message, size_t message_len, const crypt_key_t *private_key) {
    // Sign the message using RSA-SHA1 with the specified private key
    int signature_len;
    unsigned char *signature = NULL;
    EVP_MD_CTX *ctx = EVP_MD_CTX_create();
    if (!ctx) {
        ERR_print_errors_fp(stderr);
        return;
    }
    EVP_DigestSignInit(ctx, NULL, EVP_sha1(), NULL, private_key->key);
    EVP_DigestSignUpdate(ctx, message, message_len);
    EVP_DigestSignFinal(ctx, signature, &signature_len);
    EVP_MD_CTX_free(ctx);
}

void verify(const unsigned char *message, size_t message_len, const unsigned char *signature, size_t signature_len, const crypt_key_t *public_key) {
    // Verify the signature using RSA-SHA1 with the specified public key
    int result;
    EVP_MD_CTX *ctx = EVP_MD_CTX_create();
    if (!ctx) {
        ERR_print_errors_fp(stderr);
        return;
    }
    EVP_DigestVerifyInit(ctx, NULL, EVP_sha1(), NULL, public_key->key);
    EVP_DigestVerifyUpdate(ctx, message, message_len);
    result = EVP_DigestVerifyFinal(ctx, signature, signature_len);
    if (result != 1) {
        // Signature verification failed
        ERR_print_errors_fp(stderr);
    }
    EVP_MD_CTX_free(ctx);
}
