['```csharp
using System;
using System.Security.Cryptography;
using System.Text;

namespace MessageProcessor
{
    public class MessageProcessor
    {
        private const string ALGORITHM = "TripleDES";
        private const int KEY_LENGTH = 24;
        private const int IV_LENGTH = 8;

        // Encrypts a message using Triple DES with the specified key and initialization vector (IV)
        public static string Encrypt(string message, byte[] key, byte[] iv)
        {
            if (!ValidateInput(message, key, iv))
            {
                return null;
            }

            try
            {
                using (var tripleDes = new TripleDESCryptoServiceProvider())
                {
                    tripleDes.Key = key;
                    tripleDes.IV = iv;
                    var encryptedMessage = EncryptInternal(message, tripleDes);
                    return Convert.ToBase64String(encryptedMessage);
                }
            }
            catch (Exception e)
            {
                Console.WriteLine($"Error during encryption: {e.Message}");
                return null;
            }
        }

        // Decrypts a message using Triple DES with the specified key and initialization vector (IV)
        public static string Decrypt(string encryptedMessage, byte[] key, byte[] iv)
        {
            if (!ValidateInput(encryptedMessage, key, iv))
            {
                return null;
            }

            try
            {
                using (var tripleDes = new TripleDESCryptoServiceProvider())
                {
                    tripleDes.Key = key;
                    tripleDes.IV = iv;
                    var message = DecryptInternal(encryptedMessage, tripleDes);
                    return Encoding.UTF8.GetString(message);
                }
            }
            catch (Exception e)
            {
                Console.WriteLine($"Error during decryption: {e.Message}");
                return null;
            }
        }

        // Validates the integrity of the input parameters
        private static bool ValidateInput(string message, byte[] key, byte[] iv)
        {
            if (message == null || key == null || iv == null)
            {
                Console.WriteLine("Invalid input parameters");
                return false;
            }

            if (key.Length != KEY_LENGTH || iv.Length != IV_LENGTH)
            {
                Console.WriteLine($"Invalid key or IV length ({KEY_LENGTH} bytes for the key and {IV_LENGTH} bytes for the IV)");
                return false;
            }

            return true;
        }

        // Encrypts a message using the specified cryptographic algorithm
        private static byte[] EncryptInternal(string message, SymmetricAlgorithm algo)
        {
            var messageBytes = Encoding.UTF8.GetBytes(message);
            using (var encryptor = algo.CreateEncryptor())
            {
                return encryptor.TransformFinalBlock(messageBytes, 0, messageBytes.Length);
            }
        }

        // Decrypts a message using the specified cryptographic algorithm
        private static byte[] DecryptInternal(string encryptedMessage, SymmetricAlgorithm algo)
        {
            var encryptedMessageBytes = Convert.FromBase64String(encryptedMessage);
            using (var decryptor = algo.CreateDecryptor())
            {
                return decryptor.TransformFinalBlock(encryptedMessageBytes, 0, encryptedMessageBytes.Length);
            }
        }
    }
}
```
