{
    private readonly string _filePath;
    private readonly Encoding _encoding;
    private readonly Func<Stream, Stream> _compressionAlgorithm;
    private readonly SerializationBinder _binder;

    public CompressedFileDeserializer(string filePath, Encoding encoding, Func<Stream, Stream> compressionAlgorithm, SerializationBinder binder)
    {
