        using var stream = File.OpenRead(_filePath);
        using var compressedStream = _compressionAlgorithm(stream);
        using var reader = new StreamReader(compressedStream, _encoding);
        using var serializer = new DataContractSerializer(typeof(T), _binder);

        return (T)serializer.ReadObject(reader);
    }
}
