    public static <T> T deserialize(byte[] serializedData, Class<T> clazz) {
        try (ObjectInputStream in = new ObjectInputStream(new ByteArrayInputStream(serializedData))) {
            T object = in.readObject();
            if (object != null) {
                // Handle deprecated fields gracefully by setting default values for missing fields
                Field[] fields = clazz.getDeclaredFields();
                Map<String, Object> fieldValues = new HashMap<>();
                for (Field field : fields) {
