struct Vertex {
  string name;
  int id;
};

struct Edge {
  int weight;
};

// Define a cache class to store frequently accessed nodes
class Cache {
 public:
  Cache(int memory_limit) : memory_limit_(memory_limit) {}

  // Add a new node to the cache
  void addNode(const Vertex& vertex) {
    if (size() < memory_limit_) {
      nodes_.push_back(vertex);
    } else {
      // Evict an old node from the cache if necessary
      nodes_.erase(nodes_.begin());
      nodes_.push_back(vertex);
    }
  }

  // Get a node from the cache by its ID
  const Vertex* getNode(int id) {
    for (auto it = nodes_.begin(); it != nodes_.end(); ++it) {
      if (it->id == id) {
        return &(*it);
      }
    }
    return nullptr;
  }

 private:
  // Cache size limit
  int memory_limit_;

  // List of cached nodes
  vector<Vertex> nodes_;
};

// Define a graph class to manage vertex and edge operations
