#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

struct Task {
    char *description;
    int priority;
    time_t deadline;
};

struct TaskList {
    struct Task *tasks;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
};

struct TaskList* initTaskList(size_t initialCount, int minPriority, int maxPriority) {
    // Initialize the task list with the given number of tasks and priorities
    struct TaskList *list = malloc(sizeof(struct TaskList));
    list->tasks = malloc(initialCount * sizeof(struct Task));
    list->count = 0;
    list->capacity = initialCount;
    pthread_mutex_init(&list->mutex, NULL);

    // Validate the input parameters and initialize the task descriptions based on predefined templates
    if (initialCount > MAX_TASK_COUNT || minPriority < MIN_PRIORITY || maxPriority > MAX_PRIORITY) {
        return NULL;
    }
    for (int i = 0; i < initialCount; ++i) {
        list->tasks[i].description = generateTaskDescription(minPriority, maxPriority);
        list->tasks[i].priority = randomIntInRange(minPriority, maxPriority);
        list->tasks[i].deadline = time(NULL) + (rand() % 3600); // Generate a deadline between now and one hour from now
    }

    return list;
}

void addTask(struct TaskList *list, char *description, int priority, time_t deadline) {
    // Add the new task to the list, dynamically resizing it if necessary
    pthread_mutex_lock(&list->mutex);
    if (list->count == list->capacity) {
        list->tasks = realloc(list->tasks, (list->capacity + 10) * sizeof(struct Task));
        list->capacity += 10;
    }
    list->tasks[list->count].description = description;
    list->tasks[list->count].priority = priority;
    list->tasks[list->count].deadline = deadline;
    ++list->count;
    pthread_mutex_unlock(&list->mutex);
}

void removeTask(struct TaskList *list, int index) {
    // Remove the task at the given index from the list and shift the remaining tasks
    pthread_mutex_lock(&list->mutex);
    if (index < 0 || index >= list->count) {
        return;
    }
    --list->count;
    for (int i = index; i < list->count; ++i) {
        list->tasks[i] = list->tasks[i + 1];
    }
    pthread_mutex_unlock(&list->mutex);
}

void updateTask(struct TaskList *list, int index, char *newDescription, int newPriority, time_t newDeadline) {
    // Update the task at the given index with the new description and deadline
    pthread_mutex_lock(&list->mutex);
    if (index < 0 || index >= list->count) {
        return;
    }
    list->tasks[index].description = newDescription;
    list->tasks[index].priority = newPriority;
    list->tasks[index].deadline = newDeadline;
    pthread_mutex_unlock(&list->mutex);
}

struct Task* getTask(struct TaskList *list, int index) {
    // Return the task at the given index in the list, or NULL if the index is invalid
    if (index < 0 || index >= list->count) {
        return NULL;
    }
    return &list->tasks[index];
}

char* generateTaskDescription(int minPriority, int maxPriority) {
    // Generate a random task description based on the given priority range
    int priority = randomIntInRange(minPriority, maxPriority);
    switch (priority) {
        case 1:
            return "High Priority Task";
        case 2:
            return "Medium Priority Task";
        case 3:
            return "Low Priority Task";
        default:
            return "Invalid Priority Task";
    }
}

int randomIntInRange(int min, int max) {
    // Generate a random integer in the given range
    return (rand() % (max - min + 1)) + min;
}
```
