void* allocate_memory(size_t size) {
    void* mem = malloc(size);
    if (!mem) {
        // Fallback: use a shared pool of pre-allocated memory blocks
        mem = get_shared_pool_block();
    }
    return mem;
}

// Custom deallocation function for memory that was allocated using the custom allocator
void free_memory(void* mem) {
    if (mem) {
        // Free the memory block if it was not allocated from the shared pool
        free(mem);
    } else {
        // If the memory block was allocated from the shared pool, return it to the pool
        return_shared_pool_block();
    }
}

// Custom synchronization mechanism for accessing and modifying shared resources
void synchronize_memory(void* mem) {
    pthread_mutex_lock(&mem_lock);
    // Access and modify the memory block safely under high concurrency conditions
    pthread_mutex_unlock(&mem_lock);
}

// Custom logging mechanism for resource management events
void log_event(char* message) {
    printf("%s\n", message);
}

// Function to manage memory for multiple interconnected data structures: long offset values, int keys, and a record array of int values
struct record* allocate_memory(int num_records, int key_range, char* pattern, float load_factor) {
    // Validate input parameters
    if (num_records <= 0 || key_range < 0 || strlen(pattern) > MAX_PATTERN_LENGTH) {
        log_event("Invalid input parameters");
        return NULL;
    }

    // Calculate the size of the memory block to allocate based on the load factor
    int total_size = num_records * sizeof(struct record);
    if (load_factor > 1.0f || load_factor < 0.0f) {
        log_event("Invalid load factor");
        return NULL;
    }
    total_size += ceil(total_size * load_factor);

    // Allocate memory for the data structures using the custom allocator
    struct record* records = allocate_memory(total_size);
    if (!records) {
        log_event("Memory allocation failed");
        return NULL;
    }

    // Initialize the long offset values
    for (int i = 0; i < num_records; ++i) {
        records[i].offset = rand() % key_range + MIN_KEY_VALUE;
    }

    // Initialize the int keys according to the specified pattern or randomly
    if (pattern) {
        for (int i = 0; i < num_records; ++i) {
            records[i].key = pattern[i % strlen(pattern)];
        }
    } else {
        for (int i = 0; i < num_records; ++i) {
            records[i].key = rand() % key_range + MIN_KEY_VALUE;
        }
    }

    // Initialize the record array
    for (int i = 0; i < num_records; ++i) {
        records[i].value = 0;
    }

    return records;
}
