struct DisjointPairCounts {
    map<int, int> counts;
};

DisjointPairCounts computeDisjointPairs(vector<NICStatistics>& nicStats) {
    DisjointPairCounts result;
    for (auto& stat : nicStats) {
        // Compute the checksum of the IP packet
        uint16_t checksum = calculateChecksum(stat.ipPacket);
        // Check if the checksum is valid
        if (checksum != 0xFFFF) {
            // Increment the count for this disjoint pair
            result.counts[checksum]++;
        }
    }
    return result;
}

