    for (auto& stat : nicStats) {
        initMacHeader(&stat.macHeader, PAYLOAD_SIZE);
        initIpPacket(&stat.ipPacket, PAYLOAD_SIZE);
    }

    // Compute the disjoint pairs of IP packets
    DisjointPairCounts counts = computeDisjointPairs(nicStats);

    // Print the disjoint pair counts and execution times
