        DisjointPairCounts counts = computeDisjointPairs(nicStats);

        // Print the disjoint pair counts and execution times
        for (int i = 0; i < PAYLOAD_SIZE; i++) {
            NICStatistics stat = nicStats.get(i);
            int checksum = calculateChecksum(stat.ipPacket);
            if (checksum != 0xFFFF) {
                System.out.println("Checksum: " + checksum + ", Count: " + counts.counts[checksum]);
            }
        }
    }

    public static void initMacHeader(MAC_HEADER header, int payloadSize) {
        // Initialize the MAC header with random data
        Random random = new Random();
        for (int i = 0; i < header.size(); i++) {
            header.data[i] = (byte)random.nextInt(256);
        }
    }

    public static void initIpPacket(IP_PACKET packet, int payloadSize) {
        // Initialize the IP packet with random data
        Random random = new Random();
        for (int i = 0; i < packet.size(); i++) {
            packet.data[i] = (byte)random.nextInt(256);
        }
    }

    public static int calculateChecksum(IP_PACKET packet) {
        // Calculate the checksum of the IP packet using a Union-Find data structure
        UnionFind unionFind = new UnionFind();
        for (int i = 0; i < packet.size(); i++) {
            unionFind.union(packet.data[i], packet.data[i]);
        }
        return unionFind.find(packet.data[0]) == packet.data[1] ? 0xFFFF : 0xFFFE;
    }

    public static DisjointPairCounts computeDisjointPairs(Vector<NICStatistics> nicStats) {
        // Compute the disjoint pairs of IP packets using a Union-Find data structure
        DisjointPairCounts counts = new DisjointPairCounts();
        for (int i = 0; i < PAYLOAD_SIZE; i++) {
            NICStatistics stat = nicStats.get(i);
            int checksum = calculateChecksum(stat.ipPacket);
            if (checksum != 0xFFFF) {
                counts.counts[checksum]++;
            }
        }
        return counts;
    }
}
