#define MAX_SHAPES 1000000

typedef struct point {
    float x;
    float y;
} Point;

typedef enum shape_type {
    SHAPE_TYPE_RECTANGLE,
    SHAPE_TYPE_CIRCLE,
    SHAPE_TYPE_TRIANGLE,
    SHAPE_TYPE_MAX
} ShapeType;

typedef struct geometric_shape {
    ShapeType type;
