} GeometricShape;

// Function to initialize the geometric shapes array and populate it with random data
void init_geometric_shapes(GeometricShape *shapes, int num_shapes) {
    // Seed the random number generator with the current time
    srand((unsigned int)time(NULL));

    // Allocate memory for the arrays of doubles, strings, and points
    double *doubles = malloc(sizeof(double) * MAX_SHAPES);
    char **strings = malloc(sizeof(char *) * MAX_SHAPES);
    Point *points = malloc(sizeof(Point) * MAX_SHAPES);

    // Initialize the arrays with random data
    for (int i = 0; i < num_shapes; i++) {
        doubles[i] = rand() / (double)RAND_MAX;
        strings[i] = malloc(10 * sizeof(char));
        for (int j = 0; j < 10; j++) {
            strings[i][j] = 'a' + (rand() % 26);
        }
        points[i].x = rand() / (double)RAND_MAX;
        points[i].y = rand() / (double)RAND_MAX;
    }

    // Initialize the hash table for constant-time lookups
    HashTable *hash_table = create_hash_table();

    // Populate the hash table with the shapes and their corresponding data
    for (int i = 0; i < num_shapes; i++) {
        ShapeType type = rand() % SHAPE_TYPE_MAX;
        void *data = malloc(sizeof(type) * MAX_SHAPES);

        // Generate random metadata within the specified range and seeded with the current time
        for (int j = 0; j < 10; j++) {
            shapes[i].metadata[j] = rand() % 100 - 50;
        }

        // Insert the shape into the hash table
        insert_hash_table(hash_table, shapes[i].id, &shapes[i]);
    }

    // Free the memory allocated for the arrays of doubles, strings, and points
    free(doubles);
    free(strings);
    free(points);
}

// Function to insert a shape into the hash table
void insert_hash_table(HashTable *hash_table, int id, void *data) {
    // Check if the hash table is full
    if (hash_table->count >= MAX_SHAPES) {
        // If the hash table is full, double its size and rehash all the elements
        resize_hash_table(hash_table, 2 * hash_table->size);
    }

    // Compute the hash value for the shape's ID
    int hash_value = id % hash_table->size;

    // If there is already a shape with the same ID in the table, update its data
    if (hash_table->buckets[hash_value] != NULL && hash_table->buckets[hash_value]->id == id) {
        hash_table->buckets[hash_value]->data = data;
    } else {
        // Otherwise, insert the shape into a new bucket
        hash_table->count++;
        ShapeBucket *bucket = malloc(sizeof(ShapeBucket));
        bucket->id = id;
        bucket->data = data;
        hash_table->buckets[hash_value] = bucket;
    }
}

// Function to delete a shape from the hash table
void delete_hash_table(HashTable *hash_table, int id) {
    // Compute the hash value for the shape's ID
    int hash_value = id % hash_table->size;

    // If there is no bucket with the given ID in the table, return
    if (hash_table->buckets[hash_value] == NULL || hash_table->buckets[hash_value]->id != id) {
        return;
    }

    // Remove the shape from the hash table
    ShapeBucket *bucket = hash_table->buckets[hash_value];
    hash_table->count--;
    free(bucket);
}

// Function to modify a shape in the hash table
void modify_hash_table(HashTable *hash_table, int id, void *data) {
    // Compute the hash value for the shape's ID
    int hash_value = id % hash_table->size;

    // If there is no bucket with the given ID in the table, return
    if (hash_table->buckets[hash_value] == NULL || hash_table->buckets[hash_value]->id != id) {
        return;
    }

    // Update the shape's data in the hash table
    ShapeBucket *bucket = hash_table->buckets[hash_value];
    bucket->data = data;
}

// Function to query a shape from the hash table
void *query_hash_table(HashTable *hash_table, int id) {
    // Compute the hash value for the shape's ID
    int hash_value = id % hash_table->size;

    // If there is no bucket with the given ID in the table, return NULL
    if (hash_table->buckets[hash_value] == NULL || hash_table->buckets[hash_value]->id != id) {
        return NULL;
    }

    // Return the shape's data from the hash table
    ShapeBucket *bucket = hash_table->buckets[hash_value];
    return bucket->data;
}

// Function to resize the hash table and rehash all the elements
void resize_hash_table(HashTable *hash_table, int new_size) {
    // Create a new hash table with the given size
    HashTable *new_hash_table = create_hash_table(new_size);

    // Iterate over all the buckets in the current hash table and reinsert them into the new one
    for (int i = 0; i < hash_table->size; i++) {
        ShapeBucket *bucket = hash_table->buckets[i];
        if (bucket != NULL) {
            insert_hash_table(new_hash_table, bucket->id, bucket->data);
        }
    }

    // Free the memory allocated for the current hash table
    free(hash_table);
}

// Function to create a new hash table with the given size
HashTable *create_hash_table(int size) {
    HashTable *hash_table = malloc(sizeof(HashTable));
    hash_table->size = size;
    hash_table->count = 0;
    hash_table->buckets = malloc(size * sizeof(ShapeBucket*));
    return hash_table;
}
```

This implementation uses a hash table to store the shapes and their data. The `HashTable` struct contains an array of `ShapeBucket` pointers, where each bucket represents a single slot in the hash table. The `insert_hash_table`, `delete_hash_table`, `modify_hash_table`, and `query_hash_table` functions handle the insertion, deletion, modification, and querying of shapes in the hash table, respectively.

The `resize_hash_table` function is used to resize the hash table when it becomes full and needs to be expanded. It creates a new hash table with twice the size of the previous one and rehashes all the elements from the old hash table into the new one.

Note that this implementation does not provide any synchronization mechanism for multiple threads accessing the hash table simultaneously, so it is up to the user to ensure that only one thread can access the hash table at a time."]

