// Define the structure for holding the NFAPI_CRC_INDICATION_PDU_T data
typedef struct {
  uint16_t validRxUeInformationTag;
  uint32_t rnti;
  uint8_t crcIndicationRel8Tag;
  bool crcflag;
} nfapi_crc_indication_pdu_t;

// Define the list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
  size_t size;
  size_t capacity;
  nfapi_crc_indication_pdu_t* data;
} nfapi_crc_indication_list_t;

// Define the function to manage the list of NFAPI_CRC_INDICATION_PDU_T structures and execute the specified command in the background
int process_nfalib_and_execute_command(nfapi_crc_indication_list_t* list, const char* command) {
  // Check if the input parameters are valid
  if (list == NULL || command == NULL) {
    return 0;
  }

  // Declare variables for managing the memory and resources
  size_t i;
  nfapi_crc_indication_pdu_t* current_pdu = NULL;
  bool success = false;
  int ret;
  pid_t child_pid = 0;

  // Allocate memory for the command execution
  char* exec_command = (char*)malloc(strlen(command) + 1);
  if (exec_command == NULL) {
    return 0;
  }
  strcpy(exec_command, command);

  // Create a new thread for executing the command in the background
  pthread_t child_thread;
  ret = pthread_create(&child_thread, NULL, execute_command, exec_command);
  if (ret != 0) {
    free(exec_command);
    return 0;
  }

  // Iterate over the list of NFAPI_CRC_INDICATION_PDU_T structures and update their CRCFLAG fields
  for (i = 0; i < list->size; ++i) {
    current_pdu = &list->data[i];
    current_pdu->crcflag = true;
  }

  // Wait for the child process to complete
  ret = pthread_join(child_thread, NULL);
  if (ret != 0) {
    free(exec_command);
    return 0;
  }

  // Check if the command execution was successful
  if (WIFEXITED(child_pid)) {
    success = true;
  } else {
    free(exec_command);
    return 0;
  }

  // Free the memory allocated for the command execution
  free(exec_command);

  return success ? 1 : 0;
}

// Define the function to execute a specified command in the background
void* execute_command(void* arg) {
  char* exec_command = (char*)arg;
  int ret = system(exec_command);
  free(exec_command);
  return NULL;
}
