```c
#include <iostream>
#include <boost/array.hpp>
#include <boost/shared_ptr.hpp>
#include <boost/thread.hpp>
#include <boost/chrono.hpp>

using namespace std;
using boost::shared_ptr;
using boost::lock_guard;
using boost::mutex;

struct NetworkInterfaceControl {
    // MAC header structure
    struct MacHeader {
        uint8_t destination[6];
        uint8_t source[6];
        uint16_t type;
    };

    // IP packet structure
    struct IpPacket {
        uint32_t version;
        uint32_t headerLength;
        uint32_t totalLength;
        uint8_t typeOfService;
        uint8_t identification[2];
        uint16_t flagsAndFragmentOffset;
        uint8_t ttl;
        uint8_t protocol;
        uint16_t checksum;
    };

    // Payload structure
    struct Payload {
        uint32_t size;
        uint8_t data[];
    };
};

// Network interface statistics structure
struct InterfaceStatistics {
    uint64_t packetsReceived;
    uint64_t bytesReceived;
    uint64_t packetsSent;
    uint64_t bytesSent;
    uint64_t errorsReceived;
};

// Network interface structure
struct NetworkInterface {
    // MAC address
    std::string macAddress;

    // IP address
    std::string ipAddress;

    // Interface name
    std::string interfaceName;

    // Statistics
    shared_ptr<InterfaceStatistics> statistics;
};

// Network interface control structure
struct NetworkInterfaceControl {
    // MAC header
    NetworkInterfaceControl::MacHeader macHeader;

    // IP packet
    NetworkInterfaceControl::IpPacket ipPacket;

    // Payload
    shared_ptr<Payload> payload;
};

// Array of network interfaces
boost::array<NetworkInterface, MAX_NUM_INTERFACES> networkInterfaces;

// Mutex to protect access to the network interface array
mutex netIntMutex;

// Function to get the current time in milliseconds
long getCurrentTimeMillis() {
    return boost::chrono::duration_cast<boost::chrono::milliseconds>(boost::chrono::system_clock::now().time_since_epoch()).count();
}

// Function to validate IP checksums
bool validateChecksum(const NetworkInterfaceControl& nic) {
    // Calculate the checksum of the packet data and compare it to the one in the header
    uint16_t calculatedChecksum = calculateChecksum(nic.payload->data, nic.payload->size);
    return calculatedChecksum == nic.ipPacket.checksum;
}

// Function to calculate IP checksum
uint16_t calculateChecksum(const void* data, size_t len) {
    uint16_t sum = 0;
    for (size_t i = 0; i < len; i += 2) {
        uint16_t word = *((uint16_t*)data + i / 2);
        sum += word;
    }
    return sum;
}

// Function to insert a new network interface into the array
void insertNetworkInterface(const std::string& macAddress, const std::string& ipAddress, const std::string& interfaceName) {
    lock_guard<mutex> lock(netIntMutex);
    NetworkInterfaceControl nic;
    // Set up the MAC header
    nic.macHeader.destination[0] = 0xFF;
    nic.macHeader.destination[1] = 0xFF;
    nic.macHeader.destination[2] = 0xFF;
    nic.macHeader.destination[3] = 0xFF;
    nic.macHeader.destination[4] = 0xFF;
    nic.macHeader.destination[5] = 0xFF;
    nic.macHeader.source[0] = 0xAA;
    nic.macHeader.source[1] = 0xAA;
    nic.macHeader.source[2] = 0xAA;
    nic.macHeader.source[3] = 0xAA;
    nic.macHeader.source[4] = 0xAA;
    nic.macHeader.source[5] = 0xAA;
    nic.macHeader.type = 0x800;

    // Set up the IP packet
    nic.ipPacket.version = 4;
    nic.ipPacket.headerLength = 20;
    nic.ipPacket.totalLength = 20 + sizeof(uint32_t);
    nic.ipPacket.typeOfService = 0;
    nic.ipPacket.identification[0] = 0x45;
    nic.ipPacket.identification[1] = 0x67;
    nic.ipPacket.flagsAndFragmentOffset = 0x0000;
    nic.ipPacket.ttl = 255;
    nic.ipPacket.protocol = 4;
    nic.ipPacket.checksum = calculateChecksum((void*)&nic.ipPacket, sizeof(nic.ipPacket));

    // Set up the payload
    nic.payload->size = sizeof(uint32_t);
    nic.payload->data[0] = 0xDE;
    nic.payload->data[1] = 0xAD;
    nic.payload->data[2] = 0xBE;
    nic.payload->data[3] = 0xEF;

    // Insert the network interface into the array
    networkInterfaces[macAddress] = NetworkInterface{macAddress, ipAddress, interfaceName, shared_ptr<InterfaceStatistics>(new InterfaceStatistics)};
}

// Function to remove a network interface from the array
void removeNetworkInterface(const std::string& macAddress) {
    lock_guard<mutex> lock(netIntMutex);
    networkInterfaces[macAddress] = NetworkInterface{};
}

// Function to update statistics for a given network interface
void updateStatistics(const std::string& macAddress, uint64_t packetsReceived, uint64_t bytesReceived, uint64_t packetsSent, uint64_t bytesSent) {
    lock_guard<mutex> lock(netIntMutex);
    networkInterfaces[macAddress].statistics->packetsReceived += packetsReceived;
    networkInterfaces[macAddress].statistics->bytesReceived += bytesReceived;
    networkInterfaces[macAddress].statistics->packetsSent += packetsSent;
    networkInterfaces[macAddress].statistics->bytesSent += bytesSent;
}

// Main function for the Sandesh client
int main() {
    // Initialize the network interface array
    networkInterfaces.fill(NetworkInterface{});

    // Set up the socket for receiving data
    int sock = socket(AF_PACKET, SOCK_DGRAM, htons(ETH_P_ALL));
    if (sock < 0) {
        perror("socket");
        exit(1);
    }

    // Bind the socket to the network interface
    struct sockaddr_ll sll = {};
    sll.sll_family = AF_PACKET;
    sll.sll_protocol = htons(ETH_P_ALL);
    sll.sll_ifindex = if_nametoindex("eth0");
    if (bind(sock, (struct sockaddr*)&sll, sizeof(sll)) < 0) {
        perror("bind");
        exit(1);
    }

    // Set the socket options to receive data from the network interface
    struct packet_mreq mr = {};
    mr.mr_ifindex = sll.sll_ifindex;
    mr.mr_type = PACKET_MR_PROMISC;
    if (setsockopt(sock, SOL_PACKET, PACKET_ADD_MEMBERSHIP, &mr, sizeof(mr)) < 0) {
        perror("setsockopt");
        exit(1);
    }

    // Start receiving data from the socket
    struct sockaddr_ll sll2 = {};
    char buffer[4096];
    while (true) {
        int len = recvfrom(sock, buffer, sizeof(buffer), 0, (struct sockaddr*)&sll2, &sll2.sll_halen);
        if (len < 0) {
            perror("recvfrom");
            exit(1);
        }

        // Parse the received data and update statistics for the corresponding network interface
        uint8_t* payload = buffer + sizeof(struct ethhdr);
        size_t payloadSize = len - sizeof(struct ethhdr);
        if (payloadSize >= sizeof(uint32_t) && validateChecksum((void*)payload, payloadSize)) {
            // Parse the received data and update statistics for the corresponding network interface
            uint64_t packetsReceived = 1;
            uint64_t bytesReceived = payloadSize + sizeof(struct ethhdr);
            updateStatistics(sll2.sll_addr, packetsReceived, bytesReceived, 0, 0);
        } else {
            // Ignore the received data if it is invalid
        }
    }

    return 0;
}
