#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure to hold the records
typedef struct record {
    char *id; // string identifier for each record
    int key; // integer key for each record
    long offset; // long offset value for each record
} record_t;

// Define a hash table to store the records
static hashmap_t *records = NULL;

// Define a mutex to synchronize access to the records
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Initialize the function
void init_records() {
    // Create a new hash table for storing the records
    records = hashmap_new();
}

// Add a new record to the collection
void add_record(const char *id, int key, long offset) {
    // Acquire the lock to ensure thread safety during serialization and deserialization operations
    pthread_mutex_lock(&lock);

    // Check if the record already exists in the hash table
    record_t *record = hashmap_get(records, id);
    if (record != NULL) {
        // Update the existing record with the new information
        record->key = key;
        record->offset = offset;
    } else {
        // Create a new record and add it to the hash table
        record_t *new_record = malloc(sizeof(record_t));
        if (new_record == NULL) {
            fprintf(stderr, "Error: failed to allocate memory for new record\n");
            return;
        }
        strncpy(new_record->id, id, strlen(id));
        new_record->key = key;
        new_record->offset = offset;
        hashmap_set(records, id, new_record);
    }

    // Release the lock
    pthread_mutex_unlock(&lock);
}

// Get a record from the collection by its unique identifier
record_t *get_record(const char *id) {
    // Acquire the lock to ensure thread safety during serialization and deserialization operations
    pthread_mutex_lock(&lock);

    // Check if the record exists in the hash table
    record_t *record = hashmap_get(records, id);
    if (record == NULL) {
        // Release the lock and return null if the record does not exist
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Release the lock and return the record
    pthread_mutex_unlock(&lock);
    return record;
}

// Serialize the collection to a binary file format
void serialize_records(const char *filename) {
    // Acquire the lock to ensure thread safety during serialization operations
    pthread_mutex_lock(&lock);

    // Open the output file for writing
    FILE *outfile = fopen(filename, "wb");
    if (outfile == NULL) {
        fprintf(stderr, "Error: failed to open output file\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    // Write the number of records in the hash table to the output file
    size_t num_records = hashmap_size(records);
    fwrite(&num_records, sizeof(size_t), 1, outfile);

    // Iterate over each record in the hash table and write its data to the output file
    hashmap_iter_t *iter = hashmap_iter_new(records);
    while (hashmap_iter_has_next(iter)) {
        const char *id = hashmap_iter_get_key(iter);
        record_t *record = hashmap_iter_get_value(iter);
        fwrite(&record->key, sizeof(int), 1, outfile);
        fwrite(&record->offset, sizeof(long), 1, outfile);
    }

    // Close the output file and release the lock
    pthread_mutex_unlock(&lock);
}

// Deserialize a collection from a binary file format
void deserialize_records(const char *filename) {
    // Acquire the lock to ensure thread safety during deserialization operations
    pthread_mutex_lock(&lock);

    // Open the input file for reading
    FILE *infile = fopen(filename, "rb");
    if (infile == NULL) {
        fprintf(stderr, "Error: failed to open input file\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    // Read the number of records from the input file
    size_t num_records = 0;
    fread(&num_records, sizeof(size_t), 1, infile);

    // Iterate over each record in the input file and add it to the hash table
    for (int i = 0; i < num_records; i++) {
        int key = 0;
        long offset = 0;
        fread(&key, sizeof(int), 1, infile);
        fread(&offset, sizeof(long), 1, infile);
        add_record(key, offset);
    }

    // Close the input file and release the lock
    pthread_mutex_unlock(&lock);
}

// Free all resources associated with the collection
void free_records() {
    // Acquire the lock to ensure thread safety during serialization and deserialization operations
    pthread_mutex_lock(&lock);

    // Iterate over each record in the hash table and free its resources
    hashmap_iter_t *iter = hashmap_iter_new(records);
    while (hashmap_iter_has_next(iter)) {
        const char *id = hashmap_iter_get_key(iter);
        record_t *record = hashmap_iter_get_value(iter);
        free(record->id);
        free(record);
    }

    // Free the hash table and release the lock
    pthread_mutex_unlock(&lock);
}
