    char ip_packet[20]; // IP packet with random payload size and checksum
} NicStatistics;

// Define an array to store the NIC statistics data
NicStatistics *nic_statistics = NULL;
size_t nic_statistics_size = 0;

// Define a function to initialize the dynamic array of NIC statistics structures
void init_nic_statistics(int size) {
    // Allocate memory for the dynamic array
    nic_statistics = (NicStatistics *)malloc(sizeof(NicStatistics) * size);
    if (!nic_statistics) {
        printf("Memory allocation failed. Exiting...\n");
        exit(1);
    }
    // Set the initial size of the dynamic array
    nic_statistics_size = size;
}

// Define a function to add a new NIC statistics structure to the dynamic array
void add_nic_statistics(NicStatistics *new_stat) {
    if (nic_statistics_size == 0) {
        init_nic_statistics(1);
    } else if (nic_statistics_size >= SIZE_MAX / sizeof(NicStatistics)) {
        printf("Size limit reached. Exiting...\n");
        exit(1);
    } else {
        nic_statistics = (NicStatistics *)realloc(nic_statistics, (nic_statistics_size + 1) * sizeof(NicStatistics));
        if (!nic_statistics) {
            printf("Memory allocation failed. Exiting...\n");
            exit(1);
        }
        nic_statistics_size++;
    }
    // Copy the new NIC statistics structure to the end of the array
    memcpy(&nic_statistics[nic_statistics_size - 1], new_stat, sizeof(NicStatistics));
}

// Define a function to validate the checksum of an IP packet
bool validate_checksum(const char *ip_packet) {
    // Calculate the checksum of the IP packet
    uint32_t checksum = 0;
    for (int i = 0; i < sizeof(NicStatistics); i += 4) {
        checksum += *(uint32_t *)(&ip_packet[i]);
    }
    // Verify the checksum against the expected value
    return checksum == calculate_checksum(ip_packet);
}

// Define a function to calculate the checksum of an IP packet
uint32_t calculate_checksum(const char *ip_packet) {
    // Calculate the checksum of the IP packet
    uint32_t checksum = 0;
    for (int i = 0; i < sizeof(NicStatistics); i += 4) {
        checksum += *(uint32_t *)(&ip_packet[i]);
    }
    return checksum;
}

// Define a function to free the dynamic array of NIC statistics structures
void free_nic_statistics() {
    // Free the memory allocated for the dynamic array
    if (nic_statistics) {
        free(nic_statistics);
        nic_statistics = NULL;
        nic_statistics_size = 0;
    }
}
