public class DisjointPairs {
    private static final int MAX_ARRAY_SIZE = 1000; // maximum size of the dynamic array

    public static void main(String[] args) throws Exception {
        // Initialize the C function to handle NIC statistics data
        initNicStatistics();

        // Get the input from the user regarding the number of disjoint pairs to be checked
        int numDisjointPairs = getUserInput();

        // Create an ArrayList to store the disjoint pairs
        List<DisjointPair> disjointPairs = new ArrayList<>();

