            // Get the next NIC statistics structure from the dynamic array
            NicStatistics nic_stat = getNextNicStatistics();

            // Calculate the checksum of the IP packet
            int checksum = calculateChecksum(nic_stat);

            // Create a new disjoint pair and add it to the ArrayList
            DisjointPair pair = new DisjointPair(checksum, nic_stat.ip_packet, i);
            disjointPairs.add(pair);
        }

        // Print the number of milliseconds taken for each disjoint pair check
        printCheckingTime(disjointPairs);
    }

    private static void initNicStatistics() {
        // Initialize the dynamic array of NIC statistics structures with a size of 1000 elements
        init_nic_statistics(1000);
    }

    private static int getUserInput() throws Exception {
        Scanner scanner = new Scanner(System.in);
        System.out.println("Enter the number of disjoint pairs to check: ");
        return scanner.nextInt();
    }

    private static NicStatistics getNextNicStatistics() {
        // Get the next NIC statistics structure from the dynamic array
        NicStatistics nic_stat = (NicStatistics *)malloc(sizeof(NicStatistics));
        if (!nic_stat) {
            printf("Memory allocation failed. Exiting...\n");
            exit(1);
        }
        // Copy the next NIC statistics structure to the output array
        memcpy(nic_stat, &nic_statistics[0], sizeof(NicStatistics));
        return nic_stat;
    }

    private static int calculateChecksum(NicStatistics nic_stat) {
        // Calculate the checksum of the IP packet
        uint32_t checksum = 0;
        for (int i = 0; i < sizeof(NicStatistics); i += 4) {
            checksum += *(uint32_t *)(&nic_stat.ip_packet[i]);
        }
        return checksum;
    }

    private static void printCheckingTime(List<DisjointPair> disjointPairs) {
        // Print the number of milliseconds taken for each disjoint pair check
        long startTime = System.currentTimeMillis();
        for (int i = 0; i < disjointPairs.size(); i++) {
            DisjointPair pair = disjointPairs.get(i);
            if (pair.checksum != calculateChecksum(pair.nic_stat)) {
                // The checksums do not match, so the IP packets are not disjoint
                System.out.println("Not disjoint: " + pair.nic_stat.ip_packet);
            } else {
                // The checksums match, so the IP packets are disjoint
                System.out.println("Disjoint: " + pair.nic_stat.ip_packet);
            }
        }
        long endTime = System.currentTimeMillis();
        System.out.println("Total time taken: " + (endTime - startTime) + " milliseconds");
    }
}
