// Structure to represent a record in the array
typedef struct {
    long offset;
    int key;
} record;

// Global variables for memory management
static size_t max_size = 0; // Maximum allowed size of the array
static size_t curr_size = 0; // Current size of the array
static record *records = NULL; // Pointer to the array of records
static bool mem_allocated = false; // Flag indicating if memory has been allocated

// Function to allocate memory for the array and initialize it with default values
void init_array(const char* config_file) {
    // Read configuration file to determine maximum allowed size
    FILE *config = fopen(config_file, "r");
    if (config == NULL) {
        syslog(LOG_ERR, "Error opening configuration file: %s", strerror(errno));
        return;
    }
    int max_size_read = fscanf(config, "%zu", &max_size);
    if (max_size_read != 1) {
        syslog(LOG_ERR, "Error reading maximum size from configuration file");
        fclose(config);
        return;
    }
    fclose(config);

    // Allocate memory for the array and initialize it with default values
    records = (record*) malloc(max_size * sizeof(record));
    if (records == NULL) {
        syslog(LOG_ERR, "Error allocating memory for array: %s", strerror(errno));
        return;
    }
    memset(records, 0, max_size * sizeof(record));

    // Initialize the current size of the array
    curr_size = 0;

    // Set flag indicating that memory has been allocated
    mem_allocated = true;
}

// Function to add a new record to the array
void add_record(long offset, int key) {
    if (!mem_allocated) {
        syslog(LOG_ERR, "Memory has not been allocated yet");
        return;
    }

    // Check if there is enough space in the array for a new record
    if (curr_size >= max_size) {
        syslog(LOG_WARNING, "Array is full, cannot add new record");
        return;
    }

    // Add the new record to the array and increment the current size
    records[curr_size].offset = offset;
    records[curr_size].key = key;
    curr_size++;
}

// Function to get a record from the array by its index
record* get_record(int index) {
    if (!mem_allocated) {
        syslog(LOG_ERR, "Memory has not been allocated yet");
        return NULL;
    }

    // Check if the index is valid
    if (index < 0 || index >= curr_size) {
        syslog(LOG_WARNING, "Invalid index: %d", index);
        return NULL;
    }

    // Return the record at the specified index
    return &records[index];
}

// Function to free memory allocated for the array
void free_array() {
    if (!mem_allocated) {
        syslog(LOG_ERR, "Memory has not been allocated yet");
        return;
    }

    // Free memory allocated for the array and set flag indicating that it is no longer allocated
    free(records);
    records = NULL;
    mem_allocated = false;
}

// Function to scale the size of the array based on runtime memory pressure signals from an external monitoring service
void scale_array(int scaling_factor) {
    if (!mem_allocated) {
        syslog(LOG_ERR, "Memory has not been allocated yet");
        return;
    }

    // Check if the scaling factor is valid
    if (scaling_factor <= 0) {
        syslog(LOG_WARNING, "Invalid scaling factor: %d", scaling_factor);
        return;
    }

    // Calculate the new size of the array based on the current size and the scaling factor
    size_t new_size = curr_size * scaling_factor;

    // Check if the new size exceeds the maximum allowed size
    if (new_size > max_size) {
        syslog(LOG_WARNING, "New size of array would exceed maximum allowed size");
        return;
    }

    // Allocate memory for the new array and initialize it with default values
    record* new_records = (record*) malloc(new_size * sizeof(record));
    if (new_records == NULL) {
        syslog(LOG_ERR, "Error allocating memory for new array: %s", strerror(errno));
        return;
    }
    memset(new_records, 0, new_size * sizeof(record));

    // Copy the records from the old array to the new one
    for (int i = 0; i < curr_size; i++) {
        new_records[i].offset = records[i].offset;
        new_records[i].key = records[i].key;
    }

    // Free memory allocated for the old array and set flag indicating that it is no longer allocated
    free(records);
    records = NULL;
    mem_allocated = false;

    // Update the current size of the array and the maximum allowed size
    curr_size = new_size;
    max_size = new_size;

    // Set flag indicating that memory has been allocated
    mem_allocated = true;
}
```
