    if (statistics == NULL) {
        // Failed to allocate memory for the array
        return -2;
    }

    size_t total_payload_memory = 0;
    int num_entries_added = 0;

    while (num_entries_added < initial_size && total_payload_memory <= total_max_payload_memory) {
        // Generate a random payload size within the specified range
        size_t payload_size = min_payload_size + (rand() % (max_payload_size - min_payload_size));

        // Allocate memory for the payload and calculate its checksum
