        // Insert the entry into the array and update the total payload memory usage
        statistics[num_entries_added].ipaddresspacket.checksum = checksum;
        total_payload_memory += payload_size;

        num_entries_added++;
    }

    *num_entries = num_entries_added;

    // Resize the array if necessary
    if (num_entries_added < initial_size) {
        NetworkInterfaceStatistics* new_statistics = realloc(statistics, sizeof(NetworkInterfaceStatistics) * num_entries_added);
        if (new_statistics == NULL) {
            // Failed to resize the array
            return -3;
        }
