```java
import java.util.List;
import java.util.ArrayList;
import java.util.Map;
import java.util.HashMap;
import java.util.concurrent.ConcurrentHashMap;

public class SessionManager {
    private List<Session> sessions = new ArrayList<>();
    private Map<Long, Session> sessionMap = new HashMap<>();
    private ConcurrentHashMap<String, String> profileMap = new ConcurrentHashMap<>();

    public void init(int numSessions) {
        for (int i = 0; i < numSessions; i++) {
            sessions.add(new Session());
        }
        sessionMap = new HashMap<Long, Session>();
        profileMap = new ConcurrentHashMap<String, String>();
    }

    public void processSessionEvents(List<SessionEvent> events) {
        for (SessionEvent event : events) {
            switch (event.getType()) {
                case LOGIN:
                    onLogin(event);
                    break;
                case LOGOUT:
                    onLogout(event);
                    break;
                case MESSAGE_SENT:
                    onMessageSent(event);
                    break;
            }
        }
    }

    private void onLogin(SessionEvent event) {
        Session session = new Session();
        session.setId(event.getSessionId());
        session.setUserCredentials(event.getUsername(), event.getPassword());
        sessions.add(session);
        sessionMap.put(session.getId(), session);
    }

    private void onLogout(SessionEvent event) {
        Session session = sessionMap.get(event.getSessionId());
        if (session != null) {
            sessions.remove(session);
            sessionMap.remove(event.getSessionId());
        }
    }

    private void onMessageSent(SessionEvent event) {
        Session session = sessionMap.get(event.getSessionId());
        if (session != null) {
            session.incrementMessageCount();
            profileMap.put(event.getUsername(), event.getMessage());
        }
    }

    public List<Session> getSessions() {
        return sessions;
    }

    public Map<Long, Session> getSessionMap() {
        return sessionMap;
    }

    public Map<String, String> getProfileMap() {
        return profileMap;
    }
}
