#include <semaphore.h>

// Define a struct to represent a resource record
typedef struct {
    long offset;
    int key;
    int resource_id;
} ResourceRecord;

// Define a container for the resource records
typedef struct {
    int capacity;
    int count;
    ResourceRecord* records;
} ResourceContainer;

// Initialize and manage a semaphore with a specified initial value
void initSemaphore(sem_t* sem, int initialValue) {
    if (sem_init(sem, 0, initialValue) < 0) {
        fprintf(stderr, "Error: failed to initialize semaphore\n");
        exit(1);
    }
}

// Destroy a semaphore
void destroySemaphore(sem_t* sem) {
    if (sem_destroy(sem) < 0) {
        fprintf(stderr, "Error: failed to destroy semaphore\n");
        exit(1);
    }
}

// Allocate memory for the resource container and initialize it
void allocateResourceContainer(ResourceContainer* container, int capacity) {
    // Check if the requested capacity exceeds the maximum size threshold
    if (capacity > MAX_SIZE_THRESHOLD) {
        fprintf(stderr, "Error: requested capacity exceeds maximum size threshold\n");
        exit(1);
    }

    // Allocate memory for the resource records
    container->records = malloc(capacity * sizeof(ResourceRecord));
    if (container->records == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for resource records\n");
        exit(1);
    }

    // Initialize the semaphore with a specified initial value
    initSemaphore(&container->semaphore, INITIAL_SEMAPHORE_VALUE);
}

// Deallocate the memory for the resource container and destroy the semaphore
void deallocateResourceContainer(ResourceContainer* container) {
    // Destroy the semaphore
    destroySemaphore(&container->semaphore);

    // Deallocate the memory for the resource records
    free(container->records);
}

// Dynamically resize the container when the current capacity is exceeded
void resizeResourceContainer(ResourceContainer* container) {
    // Double the capacity of the container
    container->capacity *= 2;

    // Reallocate memory for the resource records
    ResourceRecord* newRecords = realloc(container->records, container->capacity * sizeof(ResourceRecord));
    if (newRecords == NULL) {
        fprintf(stderr, "Error: failed to reallocate memory for resource records\n");
        exit(1);
    }

    // Update the pointer to the new records
    container->records = newRecords;
}

// Add a new resource record to the container
void addResourceRecord(ResourceContainer* container, long offset, int key, int resource_id) {
    // Check if the requested capacity exceeds the maximum size threshold
    if (container->count == container->capacity) {
        resizeResourceContainer(container);
    }

    // Add a new record to the container
    container->records[container->count].offset = offset;
    container->records[container->count].key = key;
    container->records[container->count].resource_id = resource_id;
    container->count++;
}

// Remove a resource record from the container
void removeResourceRecord(ResourceContainer* container, int index) {
    // Check if the requested index is out of bounds
    if (index >= container->count || index < 0) {
        fprintf(stderr, "Error: requested index is out of bounds\n");
        exit(1);
    }

    // Remove the record from the container
    for (int i = index; i < container->count - 1; i++) {
        container->records[i] = container->records[i + 1];
    }
    container->count--;
}

// Retrieve a resource record from the container by its key
ResourceRecord* getResourceRecord(ResourceContainer* container, int key) {
    // Check if the requested key is present in the container
    for (int i = 0; i < container->count; i++) {
        if (container->records[i].key == key) {
            return &container->records[i];
        }
    }
    return NULL;
}

// Update a resource record in the container by its key
void updateResourceRecord(ResourceContainer* container, int key, long offset, int resource_id) {
    // Check if the requested key is present in the container
    for (int i = 0; i < container->count; i++) {
        if (container->records[i].key == key) {
            container->records[i].offset = offset;
            container->records[i].resource_id = resource_id;
            return;
        }
    }
}

// Delete a resource record from the container by its key
void deleteResourceRecord(ResourceContainer* container, int key) {
    // Check if the requested key is present in the container
    for (int i = 0; i < container->count; i++) {
        if (container->records[i].key == key) {
            removeResourceRecord(container, i);
            return;
        }
    }
}
