// Define linked list node structure
typedef struct Node {
    Record record;
    struct Node* next;
} Node;

// Function to dynamically manage collection of records
void dynamic_record_management(int num_records, int value_range, bool logging) {
    // Initialize linked list head and tail pointers
    Node* head = NULL;
    Node* tail = NULL;

    // Loop through each record
    for (int i = 0; i < num_records; i++) {
        // Allocate memory for new record
        Record* new_record = (Record*)malloc(sizeof(Record));
        if (!new_record) {
            // Handle allocation failure
            if (logging) {
                printf("Allocation failed at index %d\n", i);
            }
            continue;
        }

        // Initialize record fields
        new_record->value = rand() % value_range + 1;
        new_record->status = true;
        new_record->offset = (long*)malloc(sizeof(long));

        // Add record to linked list
        if (!head) {
            head = tail = new_record;
        } else {
            tail->next = new_record;
            tail = new_record;
        }
    }

    // Free memory for unused records
    Node* current = head;
    while (current != NULL) {
        if (!current->status) {
            free(current->record.offset);
            current = current->next;
            continue;
        }

        // Move to next record
        current = current->next;
    }
}
