#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 10000
#define MEMORY_LIMIT 1048576 // 1 MB
#define LOGGING_SYSTEM "syslog"

typedef struct {
    long offset;
    int key;
    double value;
} record;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
record *records = NULL;
int num_records = 0;
long max_size = 0;
double total_memory_usage = 0;

void init(const char *config_file) {
    FILE *fp = fopen(config_file, "r");
    if (fp == NULL) {
        printf("Error: failed to open config file\n");
        return;
    }

    // Read the configuration file and initialize the records array
    while (!feof(fp)) {
        record r = {0};
        int ret = fscanf(fp, "%ld %d %lf", &r.offset, &r.key, &r.value);
        if (ret == 3) {
            num_records++;
            total_memory_usage += sizeof(record);
            if (total_memory_usage > max_size) {
                max_size = total_memory_usage;
            }
        }
    }

    // Allocate memory for the records array
    records = malloc(num_records * sizeof(record));
    if (records == NULL) {
        printf("Error: failed to allocate memory for records\n");
        return;
    }

    // Initialize the records with the values from the configuration file
    rewind(fp);
    int i = 0;
    while (!feof(fp)) {
        record r = {0};
        int ret = fscanf(fp, "%ld %d %lf", &r.offset, &r.key, &r.value);
        if (ret == 3) {
            records[i++] = r;
        }
    }

    // Close the configuration file
    fclose(fp);
}

void cleanup() {
    pthread_mutex_lock(&mutex);
    if (records != NULL) {
        free(records);
        records = NULL;
    }
    pthread_mutex_unlock(&mutex);
}

record *get_record(long offset, int key) {
    pthread_mutex_lock(&mutex);

    // Find the record with the specified offset and key
    for (int i = 0; i < num_records; i++) {
        if (records[i].offset == offset && records[i].key == key) {
            pthread_mutex_unlock(&mutex);
            return &records[i];
        }
    }

    // If the record is not found, allocate memory for a new record and add it to the array
    if (total_memory_usage < max_size) {
        record r = {offset, key, 0};
        records = realloc(records, (num_records + 1) * sizeof(record));
        if (records != NULL) {
            records[num_records++] = r;
            total_memory_usage += sizeof(record);
            pthread_mutex_unlock(&mutex);
            return &records[num_records - 1];
        } else {
            printf("Error: failed to allocate memory for new record\n");
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
    } else {
        printf("Error: maximum size threshold reached, cannot add new records\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
}

void update_record(long offset, int key, double value) {
    pthread_mutex_lock(&mutex);

    // Find the record with the specified offset and key
    for (int i = 0; i < num_records; i++) {
        if (records[i].offset == offset && records[i].key == key) {
            records[i].value = value;
            pthread_mutex_unlock(&mutex);
            return;
