                records[i].value = value;
                pthread_mutex_unlock(&mutex);
                return;
            }
        }
    } else {
        printf("Error: maximum size threshold reached, cannot update records\n");
        pthread_mutex_unlock(&mutex);
        return;
    }
}

void remove_record(long offset, int key) {
