    // Find the record with the specified offset and key
    for (int i = 0; i < num_records; i++) {
        if (records[i].offset == offset && records[i].key == key) {
            total_memory_usage -= sizeof(record);
            records[i] = records[num_records - 1];
            num_records--;
            pthread_mutex_unlock(&mutex);
            return;
        }
    }

    // If the record is not found, remove it if it exists in memory
    if (total_memory_usage < max_size) {
        for (int i = 0; i < num_records; i++) {
            if (records[i].offset == offset && records[i].key == key) {
                total_memory_usage -= sizeof(record);
                records[i] = records[num_records - 1];
                num_records--;
                pthread_mutex_unlock(&mutex);
                return;
            }
        }
    } else {
        printf("Error: maximum size threshold reached, cannot remove records\n");
        pthread_mutex_unlock(&mutex);
        return;
    }
}

int main() {
