// Define the data structures used for logging events
struct log_entry {
    int event_type;
    char message[256];
    enum status_code status;
    unsigned long timestamp;
    bool archived;
};

struct log_system {
    struct log_entry *log_entries;
    size_t num_entries;
    pthread_mutex_t lock; // for thread safety
};

// Initialize the log system with a given capacity
void init_log(struct log_system *ls, size_t capacity) {
    ls->log_entries = malloc(capacity * sizeof(struct log_entry));
    if (ls->log_entries == NULL) {
        // handle memory allocation failure gracefully
        printf("Failed to allocate memory for log entries\n");
        return;
    }
    ls->num_entries = 0;
    pthread_mutex_init(&ls->lock, NULL);
}

// Add a new log entry to the system
void add_log(struct log_system *ls, struct log_entry *entry) {
    // Lock the mutex before modifying the shared data structure
    pthread_mutex_lock(&ls->lock);
    if (ls->num_entries < capacity) {
        ls->log_entries[ls->num_entries++] = *entry;
    } else {
        // handle overflow gracefully
        printf("Log system has reached maximum capacity\n");
    }
    pthread_mutex_unlock(&ls->lock);
}

// Remove a log entry from the system by its ID
void remove_log(struct log_system *ls, int id) {
    // Lock the mutex before modifying the shared data structure
    pthread_mutex_lock(&ls->lock);
    struct log_entry *target = NULL;
    for (int i = 0; i < ls->num_entries; i++) {
        if (ls->log_entries[i].id == id) {
            target = &ls->log_entries[i];
            break;
        }
    }
    if (target != NULL) {
        // move the last entry to the position of the removed entry
        ls->log_entries[target - ls->log_entries] = ls->log_entries[--ls->num_entries];
    } else {
        printf("Log entry with ID %d not found\n", id);
    }
    pthread_mutex_unlock(&ls->lock);
}

// Retrieve all log entries that match a given event type and timestamp range
struct log_entry *get_logs(struct log_system *ls, int event_type, unsigned long start, unsigned long end) {
    // Lock the mutex before modifying the shared data structure
    pthread_mutex_lock(&ls->lock);
    struct log_entry *results = NULL;
    for (int i = 0; i < ls->num_entries; i++) {
        if (ls->log_entries[i].event_type == event_type && start <= ls->log_entries[i].timestamp && end >= ls->log_entries[i].timestamp) {
            results = realloc(results, (ls->num_entries - i + 1) * sizeof(struct log_entry));
            results[i] = ls->log_entries[i];
        }
    }
    pthread_mutex_unlock(&ls->lock);
    return results;
}

// Free all memory allocated by the log system
void free_log(struct log_system *ls) {
    // Lock the mutex before modifying the shared data structure
    pthread_mutex_lock(&ls->lock);
    if (ls->num_entries > 0) {
        free(ls->log_entries);
        ls->num_entries = 0;
    }
    pthread_mutex_unlock(&ls->lock);
}
