}

// Function to handle memory fragmentation in NIC statistics structures
void handle_fragmentation(struct nic_stats **nic_stats, int num_interfaces) {
    // Handle memory fragmentation by allocating a larger block of memory for the NIC statistics structures
    struct nic_stats *new_nic_stats = realloc(nic_stats, sizeof(struct nic_stats *) * (num_interfaces + 1));
