// Java module for processing disjoint pairs using a Union-Find data structure
import java.util.*;

public class UnionFind {
    private Map<Integer, Set<Integer>> adjacencyList; // map of disjoint sets
    private int numDisjointSets; // number of disjoint sets

    public UnionFind(int numInterfaces) {
        // initialize the map of disjoint sets and set the number of disjoint sets to 0
        this.adjacencyList = new HashMap<>();
        this.numDisjointSets = 0;
    }

    public void addEdge(int interface1, int interface2) {
        // check if the two interfaces are already in the same set
        Set<Integer> set1 = adjacencyList.get(interface1);
        Set<Integer> set2 = adjacencyList.get(interface2);
        if (set1 != null && set2 != null) {
            // if they are, merge the two sets
            int setSize = set1.size() + set2.size();
            for (int i : set1) {
                adjacencyList.put(i, set2);
            }
            for (int i : set2) {
                adjacencyList.put(i, set1);
            }
            this.numDisjointSets--;
        } else if (set1 == null && set2 == null) {
            // if they are not, add them to the map as separate sets
            adjacencyList.put(interface1, new HashSet<>(Collections.singletonList(interface1)));
            adjacencyList.put(interface2, new HashSet<>(Collections.singletonList(interface2)));
            this.numDisjointSets++;
        } else {
            // if only one of the interfaces is in a set, add the other to it
            Set<Integer> set = (set1 != null) ? set1 : set2;
            int index = (set1 != null) ? interface2 : interface1;
            adjacencyList.put(index, set);
        }
    }

    public void findDisjointPairs() {
        // iterate over the map of disjoint sets and output each pair of interfaces that are in different sets
        for (int i = 0; i < numInterfaces; i++) {
            Set<Integer> set1 = adjacencyList.get(i);
            if (set1 == null) continue;
            for (int j = i + 1; j < numInterfaces; j++) {
                Set<Integer> set2 = adjacencyList.get(j);
                if (set2 != null && !set1.equals(set2)) {
                    System.out.println("Disjoint pair: " + i + ", " + j);
                }
            }
        }
    }
}
