#include <stdio.h>
#include <stdlib.h>
#include <assert.h>

// Define a struct to represent a node in the tree
struct Node {
    long key;
    int data;
    struct Node* left;
    struct Node* right;
};

// Define a function to create a new node with the given key and data
struct Node* createNode(long key, int data) {
    struct Node* node = malloc(sizeof(struct Node));
    assert(node != NULL);

    node->key = key;
    node->data = data;
    node->left = NULL;
    node->right = NULL;

    return node;
}

// Define a function to insert a new node with the given key and data into the tree
void insertNode(struct Node** root, long key, int data) {
    // If the root is NULL, create a new node and set it as the root
    if (*root == NULL) {
        *root = createNode(key, data);
        return;
    }

    // If the key is less than the current node's key, recurse on the left subtree
    if (key < (*root)->key) {
        insertNode(&(*root)->left, key, data);
    }

    // If the key is greater than or equal to the current node's key, recurse on the right subtree
    else if (key >= (*root)->key) {
        insertNode(&(*root)->right, key, data);
    }
}

// Define a function to find a node in the tree with the given key
struct Node* findNode(struct Node* root, long key) {
    // If the root is NULL or the key is less than the current node's key, recurse on the left subtree
    if (root == NULL || key < root->key) {
        return findNode(root->left, key);
    }

    // If the key is greater than or equal to the current node's key, recurse on the right subtree
    else if (key >= root->key) {
        return findNode(root->right, key);
    }

    // If the key matches the current node's key, return the node
    else {
        return root;
    }
}

// Define a function to traverse the tree in-order and print each node's data
void traverseAndPrint(struct Node* root) {
    if (root != NULL) {
        // Traverse the left subtree
        traverseAndPrint(root->left);

        // Print the current node's data
        printf("%d ", root->data);

        // Traverse the right subtree
        traverseAndPrint(root->right);
    }
}

// Define a function to free all memory used by the tree
void freeTree(struct Node* root) {
    if (root != NULL) {
        // Free the left and right subtrees
        freeTree(root->left);
        freeTree(root->right);

        // Free the current node's memory
        free(root);
    }
}

int main() {
    struct Node* root = NULL;

    // Insert some nodes into the tree
    insertNode(&root, 10, 20);
    insertNode(&root, 5, 30);
    insertNode(&root, 8, 40);
    insertNode(&root, 7, 50);
    insertNode(&root, 9, 60);

    // Find a node in the tree with a given key
    struct Node* node = findNode(root, 10);
    printf("Node found: %d\n", node->data);

    // Traverse the tree and print each node's data
    traverseAndPrint(root);

    // Free all memory used by the tree
    freeTree(root);

    return 0;
}']

