// Function to remove a node from the linked list
void removeNodeFromLinkedList(LinkedList *list, LinkedListNode *node) {
    if (node == list->head) {
        list->head = node->next;
    } else {
        LinkedListNode *current = list->head;
        while (current != NULL && current->next != node) {
            current = current->next;
        }
        if (current == NULL) {
