// Function to remove an element from the array
void removeElementFromArray(NFAPI_CRC_INDICATION_PDU_T **array, int size) {
    // If the array is empty, return
    if (size == 0) {
        return;
    }

    // Free the memory of the element to be removed
    free(array[size - 1]);

    // Shift all elements after the element to be removed one position left
    for (int i = size - 1; i < size; i++) {
        array[i] = array[i + 1];
    }
}

// Function to handle error conditions
void handleError(NFAPI_CRC_INDICATION_PDU_T *data) {
    // If the data is NULL, return
    if (data == NULL) {
        return;
    }

    // Free the memory of the data
