import java.util.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.nio.charset.StandardCharsets;

public class ProcessAndTransformBatch {
    private static final int MAX_STRING_LENGTH = 10000; // maximum length of a string in the batch
    private static final int MAX_BATCH_SIZE = 100000; // maximum number of strings in the batch
    private static final String RX_UE_INFORMATION_TAG = "RX_UE_INFORMATION";
    private static final String CRC_INDICATION_REL8_TAG = "CRC_INDICATION_REL8";

    public static Map<String, String> processAndTransformBatch(List<String> batch) {
        if (batch.size() > MAX_BATCH_SIZE) {
            throw new IllegalArgumentException("Batch size exceeds maximum limit");
        }

        List<NFAPI_CRC_INDICATION_PDU_T> nfapiPdus = new ArrayList<>();

        // Initialize the list of NFAPI_CRC_INDICATION_PDU_T structures
        for (String str : batch) {
            if (!isValidString(str)) {
                continue;
            }

            NFAPI_CRC_INDICATION_PDU_T pdu = new NFAPI_CRC_INDICATION_PDU_T();
            pdu.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
            pdu.RNTI = 0; // TODO: Set RNTI value
            pdu.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
            pdu.CRCFLAG = true; // Randomly set CRCFLAG to true or false

            nfapiPdus.add(pdu);
        }

        // Perform MD5 hashing on each string in the batch and store the hashes in a map
        Map<String, String> hashMap = new HashMap<>();
        for (NFAPI_CRC_INDICATION_PDU_T pdu : nfapiPdus) {
            String hash = getMd5Hash(pdu.RX_UE_INFORMATION_TAG + pdu.RNTI);
            hashMap.put(pdu.RX_UE_INFORMATION_TAG + pdu.RNTI, hash);
        }

        // Release resources allocated for the list of NFAPI_CRC_INDICATION_PDU_T structures
        nfapiPdus.clear();

        return hashMap;
    }

    private static boolean isValidString(String str) {
        if (str == null || str.length() > MAX_STRING_LENGTH) {
            return false;
        }

        for (int i = 0; i < str.length(); ++i) {
            char c = str.charAt(i);
            if (!isPrintableCharacter(c)) {
                System.out.println("Skipping string with non-printable character: " + str);
                return false;
            }
        }

        return true;
    }

    private static String getMd5Hash(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] bytes = md.digest(input.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (byte b : bytes) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Failed to get MD5 message digest instance", e);
        }
    }

    private static boolean isPrintableCharacter(char c) {
        if ((c >= '0' && c <= '9') || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')) {
            return true;
        }
        switch (c) {
            case ' ':
            case '-':
            case '.':
            case '_':
                return true;
            default:
                return false;
        }
    }
}
