struct Node {
    double value;
    int str_len;
    char *str;
    struct Node *next;
};

// Define the operations that can be performed on the data
typedef enum {
    TRANSFORM,
    AGGREGATE,
    FILTER
} OperationType;

// Define the function to handle the data processing pipeline
void process_data(struct Node *head) {
    // Initialize the operation queue
    struct OperationQueue {
        OperationType type;
        char *param1;
        char *param2;
    } op_queue[];

    // Add operations to the queue based on user-defined criteria
    add_operation(op_queue, TRANSFORM, "square", NULL);
    add_operation(op_queue, AGGREGATE, "sum", NULL);
    add_operation(op_queue, FILTER, "greater than 10", "20");

    // Iterate through the linked list and perform operations
    struct Node *current = head;
    while (current != NULL) {
        for (int i = 0; i < sizeof(op_queue) / sizeof(struct OperationQueue); i++) {
            switch (op_queue[i].type) {
                case TRANSFORM:
                    // Perform the transformation on the current node's value
                    current->value = pow(current->value, 2);
                    break;
                case AGGREGATE:
                    // Perform the aggregation on the current node's value
                    if (i == 0) {
                        current->sum = current->value;
                    } else {
                        current->sum += current->value;
                    }
                    break;
                case FILTER:
                    // Check if the current node's value meets the filtering criteria
                    if (current->value > op_queue[i].param2) {
                        current = current->next;
                    } else {
                        // Remove the current node from the linked list
                        struct Node *temp = current;
                        current = current->next;
                        temp->next = NULL;
                    }
                    break;
            }
        }
        current = current->next;
    }
}

// Function to add an operation to the queue based on user-defined criteria
void add_operation(struct OperationQueue *op_queue, OperationType type, char *param1, char *param2) {
    // Check if there is enough space in the queue for another operation
    if (sizeof(op_queue) / sizeof(struct OperationQueue) == 0) {
        return;
    }

    // Add the operation to the queue
    op_queue[sizeof(op_queue) / sizeof(struct OperationQueue) - 1].type = type;
    op_queue[sizeof(op_queue) / sizeof(struct OperationQueue) - 1].param1 = param1;
    op_queue[sizeof(op_queue) / sizeof(struct OperationQueue) - 1].param2 = param2;
}
