// Define the data structure for the linked list
typedef struct node {
    double value;
    char* str;
    int len;
    struct node* next;
} node_t;

// Define the data structure for the operations array
typedef enum operation {
    DOUBLE,
    STRING,
    NODE,
    INDEX
} op_type_t;

typedef struct operation {
    int index;
    union {
        double dval;
        char* sptr;
        node_t* nptr;
    };
    op_type_t type;
} operation_t;

// Define the data structure for the dynamic array
typedef struct {
    int size;
    int count;
    void** data;
} dynamic_array_t;

// Function to reverse a linked list, handling both non-circular and circular cases
void reverse(node_t* head) {
    node_t* current = head;
    node_t* prev = NULL;

    // Reverse the linked list in place
    while (current != NULL) {
        node_t* next = current->next;
        current->next = prev;
        prev = current;
        current = next;
    }

    // If the original list was circular, fix up the last node's next pointer
    if (head != NULL && head->next != NULL) {
        head->next = prev;
    }
}

// Function to reverse an array of operations
void reverse_operations(operation_t* op, int count) {
    for (int i = 0; i < count / 2; i++) {
        // Swap the values and types of the two operations
        operation_t temp = op[i];
        op[i] = op[count - i - 1];
        op[count - i - 1] = temp;
    }
}

// Function to create a new dynamic array with the given size and initialize it to NULL
dynamic_array_t* create_dynamic_array(int size) {
    dynamic_array_t* arr = malloc(sizeof(dynamic_array_t));
    if (arr == NULL) {
        // Handle allocation failure gracefully
        return NULL;
    }
    arr->size = size;
    arr->count = 0;
    arr->data = calloc(size, sizeof(void*));
    if (arr->data == NULL) {
        free(arr);
        // Handle allocation failure gracefully
        return NULL;
    }
    return arr;
}

// Function to add a new element to the end of a dynamic array
int push_back_dynamic_array(dynamic_array_t* arr, void* data) {
    if (arr->count >= arr->size) {
        // Handle out-of-memory gracefully
        return -1;
    }
    arr->data[arr->count++] = data;
    return 0;
}

// Function to remove the last element from a dynamic array
void pop_back_dynamic_array(dynamic_array_t* arr) {
    if (arr->count > 0) {
        arr->data[--arr->count] = NULL;
    }
}

// Function to destroy a dynamic array and free its memory
void destroy_dynamic_array(dynamic_array_t* arr) {
    if (arr != NULL) {
        for (int i = 0; i < arr->size; i++) {
            free(arr->data[i]);
        }
        free(arr);
    }
}

// Function to populate an array of operations with random values and strings
void populate_operations(operation_t* op, int count) {
    for (int i = 0; i < count; i++) {
