                }
                op[i].nptr->value = ((double)rand()) / RAND_MAX;
                op[i].nptr->str = malloc(sizeof(char) * (rand() % 10 + 1));
                if (op[i].nptr->str == NULL) {
                    free(op[i].nptr);
                    // Handle allocation failure gracefully
                    break;
                }
                op[i].nptr->len = rand() % 10 + 1;
                for (int j = 0; j < op[i].nptr->len; j++) {
                    op[i].nptr->str[j] = 'a' + rand() % 26;
                }
                break;
            case INDEX:
                // Do nothing, as the index is already set in populate_operations()
                break;
        }
    }
}

// Function to perform a reverse operation on an array of operations
void reverse_operations(operation_t* op, int count) {
    for (int i = 0; i < count / 2; i++) {
        // Swap the values and types of the two operations
        operation_t temp = op[i];
        op[i] = op[count - i - 1];
        op[count - i - 1] = temp;
    }
}

int main() {
    // Create a dynamic array to hold the linked list nodes and operations
    int size = 50;
    dynamic_array_t* arr = create_dynamic_array(size);
    if (arr == NULL) {
        return -1;
    }

    // Populate the array with random values and strings
    operation_t* op = malloc(sizeof(operation_t) * size);
    if (op == NULL) {
        destroy_dynamic_array(arr);
        return -1;
    }
    populate_operations(op, size);

    // Create a linked list and add the elements from the array to it
    node_t* head = NULL;
    for (int i = 0; i < arr->count; i++) {
        if (arr->data[i] != NULL) {
            push_back_dynamic_array(arr, arr->data[i]);
        }
    }

    // Reverse the linked list in place and reverse the operations array as well
    reverse(head);
    reverse_operations(op, size);

