#include <assert.h>
#include <pthread.h>

// Structures used in the dynamic array
struct LTE_RRC_Capability_List {
    int RadioBearerId;
    struct LTE_RRC_Radio_Bearer_Config RadioBearerConfig;
    struct LTE_RRC_Transmission_Config_Dedicated TransmissionConfigDedicated;
};
typedef struct LTE_RRC_Capability_List LTE_RRC_Capability_List;

// Global variables
LTE_RRC_Capability_List* CapabilityList = NULL; // Dynamic array of LTE_RRC_Capability_List structures
int CapabilityCount = 0; // Current number of elements in the CapabilityList array
int CapabilityMaxSize = 0; // Maximum capacity of the CapabilityList array
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // Mutex for thread-safe access to the CapabilityList array

// Methods to add new entries, resize the array, validate RadioBearerId uniqueness, and iterate over the array for debugging
void AddCapability(LTE_RRC_Capability_List* newCapability) {
    pthread_mutex_lock(&mutex);
    if (CapabilityCount == CapabilityMaxSize) { // Resize the array when it reaches its capacity limit
        CapabilityMaxSize *= 2;
        CapabilityList = realloc(CapabilityList, sizeof(LTE_RRC_Capability_List*) * CapabilityMaxSize);
    }
    assert(CapabilityCount < CapabilityMaxSize); // Ensure that the array can still fit new elements
    CapabilityList[CapabilityCount++] = newCapability; // Add new entry to the end of the array
    pthread_mutex_unlock(&mutex);
}
void ResizeArray(int newSize) {
    if (newSize <= 0) return; // Ensure that newSize is a positive value
    pthread_mutex_lock(&mutex);
    CapabilityMaxSize = newSize;
    CapabilityList = realloc(CapabilityList, sizeof(LTE_RRC_Capability_List*) * newSize);
    pthread_mutex_unlock(&mutex);
}
void ValidateRadioBearerIdUniqueness() {
    for (int i = 0; i < CapabilityCount - 1; i++) { // Check uniqueness of RadioBearerIds within the array
        if (CapabilityList[i]->RadioBearerId == CapabilityList[i + 1]->RadioBearerId) {
            printf("Error: Duplicate RadioBearerId found in CapabilityList!\n");
            exit(1);
        }
    }
}
void IterateCapabilities() {
    for (int i = 0; i < CapabilityCount; i++) { // Iterate over all elements in the array
        LTE_RRC_Capability_List* currentCapability = CapabilityList[i];
        printf("Capability #%d: RadioBearerId=%d, RadioBearerConfig=", i, currentCapability->RadioBearerId);
        PrintLTE_RRC_Radio_Bearer_Config(&currentCapability->RadioBearerConfig);
        printf(", TransmissionConfigDedicated=");
        PrintLTE_RRC_Transmission_Config_Dedicated(&currentCapability->TransmissionConfigDedicated);
    }
}

// Method to handle external dependencies and performance considerations
void InitializeExternalDependencies(FILE* configFile) { // Read configuration from a file
    pthread_mutex_lock(&mutex);
    CapabilityMaxSize = 10; // Initial capacity of the array
    CapabilityList = malloc(sizeof(LTE_RRC_Capability_List*) * CapabilityMaxSize);
    while (fscanf(configFile, "%d %d", &currentCapability->RadioBearerId, &currentCapability->TransmissionConfigDedicated) == 2) { // Read config from file
        if (currentCapability->RadioBearerId < 0 || currentCapability->TransmissionConfigDedicated < 0) {
            printf("Error: Invalid configuration found in external dependencies!\n");
            exit(1);
        }
        AddCapability(currentCapability);
    }
    pthread_mutex_unlock(&mutex);
}
void LoadFromCache() { // Read cached configurations from memory
    pthread_mutex_lock(&mutex);
    CapabilityMaxSize = 10; // Initial capacity of the array
    CapabilityList = malloc(sizeof(LTE_RRC_Capability_List*) * CapabilityMaxSize);
    int configCount = GetCachedConfigCount(); // Read number of cached configurations from memory
    for (int i = 0; i < configCount; i++) { // Iterate over all cached configurations
        LTE_RRC_Capability_List* currentCapability = malloc(sizeof(LTE_RRC_Capability_List));
        currentCapability->RadioBearerId = GetCachedConfigId(i); // Read RadioBearerId from memory
        currentCapability->TransmissionConfigDedicated = GetCachedConfigTransmissionConfigDedicated(i); // Read TransmissionConfigDedicated from memory
        AddCapability(currentCapability);
    }
    pthread_mutex_unlock(&mutex);
}
void SaveToCache() { // Write cached configurations to memory
    pthread_mutex_lock(&mutex);
    int configCount = 0; // Count number of cached configurations
    for (int i = 0; i < CapabilityCount; i++) { // Iterate over all active configurations
        if (IsCachedConfig(CapabilityList[i]->RadioBearerId)) { // Check if the configuration is already cached
            configCount++; // Increment count of cached configurations
        } else { // Add new configuration to cache
            SetCachedConfig(CapabilityList[i]->RadioBearerId, CapabilityList[i]->TransmissionConfigDedicated);
            configCount++; // Increment count of cached configurations
        }
    }
    pthread_mutex_unlock(&mutex);
}

// Helper functions for managing external dependencies and caching configurations
void GetCachedConfigCount() { // Return number of cached configurations
    return CapabilityCount;
}
int GetCachedConfigId(int index) { // Return RadioBearerId of the configuration at given index in cache
    if (index >= 0 && index < CapabilityCount) {
        return CapabilityList[index]->RadioBearerId;
    } else {
        printf("Error: Invalid index found in GetCachedConfigId()!\n");
        exit(1);
    }
}
int GetCachedConfigTransmissionConfigDedicated(int index) { // Return TransmissionConfigDedicated of the configuration at given index in cache
    if (index >= 0 && index < CapabilityCount) {
        return CapabilityList[index]->TransmissionConfigDedicated;
    } else {
        printf("Error: Invalid index found in GetCachedConfigTransmissionConfigDedicated()!\n");
        exit(1);
    }
}
void SetCachedConfig(int radioBearerId, int transmissionConfigDedicated) { // Add new configuration to cache
    LTE_RRC_Capability_List* currentCapability = malloc(sizeof(LTE_RRC_Capability_List));
    currentCapability->RadioBearerId = radioBearerId;
    currentCapability->TransmissionConfigDedicated = transmissionConfigDedicated;
    AddCapability(currentCapability);
}
bool IsCachedConfig(int radioBearerId) { // Check if the configuration with given RadioBearerId is already cached
    for (int i = 0; i < CapabilityCount; i++) {
        if (CapabilityList[i]->RadioBearerId == radioBearerId) {
            return true;
        }
    }
    return false;
}

// Helper functions for printing LTE_RRC_Radio_Bearer_Config and LTE_RRC_Transmission_Config_Dedicated structures
void PrintLTE_RRC_Radio_Bearer_Config(LTE_RRC_Radio_Bearer_Config* config) { // Print RadioBearerId and TransmissionMode fields of the structure
    printf("RadioBearerId=%d, TransmissionMode=%d", config->RadioBearerId, config->TransmissionMode);
}
void PrintLTE_RRC_Transmission_Config_Dedicated(LTE_RRC_Transmission_Config_Dedicated* config) { // Print DedicatedPDSCH_ToInterFreqCarrierConfiguration and TDD-Info fields of the structure
    printf("DedicatedPDSCH_ToInterFreqCarrierConfiguration=");
