void init() {
    if (configs == NULL) {
        configs = calloc(1, sizeof(Vector));
    }
}

// Add a new configuration to the vector
bool add_config(const char* ip_address, const char* subnet_mask, const char* gateway, const char* dns_servers[]) {
    if (configs == NULL) {
        init();
    }

    NetworkInterfaceConfig config = {
        .ip_address = strdup(ip_address),
        .subnet_mask = strdup(subnet_mask),
        .gateway = strdup(gateway),
        .dns_servers = dns_servers,
    };

    return vector_push_back(configs, &config);
}

// Remove a configuration from the vector by its index
void remove_config(int idx) {
