        init();
    }

    NetworkInterfaceConfig* config = vector_get(configs, idx);
    free((void*) config->ip_address);
    free((void*) config->subnet_mask);
    free((void*) config->gateway);
    for (int i = 0; i < NUM_DNS_SERVERS; i++) {
        free((void*) config->dns_servers[i]);
    }
    vector_erase(configs, idx);
}

// Iterate over all configurations and perform a callback function on each one
void iterate_configs(iterate_callback cb) {
    if (configs == NULL) {
        init();
    }

    for (int i = 0; i < vector_size(configs); i++) {
        NetworkInterfaceConfig* config = vector_get(configs, i);
        cb(config->ip_address, config->subnet_mask, config->gateway, config->dns_servers);
    }
}

// Clean up the library by freeing all memory allocated to the vector
void cleanup() {
    if (configs != NULL) {
        for (int i = 0; i < vector_size(configs); i++) {
            NetworkInterfaceConfig* config = vector_get(configs, i);
            free((void*) config->ip_address);
            free((void*) config->subnet_mask);
            free((void*) config->gateway);
            for (int j = 0; j < NUM_DNS_SERVERS; j++) {
                free((void*) config->dns_servers[j]);
            }
        }
        vector_free(configs);
    }
}
