typedef struct {
    int x, y;
} point;

typedef enum {
    RED, GREEN, BLUE
} color;

typedef union {
    double num;
    char str[10];
    point p;
    color c;
} shape_data;

typedef struct {
    int id;
    shape_data data;
} shape;

int hash(int key) {
    // A simple hash function that maps the key to a value between 0 and SIZE-1
    return key % SIZE;
}

void insert_shape(shape* shapes, int id, shape_data data) {
    // Insert the new shape into the hash table
    shapes[hash(id)].id = id;
    shapes[hash(id)].data = data;
}

void delete_shape(shape* shapes, int id) {
    // Delete the shape with the given ID from the hash table
    shapes[hash(id)].id = -1;
    shapes[hash(id)].data.num = 0;
}

void modify_shape(shape* shapes, int id, shape_data data) {
    // Modify the shape with the given ID in the hash table
    shapes[hash(id)].data = data;
}

int get_shape(shape* shapes, int id) {
    // Return the type of the shape with the given ID from the hash table
    return shapes[hash(id)].data.type;
}

void allocate_memory(shape* shapes, int size) {
    // Allocate memory for the hash table and initialize it to -1
    for (int i = 0; i < SIZE; i++) {
        shapes[i].id = -1;
    }
}

void free_memory(shape* shapes) {
    // Free the memory allocated for the hash table
    free(shapes);
}

int main() {
    // Test the function with a few shapes
    shape* shapes = malloc(sizeof(shape) * SIZE);
    allocate_memory(shapes, SIZE);
    insert_shape(shapes, 1, (shape_data){.num = 3.14});
    insert_shape(shapes, 2, (shape_data){.str = "hello"});
    insert_shape(shapes, 3, (shape_data){.p = {5, 6}});
    insert_shape(shapes, 4, (shape_data){.c = RED});
    printf("Shape with ID 1 is a number: %f\n", get_shape(shapes, 1));
    printf("Shape with ID 2 is a string: %s\n", get_shape(shapes, 2));
    printf("Shape with ID 3 is a point: {%d, %d}\n", get_shape(shapes, 3).p.x, get_shape(shapes, 3).p.y);
    printf("Shape with ID 4 is a color: %s\n", get_shape(shapes, 4));
    delete_shape(shapes, 2);
    modify_shape(shapes, 1, (shape_data){.num = 3.14 * 2});
    free_memory(shapes);
    return 0;
}
```
