        while (offsets[j] != NULL) {
            j = (j + 1) % size;
        }
        offsets[j] = i;
        records[i].offset = &offsets[j];
        i++;
    }

    // Set the keys in the records to unique values within the key range
    srand(time(NULL)); // seed the RNG with the current time
    for (size_t i = 0; i < record_count; i++) {
        int key = rand() % key_count;
        while (key == records[i].key) {
            key = rand() % key_count;
        }
        records[i].key = key;
    }

    // Set the values in the records to random numbers within the specified range
    for (size_t i = 0; i < record_count; i++) {
        records[i].value = rand() % max_value;
    }

    return records;
}
