// Function to populate the linked list nodes with random values and strings
void populate_list(node_t *head) {
    // Allocate memory for the linked list nodes
    node_t *current = head;
    while (current->next != NULL) {
        current = current->next;
    }
    for (size_t i = 0; i < 5; i++) {
        node_t *node = malloc(sizeof(node_t));
        node->value = d.doubles[i];
        node->string = d.strings[i];
        node->length = strlen(node->string);
        current->next = node;
        current = current->next;
    }
}

// Function to reverse the linked list while avoiding infinite loops
void reverse_list(node_t *head) {
    if (head == NULL || head->next == NULL) return;
    node_t *current = head, *prev = NULL;
    while (current != NULL) {
        node_t *next = current->next;
        current->next = prev;
        prev = current;
        current = next;
    }
}

// Function to allocate memory for the linked list nodes
void alloc_list(node_t **head, size_t n) {
    *head = malloc(sizeof(node_t));
    (*head)->next = NULL;
    node_t *current = *head;
    for (size_t i = 1; i < n; i++) {
        current->next = malloc(sizeof(node_t));
        current = current->next;
        current->next = NULL;
    }
}

