    return num_elements;
}

// Define function to process an individual element
int process_element(NFAPI_CRC_INDICATION_PDU_T *element) {
    if (element_counter >= MAX_ELEMENTS) {
        fprintf(stderr, "Error: Exceeded maximum allowed number of elements\n");
        return -1;
    }
    // Acquire mutex lock to ensure concurrent access is synchronized
    pthread_mutex_lock(&mutex);
    element->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    element_counter++;
    // Release mutex lock to release access
    pthread_mutex_unlock(&mutex);
    return 1;
}

// Define function to reset the session and clear all allocated memory
void reset_session() {
    // Acquire mutex lock to ensure concurrent access is synchronized
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < element_counter; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *element = elements[i];
        free(element);
