static void crc_indication_list_init(CrcIndicationList *list) {
    list->elements = NULL;
    list->num_elements = 0;
}

static void crc_indication_list_destroy(CrcIndicationList *list) {
    free(list->elements);
    crc_indication_list_init(list);
}

static bool crc_indication_list_add(CrcIndicationList *list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (list->num_elements >= MAX_ELEMENTS) {
        return false;
    }

    list->elements = realloc(list->elements, ELEMENT_SIZE * (list->num_elements + 1));
    memcpy(&list->elements[list->num_elements], &element, ELEMENT_SIZE);
    list->num_elements++;

    return true;
}

static bool crc_indication_list_remove(CrcIndicationList *list, size_t index) {
    if (index >= list->num_elements) {
        return false;
    }

    memmove(&list->elements[index], &list->elements[index + 1], ELEMENT_SIZE * (list->num_elements - index - 1));
    list->num_elements--;

    return true;
}

static NFAPI_CRC_INDICATION_PDU_T crc_indication_list_get(CrcIndicationList *list, size_t index) {
    if (index >= list->num_elements) {
        return NULL;
    }

    return &list->elements[index];
}
