    int id;
} SensorReading;

// Function to initialize the hash table
void initHashTable(SensorReading *sensorReadings, int numSensors) {
    // Initialize an array of size `numSensors` with all indices set to -1
    for (int i = 0; i < numSensors; i++) {
        sensorReadings[i].id = -1;
    }
}

// Function to insert a new sensor reading into the hash table
void insertSensorReading(SensorReading *sensorReadings, int numSensors, SensorReading newSensorReading) {
    // Check if the sensor ID is already in the table
    for (int i = 0; i < numSensors; i++) {
        if (sensorReadings[i].id == newSensorReading.id) {
            // If it's already in the table, update the reading
            sensorReadings[i] = newSensorReading;
            return;
        }
    }

    // If it's not in the table, find an empty slot to insert it
    for (int i = 0; i < numSensors; i++) {
        if (sensorReadings[i].id == -1) {
            sensorReadings[i] = newSensorReading;
            return;
        }
    }
}

// Function to delete a sensor reading from the hash table
void deleteSensorReading(SensorReading *sensorReadings, int numSensors, int id) {
    // Find the index of the sensor reading to delete
    for (int i = 0; i < numSensors; i++) {
        if (sensorReadings[i].id == id) {
            // Mark the slot as empty by setting it to -1
            sensorReadings[i].id = -1;
            return;
        }
    }
}

// Function to validate and format temperature readings
void validateTemperature(float *temperature, float minTemp, float maxTemp) {
    // Check if the temperature is within the specified range
    if (*temperature < minTemp || *temperature > maxTemp) {
        // If it's not, assign a default value
        *temperature = (minTemp + maxTemp) / 2.0;
    }
}

// Function to compute the minimum temperature over a given time window
float minTemperature(SensorReading *sensorReadings, int numSensors, long startTime, long endTime) {
    // Initialize the minimum temperature to the first reading
    float minTemp = sensorReadings[0].temperature;

    // Iterate over the readings within the time window
    for (int i = 0; i < numSensors; i++) {
        if (sensorReadings[i].timestamp >= startTime && sensorReadings[i].timestamp <= endTime) {
            validateTemperature(&(sensorReadings[i].temperature), minTemp, maxTemp);
            minTemp = min(minTemp, sensorReadings[i].temperature);
        }
    }

    return minTemp;
}

// Function to compute the maximum temperature over a given time window
float maxTemperature(SensorReading *sensorReadings, int numSensors, long startTime, long endTime) {
    // Initialize the maximum temperature to the first reading
    float maxTemp = sensorReadings[0].temperature;

    // Iterate over the readings within the time window
    for (int i = 0; i < numSensors; i++) {
        if (sensorReadings[i].timestamp >= startTime && sensorReadings[i].timestamp <= endTime) {
            validateTemperature(&(sensorReadings[i].temperature), minTemp, maxTemp);
            maxTemp = max(maxTemp, sensorReadings[i].temperature);
        }
    }

    return maxTemp;
}

// Function to compute the average temperature over a given time window
float avgTemperature(SensorReading *sensorReadings, int numSensors, long startTime, long endTime) {
    // Initialize the sum of temperatures to the first reading
    float sumTemp = sensorReadings[0].temperature;

    // Iterate over the readings within the time window
    for (int i = 0; i < numSensors; i++) {
        if (sensorReadings[i].timestamp >= startTime && sensorReadings[i].timestamp <= endTime) {
            validateTemperature(&(sensorReadings[i].temperature), minTemp, maxTemp);
            sumTemp += sensorReadings[i].temperature;
        }
    }

    return sumTemp / (endTime - startTime);
}
