// Function to validate input file path, ensure readability and permissions
int validate_input(const char *filepath) {
    struct stat buffer;
    int ret = 0;

    if (stat(filepath, &buffer) != 0) {
        fprintf(stderr, "Error: input file does not exist or is not readable\n");
        return -1;
    }

    // Check user permissions
    if ((buffer.st_mode & S_IRUSR) == 0 || (buffer.st_mode & S_IWUSR) == 0) {
        fprintf(stderr, "Error: user does not have sufficient permissions to access input file\n");
        return -1;
    }

    // Check if file is too large for this process
    if (buffer.st_size > MAX_FILESIZE) {
        fprintf(stderr, "Error: input file size exceeds maximum allowed size\n");
        return -1;
    }

    return ret;
}

// Function to load the selected cipher from OpenSSL based on command line options
EVP_CIPHER *load_cipher(const char *cmd) {
    EVP_CIPHER *cipher = NULL;

    if (strcmp(cmd, "encrypt") == 0) {
        cipher = EVP_aes_256_cbc();
    } else if (strcmp(cmd, "decrypt") == 0) {
        cipher = EVP_aes_256_ecb();
    } else {
        fprintf(stderr, "Error: unsupported command line option\n");
        return NULL;
    }

    return cipher;
}

// Function to initialize the cipher context with the loaded cipher and configure for multi-threaded operations if necessary
EVP_CIPHER_CTX *init_cipher(const char *cmd, int concurrency) {
    EVP_CIPHER *cipher = load_cipher(cmd);
    EVP_CIPHER_CTX *ctx = NULL;

    if (cipher == NULL) {
        return NULL;
    }

    ctx = EVP_CIPHER_CTX_new();

    // Configure for multi-threaded operations if concurrency level is greater than one
    if (concurrency > 1) {
        EVP_CIPHER_CTX_set_flags(ctx, EVP_CIPH_FLAG_FIPS);
    }

    return ctx;
}

// Function to process the input file in parallel chunks, encrypting or decrypting data concurrently as specified by the command line option
int process_input(const char *filepath, const char *cmd, int concurrency) {
    EVP_CIPHER *cipher = NULL;
    EVP_CIPHER_CTX *ctx = NULL;
    size_t blocksize = 0;
    unsigned char *inbuf = NULL;
    unsigned char *outbuf = NULL;
    int ret = 0, i = 0;

