    // Initialize cipher context with loaded cipher and configure for multi-threaded operations if necessary
    ctx = init_cipher(cmd, concurrency);

    // Calculate block size based on selected cipher
    blocksize = EVP_CIPHER_block_size(cipher);

    // Allocate buffers for input and output data
    inbuf = (unsigned char *)malloc(blocksize);
    outbuf = (unsigned char *)malloc(blocksize);

    if (inbuf == NULL || outbuf == NULL) {
        ret = -1;
        goto cleanup;
    }

    // Open input file for reading
    FILE *fp = fopen(filepath, "r");

    // Process input file in parallel chunks, encrypting or decrypting data concurrently as specified by the command line option
    while (fread(inbuf, blocksize, 1, fp) > 0) {
        // Encrypt or decrypt input chunk based on command line option
        if (strcmp(cmd, "encrypt") == 0) {
            EVP_EncryptUpdate(ctx, outbuf, &i, inbuf, blocksize);
        } else if (strcmp(cmd, "decrypt") == 0) {
            EVP_DecryptUpdate(ctx, outbuf, &i, inbuf, blocksize);
        }

        // Write encrypted or decrypted data to output file
        fwrite(outbuf, i, 1, stdout);
    }

    // Clean up memory
cleanup:
