    bool processDatasetsConcurrently(vector<string> filenames, int& largestValue) {
        vector<thread> threads;
        mutex mtx;
        condition_variable cv;

        for (auto& filename : filenames) {
            thread t([&]() {
                vector<record> records;
                if (deserializeFromDisk(filename, records)) {
                    int largestValue = 0;
                    processDataset(records, largestValue);
                    unique_lock<mutex> lck(mtx);
                    cv.notify_all();
                }
            });
            threads.push_back(move(t));
        }

        for (auto& t : threads) {
            t.join();
        }

        return true;
    }

    bool processDatasetsSequentially(vector<string> filenames, int& largestValue) {
        for (auto& filename : filenames) {
            vector<record> records;
            if (deserializeFromDisk(filename, records)) {
                processDataset(records, largestValue);
            }
        }
        return true;
    }

