// Define the function to allocate and initialize the memory for the arrays
void *allocateAndInitializeMemory(int numKeys, int numOffsets, int minValue, int maxValue) {
    // Calculate the size of each array based on the input parameters
    size_t keysSize = numKeys * sizeof(int);
    size_t offsetsSize = numOffsets * sizeof(long);
    size_t recordsSize = (keysSize + offsetsSize) / 2; // Average size of the two arrays, rounded up to nearest integer

    // Allocate memory for the arrays using aligned allocation functions
    int *keys = aligned_alloc(CACHE_LINE_SIZE, keysSize);
    long *offsets = aligned_alloc(CACHE_LINE_SIZE, offsetsSize);
    Record *records = aligned_alloc(CACHE_LINE_SIZE, recordsSize);

    // Initialize the memory for the arrays
    memset(keys, 0, keysSize);
    memset(offsets, 0, offsetsSize);
    for (int i = 0; i < recordsSize; i++) {
        Record record = {.value = rand() % (maxValue - minValue + 1) + minValue};
        records[i] = record;
    }

    // Initialize the memory for the concurrency lock and condition variable
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    // Return a pointer to the first element of the array of records
    return records;
}

