    for (int i = 0; i < num_offsets; ++i) {
        printf("%ld ", cache->offsets[i]);
    }
    printf("\n");
}

void print_keys() {
    for (int i = 0; i < num_keys; ++i) {
        printf("%d ", cache->keys[i]);
    }
    printf("\n");
}

void print_records() {
    for (int i = 0; i < num_records; ++i) {
        printf("%ld %d\n", cache->records[i].offset, cache->records[i].key);
    }
}

int main(void) {
    int max_offsets = 10;
    int max_keys = 5;
    int max_records = 20;
    cache_resize(max_offsets, max_keys, max_records);
    update_offset(0, 34);
    update_key(1, 789);
    update_record(2, (Record_t){.offset = 1234, .key = 567});
    print_offsets();
    print_keys();
    print_records();
    return 0;
}
