```python
import os

def serialize_records(records: list) -> bytes:
    serialized_data = b""
    for record in records:
        serialized_data += record.id.to_bytes(4, byteorder="big")
        serialized_data += record.value.to_bytes(4, byteorder="big")
        serialized_data += record.string_id.encode("utf-8")
    return serialized_data

def deserialize_records(serialized_data: bytes) -> list:
    records = []
    for i in range(0, len(serialized_data), 12):
        id = int.from_bytes(serialized_data[i:i+4], byteorder="big")
        value = int.from_bytes(serialized_data[i+4:i+8], byteorder="big")
        string_id = serialized_data[i+8:].decode("utf-8")
        records.append(Record(id, value, string_id))
    return records

def create_directory(dir_name: str) -> None:
    if not os.path.exists(dir_name):
        os.makedirs(dir_name)

def set_env_var(var_name: str, dir_name: str) -> None:
    os.environ[var_name] = dir_name

# Example usage:
records = [
    Record(1, 2, "hello"),
    Record(3, 4, "world")
]
serialize_records(records)
deserialized_records = deserialize_records(serialized_data)
create_directory("my_directory")
set_env_var("MY_DIRECTORY", "my_directory")
