<?php

class User {
    private $id;
    private $name;
    private $email;
    private $password;
    private $role;
    private $status;

    public function __construct($id, $name, $email, $password, $role, $status) {
        $this->id = $id;
        $this->name = $name;
        $this->email = $email;
        $this->password = $password;
        $this->role = $role;
        $this->status = $status;
    }

    public function getId() {
        return $this->id;
    }

    public function getName() {
        return $this->name;
    }

    public function getEmail() {
        return $this->email;
    }

    public function getPassword() {
        return $this->password;
    }

    public function getRole() {
        return $this->role;
    }

    public function getStatus() {
        return $this->status;
    }
}

function manageUserAccounts($request) {
    // Validate request parameters
    if (!isset($request['id']) || !is_numeric($request['id'])) {
        throw new \Exception('Invalid user ID');
    }

    $user = new User($request['id'], $request['name'], $request['email'], $request['password'], $request['role'], $request['status']);

    // Validate email format and password strength
    if (!filter_var($user->getEmail(), FILTER_VALIDATE_EMAIL)) {
        throw new \Exception('Invalid email address');
    }

    if (strlen($user->getPassword()) < 8) {
        throw new \Exception('Password must be at least 8 characters long');
    }

    // Validate role and status values
    if (!in_array($user->getRole(), ['admin', 'user'])) {
        throw new \Exception('Invalid role value');
    }

    if (!in_array($user->getStatus(), ['active', 'inactive'])) {
        throw new \Exception('Invalid status value');
    }

    // Perform sub-action based on request parameters
    switch ($request['sub_action']) {
        case 'update_details':
            updateUserDetails($user);
            break;
        case 'delete':
            deleteUser($user->getId());
            break;
        case 'change_role':
            changeUserRole($user, $request['new_role']);
            break;
        case 'change_status':
            changeUserStatus($user, $request['new_status']);
            break;
        default:
            throw new \Exception('Invalid sub-action');
    }
}

function updateUserDetails(User $user) {
    // Update user details in database
    $db = getDatabaseConnection();
    $query = "UPDATE users SET name = :name, email = :email, password = :password WHERE id = :id";
    $stmt = $db->prepare($query);
    $stmt->execute([
        ':name' => $user->getName(),
        ':email' => $user->getEmail(),
        ':password' => $user->getPassword(),
        ':id' => $user->getId()
    ]);

    // Log change for auditing purposes
    logChange($user->getId(), 'details', [
        'name' => $user->getName(),
        'email' => $user->getEmail(),
        'password' => $user->getPassword()
    ]);
}

function deleteUser($id) {
    // Delete user from database
    $db = getDatabaseConnection();
    $query = "DELETE FROM users WHERE id = :id";
    $stmt = $db->prepare($query);
    $stmt->execute([':id' => $id]);

    // Log change for auditing purposes
    logChange($id, 'delete', []);
}

function changeUserRole(User $user, $newRole) {
    // Update user role in database
    $db = getDatabaseConnection();
    $query = "UPDATE users SET role = :role WHERE id = :id";
    $stmt = $db->prepare($query);
    $stmt->execute([
        ':role' => $newRole,
        ':id' => $user->getId()
    ]);

    // Log change for auditing purposes
    logChange($user->getId(), 'role', [
        'old_role' => $user->getRole(),
        'new_role' => $newRole
    ]);
}

function changeUserStatus(User $user, $newStatus) {
    // Update user status in database
    $db = getDatabaseConnection();
    $query = "UPDATE users SET status = :status WHERE id = :id";
    $stmt = $db->prepare($query);
    $stmt->execute([
        ':status' => $newStatus,
        ':id' => $user->getId()
    ]);

    // Log change for auditing purposes
    logChange($user->getId(), 'status', [
        'old_status' => $user->getStatus(),
        'new_status' => $newStatus
    ]);
}

function getDatabaseConnection() {
    // Get database connection from cache or create a new one if necessary
    $cache = getCache();
    $conn = $cache['db'];
    if (!$conn) {
        $conn = new PDO('mysql:host=localhost;dbname=mydatabase', 'username', 'password');
        $cache['db'] = $conn;
    }

    return $conn;
}

function getCache() {
    // Get cache from memory or create a new one if necessary
    static $cache = [];
    if (!$cache) {
        $cache = ['db' => null];
    }

    return $cache;
}

function logChange($userId, $type, $data) {
    // Log change for auditing purposes
    $date = date('Y-m-d H:i:s');
    $ipAddress = getIpAddress();
    $userAgent = $_SERVER['HTTP_USER_AGENT'];

    $logEntry = "User ID: $userId | Type: $type | Data: $data | Date: $date | IP Address: $ipAddress | User Agent: $userAgent";
    error_log($logEntry, 3, 'audit.log');
}

function getIpAddress() {
    // Get client's IP address
    if (!empty($_SERVER['HTTP_CLIENT_IP'])) {
        return $_SERVER['HTTP_CLIENT_IP'];
    } elseif (!empty($_SERVER['HTTP_X_FORWARDED_FOR'])) {
        return $_SERVER['HTTP_X_FORWARDED_FOR'];
    } else {
        return $_SERVER['REMOTE_ADDR'];
    }
}
