#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

// Define the maximum number of semaphores that can be created
#define MAX_SEMAPHORES 10000

// Define the size of the memory pool for semaphore structures
#define SEM_POOL_SIZE 500

typedef struct {
    // The name of the semaphore
    char *name;

    // The number of threads waiting on the semaphore
    int waitCount;

    // The current value of the semaphore
    int value;

    // The mutex to protect the semaphore
    pthread_mutex_t mutex;

    // The condition variable to signal when the semaphore is available
    pthread_cond_t cond;
} Semaphore;

// Define a linked list for the semaphore structures
typedef struct {
    Semaphore *sem;
    struct ListNode *next;
} ListNode;

static ListNode *semaphoreList = NULL;
static int nextSemaphoreId = 0;

// Define a memory pool for the semaphore structures
static Semaphore *semaphores[SEM_POOL_SIZE] = {NULL};
static int freeSemaphoreCount = SEM_POOL_SIZE;

// Function to create a new semaphore
int createSemaphore(const char *name, int value) {
    // Check if the maximum number of semaphores has been reached
    if (nextSemaphoreId >= MAX_SEMAPHORES) {
        return -1;
    }

    // Allocate a new semaphore structure from the memory pool
    Semaphore *sem = NULL;
    if (freeSemaphoreCount > 0) {
        int index = nextSemaphoreId % SEM_POOL_SIZE;
        freeSemaphoreCount--;
        sem = semaphores[index];
        nextSemaphoreId++;
    } else {
        sem = malloc(sizeof(Semaphore));
    }

    // Initialize the semaphore structure
    sem->name = name;
    sem->waitCount = 0;
    sem->value = value;
    pthread_mutex_init(&sem->mutex, NULL);
    pthread_cond_init(&sem->cond, NULL);

    // Add the semaphore to the linked list of semaphores
    ListNode *node = malloc(sizeof(ListNode));
    node->sem = sem;
    node->next = semaphoreList;
    semaphoreList = node;

    return 0;
}

// Function to delete a semaphore
int deleteSemaphore(const char *name) {
    // Find the semaphore in the linked list of semaphores
    ListNode *node = semaphoreList;
    while (node != NULL && strcmp(node->sem->name, name) != 0) {
        node = node->next;
    }

    // Check if the semaphore was found in the linked list
    if (node == NULL) {
        return -1;
    }

    // Remove the semaphore from the linked list
    ListNode *prevNode = NULL;
    while (node != NULL && strcmp(node->sem->name, name) == 0) {
        prevNode = node;
        node = node->next;
    }

    // Release the memory used by the semaphore structure
    if (prevNode == NULL) {
        freeSemaphoreCount++;
        nextSemaphoreId--;
        pthread_mutex_destroy(&node->sem->mutex);
        pthread_cond_destroy(&node->sem->cond);
        free(node->sem);
        node->sem = NULL;
    } else {
        prevNode->next = node->next;
        pthread_mutex_destroy(&node->sem->mutex);
        pthread_cond_destroy(&node->sem->cond);
        free(node->sem);
        free(node);
    }

    return 0;
}

// Function to acquire a semaphore
int acquireSemaphore(const char *name) {
    // Find the semaphore in the linked list of semaphores
    ListNode *node = semaphoreList;
    while (node != NULL && strcmp(node->sem->name, name) != 0) {
        node = node->next;
    }

    // Check if the semaphore was found in the linked list
    if (node == NULL) {
        return -1;
    }

    // Acquire the mutex for the semaphore
    pthread_mutex_lock(&node->sem->mutex);

    // Check if the semaphore value is greater than zero
    if (node->sem->value <= 0) {
        node->sem->waitCount++;
        while (node->sem->value <= 0) {
            pthread_cond_wait(&node->sem->cond, &node->sem->mutex);
        }
        node->sem->waitCount--;
    }

    // Decrement the semaphore value
    node->sem->value--;

    // Release the mutex for the semaphore
    pthread_mutex_unlock(&node->sem->mutex);

    return 0;
}

// Function to release a semaphore
int releaseSemaphore(const char *name) {
    // Find the semaphore in the linked list of semaphores
    ListNode *node = semaphoreList;
    while (node != NULL && strcmp(node->sem->name, name) != 0) {
        node = node->next;
    }

    // Check if the semaphore was found in the linked list
    if (node == NULL) {
        return -1;
    }

    // Acquire the mutex for the semaphore
    pthread_mutex_lock(&node->sem->mutex);

    // Increment the semaphore value
    node->sem->value++;

    // Notify any waiting threads if the semaphore value is greater than zero
    if (node->sem->waitCount > 0 && node->sem->value > 0) {
        pthread_cond_broadcast(&node->sem->cond);
    }

    // Release the mutex for the semaphore
    pthread_mutex_unlock(&node->sem->mutex);

    return 0;
}
