import yaml
import json
import requests
from datetime import datetime

class NetworkDevice:
    def __init__(self, hostname):
        self.hostname = hostname
        self.url = f"https://{hostname}/api/"
        self.token = None

    def login(self, username, password):
        url = f"{self.url}login"
        data = {
            "username": username,
            "password": password
        }
        response = requests.post(url, json=data)
        if response.status_code == 200:
            self.token = response.json()["token"]
            return True
        else:
            print("Login failed")
            return False

    def logout(self):
        url = f"{self.url}logout"
        headers = {"Authorization": f"Bearer {self.token}"}
        response = requests.post(url, headers=headers)
        if response.status_code == 200:
            self.token = None
            return True
        else:
            print("Logout failed")
            return False

    def apply_policies(self, policies):
        url = f"{self.url}apply-policies"
        headers = {"Authorization": f"Bearer {self.token}"}
        data = {"policies": policies}
        response = requests.post(url, headers=headers, json=data)
        if response.status_code == 200:
            return True
        else:
            print("Apply policies failed")
            return False

    def get_policies(self):
        url = f"{self.url}get-policies"
        headers = {"Authorization": f"Bearer {self.token}"}
        response = requests.get(url, headers=headers)
        if response.status_code == 200:
            policies = response.json()["policies"]
            return policies
        else:
            print("Get policies failed")
            return []

    def update_configuration(self, config):
        url = f"{self.url}update-configuration"
        headers = {"Authorization": f"Bearer {self.token}"}
        data = json.dumps(config)
        response = requests.post(url, headers=headers, data=data)
        if response.status_code == 200:
            return True
        else:
            print("Update configuration failed")
            return False

    def get_configuration(self):
        url = f"{self.url}get-configuration"
        headers = {"Authorization": f"Bearer {self.token}"}
        response = requests.get(url, headers=headers)
        if response.status_code == 200:
            config = response.json()["config"]
            return config
        else:
            print("Get configuration failed")
            return []

class PolicyManager:
    def __init__(self, device):
        self.device = device
        self.policies = []

    def load_policies(self, policies):
        self.policies = policies

    def apply_policies(self):
        for policy in self.policies:
            url = f"{self.device.url}apply-policy"
            headers = {"Authorization": f"Bearer {self.device.token}"}
            data = json.dumps(policy)
            response = requests.post(url, headers=headers, data=data)
            if response.status_code == 200:
                print(f"Applied policy {policy['name']}")
            else:
                print("Policy application failed")

    def get_policies(self):
        url = f"{self.device.url}get-policies"
        headers = {"Authorization": f"Bearer {self.device.token}"}
        response = requests.get(url, headers=headers)
        if response.status_code == 200:
            policies = response.json()["policies"]
            return policies
        else:
            print("Get policies failed")
            return []

class ConfigurationManager:
    def __init__(self, device):
        self.device = device
        self.config = {}

    def load_configuration(self, config):
        self.config = config

    def update_configuration(self):
        url = f"{self.device.url}update-configuration"
        headers = {"Authorization": f"Bearer {self.device.token}"}
        data = json.dumps(self.config)
        response = requests.post(url, headers=headers, data=data)
        if response.status_code == 200:
            print("Updated configuration")
        else:
            print("Update configuration failed")

    def get_configuration(self):
        url = f"{self.device.url}get-configuration"
        headers = {"Authorization": f"Bearer {self.device.token}"}
        response = requests.get(url, headers=headers)
        if response.status_code == 200:
            config = response.json()["config"]
            return config
        else:
            print("Get configuration failed")
            return []

class NetworkDeviceMonitor:
    def __init__(self, device):
        self.device = device
        self.policies = {}
        self.config = {}
        self.last_update = datetime.now()

    def update(self):
        policies = self.device.get_policies()
        config = self.device.get_configuration()
        if policies != []:
            self.policies = policies
        if config != []:
            self.config = config
        self.last_update = datetime.now()

    def get_status(self):
        status = {
            "policies": self.policies,
            "configuration": self.config,
            "last_update": str(self.last_update)
        }
        return status

# Example usage:
device = NetworkDevice("192.168.1.1")
device.login("admin", "password")
policies = device.get_policies()
config = device.get_configuration()
policy_manager = PolicyManager(device)
policy_manager.load_policies(policies)
policy_manager.apply_policies()
config_manager = ConfigurationManager(device)
config_manager.load_configuration(config)
config_manager.update_configuration()
device.logout()']

