// C component for managing a dynamic list of geometric shapes
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct shape {
    int id;
    char* name;
} shape_t;

struct shape_list {
    shape_t** shapes;
    size_t num_shapes;
    pthread_mutex_t mutex;
};

void init_shape_list(shape_list_t* list) {
    list->num_shapes = 0;
    list->shapes = NULL;
}

int add_shape(shape_list_t* list, shape_t* shape) {
    pthread_mutex_lock(&list->mutex);
    int ret = 0;
    if (list->num_shapes == 0) {
        // allocate memory for the first shape
        list->shapes = malloc(sizeof(shape_t*));
    } else {
        // reallocate memory to accommodate new shape
        list->shapes = realloc(list->shapes, (list->num_shapes + 1) * sizeof(shape_t*));
    }
    if (!list->shapes) {
        ret = -1;
    } else {
        // add the new shape to the list
        list->shapes[list->num_shapes++] = shape;
    }
    pthread_mutex_unlock(&list->mutex);
    return ret;
}

int remove_shape(shape_list_t* list, int id) {
    pthread_mutex_lock(&list->mutex);
    int ret = 0;
    // find the shape with the given ID and remove it from the list
    for (size_t i = 0; i < list->num_shapes; i++) {
        if (list->shapes[i]->id == id) {
            memmove(list->shapes + i, list->shapes + i + 1, (list->num_shapes - i - 1) * sizeof(shape_t*));
            list->num_shapes--;
            break;
        }
    }
    if (list->num_shapes == 0) {
        // free the memory allocated for the shapes
        free(list->shapes);
        list->shapes = NULL;
    } else {
        // reallocate the memory to remove the freed space
        list->shapes = realloc(list->shapes, list->num_shapes * sizeof(shape_t*));
    }
    pthread_mutex_unlock(&list->mutex);
    return ret;
}

int get_shape(shape_list_t* list, int id) {
    pthread_mutex_lock(&list->mutex);
    int ret = 0;
    // find the shape with the given ID and return it
    for (size_t i = 0; i < list->num_shapes; i++) {
        if (list->shapes[i]->id == id) {
            pthread_mutex_unlock(&list->mutex);
            return list->shapes[i];
        }
    }
    ret = -1;
    pthread_mutex_unlock(&list->mutex);
    return ret;
}

// Java component for handling user sessions in an online messaging application
import java.util.*;
import java.io.*;

class Session {
    private static final int SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes in milliseconds
    private static Map<Integer, User> sessions = new HashMap<>();
    private static Random random = new Random();

    public static void addSession(User user) {
        synchronized (sessions) {
            int sessionId = generateRandomSessionId();
            while (sessions.containsKey(sessionId)) {
                sessionId = generateRandomSessionId();
            }
            sessions.put(sessionId, user);
        }
    }

    public static void removeSession(User user) {
        synchronized (sessions) {
            int sessionId = getSessionId(user);
            if (sessionId != -1) {
                sessions.remove(sessionId);
            }
        }
    }

    public static User getSession(int sessionId) {
        synchronized (sessions) {
            return sessions.get(sessionId);
        }
    }

    private static int generateRandomSessionId() {
        // seed the random number generator with the current time in milliseconds
        long seed = System.currentTimeMillis();
        return (int)(seed + random.nextInt());
    }

    private static int getSessionId(User user) {
        synchronized (sessions) {
            for (Map.Entry<Integer, User> entry : sessions.entrySet()) {
                if (user.equals(entry.getValue())) {
                    return entry.getKey();
                }
            }
            return -1;
        }
    }
}
