// Structure to store information about each device connection
typedef struct DeviceConnection {
    int id;
    char* type;
    int status;
    time_t lastHealthCheck;
    void* configSettings;
} DeviceConnection;

// List of all current device connections
DeviceConnection* connections = NULL;
int numConnections = 0;

// Function to initialize the list of device connections based on user input
void initConnections(int maxNumConnections) {
    if (connections != NULL) {
        // Clean up existing connections before reinitializing
        for (int i = 0; i < numConnections; i++) {
            freeConnection(&connections[i]);
        }
    }
    numConnections = maxNumConnections;
    connections = (DeviceConnection*)malloc(numConnections * sizeof(DeviceConnection));
}

// Function to add a new device connection to the list
void addConnection(int id, char* type, void* configSettings) {
    // Check if there is enough space in the list for the new connection
    if (numConnections >= maxNumConnections) {
        printf("Error: Maximum number of connections reached. Cannot add more devices.\n");
        return;
    }
    // Initialize a new connection structure
    DeviceConnection* newConnection = &connections[numConnections];
    newConnection->id = id;
    newConnection->type = type;
    newConnection->status = CONNECTED;
    newConnection->lastHealthCheck = time(NULL);
    newConnection->configSettings = configSettings;
    numConnections++;
}

// Function to remove a device connection from the list
void removeConnection(int id) {
    // Find the index of the connection to be removed
    int index = -1;
    for (int i = 0; i < numConnections; i++) {
        if (connections[i].id == id) {
            index = i;
            break;
        }
    }
    // Check if the connection was found and remove it from the list
    if (index != -1) {
        freeConnection(&connections[index]);
        numConnections--;
    } else {
        printf("Error: Connection with ID %d not found. Cannot remove.\n", id);
    }
}

// Function to validate the health status of each device connection and maintain network stability
void validateConnections() {
    for (int i = 0; i < numConnections; i++) {
        // Check if the connection is still active
        if (connections[i].status == CONNECTED) {
            // Validate the health status of the connection by sending a heartbeat message
            if (!sendHeartbeatMessage(connections[i])) {
                // Flag unhealthy connections for maintenance or removal to maintain network stability
                printf("Warning: Connection with ID %d is unhealthy. Marking for maintenance.\n", connections[i].id);
                connections[i].status = UNHEALTHY;
            } else {
                // Update the last health check timestamp for the connection
                connections[i].lastHealthCheck = time(NULL);
            }
        } else if (connections[i].status == UNHEALTHY) {
            // Flag unhealthy connections for removal to maintain network stability
            printf("Error: Connection with ID %d is unhealthy. Marking for removal.\n", connections[i].id);
            removeConnection(connections[i].id);
        }
    }
}

// Function to periodically validate the health status of each device connection and maintain network stability
void periodicValidation() {
    // Set a timer interval to trigger the validation function at regular intervals
    struct itimerval timer;
    timer.it_interval = 10;  // 10 seconds
    timer.it_value = 10;  // 10 seconds initially
    setitimer(ITIMER_REAL, &timer, NULL);
}

// Function to free a device connection structure and its associated memory
void freeConnection(DeviceConnection* connection) {
    if (connection->type != NULL) {
        free(connection->type);
    }
    if (connection->configSettings != NULL) {
        free(connection->configSettings);
    }
}
