public:
    RandomNumberGenerator() {
        srand(time(NULL));
    }

    ~RandomNumberGenerator() {}

    bool generateNumbers(const std::vector<std::vector<int>> &inputStreams, std::vector<Record> &records) {
        // Initialize variables
        int numInputStreams = inputStreams.size();
        int totalNumRecords = 0;
        for (int i = 0; i < numInputStreams; ++i) {
            totalNumRecords += inputStreams[i].size();
        }
        bool success = true;

        // Allocate memory for arrays
        std::vector<long> offsetArray(numInputStreams);
        std::vector<int> keyArray(totalNumRecords);
        records.resize(totalNumRecords);

        // Initialize variables
        int recordIndex = 0;
        int inputStreamIndex = 0;
        long currentOffset = 0;
        for (auto &stream : inputStreams) {
            offsetArray[inputStreamIndex] = currentOffset;
            inputStreamIndex++;
            for (auto &value : stream) {
                records[recordIndex].key = value;
                recordIndex++;
            }
            currentOffset += stream.size();
        }

        // Assign random values to each record's int field
        for (int i = 0; i < totalNumRecords; ++i) {
            records[i].value = rand() % MAX_RANGE + MIN_RANGE;
        }

        // Validate and store integers in arrays
        inputStreamIndex = 0;
        for (auto &stream : inputStreams) {
            for (auto &value : stream) {
                if (value == CRITICAL_KEY) {
                    records[recordIndex].key = value;
                    recordIndex++;
                } else {
                    records[recordIndex].key = -1; // invalid key
                }
            }
            inputStreamIndex++;
        }

        // Find and print largest integer in array
        int maxValue = 0;
        for (auto &record : records) {
            if (record.value > maxValue) {
                maxValue = record.value;
            }
        }
        std::cout << "Largest value: " << maxValue << std::endl;

        // Clean up memory
        free(offsetArray);
        free(keyArray);
        records.clear();

        return success;
    }

private:
    struct Record {
        int key;
        int value;
    };
};
}
