#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_DATA_POINTS 1000000
#define MAX_FLOAT_RANGE 5.0
#define DEFAULT_MAX_MEMORY_SIZE (1024 * 1024) // 1 MB

typedef struct data_point {
    double value;
    float range;
    time_t timestamp;
} data_point_t;

void read_stream(int fd, int max_data_points, int max_memory_size, int toggle_compression) {
    // Initialize variables
    char *buffer = malloc(max_memory_size);
    if (buffer == NULL) {
        perror("Memory allocation failed");
        return;
    }
    double largest = 0.0;
    float range = MAX_FLOAT_RANGE;
    int data_points = 0;
    time_t timestamp = time(NULL);
    // Create a hash table to store the data points and facilitate lookups
    struct hash_table *ht = create_hash_table();
    if (ht == NULL) {
        perror("Hash table creation failed");
        free(buffer);
        return;
    }
    // Read from standard input until EOF is reached
    while (!feof(stdin)) {
        double value = 0.0;
        fscanf(stdin, "%lf", &value);
        if (data_points < max_data_points) {
            data_point_t *dp = malloc(sizeof(data_point_t));
            if (dp == NULL) {
                perror("Memory allocation failed");
                break;
            }
            dp->value = value;
            dp->range = range;
            dp->timestamp = timestamp;
            ht_insert(ht, dp);
            data_points++;
        } else {
            // Remove the oldest entry if the maximum capacity is reached
            data_point_t *oldest = ht_remove_oldest(ht);
            free(oldest);
        }
        // Update the largest value and range if necessary
        if (value > largest) {
            largest = value;
        } else if (value < range) {
            range = value;
        }
    }
    // Print the largest value found in the stream
    printf("Largest value: %f\n", largest);
    // Free memory
    free(buffer);
    ht_destroy(ht);
}

void *create_hash_table() {
    struct hash_table *ht = malloc(sizeof(struct hash_table));
    if (ht == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }
    ht->size = 0;
    ht->max_size = DEFAULT_MAX_MEMORY_SIZE / sizeof(data_point_t);
    ht->table = malloc(ht->max_size * sizeof(struct hash_table_entry));
    if (ht->table == NULL) {
        perror("Memory allocation failed");
        free(ht);
        return NULL;
    }
    for (int i = 0; i < ht->max_size; i++) {
        ht->table[i].key = NULL;
        ht->table[i].value = NULL;
        ht->table[i].next = NULL;
    }
    return ht;
}

void *ht_insert(struct hash_table *ht, data_point_t *dp) {
    int index = ht_hash(dp);
    struct hash_table_entry *he = malloc(sizeof(struct hash_table_entry));
    he->key = dp;
    he->value = dp;
    if (ht->table[index].key == NULL) {
        ht->table[index].key = dp;
        ht->table[index].value = dp;
        return dp;
    } else {
        struct hash_table_entry *curr = ht->table[index].next;
        while (curr != NULL) {
            if (dp == curr->key || dp < curr->key) {
                he->next = curr;
                ht->table[index].next = he;
                return dp;
            }
            curr = curr->next;
        }
    }
    ht->size++;
    if (ht->size > ht->max_size) {
        // Dynamic resizing of the hash table when its current capacity is reached
        int new_size = ht->max_size * 2;
        struct hash_table_entry **new_table = realloc(ht->table, new_size * sizeof(struct hash_table_entry));
        if (new_table == NULL) {
            perror("Memory allocation failed");
            return NULL;
        }
        ht->max_size = new_size;
        ht->table = new_table;
    }
    struct hash_table_entry *last = ht->table[index].next;
    while (last->next != NULL) {
        last = last->next;
    }
    last->next = he;
    return dp;
}

data_point_t *ht_remove(struct hash_table *ht, data_point_t *key) {
    int index = ht_hash(key);
    if (ht->table[index].key == NULL) {
        return NULL;
    } else if (ht->table[index].key == key) {
        struct hash_table_entry *he = ht->table[index].next;
        while (he != NULL && he->key != key) {
            he = he->next;
        }
        if (he == NULL) {
            return NULL;
        } else {
            ht->size--;
            struct hash_table_entry *prev = ht->table[index].next;
            while (prev != he) {
                prev = prev->next;
            }
            prev->next = he->next;
            free(he);
            return key;
        }
    } else {
        struct hash_table_entry *curr = ht->table[index].next;
        while (curr != NULL) {
            if (key == curr->key || key < curr->key) {
                break;
            }
            curr = curr->next;
        }
        if (curr == NULL) {
            return NULL;
        } else {
            struct hash_table_entry *prev = ht->table[index].next;
            while (prev != curr) {
                prev = prev->next;
            }
            prev->next = curr->next;
            free(curr);
            return key;
        }
    }
}

int ht_hash(data_point_t *dp) {
    int hash = 0;
    char *str = dp->key;
    for (int i = 0; str[i] != '\0'; i++) {
        hash += str[i];
    }
    return hash % ht->max_size;
}

void ht_destroy(struct hash_table *ht) {
    free(ht->table);
    free(ht);
}
