['```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <mutex>
#include <thread>
#include <chrono>
#include <atomic>
#include <cstdint>

// Data structure to store records
struct Record {
  int value;
  std::chrono::system_clock::time_point timestamp;
};

// Data structure to store datasets
struct Dataset {
  std::vector<Record> records;
  std::atomic<int> numRecords;
  std::mutex mutex;
};

// Library class for managing datasets and records
class DatasetManager {
 public:
  // Constructor to initialize library with default configuration
  DatasetManager() : maxNumRecords_(1000) {}

  // Method to create a new dataset
  void createDataset(const std::string& name) {
    std::lock_guard<std::mutex> lock(mutex_);
    datasets_.push_back(Dataset{name, maxNumRecords_, std::vector<Record>()});
  }

  // Method to add a record to a dataset
  void addRecordToDataset(const std::string& name, const Record& record) {
    std::lock_guard<std::mutex> lock(mutex_);
    auto it = findDataset(name);
    if (it != datasets_.end()) {
      it->records.push_back(record);
      it->numRecords++;
    } else {
      std::cerr << "Error: dataset not found" << std::endl;
    }
  }

  // Method to remove a record from a dataset
  void removeRecordFromDataset(const std::string& name, const Record& record) {
    std::lock_guard<std::mutex> lock(mutex_);
    auto it = findDataset(name);
    if (it != datasets_.end()) {
      it->records.erase(std::remove(it->records.begin(), it->records.end(), record),
                       it->records.end());
      it->numRecords--;
    } else {
      std::cerr << "Error: dataset not found" << std::endl;
    }
  }

  // Method to serialize a dataset to disk
  void serializeDataset(const std::string& name, const std::string& filename) {
    std::lock_guard<std::mutex> lock(mutex_);
    auto it = findDataset(name);
    if (it != datasets_.end()) {
      std::ofstream ofs(filename, std::ios::binary | std::ios::out);
      ofs.write((char*)&(it->numRecords), sizeof(int));
      for (const auto& record : it->records) {
        ofs.write((char*)&(record.value), sizeof(int));
        ofs.write((char*)&(record.timestamp), sizeof(std::chrono::system_clock::time_point));
      }
    } else {
      std::cerr << "Error: dataset not found" << std::endl;
    }
  }

  // Method to deserialize a dataset from disk
  void deserializeDataset(const std::string& name, const std::string& filename) {
    std::lock_guard<std::mutex> lock(mutex_);
    auto it = findDataset(name);
    if (it != datasets_.end()) {
      std::ifstream ifs(filename, std::ios::binary | std::ios::in);
      int numRecords;
      ifs.read((char*)&numRecords, sizeof(int));
      it->records.clear();
      for (int i = 0; i < numRecords; ++i) {
        Record record;
        ifs.read((char*)&record.value, sizeof(int));
        ifs.read((char*)&record.timestamp, sizeof(std::chrono::system_clock::time_point));
        it->records.push_back(record);
      }
    } else {
      std::cerr << "Error: dataset not found" << std::endl;
    }
  }

 private:
  // Find a dataset by name
  std::vector<Dataset>::iterator findDataset(const std::string& name) {
    for (auto it = datasets_.begin(); it != datasets_.end(); ++it) {
      if (it->name == name) return it;
    }
    return datasets_.end();
  }

  // Vector of datasets
  std::vector<Dataset> datasets_;

  // Maximum number of records per dataset
  int maxNumRecords_;

  // Mutex to protect access to the vector of datasets
  std::mutex mutex_;
};

// Example usage of the library
int main() {
  // Create a new dataset
  DatasetManager manager;
  manager.createDataset("my_dataset");

  // Add some records to the dataset
  Record record1 = {1, std::chrono::system_clock::now()};
  Record record2 = {2, std::chrono::system_clock::now()};
  manager.addRecordToDataset("my_dataset", record1);
  manager.addRecordToDataset("my_dataset", record2);

  // Serialize the dataset to disk
  manager.serializeDataset("my_dataset", "my_dataset.bin");

  // Deserialize the dataset from disk
  manager.deserializeDataset("my_dataset", "my_dataset.bin");

  return 0;
}
