// Define a structure to represent geometric shapes
typedef struct {
    int type; // Type identifier (0 for double, 1 for char*, 2 for struct point)
    void* data; // Pointer to data (doubl, char*, or struct point)
} geometric_shape;

// Define a hash table to store the shapes
typedef struct {
    int size; // Size of the hash table
    int count; // Number of shapes in the table
    geometric_shape* shapes[]; // Array of shapes
} shape_table;

// Initialize the hash table and allocate memory for the shapes
void initializeGeometricShapes(int label, const char* f) {
    shape_table* table = malloc(sizeof(shape_table));
    if (!table) {
        printf("Error: Unable to allocate memory for shape table\n");
        return;
    }

    // Initialize the hash table with a size of 1024 and an empty array of shapes
    table->size = 1024;
    table->count = 0;
    table->shapes = malloc(table->size * sizeof(geometric_shape));
    if (!table->shapes) {
        printf("Error: Unable to allocate memory for shape array\n");
        return;
    }

    // Set the module and test names for logging purposes
    char* module = "Geometric Shapes";
    char* test = f;

    // Reset the state of the hash table after each test
    printf("Resetting state of %s.%s...\n", module, test);
    int i;
    for (i = 0; i < table->size; i++) {
        geometric_shape* shape = &table->shapes[i];
        shape->type = -1; // Invalid type identifier
        shape->data = NULL; // No data
    }
    table->count = 0; // Reset the count to 0

    // Run the test function and handle any errors that may occur
    printf("Running %s.%s...\n", module, test);
    f(table);
    if (table->count != 0) {
        printf("Error: Shape table not empty after test\n");
        return;
    }

    // Free the memory allocated for the hash table and shapes
    free(table->shapes);
    free(table);
}
