  struct NetworkInterfaceControl* nicStats = malloc(arraySize);
  if (nicStats == NULL) {
    printf("Error: failed to allocate memory for NIC statistics\n");
    return -1;
  }

  // Initialize the array of NIC statistics structures
  for (int i = 0; i < numNicStats; i++) {
