    nicStats[i].macHeader.destinationAddress[7] = rand() % 256;
    nicStats[i].ipPacket.payloadSize = rand() % maxPacketSize + 1;
    nicStats[i].ipPacket.checksum = 0; // Initialize checksum to 0
  }

