    printf("Error: failed to allocate memory for custom memory pool\n");
    free(nicStats);
    return -1;
  }
  memPool->data = nicStats;
  memPool->size = arraySize;

  // Initialize the system dependencies and validate the integrity of the IP packets
  for (int i = 0; i < numNicStats; i++) {
    struct NetworkInterfaceControl* currNicStat = &nicStats[i];
    uint32_t checksum = calculateChecksum(currNicStat->ipPacket.payloadSize);
    if (checksum == 0) { // Checksum should not be 0, it should have some value
      printf("Error: invalid checksum for NIC statistics structure %d\n", i);
      freeMemoryPool(memPool);
      return -1;
    }
    currNicStat->ipPacket.checksum = checksum;
  }

  // Print some feedback to the user about the initialization process
  printf("Initialized %d NIC statistics structures with maximum packet size %d\n", numNicStats, maxPacketSize);

  return 0;
}

void freeMemoryPool(struct MemoryPool* memPool) {
  if (memPool != NULL) {
    free(memPool->data);
    free(memPool);
  }
}

uint32_t calculateChecksum(int payloadSize) {
  // Generate a random checksum for the IP packet with the given payload size
  uint32_t checksum = rand() % (1 << (payloadSize * 8));
  return checksum;
}
