// C function to initialize and manage dynamic array of NIC statistics structures
void nic_stats_init(int max_size, int min_size) {
    // Initialize memory pool with fixed size
    mempool = init_mempool(max_size, min_size);

    // Allocate memory for NIC statistics structure array
    nic_stats_array = (NIC_STATS*)malloc(sizeof(NIC_STATS) * max_size);

    // Initialize each NIC statistics structure with random payload size and checksum
    for (int i = 0; i < max_size; i++) {
        nic_stats_array[i].mac_header.payload_size = rand() % (max_size - min_size) + min_size;
        nic_stats_array[i].mac_header.checksum = calculate_checksum(nic_stats_array[i].mac_header.payload, nic_stats_array[i].mac_header.payload_size);
    }
}

// C function to add new NIC statistics structure to the dynamic array
void nic_stats_add(NIC_STATS *new_nic_stat) {
    // Acquire lock for thread-safe access to memory pool and NIC statistics array
    pthread_mutex_lock(&mempool.lock);

    // Check if memory pool has space available for new NIC statistics structure
    if (mempool.used < mempool.size) {
        // Allocate memory for new NIC statistics structure from memory pool
        nic_stats_array[mempool.used].mac_header.payload = malloc(new_nic_stat->mac_header.payload_size);
        memcpy(nic_stats_array[mempool.used].mac_header.payload, new_nic_stat->mac_header.payload, new_nic_stat->mac_header.payload_size);
        nic_stats_array[mempool.used].ip_packet.checksum = calculate_checksum(nic_stats_array[mempool.used].ip_packet.payload, nic_stats_array[mempool.used].ip_packet.payload_size);
    } else {
        // Memory pool is full, resize it to accommodate new NIC statistics structure
        int new_size = mempool.size * 2;
        if (new_size > max_size) {
            new_size = max_size;
        }
        nic_stats_resize(new_size);
    }

    // Increment used memory in memory pool
    mempool.used++;

    // Release lock for thread-safe access to memory pool and NIC statistics array
    pthread_mutex_unlock(&mempool.lock);
}

// C function to remove NIC statistics structure from the dynamic array
void nic_stats_remove(int index) {
    // Acquire lock for thread-safe access to memory pool and NIC statistics array
    pthread_mutex_lock(&mempool.lock);

    // Check if NIC statistics structure exists at given index
    if (index < mempool.used) {
        // Free memory used by NIC statistics structure
        free(nic_stats_array[index].mac_header.payload);
    } else {
        // Index out of bounds, do nothing
    }

    // Decrement used memory in memory pool
    mempool.used--;

    // Release lock for thread-safe access to memory pool and NIC statistics array
    pthread_mutex_unlock(&mempool.lock);
}

// C function to resize memory pool based on new maximum size
void nic_stats_resize(int max_size) {
    // Acquire lock for thread-safe access to memory pool and NIC statistics array
    pthread_mutex_lock(&mempool.lock);

    // Check if new maximum size is larger than current maximum size
    if (max_size > mempool.max_size) {
        // Reallocate memory for NIC statistics structure array to new maximum size
        nic_stats_array = realloc(nic_stats_array, sizeof(NIC_STATS) * max_size);
        if (!nic_stats_array) {
            // Memory allocation failed, do nothing
        } else {
            mempool.max_size = max_size;
        }
    }

    // Release lock for thread-safe access to memory pool and NIC statistics array
    pthread_mutex_unlock(&mempool.lock);
}

// C function to calculate checksum of given payload and payload size
unsigned short calculate_checksum(char *payload, int payload_size) {
    // Initialize checksum with random value
    unsigned short checksum = rand() % (max_size - min_size) + min_size;

    // Calculate checksum of payload using simple addition
    for (int i = 0; i < payload_size; i++) {
        checksum += (unsigned char)payload[i];
    }

    return checksum;
}

// Java function to process results from C function and compute disjoint pairs of elements in an integer array using Union-Find data structure
void compute_disjoint_pairs(int[] array, int size) {
    // Initialize Union-Find data structure with size of input array
    UnionFind union_find = new UnionFind(size);

    // Iterate over each element in the input array
    for (int i = 0; i < size; i++) {
        // Find root of element and its parent element
        int root = union_find.find(i);
        int parent = union_find.parent[root];

        // If element is not the root of its own component, add it to the Union-Find data structure
        if (parent != i) {
            union_find.add(i);
        }
    }

    // Compute disjoint pairs of elements in the input array using Union-Find data structure
    int[] disjoint_pairs = new int[union_find.size()];
    int pair_count = 0;
    for (int i = 0; i < union_find.size(); i++) {
        // Find root of element and its parent element
        int root = union_find.find(i);
        int parent = union_find.parent[root];

        // If element is the root of its own component, add it to disjoint pairs array
        if (parent == i) {
            disjoint_pairs[pair_count++] = i;
        }
    }
}
