// Define a structure to represent a student record
typedef struct {
    int id;
    char name[20];
    double score;
} Student;

// Define a hash table to store the student records
static Student* students = NULL;
static size_t numStudents = 0;
static size_t capacity = 1000; // initial capacity of the hash table

// Function to insert a new student record into the hash table
void insertStudent(int id, const char* name, double score) {
    if (id < 0) {
        return;
    }

    // Check if the hash table is full and needs to be resized
    if (numStudents >= capacity) {
        resize();
    }

    // Find an empty slot in the hash table
    size_t index = id % capacity;
    while (students[index].id != -1) {
        index++;
        if (index == capacity) {
            index = 0;
        }
    }

    // Initialize the new student record and insert it into the hash table
    Student* newStudent = &students[index];
    newStudent->id = id;
    strncpy(newStudent->name, name, 20);
    newStudent->score = score;

    numStudents++;
}

// Function to delete a student record from the hash table by ID
void deleteStudent(int id) {
    if (id < 0 || numStudents == 0) {
        return;
    }

    // Find the index of the student record to be deleted
    size_t index = id % capacity;
    while (students[index].id != -1 && students[index].id != id) {
        index++;
        if (index == capacity) {
            index = 0;
        }
    }

    // If the student record is found, delete it and update the number of students
    if (students[index].id != -1) {
        Student* deletedStudent = &students[index];
        deletedStudent->id = -1;
        numStudents--;
    }
}

// Function to resize the hash table when it is full
void resize() {
    // Create a new array of double the size of the current capacity
    Student* newStudents = (Student*) malloc(2 * capacity * sizeof(Student));

    // Copy all existing student records into the new array
    for (size_t i = 0; i < capacity; i++) {
        if (students[i].id != -1) {
            newStudents[i] = students[i];
        }
    }

    // Update the hash table with the new array and its size
    free(students);
    students = newStudents;
    capacity *= 2;
}

// Function to retrieve a student record from the hash table by ID
Student* getStudent(int id) {
    if (id < 0 || numStudents == 0) {
        return NULL;
    }

    // Find the index of the student record to be retrieved
    size_t index = id % capacity;
    while (students[index].id != -1 && students[index].id != id) {
        index++;
        if (index == capacity) {
            index = 0;
        }
    }

    // Return the student record if found, otherwise return NULL
    return (students[index].id == id) ? &students[index] : NULL;
}

// Function to retrieve all student records in the hash table
Student** getAllStudents() {
    Student** studentsCopy = (Student**) malloc(numStudents * sizeof(Student*));
    size_t count = 0;

    // Copy all existing student records into the copy array
    for (size_t i = 0; i < capacity; i++) {
        if (students[i].id != -1) {
            studentsCopy[count] = &students[i];
            count++;
        }
    }

    return studentsCopy;
}

// Function to update a student record in the hash table by ID
void updateStudent(int id, const char* name, double score) {
    if (id < 0 || numStudents == 0) {
        return;
    }

    // Find the index of the student record to be updated
    size_t index = id % capacity;
    while (students[index].id != -1 && students[index].id != id) {
        index++;
        if (index == capacity) {
            index = 0;
        }
    }

    // Update the student record if found, otherwise do nothing
    if (students[index].id == id) {
        strncpy(students[index].name, name, 20);
        students[index].score = score;
    }
}

// Function to retrieve statistical summaries of scores for a given period
void getScoreSummaries(int* ids, int numIds) {
    if (numStudents == 0 || numIds == 0) {
        return;
    }

    // Calculate the highest and lowest scores
    double highestScore = -1.0;
    double lowestScore = -1.0;
    for (size_t i = 0; i < capacity; i++) {
        if (students[i].id != -1) {
            if (highestScore == -1 || students[i].score > highestScore) {
                highestScore = students[i].score;
            }
            if (lowestScore == -1 || students[i].score < lowestScore) {
                lowestScore = students[i].score;
            }
        }
    }

    // Calculate the average score
    double totalScore = 0.0;
    for (size_t i = 0; i < capacity; i++) {
        if (students[i].id != -1) {
            totalScore += students[i].score;
        }
    }
    double averageScore = totalScore / numStudents;

    // Print the statistical summaries for the given period
    printf("Highest score: %.2lf\n", highestScore);
    printf("Lowest score: %.2lf\n", lowestScore);
    printf("Average score: %.2lf\n", averageScore);
}

// Function to integrate the system with an external data source for periodic updates
void updateFromExternalSource() {
    // Perform necessary operations to retrieve and update student records from an external data source
}

int main() {
    // Initialize the hash table with a default capacity of 1000 students
    students = (Student*) malloc(capacity * sizeof(Student));

    // Add some initial students to the hash table
    addStudent(1, "John Doe", 95.5);
    addStudent(2, "Jane Doe", 85.2);
    addStudent(3, "Bob Smith", 70.9);

