#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>
#include <errno.h>

// Define the profile structure
typedef struct Profile {
    int id;
    char *name;
    int preferences[3];
} Profile;

// Define the profile array and its size
Profile profiles[1024];
int profile_count = 0;

// Define the synchronization mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the function to manage user profiles
Profile *manage_profiles(bool initialize_names, int name_length_min, int name_length_max, int pref_range_min, int pref_range_max) {
    // Check if there is enough memory available for a new profile
    if (profile_count >= 1024) {
        return NULL;
    }

    // Acquire the mutex to ensure thread safety
    pthread_mutex_lock(&mutex);

    // Allocate memory for the new profile and set its initial values
    Profile *new_profile = (Profile *)malloc(sizeof(Profile));
    if (!new_profile) {
        fprintf(stderr, "Error: allocation failure\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    new_profile->id = profile_count++;
    new_profile->name = (initialize_names) ? strdup("Default Name") : generate_random_name(name_length_min, name_length_max);
    for (int i = 0; i < 3; i++) {
        new_profile->preferences[i] = generate_random_pref(pref_range_min, pref_range_max);
    }

    // Add the new profile to the array and return its pointer
    profiles[new_profile->id] = *new_profile;
    pthread_mutex_unlock(&mutex);
