    public SessionManager(AuthService authService) {
        this.authService = authService;
    }

    public void addShape(Shape shape) {
        if (shape == null) {
            throw new NullPointerException("Shape cannot be null");
        }

        // Check for duplicate shape identifiers
        Integer shapeIdentifier = shape.getIdentifier();
        if (shapeHashTable.containsKey(shapeIdentifier)) {
            throw new IllegalArgumentException("Duplicate shape identifier: " + shapeIdentifier);
        }

        // Add the shape to the hash table and list of shapes
        shapeHashTable.put(shapeIdentifier, shape);
        sessionList.add(new Session(shapeIdentifier));
    }

    public void removeShape(Integer shapeIdentifier) {
        if (shapeIdentifier == null || !shapeHashTable.containsKey(shapeIdentifier)) {
            throw new IllegalArgumentException("Invalid shape identifier: " + shapeIdentifier);
        }

        // Remove the shape from the hash table and list of shapes
        Shape removedShape = shapeHashTable.remove(shapeIdentifier);
        sessionList.removeIf((session) -> session.getShapeId() == shapeIdentifier);
    }

    public void addSession(Integer shapeIdentifier, String userName) {
        if (shapeIdentifier == null || !shapeHashTable.containsKey(shapeIdentifier)) {
            throw new IllegalArgumentException("Invalid shape identifier: " + shapeIdentifier);
        }

        // Check for duplicate session identifiers
        if (sessionList.stream().anyMatch((session) -> session.getShapeId() == shapeIdentifier && session.getUserName().equals(userName))) {
            throw new IllegalArgumentException("Duplicate session identifier: " + userName);
        }

        // Add the session to the list of sessions
        sessionList.add(new Session(shapeIdentifier, userName));
    }

    public void removeSession(Integer shapeIdentifier, String userName) {
        if (shapeIdentifier == null || !shapeHashTable.containsKey(shapeIdentifier)) {
            throw new IllegalArgumentException("Invalid shape identifier: " + shapeIdentifier);
        }

        // Remove the session from the list of sessions
        Session removedSession = sessionList.removeIf((session) -> session.getShapeId() == shapeIdentifier && session.getUserName().equals(userName));
    }

    public void updateSessions(Integer shapeIdentifier, String userName, List<String> newUsers) {
        if (shapeIdentifier == null || !shapeHashTable.containsKey(shapeIdentifier)) {
            throw new IllegalArgumentException("Invalid shape identifier: " + shapeIdentifier);
        }

        // Update the list of sessions for the given shape and user name
        List<Session> updatedSessions = sessionList.stream()
                .filter((session) -> session.getShapeId() == shapeIdentifier && session.getUserName().equals(userName))
                .map((session) -> new Session(shapeIdentifier, userName, newUsers))
                .collect(Collectors.toList());
        sessionList = updatedSessions;
    }

    public void handleSessionTimeout() {
        // Handle session timeout by removing all sessions that have timed out
        List<Session> timedOutSessions = sessionList.stream()
                .filter((session) -> session.getLastUpdateTime().plusSeconds(MAX_SESSION_TIMEOUT).isBefore(Instant.now()))
                .collect(Collectors.toList());
        for (Session timedOutSession : timedOutSessions) {
            removeSession(timedOutSession.getShapeId(), timedOutSession.getUserName());
        }
    }

    public void handleInvalidToken() {
        // Handle invalid token by removing all sessions that have an expired or invalid token
        List<Session> invalidSessions = sessionList.stream()
                .filter((session) -> authService.isTokenValid(session.getToken()) == false)
                .collect(Collectors.toList());
        for (Session invalidSession : invalidSessions) {
            removeSession(invalidSession.getShapeId(), invalidSession.getUserName());
        }
    }

    public void handleFailedAuthentication() {
        // Handle failed authentication by retrying the authentication request with exponential backoff
        List<Session> failedSessions = sessionList.stream()
                .filter((session) -> authService.authenticate(session.getToken()) == false)
                .collect(Collectors.toList());
        for (Session failedSession : failedSessions) {
            try {
                // Sleep with exponential backoff
                long sleepTime = Math.min(10000, Math.pow(2, failedSession.getFailedAuthCount()));
                Thread.sleep(sleepTime);
                authService.authenticate(failedSession.getToken());
                failedSession.setFailedAuthCount(0);
            } catch (InterruptedException e) {
                // Handle interrupted exception
            }
        }
    }
}
