// Initialize device connection list with maximum number of concurrent connections and available bandwidth
void initialize_device_connections(int max_concurrent_connections, long available_bandwidth) {
    // Create a linked list to store the active connections
    struct node *head = NULL;

    // Set up the connection pool with the specified maximum number of concurrent connections and available bandwidth
    connection_pool = (struct connection_pool){ .max_concurrent_connections = max_concurrent_connections, .available_bandwidth = available_bandwidth };
}

// Add a new device connection to the list
void add_device_connection(int device_id) {
    // Check if the pool has reached its maximum capacity
    if (connection_pool.num_active_connections == connection_pool.max_concurrent_connections) {
        // Throttle new connections if the current load exceeds 80% of the available bandwidth
        long load = get_current_load();
        if (load > (available_bandwidth * 0.8)) {
            return;
        }
    }

    // Create a new node for the device connection
    struct node *new_node = malloc(sizeof(struct node));
    new_node->device_id = device_id;
    new_node->next = NULL;

    // Add the new node to the end of the linked list
    if (head == NULL) {
        head = new_node;
    } else {
        struct node *current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    // Update the connection pool with the new active connection
    connection_pool.num_active_connections++;
}

// Remove a device connection from the list
void remove_device_connection(int device_id) {
    // Find the node for the device connection in the linked list
    struct node *current = head;
    while (current != NULL && current->device_id != device_id) {
        current = current->next;
    }

    // If the node is found, remove it from the linked list and update the connection pool
    if (current != NULL) {
        struct node *previous = current->previous;
        previous->next = current->next;
        free(current);

        connection_pool.num_active_connections--;
    }
}

// Get the current load of the connection pool
long get_current_load() {
    long load = 0;
    struct node *current = head;
    while (current != NULL) {
        load += current->device_id;
        current = current->next;
    }

    return load;
}
