import java.util.concurrent.ConcurrentHashMap;

// Define a class to store the average latency for each device connection
class DeviceConnection {
    private long average_latency;

    public DeviceConnection() {}

    public void updateLatency(long new_latency) {
        this.average_latency = (this.average_latency * 0.9) + (new_latency * 0.1);
    }
}

// Define a function to calculate the average latency for all active connections
public long getAverageLatency() {
    ConcurrentHashMap<Integer, DeviceConnection> device_connections = new ConcurrentHashMap<>();

    // Iterate over each active connection and update the average latency for each device
    synchronized (device_connections) {
        Iterator<Entry<Integer, DeviceConnection>> it = device_connections.entrySet().iterator();
        while (it.hasNext()) {
            Entry<Integer, DeviceConnection> entry = it.next();

            // Update the average latency for each device connection
            long new_latency = getLatency(entry.getKey());
            entry.getValue().updateLatency(new_latency);
        }
    }

    // Calculate the overall average latency by summing the average latencies for all active connections
    long average_latency = 0;
    synchronized (device_connections) {
        Iterator<Entry<Integer, DeviceConnection>> it = device_connections.entrySet().iterator();
        while (it.hasNext()) {
            Entry<Integer, DeviceConnection> entry = it.next();

            // Sum the average latencies for each active connection
            average_latency += entry.getValue().getAverageLatency();
        }
    }

    return average_latency / device_connections.size();
}

// Define a function to get the current load of the connection pool
public long getCurrentLoad() {
    // Calculate the total number of active connections by summing the numbers of active connections for each device
    long num_active_connections = 0;
    synchronized (device_connections) {
        Iterator<Entry<Integer, DeviceConnection>> it = device_connections.entrySet().iterator();
        while (it.hasNext()) {
            Entry<Integer, DeviceConnection> entry = it.next();

            // Sum the numbers of active connections for each device
            num_active_connections += entry.getValue().getNumActiveConnections();
        }
    }

    return num_active_connections;
}
