    }

    // Update the records with new data
    size_t i;
    for (i = 0; i < num_records; i++) {
        (*records)[i].offset = (*records)[i].offset + 1;
        (*records)[i].key = (*records)[i].key + ret;
    }

    return 0;
}

// Function to randomly populate the long field of each record within a specified range
void random_populate(Record* records, size_t num_records, long min, long max) {
    // Check for edge cases such as zero-length arrays and invalid indices
    if (num_records == 0 || min > max) {
        fprintf(stderr, "Error: Invalid input parameters. %s\n", strerror(EINVAL));
        return;
    }

    // Populate the records randomly within the specified range
    size_t i;
    for (i = 0; i < num_records; i++) {
        records[i].offset = min + ((max - min) * rand() / RAND_MAX);
    }
}

// Function to periodically revalidate the integrity of the data structures to ensure they remain consistent and free of corruption
void validate(Record* records, size_t num_records) {
    // Check for edge cases such as zero-length arrays
    if (num_records == 0) {
        fprintf(stderr, "Error: Invalid input parameters. %s\n", strerror(EINVAL));
        return;
    }

    // Calculate the hash value of each record and compare it with the previous hash value to ensure consistency
    size_t i;
    for (i = 0; i < num_records - 1; i++) {
        if (records[i].hash != records[i + 1].hash) {
            fprintf(stderr, "Error: Data corruption detected. %s\n", strerror(EINVAL));
            break;
        }
    }
}
