// Function to allocate and initialize memory for an array of records
Record* allocateRecords(int numRecords, int minInt, int maxInt, double minDouble, double maxDouble) {
    // Validate input parameters
    if (numRecords > MAX_RECORDS || numRecords < 0) {
        return NULL;
    }
    if (minInt >= maxInt || minDouble >= maxDouble || minInt < 0 || minDouble < 0) {
        return NULL;
