record* read_ints(int max_records) {
    // Initialize arrays for storing the offset values, keys, and records
    long* offsets = malloc(max_records * sizeof(long));
    int* keys = malloc(max_records * sizeof(int));
    record* recs = malloc(max_records * sizeof(record));

    // Check for memory allocation failure
    if (offsets == NULL || keys == NULL || recs == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory\n");
        return NULL;
    }

    // Read integers from standard input and store them in the record array
    int i = 0;
    while (i < max_records && scanf("%d", &recs[i].val) == 1) {
        recs[i].timestamp = time(NULL);
        recs[i].status = 'N'; // Initialize status flag to 'N' for not processed
        offsets[i] = i;
        keys[i] = i;
        i++;
    }

    // Resize arrays if necessary to avoid infinite growth
    if (i < max_records) {
        long* temp_offsets = realloc(offsets, i * sizeof(long));
        int* temp_keys = realloc(keys, i * sizeof(int));
        record* temp_recs = realloc(recs, i * sizeof(record));
        if (temp_offsets == NULL || temp_keys == NULL || temp_recs == NULL) {
            fprintf(stderr, "Error: Failed to resize arrays\n");
            free(offsets);
            free(keys);
            free(recs);
            return NULL;
        }
        offsets = temp_offsets;
        keys = temp_keys;
        recs = temp_recs;
    }

    // Find and print the largest integer in the array
    int max_key = -1;
    for (int j = 0; j < i; j++) {
        if (max_key == -1 || recs[j].val > recs[max_key].val) {
            max_key = j;
        }
    }
    printf("Largest integer: %d\n", recs[max_key].val);

    // Free memory for arrays and return success
    free(offsets);
    free(keys);
    free(recs);
    return &recs[0];
}
