#define MAXIMUM_PAYLOAD_SIZE 16384

typedef struct {
    MACHeader mac;
    IPAddressPacket ip;
} NetworkInterfaceStatistics;

void updateNetworkStatsUI(int *numEntries, int initialSize, int minPayloadSize, int maxPayloadSize) {
    // Initialize the array of network interface statistics
    NetworkInterfaceStatistics *stats = malloc(sizeof(NetworkInterfaceStatistics) * initialSize);
    assert(stats != NULL);

    // Initialize the total number of entries added
    *numEntries = 0;

    // Dynamically resize the array as needed
    while (*numEntries < initialSize) {
        int payloadSize = minPayloadSize + (rand() % (maxPayloadSize - minPayloadSize));
        NetworkInterfaceStatistics stat;
        stat.mac.checksum = 0;
        stat.ip.checksum = 0;
        stat.ip.payloadSize = payloadSize;
        for (int i = 0; i < payloadSize; i++) {
            stat.ip.payload[i] = rand() % 256;
        }
        // Calculate the checksum for the IP packet
        stat.ip.checksum = calculateChecksum(&stat.ip);
        stats[*numEntries] = stat;
        (*numEntries)++;
    }

    // Update the UI elements using the resource ID and URL
    for (int i = 0; i < *numEntries; i++) {
        NetworkInterfaceStatistics *stat = &stats[i];
        // Check if the element ID matches any of the IDs to update
        int idToUpdate = 0;
        for (int j = 0; j < numIdsToUpdate; j++) {
            if (stat->ip.id == idsToUpdate[j]) {
                idToUpdate = 1;
                break;
            }
        }
        // Send a message to the parent window with the element ID and updated value
        char *message = malloc(sizeof(char) * 20);
        assert(message != NULL);
        sprintf(message, "update_ui %d %lu", stat->ip.id, stat->ip.checksum);
        // If the message is successful, update the UI element with the new value
        if (parentWindow->sendMessage(message) == 0) {
            // Update the UI element with the new value
            parentWindow->updateUI(stat->ip.id, stat->ip.checksum);
        }
    }
}

int calculateChecksum(IPAddressPacket *packet) {
    int checksum = 0;
    // Calculate the checksum for the IP packet
    for (int i = 0; i < packet->payloadSize; i++) {
        checksum += packet->payload[i];
    }
    return checksum;
}
