struct network_stats {
    time_t timestamp;
    char *interface_name;
    unsigned long received_bytes;
    unsigned long transmitted_bytes;
    int packet_loss;
};

int init_network_stats(void) {
    // Initialize list of structures representing network interface statistics
    struct network_stats stats[10];
    for (int i = 0; i < 10; i++) {
        stats[i].timestamp = time(NULL);
        stats[i].interface_name = NULL;
        stats[i].received_bytes = 0;
        stats[i].transmitted_bytes = 0;
        stats[i].packet_loss = 0;
    }

    // Initialize logging system with configuration from settings file
    char *log_file = "/var/log/network_stats.log";
    int log_level = LOG_INFO;
    int log_rotation_size = 1024 * 1024 * 5; // 5 MB
    int log_retention_days = 7;
    syslog(LOG_NOTICE, "Initializing network statistics logging system");
    openlog("network_stats", LOG_PID | LOG_CONS, LOG_LOCAL0);

    // Start background monitoring of network traffic changes and dynamically update the statistics list
    pthread_t thread;
    pthread_create(&thread, NULL, monitor_network_traffic, stats);

    return 1;
}

void *monitor_network_traffic(struct network_stats *stats) {
    // Get list of interfaces from /proc/net/dev
    FILE *fp = fopen("/proc/net/dev", "r");
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        if (strncmp(line, "lo:", 3) == 0) {
            // Skip loopback interface
            continue;
        }
        char *interface_name = strtok(line, ":");
        struct network_stats *curr_stat = stats + i;
        curr_stat->interface_name = interface_name;
        int ret = get_network_stats(interface_name, &curr_stat->received_bytes, &curr_stat->transmitted_bytes);
        if (ret == 0) {
            syslog(LOG_WARNING, "Failed to get network statistics for interface %s", interface_name);
        }
    }
    fclose(fp);

    while (1) {
        // Sleep for 5 seconds and check if any new interfaces have been added or removed
        sleep(5);
        struct network_stats *curr_stat = stats;
        for (int i = 0; i < 10; i++) {
            char interface_name[256];
            snprintf(interface_name, sizeof(interface_name), "eth%d", i);
            if (get_network_stats(interface_name, &curr_stat->received_bytes, &curr_stat->transmitted_bytes) == 0) {
                // Interface has been added or removed, update statistics list
                curr_stat++;
            } else {
                curr_stat->timestamp = time(NULL);
                get_network_stats(interface_name, &curr_stat->received_bytes, &curr_stat->transmitted_bytes);
            }
        }
    }
}

int get_network_stats(char *interface_name, unsigned long *received_bytes, unsigned long *transmitted_bytes) {
    // Get network statistics for the specified interface using ioctl()
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        return -1;
    }
    struct ifreq ifr;
    strcpy(ifr.ifr_name, interface_name);
    if (ioctl(sock, SIOCGIFSTATS, &ifr) == 0) {
        *received_bytes = ifr.ifr_stat->rx_bytes;
        *transmitted_bytes = ifr.ifr_stat->tx_bytes;
        return 1;
    } else {
        close(sock);
        return -1;
    }
}
