#include <stdlib.h>
#include <stdio.h>
#include <string.h>

// Structure to store NIC statistics
typedef struct nic_statistics {
    char mac_header[6]; // MAC header
    char ip_packet[20]; // IP packet with payload size and checksum
} nic_statistics;

// Dynamic array of NIC statistics structures
nic_statistics* nic_stats = NULL;
size_t nic_stats_len = 0;

void init_nic_stats(size_t initial_capacity) {
    // Initialize the dynamic array with a default capacity
    nic_stats_len = initial_capacity;
    nic_stats = (nic_statistics*)malloc(sizeof(nic_statistics) * nic_stats_len);
}

void free_nic_stats() {
    // Free memory allocated to the dynamic array
    if (nic_stats != NULL) {
        free(nic_stats);
        nic_stats = NULL;
    }
}

void insert_nic_statistics(const char* mac_header, const char* ip_packet) {
    // Insert a new NIC statistics structure into the dynamic array
    if (nic_stats == NULL || nic_stats_len >= SIZE_MAX / sizeof(nic_statistics)) {
        return;
    }
    size_t index = nic_stats_len++;
    nic_stats[index].mac_header = (char*)malloc(6);
    memcpy(nic_stats[index].mac_header, mac_header, 6);
    nic_stats[index].ip_packet = (char*)malloc(20);
    memcpy(nic_stats[index].ip_packet, ip_packet, 20);
}

void delete_nic_statistics(size_t index) {
    // Delete a NIC statistics structure from the dynamic array
    if (index >= nic_stats_len || nic_stats == NULL) {
        return;
    }
    free(nic_stats[index].mac_header);
    free(nic_stats[index].ip_packet);
    nic_stats[index] = nic_stats[--nic_stats_len];
}
