Here is an example of how the Java function to compute the number of disjoint pairs of elements in an integer array using a Union-Find data structure could be implemented:
```java
import java.util.*;

public class DisjointPairs {
    public static int countDisjointPairs(int[] arr) {
        // Initialize Union-Find data structure with each element as its own set
        UnionFind uf = new UnionFind();
        for (int i = 0; i < arr.length; i++) {
            uf.addSet(i);
        }

        // Iterate over the array and union elements that are disjoint pairs
        int count = 0;
        for (int i = 0; i < arr.length - 1; i++) {
            if (arr[i] != arr[i + 1]) {
                int set1 = uf.findSet(i);
                int set2 = uf.findSet(i + 1);
                if (set1 != set2) {
                    count++;
                    uf.unionSets(set1, set2);
                }
            }
        }

        return count;
    }
}
