#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct CRCIndicationList {
    size_t capacity; // maximum number of elements in the list
    size_t count; // current number of elements in the list
    NFAPI_CRC_INDICATION_PDU_T* pdu[]; // dynamically allocated array of PDUs
} CRCIndicationList;

// initialize a new list with the given capacity
CRCIndicationList* crcIndicationListInit(size_t capacity) {
    CRCIndicationList* list = (CRCIndicationList*)malloc(sizeof(CRCIndicationList));
    if (!list) {
        return NULL; // out of memory
    }
    list->capacity = capacity;
    list->count = 0;
    list->pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * capacity);
    if (!list->pdu) {
        free(list);
        return NULL; // out of memory
    }
    return list;
}

// add a new PDU to the list, returns true on success and false otherwise
bool crcIndicationListAddPdu(CRCIndicationList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list || list->count >= list->capacity) {
        return false; // list is full or NULL pointer passed
    }
    list->pdu[list->count++] = pdu;
    return true;
}

// remove a PDU from the list, returns true on success and false otherwise
bool crcIndicationListRemovePdu(CRCIndicationList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list || list->count == 0) {
        return false; // list is empty or NULL pointer passed
    }
    size_t i = 0;
    while (i < list->count && list->pdu[i].RNTI != pdu.RNTI) {
        i++;
    }
    if (i == list->count) { // not found
        return false;
    }
    list->count--;
    memmove(&list->pdu[i], &list->pdu[i+1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->count - i));
    return true;
}

// check if a PDU is in the list, returns true if found and false otherwise
bool crcIndicationListContainsPdu(CRCIndicationList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list || list->count == 0) {
        return false; // list is empty or NULL pointer passed
    }
    size_t i = 0;
    while (i < list->count && list->pdu[i].RNTI != pdu.RNTI) {
        i++;
    }
    return i != list->count; // found if not equal to count
}

// get the number of PDUs in the list
size_t crcIndicationListGetCount(CRCIndicationList* list) {
    if (!list) {
        return 0; // NULL pointer passed
    }
    return list->count;
}

// get a copy of the PDU at the given index, returns NULL on failure
NFAPI_CRC_INDICATION_PDU_T* crcIndicationListGetPdu(CRCIndicationList* list, size_t index) {
    if (!list || index >= list->count) {
        return NULL; // out of range or NULL pointer passed
    }
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        return NULL; // out of memory
    }
    *pdu = list->pdu[index];
    return pdu;
}

// free the memory allocated by crcIndicationListInit, crcIndicationListAddPdu and crcIndicationListGetPdu
void crcIndicationListFree(CRCIndicationList* list) {
    if (!list) {
        return; // NULL pointer passed
    }
    free(list->pdu);
    free(list);
}

// thread-safe access to the list using locks, ensuring thread safety and efficient performance under high-frequency data processing conditions
void crcIndicationListAddPduLocked(CRCIndicationList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);
    if (crcIndicationListAddPdu(list, pdu)) {
        pthread_cond_signal(&list->cond);
    }
    pthread_mutex_unlock(&list->lock);
}

void crcIndicationListRemovePduLocked(CRCIndicationList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);
    if (crcIndicationListRemovePdu(list, pdu)) {
        pthread_cond_signal(&list->cond);
    }
    pthread_mutex_unlock(&list->lock);
}

void crcIndicationListContainsPduLocked(CRCIndicationList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);
    bool result = crcIndicationListContainsPdu(list, pdu);
    pthread_mutex_unlock(&list->lock);
}

size_t crcIndicationListGetCountLocked(CRCIndicationList* list) {
    pthread_mutex_lock(&list->lock);
    size_t count = crcIndicationListGetCount(list);
    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T* crcIndicationListGetPduLocked(CRCIndicationList* list, size_t index) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T* pdu = crcIndicationListGetPdu(list, index);
    pthread_mutex_unlock(&list->lock);
}

// initialize the list with a lock and condition variable for thread-safe access
CRCIndicationList* crcIndicationListInitLocked() {
    CRCIndicationList* list = (CRCIndicationList*)malloc(sizeof(CRCIndicationList));
    if (!list) {
        return NULL; // out of memory
    }
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond, NULL);
    return list;
}

// free the lock and condition variable allocated by crcIndicationListInitLocked
void crcIndicationListFreeLocked(CRCIndicationList* list) {
    if (!list) {
        return; // NULL pointer passed
    }
    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->cond);
}']

