// Define the storage volume management structure
typedef struct {
    int fd; // File descriptor
    size_t block_size; // Block size
    off_t file_offset; // File offset
    char access_pattern[16]; // Access pattern (e.g., "read", "write")
} SVMMetadata;

// Define the dynamic array of storage volume management structures
typedef struct {
    SVMMetadata* metadata; // Pointer to an array of SVM metadata structures
    size_t count; // Number of elements in the array
    size_t capacity; // Capacity of the array (number of elements that can be stored)
} SVMArray;

// Initialize a dynamic array of storage volume management structures
void init_svm_array(SVMArray* array, size_t capacity) {
    // Allocate memory for the array and its metadata
    array->metadata = malloc(capacity * sizeof(SVMMetadata));
    assert(array->metadata != NULL);
    array->count = 0;
    array->capacity = capacity;
}

// Add a new storage volume management structure to the dynamic array
void add_svm(SVMArray* array, int fd, size_t block_size, off_t file_offset, char access_pattern) {
    // Check if the array is full and needs to be resized
    if (array->count == array->capacity) {
        // Double the capacity of the array
        array->capacity *= 2;
        array->metadata = realloc(array->metadata, array->capacity * sizeof(SVMMetadata));
        assert(array->metadata != NULL);
    }

    // Add the new storage volume management structure to the array
    array->metadata[array->count].fd = fd;
    array->metadata[array->count].block_size = block_size;
    array->metadata[array->count].file_offset = file_offset;
    strcpy(array->metadata[array->count].access_pattern, access_pattern);
    array->count++;
}

// Remove a storage volume management structure from the dynamic array
void remove_svm(SVMArray* array, size_t index) {
    // Check if the given index is valid
    assert(index < array->count);

    // Shift all elements after the specified index to the left by one position
    for (size_t i = index; i < array->count - 1; i++) {
        array->metadata[i] = array->metadata[i + 1];
    }

    // Decrement the number of elements in the array
    array->count--;
}

// Validate the consistency of file offsets and block sizes upon insertion into the array
void validate_svm(SVMArray* array, size_t index) {
    // Check if the given index is valid
    assert(index < array->count);

    // Get the current storage volume management structure
    SVMMetadata* metadata = &array->metadata[index];

    // Validate the file offset and block size
    if (metadata->file_offset % metadata->block_size != 0) {
        fprintf(stderr, "Invalid file offset: %lld (must be a multiple of block size %zu)\n", metadata->file_offset, metadata->block_size);
        exit(1);
    }
}

// Deallocate the memory used by the dynamic array of storage volume management structures
void free_svm_array(SVMArray* array) {
    free(array->metadata);
}
