// Function to manage the dynamically allocated array of NFAPI_CRC_INDICATION_PDU structures
void manageNFAPICRCIndicationPDU(int numElements, int maxNumElements) {
    // Initialize the array with a maximum size of 1000 elements
    static NFAPI_CRC_INDICATION_PDU_T *array = malloc(maxNumElements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
        printf("Error: Failed to allocate memory for the array\n");
        return;
    }

    // If the number of elements is greater than the current size of the array, resize it
    if (numElements > maxNumElements) {
        int newSize = numElements * 2;
        NFAPI_CRC_INDICATION_PDU_T *newArray = realloc(array, newSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (newArray == NULL) {
            printf("Error: Failed to resize the array\n");
            return;
        }
        array = newArray;
        maxNumElements = newSize;
    }

    // Iterate through each element in the array and validate the RNTI values using an external data source
    for (int i = 0; i < numElements; i++) {
        int rnti = array[i].RNTI;
        bool validRNTI = validateRNTI(rnti);
        if (!validRNTI) {
            // If the RNTI is not valid, remove it from the array and adjust the count accordingly
            memmove(&array[i], &array[i + 1], (maxNumElements - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            numElements--;
            maxNumElements--;
        }
    }

    // If the number of unique RNTI values is greater than 500, remove the extra elements from the array
    if (getUniqueRNTICount(array, numElements) > 500) {
        int numToRemove = getUniqueRNTICount(array, numElements) - 500;
        for (int i = 0; i < numToRemove; i++) {
            memmove(&array[i], &array[i + 1], (maxNumElements - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            numElements--;
            maxNumElements--;
        }
    }

    // Free the memory allocated for the array when it is no longer needed
    if (numElements == 0) {
        free(array);
        array = NULL;
    }
}

// Function to validate an RNTI value using an external data source
bool validateRNTI(int rnti) {
    // Use a live database to validate the RNTI value
    bool valid = true;
    // Implement a fallback mechanism if validation fails due to delay in response from external data source
    while (valid && !validateRNTIFallback(rnti)) {
        sleep(1);
        valid = validateRNTI(rnti);
    }
    return valid;
}

// Function to get the count of unique RNTI values in an array
int getUniqueRNTICount(NFAPI_CRC_INDICATION_PDU_T *array, int numElements) {
    // Use a hash table to keep track of the unique RNTI values
    static char **hashTable = NULL;
    if (hashTable == NULL) {
        hashTable = malloc(numElements * sizeof(char*));
        memset(hashTable, 0, numElements * sizeof(char*));
    }

    int count = 0;
    for (int i = 0; i < numElements; i++) {
        char *rntiString = malloc(10 * sizeof(char)); // Assumes an RNTI value is at most 10 characters long
        sprintf(rntiString, "%d", array[i].RNTI);
        if (!strcmp(hashTable[array[i].RNTI], rntiString)) {
            count++;
        } else {
            hashTable[array[i].RNTI] = rntiString;
        }
    }
    return count;
}

// Function to clear the list when no longer needed, ensuring all resources are freed properly
void clearNFAPICRCIndicationPDUList(NFAPI_CRC_INDICATION_PDU_T *array) {
    // Free the memory allocated for the array and hash table
    if (array != NULL) {
        free(array);
        array = NULL;
    }
}
