#define DEFAULT_ARRAY_SIZE 1024
#define MAX_PAYLOAD_SIZE 65535
#define MAX_CHECKSUM_SIZE 16

typedef struct NetworkInterfaceControlStatistics {
    uint8_t macHeader[6];
    uint8_t ipPacket[MAX_PAYLOAD_SIZE + 20]; // IP header size is 20 bytes
    uint16_t checksum;
    bool tcpHeaderPresent;
    struct NetworkInterfaceControlStatistics* next;
} NetworkInterfaceControlStatistics;

typedef struct NetworkInterfaceControlStatisticsList {
    NetworkInterfaceControlStatistics* head;
    size_t size;
} NetworkInterfaceControlStatisticsList;

// Initializes a dynamic array of Network Interface Control (NIC) statistics structures.
void initializeNetworkInterfaceControlStatistics(NetworkInterfaceControlStatisticsList* list, size_t initialSize) {
    // Allocate memory for the list header and set its size to 0.
    list->head = NULL;
    list->size = 0;

    // Allocate memory for the first block of statistics structures.
    NetworkInterfaceControlStatistics* current = malloc(sizeof(NetworkInterfaceControlStatistics) * initialSize);
    if (current == NULL) {
        printf("Failed to allocate memory for the first block of statistics structures.\n");
        exit(-1);
    }

    // Set the head of the list to point to the first block.
    list->head = current;

    // Initialize each structure in the block with a MAC header and an IP packet.
    for (size_t i = 0; i < initialSize; ++i) {
        NetworkInterfaceControlStatistics* stats = &current[i];

        // Set the MAC header to all zeros.
        memset(stats->macHeader, 0, 6);

        // Generate a random payload size and checksum.
        uint16_t payloadSize = rand() % MAX_PAYLOAD_SIZE;
        uint16_t checksum = generateChecksum();

        // Set the IP packet to contain the payload and checksum.
        memset(stats->ipPacket, 0, sizeof(uint8_t) * (payloadSize + 20));
        stats->ipPacket[0] = 0x45; // Version and header length are set to 0x45.
        stats->ipPacket[1] = 0x00; // Type of service is set to 0x00.
        stats->ipPacket[2] = payloadSize >> 8; // Total length is set to the payload size plus the header length (20 bytes).
        stats->ipPacket[3] = payloadSize & 0xFF;
        stats->ipPacket[4] = 0x00; // Identification is set to 0.
        stats->ipPacket[5] = 0x06; // Flags and fragment offset are set to 0x06 (don't fragment).
        stats->ipPacket[6] = 0x00; // Time to live is set to 0.
        stats->ipPacket[7] = 0x11; // Protocol is set to UDP (17).
        stats->ipPacket[8] = 0x00; // Header checksum is set to 0.
        stats->checksum = checksum;

        // Set the optional TCP header if needed.
        if (stats->tcpHeaderPresent) {
            // Set the source and destination port numbers to random values.
            stats->ipPacket[9] = rand() % 65535;
            stats->ipPacket[10] = rand() % 65535;

            // Set the sequence number to a random value.
            stats->ipPacket[11] = rand() & 0xFF;
            stats->ipPacket[12] = (rand() >> 8) & 0xFF;
            stats->ipPacket[13] = (rand() >> 16) & 0xFF;
            stats->ipPacket[14] = rand() >> 24;

            // Set the acknowledgement number to a random value.
            stats->ipPacket[15] = rand() & 0xFF;
            stats->ipPacket[16] = (rand() >> 8) & 0xFF;
            stats->ipPacket[17] = (rand() >> 16) & 0xFF;
            stats->ipPacket[18] = rand() >> 24;

            // Set the data offset to 5 (i.e., the TCP header is present).
            stats->ipPacket[19] = 0x50;
        } else {
            // Set the data offset to 0 (i.e., no TCP header).
            stats->ipPacket[19] = 0x40;
        }
    }

    // Set the size of the list to the initial size.
    list->size = initialSize;
}

// Adds a new block of statistics structures to the dynamic array.
void addBlockToNetworkInterfaceControlStatistics(NetworkInterfaceControlStatisticsList* list) {
    // Allocate memory for the new block.
    NetworkInterfaceControlStatistics* current = malloc(sizeof(NetworkInterfaceControlStatistics) * DEFAULT_ARRAY_SIZE);
    if (current == NULL) {
        printf("Failed to allocate memory for the new block of statistics structures.\n");
        exit(-1);
    }

    // Set the next pointer of the last structure in the previous block to point to the first structure in the new block.
    NetworkInterfaceControlStatistics* prev = list->head;
    for (size_t i = 0; i < list->size - 1; ++i) {
        prev[i].next = &current[i];
    }

    // Set the head of the list to point to the new block.
    list->head = current;

    // Increment the size of the list by the default block size.
    list->size += DEFAULT_ARRAY_SIZE;
}

// Resizes the dynamic array to fit a given number of statistics structures.
void resizeNetworkInterfaceControlStatistics(NetworkInterfaceControlStatisticsList* list, size_t newSize) {
    // If the new size is smaller than the current size, remove excess blocks.
    while (list->size > newSize && list->head != NULL) {
        addBlockToNetworkInterfaceControlStatistics(list);
    }

    // If the new size is larger than the current size, add new blocks.
    while (list->size < newSize) {
        addBlockToNetworkInterfaceControlStatistics(list);
    }
}

// Validates a given number of statistics structures against the dynamic array.
void validateNumberOfNetworkInterfaceControlStatistics(NetworkInterfaceControlStatisticsList* list, size_t numStats) {
    // If the number of statistics is valid, return.
    if (numStats <= list->size) {
        return;
    }

    // Otherwise, resize the array to fit the new number of statistics.
    resizeNetworkInterfaceControlStatistics(list, numStats);
}

// Validates a given block index against the dynamic array.
void validateBlockIndexOfNetworkInterfaceControlStatistics(NetworkInterfaceControlStatisticsList* list, size_t blockIndex) {
    // If the block index is valid, return.
    if (blockIndex < list->size) {
        return;
    }

    // Otherwise, resize the array to fit the new number of blocks.
    resizeNetworkInterfaceControlStatistics(list, blockIndex + 1);
}

// Validates a given statistics index against the dynamic array.
void validateStatisticsIndexOfNetworkInterfaceControlStatistics(NetworkInterfaceControlStatisticsList* list, size_t statisticsIndex) {
    // If the statistics index is valid, return.
    if (statisticsIndex < list->size) {
        return;
    }

    // Otherwise, resize the array to fit the new number of statistics.
    resizeNetworkInterfaceControlStatistics(list, statisticsIndex + 1);
}
