struct LTE_RRC_NAS_MESSAGE_queue {
    struct LTE_RRC_NAS_MESSAGE *head;
    struct LTE_RRC_NAS_MESSAGE *tail;
};

typedef struct LTE_RRC_NAS_MESSAGE_queue LTE_RRC_NAS_MESSAGE_queue;

struct LTE_RRC_NAS_MESSAGE {
    RRC_MESSAGE_TYPE messageType;
    NAS_MESSAGE *message;
    NAS_TRANSACTION_ID transactionId;
};

typedef struct LTE_RRC_NAS_MESSAGE LTE_RRC_NAS_MESSAGE;

struct LTE_RRC_NAS_MESSAGE_queue *LTE_RRC_NAS_MESSAGE_queue_create() {
    struct LTE_RRC_NAS_MESSAGE_queue *queue = malloc(sizeof(struct LTE_RRC_NAS_MESSAGE_queue));
    queue->head = NULL;
    queue->tail = NULL;
}

void LTE_RRC_NAS_MESSAGE_queue_destroy(struct LTE_RRC_NAS_MESSAGE_queue *queue) {
    struct LTE_RRC_NAS_MESSAGE *message = queue->head;
    while (message != NULL) {
        struct LTE_RRC_NAS_MESSAGE *nextMessage = message->next;
        free(message);
        message = nextMessage;
    }
    free(queue);
}

void LTE_RRC_NAS_MESSAGE_queue_enqueue(struct LTE_RRC_NAS_MESSAGE_queue *queue, struct LTE_RRC_NAS_MESSAGE *message) {
    if (queue->head == NULL) {
        queue->head = message;
        queue->tail = message;
    } else {
        queue->tail->next = message;
        queue->tail = message;
    }
}

struct LTE_RRC_NAS_MESSAGE *LTE_RRC_NAS_MESSAGE_queue_dequeue(struct LTE_RRC_NAS_MESSAGE_queue *queue) {
    struct LTE_RRC_NAS_MESSAGE *message = queue->head;
    if (message != NULL) {
        queue->head = message->next;
        if (queue->head == NULL) {
            queue->tail = NULL;
        }
    }
    return message;
}

int LTE_RRC_NAS_MESSAGE_process(struct LTE_RRC_NAS_MESSAGE *message, pthread_mutex_t *mutex) {
    int ret = 0;
    switch (message->messageType) {
        case RRC_MESSAGE_TYPE_CONNECT:
            // Handle connection establishment
            break;
        case RRC_MESSAGE_TYPE_DISCONNECT:
            // Handle disconnection
            break;
        case RRC_MESSAGE_TYPE_SEND:
            // Send message to the network
            ret = sendMessage(message->transactionId, message->message);
            break;
        case RRC_MESSAGE_TYPE_RECEIVE:
            // Handle received message from the network
            break;
        default:
            printf("Invalid LTE_RRC_NAS_MESSAGE type\n");
            ret = 0;
    }
    return ret;
}

void *LTE_RRC_NAS_message_handler(void *args) {
    struct LTE_RRC_NAS_MESSAGE_queue *queue = (struct LTE_RRC_NAS_MESSAGE_queue *) args;
    while (1) {
        pthread_mutex_lock(mutex);
        struct LTE_RRC_NAS_MESSAGE *message = LTE_RRC_NAS_MESSAGE_queue_dequeue(queue);
        if (message != NULL) {
            int ret = LTE_RRC_NAS_MESSAGE_process(message, mutex);
            if (ret == 0) {
                printf("Error processing LTE_RRC_NAS_MESSAGE\n");
                // Handle error here
            }
        } else {
            pthread_mutex_unlock(mutex);
            break;
        }
        pthread_mutex_unlock(mutex);
    }
}
