2. Java function for checking disjoint pairs of elements in an integer array:
```java
import java.util.*;

public class DisjointPairs {
    public static int countDisjointPairs(int[] arr) {
        // Initialize a union-find data structure to keep track of connected components
        UnionFind uf = new UnionFind();

        // Iterate over the array and check for disjoint pairs
        int num_disjoint_pairs = 0;
        for (int i = 0; i < arr.length - 1; i++) {
            if (!uf.connected(arr[i], arr[i + 1])) {
                num_disjoint_pairs++;
            }
            uf.union(arr[i], arr[i + 1]);
        }
        return num_disjoint_pairs;
    }
}
