    public static void monitor(int num_nics) {
        // Authenticate with Google Cloud Platform
        GoogleCredential credential = GoogleCredential.getApplicationDefault().createScoped(Arrays.asList(CLOUD_MONITORING_SCOPE));

        // Create a client for the Monitoring API
        MetricServiceClient metricClient = new MetricServiceClient.Builder()
            .setProjectId(PROJECT_ID)
            .build();

        // Define a custom metric
        Metric metric = Metric.newBuilder()
            .setName("network_throughput")
            .setDescription("Network throughput metric")
            .build();

        // Set up monitoring for the custom metric
        MonitoredResource resource = MonitoredResource.newBuilder()
            .setType("gce_instance")
            .setLabels(Collections.singletonMap("project_id", PROJECT_ID))
            .build();

        // Create a time series for the custom metric
        TimeSeries series = TimeSeries.newBuilder()
            .setMetricKind(MetricKind.GAUGE)
            .setValueType(ValueType.DOUBLE)
            .addPoints(Point.newBuilder().setInterval(Interval.newBuilder().setEndTime(Timestamp.now())).setValue(Value.newBuilder().setDoubleValue(num_nics)))
            .build();

        // Send the time series to the Monitoring API
        metricClient.createTimeSeries(Collections.singletonList(series), resource, metric);
    }
}
