// Define the record structure
typedef struct {
    long offset;
    int key;
} Record;

// Function to manage memory for a configurable number of record structures
int initialize_records(int *keys, long *offsets, int num_records) {
    // Check input parameters
    if (keys == NULL || offsets == NULL || num_records < 0) {
        return -1;
    }

    // Calculate the total number of bytes needed for allocation
    size_t num_bytes = sizeof(Record) * num_records;

    // Allocate memory for the record structures
    Record *records = malloc(num_bytes);

    if (records == NULL) {
        return -2;
    }

    // Initialize each record structure with a random key and offset from the arrays
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].key = keys[rand() % (sizeof(keys) / sizeof(*keys))];
        records[i].offset = offsets[rand() % (sizeof(offsets) / sizeof(*offsets))];
    }

    // Free the memory allocated for the input arrays
    free(keys);
    free(offsets);

    return 0;
}
```
