#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include "nfapi_crc_indication_pdu.h"

// Custom allocator for memory efficiency and thread-safe allocation
void* nfapi_alloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        printf("ERROR: Failed to allocate memory\n");
        return NULL;
    }
    memset(ptr, 0, size);
    return ptr;
}

// Custom free function for thread-safe deallocation of NFAPI_CRC_INDICATION_PDUs
void nfapi_free(NFAPI_CRC_INDICATION_PDU* pdu) {
    if (pdu == NULL) return;
    // Check if the CRCFLAG is set, indicating that the PDU has been allocated by this function.
    if ((pdu->flags & NFAPI_CRC_INDICATION_PDU_ALLOCATED) != 0) {
        free(pdu);
        return;
    }
    // If the CRCFLAG is not set, indicate that the PDU was allocated by an external source.
    pdu->flags |= NFAPI_CRC_INDICATION_PDU_EXTERNAL_SOURCE;
}

// Function to manage a dynamically resizable list of NFAPI_CRC_INDICATION_PDUs
NFAPI_CRC_INDICATION_PDU* nfapi_crc_indication_list(void) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    // Create the list of NFAPI_CRC_INDICATION_PDUs and initialize its size to 0.
    NFAPI_CRC_INDICATION_PDU* list = NULL;
    int size = 0;

    // Function to add a new PDU to the list
    void nfapi_crc_indication_add(NFAPI_CRC_INDICATION_PDU* pdu) {
        pthread_mutex_lock(&mutex);
        // Check if the list is full and needs to be resized.
        if (size >= NFAPI_CRC_INDICATION_MAX_SIZE) {
            // Reallocate the list with a larger size.
            int new_size = size * 2;
            NFAPI_CRC_INDICATION_PDU* new_list = nfapi_alloc(new_size * sizeof(NFAPI_CRC_INDICATION_PDU));
            memcpy(new_list, list, size * sizeof(NFAPI_CRC_INDICATION_PDU));
            free(list);
            list = new_list;
        }
        // Add the PDU to the list.
        list[size++] = pdu;
        pthread_mutex_unlock(&mutex);
    }

    // Function to remove a PDU from the list and deallocate it if necessary.
    void nfapi_crc_indication_remove(NFAPI_CRC_INDICATION_PDU* pdu) {
        pthread_mutex_lock(&mutex);
        // Search for the PDU in the list and remove it.
        int i;
        for (i = 0; i < size; ++i) {
            if (list[i] == pdu) break;
        }
        if (i < size) {
            // If the PDU is found, deallocate it if necessary.
            if ((pdu->flags & NFAPI_CRC_INDICATION_PDU_ALLOCATED) != 0) nfapi_free(pdu);
            // Shift the remaining elements in the list to fill the gap.
            for (int j = i; j < size - 1; ++j) {
                list[j] = list[j + 1];
            }
            --size;
        }
        pthread_mutex_unlock(&mutex);
    }

    // Function to search for a PDU in the list and return it if found.
    NFAPI_CRC_INDICATION_PDU* nfapi_crc_indication_find(RX_UE_INFORMATION_TAG rxUeInformationTag, RNTI rnti, CRC_INDICATION_REL8_TAG crcIndicationRel8Tag) {
        pthread_mutex_lock(&mutex);
        // Search for the PDU in the list.
        int i;
        for (i = 0; i < size; ++i) {
            if (list[i]->rxUeInformationTag == rxUeInformationTag && list[i]->rnti == rnti && list[i]->crcIndicationRel8Tag == crcIndicationRel8Tag) break;
        }
        // If the PDU is found, return it.
        if (i < size) {
            pthread_mutex_unlock(&mutex);
            return list[i];
        }
        // If the PDU is not found, return NULL.
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Function to return the size of the list.
    int nfapi_crc_indication_size(void) {
        pthread_mutex_lock(&mutex);
        int result = size;
        pthread_mutex_unlock(&mutex);
        return result;
    }

    // Function to clear the list and free all PDUs.
    void nfapi_crc_indication_clear(void) {
        pthread_mutex_lock(&mutex);
        for (int i = 0; i < size; ++i) {
            if ((list[i]->flags & NFAPI_CRC_INDICATION_PDU_ALLOCATED) != 0) nfapi_free(list[i]);
        }
        free(list);
        list = NULL;
        size = 0;
        pthread_mutex_unlock(&mutex);
    }

    // Function to wait for new PDUs and handle them.
    void nfapi_crc_indication_wait(void) {
        while (true) {
            pthread_mutex_lock(&mutex);
            // Check if the list is empty.
            if (size == 0) {
                // Wait for new PDUs to be added.
                pthread_cond_wait(&cond, &mutex);
            } else {
                // Handle the first PDU in the list and remove it.
                nfapi_crc_indication_handle(list[0]);
                nfapi_crc_indication_remove(list[0]);
            }
            pthread_mutex_unlock(&mutex);
        }
    }

    // Function to handle a PDU and update the list accordingly.
    void nfapi_crc_indication_handle(NFAPI_CRC_INDICATION_PDU* pdu) {
        // Update the list if necessary.
        pthread_mutex_lock(&mutex);
        // Search for the PDU in the list.
        int i;
        for (i = 0; i < size; ++i) {
            if (list[i] == pdu) break;
        }
        // If the PDU is found, remove it from the list.
        if (i < size) {
            nfapi_crc_indication_remove(pdu);
        } else {
            // If the PDU is not found, add it to the list.
            nfapi_crc_indication_add(pdu);
        }
        pthread_mutex_unlock(&mutex);
    }
}

