};

// Function to create a new thread that waits for new PDUs and handles them.
struct nfapi_crc_indication_thread* nfapi_crc_indication_create_thread(void) {
    // Allocate memory for the thread structure.
    struct nfapi_crc_indication_thread* thread = malloc(sizeof(struct nfapi_crc_indication_thread));
    if (!thread) return NULL;
    // Initialize the list of PDUs.
    thread->list.size = 0;
    for (int i = 0; i < NFAPI_CRC_INDICATION_MAX_PDU; ++i) {
        thread->list.pdu[i] = NULL;
    }
    // Create the thread.
    pthread_create(&thread->id, NULL, nfapi_crc_indication_wait_and_handle, (void*)thread);
    return thread;
}

// Function to destroy a thread that waits for new PDUs and handles them.
void nfapi_crc_indication_destroy_thread(struct nfapi_crc_indication_thread* thread) {
    // Join the thread.
    pthread_join(thread->id, NULL);
    // Free the memory for the list of PDUs.
    for (int i = 0; i < NFAPI_CRC_INDICATION_MAX_PDU; ++i) {
        if (thread->list.pdu[i]) free(thread->list.pdu[i]);
    }
    // Free the memory for the thread structure.
    free(thread);
}

// Function to add a PDU to the list.
