    // Check if there is space in the list.
    if (nfapi_crc_indication_list.size == NFAPI_CRC_INDICATION_MAX_PDU) {
        // If not, remove the oldest PDU from the list.
        struct nfapi_crc_indication_pdu* to_free = nfapi_crc_indication_list.pdu[0];
        for (int i = 1; i < NFAPI_CRC_INDICATION_MAX_PDU; ++i) {
            nfapi_crc_indication_list.pdu[i - 1] = nfapi_crc_indication_list.pdu[i];
        }
        // Free the memory for the PDU.
        free(to_free);
    } else {
        // If there is space, add the PDU to the end of the list.
        nfapi_crc_indication_list.pdu[nfapi_crc_indication_list.size] = pdu;
    }
    // Increment the size of the list.
    nfapi_crc_indication_list.size += 1;
    // Unlock the mutex.
    pthread_mutex_unlock(&nfapi_crc_indication_list.mutex);
}

// Function to remove a PDU from the list.
void nfapi_crc_indication_remove(struct nfapi_crc_indication_pdu* pdu) {
