    off_t file_size;
    time_t last_modified_time;
} file_metadata_t;

int manage_memory(char** filenames, off_t* sizes, time_t* timestamps, int num_structs, configuration_t* config) {
    if (num_structs <= 0 || num_structs > config->max_allocations) {
        return -1;
    }

    // Calculate total size of memory needed for file metadata structures
    size_t mem_size = sizeof(file_metadata_t) * num_structs;

    // Allocate memory for the file metadata structures
    file_metadata_t* metadata = malloc(mem_size);
    if (metadata == NULL) {
        return -1;
    }

    // Initialize the file metadata structures randomly from the arrays of filenames, sizes, and timestamps
    for (int i = 0; i < num_structs; i++) {
        int rand_index = rand() % config->num_filenames;
        metadata[i].filename = strdup(filenames[rand_index]);
        metadata[i].file_size = sizes[rand_index];
        metadata[i].last_modified_time = timestamps[rand_index];
    }

    // Clean up and return
    free(metadata);
    return 0;
}
