```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Struct to represent a record
typedef struct Record {
    long offset;
    int key;
    char* identifier;
} Record;

// Struct to represent the collection of records
typedef struct Records {
    int size; // number of records in the collection
    Record** records; // array of pointers to records
} Records;

// Initialize a new record
void init_record(Record* record, long offset, int key, char* identifier) {
    record->offset = offset;
    record->key = key;
    record->identifier = (char*)malloc(strlen(identifier) + 1);
    strcpy(record->identifier, identifier);
}

// Add a new record to the collection
void add_record(Records* records, long offset, int key, char* identifier) {
    // Check if there is enough space for a new record
    if (records->size >= 10 * 1000 * 1000) { // 10 million records
        fprintf(stderr, "Reached maximum number of records\n");
        return;
    }

    // Allocate memory for the new record
    Record* new_record = (Record*)malloc(sizeof(Record));
    init_record(new_record, offset, key, identifier);

    // Add the new record to the collection
    records->records[records->size] = new_record;
    records->size++;
}

// Serialize the collection into a binary file
void serialize(Records* records, const char* filename) {
    FILE* fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file\n");
        return;
    }

    // Write the number of records to the file
    int num_records = records->size;
    fwrite(&num_records, sizeof(int), 1, fp);

    // Iterate over each record and write its fields to the file
    for (int i = 0; i < num_records; i++) {
        Record* record = records->records[i];
        fwrite(&record->offset, sizeof(long), 1, fp);
        fwrite(&record->key, sizeof(int), 1, fp);
        fwrite(record->identifier, strlen(record->identifier) + 1, 1, fp);
    }

    // Close the file
    fclose(fp);
}

// Deserialize the collection from a binary file
void deserialize(Records* records, const char* filename) {
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file\n");
        return;
    }

    // Read the number of records from the file
    int num_records;
    fread(&num_records, sizeof(int), 1, fp);

    // Initialize the collection with the number of records read from the file
    init_records(records, num_records);

    // Iterate over each record and read its fields from the file
    for (int i = 0; i < num_records; i++) {
        Record* record = records->records[i];
        fread(&record->offset, sizeof(long), 1, fp);
        fread(&record->key, sizeof(int), 1, fp);
        record->identifier = (char*)malloc(sizeof(char) * (strlen(record->identifier) + 1));
        fread(record->identifier, strlen(record->identifier) + 1, 1, fp);
    }

    // Close the file
    fclose(fp);
}

// Iterate over each record in the collection in forward order
void iterate_forward(Records* records, void (*callback)(Record*, void*), void* user_data) {
    for (int i = 0; i < records->size; i++) {
        Record* record = records->records[i];
        callback(record, user_data);
    }
}

// Iterate over each record in the collection in backward order
void iterate_backward(Records* records, void (*callback)(Record*, void*), void* user_data) {
    for (int i = records->size - 1; i >= 0; i--) {
        Record* record = records->records[i];
        callback(record, user_data);
    }
}
