        records[index].key = key;
        records[index].value = value;
        records[index].status = status;
    } else {
        records = (Record*)realloc(records, (num_records + 1) * sizeof(Record));
        records[index].key = key;
        records[index].value = value;
        records[index].status = status;
    }
