#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    long offset;
    int key;
} Record;

// Define the service state structure
typedef struct {
    int initialized; // Whether the service is currently running
    pthread_mutex_t mutex; // Mutex for synchronizing access to the service state
    int memoryLimit; // Maximum amount of memory allowed per batch (in bytes)
    int recordCount; // Number of records currently in the pipeline
    Record *records; // Array of records in the pipeline
} ServiceState;

// Initialize the service state
void initServiceState(ServiceState *state, int memoryLimit) {
    state->initialized = 0;
    pthread_mutex_init(&state->mutex, NULL);
    state->memoryLimit = memoryLimit;
    state->recordCount = 0;
    state->records = NULL;
}

// Add a record to the pipeline
void addRecord(ServiceState *state, long offset, int key) {
    pthread_mutex_lock(&state->mutex);

    // Check if there is enough memory available for the new record
    if (state->recordCount >= state->memoryLimit / sizeof(Record)) {
        printf("Not enough memory to add another record. Memory limit exceeded.\n");
        pthread_mutex_unlock(&state->mutex);
        return;
    }

    // Allocate memory for the new record
    state->records = realloc(state->records, (state->recordCount + 1) * sizeof(Record));
    if (!state->records) {
        printf("Memory allocation failed. Could not add new record.\n");
        pthread_mutex_unlock(&state->mutex);
        return;
    }

    // Initialize the new record and increment the record count
    state->records[state->recordCount].offset = offset;
    state->records[state->recordCount].key = key;
    state->recordCount++;

    pthread_mutex_unlock(&state->mutex);
}

// Start the data processing service
void startService(ServiceState *state) {
    if (!state->initialized) {
        printf("The service is not initialized. Call initService() first.\n");
        return;
    }

    // Start a new thread to process the records
    pthread_t thread;
    pthread_create(&thread, NULL, processRecords, state);
}

// Stop the data processing service
void stopService(ServiceState *state) {
    if (!state->initialized) {
        printf("The service is not initialized. Call initService() first.\n");
        return;
    }

    // Signal the thread to terminate and wait for it to exit
    pthread_cancel(thread);
    pthread_join(thread, NULL);

    // Release all resources used by the service
    free(state->records);
    state->initialized = 0;
}

// Function to be executed by each thread to process the records
void *processRecords(void *args) {
    ServiceState *state = (ServiceState *) args;

    // Process all records in the pipeline
    for (int i = 0; i < state->recordCount; i++) {
        // Do some processing here...

        // Send a status update to the monitoring system
        sendStatusUpdate(state);
    }

    return NULL;
}

// Function to send a status update to the monitoring system
void sendStatusUpdate(ServiceState *state) {
    // Log the event synchronously after processing is complete
    printf("Data processing completed. %d records processed.\n", state->recordCount);
}
```
