// Custom data structure for storing information about a network device
typedef struct {
    int id; // Unique identifier for the device
    char *supported_protocols; // List of supported protocols
    int bandwidth_limit; // Configurable bandwidth limit
} network_device_t;

// Linked list node for storing information about a network device
typedef struct {
    network_device_t data; // Data stored in the node
    struct node *next; // Pointer to the next node in the linked list
} node_t;

// Linked list for storing information about all network devices
node_t *head = NULL;

// Function for initializing a linked list of network device configurations
void init_network_devices(int num_devices) {
    int i;
    for (i = 0; i < num_devices; i++) {
        node_t *new_node = malloc(sizeof(node_t));
        new_node->data.id = i + 1;
        new_node->data.supported_protocols = "ethernet, wifi";
        new_node->data.bandwidth_limit = 10000; // 10 MB/s
        new_node->next = head;
        head = new_node;
    }
}

// Function for updating the supported protocols and bandwidth limits of a network device
void update_device(int id, char *supported_protocols, int bandwidth_limit) {
    node_t *current = head;
    while (current != NULL) {
        if (current->data.id == id) {
            current->data.supported_protocols = supported_protocols;
            current->data.bandwidth_limit = bandwidth_limit;
            break;
        }
        current = current->next;
    }
}

// Function for adding a new network device to the linked list
void add_device(int id, char *supported_protocols, int bandwidth_limit) {
    node_t *new_node = malloc(sizeof(node_t));
    new_node->data.id = id;
    new_node->data.supported_protocols = supported_protocols;
    new_node->data.bandwidth_limit = bandwidth_limit;
    new_node->next = head;
    head = new_node;
}

// Function for removing a network device from the linked list by ID
void remove_device(int id) {
    node_t *current = head;
    node_t *previous = NULL;
    while (current != NULL) {
        if (current->data.id == id) {
            if (previous == NULL) {
                head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
}

// Function for iterating over all network devices in the linked list and printing their information
void print_devices() {
    node_t *current = head;
    while (current != NULL) {
        printf("Device %d: ", current->data.id);
        printf("%s\n", current->data.supported_protocols);
        printf("Bandwidth limit: %.2f MB/s\n", (float)current->data.bandwidth_limit / 1000);
        current = current->next;
    }
}
