int generate_records(const char *offsets, struct record **records) {
    // Initialize variables
    int num_offsets = 0;
    long *long_offsets = NULL;
    struct record *record_array = NULL;
    int num_records = 0;
    int i, j;

    // Parse the input string and validate it
    char *token = strtok(offsets, ",");
    while (token != NULL) {
        long offset = atol(token);
        if (offset < INT_MIN || offset > INT_MAX) {
            printf("Error: Invalid offset value %ld\n", offset);
            return -1;
        }
        num_offsets++;
        token = strtok(NULL, ",");
    }

    // Allocate memory for the long offset array and initialize it
    long_offsets = (long *)malloc(num_offsets * sizeof(long));
    if (long_offsets == NULL) {
        printf("Error: Failed to allocate memory for long offsets\n");
        return -1;
    }
    num_records = num_offsets / 2;
    struct record *record_array = (struct record *)malloc(num_records * sizeof(struct record));
    if (record_array == NULL) {
        printf("Error: Failed to allocate memory for records\n");
        return -1;
    }

    // Initialize the long offset array and record array
    token = strtok(offsets, ",");
    i = 0;
    j = 0;
    while (token != NULL) {
        long_offsets[i] = atol(token);
        if (j < num_records) {
            record_array[j].key = rand() % INT_MAX + 1;
            record_array[j].offset = &long_offsets[i];
            j++;
        }
        i++;
        token = strtok(NULL, ",");
    }

    // Check for potential integer overflow when generating random numbers
    if (rand() > RAND_MAX) {
        printf("Error: Integer overflow when generating random numbers\n");
        return -1;
    }

    // Handle memory allocation failures and data validation errors
    if (long_offsets == NULL || record_array == NULL) {
        printf("Error: Memory allocation failed\n");
        return -1;
    } else if (num_records != num_offsets / 2) {
        printf("Error: Number of records does not match the number of offsets\n");
        return -1;
    }

    // Clean up and return success
    *records = record_array;
    free(long_offsets);
    return num_records;
}
