// Define the PHY_LAYER_EVENT_RECORD structure
typedef struct {
    uint64_t timestamp;
    uint8_t event_type;
    uint8_t received_packet_data[1024]; // 1KB of data
} PHY_LAYER_EVENT_RECORD;

// Define the linked list node structure for managing the dynamic array
typedef struct _node {
    PHY_LAYER_EVENT_RECORD record;
    struct _node *next;
} node_t;

// Define the dynamic array structure
typedef struct {
    size_t num_elements; // Number of elements in the array
    node_t **nodes; // Array of linked list nodes
    size_t capacity; // Maximum number of elements the array can hold
} dynarray_t;

// Define a mutex for thread-safe access to the dynamic array
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

/**
 * Adds a new element to the dynamic array.
 * @param dynarray The dynamic array to add the element to.
 * @param record The PHY_LAYER_EVENT_RECORD structure to add.
 */
void dynarray_add(dynarray_t *dynarray, PHY_LAYER_EVENT_RECORD *record) {
    // Acquire the mutex for thread-safe access
    pthread_mutex_lock(&mutex);

    // Check if there is enough capacity in the array to add a new element
    if (dynarray->num_elements < dynarray->capacity) {
        // Allocate memory for the new node and copy the record data into it
        node_t *node = malloc(sizeof(node_t));
        memcpy(&node->record, record, sizeof(PHY_LAYER_EVENT_RECORD));

        // Add the new node to the end of the linked list
        if (dynarray->nodes[0] == NULL) {
            dynarray->nodes[0] = node;
        } else {
            node_t *curr_node = dynarray->nodes[0];
            while (curr_node->next != NULL) {
                curr_node = curr_node->next;
            }
            curr_node->next = node;
        }

        // Increment the number of elements in the array
        ++dynarray->num_elements;
    } else {
        fprintf(stderr, "Error: Dynarray is full.\n");
    }

    // Release the mutex for thread-safe access
    pthread_mutex_unlock(&mutex);
}

/**
 * Removes an element from the dynamic array based on a given timestamp.
 * @param dynarray The dynamic array to remove the element from.
 * @param timestamp The timestamp of the element to remove.
 */
void dynarray_remove(dynarray_t *dynarray, uint64_t timestamp) {
    // Acquire the mutex for thread-safe access
    pthread_mutex_lock(&mutex);

    // Find the node with the matching timestamp and remove it from the linked list
    if (dynarray->nodes[0] != NULL) {
        node_t *curr_node = dynarray->nodes[0];
        while (curr_node->next != NULL) {
            if (curr_node->record.timestamp == timestamp) {
                // Remove the current node from the linked list
                if (curr_node == dynarray->nodes[0]) {
                    dynarray->nodes[0] = curr_node->next;
                } else {
                    node_t *prev_node = dynarray->nodes[0];
                    while (prev_node->next != curr_node) {
                        prev_node = prev_node->next;
                    }
                    prev_node->next = curr_node->next;
                }

                // Decrement the number of elements in the array
                --dynarray->num_elements;

                break;
            }
            curr_node = curr_node->next;
        }
    } else {
        fprintf(stderr, "Error: No node with matching timestamp found.\n");
    }

    // Release the mutex for thread-safe access
    pthread_mutex_unlock(&mutex);
}

/**
 * Updates a packet data element in the dynamic array based on a given timestamp.
 * @param dynarray The dynamic array to update the element in.
 * @param timestamp The timestamp of the element to update.
 * @param new_data The new packet data to update with.
 */
void dynarray_update(dynarray_t *dynarray, uint64_t timestamp, uint8_t *new_data) {
    // Acquire the mutex for thread-safe access
    pthread_mutex_lock(&mutex);

    // Find the node with the matching timestamp and update its packet data
    if (dynarray->nodes[0] != NULL) {
        node_t *curr_node = dynarray->nodes[0];
        while (curr_node->next != NULL) {
            if (curr_node->record.timestamp == timestamp) {
                memcpy(curr_node->record.received_packet_data, new_data, 1024);
                break;
            }
            curr_node = curr_node->next;
        }
    } else {
        fprintf(stderr, "Error: No node with matching timestamp found.\n");
    }

    // Release the mutex for thread-safe access
    pthread_mutex_unlock(&mutex);
}

int main() {
    dynarray_t *dynarray = malloc(sizeof(dynarray_t));
    dynarray->num_elements = 0;
    dynarray->capacity = 100;
    dynarray->nodes = malloc(dynarray->capacity * sizeof(node_t));
    memset(dynarray->nodes, 0, dynarray->capacity * sizeof(node_t));

    PHY_LAYER_DATA phy_layer;
    phy_layer.timestamp = 100;
    phy_layer.data[1023] = 0xFF;
    dynarray_add(dynarray, &phy_layer);

    PHY_LAYER_DATA phy_layer_updated;
    phy_layer_updated.timestamp = 100;
    phy_layer_updated.data[1023] = 0xAA;
    dynarray_update(dynarray, 100, &phy_layer_updated);

    node_t *curr_node = dynarray->nodes[0];
    while (curr_node != NULL) {
        fprintf(stdout, "Node: Timestamp=%ld, Data=%s\n", curr_node->record.timestamp, curr_node->record.received_packet_data);
        curr_node = curr_node->next;
    }
}
