    LTE_RRC_System_Info_Block* SystemInfoBlock;
} LTE_RRC_Paging_Message;

typedef struct {
    int Key;
    long Offset;
} Record;

// Caching strategies for latency management
#define CACHE_SIZE 1024
#define CACHE_EXPIRY_SECONDS 30

static LTE_RRC_System_Info_Block* cache[CACHE_SIZE];
static uint8_t cache_index = 0;
static time_t last_cache_refresh = 0;

// Memory allocation and initialization for arrays of 'long' offset values, 'int' keys, and an array of 'record' structures
#define NUM_RECORDS 1024
#define NUM_OFFSETS 16
Record records[NUM_RECORDS];
long offsets[NUM_OFFSETS];

// Function to manage the dynamic list of LTE_RRC_Paging_Message structures
void manageList(LTE_RRC_Paging_Message* paging_message) {
    // Check if the SystemInfoBlockId is unique
    for (int i = 0; i < NUM_RECORDS; i++) {
        if (paging_message->SystemInfoBlockId == records[i].Key) {
            return;
        }
    }

    // Add the new SystemInfoBlockId to the list and set its corresponding Offset value
    records[cache_index].Key = paging_message->SystemInfoBlockId;
    offsets[cache_index] = (long)paging_message->SystemInfoBlock;

    // Update the cache if necessary
    if (time(NULL) - last_cache_refresh >= CACHE_EXPIRY_SECONDS) {
        memcpy(cache, records, sizeof(LTE_RRC_Paging_Message*) * NUM_RECORDS);
        last_cache_refresh = time(NULL);
    }

    // Increment the cache index and update the LTE_RRC_Mobile_Identification
    cache_index++;
    if (cache_index >= NUM_RECORDS) {
        cache_index = 0;
    }
    paging_message->LTE_RRC_Mobile_Identification = (int*)offsets[cache_index];
}

// Function to retrieve the LTE_RRC_Paging_Message structure from the list given its SystemInfoBlockId
LTE_RRC_Paging_Message* retrieveFromList(uint8_t SystemInfoBlockId) {
    for (int i = 0; i < NUM_RECORDS; i++) {
        if (records[i].Key == SystemInfoBlockId) {
            return (LTE_RRC_Paging_Message*)offsets[i];
        }
    }
    return NULL;
}

// Function to retrieve the LTE_RRC_System_Info_Block structure from the list given its Offset value
LTE_RRC_System_Info_Block* retrieveFromList(long offset) {
    for (int i = 0; i < NUM_OFFSETS; i++) {
        if (offsets[i] == offset) {
            return (LTE_RRC_System_Info_Block*)records[i].Key;
        }
    }
    return NULL;
}
```
