typedef struct {
    int max_records; // The maximum number of records that can be stored in the manager
    int num_records; // The current number of records stored in the manager
    Record* records; // An array of pointers to the records
    pthread_mutex_t mutex; // A mutex for synchronizing access to the shared data structures
} MemoryManager;

// Function to allocate and initialize memory for an offset array and a key array
MemoryManager* init_memory_manager(int max_records) {
    // Allocate space for the struct that holds the state of the memory manager
    MemoryManager* manager = malloc(sizeof(MemoryManager));
    if (!manager) {
        return NULL;
    }

    // Initialize the mutex and set the maximum number of records to be stored in the manager
    pthread_mutex_init(&manager->mutex, NULL);
    manager->max_records = max_records;
    manager->num_records = 0;

    // Allocate space for the arrays of offsets and keys
    int* offsets = malloc(sizeof(int) * (max_records + 1));
    if (!offsets) {
        free(manager);
        return NULL;
    }
    manager->records = malloc(sizeof(Record) * max_records);
    if (!manager->records) {
        free(offsets);
        free(manager);
        return NULL;
    }

    // Initialize the arrays of offsets and keys
    for (int i = 0; i < max_records + 1; i++) {
        offsets[i] = -1;
    }
    for (int i = 0; i < max_records; i++) {
        manager->records[i].key = -1;
        manager->records[i].data = NULL;
    }

    // Store the pointers to the arrays of offsets and keys in the memory manager struct
    manager->offsets = offsets;
    manager->keys = &manager->records[0].key;

    return manager;
}

// Function to resize an array of records, preserving cache locality and minimizing performance impact
int resize_records(Record* records, int new_size) {
    // Check if the new size is larger or smaller than the current size
    if (new_size > sizeof(Records)) {
        return -1;
    } else if (new_size < sizeof(Records)) {
        return -2;
    }

    // Allocate space for the new array of records
    Record* new_records = malloc(sizeof(Record) * new_size);
    if (!new_records) {
        return -3;
    }

    // Copy the existing records to the new array, preserving cache locality and minimizing performance impact
    for (int i = 0; i < sizeof(Records); i++) {
        new_records[i] = records[i];
    }

    // Free the old array of records and update the pointer to the new array
    free(records);
    records = new_records;

    return 0;
}

// Function to add a record to the memory manager, preserving cache locality and minimizing performance impact
int add_record(MemoryManager* manager, int key, void* data) {
    // Check if there is enough space in the memory manager for a new record
    if (manager->num_records >= manager->max_records) {
        return -1;
    }

    // Compute the hash value of the key and find the index where it should be inserted
    int hash = custom_hash(key);
    int idx = hash % manager->max_records;

    // If there is already a record at the insertion point, move it to a new position in the array
    if (manager->offsets[idx] != -1) {
        resize_records(manager->records, manager->num_records * 2);
    }

    // Insert the new record into the array, preserving cache locality and minimizing performance impact
    Record* new_record = &manager->records[manager->num_records];
    new_record->key = key;
    new_record->data = data;
    manager->offsets[idx] = manager->num_records++;

    return 0;
}

// Function to retrieve a record from the memory manager, preserving cache locality and minimizing performance impact
Record* get_record(MemoryManager* manager, int key) {
    // Compute the hash value of the key and find the index where it should be inserted
    int hash = custom_hash(key);
    int idx = hash % manager->max_records;

    // If there is no record at the insertion point, return NULL
    if (manager->offsets[idx] == -1) {
        return NULL;
    }

    // Retrieve the record from the array, preserving cache locality and minimizing performance impact
    Record* record = &manager->records[manager->offsets[idx]];

    return record;
}

// Function to release all allocated memory for the memory manager
void free_memory_manager(MemoryManager* manager) {
    // Free the mutex and the arrays of offsets and keys
    pthread_mutex_destroy(&manager->mutex);
    free(manager->offsets);
    free(manager->keys);

    // Free all records in the memory manager, preserving cache locality and minimizing performance impact
    for (int i = 0; i < manager->num_records; i++) {
        if (manager->records[i].data != NULL) {
            free(manager->records[i].data);
        }
    }
    free(manager->records);

    // Free the memory manager struct itself
    free(manager);
}

// Function to handle errors in the memory manager, preserving cache locality and minimizing performance impact
void error_handler(int error) {
    switch (error) {
        case -1:
