} NFAPI_CRC_INDICATION_PDU_T;

// Function to manage dynamically allocated array of NFAPI_CRC_INDICATION_PDU_T structures
int parse_crc_indication_pdu(char *primary_csv_file, char *secondary_xml_file, char *json_config_file) {
    // Allocate memory for the array of NFAPI_CRC_INDICATION_PDU_T structures
    int num_entries = 0;
    NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu_array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_entries);
    if (!crc_indication_pdu_array) {
        fprintf(stderr, "Failed to allocate memory for crc_indication_pdu_array\n");
        return -1;
    }

    // Initialize the array with empty entries
    memset(crc_indication_pdu_array, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_entries);

    // Parse data from primary CSV file and secondary XML file
    FILE *primary_csv = fopen(primary_csv_file, "r");
    if (!primary_csv) {
        fprintf(stderr, "Failed to open primary CSV file\n");
        return -1;
    }
    FILE *secondary_xml = fopen(secondary_xml_file, "r");
    if (!secondary_xml) {
        fprintf(stderr, "Failed to open secondary XML file\n");
        return -1;
    }
    int num_primary_entries = parse_csv(primary_csv, crc_indication_pdu_array);
    int num_secondary_entries = parse_xml(secondary_xml, crc_indication_pdu_array + num_primary_entries);
    fclose(primary_csv);
    fclose(secondary_xml);

    // Parse data from third-party JSON configuration file
    FILE *json_config = fopen(json_config_file, "r");
    if (!json_config) {
        fprintf(stderr, "Failed to open JSON configuration file\n");
        return -1;
    }
    int num_json_entries = parse_json(json_config, crc_indication_pdu_array + num_primary_entries + num_secondary_entries);
    fclose(json_config);

    // Resolve discrepancies and conflicts among data sources
    for (int i = 0; i < num_entries; ++i) {
        if (crc_indication_pdu_array[i].RNTI == -1) {
            crc_indication_pdu_array[i].RNTI = crc_indication_pdu_array[i + 1].RNTI;
        }
    }

    // Append unique identifier to duplicate RNTIs
    int duplicate_rntis = 0;
    for (int i = 0; i < num_entries - 1; ++i) {
        if (crc_indication_pdu_array[i].RNTI == crc_indication_pdu_array[i + 1].RNTI) {
            duplicate_rntis++;
            int new_id = i + duplicate_rntis;
            crc_indication_pdu_array[i].RX_UE_INFORMATION_TAG += new_id;
        }
    }

    // Free unused memory and return total number of parsed entries
    if (num_entries > 0) {
        free(crc_indication_pdu_array + num_primary_entries + num_secondary_entries);
    }
    free(crc_indication_pdu_array);
    return num_entries;
}

// Parse data from primary CSV file and secondary XML file
int parse_csv(FILE *primary_csv, NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu_array) {
    int num_entries = 0;
    while (!feof(primary_csv)) {
        char line[256];
        fgets(line, sizeof(line), primary_csv);
        // Skip empty lines and comments
        if (strlen(line) == 0 || line[0] == '#') continue;
        int rnti = -1, crcflag = -1;
