        crc_indication_pdu_array[num_entries].RX_UE_INFORMATION_TAG = num_entries;
        crc_indication_pdu_array[num_entries].RNTI = rnti;
        crc_indication_pdu_array[num_entries].CRC_INDICATION_REL8_TAG = crcflag;
        num_entries++;
    }
    return num_entries;
