    void* data;
    struct Node* next;
};

// data structure for storing records, keys, and offsets
typedef struct {
    int num_records; // number of records
    char** keys;    // array of keys
    long* offsets;  // array of offsets
    struct Node* head; // linked list of nodes
} DataStructure;

// function to manage the flexible and efficient data storage system for records, keys, and offsets
void managing_data_structure(int num_records, int valid_range, char* init_pattern) {
    if (num_records > MAX_RECORDS) {
        printf("Number of records exceeds the maximum allowed limit. Exiting...\n");
        exit(1);
    }

    // initialize the data structure
    DataStructure* ds = malloc(sizeof(DataStructure));
    if (ds == NULL) {
        printf("Error: Failed to allocate memory for data structure.\n");
        exit(2);
    }
    ds->num_records = num_records;
    ds->keys = malloc(sizeof(char*) * num_records);
    if (ds->keys == NULL) {
        printf("Error: Failed to allocate memory for keys.\n");
        exit(3);
    }
    ds->offsets = malloc(sizeof(long) * num_records);
    if (ds->offsets == NULL) {
        printf("Error: Failed to allocate memory for offsets.\n");
        exit(4);
    }
    ds->head = NULL;

    // initialize the keys and offsets
    for (int i = 0; i < num_records; i++) {
        char* key = malloc(sizeof(char) * strlen(init_pattern));
        if (key == NULL) {
            printf("Error: Failed to allocate memory for key %d.\n", i);
            exit(5);
        }
        strcpy(key, init_pattern);
        ds->keys[i] = key;
        ds->offsets[i] = -1;
    }

    // implement dynamic resizing of the record array using a linked list approach
    for (int i = 0; i < num_records; i++) {
        struct Node* node = malloc(sizeof(struct Node));
        if (node == NULL) {
            printf("Error: Failed to allocate memory for node %d.\n", i);
            exit(6);
        }
        node->data = ds->keys[i];
        node->next = NULL;
        if (ds->head == NULL) {
            ds->head = node;
        } else {
            struct Node* current = ds->head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = node;
        }
    }

    // serialize the data structure to disk in a binary format
    FILE* file = fopen("data.bin", "wb");
    if (file == NULL) {
        printf("Error: Failed to open file for writing.\n");
        exit(7);
    }
    fwrite(ds, sizeof(DataStructure), 1, file);
    fclose(file);

    // compress the data structure using a third-party compression library
    int compressed_size = ZSTD_compress_data(ds->keys[0], ds->offsets[0]);
    if (compressed_size == 0) {
        printf("Error: Failed to compress data.\n");
        exit(8);
    }

    // monitor memory usage and implement early termination if the system approaches a predefined threshold
    int total_memory = ZSTD_get_total_memory();
    if (total_memory > MEMORY_LIMIT * 1024) { // MB to Bytes
        printf("Memory usage exceeds the maximum allowed limit. Exiting...\n");
        exit(9);
    } else if ((float)total_memory / MEMORY_LIMIT >= THRESHOLD) {
        printf("Memory usage approaching the threshold. Exiting...\n");
        exit(10);
    }

    // enable debug mode for detailed logging of memory allocation and deallocation events
    if (DEBUG_MODE) {
        printf("Debug mode enabled.\n");
    }

    // ensure thread safety by implementing synchronization primitives to handle concurrent access from multiple threads
    pthread_mutex_t* mutex = malloc(sizeof(pthread_mutex_t));
    if (mutex == NULL) {
        printf("Error: Failed to allocate memory for mutex.\n");
        exit(11);
    }
    int result = pthread_mutex_init(mutex, NULL);
    if (result != 0) {
        printf("Error: Failed to initialize mutex with error code %d.\n", result);
        exit(12);
    }

    // add a feature to validate the integrity of the data structure after deserialization
    bool is_valid = ZSTD_validate_data(ds->keys[0], ds->offsets[0]);
    if (!is_valid) {
        printf("Error: Data structure has been corrupted. Exiting...\n");
        exit(13);
    }

    // optimize the compression algorithm used for serialization by using a third-party library
    ZSTD_optimize_compression(ds->keys[0], ds->offsets[0]);
}
