    list->allocated_size = 16; // initial size of the list
    list->elements = malloc(list->allocated_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

// Define function to add element to dynamic list
void add_element_to_dynamic_list(DYNAMIC_LIST_T* list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (list->num_elements >= list->allocated_size) {
        // Increase the size of the list if it is full
        list->allocated_size *= 2;
        list->elements = realloc(list->elements, list->allocated_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    list->elements[list->num_elements++] = element;
}

// Define function to remove element from dynamic list
void remove_element_from_dynamic_list(DYNAMIC_LIST_T* list, size_t index) {
    // Shift elements after the target index to fill the gap
    for (size_t i = index + 1; i < list->num_elements; i++) {
        list->elements[i - 1] = list->elements[i];
    }
