void handle_reallocation(DYNAMIC_LIST_T* list, size_t new_size) {
    // If the new size is larger than the current size, allocate new memory and copy elements
    if (new_size > list->allocated_size) {
        void* new_mem = realloc(list->elements, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_mem != NULL) {
