// Define function to allocate memory for arrays and initialize records
void allocateMemory(int recordCount) {
    // Acquire lock before modifying global variables
    pthread_mutex_lock(&lock);

    // Validate that total size of arrays does not exceed maximum memory limit
    long totalSize = (long)recordCount * sizeof(long) + (long)recordCount * sizeof(int) + (long)recordCount * sizeof(record);
    if (totalSize > MAX_MEMORY) {
        pthread_mutex_unlock(&lock);
        return; // Return error code if memory limit exceeded
    }

    // Allocate memory for offset, key, and record arrays
    offsets = malloc(recordCount * sizeof(long));
    keys = malloc(recordCount * sizeof(int));
    records = malloc(recordCount * sizeof(record));

    // Initialize random seed for generating 'int' values
    srand(CUSTOM_SEED);

    // Generate random 'int' values and string identifiers for each record
    for (int i = 0; i < recordCount; i++) {
        offsets[i] = rand() % MAX_MEMORY;
        keys[i] = rand();
        records[i].value = rand();
        records[i].identifier = malloc(10 * sizeof(char));
        sprintf(records[i].identifier, "%d", i);
    }

    // Release lock after completing allocation and initialization
    pthread_mutex_unlock(&lock);
}

