void generate_nfapi_crc_indication_pdu(int num_ue, int* ue_ids) {
    // Initialize the list of PDUs
    NFAPI_CRC_INDICATION_PDU_T pdu_list[MAX_NFAPI_CRC_INDICATION_PDU];
    memset(pdu_list, 0, sizeof(pdu_list));

    // Create a semaphore to protect the list of PDUs from concurrent access
    sem_t *pdu_sem = sem_open("/nfapi_crc_indication_pdu_sem", O_CREAT | O_EXCL, 0644, 1);

    // Initialize the database connection
    sqlite3 *db;
    sqlite3_open("nfapi_crc_indication_database.db", &db);

    for (int i = 0; i < num_ue; i++) {
        // Retrieve the UE information from the database
