        sprintf(query, "SELECT rx_ue_information_tag, rnti FROM ue_info WHERE id=%d", ue_ids[i]);
        sqlite3_stmt *stmt = sqlite3_prepare_v2(db, query, -1, NULL);
        bool retrieved = false;

        while (retrieved == false) {
            if (sqlite3_step(stmt) != SQLITE_ROW) {
                break;
            }

            // Extract the UE information from the result set
            uint16_t rx_ue_information_tag = sqlite3_column_int(stmt, 0);
            uint32_t rnti = sqlite3_column_int(stmt, 1);

            // Generate a random CRCFlag value
