            // Create a new PDU and populate it with the UE information
            NFAPI_CRC_INDICATION_PDU_T pdu;
            pdu.rx_ue_information_tag = rx_ue_information_tag;
            pdu.rnti = rnti;
            pdu.crc_indication_rel8_tag = 0; // TODO: generate a valid CRC indication REL8 tag
            pdu.crcflag = crcflag;

            // Add the PDU to the list
            sem_wait(pdu_sem);
            memcpy(&pdu_list[i], &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            sem_post(pdu_sem);

            retrieved = true;
        }

        // Clean up the statement and database connection
        sqlite3_finalize(stmt);
    }

    // Close the database connection
    sqlite3_close(db);
}

