#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <netinet/ip.h>
#include <netpacket/packet.h>

#define MAX_NIC_STATS 100
#define MAX_PACKET_SIZE 1500

typedef struct nic_stats {
    MAC_HEADER mac;
    IP_PACKET ip;
    uint64_t latency;
    uint64_t throughput;
} nic_stats_t;

nic_stats_t *nic_stats = NULL;
size_t nic_stats_len = 0;
size_t nic_stats_capacity = 0;

int init_nic_stats(void) {
    // Allocate memory for the dynamic array of NIC statistics structures
    nic_stats = malloc(sizeof(nic_stats_t) * MAX_NIC_STATS);
    if (nic_stats == NULL) {
        return -1;
    }

    // Initialize the NIC statistics structure with default values
    for (size_t i = 0; i < MAX_NIC_STATS; i++) {
        nic_stats[i].mac.hdr_len = sizeof(nic_stats[i].mac);
        nic_stats[i].ip.version = IPVERSION;
        nic_stats[i].ip.header_length = sizeof(nic_stats[i].ip);
        nic_stats[i].ip.total_length = 0;
        nic_stats[i].ip.identification = 0;
        nic_stats[i].ip.flags = 0;
        nic_stats[i].ip.fragment_offset = 0;
        nic_stats[i].ip.time_to_live = IPDEFTTL;
        nic_stats[i].ip.protocol = IPPROTO_TCP;
        nic_stats[i].ip.checksum = 0;
    }

    // Initialize the NIC statistics array with a capacity of MAX_NIC_STATS
    nic_stats_capacity = MAX_NIC_STATS;

    return 0;
}

int insert_nic_stat(const MAC_HEADER *mac, const IP_PACKET *ip) {
    // Check if the NIC statistics array is full
    if (nic_stats_len == nic_stats_capacity) {
        // Increase the capacity of the NIC statistics array by 10%
        size_t new_capacity = (size_t)(nic_stats_capacity * 1.1);
        nic_stats = realloc(nic_stats, sizeof(nic_stats_t) * new_capacity);
        if (nic_stats == NULL) {
            // Reallocation failed, return an error
            return -1;
        }
        // Update the capacity of the NIC statistics array
        nic_stats_capacity = new_capacity;
    }

    // Insert a new NIC statistics structure into the array
    nic_stats[nic_stats_len].mac = *mac;
    nic_stats[nic_stats_len].ip = *ip;
    // Calculate the network latency and throughput metrics
    uint64_t time = get_current_time();
    uint64_t latency = time - nic_stats[nic_stats_len].mac.timestamp;
    uint64_t throughput = 0;
    if (latency > 0) {
        throughput = ((double)(nic_stats[nic_stats_len].ip.total_length - ip->header_length) / latency);
    }
    nic_stats[nic_stats_len].latency = latency;
    nic_stats[nic_stats_len].throughput = throughput;

    // Increment the number of NIC statistics structures in the array
    nic_stats_len++;

    return 0;
}

int validate_packet(const IP_PACKET *ip) {
    // Validate the IP packet checksum
    uint16_t checksum = ip->checksum;
    ip->checksum = 0;
    uint16_t calculated_checksum = calculate_checksum(ip);
    ip->checksum = checksum;
    if (calculated_checksum != checksum) {
        // Checksum mismatch, return an error
        return -1;
    }
    return 0;
}

uint64_t calculate_checksum(const IP_PACKET *ip) {
    // Calculate the IP packet checksum using the Internet Checksum Algorithm (IPv4)
    uint64_t sum = 0;
    const unsigned char *ptr = (const unsigned char *)ip;
    size_t length = ip->header_length + ip->total_length;
    for (size_t i = 0; i < length; i++) {
        sum += ptr[i];
    }
    while ((sum >> 16) != 0) {
        sum = (sum & 0xFFFF) + (sum >> 16);
    }
    return sum;
}
