#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Structures for student record system
struct student {
    int id;
    char name[256];
    double score;
};

struct grade_record {
    int id;
    double score;
    char name[256];
};

// Hash table for efficient lookup times
struct hash_table {
    struct student **students;
    int capacity;
    int size;
};

// Function to dynamically manage student records
void manage_student_records(struct hash_table *table, int id) {
    // Insert or delete student based on unique ID
    if (id >= 0) {
        insert_student(table, id);
    } else {
        delete_student(table, -id);
    }
}

// Function to insert a new student into the hash table
void insert_student(struct hash_table *table, int id) {
    // Check if student with given ID already exists
    if (lookup_student(table, id)) {
        printf("Student with ID %d already exists\n", id);
        return;
    }

    // Create new student structure and insert into hash table
    struct student *new_student = malloc(sizeof(struct student));
    new_student->id = id;
    strcpy(new_student->name, "");
    new_student->score = 0.0;

    int index = id % table->capacity;
    if (table->students[index] == NULL) {
        table->size++;
    }
    table->students[index] = new_student;
}

// Function to delete a student from the hash table
void delete_student(struct hash_table *table, int id) {
    // Check if student with given ID exists
    if (!lookup_student(table, id)) {
        printf("Student with ID %d does not exist\n", id);
        return;
    }

    // Remove student from hash table
    int index = id % table->capacity;
    struct student *removed_student = table->students[index];
    if (removed_student != NULL) {
        table->size--;
    }
    table->students[index] = NULL;
}

// Function to lookup a student in the hash table
struct student *lookup_student(struct hash_table *table, int id) {
    int index = id % table->capacity;
    struct student *current_student = table->students[index];
    while (current_student != NULL && current_student->id != id) {
        current_student = current_student->next;
    }
    return current_student;
}

// Function to calculate the average score of all students in the hash table
double calculate_average_score(struct hash_table *table) {
    double sum = 0.0;
    int count = 0;
    for (int i = 0; i < table->capacity; i++) {
        struct student *current_student = table->students[i];
        while (current_student != NULL) {
            sum += current_student->score;
            count++;
            current_student = current_student->next;
        }
    }
    return sum / count;
}

// Function to calculate the highest and lowest scores of all students in the hash table
void calculate_highest_lowest(struct hash_table *table, int *highest, int *lowest) {
    *highest = -100000;
    *lowest = 100000;
    for (int i = 0; i < table->capacity; i++) {
        struct student *current_student = table->students[i];
        while (current_student != NULL) {
            if (current_student->score > *highest) {
                *highest = current_student->score;
            }
            if (current_student->score < *lowest) {
                *lowest = current_student->score;
            }
            current_student = current_student->next;
        }
    }
}

// Function to generate random values for an array of ints
void generate_random_values(int *array, int size) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        array[i] = rand() % 100 + 1;
    }
}

// Function to generate random values for an array of structs
void generate_random_structures(struct record *array, int size) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        array[i].value = rand() % 100 + 1;
    }
}
