#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "memory_manager.h"

struct config_setting {
    char* key;
    char* value;
    size_t expiration_timestamp;
};

struct memory_pool {
    struct config_setting* settings;
    size_t capacity;
    size_t used;
    pthread_mutex_t lock;
};

struct config_manager {
    struct memory_pool pool;
    size_t max_memory_limit;
    unsigned int seed;
    bool initialized;
};

void init_config_manager(struct config_manager* manager, size_t max_memory_limit) {
    memset(&manager->pool, 0, sizeof(struct memory_pool));
    manager->pool.capacity = max_memory_limit / sizeof(struct config_setting);
    manager->pool.settings = malloc(manager->pool.capacity * sizeof(struct config_setting));
    manager->max_memory_limit = max_memory_limit;
    manager->seed = time(NULL);
    manager->initialized = true;
}

void deinit_config_manager(struct config_manager* manager) {
    free(manager->pool.settings);
    manager->initialized = false;
}

int add_config_setting(struct config_manager* manager, const char* key, const char* value, size_t expiration_timestamp) {
    if (!manager->initialized) {
        return -1; // Error: Config manager not initialized
    }

    if (strlen(key) == 0 || strlen(value) == 0 || expiration_timestamp <= time(NULL)) {
        return -2; // Error: Invalid argument
    }

    size_t total_size = sizeof(struct config_setting);
    size_t new_size = manager->pool.used + total_size;

    if (new_size > manager->max_memory_limit) {
        return -3; // Error: Memory limit exceeded
    }

    struct config_setting* setting = malloc(total_size);
    strcpy(setting->key, key);
    strcpy(setting->value, value);
    setting->expiration_timestamp = expiration_timestamp;

    pthread_mutex_lock(&manager->pool.lock);

    manager->pool.settings[manager->pool.used++] = setting;

    pthread_mutex_unlock(&manager->pool.lock);

    return 0; // Success
}

int remove_config_setting(struct config_manager* manager, const char* key) {
    if (!manager->initialized) {
        return -1; // Error: Config manager not initialized
    }

    size_t index = get_config_index(manager, key);

    if (index == SIZE_MAX) {
        return -2; // Error: Key not found
    }

    pthread_mutex_lock(&manager->pool.lock);

    free(manager->pool.settings[index]);
    memmove(&manager->pool.settings[index], &manager->pool.settings[index + 1], (manager->pool.used - index - 1) * sizeof(struct config_setting));
    manager->pool.used--;

    pthread_mutex_unlock(&manager->pool.lock);

    return 0; // Success
}

int get_config_index(struct config_manager* manager, const char* key) {
    if (!manager->initialized) {
        return SIZE_MAX; // Error: Config manager not initialized
    }

    size_t index = 0;

    pthread_mutex_lock(&manager->pool.lock);

    for (size_t i = 0; i < manager->pool.used; i++) {
        if (!strcmp(key, manager->pool.settings[i]->key)) {
            index = i;
            break;
        }
    }

    pthread_mutex_unlock(&manager->pool.lock);

    return index; // Success
}

int get_config_value(struct config_manager* manager, const char* key, char* value, size_t* len) {
    if (!manager->initialized) {
        return -1; // Error: Config manager not initialized
    }

    size_t index = get_config_index(manager, key);

    if (index == SIZE_MAX) {
        return -2; // Error: Key not found
    }

    *len = strlen(manager->pool.settings[index]->value);
    memcpy(value, manager->pool.settings[index]->value, *len + 1);

    return 0; // Success
}

int update_config_setting(struct config_manager* manager, const char* key, const char* value, size_t expiration_timestamp) {
    if (!manager->initialized) {
        return -1; // Error: Config manager not initialized
    }

    size_t index = get_config_index(manager, key);

    if (index == SIZE_MAX) {
        return -2; // Error: Key not found
    }

    pthread_mutex_lock(&manager->pool.lock);

    free(manager->pool.settings[index]->value);
    strcpy(manager->pool.settings[index]->value, value);
    manager->pool.settings[index]->expiration_timestamp = expiration_timestamp;

    pthread_mutex_unlock(&manager->pool.lock);

    return 0; // Success
}
```
