// Structure to hold NIC statistics
struct nic_statistics {
    uint8_t mac_header[6];
    struct ip_packet *ip_packet;
};

// Structure to hold an IP packet
struct ip_packet {
    uint16_t payload_size;
    uint32_t checksum;
    uint8_t payload[0];
};

// Hash table to store NIC statistics
static struct nic_statistics **nic_stats = NULL;

// Number of elements in the hash table
static size_t num_elements = 0;

// Size of the hash table
static size_t hash_table_size = 1024;

// Maximum number of elements to grow the hash table to
static size_t max_growth_limit = 10 * 1024;

// Function to initialize a NIC statistics structure
void nic_statistics_init(struct nic_statistics *nic) {
    // Initialize the MAC header and IP packet structures
    memset(&nic->mac_header, 0, sizeof(nic->mac_header));
    nic->ip_packet = malloc(sizeof(struct ip_packet));
    if (nic->ip_packet == NULL) {
        perror("malloc");
        exit(1);
    }

    // Generate a random payload size and checksum for the IP packet
    nic->ip_packet->payload_size = rand() % 2048;
    nic->ip_packet->checksum = generate_checksum(nic->ip_packet, sizeof(*nic->ip_packet) + nic->ip_packet->payload_size);
}

// Function to validate the checksum of an IP packet
bool is_valid_checksum(struct ip_packet *ip_packet) {
    uint32_t calculated_checksum = generate_checksum(ip_packet, sizeof(*ip_packet) + ip_packet->payload_size);
    return calculated_checksum == ip_packet->checksum;
}

// Function to add a NIC statistics structure to the hash table
void nic_statistics_add(struct nic_statistics *nic) {
    // If the hash table is full, resize it and rehash all elements
    if (num_elements == hash_table_size) {
        hash_table_resize();
    }

    // Add the NIC statistics structure to the hash table
    int index = hash(nic->mac_header);
    nic_stats[index] = nic;
    num_elements++;
}

// Function to remove a NIC statistics structure from the hash table
void nic_statistics_remove(struct nic_statistics *nic) {
    // If the NIC statistics structure is not in the hash table, do nothing
    if (nic_stats[hash(nic->mac_header)] != nic) {
        return;
    }

    // Remove the NIC statistics structure from the hash table
    int index = hash(nic->mac_header);
    nic_stats[index] = NULL;
    num_elements--;
}

// Function to update the checksum of an IP packet in the hash table
void nic_statistics_update_checksum(struct nic_statistics *nic) {
    // If the NIC statistics structure is not in the hash table, do nothing
    if (nic_stats[hash(nic->mac_header)] != nic) {
        return;
    }

    // Update the checksum of the IP packet
    nic->ip_packet->checksum = generate_checksum(nic->ip_packet, sizeof(*nic->ip_packet) + nic->ip_packet->payload_size);
}

// Function to find a NIC statistics structure in the hash table by MAC address
struct nic_statistics *nic_statistics_find(uint8_t mac_address[]) {
    // If the hash table is empty, return NULL
    if (num_elements == 0) {
        return NULL;
    }

    // Search for the NIC statistics structure with the given MAC address in the hash table
    int index = hash(mac_address);
    struct nic_statistics *nic = nic_stats[index];
    while (nic != NULL && memcmp(nic->mac_header, mac_address, sizeof(nic->mac_header)) != 0) {
        index++;
        if (index >= hash_table_size) {
            index = 0;
        }
        nic = nic_stats[index];
    }
    return nic;
}

// Function to generate a checksum for an IP packet
uint32_t generate_checksum(struct ip_packet *ip_packet, size_t size) {
    // Calculate the checksum of the IP packet
    uint32_t checksum = 0;
    for (size_t i = 0; i < size; i++) {
        checksum += ip_packet->payload[i];
    }
    return checksum;
}

// Function to resize the hash table if it is full
void hash_table_resize() {
    // If the hash table is already at its maximum growth limit, do nothing
    if (num_elements >= max_growth_limit) {
        return;
    }

    // Create a new hash table with twice the size of the current one
    size_t new_hash_table_size = hash_table_size * 2;
    struct nic_statistics **new_nic_stats = malloc(sizeof(struct nic_statistics *) * new_hash_table_size);
    if (new_nic_stats == NULL) {
        perror("malloc");
        exit(1);
    }

    // Copy all elements from the current hash table to the new one
    for (int i = 0; i < hash_table_size; i++) {
        struct nic_statistics *nic = nic_stats[i];
        if (nic != NULL) {
            int index = hash(nic->mac_header);
            new_nic_stats[index] = nic;
            num_elements++;
        }
    }

    // Free the memory of the current hash table and set the new one as the current one
    free(nic_stats);
    nic_stats = new_nic_stats;
    hash_table_size = new_hash_table_size;
}

// Function to calculate a hash value for a given MAC address
int hash(uint8_t mac_address[]) {
    uint32_t hash = 0;
    for (size_t i = 0; i < sizeof(mac_address); i++) {
        hash += mac_address[i];
    }
    return hash % hash_table_size;
}
```

