typedef struct {
    int key;
    long offset;
} record;

void *allocate_memory(size_t size, int range) {
    // Dynamically allocate memory for all structures
    long *offsets = malloc(sizeof(long) * size);
    int *keys = malloc(sizeof(int) * size);
    record *records = malloc(sizeof(record) * size);

    // Initialize offsets and keys with random values within the specified range
    for (int i = 0; i < size; i++) {
        offsets[i] = rand() % range;
        keys[i] = rand() % range;
    }

    // Ensure that no two records share the same key
    for (int i = 0; i < size - 1; i++) {
        int j = i + 1;
        while (j < size) {
            if (keys[i] == keys[j]) {
                // If two records have the same key, swap their values and increment j
                long temp_offset = offsets[i];
                offsets[i] = offsets[j];
                offsets[j] = temp_offset;
                int temp_key = keys[i];
                keys[i] = keys[j];
                keys[j] = temp_key;
                j++;
            } else {
                // If two records don't have the same key, increment j by 1
                j++;
            }
        }
    }

    // Initialize each record with a random integer within the specified range
    for (int i = 0; i < size; i++) {
        records[i].key = keys[i];
        records[i].offset = offsets[i];
    }

    // Validate the integrity of allocated memory
    for (int i = 0; i < size; i++) {
        if (records[i].key == -1 || records[i].offset == -1) {
            printf("Error: Invalid record at index %d\n", i);
            return NULL;
        }
    }

    // Log memory usage and errors for debugging purposes
    printf("Memory usage: %lu bytes\n", size * sizeof(record));

    // Return the allocated memory
    return records;
}

void deallocate_memory(void *ptr) {
    free(ptr);
}

int main() {
    // Test the allocate_memory function by allocating 1000 records with a range of 1-1000
    record *records = allocate_memory(1000, 1000);

    // Use the allocated memory for some computation
    printf("First record: %d, offset: %ld\n", records[0].key, records[0].offset);

    // Deallocate the memory when it is no longer needed
    deallocate_memory(records);

    return 0;
}
