    // Calculate the total number of accesses for the storage volume
    int num_accesses = 0;
    for (int i = 0; i < MAX_LOG_ENTRIES; i++) {
        if (log[i] == '1') {
            num_accesses++;
        }
    }

    // Calculate the usage percentage of the storage volume
    float usage_percentage = (float)num_accesses / capacity;

    return usage_percentage;
}
