struct record {
  int key;
  long offset;
};

typedef struct {
  struct record* records;
  size_t num_records;
  pthread_mutex_t lock;
  sem_t sem;
} mem_manager;

mem_manager* create_mem_manager(size_t num_records) {
  mem_manager* manager = malloc(sizeof(mem_manager));
  if (!manager) {
    fprintf(stderr, "Failed to allocate memory for mem_manager\n");
    return NULL;
  }
  manager->records = calloc(num_records, sizeof(struct record));
  if (!manager->records) {
    fprintf(stderr, "Failed to allocate memory for records array\n");
    free(manager);
    return NULL;
  }
  manager->num_records = num_records;
  pthread_mutex_init(&manager->lock, NULL);
  sem_init(&manager->sem, 0, 1);
  return manager;
}

void destroy_mem_manager(mem_manager* manager) {
  if (!manager) {
    fprintf(stderr, "Invalid mem_manager pointer\n");
    return;
  }
  pthread_mutex_destroy(&manager->lock);
  sem_destroy(&manager->sem);
  free(manager->records);
  free(manager);
}

int generate_random_key(int min, int max) {
  // Generate a random integer between the specified range.
  return rand() % (max - min + 1) + min;
}

void update_record(struct record* record, long offset) {
  record->offset = offset;
}

int handle_http_post(mem_manager* manager, char* json_payload) {
  // Parse the JSON payload and validate input.
  int num_records;
  if (sscanf(json_payload, "{\"num_records\":%d}", &num_records) != 1 || num_records > MAX_RECORDS) {
    fprintf(stderr, "Invalid input: %s\n", json_payload);
    return -1;
  }
  int min_int = INT_MIN, max_int = INT_MAX;
  if (sscanf(json_payload, "{\"min_int\":%d,\"max_int\":%d}", &min_int, &max_int) == 2) {
    // Generate random keys for the records.
    for (size_t i = 0; i < num_records; ++i) {
      manager->records[i].key = generate_random_key(min_int, max_int);
    }
  } else {
    // Initialize keys with a specified pattern.
    int key_pattern;
    if (sscanf(json_payload, "{\"key_pattern\":%d}", &key_pattern) != 1) {
      fprintf(stderr, "Invalid input: %s\n", json_payload);
      return -1;
    }
    for (size_t i = 0; i < num_records; ++i) {
      manager->records[i].key = key_pattern * i + i / MAX_RECORDS;
    }
  }
  // Update offset values using a third-party API.
  for (size_t i = 0; i < num_records; ++i) {
    long offset = retrieve_offset(manager->records[i].key);
    update_record(&manager->records[i], offset);
  }
  return 0;
}

int handle_http_get(mem_manager* manager, int key) {
  // Find the record with the specified key and return its offset value.
  for (size_t i = 0; i < manager->num_records; ++i) {
    if (manager->records[i].key == key) {
      sem_wait(&manager->sem);
      long offset = manager->records[i].offset;
      sem_post(&manager->sem);
      return offset;
    }
  }
  fprintf(stderr, "Failed to find record with key %d\n", key);
  return -1;
}

void* update_page(void* arg) {
  // Update the page content using a service class.
  mem_manager* manager = (mem_manager*)arg;
  for (size_t i = 0; i < manager->num_records; ++i) {
    long offset = manager->records[i].offset;
    char* html = generate_html(offset);
    update_page_content(html);
  }
}

int handle_http_post_async(mem_manager* manager, char* json_payload) {
  // Update the page content asynchronously using a service class.
  if (pthread_create(&update_page_thread, NULL, update_page, (void*)manager)) {
    fprintf(stderr, "Failed to create update_page thread\n");
    return -1;
  }
}

int handle_http_get_sync(mem_manager* manager, int key) {
  // Update the page content synchronously using a service class.
  sem_wait(&manager->sem);
  long offset = handle_http_get(manager, key);
  sem_post(&manager->sem);
  return offset;
}
