void nfapi_l1_context_add(NFAPI_L1_CONTEXTS* contexts, bool is_lte_a_enabled, bool is_lte_r_enabled) {
    // Check if there is enough memory available to allocate a new NFAPI_L1_CONTEXT structure
    if (contexts->total_size + sizeof(NFAPI_L1_CONTEXT) > MAX_ALLOCATED_MEMORY) {
        printf("Not enough memory available to allocate a new NFAPI_L1_CONTEXT structure\n");
        return;
    }

