#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include <pthread.h>

// Macros for configuration
#define MAX_RECORDS 10000
#define MEMORY_THRESHOLD 80

// Structures and types
typedef struct {
    uint32_t valid_rx_ue_information_tag;
    uint32_t rnti;
    uint32_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t count;
    pthread_mutex_t lock;
} NFAPI_CRC_INDICATION_PDU_LIST_T;

// Function prototypes
void add_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_LIST_T *list, uint32_t valid_rx_ue_information_tag, uint32_t rnti);
void remove_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_LIST_T *list, uint32_t crc_indication_rel8_tag);
void update_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_LIST_T *list, uint32_t crc_indication_rel8_tag, uint32_t crcflag);
void clear_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_LIST_T *list);
void print_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_LIST_T *list);
void serialize_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_LIST_T *list, char *filename);
void deserialize_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_LIST_T *list, char *filename);

// Implementation of the functions above

void add_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_LIST_T *list, uint32_t valid_rx_ue_information_tag, uint32_t rnti) {
    // Check if the list is full
    if (list->count >= MAX_RECORDS) {
        printf("Maximum number of records reached\n");
        return;
    }

    // Lock the list
    pthread_mutex_lock(&list->lock);

    // Create a new node for the PDU
    NFAPI_CRC_INDICATION_PDU_T *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    assert(new_node != NULL);
    new_node->valid_rx_ue_information_tag = valid_rx_ue_information_tag;
    new_node->rnti = rnti;
    new_node->crc_indication_rel8_tag = 0; // Randomly set CRCFLAG

    // Add the node to the list
    if (list->data == NULL) {
        list->data = new_node;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *last_node = list->data;
        while (last_node->next != NULL) {
            last_node = last_node->next;
        }
        last_node->next = new_node;
    }
    list->count++;

    // Unlock the list
    pthread_mutex_unlock(&list->lock);
}

void remove_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_LIST_T *list, uint32_t crc_indication_rel8_tag) {
    // Lock the list
    pthread_mutex_lock(&list->lock);

    // Find the node with the given CRCFLAG
    NFAPI_CRC_INDICATION_PDU_T *node = list->data;
    while (node != NULL) {
        if (node->crc_indication_rel8_tag == crc_indication_rel8_tag) {
            // Remove the node from the list
            if (node == list->data) {
                list->data = node->next;
            } else {
                NFAPI_CRC_INDICATION_PDU_T *prev_node = list->data;
                while (prev_node->next != node) {
                    prev_node = prev_node->next;
                }
                prev_node->next = node->next;
            }
            list->count--;

            // Free the memory of the node
            free(node);

            break;
        }
        node = node->next;
    }

    // Unlock the list
    pthread_mutex_unlock(&list->lock);
}

void update_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_LIST_T *list, uint32_t crc_indication_rel8_tag, uint32_t crcflag) {
    // Lock the list
    pthread_mutex_lock(&list->lock);

    // Find the node with the given CRCFLAG
    NFAPI_CRC_INDICATION_PDU_T *node = list->data;
    while (node != NULL) {
        if (node->crc_indication_rel8_tag == crc_indication_rel8_tag) {
            node->crcflag = crcflag;
            break;
        }
        node = node->next;
    }

    // Unlock the list
    pthread_mutex_unlock(&list->lock);
}

void clear_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_LIST_T *list) {
    // Lock the list
    pthread_mutex_lock(&list->lock);

    // Free all nodes in the list
    NFAPI_CRC_INDICATION_PDU_T *node = list->data;
    while (node != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next_node = node->next;
        free(node);
        node = next_node;
    }

    // Reset the list
    list->data = NULL;
    list->count = 0;

    // Unlock the list
    pthread_mutex_unlock(&list->lock);
}

void serialize(NFAPI_CRC_INDICATION_PDU_LIST *list, uint8_t **buffer) {
    // Lock the list
    pthread_mutex_lock(&list->lock);

    // Calculate the size of the buffer needed to store the PDUs
    int size = 0;
    NFAPI_CRC_INDICATION_PDU_T *node = list->data;
    while (node != NULL) {
        size += sizeof(NFAPI_CRC_INDICATION_PDU);
        node = node->next;
    }

    // Allocate the buffer
    uint8_t *buf = malloc(size);
    assert(buf != NULL);

    // Serialize the PDUs into the buffer
    node = list->data;
    while (node != NULL) {
        memcpy(buf + size, &node->valid_rx_ue_information_tag, sizeof(uint32_t));
        memcpy(buf + size + 4, &node->rnti, sizeof(uint32_t));
        memcpy(buf + size + 8, &node->crcflag, sizeof(uint32_t));
        size += sizeof(NFAPI_CRC_INDICATION_PDU);
        node = node->next;
    }

    // Unlock the list
    pthread_mutex_unlock(&list->lock);

    *buffer = buf;
}

void deserialize(uint8_t **buffer, NFAPI_CRC_INDICATION_PDU_LIST *list) {
    // Lock the list
    pthread_mutex_lock(&list->lock);

    // Calculate the size of the buffer needed to store the PDUs
    int size = 0;
    NFAPI_CRC_INDICATION_PDU_T *node = list->data;
    while (node != NULL) {
        size += sizeof(NFAPI_CRC_INDICATION_PDU);
        node = node->next;
    }

    // Allocate the buffer
    uint8_t *buf = malloc(size);
    assert(buf != NULL);

    // Deserialize the PDUs from the buffer
    memcpy(buf, *buffer, size);
    node = list->data;
    while (node != NULL) {
        memcpy(&node->valid_rx_ue_information_tag, buf + size, sizeof(uint32_t));
        memcpy(&node->rnti, buf + size + 4, sizeof(uint32_t));
        memcpy(&node->crcflag, buf + size + 8, sizeof(uint32_t));
        size += sizeof(NFAPI_CRC_INDICATION_PDU);
        node = node->next;
    }

    // Unlock the list
    pthread_mutex_unlock(&list->lock);
}

int main() {
    NFAPI_CRC_INDICATION_PDU_LIST list;
    init(&list);

    uint8_t *buffer = NULL;

    // Serialize the list to a buffer
    serialize(&list, &buffer);

    // Deserialize the list from a buffer
    deserialize(&buffer, &list);

    return 0;
}']

