void ExecuteSQLCommand(List<string> values, Connection connection, string sqlCommand) {
    // Check if the list of values is empty or null
    if (values == null || values.Count == 0) {
        return;
    }

    // Initialize a variable to hold the number of parameters in the SQL command
    int numParams = values.Count;

    // Iterate over each value in the list and replace any placeholders with the corresponding parameter
    for (int i = 0; i < numParams; i++) {
        sqlCommand = sqlCommand.Replace("?", values[i]);
    }

    // Execute the SQL command using the database connection
    connection.ExecuteQuery(sqlCommand);
}
