// Structure to represent a record in the hash table
struct record {
    int id; // Data identifier
    long offset; // Pointer to offset in physical storage
};

// Union-Find data structure for dynamic memory management
typedef struct uf_t {
    int *parent; // Array of parent pointers
    int *rank; // Array of rank values
} uf_t;

// Initialize the Union-Find data structure with a given number of nodes
void init_uf(uf_t *uf, int num_nodes) {
    uf->parent = malloc(num_nodes * sizeof(int));
    uf->rank = malloc(num_nodes * sizeof(int));
    for (int i = 0; i < num_nodes; i++) {
        uf->parent[i] = i;
        uf->rank[i] = 1;
    }
}

// Find the root node of a given subtree
int find(uf_t *uf, int node) {
    if (uf->parent[node] != node) {
        // Path compression: set parent of child to parent of parent
        uf->parent[node] = find(uf, uf->parent[node]);
    }
    return uf->parent[node];
}

// Perform a union operation on two given nodes
void union(uf_t *uf, int node1, int node2) {
    int root1 = find(uf, node1);
    int root2 = find(uf, node2);
    if (root1 == root2) return;
    // Rank values are used to determine which subtree is larger
    if (uf->rank[root1] < uf->rank[root2]) {
        uf->parent[root1] = root2;
    } else if (uf->rank[root1] > uf->rank[root2]) {
        uf->parent[root2] = root1;
    } else {
        // Tie-breaking: increment the rank of the smaller subtree
        uf->parent[root2] = root1;
        uf->rank[root1]++;
    }
}

// Free memory allocated by the Union-Find data structure
void free_uf(uf_t *uf) {
    free(uf->parent);
    free(uf->rank);
}
```
