        free(records);
        printf("Error: Failed to resolve hostname %s\n", hostname);
        return -1;
    }

    // Fill in the offset and key arrays
    for (int i = 0; i < maxRecords; i++) {
        offsets[i] = i * sizeof(record);
        keys[i] = i + 1;
        records[i].value = i * i;
    }

    // Print the offset and key arrays
