    for (int i = 0; i < maxRecords; i++) {
        printf("%ld ", offsets[i]);
    }
    printf("\n");
    printf("Key array: ");
    for (int i = 0; i < maxRecords; i++) {
        printf("%d ", keys[i]);
    }
    printf("\n");

    // Print the record array
    printf("Record array: ");
    for (int i = 0; i < maxRecords; i++) {
        printf("{value: %d} ", records[i].value);
    }
    printf("\n");

    // Free memory
    free(offsets);
    free(keys);
    free(records);

    return 0;
}
