#include <stdlib.h>
#include <stdio.h>
#include <time.h>

struct record {
    int key;
    float measurement;
    char status;
    struct tm timestamp;
};

// Define a balanced binary search tree structure for storing records
typedef struct BSTNode {
    struct record* value;
    struct BSTNode* left;
    struct BSTNode* right;
} BSTNode;

// Create an array of records and a linked list to store the records in the BST
struct record** records = NULL;
size_t num_records = 0;
BSTNode* root = NULL;

// Function for generating random numbers within specified ranges
int generate_random(int min, int max) {
    // Use a seed derived from the current time and a unique process ID to ensure unpredictability
    srand(time(NULL) + getpid());
    return rand() % (max - min + 1) + min;
}

// Function for inserting a record into the BST
void insert_record(struct record* new_record) {
    // Generate a random key if none is provided
    if (!new_record->key) {
        new_record->key = generate_random(1, 100);
    }

    // Initialize the BST root node if it doesn't exist
    if (!root) {
        root = malloc(sizeof(BSTNode));
        root->value = NULL;
        root->left = NULL;
        root->right = NULL;
    }

    // Perform a binary search to find the appropriate location for the new record
    BSTNode* current = root;
    while (current) {
        if (new_record->key < current->value->key) {
            if (!current->left) {
                current->left = malloc(sizeof(BSTNode));
                current->left->value = NULL;
                current->left->left = NULL;
                current->left->right = NULL;
            }
            current = current->left;
        } else if (new_record->key > current->value->key) {
            if (!current->right) {
                current->right = malloc(sizeof(BSTNode));
                current->right->value = NULL;
                current->right->left = NULL;
                current->right->right = NULL;
            }
            current = current->right;
        } else {
            // Duplicate key found, abort insertion
            return;
        }
    }

    // Insert the new record into the BST at the appropriate location
    struct record* temp = malloc(sizeof(struct record));
    *temp = *new_record;
    current->value = temp;

    // Update the linked list and array of records to reflect the insertion
    if (!records) {
        records = malloc(sizeof(struct record*) * 1);
        records[0] = temp;
        num_records++;
    } else {
        struct record** new_records = realloc(records, sizeof(struct record*) * (num_records + 1));
        if (!new_records) return; // Handle out of memory error
        records = new_records;
        records[num_records++] = temp;
    }
}

// Function for deleting a record from the BST
void delete_record(int key) {
    // Find the node containing the target key in the BST
    BSTNode* current = root;
    while (current) {
        if (key < current->value->key) {
            current = current->left;
        } else if (key > current->value->key) {
            current = current->right;
        } else {
            break;
        }
    }

    // If the key is not found, return
    if (!current) return;

    // Remove the record from the BST and update the linked list and array of records
    struct record** to_delete = &(current->value);
    if (current == root) {
        // Update the root node if it contains the target key
        if (*to_delete != NULL) {
            free(*to_delete);
            *to_delete = NULL;
        }
    } else {
        // Remove the record from the BST and update the linked list and array of records
        struct record** prev = &root;
        while (*prev && *prev != current) {
            prev = &(*prev)->left;
        }
        if (*prev == current) {
            *prev = NULL;
        }
        free(*to_delete);
        *to_delete = NULL;
    }
    struct record** new_records = realloc(records, sizeof(struct record*) * (num_records - 1));
    if (!new_records) return; // Handle out of memory error
    records = new_records;
    num_records--;
}

// Function for looking up a record in the BST
struct record* find_record(int key) {
    // Find the node containing the target key in the BST
    BSTNode* current = root;
    while (current) {
        if (key < current->value->key) {
            current = current->left;
        } else if (key > current->value->key) {
            current = current->right;
        } else {
            return current->value;
        }
    }

    // If the key is not found, return NULL
    return NULL;
}

// Function for inserting multiple records into the BST at once
void insert_records(struct record* new_records[], size_t num_new_records) {
    // Insert each record individually to ensure no duplicates are allowed
    for (size_t i = 0; i < num_new_records; i++) {
        insert_record(&new_records[i]);
    }
}

// Function for deleting multiple records from the BST at once
void delete_records(int keys[]) {
    // Delete each record individually to ensure no duplicates are allowed
    for (size_t i = 0; i < num_new_records; i++) {
        delete_record(keys[i]);
    }
}

// Function for compacting memory allocations periodically to minimize fragmentation and improve performance
void compact() {
    // Compact the linked list of records by freeing any unused nodes
    BSTNode* current = root;
    while (current) {
        if (!current->value) {
            struct record** new_records = realloc(records, sizeof(struct record*) * (num_records - 1));
            if (!new_records) return; // Handle out of memory error
            records = new_records;
            num_records--;
        }
        current = current->left;
    }
}

// Function for logging insertions, deletions, and lookups to a file
void log(const char* action, struct record* record) {
    // Open the log file in append mode
    FILE* log_file = fopen("log.txt", "a");
    if (!log_file) return; // Handle error opening file

    // Write a new line to the log file with the action and record details
    char* date = get_date();
    fprintf(log_file, "%s %s %d\n", date, action, record->key);

    // Close the log file
    fclose(log_file);
}
