// Custom data structure for storing integer and floating-point values
typedef struct {
    int i;
    float f;
} kv_value;

// Key-value pair data store
typedef struct {
    char *key;
    kv_value value;
} kv_pair;

// Initialize the data store with a specific pattern instead of random values
void init_pattern(kv_pair *store, int num_entries, int pattern) {
    for (int i = 0; i < num_entries; i++) {
        // Generate key-value pairs based on the specified pattern
        switch (pattern) {
            case 1:
                store[i].key = "key";
                store[i].value.i = i + 1;
                store[i].value.f = sqrt((float)i);
                break;
            case 2:
                store[i].key = "key";
                store[i].value.i = i * 2;
                store[i].value.f = (float)i / 10;
                break;
        }
    }
}

// Validate input parameters and initialize the data store
int init_data_store(kv_pair **store, int num_entries, int pattern) {
    // Check if the maximum number of entries is within the predefined limit
    if (num_entries > MAX_ENTRIES) {
        fprintf(stderr, "Error: Maximum number of entries exceeds predefined limit\n");
        return -1;
    }

    // Allocate memory for the data store
    *store = malloc(sizeof(kv_pair) * num_entries);
    if (*store == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return -1;
    }

    // Initialize the data store with a specific pattern or random values
    if (pattern != 0) {
        init_pattern(*store, num_entries, pattern);
    } else {
        for (int i = 0; i < num_entries; i++) {
            (*store)[i].key = "key";
            (*store)[i].value.i = rand() % 100;
            (*store)[i].value.f = (float)rand() / RAND_MAX;
        }
    }

    return 0;
}

// Free memory allocated for the data store
void free_data_store(kv_pair *store, int num_entries) {
    free(store);
}

// Insert a new key-value pair into the data store
int insert_key_value(kv_pair *store, char *key, int value, float f_value) {
    // Check if the data store is full
    if (store == NULL) {
        return -1;
    }

    // Find an empty slot in the data store
    for (int i = 0; i < num_entries; i++) {
        if (store[i].key == NULL) {
            store[i].key = key;
            store[i].value.i = value;
            store[i].value.f = f_value;
            return 0;
        }
    }

    // Data store is full, return error
    return -1;
}

// Retrieve a key-value pair from the data store
int retrieve_key_value(kv_pair *store, char *key, int *value, float *f_value) {
    // Check if the key exists in the data store
    for (int i = 0; i < num_entries; i++) {
        if (strcmp(store[i].key, key) == 0) {
            *value = store[i].value.i;
            *f_value = store[i].value.f;
            return 0;
        }
    }

    // Key does not exist in the data store, return error
    return -1;
}

// Update a key-value pair in the data store
int update_key_value(kv_pair *store, char *key, int value, float f_value) {
    // Check if the key exists in the data store
    for (int i = 0; i < num_entries; i++) {
        if (strcmp(store[i].key, key) == 0) {
            store[i].value.i = value;
            store[i].value.f = f_value;
            return 0;
        }
    }

    // Key does not exist in the data store, return error
    return -1;
}

// Delete a key-value pair from the data store
int delete_key_value(kv_pair *store, char *key) {
    // Check if the key exists in the data store
    for (int i = 0; i < num_entries; i++) {
        if (strcmp(store[i].key, key) == 0) {
            store[i].key = NULL;
            return 0;
        }
    }

    // Key does not exist in the data store, return error
    return -1;
}

// Serialize the entire data store to disk in a binary format
int serialize_data_store(kv_pair *store, int num_entries) {
    FILE *fp = fopen("datastore.bin", "wb");
    if (fp == NULL) {
        return -1;
    }

    // Write the number of entries to the file
    fwrite(&num_entries, sizeof(int), 1, fp);

    // Write each key-value pair to the file
    for (int i = 0; i < num_entries; i++) {
        fwrite(store[i].key, strlen(store[i].key), 1, fp);
        fwrite(&store[i].value.i, sizeof(int), 1, fp);
        fwrite(&store[i].value.f, sizeof(float), 1, fp);
    }

    // Close the file
    fclose(fp);

    return 0;
}

// Deserialize the entire data store from disk in a binary format
int deserialize_data_store(kv_pair *store, int num_entries) {
    FILE *fp = fopen("datastore.bin", "rb");
    if (fp == NULL) {
        return -1;
    }

    // Read the number of entries from the file
    fread(&num_entries, sizeof(int), 1, fp);

    // Read each key-value pair from the file
    for (int i = 0; i < num_entries; i++) {
        store[i].key = malloc(strlen(store[i].key) + 1);
        fread(store[i].key, strlen(store[i].key), 1, fp);
        fread(&store[i].value.i, sizeof(int), 1, fp);
        fread(&store[i].value.f, sizeof(float), 1, fp);
    }

    // Close the file
    fclose(fp);

    return 0;
}
