// function to read numerical values from the network stream and store them in a dynamically resizable array
int read_data(const char* input, int max_points, int max_size) {
    // validate input parameters
    if (input == NULL || max_points <= 0 || max_size <= 0) {
        return -1;
    }

    // create a dynamic array to store the data points
    data_point* points = malloc(max_size * sizeof(data_point));
    if (points == NULL) {
        perror("malloc");
        return -2;
    }

    // allocate memory for metadata strings
    char** metadata = malloc(max_points * MAX_METADATA_SIZE);
    if (metadata == NULL) {
        perror("malloc");
        free(points);
        return -3;
    }

    // initialize the data point array and metadata strings
    for (int i = 0; i < max_size; i++) {
        points[i].value = NAN;
        points[i].range = 0.0f;
        points[i].timestamp = 0;
        metadata[i] = malloc(MAX_METADATA_SIZE);
    }

    // read the numerical values from the input stream and store them in the data point array
    int num_points = 0;
    while (num_points < max_size && fscanf(input, "%lf %f %d", &points[num_points].value, &points[num_points].range, &points[num_points].timestamp) == 3) {
        // allocate memory for the metadata string
        if (metadata[num_points] == NULL) {
            metadata[num_points] = malloc(MAX_METADATA_SIZE);
        }

        // read the metadata string from the input stream
        fgets(metadata[num_points], MAX_METADATA_SIZE, input);

        num_points++;
    }

    // resize the data point array if necessary
    if (num_points > max_points) {
        // allocate memory for a new data point array with twice the size of the current array
        data_point* new_points = realloc(points, 2 * max_size * sizeof(data_point));
        if (new_points == NULL) {
            perror("realloc");
            free(points);
            return -4;
        } else {
            points = new_points;
        }
    }

    // resize the metadata strings array if necessary
    for (int i = max_size; i < num_points; i++) {
        if (metadata[i] == NULL) {
            metadata[i] = malloc(MAX_METADATA_SIZE);
        }
    }

    // return the number of data points read and the data point array
    return num_points;
}

// function to free memory allocated for the data points and metadata strings
void free_data(data_point* points, int size) {
    if (points != NULL) {
        for (int i = 0; i < size; i++) {
            free(metadata[i]);
        }
        free(points);
    }
}

// function to log the number of times the data point array has been resized and the timestamps of these events in a separate file
void log_resize(const char* filename, int size) {
    FILE* fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("fopen");
        return;
    }

    // write the number of times the data point array has been resized and the timestamps of these events to the log file
    for (int i = 0; i < size; i++) {
        fprintf(fp, "%d %ld\n", i + 1, points[i].timestamp);
    }

    // close the log file
    fclose(fp);
}
