void allocate_and_initialize(size_t N, size_t minKey, size_t maxKey, size_t minValue, size_t maxValue, size_t memoryLimit, size_t* finalN) {
    // Check for invalid inputs
    if (N < 0 || minKey < 0 || maxKey < 0 || minValue < 0 || maxValue < 0 || memoryLimit < 0) {
        printf("Invalid input parameters\n");
        return;
    }

    // Allocate memory for the offset and key arrays
    size_t* offsets = (size_t*)malloc(N * sizeof(size_t));
    int* keys = (int*)malloc(N * sizeof(int));

    // Initialize the offset array with sequential integers starting from 0
    for (size_t i = 0; i < N; i++) {
        offsets[i] = i;
    }

    // Generate unique random integers within the specified range for the key array
    srand(time(NULL));
    for (size_t i = 0; i < N; i++) {
        keys[i] = minKey + rand() % (maxKey - minKey);
    }

    // Allocate memory for the record array and initialize it with random values within the specified range
    Record* records = (Record*)malloc(N * sizeof(Record));
    for (size_t i = 0; i < N; i++) {
        records[i].value = minValue + rand() % (maxValue - minValue);
    }

    // Ensure that the total memory usage does not exceed the predefined limit
    size_t memoryUsage = N * sizeof(size_t) + N * sizeof(int) + N * sizeof(Record);
    if (memoryUsage > memoryLimit) {
        printf("Memory limit exceeded\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    // Sort the records based on the values in the key array using a stable sorting algorithm
    qsort(records, N, sizeof(Record), compare_record_values);

    // Return the sorted array of records along with the final value of N used
    *finalN = N;
    return records;
}

// Define the compare function for sorting records based on their values in the key array
int compare_record_values(const void* a, const void* b) {
    const Record* recordA = (Record*)a;
    const Record* recordB = (Record*)b;
    return recordA->value - recordB->value;
}
