    if (!ptr) {
        // Handle allocation failure
    }
    return ptr;
}

typedef struct TrafficFlow {
    FlowIdentifier flow_id;
    PacketCounter packet_count;
    BandwidthRequest bandwidth_request;
} TrafficFlow;

// Array of TrafficFlow structures, with a custom allocator for memory management
TrafficFlow *traffic_flows = NULL;
size_t traffic_flows_len = 0;
size_t traffic_flows_capacity = 0;
pthread_mutex_t traffic_flows_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to safely populate a TrafficFlow structure with random values
void populate_traffic_flow(TrafficFlow *flow, size_t index) {
    // Generate random values for packet count and bandwidth request
    flow->packet_count = rand() % 501;
    double factor = (double)(rand() % 1000) / 1000.0;
    flow->bandwidth_request = (int)((flow->flow_id * factor) + rand() % 10);
}

// Function to safely add a TrafficFlow structure to the array
void add_traffic_flow(TrafficFlow *flow) {
    // Acquire lock on traffic flows array
    pthread_mutex_lock(&traffic_flows_lock);

    // Check if array needs to be resized
    if (traffic_flows_len == traffic_flows_capacity) {
        size_t new_capacity = (traffic_flows_capacity > 0) ? traffic_flows_capacity * 2 : 16;
        TrafficFlow *new_flows = my_alloc(sizeof(*new_flows) * new_capacity);

        // Copy existing flows to new array
        memcpy(new_flows, traffic_flows, sizeof(*traffic_flows) * traffic_flows_len);

        // Free old array and set new array
        free(traffic_flows);
        traffic_flows = new_flows;
        traffic_flows_capacity = new_capacity;
    }

    // Add new flow to array
    traffic_flows[traffic_flows_len++] = *flow;

    // Release lock on traffic flows array
    pthread_mutex_unlock(&traffic_flows_lock);
}

// Function to safely update a TrafficFlow structure in the array
void update_traffic_flow(size_t index, TrafficFlow *flow) {
    // Acquire lock on traffic flows array
    pthread_mutex_lock(&traffic_flows_lock);

    // Check if array needs to be resized
    if (index >= traffic_flows_len) {
        // Release lock on traffic flows array and return early
        pthread_mutex_unlock(&traffic_flows_lock);
        return;
    }

    // Update flow in array
    traffic_flows[index] = *flow;

    // Release lock on traffic flows array
    pthread_mutex_unlock(&traffic_flows_lock);
}

// Function to safely remove a TrafficFlow structure from the array
void remove_traffic_flow(size_t index) {
    // Acquire lock on traffic flows array
    pthread_mutex_lock(&traffic_flows_lock);

    // Check if array needs to be resized
    if (index >= traffic_flows_len) {
        // Release lock on traffic flows array and return early
        pthread_mutex_unlock(&traffic_flows_lock);
        return;
    }

    // Remove flow from array
    TrafficFlow *last_flow = &traffic_flows[--traffic_flows_len];
    traffic_flows[index] = *last_flow;

    // Release lock on traffic flows array
    pthread_mutex_unlock(&traffic_flows_lock);
}
