fn main() -> i32 {
    // Initialize the logging system
    INIT.call_once(|| {
        println!("Initializing logging system...");
    });

    let mut build_process = Command::new("rustc")
        .arg("-O")
        .arg("-o")
        .arg("myprogram")
        .arg("src/main.rs")
        .stderr(Stdio::inherit())
        .stdout(Stdio::piped());

