    let mut hook = SyncLazy::new(|| {
        println!("Caught error during compilation!");
        early_error();
    });
    build_process.catch_with_exit_code(&hook);

    // Measure the time taken for the compilation and record the resident set size before and after compilation
    let start = time::Instant::now();
    let exit_code = build_process.wait().unwrap();
    let end = time::Instant::now();
    println!("Compilation took {} seconds.", end - start);

    // Log a message if the compilation takes longer than 5 seconds
    if end - start > Duration::from_secs(5) {
        println!("Compilation took longer than expected!");
    }

    // Install a conditional logging mechanism to log messages based on a specific condition
    let mut log_msg = String::new();
    write!(log_msg, "Compilation took {} seconds.", end - start);
    if log_msg.len() > 0 {
        println!("{}", log_msg);
    }

    // Handle errors gracefully and adhere to best practices for Rust programming
