        while (pthread_cond_wait(&cond, &mutex) == 0) {
            printf("Record %d: Long offset = %ld, Int key = %d, Record value = %d, Metadata string = %s, Event timestamp = %lu\n", i, longOffset->offset, intKey->key, record->value, metadataString->metadata, eventTimestamp->timestamp);
        }
        pthread_mutex_unlock(&mutex);
    }

    // Handle external service outages or delays gracefully
    while (1) {
        // Check if external services are available
        if (isExternalServiceAvailable()) {
            break;
        }

        // Sleep for a short period to avoid overloading the system with frequent requests
        sleep(5);
    }

    // Handle edge cases, such as invalid input ranges or malformed metadata strings
    if (minValue > maxValue) {
        printf("Error: Invalid range of values specified. Exiting.\n");
        exit(1);
    }

    for (int i = 0; i < numRecords; i++) {
        if (strlen(metadataStrings[i].metadata) > MAX_METADATA_STRING_LENGTH) {
            printf("Error: Malformed metadata string specified. Exiting.\n");
            exit(1);
