// Define the function to create a new list
nfapi_crc_indication_list_t* nfapi_crc_indication_list_create(void) {
  nfapi_crc_indication_list_t* list = malloc(sizeof(nfapi_crc_indication_list_t));
  if (!list) {
    printf("Error: Failed to allocate memory for the NFAPI CRC indication list\n");
    return NULL;
  }
  list->size = 0;
  list->capacity = 16;
  list->elements = malloc(sizeof(nfapi_crc_indication_pdu_t) * list->capacity);
  if (!list->elements) {
    printf("Error: Failed to allocate memory for the NFAPI CRC indication elements\n");
    free(list);
    return NULL;
  }
  return list;
}

// Define the function to add a new element to the list
bool nfapi_crc_indication_list_add(nfapi_crc_indication_list_t* list, uint32_t rx_ue_information_tag, uint16_t rnti, uint8_t crc_indication_rel8_tag) {
  if (!list || !list->elements) {
    printf("Error: NFAPI CRC indication list or elements are NULL\n");
    return false;
  }
  // Check if the list is full and needs to be resized
  if (list->size == list->capacity) {
    size_t new_capacity = list->capacity * 2;
    nfapi_crc_indication_pdu_t* new_elements = realloc(list->elements, sizeof(nfapi_crc_indication_pdu_t) * new_capacity);
    if (!new_elements) {
      printf("Error: Failed to resize the NFAPI CRC indication list\n");
      return false;
    }
    list->elements = new_elements;
    list->capacity = new_capacity;
  }
  // Add the new element to the end of the list
  nfapi_crc_indication_pdu_t* new_element = &list->elements[list->size++];
  new_element->rx_ue_information_tag = rx_ue_information_tag;
  new_element->rnti = rnti;
  new_element->crc_indication_rel8_tag = crc_indication_rel8_tag;
  return true;
}

// Define the function to retrieve an element from the list by index
