  if (!list || !list->elements || index >= list->size) {
    printf("Error: NFAPI CRC indication list or elements are NULL or invalid index\n");
    return NULL;
  }
  return &list->elements[index];
}

// Define the function to update an element in the list by RNTI
bool nfapi_crc_indication_list_update(nfapi_crc_indication_list_t* list, uint16_t rnti, uint8_t crc_indication_rel8_tag) {
