  return false;
}

// Define the function to delete an element from the list by index
bool nfapi_crc_indication_list_delete(nfapi_crc_indication_list_t* list, size_t index) {
  if (!list || !list->elements || index >= list->size) {
    printf("Error: NFAPI CRC indication list or elements are NULL or invalid index\n");
    return false;
  }
  // Shift the elements after the deleted element to fill the gap
  for (size_t i = index + 1; i < list->size; i++) {
    memcpy(&list->elements[i - 1], &list->elements[i], sizeof(nfapi_crc_indication_pdu_t));
  }
  // Decrement the size of the list and reallocate memory if necessary
  list->size--;
  if (list->size < list->capacity / 2) {
    size_t new_capacity = list->capacity / 2;
    nfapi_crc_indication_pdu_t* new_elements = realloc(list->elements, sizeof(nfapi_crc_indication_pdu_t) * new_capacity);
    if (!new_elements) {
      printf("Error: Failed to resize the NFAPI CRC indication list\n");
      return false;
    }
    list->elements = new_elements;
    list->capacity = new_capacity;
  }
  return true;
}

// Define the function to destroy the list and free its memory
void nfapi_crc_indication_list_destroy(nfapi_crc_indication_list_t* list) {
