// Function to create a new TCP connection
tcp_connection* create_tcp_connection(const char* client_ip, uint16_t port) {
    assert(client_ip != NULL && strlen(client_ip) == 15); // Check for valid client IP address
    tcp_connection* conn = (tcp_connection*) malloc(sizeof(tcp_connection));
    if (!conn) {
        fprintf(stderr, "Error: unable to allocate memory for TCP connection\n");
        return NULL;
    }
    memcpy(conn->client_ip, client_ip, 16);
    conn->port = port;
    conn->status = false; // Set initial status to disconnected
    HEADER(conn) = create_custom_tcp_header(); // Create a new custom TCP header structure
    return conn;
}

// Function to destroy a TCP connection
void destroy_tcp_connection(tcp_connection* conn) {
