struct NFAPI_CRC_INDICATION_LIST {
    size_t capacity;  // maximum number of elements in the list
    size_t count;     // current number of elements in the list
    NFAPI_CRC_INDICATION_PDU_T* elements;  // array of elements
};

struct NFAPI_CRC_INDICATION_LIST* createNFAPI_CRC_INDICATION_LIST(size_t capacity) {
    struct NFAPI_CRC_INDICATION_LIST* list = malloc(sizeof(struct NFAPI_CRC_INDICATION_LIST));
    list->capacity = capacity;
    list->count = 0;
    list->elements = calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    return list;
}

void destroyNFAPI_CRC_INDICATION_LIST(struct NFAPI_CRC_INDICATION_LIST* list) {
    free(list->elements);
    free(list);
}

int pushBackNFAPI_CRC_INDICATION_PDU(struct NFAPI_CRC_INDICATION_LIST* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (list->count == list->capacity) {
        // resize the list by 25% to accommodate new elements
        size_t newCapacity = list->capacity * 1.25;
        NFAPI_CRC_INDICATION_PDU_T* newElements = realloc(list->elements, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (newElements == NULL) {
            // failed to resize the list, handle error gracefully
            return -1;
        }
        list->capacity = newCapacity;
        list->elements = newElements;
    }
    list->elements[list->count++] = *pdu;
    return 0;
}

int popFrontNFAPI_CRC_INDICATION_PDU(struct NFAPI_CRC_INDICATION_LIST* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (list->count == 0) {
        return -1;  // empty list
    }
    *pdu = list->elements[0];
    memmove(list->elements, list->elements + 1, (list->count - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->count--;
    return 0;
}

void iterateNFAPI_CRC_INDICATION_LIST(struct NFAPI_CRC_INDICATION_LIST* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    for (size_t i = 0; i < list->count; i++) {
        callback(&list->elements[i]);
    }
}

void queryAndModifyIndividualElement(struct NFAPI_CRC_INDICATION_LIST* list, size_t index, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    if (index >= list->count) {
        return;  // invalid index
    }
    callback(&list->elements[index]);
}

void threadSafePushBackNFAPI_CRC_INDICATION_PDU(struct NFAPI_CRC_INDICATION_LIST* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list->mutex);
    pushBackNFAPI_CRC_INDICATION_PDU(list, pdu);
    pthread_cond_signal(&list->cond);
    pthread_mutex_unlock(&list->mutex);
}

void threadSafePopFrontNFAPI_CRC_INDICATION_PDU(struct NFAPI_CRC_INDICATION_LIST* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list->mutex);
    while (list->count == 0) {
        pthread_cond_wait(&list->cond, &list->mutex);
    }
    popFrontNFAPI_CRC_INDICATION_PDU(list, pdu);
    pthread_mutex_unlock(&list->mutex);
}
