    UEContext ueContext;
    struct UEContextNode *next;
} UEContextNode;

// Define a function to initialize the linked list and allocate memory for it
void initUEList() {
    // Create an empty linked list
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    UEContextNode *head = NULL;
    size_t maxNodes = 1000; // maximum number of nodes in the list
    size_t maxMemory = 1024 * 1024 * 50; // maximum amount of memory to allocate (50 MB)

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&lock);

    // Allocate memory for the linked list
    head = malloc(sizeof(UEContextNode));
    if (head == NULL) {
        printf("Error: unable to allocate memory for UE list\n");
        exit(1);
    }

    // Initialize the head node
    head->next = NULL;

    // Unlock the mutex and return
    pthread_mutex_unlock(&lock);
}

// Define a function to insert a new UE context structure into the linked list
void insertUEContext(uint32_t ueId, uint32_t rnti, void *packetInfo) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&lock);

    // Allocate memory for the new node
    UEContextNode *newNode = malloc(sizeof(UEContextNode));
    if (newNode == NULL) {
        printf("Error: unable to allocate memory for new UE context structure\n");
        exit(1);
    }

    // Initialize the new node with the given parameters
    newNode->ueContext.ueId = ueId;
    newNode->ueContext.rnti = rnti;
    newNode->ueContext.packetInfo = packetInfo;

    // Add the new node to the end of the linked list
    UEContextNode *currNode = head;
    while (currNode->next != NULL) {
        currNode = currNode->next;
    }
    currNode->next = newNode;

    // Update the total number of nodes and allocated memory if necessary
    size_t numNodes = 1;
    size_t memUsage = sizeof(UEContextNode);
    while (currNode->next != NULL) {
        currNode = currNode->next;
        numNodes++;
        memUsage += sizeof(UEContextNode);
    }
    if (memUsage > maxMemory || numNodes > maxNodes) {
        // Garbage collection: reclaim unused resources
        UEContextNode *garbageNode = head;
        while (garbageNode != NULL) {
            UEContextNode *nextGarbageNode = garbageNode->next;
            free(garbageNode);
            garbageNode = nextGarbageNode;
        }
        // Update the head node and maximum memory usage
        head = malloc(sizeof(UEContextNode));
        if (head == NULL) {
            printf("Error: unable to allocate memory for new UE context structure\n");
            exit(1);
        }
        maxMemory -= sizeof(UEContextNode);
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&lock);
}

