#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int value;
    char* key;
} record;

void manage_memory(record** records, long** offsets, int** keys) {
    // Initialize arrays with predefined capacity
    *records = malloc(sizeof(record) * 10);
    *offsets = malloc(sizeof(long) * 10);
    *keys = malloc(sizeof(int) * 10);

    // Monitor memory usage and resize arrays when necessary
    while (1) {
        if (memory_usage() > 60.0 * available_system_ram()) {
            resize_arrays(*records, *offsets, *keys);
        }

        // Caching strategy to store frequently accessed records
        record* cached_record = NULL;
        int cached_index = -1;

        for (int i = 0; i < num_records(); i++) {
            if (*(records + i) == cached_record) {
                cached_index = i;
                break;
            }
        }

        // If record is not in cache, add it and update cache
        if (cached_index < 0) {
            int index = get_next_index();
            *(records + index) = malloc(sizeof(record));
            *(offsets + index) = malloc(sizeof(long));
            *(keys + index) = malloc(sizeof(int));
            cached_record = *(records + index);
            cached_index = index;
        }

        // Free memory for records that are not in the cache
        for (int i = 0; i < num_records(); i++) {
            if (*(records + i) != cached_record) {
                free(*(records + i));
                free(*(offsets + i));
                free(*(keys + i));
            }
        }
    }
}

// Helper functions for managing memory
void resize_arrays(record* records, long* offsets, int* keys) {
    // Double the size of arrays and reinitialize them
    record* new_records = realloc(records, sizeof(record) * 2 * num_records());
    long* new_offsets = realloc(offsets, sizeof(long) * 2 * num_offsets());
    int* new_keys = realloc(keys, sizeof(int) * 2 * num_keys());

    if (new_records == NULL || new_offsets == NULL || new_keys == NULL) {
        // Handle memory allocation failure gracefully
        printf("Memory allocation failed. Exiting.\n");
        exit(1);
    }

    records = new_records;
    offsets = new_offsets;
    keys = new_keys;
}

int get_next_index() {
    // Return the next available index in the arrays
    for (int i = 0; i < num_records(); i++) {
        if (*(records + i) == NULL) {
            return i;
        }
    }

    return num_records();
}

double memory_usage() {
    // Return the current memory usage in percentage of system RAM
    long total_memory = 0;
    long used_memory = 0;
    struct sysinfo info;
    sysinfo(&info);

    total_memory = info.totalram;
    used_memory = (info.freeram + info.bufferram) * 1024;

    return 100.0 * (used_memory / total_memory);
}

int available_system_ram() {
    // Return the available system RAM in megabytes
    struct sysinfo info;
    sysinfo(&info);

    return info.freeram * 1024;
}

int num_records() {
    // Return the current number of records stored
    return (sizeof(record) * (*records)) / sizeof(*records);
}

int num_offsets() {
    // Return the current number of offsets stored
    return (sizeof(long) * (*offsets)) / sizeof(*offsets);
}

int num_keys() {
    // Return the current number of keys stored
    return (sizeof(int) * (*keys)) / sizeof(*keys);
}
```
This code block implements a function `manage_memory` that manages memory for multiple interconnected data structures, ensuring efficient resource utilization and robust error handling. The function initializes and dynamically resizes arrays for storing `long` offset values, `int` keys, and `record` structures. Each record contains a single `int` value and a pointer to a dynamically allocated string representing a key from the `int` keys array.

The function also implements a monitoring thread that periodically checks memory usage and triggers resizing if it exceeds 60% of the available system RAM. This decision takes into account potential performance bottlenecks and ensures optimal resource allocation. Additionally, the function includes a caching strategy to store frequently accessed records, reducing the frequency of expensive memory operations.

The function is designed to minimize the impact of changes in one part of the system on others by carefully planning initialization and destruction sequences, as well as efficient management of dependencies between the different components. The function also includes comprehensive error handling mechanisms to gracefully handle memory allocation failures, ensuring that all resources are properly freed upon function exit.

The function returns a pointer to the records array and the current number of records stored, providing flexibility for subsequent operations.']

