// Recursively traverse the DOM tree using the callback function to test each element against the configuration criteria
char *recursive_traverse(char *buffer, int limit, struct config *config, pthread_mutex_t *lock) {
    // Initialize a list for storing matching elements
    char **list = NULL;
    size_t len = 0;

    // Iterate over the DOM tree using the callback function to test each element against the configuration criteria
    for (char *node = buffer; node != NULL; node = node[1]) {
