    // Check if the resulting string exceeds the maximum size limit
    int length = strlen(buffer);
    for (int i = 0; i < len; i++) {
        length += strlen(list[i]);
        if (length > limit) {
            free(list);
            return NULL;
        }
    }

    // Append a slash to the end of the string and return the modified buffer
