}

// define a function to add a new subdirectory to the file system
void add_subdir(fs* fs, char* name) {
    // allocate memory for the new directory entry
    dir_entry* entry = malloc(sizeof(dir_entry));
    if (entry == NULL) {
        fprintf(stderr, "Error: failed to add subdirectory\n");
        exit(1);
    }
    // update the file system's root directory and number of entries
    if (fs->root == NULL) {
        fs->root = malloc(sizeof(root_dir));
        if (fs->root == NULL) {
            fprintf(stderr, "Error: failed to allocate memory for new root directory\n");
            exit(1);
        }
        // initialize the fields of the root directory
        fs->root->name = name;
        fs->root->num_entries = 0;
        fs->root->entries = NULL;
    }
    // add the new entry to the list of entries in the root directory
    fs->root->entries = realloc(fs->root->entries, (fs->root->num_entries + 1) * sizeof(dir_entry*));
    if (fs->root->entries == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for new directory entry\n");
        exit(1);
    }
    fs->root->entries[fs->root->num_entries++] = entry;
}

// define a function to traverse the file system and print all the files and directories
void traverse_file_system(fs* fs) {
    // check if the file system is empty
    if (fs->root == NULL) {
        printf("The file system is empty\n");
        return;
    }
    // initialize a stack to keep track of the directories we need to traverse
    struct dir_stack* stack = malloc(sizeof(struct dir_stack));
    if (stack == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for directory stack\n");
        exit(1);
    }
    // add the root directory to the stack
    push(stack, fs->root);
    // traverse the file system and print all the files and directories
    while (!isEmpty(stack)) {
        dir_entry* entry = pop(stack);
        if (entry == NULL) {
            fprintf(stderr, "Error: failed to pop directory entry from stack\n");
            exit(1);
        }
        // print the name of the current directory or file
        printf("%s\n", entry->name);
        // add all subdirectories and files to the stack for traversal
        if (entry->is_directory) {
            int i;
            for (i = 0; i < entry->num_entries; i++) {
                push(stack, entry->entries[i]);
            }
        }
    }
    // free the stack
    free(stack);
}

int main() {
    fs* fs = create_file_system();
    add_dir_entry(fs, "Documents", 1024);
    add_subdir(fs, "Pictures");
    add_subdir(fs, "Videos");
    add_file(fs, "notes.txt", 512);
    traverse_file_system(fs);
    return 0;
}
