// Structure to represent a node in the dynamic linked list
typedef struct UEContext {
    int ueId;
    int rnti;
    void* packetInfo; // dynamically allocated buffer for packet data
} UEContext;

// Function to initialize and manage the dynamic linked list of UEContext structures
int initUEDynamicList(int maxNodes, size_t maxMemSize) {
    if (maxNodes <= 0 || maxMemSize <= 0) {
        return -1; // error: invalid input parameters
    }

    // initialize the linked list head and tail pointers to NULL
    UEContext* head = NULL;
    UEContext* tail = NULL;

    // allocate memory for the linked list management data structure
    int* memPtr = (int*)malloc(maxNodes * sizeof(UEContext));
    if (!memPtr) {
        return -1; // error: failed to allocate memory
    }

    // initialize the memory management data structure
    for (int i = 0; i < maxNodes; ++i) {
        memPtr[i] = 0; // mark all nodes as unused
    }

    // set the maximum number of nodes and allocated memory size
    int maxNodes_ = maxNodes;
    size_t maxMemSize_ = maxMemSize;

    // create a mutex for synchronizing node insertion and deletion operations
    pthread_mutex_t* mutex = (pthread_mutex_t*)malloc(sizeof(pthread_mutex_t));
    if (!mutex) {
        return -1; // error: failed to allocate memory for the mutex
    }
    pthread_mutex_init(mutex, NULL);

    // create a condition variable for notifying threads when node insertion or deletion operations are completed
    pthread_cond_t* cond = (pthread_cond_t*)malloc(sizeof(pthread_cond_t));
    if (!cond) {
        return -1; // error: failed to allocate memory for the condition variable
    }
    pthread_cond_init(cond, NULL);

    // create a logging mechanism to track statistics about list operations
    Logging* log = (Logging*)malloc(sizeof(Logging));
    if (!log) {
        return -1; // error: failed to allocate memory for the logging mechanism
    }
    log->enabled = false;

    // create a rate-limiting module to enforce a maximum allowed size for the total allocated memory for the list
    RateLimiting* rateLimit = (RateLimiting*)malloc(sizeof(RateLimiting));
    if (!rateLimit) {
        return -1; // error: failed to allocate memory for the rate-limiting module
    }
    rateLimit->maxMemSize = maxMemSize_;
    rateLimit->currentMemSize = 0;
    rateLimit->enabled = false;

    // create a garbage collection mechanism to reclaim unused resources when the list is cleared
    GarbageCollection* gc = (GarbageCollection*)malloc(sizeof(GarbageCollection));
    if (!gc) {
        return -1; // error: failed to allocate memory for the garbage collection mechanism
    }
    gc->enabled = false;

    // create a streaming data pipeline that delivers real-time updates to the list from multiple sources
    StreamingDataPipeline* stream = (StreamingDataPipeline*)malloc(sizeof(StreamingDataPipeline));
    if (!stream) {
        return -1; // error: failed to allocate memory for the streaming data pipeline
    }
    stream->enabled = false;

    // return the initialized linked list management data structure
    return 0;
}

// Function to insert a new node into the dynamic linked list of UEContext structures
int insertUENode(UEContext* node) {
    if (!node) {
        return -1; // error: invalid input parameter
    }

    pthread_mutex_lock(&mutex);

    // check if the maximum number of nodes has been reached
    if (numNodes >= maxNodes_) {
        pthread_mutex_unlock(&mutex);
        return -1; // error: maximum number of nodes has been reached
    }

    // check if the total allocated memory size has exceeded the maximum allowed size
    if (currentMemSize + node->packetInfoSize > maxMemSize_) {
        pthread_mutex_unlock(&mutex);
        return -1; // error: total allocated memory size has exceeded the maximum allowed size
    }

    // allocate memory for the new node and copy its data from the input parameter
    int* memPtr = (int*)malloc(sizeof(UEContext));
    if (!memPtr) {
        pthread_mutex_unlock(&mutex);
        return -1; // error: failed to allocate memory for the new node
    }
    *memPtr = 0;
    memcpy((void*)memPtr, (void*)node, sizeof(UEContext));

    // update the linked list management data structure with the new node
    numNodes++;
    currentMemSize += node->packetInfoSize;
    if (!head) {
        head = tail = memPtr;
    } else {
        tail->next = memPtr;
        tail = memPtr;
    }

    pthread_mutex_unlock(&mutex);

    // log statistics about the list operation
    if (log->enabled) {
        log->insert++;
    }

    // notify threads waiting for node insertion operations to complete
    pthread_cond_signal(cond);

    return 0;
}

// Function to delete a node from the dynamic linked list of UEContext structures
int deleteUENode(UEContext* node) {
    if (!node) {
        return -1; // error: invalid input parameter
    }

    pthread_mutex_lock(&mutex);

    // search for the node in the linked list management data structure and remove it
    int* prevMemPtr = NULL;
    int* memPtr = head;
    while (memPtr) {
        if (*(UEContext*)memPtr == *node) {
            if (!prevMemPtr) {
                head = tail = memPtr->next;
            } else {
                prevMemPtr->next = memPtr->next;
                if (tail == memPtr) {
                    tail = prevMemPtr;
                }
            }
            free(memPtr);
            numNodes--;
            currentMemSize -= node->packetInfoSize;
            break;
        }
        prevMemPtr = memPtr;
        memPtr = memPtr->next;
    }

    // if the node was not found in the linked list management data structure, return an error
    if (!memPtr) {
        pthread_mutex_unlock(&mutex);
        return -1; // error: node not found in the dynamic linked list of UEContext structures
    }

    pthread_mutex_unlock(&mutex);

    // log statistics about the list operation
    if (log->enabled) {
        log->delete++;
    }

    return 0;
}
