        // Validate the user credentials
        if (strcmp(session->username, "admin") && strcmp(session->password, "123456")) {
            printf("Error: Invalid user credentials\n");
            session->connection_status = DISCONNECTED;
            return;
        }
    }
}

// Function to terminate inactive sessions to optimize resource usage
void terminateInactiveSessions() {
    time_t current_time = time(NULL);
    for (int i = 0; i < max_sessions; i++) {
        struct UserSession *session = &session_list[i];
        if (session->connection_status == DISCONNECTED) {
            continue;
        }
        time_t last_activity = session->last_activity;
        if ((current_time - last_activity) > 300) { // 5 minutes in seconds
            printf("Terminating inactive session %d\n", i);
            session->connection_status = DISCONNECTED;
        }
    }
}

