// Structure to store records with unique keys and associated offset values
typedef struct record {
    int key;
    long offset;
} record_t;

// Function to dynamically manage multiple instances of a data structure used to store and retrieve records
int record_manager(record_t **records, size_t *capacity, size_t threshold) {
    // Check if the array needs to be resized
    if (*capacity < threshold) {
        // Reallocate memory for the array and hash table
        *records = realloc(*records, sizeof(record_t) * 2 * *capacity);
        *hash = realloc(*hash, sizeof(record_t *) * 2 * *capacity);

        if (*records == NULL || *hash == NULL) {
            // Handle memory allocation failure gracefully
            return -1;
        }

        // Resize the array and hash table
        *capacity *= 2;
    }

    // Acquire a lock to prevent concurrent access to the data structures
    pthread_mutex_lock(&lock);

    // Insert a new record into the array and hash table
    (*records)[*num_records].key = key;
    (*records)[*num_records].offset = offset;

    // Store the record in the hash table using its unique key
    (*hash)[key] = &(*records)[*num_records];

    // Increment the number of records
    *num_records += 1;

    // Release the lock to allow other threads to access the data structures simultaneously
    pthread_mutex_unlock(&lock);

    return 0;
}
