    // Generate a random integer within the specified range
    srand(time(NULL));
    int rand_int = rand() % (key - 1) + 1;

    // Populate the record structure with the generated integer and metadata
    rec->key = rand_int;
    snprintf(rec->metadata, sizeof(rec->metadata), "%d", rand_int);
