void* init_records(size_t num_records) {
    // Calculate the total memory required for the records and metadata
    size_t mem_required = (num_records * sizeof(record_t)) + (sizeof(metadata_t));

    // Allocate memory for the records and metadata
    void* mem = malloc(mem_required);
    if (!mem) {
        fprintf(stderr, "Failed to allocate memory for %zu records\n", num_records);
        return NULL;
    }

    // Initialize the metadata structure
    metadata_t* meta = (metadata_t*)mem;
    meta->num_records = num_records;
    meta->initialized = true;

    // Initialize each record in the records array
    record_t* recs = (record_t*)(meta + 1);
    for (size_t i = 0; i < num_records; i++) {
        init_record(recs + i, i + 1);
    }

    return mem;
}

