#include <openssl/aes.h>
#include <openssl/sha.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

#define MAX_RECORDS 1024
#define IV_LEN 16
#define KEY_LEN 32

typedef struct {
    long offset;
    int key;
} record_t;

void init_aes(const char* password, const char* iv) {
    // Derive encryption key from password using SHA-1 hashing
    unsigned char key[KEY_LEN];
    SHA1((unsigned char*)password, strlen(password), (unsigned char*)key);

    // Validate IV length against expected standards
    if (strlen(iv) != IV_LEN) {
        fprintf(stderr, "Invalid initialization vector length\n");
        return;
    }

    // Initialize AES-256-CBC cipher with derived key and IV
    AES_KEY aes_key;
    AES_set_encrypt_key(key, KEY_LEN * 8, &aes_key);
    AES_cbc_encrypt((unsigned char*)iv, (unsigned char*)iv, IV_LEN, &aes_key, NULL, NULL);

    // Initialize theme cache arrays
    record_t* offset_array = malloc(sizeof(record_t) * MAX_RECORDS);
    int* key_array = malloc(sizeof(int) * MAX_RECORDS);

    if (offset_array == NULL || key_array == NULL) {
        fprintf(stderr, "Failed to allocate memory for theme cache arrays\n");
        return;
    }

    // Initialize offset and key arrays with default values
    memset(offset_array, 0, sizeof(record_t) * MAX_RECORDS);
    memset(key_array, -1, sizeof(int) * MAX_RECORDS);

    // Set theme cache directory to default if not set
    char* theme_cache_dir = getenv("THEME_CACHE_DIR");
    if (theme_cache_dir == NULL) {
        theme_cache_dir = "/tmp/theme-cache";
    }

    // Parse PNG file from cache root directory and store in theme cache
    char png_file[256];
    sprintf(png_file, "%s/%d.png", theme_cache_dir, 0);
    FILE* png = fopen(png_file, "rb");
    if (png == NULL) {
        fprintf(stderr, "Failed to open PNG file: %s\n", strerror(errno));
        return;
    }

    // Verify PNG file integrity and handle potential errors
    int error = 0;
    if (fseek(png, 0, SEEK_END) == -1 || (long)ftell(png) != sizeof(record_t)) {
        fprintf(stderr, "Invalid PNG file format\n");
        error = 1;
    } else if (fseek(png, 0, SEEK_SET) == -1 || !feof(png)) {
        fprintf(stderr, "Failed to seek in PNG file: %s\n", strerror(errno));
        error = 1;
    } else {
        record_t* theme = malloc(sizeof(record_t));
        if (theme == NULL) {
            fprintf(stderr, "Failed to allocate memory for theme data\n");
            error = 1;
        } else {
            // Read PNG file and store in theme cache
            int num_read = fread(theme, sizeof(record_t), 1, png);
            if (num_read != 1) {
                fprintf(stderr, "Failed to read from PNG file: %s\n", strerror(errno));
                error = 1;
            } else {
                offset_array[0] = *theme;
                key_array[0] = theme->key;
            }
        }
    }

    // Cleanup and return
    if (error) {
        fclose(png);
        free(offset_array);
        free(key_array);
    } else {
        fclose(png);
        return offset_array, key_array;
    }
}
