```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    int key;
    long offset;
} Record;

// Define the hash table implementation (open addressing)
typedef struct {
    size_t capacity;
    size_t size;
    Record* records;
} HashTable;

// Define the synchronization mechanism (mutexes)
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize an array of records and a hash table
void initRecords(int num_records, Record** records, HashTable** hash_table) {
    // Allocate memory for the record array
    *records = (Record*) malloc(num_records * sizeof(Record));
    if (*records == NULL) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for the hash table
    *hash_table = (HashTable*) malloc(sizeof(HashTable));
    if (*hash_table == NULL) {
        perror("Failed to allocate memory for hash table");
        exit(EXIT_FAILURE);
    }

    // Initialize the hash table with the capacity of the record array
    (*hash_table)->capacity = num_records;
    (*hash_table)->size = 0;
    (*hash_table)->records = *records;

    // Initialize the records with default values
    for (int i = 0; i < num_records; i++) {
        (*records)[i].key = -1;
        (*records)[i].offset = -1;
    }
}

// Function to resize the record array and hash table if necessary
void resizeRecords(Record** records, HashTable* hash_table) {
    // If the current capacity is exceeded, double the size of the record array and hash table
    if (hash_table->size >= hash_table->capacity) {
        int new_capacity = 2 * hash_table->capacity;
        Record* new_records = (Record*) realloc(*records, new_capacity * sizeof(Record));
        if (new_records == NULL) {
            perror("Failed to resize record array");
            exit(EXIT_FAILURE);
        }
        hash_table->capacity = new_capacity;
        *records = new_records;
    }
}

// Function to add a record to the hash table
void addRecord(int key, long offset, Record** records, HashTable* hash_table) {
    // Acquire a lock on the mutex before modifying the data structure
    pthread_mutex_lock(&mutex);

    // Check if the key already exists in the hash table
    for (int i = 0; i < hash_table->size; i++) {
        if ((*records)[i].key == key) {
            (*records)[i].offset = offset;
            pthread_mutex_unlock(&mutex);
            return;
        }
    }

    // If the key does not exist, add it to the end of the record array and hash table
    int index = hash_table->size++;
    (*records)[index].key = key;
    (*records)[index].offset = offset;

    resizeRecords(records, hash_table);

    // Release the lock on the mutex after modifying the data structure
    pthread_mutex_unlock(&mutex);
}

// Function to get a record from the hash table by key
Record* getRecord(int key, Record** records, HashTable* hash_table) {
    // Acquire a lock on the mutex before modifying the data structure
    pthread_mutex_lock(&mutex);

    // Check if the key exists in the hash table
    for (int i = 0; i < hash_table->size; i++) {
        if ((*records)[i].key == key) {
            pthread_mutex_unlock(&mutex);
            return &((*records)[i]);
        }
    }

    // If the key does not exist, return NULL
    pthread_mutex_unlock(&mutex);
    return NULL;
}

// Function to update a record in the hash table by key
void updateRecord(int key, long offset, Record** records, HashTable* hash_table) {
    // Acquire a lock on the mutex before modifying the data structure
    pthread_mutex_lock(&mutex);

    // Check if the key exists in the hash table
    for (int i = 0; i < hash_table->size; i++) {
        if ((*records)[i].key == key) {
            (*records)[i].offset = offset;
            break;
        }
    }

    resizeRecords(records, hash_table);

    // Release the lock on the mutex after modifying the data structure
    pthread_mutex_unlock(&mutex);
}

// Function to remove a record from the hash table by key
void removeRecord(int key, Record** records, HashTable* hash_table) {
    // Acquire a lock on the mutex before modifying the data structure
    pthread_mutex_lock(&mutex);

    // Check if the key exists in the hash table
    for (int i = 0; i < hash_table->size; i++) {
        if ((*records)[i].key == key) {
            (*records)[i].key = -1;
            (*records)[i].offset = -1;
            break;
        }
    }

    // If the key does not exist, return NULL
    resizeRecords(records, hash_table);

    // Release the lock on the mutex after modifying the data structure
    pthread_mutex_unlock(&mutex);
}
