#define MIN_CRC_INDICATION_PDU_T_COUNT 32
#define MAX_CRC_INDICATION_PDU_T_COUNT 512
#define MIN_NFAPI_CRC_INDICATION_REL8_TAG 0
#define MAX_NFAPI_CRC_INDICATION_REL8_TAG 255
#define MIN_RX_UE_INFORMATION_TAG 1
#define MAX_RX_UE_INFORMATION_TAG 63
#define MIN_RNTI 0
#define MAX_RNTI 65535

