} NFAPI_CRC_INDICATION_PDU_T;

int generate_filename(char *path, int max_length) {
    // Sanity check input parameters
    if (path == NULL || max_length <= 0) {
        syslog(LOG_ERR, "Invalid input parameter in generate_filename()");
        return -1;
    }

    char *directory = strtok(path, "/");
    char *file = strtok(NULL, "/");

    // Calculate the hash of the directory path
    unsigned long hash = 5381;
    for (int i = 0; i < strlen(directory); i++) {
        hash = ((hash << 5) + hash) ^ directory[i];
    }
    char hash_str[MAX_HASH_LENGTH + 1];
    snprintf(hash_str, MAX_HASH_LENGTH + 1, "%lu", hash);

    // Generate the new filename by modifying the existing extension
    int dir_len = strlen(directory);
    int file_len = strlen(file);
    char *new_filename = (char *)malloc(dir_len + file_len + MAX_HASH_LENGTH + 1);
    memcpy(new_filename, directory, dir_len);
    memcpy(new_filename + dir_len, ".", 1);
    memcpy(new_filename + dir_len + 1, hash_str, MAX_HASH_LENGTH);
    memcpy(new_filename + dir_len + MAX_HASH_LENGTH + 1, file, file_len);
    new_filename[max_length] = '\0';

    // Truncate the filename if it exceeds the maximum length
    int new_len = strlen(new_filename);
    if (new_len > max_length) {
        syslog(LOG_ERR, "New filename exceeds maximum length in generate_filename()");
        free(new_filename);
        return -1;
    }

    // Replace the original filename with the new one
    memcpy(path, new_filename, new_len + 1);

    // Clean up memory
    free(new_filename);

    return 0;
}

int populate_crc_indication_pdu_t(char *path, int max_length) {
    // Sanity check input parameters
    if (path == NULL || max_length <= 0) {
        syslog(LOG_ERR, "Invalid input parameter in populate_crc_indication_pdu_t()");
        return -1;
    }

    int ret = generate_filename(path, max_length);
    if (ret != 0) {
        // If generating the filename failed, log an error and exit
        syslog(LOG_ERR, "Failed to generate filename in populate_crc_indication_pdu_t()");
        return ret;
    }

    // Parse the filename for the RX_UE_INFORMATION_TAG and RNTI
    char *rx_ue_information_tag_str = strtok(path, "_");
    char *rnti_str = strtok(NULL, "_");
    if (rx_ue_information_tag_str == NULL || rnti_str == NULL) {
        syslog(LOG_ERR, "Failed to parse filename in populate_crc_indication_pdu_t()");
        return -1;
    }

    int rx_ue_information_tag = atoi(rx_ue_information_tag_str);
    if (rx_ue_information_tag < MIN_RX_UE_INFORMATION_TAG ||
            rx_ue_information_tag > MAX_RX_UE_INFORMATION_TAG) {
        syslog(LOG_ERR, "Invalid RX_UE_INFORMATION_TAG in populate_crc_indication_pdu_t()");
        return -1;
    }

    int rnti = atoi(rnti_str);
    if (rnti < MIN_RNTI || rnti > MAX_RNTI) {
        syslog(LOG_ERR, "Invalid RNTI in populate_crc_indication_pdu_t()");
        return -1;
    }

    // Generate a random CRCFLAG within predefined constraints
    int crcflag = rand() % (MAX_NFAPI_CRC_INDICATION_REL8_TAG - MIN_NFAPI_CRC_INDICATION_REL8_TAG + 1) +
            MIN_NFAPI_CRC_INDICATION_REL8_TAG;

    // Create an array of NFAPI_CRC_INDICATION_PDU_T structures and populate them with the parsed values
    int count = rand() % (MAX_CRC_INDICATION_PDU_T_COUNT - MIN_CRC_INDICATION_PDU_T_COUNT + 1) +
            MIN_CRC_INDICATION_PDU_T_COUNT;
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * count);
    for (int i = 0; i < count; i++) {
        pdu[i].rx_ue_information.rx_ue_information_rel8.rnti = rnti;
        pdu[i].crc_flag = crcflag;
    }

    // Clean up memory
    free(pdu);

    return 0;
}

int execute_command(char *path) {
    // Sanity check input parameter
    if (path == NULL) {
        syslog(LOG_ERR, "Invalid path in execute_command()");
        return -1;
    }

    // Execute the command using system() function
    int ret = system(path);
    if (ret != 0) {
        syslog(LOG_ERR, "Command execution failed in execute_command()");
        return -1;
    }

    return 0;
}

int main(int argc, char **argv) {
    // Sanity check input parameters
    if (argc != 3) {
        syslog(LOG_ERR, "Invalid number of arguments in main()");
        return -1;
    }

    int ret = populate_crc_indication_pdu_t(argv[1], atoi(argv[2]));
    if (ret != 0) {
        // If populating the CRC indication PDU failed, log an error and exit
        syslog(LOG_ERR, "Failed to populate CRC indication PDU in main()");
        return -1;
    }

    ret = execute_command("nfapi-simulator -c config.json");
    if (ret != 0) {
        // If executing the command failed, log an error and exit
