// Structure to store file metadata
typedef struct {
    char* filename;
    size_t size;
    time_t modification_time;
} file_metadata;

// Global variables
const int MAX_NUM_FILES = 1000; // Maximum number of files to process
int num_files = 0; // Current number of files processed
file_metadata* metadata_pool = NULL; // Pool of pre-allocated file metadata structures
bool success = true; // Flag indicating whether the function succeeded or failed

// Function to read a dynamic stream of file paths from standard input and construct a dictionary that maps filenames to their respective file sizes and last modification times
file_metadata* process_files() {
    char line[1024]; // Temporary buffer for reading lines from stdin
    while (fgets(line, sizeof(line), stdin)) {
        if (num_files >= MAX_NUM_FILES) {
            success = false;
            break;
        }

        // Parse the file path and retrieve its metadata
        char* filename = strtok(line, " ");
        struct stat file_info;
        if (stat(filename, &file_info) == -1) {
            success = false;
            break;
        }

        // Allocate memory for the file metadata structure
        file_metadata* metadata = malloc(sizeof(file_metadata));
        if (!metadata) {
            success = false;
            break;
        }

        // Initialize the file metadata structure with the parsed data
        metadata->filename = filename;
        metadata->size = file_info.st_size;
        metadata->modification_time = file_info.st_mtime;

        // Add the file metadata to the pool
        if (metadata_pool) {
            metadata->next = metadata_pool->next;
            metadata_pool->next = metadata;
        } else {
            metadata_pool = metadata;
        }

        num_files++;
    }

    // Free any allocated memory if an error occurred
    if (!success) {
        file_metadata* current = metadata_pool;
        while (current) {
            free(current->filename);
            current = current->next;
        }

        free(metadata_pool);
    }

    // Return a pointer to the first element of the file metadata array, along with a boolean indicating success or failure
    return (success) ? metadata_pool : NULL;
}
