// Define the structure to store CRC indication data
typedef struct NFAPI_CRC_INDICATION_PDU {
    uint8_t crc; // 0-32 bits, depending on radio technology
    char *userData; // optional user data
} NFAPI_CRC_INDICATION_PDU_T;

// Define the schema for validating input events
typedef struct NFAPI_EVENT_SCHEMA {
    uint8_t crcLen;
    char *userData; // optional user data
} NFAPI_EVENT_SCHEMA_T;

// Define the error codes
#define SUCCESS 0
#define ERROR_INVALID_ARGUMENT -1
#define ERROR_FILE_OPEN -2
#define ERROR_FILE_READ -3
#define ERROR_MEMORY_ALLOCATION -4
#define ERROR_CRC_COMPUTATION -5
#define ERROR_SCHEMA_VALIDATION -6
#define ERROR_THREAD_CREATION -7
#define ERROR_THREAD_JOINING -8

// Define the command line arguments
#define INPUT_DIRECTORY "input"
#define OUTPUT_DIRECTORY "output"
#define USAGE_INFORMATION "Usage: ./crc-indication-processor [options]\nOptions:\n\t--input <input directory>\n\t--output <output directory>\n\t--max-structures <maximum number of structures allowed in memory>\n\t--max-size <maximum size of each structure>\n\t--verbose (enable verbose output)"

// Define the logging levels
#define LOG_LEVEL_INFO 0
#define LOG_LEVEL_WARNING 1
#define LOG_LEVEL_ERROR 2

// Define the maximum number of structures allowed in memory
#define MAX_STRUCTURES 10000

// Define the maximum size of each structure
#define MAX_SIZE 100000

// Function to validate a given string against a regular expression
int validateString(const char *string, const char *regex) {
    int result = -1;
    regex_t regexObj;
    if (regcomp(&regexObj, regex, REG_EXTENDED)) {
        return -1;
    }
    if (!regexec(&regexObj, string, 0, NULL, 0)) {
        result = 0;
    }
    regfree(&regexObj);
    return result;
}

// Function to compute CRC for a given string
uint8_t computeCRC(const char *string) {
    uint8_t crc = 0;
    size_t length = strlen(string);
    for (size_t i = 0; i < length; i++) {
        crc ^= string[i];
    }
    return crc;
}

// Function to validate a given event structure against the schema
int validateEvent(const NFAPI_CRC_INDICATION_PDU *event, const NFAPI_EVENT_SCHEMA *schema) {
    int result = -1;
    if (validateString(event->userData, schema->userData)) {
        return ERROR_SCHEMA_VALIDATION;
    }
    uint8_t computedCrc = computeCRC(event->userData);
    if (computedCrc != event->crc) {
        return ERROR_CRC_COMPUTATION;
    }
    result = 0;
    return result;
}

// Function to populate an array of structures from a single input file
int populateArray(NFAPI_CRC_INDICATION_PDU **array, const char *filename) {
    int result = ERROR_INVALID_ARGUMENT;
    FILE *inputFile = fopen(filename, "r");
    if (inputFile == NULL) {
        return ERROR_FILE_OPEN;
    }
    // Read each line from the file and validate against the schema
    while (!feof(inputFile)) {
        char *line = NULL;
        size_t len = 0;
        if (getline(&line, &len, inputFile) < 0) {
            break;
        }
        // Skip comments and metadata tags
        if (!validateString(line, "^#.*|^@.*") && strlen(line) > schema->userData.length) {
            NFAPI_CRC_INDICATION_PDU *event = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
            if (event == NULL) {
                return ERROR_MEMORY_ALLOCATION;
            }
            event->userData = strdup(line);
            event->crc = computeCRC(event->userData);
            *array = realloc(*array, sizeof(NFAPI_CRC_INDICATION_PDU) * (count + 1));
            if (*array == NULL) {
                return ERROR_MEMORY_ALLOCATION;
            }
            (*array)[count] = event;
            count++;
        }
    }
    fclose(inputFile);
    result = SUCCESS;
    return result;
}

// Function to populate an array of structures from multiple input files concurrently
int populateArrayAsync(NFAPI_CRC_INDICATION_PDU **array, const char *directory) {
    int result = ERROR_INVALID_ARGUMENT;
    DIR *inputDir = opendir(directory);
    if (inputDir == NULL) {
        return ERROR_FILE_OPEN;
    }
    struct dirent *file;
    pthread_t thread[MAX_STRUCTURES];
    while ((file = readdir(inputDir)) != NULL) {
        if (!strcmp(file->d_name, ".") || !strcmp(file->d_name, "..")) {
            continue;
        }
        pthread_create(&thread[count], NULL, populateArray, &array);
    }
    for (size_t i = 0; i < count; i++) {
        pthread_join(thread[i], NULL);
    }
    closedir(inputDir);
    result = SUCCESS;
    return result;
}

// Main function to populate an array of structures from either a single input file or multiple files in a directory
int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <input>\n", argv[0]);
        return 1;
    }
    const char *input = argv[1];
    NFAPI_CRC_INDICATION_PDU **array = NULL;
    if (isDirectory(input)) {
        populateArrayAsync(&array, input);
    } else {
        populateArray(&array, input);
    }
}
