#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
    char* identifier;
} record_t;

void free_record(record_t* record) {
    if (record->identifier != NULL) {
        free(record->identifier);
    }
    free(record);
}

int deserialize_records(FILE* file, record_t** records, int num_records) {
    pthread_mutex_lock(&mutex);
    fseek(file, 0, SEEK_SET);
    for (int i = 0; i < num_records; i++) {
        record_t* record = malloc(sizeof(record_t));
        if (fread(record, sizeof(record_t), 1, file) != 1) {
            free_record(record);
            pthread_mutex_unlock(&mutex);
            return -1;
        }
        records[i] = record;
    }
    pthread_mutex_unlock(&mutex);
    return 0;
}

int serialize_records(FILE* file, record_t** records, int num_records) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_records; i++) {
        if (fwrite(records[i], sizeof(record_t), 1, file) != 1) {
            free_record(records[i]);
            pthread_mutex_unlock(&mutex);
            return -1;
        }
    }
    pthread_mutex_unlock(&mutex);
    return 0;
}

int add_record(record_t* record, FILE* file) {
    pthread_mutex_lock(&mutex);
    if (serialize_records(file, records, num_records + 1) != 0) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }
    records[num_records] = record;
    num_records++;
    pthread_mutex_unlock(&mutex);
    return 0;
}

int remove_record(int index, FILE* file) {
    pthread_mutex_lock(&mutex);
    if (index >= num_records) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }
    record_t* record = records[index];
    for (int i = index + 1; i < num_records; i++) {
        records[i - 1] = records[i];
    }
    num_records--;
    serialize_records(file, records, num_records);
    pthread_mutex_unlock(&mutex);
    return 0;
}

int find_largest_record(FILE* file) {
    int largest_index = -1;
    long largest_offset = -1;
    for (int i = 0; i < num_records; i++) {
        record_t* record = records[i];
        if (record->offset > largest_offset) {
            largest_offset = record->offset;
            largest_index = i;
        }
    }
    return largest_index;
}

int find_smallest_record(FILE* file) {
    int smallest_index = -1;
    long smallest_offset = LONG_MAX;
    for (int i = 0; i < num_records; i++) {
        record_t* record = records[i];
        if (record->offset < smallest_offset) {
            smallest_offset = record->offset;
            smallest_index = i;
        }
    }
    return smallest_index;
}

int iterate_forward(FILE* file, int (*callback)(record_t*, void*), void* data) {
    for (int i = 0; i < num_records; i++) {
        record_t* record = records[i];
        if ((*callback)(record, data) == -1) {
            return -1;
        }
    }
    return 0;
}

int iterate_backward(FILE* file, int (*callback)(record_t*, void*), void* data) {
    for (int i = num_records - 1; i >= 0; i--) {
        record_t* record = records[i];
        if ((*callback)(record, data) == -1) {
            return -1;
        }
    }
    return 0;
}

int free_records(FILE* file) {
    for (int i = 0; i < num_records; i++) {
        record_t* record = records[i];
        free_record(record);
    }
    free(records);
    return 0;
}

int main() {
    FILE* file = fopen("records.bin", "w+b");
    if (file == NULL) {
        printf("Failed to open records file\n");
        return -1;
    }
    record_t** records = malloc(sizeof(record_t*) * 1024);
    int num_records = 0;
    int max_num_records = 1024;
    mutex_init(&mutex, NULL);
    while (true) {
        char input[64];
        scanf("%s", input);
        if (strcmp(input, "add") == 0) {
            record_t* record = malloc(sizeof(record_t));
            record->offset = rand() % 100;
            record->key = rand();
            record->identifier = malloc(16);
            strcpy(record->identifier, "Random string");
            add_record(record, file);
        } else if (strcmp(input, "remove") == 0) {
            int index;
            scanf("%d", &index);
            remove_record(index, file);
        } else if (strcmp(input, "largest") == 0) {
            int largest_index = find_largest_record(file);
            record_t* largest_record = records[largest_index];
            printf("Largest offset: %ld\n", largest_record->offset);
        } else if (strcmp(input, "smallest") == 0) {
            int smallest_index = find_smallest_record(file);
            record_t* smallest_record = records[smallest_index];
            printf("Smallest offset: %ld\n", smallest_record->offset);
        } else if (strcmp(input, "iterate") == 0) {
            char direction[16];
            scanf("%s", direction);
            int (*callback)(record_t*, void*);
            if (strcmp(direction, "forward") == 0) {
                callback = print_record;
            } else if (strcmp(direction, "backward") == 0) {
                callback = print_record;
            } else {
                printf("Invalid direction\n");
                continue;
            }
            int data;
            scanf("%d", &data);
            iterate_forward(file, callback, (void*)&data);
        } else if (strcmp(input, "exit") == 0) {
            break;
        } else {
            printf("Invalid input\n");
        }
    }
    mutex_destroy(&mutex);
    free_records(file);
    fclose(file);
    return 0;
}
