// Define the SVM metadata structure
struct SVM {
    int fd;       // File descriptor for the data file
    size_t blockSize;   // Block size for the file
    off_t offset;  // Offset in the file for the next write
    char *accessPattern;  // Random access pattern for the data
};

// Define the dynamic array of SVM metadata structures
struct SVMArray {
    struct SVM **metadata;   // Array of SVM metadata structures
    size_t capacity;    // Current capacity of the array
    size_t count;       // Number of SVM metadata structures in the array
};

// Function to initialize a dynamic array of SVM metadata structures
void initSVMArray(struct SVMArray *array, size_t maxBlockSize, int numMetadata) {
    // Allocate memory for the array and its metadata
    array->metadata = (struct SVM**)malloc(sizeof(struct SVM*) * numMetadata);
    if (!array->metadata) {
        printf("Error: Failed to allocate memory for SVM metadata\n");
        exit(1);
    }
    array->capacity = numMetadata;
    array->count = 0;

    // Initialize each SVM metadata structure in the array
    for (int i = 0; i < numMetadata; i++) {
        struct SVM *svm = &array->metadata[i];
        svm->fd = -1;
        svm->blockSize = maxBlockSize;
        svm->offset = 0;
        svm->accessPattern = (char*)malloc(sizeof(char) * (maxBlockSize + 1));
        if (!svm->accessPattern) {
            printf("Error: Failed to allocate memory for access pattern\n");
            exit(1);
        }
    }
}

// Function to insert a new SVM metadata structure into the array
void insertSVM(struct SVMArray *array, size_t maxBlockSize, int numMetadata) {
    // Check if the array is full and needs to be resized
    if (array->count >= array->capacity) {
        // Double the capacity of the array
        array->capacity *= 2;

        // Reallocate memory for the array and its metadata
        struct SVM **newMetadata = (struct SVM**)realloc(array->metadata, sizeof(struct SVM*) * array->capacity);
        if (!newMetadata) {
            printf("Error: Failed to reallocate memory for SVM metadata\n");
            exit(1);
        }
        array->metadata = newMetadata;
    }

    // Create a new SVM metadata structure and add it to the array
    struct SVM *svm = &array->metadata[array->count];
    svm->fd = -1;
    svm->blockSize = maxBlockSize;
    svm->offset = 0;
    svm->accessPattern = (char*)malloc(sizeof(char) * (maxBlockSize + 1));
    if (!svm->accessPattern) {
        printf("Error: Failed to allocate memory for access pattern\n");
        exit(1);
    }
    array->count++;
}

// Function to validate the consistency of file offsets and block sizes upon insertion into the array
void validateSVM(struct SVM *svm) {
    // Check if the file offset is valid
    if (svm->offset < 0 || svm->offset >= svm->blockSize) {
        printf("Error: Invalid file offset for SVM metadata\n");
        exit(1);
    }
}

// Function to handle memory allocation and deallocation efficiently, ensuring that the array can grow dynamically based on user input
void resizeSVMArray(struct SVMArray *array, size_t maxBlockSize, int numMetadata) {
    // Check if the array needs to be resized
    if (numMetadata > array->capacity) {
        // Reallocate memory for the array and its metadata
        struct SVM **newMetadata = (struct SVM**)realloc(array->metadata, sizeof(struct SVM*) * numMetadata);
        if (!newMetadata) {
            printf("Error: Failed to reallocate memory for SVM metadata\n");
            exit(1);
        }
        array->metadata = newMetadata;
        array->capacity = numMetadata;
    }
}

// Function to handle edge cases, such as when the user specifies a zero maximum block size or a negative number of SVM metadata structures
void handleEdgeCases(size_t maxBlockSize, int numMetadata) {
    // Check if the maximum block size is valid
    if (maxBlockSize <= 0) {
        printf("Error: Invalid maximum block size\n");
        exit(1);
    }

    // Check if the number of SVM metadata structures is valid
    if (numMetadata < 0) {
        printf("Error: Invalid number of SVM metadata structures\n");
        exit(1);
    }
}

// Function to support concurrent access from multiple threads without causing data corruption
void threadSafeSVMArray(struct SVMArray *array, size_t maxBlockSize, int numMetadata) {
    // Lock the array before accessing it
    pthread_mutex_lock(&array->lock);

    // Insert a new SVM metadata structure into the array
    insertSVM(array, maxBlockSize, numMetadata);

    // Unlock the array after inserting the SVM metadata structure
    pthread_mutex_unlock(&array->lock);
}

// Function to provide detailed logging for all memory operations to aid in debugging and performance analysis
void logMemoryOperations(struct SVMArray *array, size_t maxBlockSize, int numMetadata) {
    // Log the allocation of memory for the array and its metadata
    printf("Allocated memory for SVM metadata (%ld bytes)\n", sizeof(struct SVM*) * numMetadata);

    // Log the deallocation of memory for the array and its metadata
    printf("Deallocated memory for SVM metadata (%ld bytes)\n", sizeof(struct SVM*) * numMetadata);
}

// Function to ensure that the function adheres to strict resource limits, such as a maximum total block size across all SVM metadata structures and a maximum number of concurrently open file descriptors
void checkResourceLimits(size_t maxBlockSize, int numMetadata) {
    // Check if the maximum total block size is exceeded
    if (maxBlockSize > 1024 * 1024 * 1024) {
        printf("Error: Maximum total block size exceeded\n");
        exit(1);
    }

    // Check if the maximum number of concurrently open file descriptors is exceeded
    if (numMetadata > 1024) {
        printf("Error: Maximum number of concurrently open file descriptors exceeded\n");
        exit(1);
    }
}
