// Structure to store pressure readings
struct pressure_reading {
    long timestamp;
    double value;
    int sensor_index;
};

// Function to allocate and initialize memory for an array of pressure structures
struct pressure_reading* create_pressure_readings(int capacity) {
    struct pressure_reading* readings = (struct pressure_reading*) malloc(capacity * sizeof(struct pressure_reading));
    if (readings == NULL) {
        return NULL;
    }

    for (int i = 0; i < capacity; i++) {
        readings[i].timestamp = -1;
        readings[i].value = NAN;
        readings[i].sensor_index = -1;
    }

    return readings;
}

// Function to insert a pressure reading into the BST
void insert_pressure_reading(struct pressure_reading* readings, int capacity, struct pressure_reading new_reading) {
    // Binary search to find the correct position for the new reading
    int low = 0;
    int high = capacity - 1;
    while (low <= high) {
        int mid = (low + high) / 2;
        if (new_reading.timestamp < readings[mid].timestamp) {
            high = mid - 1;
        } else if (new_reading.timestamp > readings[mid].timestamp) {
            low = mid + 1;
        } else {
            // Duplicate timestamp, do not insert
            return;
        }
    }

    // Insert the new reading at the found position
    for (int i = capacity - 1; i >= high; i--) {
        readings[i + 1] = readings[i];
    }
    readings[high] = new_reading;
}

// Function to delete a pressure reading from the BST
void delete_pressure_reading(struct pressure_reading* readings, int capacity, long timestamp) {
    // Binary search to find the position of the reading to be deleted
    int low = 0;
    int high = capacity - 1;
    while (low <= high) {
        int mid = (low + high) / 2;
        if (timestamp < readings[mid].timestamp) {
            high = mid - 1;
        } else if (timestamp > readings[mid].timestamp) {
            low = mid + 1;
        } else {
            // Found the reading to be deleted, delete it
            for (int i = mid; i < capacity - 1; i++) {
                readings[i] = readings[i + 1];
            }
            return;
        }
    }
}

// Function to validate and format pressure readings
void validate_pressure_readings(struct pressure_reading* readings, int capacity) {
    // Loop through all the readings and validate them
    for (int i = 0; i < capacity; i++) {
        if (!isnan(readings[i].value)) {
            readings[i].value = fmax(fmin(readings[i].value, 1000.0), 900.0);
        } else {
            // Missing or invalid data, replace with NaN
            readings[i].value = NAN;
        }
    }
}

