    double maximum = NAN;
    double sum = 0.0;
    int count = 0;

    // Loop through all the readings within the given time range and calculate the summaries
    for (int i = 0; i < capacity; i++) {
        if (readings[i].timestamp >= start_time && readings[i].timestamp <= end_time) {
            count++;
            sum += readings[i].value;
            minimum = isnan(minimum) ? readings[i].value : fmin(minimum, readings[i].value);
            maximum = isnan(maximum) ? readings[i].value : fmax(maximum, readings[i].value);
        }
    }

    // Calculate the average pressure reading
    double average = isnan(sum) || count == 0 ? NAN : sum / count;

    printf("Minimum pressure reading: %f\n", minimum);
    printf("Maximum pressure reading: %f\n", maximum);
    printf("Average pressure reading: %f\n", average);
}

