// Function to populate the arrays with random values
void populate_arrays(int num_records) {
    srand(time(NULL));

    // Allocate memory for the offset array
    offset_array = (long *)malloc(num_records * sizeof(long));
    if (!offset_array) {
        printf("Error: unable to allocate memory for offset array\n");
        return;
    }

    // Allocate memory for the key array
    key_array = (int *)malloc(num_records * sizeof(int));
    if (!key_array) {
        printf("Error: unable to allocate memory for key array\n");
        free(offset_array);
        return;
    }

    // Allocate memory for the record array
    record_array = (record_t **)malloc(num_records * sizeof(record_t));
    if (!record_array) {
        printf("Error: unable to allocate memory for record array\n");
        free(offset_array);
        free(key_array);
        return;
    }

    // Populate the arrays with random values
    for (int i = 0; i < num_records; i++) {
        offset_array[i] = rand() % 10000;
        key_array[i] = rand() % 10000;
        record_array[i] = malloc(sizeof(record_t));
        if (!record_array[i]) {
            printf("Error: unable to allocate memory for record %d\n", i);
            free(offset_array);
            free(key_array);
            free(record_array);
            return;
        }
    }
}

// Function to deallocate the arrays
