    // Free the memory allocated for the offset array
    if (offset_array) {
        free(offset_array);
        offset_array = NULL;
    }

    // Free the memory allocated for the key array
    if (key_array) {
        free(key_array);
        key_array = NULL;
    }

    // Free the memory allocated for the record array
    if (record_array) {
        for (int i = 0; i < num_records; i++) {
            if (record_array[i]) {
                free(record_array[i]);
            }
        }
        free(record_array);
        record_array = NULL;
    }
}
