    task->data = malloc(data_size);
    if (task->data == NULL) {
        free(task->name);
        free(task);
        return NULL;
    }

    // Validate the priority level within a specified range
    if (priority < 0 || priority > 10) {
        free(task->data);
        free(task->name);
        free(task);
        return NULL;
    }

    return task;
}
