import os
import time
from statistics import mean
from collections import defaultdict

def getFileMetadataDict(file_paths):
    start = time.time()
    file_metadata_dict = {}
    for file in file_paths:
        try:
            stat = os.stat(file)
            filename = os.path.basename(file)
            filesize = stat.st_size
            mtime = stat.st_mtime
            permission = stat.st_mode & 0o777
            file_metadata = FileMetadata()
            file_metadata.filename = filename
            file_metadata.filesize = filesize
            file_metadata.mtime = mtime
            file_metadata.permission = permission
            file_metadata_dict[file] = file_metadata
        except OSError as e:
            if e.errno != errno.ENOENT:
                raise
    elapsed = time.time() - start
    print(f"Processed {len(file_paths)} files in {elapsed} seconds")
    return file_metadata_dict

def getFileExtensionStats(file_metadata_dict):
    start = time.time()
    extension_stats = defaultdict(list)
    for file, metadata in file_metadata_dict.items():
        extension = os.path.splitext(metadata.filename)[1]
        extension_stats[extension].append(metadata.filesize)
    elapsed = time.time() - start
    print(f"Processed {len(file_metadata_dict)} files in {elapsed} seconds")
    return extension_stats

def getAverageFileSize(extension_stats):
    average_size = 0
    for size in extension_stats.values():
        average_size += sum(size) / len(size)
    return average_size / len(extension_stats)

def getMostCommonPermission(file_metadata_dict):
    permissions = []
    for file, metadata in file_metadata_dict.items():
        permissions.append(metadata.permission)
    most_common_permission = max(set(permissions), key=lambda x: permissions.count(x))
    return most_common_permission

def main():
