    file_metadata_dict = getFileMetadataDict(file_paths)
    extension_stats = getFileExtensionStats(file_metadata_dict)
    average_size = getAverageFileSize(extension_stats)
    most_common_permission = getMostCommonPermission(file_metadata_dict)
    print(f"Average file size: {average_size}")
    print(f"Most common permission: {most_common_permission}")

