// Define the record structure
struct record {
    long offset;
    int key;
    double value;
};

// Define a hash table data structure to store records
typedef struct {
    size_t capacity; // Maximum number of records in the table
    size_t count; // Current number of records in the table
    struct record* records; // Array of records
} hash_table_t;

// Initialize a new hash table with a given capacity
hash_table_t* hash_table_init(size_t capacity) {
    assert(capacity > 0);

    // Allocate memory for the hash table structure and initialize its fields
    hash_table_t* table = (hash_table_t*)malloc(sizeof(hash_table_t));
    table->capacity = capacity;
    table->count = 0;
    table->records = (struct record*)malloc(capacity * sizeof(struct record));

    // Initialize the records array with NULL values
    for (size_t i = 0; i < capacity; i++) {
        table->records[i].offset = -1;
        table->records[i].key = -1;
        table->records[i].value = NAN;
    }

    return table;
}

// Add a new record to the hash table
bool hash_table_add(hash_table_t* table, long offset, int key, double value) {
    assert(table != NULL);

    // Check if the table is full and needs to be resized
    if (table->count == table->capacity) {
        return false;
    }

    // Find an empty slot in the records array
    size_t index = 0;
    while (index < table->capacity && table->records[index].offset != -1) {
        index++;
    }

    if (index == table->capacity) {
        return false;
    }

    // Add the new record to the table and increment the count
    table->records[index].offset = offset;
    table->records[index].key = key;
    table->records[index].value = value;
    table->count++;

    return true;
}

// Remove a record from the hash table by its key
bool hash_table_remove(hash_table_t* table, int key) {
    assert(table != NULL);

    // Find the index of the record with the given key
    size_t index = 0;
    while (index < table->count && table->records[index].key != key) {
        index++;
    }

    if (index == table->count) {
        return false;
    }

    // Shift the records in the table down one position to fill the gap
    for (size_t i = index; i < table->count - 1; i++) {
        table->records[i] = table->records[i + 1];
    }

    // Decrement the count of records in the table
    table->count--;

    return true;
}

// Look up a record in the hash table by its key
struct record* hash_table_lookup(hash_table_t* table, int key) {
    assert(table != NULL);

    // Find the index of the record with the given key
    size_t index = 0;
    while (index < table->count && table->records[index].key != key) {
        index++;
    }

    if (index == table->count) {
        return NULL;
    }

    // Return the record at the found index
    return &table->records[index];
}

// Clean up a hash table and free its memory
void hash_table_destroy(hash_table_t* table) {
    assert(table != NULL);

    // Free the records array
    free(table->records);

    // Reset the fields of the table structure to their default values
    table->capacity = 0;
    table->count = 0;
    table->records = NULL;
}
```
This implementation uses a hash table data structure with an array of records, each containing an `offset`, `key`, and `value` field. The hash table is resized when it becomes full to prevent memory fragmentation and handle potential memory allocation failures gracefully. The function also implements thread-safe operations for adding, removing, and looking up records in the table.

Note that this implementation does not provide any error handling or logging mechanisms, which can be added as necessary depending on the specific requirements of the system."]

