bool init_and_populate_linked_list(LTE_Transport_Channel** head) {
    // Fetch necessary configuration parameters for pdcch_mask, pdsch_mask, and harq_process_id from external data source
    int pdcch_mask = fetch_pdcch_mask();
    if (pdcch_mask == -1) {
