    // Populate linked list with new TransportChannelInfo structures
    LTE_Transport_Channel* curr = NULL;
    for (int i = 0; i < 10; i++) {
        // Allocate memory for new TransportChannelInfo structure
        TransportChannelInfo* info = malloc(sizeof(TransportChannelInfo));
        if (info == NULL) {
            return false;
        }

        // Initialize TransportChannelInfo structure with fetched configuration parameters
        info->pdcch_mask = pdcch_mask;
        info->pdsch_mask = pdsch_mask;
        info->harq_process_id = harq_process_id;

