        if ((*stats_array)[i].transaction_age <= transaction_age_threshold && (*stats_array)[i].recent_transaction_frequency >= recent_transaction_frequency_threshold && (*stats_array)[i].weighted_sum >= weighted_sum_threshold) {
            filtered_stats_count++;
