    int i;
    for (i = 0; i < num_packets; i++) {
        if (!strcmp(packet_array[i].source_ip, ip) || !strcmp(packet_array[i].dest_ip, ip)) {
            memmove(&packet_array[i], &packet_array[i + 1], (num_packets - i - 1) * sizeof(Packet));
            num_packets--;
            break;
        }
    }
}

