int validateIpChecksum(unsigned char *payload, size_t length) {
    // Calculate the IP header checksum and compare it to the input checksum
    uint16_t calculatedChecksum = calculateIpHeaderChecksum(payload, length);
    if (calculatedChecksum == 0) {
        return 0;
    } else {
        return calculatedChecksum - ipPacket.checksum;
    }
}

// Function to calculate an IP header checksum
uint16_t calculateIpHeaderChecksum(unsigned char *payload, size_t length) {
    // Initialize the checksum variable with the IP version and header length fields
    uint32_t checksum = (ipPacket.version << 12 | ipPacket.headerLength << 8);

    // Process each byte of the IP packet payload
    for (size_t i = 0; i < length; ++i) {
        checksum += *payload++;
        if (checksum > 0xFFFF) {
            checksum -= 0xFFFF;
        }
    }

    // Return the calculated checksum
    return checksum & 0xFFFF;
}
