  if (!list) {
    printf("Failed to allocate memory for CRC indication PDU list\n");
    return NULL;
  }

  // Initialize the cache structure
  pdu_cache_t *cache = (pdu_cache_t*)malloc(sizeof(pdu_cache_t) * NFAPI_MAX_UE);
  if (!cache) {
