  list[list_size++].rnti = pdu->rnti;
  list[list_size++].crc_indication_rel8_tag = pdu->crc_indication_rel8_tag;
  list[list_size++].crcflag = false;
}

// Function to remove a PDU from the list
void nfapi_crc_indication_remove(nfapi_crc_indication_pdu_t *pdu) {
  // Find the index of the PDU in the list
  int idx = -1;
  for (int i = 0; i < list_size; i++) {
    if (list[i].rx_ue_information_tag == pdu->rx_ue_information_tag && list[i].rnti == pdu->rnti) {
      idx = i;
      break;
    }
  }

  // If the PDU is found, remove it from the list and update the cache
  if (idx != -1) {
    nfapi_crc_indication_pdu_t *removed = &list[idx];
    list[idx] = list[--list_size];
    cache[cache_size++].pdu = removed;
  }
}

// Function to get a PDU from the list by RNTI
nfapi_crc_indication_pdu_t* nfapi_crc_indication_get(uint32_t rnti) {
  // Find the index of the PDU in the list
  int idx = -1;
  for (int i = 0; i < list_size; i++) {
    if (list[i].rnti == rnti) {
      idx = i;
      break;
    }
  }

  // If the PDU is found, return it from the cache
  if (idx != -1) {
    nfapi_crc_indication_pdu_t *pdu = &list[idx];
    pdu->in_use = true;
    return pdu;
  }

  // If the PDU is not found, create a new one and add it to the list
  nfapi_crc_indication_pdu_t *new_pdu = (nfapi_crc_indication_pdu_t*)malloc(sizeof(nfapi_crc_indication_pdu_t));
  if (!new_pdu) {
    printf("Failed to allocate memory for new CRC indication PDU\n");
    return NULL;
  }
  new_pdu->rx_ue_information_tag = UINT16_MAX;
  new_pdu->rnti = rnti;
  new_pdu->crc_indication_rel8_tag = UINT8_MAX;
  new_pdu->crcflag = false;
  nfapi_crc_indication_add(new_pdu);

  // Return the new PDU from the cache
  return &list[list_size - 1];
}

// Function to update a PDU in the list
void nfapi_crc_indication_update(nfapi_crc_indication_pdu_t *pdu) {
  // Find the index of the PDU in the list
  int idx = -1;
  for (int i = 0; i < list_size; i++) {
    if (list[i].rx_ue_information_tag == pdu->rx_ue_information_tag && list[i].rnti == pdu->rnti) {
      idx = i;
      break;
    }
  }

  // If the PDU is found, update it in the cache
  if (idx != -1) {
    list[idx] = *pdu;
  }
}

// Function to clear all items from the list and cache
void nfapi_crc_indication_clear(void) {
  // Free all memory allocated for the list and cache
  free(list);
  cache[0] = NULL;
  cache_size = 0;
}
