int count_disjoint_pairs(int *arr, int size) {
  // Initialize the Union-Find data structure with each element as its own set
  int *sets = malloc(size * sizeof(int));
  for (int i = 0; i < size; i++) {
    sets[i] = i;
  }

  int count = 0;
  for (int i = 0; i < size; i++) {
    // Find the root of the set containing element arr[i]
    while (sets[i] != i) {
      sets[i] = sets[sets[i]];
    }

    int j = i + 1;
    while (j < size) {
      if (sets[j] == sets[i]) {
        // The elements arr[i] and arr[j] are in the same set, so they must be disjoint
        count++;
        break;
      } else {
        // Find the root of the set containing element arr[j]
        while (sets[j] != j) {
          sets[j] = sets[sets[j]];
        }
      }
    }
  }

  free(sets);
  return count;
}

