// Function to calculate the checksum of an IP packet
int calculate_ip_checksum(char *packet, int size) {
  // Calculate the checksum of the IP packet by iterating over each byte and adding it to a running total
  int sum = 0;
  for (int i = 0; i < size; i++) {
    sum += (unsigned char)packet[i];
  }

  // Calculate the ones' complement of the checksum by inverting all bits and adding 1 to the result
  int checksum = ~sum + 1;
  return checksum;
}
