#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include <stdbool.h>
#include <pthread.h>
#include <semaphore.h>

// Linked list node structure for storing NFAPI_CRC_INDICATION_PDU_T structures
typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct ListNode *next;
} ListNode;

// Linked list header structure to manage the list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct List {
    ListNode *head;
    ListNode *tail;
    size_t count;
    size_t capacity;
} List;

// Mutex and semaphore for controlling concurrent access to the linked list
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
semaphore_t semaphore;

// Function to initialize a new linked list with an initial capacity of `capacity`
List *list_init(size_t capacity) {
    List *list = malloc(sizeof(List));
    if (list == NULL) {
        return NULL;
    }

    // Initialize the mutex and semaphore for controlling concurrent access
    pthread_mutex_init(&mutex, NULL);
    semaphore_init(&semaphore, 0, capacity - 1);

    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    list->capacity = capacity;

    return list;
}

// Function to free a linked list and all of its nodes
void list_free(List *list) {
    ListNode *current = list->head;
    while (current != NULL) {
        ListNode *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&mutex);
    semaphore_destroy(&semaphore);
}

// Function to add a new `NFAPI_CRC_INDICATION_PDU_T` structure to the linked list
void list_add(List *list, NFAPI_CRC_INDICATION_PDU_T *data) {
    // Acquire the mutex before modifying the linked list
    pthread_mutex_lock(&mutex);

    // Check if the list is full and resize it if necessary
    if (list->count == list->capacity) {
        size_t new_capacity = 2 * list->capacity;
        ListNode **new_nodes = realloc(list->head, sizeof(ListNode *) * new_capacity);
        if (new_nodes == NULL) {
            // Reallocation failed, free the allocated nodes and return
            pthread_mutex_unlock(&mutex);
            list_free(list);
            return;
        }
        list->head = new_nodes;
        list->tail = &new_nodes[list->capacity - 1];
        list->capacity = new_capacity;
    }

    // Add the new data to the end of the list
    ListNode *node = malloc(sizeof(ListNode));
    if (node == NULL) {
        pthread_mutex_unlock(&mutex);
        return;
    }
    node->data = data;
