#include <unistd.h>
#include <sys/wait.h>
#include <pthread.h>
#include "nfaapi_crc_indication.h"

int process_nfaapi_crc_indication(NFAPI_CRC_INDICATION_PDU_T* pdu, size_t num_elements) {
    // Dynamically allocate memory for the list of structures
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        // Memory allocation failed, handle error
        perror("Memory allocation failed");
        return 0;
    }

    // Validate that each structure is correctly initialized before proceeding
    for (size_t i = 0; i < num_elements; i++) {
        if (!pdu[i].valid || !pdu[i].rnti || !pdu[i].crc_indication_rel8.valid) {
            // Structure is not valid, handle error
            fprintf(stderr, "Invalid structure at index %zu\n", i);
            free(pdu_list);
            return 0;
        }
    }

    // Handle signal interrupts during command execution
    pthread_sigmask(SIG_BLOCK, &set, NULL);

    // Execute the command in a way that minimizes performance impact on the main processing thread
    pid_t child = fork();
    if (child == 0) {
        // Child process executes the command
        execvp("command", argv);
        exit(EXIT_FAILURE);
    } else if (child < 0) {
        // Error handling for fork() failure
        perror("Fork failed");
        free(pdu_list);
        return 0;
    }

    // Wait for the command to complete or be interrupted by a signal
    int status = 0;
    while (waitpid(child, &status, WNOHANG) == child || WIFSIGNALED(status)) {
        if (WIFEXITED(status) && WEXITSTATUS(status) != EXIT_SUCCESS) {
            // Command exited with failure
            fprintf(stderr, "Command exited with non-zero status\n");
            free(pdu_list);
            return 0;
        } else if (WIFSIGNALED(status)) {
            // Command was interrupted by a signal
            fprintf(stderr, "Command was interrupted by a signal\n");
            free(pdu_list);
            return 0;
        }
    }

    // Clean up resources if the function fails or exits
    if (status == -1) {
        perror("waitpid() failed");
        free(pdu_list);
        return 0;
    } else if (WIFSIGNALED(status)) {
        fprintf(stderr, "Command was interrupted by a signal\n");
        free(pdu_list);
        return 0;
    }

    // Return 1 only if both memory allocation and command execution are successful
    free(pdu_list);
    return 1;
}
```
