#include <stdlib.h>
#include <stdio.h>
#include <stdbool.h>
#include <string.h>
#include <pthread.h>

// Define the structure to hold the NFAPI_CRC_INDICATION_PDU_T data
typedef struct {
    uint16_t rx_ue_information_tag;
    uint16_t rnti;
    uint16_t rrc_ue_id;
    uint8_t crc_indication_rel8_tag;
    bool crcflag;
} nfapi_crc_indication_pdu_t;

// Define the list to hold the dynamically sized array of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    nfapi_crc_indication_pdu_t **data;
    size_t capacity;
    size_t size;
} nfapi_crc_indication_list_t;

// Define the function to manage the dynamically sized list of NFAPI_CRC_INDICATION_PDU_T structures
void manage_nfapi_crc_indication_list(nfapi_crc_indication_list_t *list, size_t n) {
    // Check if the list is null or if the number of elements to add exceeds the capacity
    if (list == NULL || n > list->capacity - list->size) {
        // If the list is null or the number of elements to add exceeds the capacity, allocate a new block of memory with double the current capacity
        size_t new_capacity = list == NULL ? 1 : list->capacity * 2;
        nfapi_crc_indication_pdu_t **new_data = realloc(list->data, sizeof(nfapi_crc_indication_pdu_t *) * new_capacity);
        if (new_data == NULL) {
            // If the allocation fails, log an error and return immediately
            printf("Error: Failed to allocate memory for NFAPI CRC indication list\n");
            return;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }
    // Loop through the number of elements to add and add them to the list
    for (size_t i = 0; i < n; i++) {
        // Allocate a new structure and populate it with the data from the current element
        nfapi_crc_indication_pdu_t *new_element = malloc(sizeof(nfapi_crc_indication_pdu_t));
        if (new_element == NULL) {
            // If the allocation fails, log an error and return immediately
            printf("Error: Failed to allocate memory for NFAPI CRC indication list element\n");
            return;
        }
        new_element->rx_ue_information_tag = 0xDEAD;
        new_element->rnti = 0xBEEF;
        new_element->rrc_ue_id = 0xCAFE;
        new_element->crc_indication_rel8_tag = 0xFACE;
        new_element->crcflag = false;
        // Add the new structure to the list
        list->data[list->size++] = new_element;
    }
}

// Define the function to add a new element to the list, ensuring that no two elements share the same RNTI or RRC UE ID within a given cell ID
void add_nfapi_crc_indication(nfapi_crc_indication_list_t *list, uint16_t rx_ue_information_tag, uint16_t rnti, uint16_t rrc_ue_id, uint8_t crc_indication_rel8_tag) {
    // Check if the list is null or if the number of elements to add exceeds the capacity
    if (list == NULL || list->size == 0) {
        // If the list is null or empty, initialize it with the new element
        manage_nfapi_crc_indication_list(list, 1);
    } else {
        // Loop through the existing elements and check for duplicates
        bool duplicate = false;
        for (size_t i = 0; i < list->size; i++) {
            if (list->data[i]->rnti == rnti || list->data[i]->rrc_ue_id == rrc_ue_id) {
                duplicate = true;
                break;
            }
        }
        // If a duplicate is found, allocate a new block of memory with double the current capacity and copy the existing elements to it
        if (duplicate) {
            manage_nfapi_crc_indication_list(list, list->size * 2);
        }
    }
    // Add the new element to the end of the list
    nfapi_crc_indication_pdu_t *new_element = malloc(sizeof(nfapi_crc_indication_pdu_t));
    if (new_element == NULL) {
        // If the allocation fails, log an error and return immediately
        printf("Error: Failed to allocate memory for NFAPI CRC indication list element\n");
        return;
    }
    new_element->rx_ue_information_tag = rx_ue_information_tag;
    new_element->rnti = rnti;
    new_element->rrc_ue_id = rrc_ue_id;
    new_element->crc_indication_rel8_tag = crc_indication_rel8_tag;
    list->data[list->size++] = new_element;
}

// Define the function to validate that all CRCINDICATIONREL8_T fields are correctly populated within specified range limits
bool validate_nfapi_crc_indication(nfapi_crc_indication_list_t *list) {
    // Loop through each element in the list and validate its fields
    for (size_t i = 0; i < list->size; i++) {
        nfapi_crc_indication_pdu_t *element = list->data[i];
        if (element->rx_ue_information_tag < 0xDEAD || element->rnti < 0xBEEF || element->rrc_ue_id < 0xCAFE) {
            printf("Error: NFAPI CRC indication field not correctly populated\n");
            return false;
        }
    }
    // If all elements are valid, return true
    return true;
}

// Define the function to print the contents of a list of NFAPI CRC indications
void print_nfapi_crc_indication(nfapi_crc_indication_list_t *list) {
    // Loop through each element in the list and print its fields
    for (size_t i = 0; i < list->size; i++) {
        nfapi_crc_indication_pdu_t *element = list->data[i];
        printf("RX UE Information Tag: %#x\n", element->rx_ue_information_tag);
        printf("RNTI: %#x\n", element->rnti);
        printf("RRC UE ID: %#x\n", element->rrc_ue_id);
        printf("CRC Indication Rel8 Tag: %#x\n", element->crc_indication_rel8_tag);
    }
}

// Define the function to free the memory allocated for a list of NFAPI CRC indications
void free_nfapi_crc_indication(nfapi_crc_indication_list_t *list) {
    // Loop through each element in the list and free its memory
    for (size_t i = 0; i < list->size; i++) {
        nfapi_crc_indication_pdu_t *element = list->data[i];
        free(element);
    }
    // Free the memory allocated for the list itself
    free(list->data);
}

int main() {
    // Create a new list of NFAPI CRC indications and add some elements to it
    nfapi_crc_indication_list_t *list = malloc(sizeof(nfapi_crc_indication_list_t));
    list->size = 0;
    manage_nfapi_crc_indication_list(list, 10);
    // Add a new element to the list with invalid fields and check if it is validated correctly
    nfapi_crc_indication_pdu_t *element = malloc(sizeof(nfapi_crc_indication_pdu_t));
    element->rx_ue_information_tag = 0xFEED;
    element->rnti = 0xBEEF;
    element->rrc_ue_id = 0xCAFE;
    element->crc_indication_rel8_tag = 0xFADE;
    add_nfapi_crc_indication(list, 0xFEED, 0xBEEF, 0xCAFE, 0xFADE);
    // Check if the list is validated correctly and print its contents
    if (validate_nfapi_crc_indication(list)) {
        printf("NFAPI CRC indications are valid\n");
        print_nfapi_crc_indication(list);
    } else {
        printf("Error: NFAPI CRC indications are not valid\n");
    }
    // Free the memory allocated for the list and its elements
    free_nfapi_crc_indication(list);
    return 0;
}
