        return NULL;
    }

    // Allocate memory for the array of structures
    NetworkInterfaceStatistics* stats = calloc(array_size, sizeof(NetworkInterfaceStatistics));
    if (stats == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for statistics array\n");
        return NULL;
    }

    // Initialize each structure in the array
    for (size_t i = 0; i < array_size; i++) {
        stats[i].macheader.src_mac = calloc(6, sizeof(char));
        stats[i].macheader.dst_mac = calloc(6, sizeof(char));
        stats[i].ippacket.header = calloc(20, sizeof(char));
        stats[i].payload = calloc(payload_size, sizeof(char));
    }

    // Set the payload size for each structure
    for (size_t i = 0; i < array_size; i++) {
        stats[i].ippacket.header.payload_size = payload_size;
    }

    return stats;
}

// Function to free the statistics structure
