#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <errno.h>
#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/sha.h>
#include "image_processing_library.h"

// Define constants for supported encryption modes
#define MODE_AES_256_CBC 1
#define MODE_AES_128_ECB 2

// Define a struct to hold the encryption key and initialization vector (IV)
struct AES_Key {
    unsigned char key[32]; // AES-256 key size
    unsigned char iv[16]; // AES-128 IV size
};

// Function to generate an encryption key from a password
// using SHA-256 hashing algorithm
void generate_key(const unsigned char* password, int password_len, struct AES_Key *key) {
    // Hash the password with SHA-256 and store the result in a temporary buffer
    SHA256_CTX ctx;
    unsigned char tmp[SHA256_DIGEST_LENGTH];
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, password, password_len);
    SHA256_Final(tmp, &ctx);

    // Extract the first 32 bytes of the hash result as the encryption key
    memcpy(key->key, tmp, 32);

    // Generate a random IV for each encryption session
    rand_bytes(key->iv, 16);
}

// Function to perform AES-CBC encryption on a given buffer using a predefined key
void encrypt_buffer(const unsigned char* buf, int buf_len, const struct AES_Key *key) {
    // Create an EVP context for the chosen encryption mode and set the key and IV
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit(ctx, EVP_aes_256_cbc(), NULL, key->key, key->iv);

    // Encrypt the buffer and store the result in a temporary buffer
    unsigned char tmp[buf_len];
    int len = EVP_EncryptUpdate(ctx, tmp, buf_len, buf, buf_len);

    // Free the context memory
    EVP_CIPHER_CTX_free(ctx);

    // Copy the encrypted data to the output buffer
    memcpy(buf, tmp, len);
}

// Function to perform AES-ECB encryption on a given buffer using a predefined key
void encrypt_buffer_ecb(const unsigned char* buf, int buf_len, const struct AES_Key *key) {
    // Create an EVP context for the chosen encryption mode and set the key and IV
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit(ctx, EVP_aes_128_ecb(), NULL, key->key, key->iv);

    // Encrypt the buffer and store the result in a temporary buffer
    unsigned char tmp[buf_len];
    int len = EVP_EncryptUpdate(ctx, tmp, buf_len, buf, buf_len);

    // Free the context memory
    EVP_CIPHER_CTX_free(ctx);

    // Copy the encrypted data to the output buffer
    memcpy(buf, tmp, len);
}

// Function to decrypt a given buffer using a predefined key
void decrypt_buffer(const unsigned char* buf, int buf_len, const struct AES_Key *key) {
    // Create an EVP context for the chosen encryption mode and set the key and IV
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    EVP_DecryptInit(ctx, EVP_aes_256_cbc(), NULL, key->key, key->iv);

    // Decrypt the buffer and store the result in a temporary buffer
    unsigned char tmp[buf_len];
    int len = EVP_DecryptUpdate(ctx, tmp, buf_len, buf, buf_len);

    // Free the context memory
    EVP_CIPHER_CTX_free(ctx);

    // Copy the decrypted data to the output buffer
    memcpy(buf, tmp, len);
}

// Function to convert a PNG image to JPEG format using an external library
void convert_image(const unsigned char* buf, int buf_len) {
    // Create a new image object and load the PNG data into it
    Image *img = new Image();
    img->load_from_png((unsigned char*)buf, buf_len);

    // Convert the image to JPEG format and store the result in a temporary buffer
    unsigned char tmp[buf_len];
    int len = img->save_to_jpeg(tmp, buf_len);

    // Free the image memory
    delete img;

    // Copy the converted data to the output buffer
    memcpy(buf, tmp, len);
}

// Function to dynamically allocate and initialize two arrays for 'long' offset values and 'int' keys
void init_offset_arrays(struct AES_Key* key_list, struct AES_Key** offset_arrays) {
    // Allocate memory for the array of encryption keys
    *key_list = (struct AES_Key*)malloc(sizeof(struct AES_Key));

    // Initialize each key with a random value
    for (int i = 0; i < KEY_COUNT; i++) {
        generate_key((unsigned char*)&i, sizeof(int), &(*offset_arrays)[i]);
    }
}

// Function to free the memory allocated by init_offset_arrays()
