                // Encrypt a PNG image using an external library
                convert_image((unsigned char*)argv[1], strlen(argv[1]));
                break;
            case 'd':
                // Decrypt a JPEG image using AES-256/ECB
                decrypt_buffer((unsigned char*)argv[1], strlen(argv[1]), &(*offset_arrays)[key_index]);
                break;
            default:
                printf("Invalid input\n");
                break;
        }
    }

    // Free the memory allocated by init_offset_arrays()
    free_offset_arrays(key_list);

    return 0;
}
```

