    // Check if the array has been allocated
    if (tx_power_levels == NULL) {
        allocate_and_initialize_tx_power_levels();
    }

    // Get the current size of the TX power level array
    size_t curr_size = tx_power_levels_size;

    // Allocate memory for the new TX power level
    tx_power_levels[curr_size].timestamp = timestamp;
    tx_power_levels[curr_size].cell_id = cell_id;
    tx_power_levels[curr_size].power_level = power_level;

    // Update the size of the TX power level array
    tx_power_levels_size++;

    return 1;
}

// Function to retrieve a TX power level from the array
tx_power_level_t *get_tx_power_level(time_t timestamp, int cell_id) {
    // Check if the array has been allocated
    if (tx_power_levels == NULL) {
        return NULL;
    }

    // Find the index of the TX power level in the array
    size_t i = 0;
    for (i = 0; i < tx_power_levels_size; i++) {
        if (tx_power_levels[i].timestamp == timestamp && tx_power_levels[i].cell_id == cell_id) {
            break;
        }
    }

    // Return the TX power level at the index, or NULL if not found
    return i < tx_power_levels_size ? &tx_power_levels[i] : NULL;
}
