#include <stdlib.h>
#include <stdio.h>
#include <stdbool.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define a structure to represent a network event
struct NetworkEvent {
    long timestamp; // Unix timestamp in milliseconds
    int type; // Event type (e.g., connect, disconnect)
    char* userIDs[]; // Array of associated user IDs
};

// A dynamic array of NetworkEvents to store all the events
struct EventArray {
    struct NetworkEvent** events; // Pointer to an array of pointers to NetworkEvents
    size_t capacity; // Maximum number of elements in the array
    size_t count; // Current number of elements in the array
};

// Initialize a new dynamic array with a given initial capacity
struct EventArray* initEventArray(size_t capacity) {
    struct EventArray* arr = malloc(sizeof(struct EventArray));
    arr->events = malloc(capacity * sizeof(struct NetworkEvent*));
    arr->capacity = capacity;
    arr->count = 0;
    return arr;
}

// Add a new event to the array, allocating memory as needed
void addEvent(struct EventArray* arr, struct NetworkEvent* evt) {
    // Check if we need to grow the array
    if (arr->count == arr->capacity) {
        arr->events = realloc(arr->events, 2 * arr->capacity * sizeof(struct NetworkEvent*));
        arr->capacity *= 2;
    }
    arr->events[arr->count++] = evt;
}

// Remove an event from the array by its index
void removeEvent(struct EventArray* arr, size_t index) {
    if (index >= arr->count) return; // Invalid index
    for (size_t i = index; i < arr->count - 1; i++) {
        arr->events[i] = arr->events[i + 1];
    }
    arr->count--;
}

// Get the number of events in the array
size_t getEventCount(struct EventArray* arr) {
    return arr->count;
}

// Find an event by its timestamp and type
struct NetworkEvent* findEvent(struct EventArray* arr, long timestamp, int type) {
    for (size_t i = 0; i < arr->count; i++) {
        struct NetworkEvent* evt = arr->events[i];
        if (evt->timestamp == timestamp && evt->type == type) {
            return evt;
        }
    }
    return NULL;
}

// Free the memory allocated to an event array
void freeEventArray(struct EventArray* arr) {
    for (size_t i = 0; i < arr->count; i++) {
        struct NetworkEvent* evt = arr->events[i];
        free(evt);
    }
    free(arr->events);
    free(arr);
}

// Clean up unused events periodically to optimize performance and reduce overhead
void cleanupEvents(struct EventArray* arr) {
    time_t currentTime = time(NULL);
    long threshold = currentTime - 60 * 60 * 24; // One day in seconds

    for (size_t i = 0; i < arr->count; i++) {
        struct NetworkEvent* evt = arr->events[i];
        if (evt->timestamp <= threshold) {
            removeEvent(arr, i);
            free(evt);
            i--; // Decrement the index to account for the new empty slot
        }
    }
}

// Periodically call cleanupEvents() in a separate thread
void* eventCleanerThread(void* arg) {
    struct EventArray* arr = (struct EventArray*)arg;
    while (true) {
        cleanupEvents(arr);
        sleep(60 * 10); // 10 minutes
    }
}

int main() {
    struct EventArray* arr = initEventArray(1000);
    pthread_t thread;
    pthread_create(&thread, NULL, eventCleanerThread, (void*)arr);

    // Add events to the array as they occur
    struct NetworkEvent evt1 = {1637894520000, 1, {"user1", "user2"}};
    addEvent(arr, &evt1);
    struct NetworkEvent evt2 = {1637894521000, 2, {"user3", "user4"}};
    addEvent(arr, &evt2);
    struct NetworkEvent evt3 = {1637894522000, 3, {"user5", "user6"}};
    addEvent(arr, &evt3);

    // Query the array for events
    size_t count = getEventCount(arr);
    printf("Number of events: %zu\n", count);
    struct NetworkEvent* evt = findEvent(arr, 1637894521000, 2);
    if (evt != NULL) {
        printf("Event type: %d\n", evt->type);
        for (int i = 0; i < evt->count; i++) {
            printf("%s\n", evt->userIDs[i]);
        }
    }

    // Remove an event from the array by its index
    removeEvent(arr, 1);

    freeEventArray(arr);
    pthread_join(thread, NULL);
    return 0;
}']

