// Structures for storing sensor readings and metadata
typedef struct SENSOR_READING_T {
    long timestamp; // Timestamp of the reading
    int sensorID; // ID of the sensor that generated the reading
    double value; // Measured value
} SENSOR_READING_T;

typedef struct TIME_SLICE_T {
    long startTime; // Start time of the time slice
    long endTime; // End time of the time slice
    SENSOR_READING_T* readings; // Array of sensor readings within the time slice
} TIME_SLICE_T;

typedef struct METADATA_RECORD_T {
    long timestamp; // Timestamp of the metadata record
    int batchSize; // Number of sensor readings in the batch
    double averageValue; // Average value of all sensor readings in the batch
} METADATA_RECORD_T;

// Global variables for dynamic data structures
SENSOR_READING_T* sensorReadings = NULL;
int numSensorReadings = 0;
TIME_SLICE_T* timeSlices = NULL;
int numTimeSlices = 0;
METADATA_RECORD_T* metadataRecords = NULL;
int numMetadataRecords = 0;

// Function to add a new sensor reading to the dynamic data structure
void addSensorReading(long timestamp, int sensorID, double value) {
    // Check if there is enough memory to allocate a new SENSOR_READING_T struct
    if (!sensorReadings || numSensorReadings == SIZE_MAX / sizeof(SENSOR_READING_T)) {
        // Reallocate memory for the array of sensor readings
        SENSOR_READING_T* newSensorReadings = realloc(sensorReadings, (numSensorReadings + 1) * sizeof(SENSOR_READING_T));
        if (!newSensorReadings) {
            printf("Error: Failed to allocate memory for sensor reading.\n");
            return;
        }
        sensorReadings = newSensorReadings;
    }

    // Add the new sensor reading to the array
    SENSOR_READING_T* newReading = &sensorReadings[numSensorReadings++];
    newReading->timestamp = timestamp;
    newReading->sensorID = sensorID;
    newReading->value = value;

    // Check if there is enough memory to allocate a new TIME_SLICE_T struct
    if (!timeSlices || numTimeSlices == SIZE_MAX / sizeof(TIME_SLICE_T)) {
        // Reallocate memory for the array of time slices
        TIME_SLICE_T* newTimeSlices = realloc(timeSlices, (numTimeSlices + 1) * sizeof(TIME_SLICE_T));
        if (!newTimeSlices) {
            printf("Error: Failed to allocate memory for time slice.\n");
            return;
        }
        timeSlices = newTimeSlices;
    }

    // Add the new time slice to the array
    TIME_SLICE_T* newSlice = &timeSlices[numTimeSlices++];
    newSlice->startTime = timestamp;
    newSlice->endTime = timestamp;
    newSlice->readings = sensorReadings + numSensorReadings - 1;

    // Check if there is enough memory to allocate a new METADATA_RECORD_T struct
    if (!metadataRecords || numMetadataRecords == SIZE_MAX / sizeof(METADATA_RECORD_T)) {
        // Reallocate memory for the array of metadata records
        METADATA_RECORD_T* newMetadataRecords = realloc(metadataRecords, (numMetadataRecords + 1) * sizeof(METADATA_RECORD_T));
        if (!newMetadataRecords) {
            printf("Error: Failed to allocate memory for metadata record.\n");
            return;
        }
        metadataRecords = newMetadataRecords;
    }

    // Add the new metadata record to the array
    METADATA_RECORD_T* newRecord = &metadataRecords[numMetadataRecords++];
    newRecord->timestamp = timestamp;
    newRecord->batchSize = 1;
    newRecord->averageValue = value;
}

// Function to update the dynamic data structure with new sensor readings and metadata
void updateDataStructure(long timestamp, int sensorID, double value) {
    // Find the relevant time slice based on the timestamp
    TIME_SLICE_T* relevantSlice = NULL;
    for (int i = 0; i < numTimeSlices; i++) {
        if (timestamp >= timeSlices[i].startTime && timestamp <= timeSlices[i].endTime) {
            relevantSlice = &timeSlices[i];
            break;
        }
    }

    // If there is no relevant time slice, create a new one
    if (!relevantSlice) {
        // Check if there is enough memory to allocate a new TIME_SLICE_T struct
        if (!timeSlices || numTimeSlices == SIZE_MAX / sizeof(TIME_SLICE_T)) {
            // Reallocate memory for the array of time slices
            TIME_SLICE_T* newTimeSlices = realloc(timeSlices, (numTimeSlices + 1) * sizeof(TIME_SLICE_T));
            if (!newTimeSlices) {
                printf("Error: Failed to allocate memory for time slice.\n");
                return;
            }
            timeSlices = newTimeSlices;
        }

        // Add the new time slice to the array
        TIME_SLICE_T* newSlice = &timeSlices[numTimeSlices++];
        newSlice->startTime = timestamp;
        newSlice->endTime = timestamp;
        relevantSlice = newSlice;
    }

    // Check if there is enough memory to allocate a new SENSOR_READING_T struct
    if (!relevantSlice->readings || numSensorReadings == SIZE_MAX / sizeof(SENSOR_READING_T)) {
        // Reallocate memory for the array of sensor readings
        SENSOR_READING_T* newSensorReadings = realloc(relevantSlice->readings, (numSensorReadings + 1) * sizeof(SENSOR_READING_T));
        if (!newSensorReadings) {
            printf("Error: Failed to allocate memory for sensor reading.\n");
            return;
        }
        relevantSlice->readings = newSensorReadings;
    }

    // Add the new sensor reading to the array
    SENSOR_READING_T* newReading = &relevantSlice->readings[numSensorReadings++];
    newReading->timestamp = timestamp;
    newReading->sensorID = sensorID;
    newReading->value = value;

    // Update the metadata record for this time slice
    METADATA_RECORD_T* relevantRecord = NULL;
    for (int i = 0; i < numMetadataRecords; i++) {
        if (timestamp >= metadataRecords[i].startTime && timestamp <= metadataRecords[i].endTime) {
            relevantRecord = &metadataRecords[i];
            break;
        }
    }

    // If there is no relevant metadata record, create a new one
    if (!relevantRecord) {
        // Check if there is enough memory to allocate a new METADATA_RECORD_T struct
        if (!metadataRecords || numMetadataRecords == SIZE_MAX / sizeof(METADATA_RECORD_T)) {
            // Reallocate memory for the array of metadata records
            METADATA_RECORD_T* newMetadataRecords = realloc(metadataRecords, (numMetadataRecords + 1) * sizeof(METADATA_RECORD_T));
            if (!newMetadataRecords) {
                printf("Error: Failed to allocate memory for metadata record.\n");
                return;
            }
            metadataRecords = newMetadataRecords;
        }

        // Add the new metadata record to the array
        METADATA_RECORD_T* newRecord = &metadataRecords[numMetadataRecords++];
        newRecord->timestamp = timestamp;
        newRecord->batchSize = 1;
        newRecord->averageValue = value;
    } else {
        // Increment the batch size and average value in the relevant metadata record
        relevantRecord->batchSize++;
        relevantRecord->averageValue += value;
    }
}

// Function to retrieve data from the dynamic structure
void getData(int sensorID, long startTime, long endTime) {
    // Find the relevant time slice based on the start time and end time
    TIME_SLICE_T* relevantSlice = NULL;
    for (int i = 0; i < numTimeSlices; i++) {
        if (startTime >= timeSlices[i].startTime && endTime <= timeSlices[i].endTime) {
            relevantSlice = &timeSlices[i];
            break;
        }
    }

    // If there is no relevant time slice, return an empty array of sensor readings
    if (!relevantSlice) {
        printf("Error: No relevant data found.\n");
        return;
    }

    // Find the relevant sensor reading in the relevant time slice based on the sensor ID and start time
    SENSOR_READING_T* relevantReading = NULL;
    for (int i = 0; i < relevantSlice->numReadings; i++) {
        if (sensorID == relevantSlice->readings[i].sensorID && startTime >= relevantSlice->readings[i].timestamp) {
            relevantReading = &relevantSlice->readings[i];
            break;
        }
    }

    // If there is no relevant sensor reading, return an empty array of data points
    if (!relevantReading) {
        printf("Error: No relevant data found.\n");
        return;
    }

    // Retrieve the data points for the relevant sensor reading in the relevant time slice
    double* dataPoints = malloc(sizeof(double) * (endTime - startTime));
    int numDataPoints = 0;
    for (long t = startTime; t <= endTime; t++) {
        if (t >= relevantReading->timestamp && t < relevantReading->nextTimestamp) {
            dataPoints[numDataPoints++] = relevantReading->value;
        } else {
            printf("Error: No relevant data found.\n");
            return;
        }
    }

    // Print the retrieved data points
    for (int i = 0; i < numDataPoints; i++) {
        printf("%f\n", dataPoints[i]);
    }
}

// Function to free memory allocated by the dynamic structure
void freeStructure() {
    for (int i = 0; i < numTimeSlices; i++) {
        if (timeSlices[i].readings) {
            free(timeSlices[i].readings);
        }
    }
