// Define a structure for the profile records
typedef struct {
  int id;
  char* name;
  int preferences[3]; // 3 preference fields
} record_t;

// Define a structure for the profile array
typedef struct {
  int num_profiles;
  int max_profiles;
  record_t* profiles;
} profile_array_t;

// Initialize a new profile array with the given number of profiles
void init_profile_array(profile_array_t* arr, int num_profiles) {
  // Allocate memory for the array and initialize it to NULL
  arr->profiles = malloc(sizeof(record_t*) * num_profiles);
  memset(arr->profiles, 0, sizeof(record_t*) * num_profiles);
  arr->num_profiles = 0;
  arr->max_profiles = num_profiles;
}

// Add a new record to the profile array
void add_record(profile_array_t* arr, int id, const char* name, int pref1, int pref2, int pref3) {
  // Check if there is enough space in the array for the new record
  if (arr->num_profiles == arr->max_profiles) {
    // If not, allocate more memory and copy the existing records to it
    int new_size = arr->max_profiles * 2;
    record_t* new_records = realloc(arr->profiles, sizeof(record_t*) * new_size);
    if (new_records == NULL) {
      // If the allocation fails, log an error and return
      printf("Error: Failed to allocate more memory for the profile array\n");
      return;
    }
    arr->profiles = new_records;
    arr->max_profiles = new_size;
  }

  // Allocate memory for the new record and copy the given values into it
  int index = arr->num_profiles++;
  record_t* rec = malloc(sizeof(record_t));
  if (rec == NULL) {
    printf("Error: Failed to allocate memory for a new record\n");
    return;
  }
  rec->id = id;
  rec->name = strdup(name);
  rec->preferences[0] = pref1;
  rec->preferences[1] = pref2;
  rec->preferences[2] = pref3;

  // Add the new record to the array and return it
  arr->profiles[index] = rec;
}

// Update a record in the profile array
void update_record(profile_array_t* arr, int id, const char* name, int pref1, int pref2, int pref3) {
  // Find the record with the given ID and update its values if it exists
  for (int i = 0; i < arr->num_profiles; i++) {
    if (arr->profiles[i]->id == id) {
      free(arr->profiles[i]->name);
      arr->profiles[i]->name = strdup(name);
      arr->profiles[i]->preferences[0] = pref1;
      arr->profiles[i]->preferences[1] = pref2;
      arr->profiles[i]->preferences[2] = pref3;
      return;
    }
  }

  // If the record does not exist, add a new one with the given values
  add_record(arr, id, name, pref1, pref2, pref3);
}

// Remove a record from the profile array
void remove_record(profile_array_t* arr, int id) {
  // Find the record with the given ID and remove it if it exists
  for (int i = 0; i < arr->num_profiles; i++) {
    if (arr->profiles[i]->id == id) {
      free(arr->profiles[i]);
      arr->num_profiles--;
      return;
    }
  }
}

// Return the record with the given ID from the profile array
record_t* get_record(profile_array_t* arr, int id) {
  // Find the record with the given ID and return it if it exists
  for (int i = 0; i < arr->num_profiles; i++) {
    if (arr->profiles[i]->id == id) {
      return arr->profiles[i];
    }
  }

  // If the record does not exist, return NULL
  return NULL;
}

// Free the memory allocated for a profile array
void free_profile_array(profile_array_t* arr) {
  for (int i = 0; i < arr->num_profiles; i++) {
    free(arr->profiles[i]);
  }
  free(arr->profiles);
}
