class CRCIndicationPDU:
    def __init__(self):
        self.rxUeInformationTag = None
        self.rnti = None
        self.crcIndicationRel8Tag = None

class CRCIndicationPDUList:
    def __init__(self, size=0):
        self.size = size
        self.head = [None] * size
        self.tail = [None] * size

def allocate_crc_indication_pdu(rxUeInformationTag, rnti, crcIndicationRel8Tag):
    pdu = CRCIndicationPDU()
    pdu.rxUeInformationTag = rxUeInformationTag
    pdu.rnti = rnti
    pdu.crcIndicationRel8Tag = crcIndicationRel8Tag
    return pdu

def deallocate_crc_indication_pdu(pdu):
    del pdu

def allocate_crc_indication_pdu_list(size=0):
    list = CRCIndicationPDUList(size)
    for i in range(size):
        pdu = allocate_crc_indication_pdu(None, None, None)
        list.head[i] = pdu
        list.tail[i] = pdu
    return list

def deallocate_crc_indication_pdu_list(list):
    for i in range(len(list.head)):
        deallocate_crc_indication_pdu(list.head[i])

def optimize_crc_indication_pdu_list(list, num_elements=0):
    if num_elements == 0:
        num_elements = len(list.head)
    for i in range(num_elements):
        pdu = list.head[i]
        while pdu != None:
            if pdu.next != None and pdu.rxUeInformationTag == 0 and pdu.rnti == 0 and pdu.crcIndicationRel8Tag == 0:
                deallocate_crc_indication_pdu(pdu)
                deallocate_crc_indication_pdu(pdu.next)
