            elif pdu.prev != None and pdu.rxUeInformationTag == 0 and pdu.rnti == 0 and pdu.crcIndicationRel8Tag == 0:
                deallocate_crc_indication_pdu(pdu)
                deallocate_crc_indication_pdu(pdu.prev)
                break
            else:
                break

if __name__ == "__main__":
