// Structure to represent a Network Interface Control (NIC) statistics structure
typedef struct NICStats {
    MAC_HEADER macHeader;
    IP_PACKET ipPacket;
} NICStats;

// Function to initialize an array of NIC statistics structures
void initializeNICStatsArray(int size, int minSize) {
    // Allocate memory for the array using dynamic allocation
    NICStats *stats = malloc(sizeof(NICStats) * size);
    if (!stats) {
        fprintf(stderr, "Error: Failed to allocate memory for NIC statistics array.\n");
        return;
    }

    // Initialize each structure in the array with a valid MAC header and IP packet
    for (int i = 0; i < size; i++) {
        stats[i].macHeader = initializeMACHeader();
        stats[i].ipPacket = initializeIPPacket(rand() % minSize, rand() % minSize);
    }

    // Recursively traverse the DOM to validate IP packet checksums
    validateDOMChecksums(stats, size);

    // Print a message indicating successful initialization
    printf("Initialized NIC statistics array with %d elements.\n", size);
}

// Function to dynamically allocate memory for a MAC header structure
MAC_HEADER initializeMACHeader() {
    // Allocate memory for the MAC header using dynamic allocation
    MAC_HEADER *macHeader = malloc(sizeof(MAC_HEADER));
    if (!macHeader) {
        fprintf(stderr, "Error: Failed to allocate memory for MAC header.\n");
        return NULL;
    }

    // Initialize the MAC header with a valid value
    macHeader->destination = 0x1234567890ab;

    return macHeader;
}

// Function to dynamically allocate memory for an IP packet structure
IP_PACKET initializeIPPacket(int payloadSize, int checksum) {
    // Allocate memory for the IP packet using dynamic allocation
    IP_PACKET *ipPacket = malloc(sizeof(IP_PACKET));
    if (!ipPacket) {
        fprintf(stderr, "Error: Failed to allocate memory for IP packet.\n");
        return NULL;
    }

    // Initialize the IP packet with a valid value
    ipPacket->source = 0x1234567890ab;
    ipPacket->destination = 0x1234567890ab;
    ipPacket->payloadSize = payloadSize;
    ipPacket->checksum = checksum;

    return ipPacket;
}

// Function to validate the integrity of IP packet checksums within the DOM
void validateDOMChecksums(NICStats *stats, int size) {
    for (int i = 0; i < size; i++) {
        // Compute the checksum for the current IP packet
        unsigned short checksum = computeIPChecksum(&stats[i].ipPacket);

        // Compare the computed checksum with the stored value
        if (checksum != stats[i].ipPacket.checksum) {
            fprintf(stderr, "Error: Invalid IP packet checksum detected.\n");
            return;
        }
    }
}

// Function to compute the checksum of an IP packet
unsigned short computeIPChecksum(IP_PACKET *ipPacket) {
    // Initialize a checksum with the starting value
    unsigned short checksum = 0xffff;

    // Sum up the values in the IP header and the payload
    for (int i = 0; i < ipPacket->payloadSize; i++) {
        checksum += ipPacket->payload[i];
    }

    // Invert the sum to get the final checksum value
    return ~checksum + 1;
}

// Function to print a message indicating successful initialization
void printInitializationMessage(int size) {
    printf("Initialized NIC statistics array with %d elements.\n", size);
}
