typedef struct message_node {
    NFAPI_MESSAGE_T msg;
    struct message_node *next;
} message_node_t;

static message_node_t *head = NULL;
static unsigned long sequence_id = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_MESSAGE_T *initialize_and_populate_linked_list(int num_messages) {
    int i;
    for (i = 0; i < num_messages; ++i) {
        NFAPI_MESSAGE_T *msg = malloc(sizeof(NFAPI_MESSAGE_T));
        if (!msg) {
            printf("Memory allocation failed\n");
            return NULL;
        }
        memset(msg, 0, sizeof(NFAPI_MESSAGE_T));
        msg->pd.rx_ue_information_tag = RX_UE_INFORMATION_TAG;
        msg->pd.rnti = i + 1;
        msg->pd.crc_indication_rel8_tag = CRC_INDICATION_REL8_TAG;
        msg->sequence_id = sequence_id++;
        pthread_mutex_lock(&mutex);
        message_node_t *new_node = malloc(sizeof(message_node_t));
        if (!new_node) {
            printf("Memory allocation failed\n");
            return NULL;
        }
        memset(new_node, 0, sizeof(message_node_t));
        new_node->msg = *msg;
        new_node->next = head;
        head = new_node;
        pthread_mutex_unlock(&mutex);
    }
    return head;
}
