// Structure to hold NIC statistics
typedef struct {
    MAC_HEADER mac; // MAC header for the packet
    IP_PACKET ip; // IP packet for the payload
} nic_statistics_t;

// Function to initialize dynamic array of NIC statistics structures
void initialize_nic_stats(nic_statistics_t** stats, int num_threads) {
    int i;

    // Allocate memory for the dynamic array
    *stats = malloc(num_threads * sizeof(nic_statistics_t));
    if (*stats == NULL) {
        perror("Failed to allocate memory for NIC statistics");
        exit(EXIT_FAILURE);
    }

    // Initialize the structure elements with default values
    for (i = 0; i < num_threads; i++) {
        (*stats)[i].mac.header_length = sizeof(struct ether_header);
        (*stats)[i].mac.type = htons(ETH_P_IP);
        (*stats)[i].ip.version = IPVERSION;
        (*stats)[i].ip.header_length = (sizeof(struct ip) >> 2) << 2;
        (*stats)[i].ip.total_length = sizeof(nic_statistics_t);
        (*stats)[i].ip.identification = htons(i);
        (*stats)[i].ip.flags = IP_DF;
        (*stats)[i].ip.ttl = 64;
        (*stats)[i].ip.protocol = IPPROTO_TCP;
        (*stats)[i].ip.checksum = 0;
        (*stats)[i].ip.source_address = htonl(INADDR_ANY);
        (*stats)[i].ip.destination_address = htonl(INADDR_BROADCAST);
        (*stats)[i].ip.option_length = 0;
        (*stats)[i].mac.source_address = htons(*((uint16_t*) &((*stats)[i].ip.source_address)));
        (*stats)[i].mac.destination_address = htons(*((uint16_t*) &((*stats)[i].ip.destination_address)));
        (*stats)[i].mac.ethertype = htons(ETH_P_IP);
    }
}

// Function to generate payload size and checksum for IP packet
void generate_payload_size_and_checksum(nic_statistics_t* stats, int thread_id) {
    // Generate random payload size between 1024 and 65535 bytes
    uint16_t payload_size = rand() % (65535 - 1024 + 1) + 1024;

    // Allocate memory for the payload
    stats->ip.payload = malloc(payload_size);
    if (stats->ip.payload == NULL) {
        perror("Failed to allocate memory for IP packet payload");
        exit(EXIT_FAILURE);
    }

    // Generate random payload data
    memset(stats->ip.payload, 0x00, payload_size);

    // Calculate checksum for the IP packet
    stats->ip.checksum = ip_checksum((unsigned char*) &(stats->ip), sizeof(struct ip));
}

// Function to validate the checksum for IP packet
int validate_checksum(nic_statistics_t* stats, int thread_id) {
    // Calculate checksum for the IP packet
    uint16_t calculated_checksum = ip_checksum((unsigned char*) &(stats->ip), sizeof(struct ip));

    // Compare calculated and expected checksums
    if (calculated_checksum == stats->ip.checksum) {
        return 0;
    } else {
        perror("Checksum validation failed");
        return -1;
    }
}

// Function to update NIC statistics structure with generated payload size and checksum
void update_nic_statistics(nic_statistics_t* stats, int thread_id) {
    // Generate payload size and checksum for the IP packet
    generate_payload_size_and_checksum(stats, thread_id);

    // Validate the generated checksum
    validate_checksum(stats, thread_id);
}

// Function to insert generated NIC statistics structure into a dynamic array
void insert_nic_statistics(nic_statistics_t* stats, int num_threads) {
    for (int i = 0; i < num_threads; i++) {
        // Update the NIC statistics structure with generated payload size and checksum
        update_nic_statistics(&stats[i], i);

        // Insert the updated NIC statistics structure into the dynamic array
        *((int*) &(stats[i].mac.header_length)) = sizeof(struct ether_header);
        *((int*) &(stats[i].ip.header_length)) = (sizeof(struct ip) >> 2) << 2;
    }
}
