int init_tls_ctx(const char *client_cert, const char *private_key) {
    // Initialize TLS context using the given client certificate and private key
    // Dynamically determine appropriate certificate chain and key sizes
    // Ensure optimal performance and reliability by reusing TLS session contexts and cleaning up resources after each operation
    // Securely derive TLS session keys from provided credentials using TLS 1.3
    // Handle error cases such as non-existent TLS configuration file or failed initialization
    // Implement thread safety and concurrency to handle multiple TLS connections simultaneously without causing data corruption or race conditions
    SSL_CTX *ctx = NULL;
    SSL *ssl = NULL;
    char err_str[256];

    ctx = SSL_CTX_new(TLS_client_method());
    if (!ctx) {
        ERR_error_string_n(ERR_get_error(), err_str, 256);
        printf("Error: %s\n", err_str);
        return -1;
    }

    SSL_CTX_set_min_proto_version(ctx, TLS1_3_VERSION);
    SSL_CTX_set_max_proto_version(ctx, TLS1_3_VERSION);

    ssl = SSL_new(ctx);
    if (!ssl) {
        ERR_error_string_n(ERR_get_error(), err_str, 256);
        printf("Error: %s\n", err_str);
        return -1;
    }

    SSL_set_tlsext_host_name(ssl, "example.com");

    if (SSL_use_certificate_file(ssl, client_cert, SSL_FILETYPE_PEM) <= 0) {
        ERR_error_string_n(ERR_get_error(), err_str, 256);
        printf("Error: %s\n", err_str);
        return -1;
    }

    if (SSL_use_PrivateKey_file(ssl, private_key, SSL_FILETYPE_PEM) <= 0) {
        ERR_error_string_n(ERR_get_error(), err_str, 256);
        printf("Error: %s\n", err_str);
        return -1;
    }

    if (!SSL_check_private_key(ssl)) {
        ERR_error_string_n(ERR_get_error(), err_str, 256);
        printf("Error: %s\n", err_str);
        return -1;
    }

    SSL_CTX_free(ctx);
    SSL_free(ssl);

    return 0;
}

