            method = "POST";
            break;
        default:
            return 0;
    }

    char *uri = request->uri;
    if (uri == NULL) {
        return 0;
    }

    size_t uri_len = strlen(uri);

    char *header_buf = malloc(1024);
    if (header_buf == NULL) {
        return 0;
    }

    size_t header_len = 0;
    for (int i = 0; i < request->headers->count; i++) {
        char *key = request->headers[i].key;
        char *value = request->headers[i].value;
        header_len += snprintf(header_buf + header_len, 1024 - header_len, "%s: %s\r\n", key, value);
    }

    size_t total_len = uri_len + header_len + 4; // 4 is for \r\n\r\n
    char *request_str = malloc(total_len);
    if (request_str == NULL) {
        return 0;
    }

    memset(request_str, 0, total_len);
    snprintf(request_str, total_len, "%s %s HTTP/1.1\r\n%s\r\n", method, uri, header_buf);
    free(header_buf);
    return request_str;
}

int http_parse_response(HTTP_REQUEST *request) {
