async function processImageArray(imagePaths, initialState, config) {
  // Validate input parameters
  if (!Array.isArray(imagePaths)) {
    throw new Error('Invalid image paths provided');
  }
  if (initialState === null || typeof initialState !== 'object') {
    throw new Error('Invalid initial state provided');
  }
  if (config === null || typeof config !== 'object') {
    throw new Error('Invalid configuration provided');
  }

  // Initialize output object and context objects for async processing
  const output = {};
  const contexts = [];

  // Filter out invalid image paths and convert to absolute paths
  imagePaths = imagePaths.filter(path => typeof path === 'string' && path !== '');
  imagePaths = imagePaths.map(path => {
    return new URL(path, import.meta.url).href;
  });

  // Resize images to maximum width and height if specified in config
  const resizeConfig = config.resize || {};
  if (resizeConfig.width && resizeConfig.height) {
    imagePaths = imagePaths.map(path => {
      return await resizeImage(path, resizeConfig.width, resizeConfig.height);
    });
  }

  // Convert images to specified output format (JPEG or PNG) if specified in config
  const convertConfig = config.convert || {};
  if (convertConfig.format && ['jpeg', 'png'].includes(convertConfig.format.toLowerCase())) {
    imagePaths = imagePaths.map(path => {
      return await convertImage(path, convertConfig.format);
    });
  }

  // Apply optional image effects (brightness adjustment or rotation) if specified in config
  const effectConfig = config.effect || {};
  if (effectConfig.brightness && typeof effectConfig.brightness === 'number') {
    imagePaths = imagePaths.map(path => {
      return await applyBrightnessEffect(path, effectConfig.brightness);
    });
  }
  if (effectConfig.rotate && typeof effectConfig.rotate === 'number') {
    imagePaths = imagePaths.map(path => {
      return await rotateImage(path, effectConfig.rotate);
    });
  }

  // Reduce redundant processing and improve performance by caching context objects
  const cacheConfig = config.cache || {};
  if (cacheConfig.enabled && cacheConfig.ttl) {
    const cache = new Map();
    imagePaths = imagePaths.map(path => {
      const cachedContext = cache.get(path);
      if (cachedContext) {
        return cachedContext;
      } else {
        const context = await createImageContext(path);
        cache.set(path, context);
        return context;
      }
    });
  }

  // Process images concurrently to minimize resource usage and improve performance
  const processedImages = [];
  for (const imagePath of imagePaths) {
    processedImages.push(await processImage(imagePath, initialState, config));
  }

  // Handle errors and return output object with processed images and error information
  if (processedImages.length !== imagePaths.length) {
    const errors = [];
    for (const imagePath of imagePaths) {
      if (!processedImages.includes(imagePath)) {
        errors.push(`Error processing image ${imagePath}`);
      }
    }
    return {
      images: processedImages,
      errors: errors
    };
  } else {
    return {
      images: processedImages,
      errors: []
    };
  }
}
