#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

// Define the structure for a MAC PDU
typedef struct {
    unsigned short pdcp_sn;
    unsigned char pdcp_cc;
    char mac_header[10];
} MAC_PDU_T;

// Define the maximum number of attempts for memory allocation
#define MAX_ALLOCATION_ATTEMPTS 5

// Define the cache size for storing SN values
#define CACHE_SIZE 1024

// Define the structure for a cache entry
typedef struct {
    unsigned short pdcp_sn;
    time_t timestamp;
} CacheEntry;

// Define the global cache
CacheEntry cache[CACHE_SIZE];

// Define the locking strategy for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initializeDynamicArray(MAC_PDU_T** pdu_array, unsigned int* num_pdu, unsigned short protocol_version) {
    // Validate the input parameters
    if (pdu_array == NULL || num_pdu == NULL || protocol_version < 1 || protocol_version > 3) {
        printf("Error: Invalid input parameters\n");
        return;
    }

    // Initialize the dynamic array
    *pdu_array = (MAC_PDU_T*)malloc(sizeof(MAC_PDU_T));
    if (*pdu_array == NULL) {
        printf("Error: Failed to allocate memory for the dynamic array\n");
        return;
    }
    *num_pdu = 0;

    // Read SN values from an external configuration file
    FILE* config_file = fopen("config.txt", "r");
    if (config_file == NULL) {
        printf("Error: Failed to open the configuration file\n");
        return;
    }
    char line[256];
    while (fgets(line, 256, config_file) != NULL) {
        // Parse the SN value from the line
        unsigned short sn = atoi(strtok(line, " \n"));
        if (sn < 0 || sn > protocol_version * 1024) {
            printf("Error: Invalid SN value in the configuration file\n");
            fclose(config_file);
            return;
        }

        // Check for duplicate SN values
        pthread_mutex_lock(&mutex);
        for (int i = 0; i < *num_pdu; i++) {
            if ((*pdu_array)[i].pdcp_sn == sn) {
                printf("Error: Duplicate SN value detected in the configuration file\n");
                fclose(config_file);
                pthread_mutex_unlock(&mutex);
                return;
            }
        }
        pthread_mutex_unlock(&mutex);

        // Add the SN value to the cache
        CacheEntry* cache_entry = &cache[sn % CACHE_SIZE];
        if (cache_entry->pdcp_sn == 0) {
            cache_entry->pdcp_sn = sn;
            cache_entry->timestamp = time(NULL);
        }

        // Add the SN value to the dynamic array
        MAC_PDU_T* new_pdu = (MAC_PDU_T*)malloc(sizeof(MAC_PDU_T));
        if (new_pdu == NULL) {
            printf("Error: Failed to allocate memory for a new PDU\n");
            return;
        }
        new_pdu->pdcp_sn = sn;
        new_pdu->pdcp_cc = 0; // Randomly generate a CC value
        memset(new_pdu->mac_header, 'A', 10); // Randomly generate a MAC header
        *num_pdu += 1;
    }
    fclose(config_file);

    // Reallocate the dynamic array if necessary
