#define MAX_PDCP_SN 0xffff
#define MAX_MAC_HEADER_SIZE 16

typedef struct {
    uint32_t pdcp_sn;
    uint8_t pdcp_cc;
    char mac_header[MAX_MAC_HEADER_SIZE];
} MAC_PDU_T;

static bool is_valid_pdcp_version(uint16_t version) {
    // Check if the given protocol version is valid
    return (version == 0 || version >= 1 && version <= 2);
}

static bool is_duplicate_pdcp_sn(MAC_PDU_T *array, uint32_t pdcp_sn) {
    // Check if the given PDCP_SN already exists in the array
    for (int i = 0; i < array->length; i++) {
        if (array[i].pdcp_sn == pdcp_sn) return true;
    }
    return false;
}

MAC_PDU_T *initialize_mac_pdu_array(uint16_t version, uint32_t length) {
    // Validate the protocol version and allocate memory for the array
    if (!is_valid_pdcp_version(version)) return NULL;
    MAC_PDU_T *array = malloc(length * sizeof(MAC_PDU_T));
    if (array == NULL) {
        // Handle memory allocation failure gracefully with retry logic
        for (int i = 0; i < 3; i++) {
            array = malloc(length * sizeof(MAC_PDU_T));
            if (array != NULL) break;
            sleep(1 << i); // Exponential backoff
        }
    }
    return array;
}

void destroy_mac_pdu_array(MAC_PDU_T *array) {
    // Deallocate memory for the array
    free(array);
}

static bool read_pdcp_sn_from_file(char *filename, uint32_t *pdcp_sn) {
    // Read the PDCP_SN from the given file
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) return false;
    int ret = fscanf(fp, "%"SCNu32, pdcp_sn);
    fclose(fp);
    return (ret == 1 && *pdcp_sn <= MAX_PDCP_SN);
}

static bool validate_pdcp_sn(uint16_t version, uint32_t pdcp_sn) {
    // Validate the PDCP_SN against the given protocol version
    if (!is_valid_pdcp_version(version)) return false;
    if (pdcp_sn > MAX_PDCP_SN) return false;
    if (pdcp_sn % 2 == 1 && version >= 2) return false;
    return true;
}

MAC_PDU_T *initialize_mac_pdu_array_with_cache(uint16_t version, uint32_t length) {
    // Validate the protocol version and allocate memory for the array
    if (!is_valid_pdcp_version(version)) return NULL;
    MAC_PDU_T *array = malloc(length * sizeof(MAC_PDU_T));
    if (array == NULL) {
        // Handle memory allocation failure gracefully with retry logic
        for (int i = 0; i < 3; i++) {
            array = malloc(length * sizeof(MAC_PDU_T));
            if (array != NULL) break;
            sleep(1 << i); // Exponential backoff
        }
    }

    // Initialize the cache for reading PDCP_SN values from file
    char cache_file[256];
    snprintf(cache_file, sizeof(cache_file), "/tmp/pdcp_sn_%d.cache", version);
    FILE *cache = fopen(cache_file, "r");

    // Populate the array with valid PDCP_SN values from the cache or file
    for (int i = 0; i < length; i++) {
        if (cache != NULL) {
            uint32_t pdcp_sn;
            fscanf(cache, "%"SCNu32, &pdcp_sn);
            if (validate_pdcp_sn(version, pdcp_sn)) {
                array[i].pdcp_sn = pdcp_sn;
            }
        } else {
            uint32_t pdcp_sn;
            while (!read_pdcp_sn_from_file(cache_file, &pdcp_sn) && i < length) {
                if (validate_pdcp_sn(version, pdcp_sn)) {
                    array[i].pdcp_sn = pdcp_sn;
                    fprintf(cache, "%"PRIu32"\n", pdcp_sn);
                } else {
                    i++; // Skip invalid PDCP_SN values
                }
            }
        }
    }

    // Clean up the cache file if it has been modified
    if (cache != NULL) fclose(cache);
    remove(cache_file);

    return array;
}

void destroy_mac_pdu_array_with_cache(MAC_PDU_T *array) {
    // Deallocate memory for the array and the cache file
    free(array);
}

int main() {
    MAC_PDU_T *array = initialize_mac_pdu_array_with_cache(2, 10);
    if (array == NULL) {
        perror("Failed to allocate memory for the array");
        return 1;
    }

    // Use the array
    ...

    // Clean up the cache file before exiting
    destroy_mac_pdu_array_with_cache(array);
    return 0;
}
