#define MAX_PAYLOAD_SIZE 1024
#define MIN_PAYLOAD_SIZE 64
#define CHECKSUM_FAILURE -1
#define SUCCESS 0

typedef struct NIC_STATISTICS {
    MAC_HEADER header;
    IP_PACKET packet;
} NIC_STATISTICS;

typedef struct IP_PACKET {
    unsigned char *payload;
    size_t payload_size;
    unsigned short checksum;
} IP_PACKET;

typedef struct MAC_HEADER {
    unsigned char destination[6];
    unsigned char source[6];
    unsigned short type;
} MAC_HEADER;

// external CRC calculation library
#include <crc.h>

/* function to dynamically allocate and initialize an array of NIC_STATISTICS structures
 * with a valid MAC header and corresponding IP packet with randomly generated payload size and checksum
 * manage memory efficiently, supporting dynamic growth based on user-defined limits to prevent leaks and adhere to strict memory usage quotas.
 * implement validation mechanisms to ensure the integrity of the IP_PACKET checksums upon insertion into the array, providing detailed error messages for invalid inputs.
 */
NIC_STATISTICS* allocate_nic_statistics(size_t size) {
    // validate input size
    if (size == 0 || size > MAX_PAYLOAD_SIZE) {
        fprintf(stderr, "Invalid input size: %zu. Must be between %d and %d.\n", size, MIN_PAYLOAD_SIZE, MAX_PAYLOAD_SIZE);
        return NULL;
    }

    // allocate memory for the array of NIC_STATISTICS structures
    NIC_STATISTICS *stats = malloc(sizeof(NIC_STATISTICS) * size);
    if (stats == NULL) {
        fprintf(stderr, "Failed to allocate memory for %zu NIC_STATISTICS structures.\n", size);
        return NULL;
    }

    // initialize each NIC_STATISTICS structure with a valid MAC header and corresponding IP packet
    for (size_t i = 0; i < size; ++i) {
        stats[i].header.destination[0] = 0xff;
        stats[i].header.destination[1] = 0xff;
        stats[i].header.destination[2] = 0xff;
        stats[i].header.source[0] = 0xaa;
        stats[i].header.source[1] = 0xaa;
        stats[i].header.source[2] = 0xaa;
        stats[i].header.type = 0x0800;

        // generate a random payload size between MIN_PAYLOAD_SIZE and MAX_PAYLOAD_SIZE
        int payload_size = rand() % (MAX_PAYLOAD_SIZE - MIN_PAYLOAD_SIZE + 1) + MIN_PAYLOAD_SIZE;
        stats[i].packet.payload_size = payload_size;

        // allocate memory for the payload
        stats[i].packet.payload = malloc(stats[i].packet.payload_size);
        if (stats[i].packet.payload == NULL) {
            fprintf(stderr, "Failed to allocate memory for %d bytes of payload.\n", stats[i].packet.payload_size);
            free(stats);
            return NULL;
        }

        // generate a random payload with the specified size
        for (int j = 0; j < stats[i].packet.payload_size; ++j) {
            stats[i].packet.payload[j] = rand() % 256;
        }

        // calculate checksum of the payload and update the IP_PACKET structure
        unsigned short checksum = crc16(stats[i].packet.payload, stats[i].packet.payload_size);
        if (checksum == CHECKSUM_FAILURE) {
            fprintf(stderr, "Failed to calculate checksum for %d bytes of payload.\n", stats[i].packet.payload_size);
            free(stats[i].packet.payload);
            free(stats);
            return NULL;
        }
        stats[i].packet.checksum = checksum;
    }

    // validate the integrity of the IP_PACKET checksums
    for (size_t i = 0; i < size; ++i) {
        if (crc16(stats[i].packet.payload, stats[i].packet.payload_size) != stats[i].packet.checksum) {
            fprintf(stderr, "Checksum validation failed for %d bytes of payload.\n", stats[i].packet.payload_size);
            free(stats[i].packet.payload);
            free(stats);
            return NULL;
        }
    }

    return stats;
