void manageMMUState(uint64_t virtualAddress, uint64_t pageTableEntry) {
    // Check if the virtual address is already mapped
    bool found = false;
    for (size_t i = 0; i < numEntries; ++i) {
        if (mmuStates[i].virtualAddress == virtualAddress) {
            found = true;
            break;
        }
