This is the code for a simple linked list implementation in C. The `node` struct represents a node in the linked list, which contains a value and a pointer to the next node. The `list` struct represents the entire linked list, which contains a pointer to the head of the list (the first node) and a pointer to the tail of the list (the last node). The `add_node`, `remove_node`, `get_node`, and `print_list` functions are for adding nodes to the end of the list, removing a specific node by value, retrieving a specific node by value, and printing the contents of the list.

```c
#include <stdio.h>
#include <stdlib.h>

struct node {
    int data;
    struct node *next;
};

struct list {
    struct node *head;
    struct node *tail;
};

void add_node(struct list *list, int data) {
    // Create a new node with the given data
    struct node *new_node = malloc(sizeof(struct node));
    new_node->data = data;
    new_node->next = NULL;

    // If the list is empty, set the head and tail to the new node
    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        // Otherwise, add the new node to the end of the list
        list->tail->next = new_node;
        list->tail = new_node;
    }
}

void remove_node(struct list *list, int data) {
    struct node *current = list->head;
    struct node *previous = NULL;

    // Loop through the list until we find the node with the given data
    while (current != NULL && current->data != data) {
        previous = current;
        current = current->next;
    }

    // If we found the node, remove it from the list
    if (current != NULL) {
        if (previous == NULL) {
            list->head = current->next;
        } else {
            previous->next = current->next;
        }

        free(current);
    }
}

struct node *get_node(struct list *list, int data) {
    struct node *current = list->head;

    // Loop through the list until we find the node with the given data
    while (current != NULL && current->data != data) {
        current = current->next;
    }

    return current;
}

void print_list(struct list *list) {
    struct node *current = list->head;

    // Loop through the list and print each value
    while (current != NULL) {
        printf("%d ", current->data);
        current = current->next;
    }
}
```

This is a simple implementation of a stack in C. The `push` function adds an element to the top of the stack, and the `pop` function removes the element from the top of the stack. The `isEmpty` function checks if the stack is empty, and the `peek` function returns the element at the top of the stack without removing it.

```c
#include <stdio.h>
#include <stdlib.h>

struct Stack {
    int size;
    int *data;
};

void push(struct Stack *stack, int value) {
    if (stack->size == 0) {
        stack->data = malloc(sizeof(int));
        stack->data[0] = value;
        stack->size++;
    } else {
        int *temp = realloc(stack->data, (stack->size + 1) * sizeof(int));
        if (temp == NULL) {
            printf("Error: Out of memory\n");
            return;
        }
        stack->data = temp;
        stack->data[stack->size] = value;
        stack->size++;
    }
}

int pop(struct Stack *stack) {
    if (stack->size == 0) {
        printf("Error: Empty stack\n");
        return -1;
    }
    int value = stack->data[stack->size - 1];
    free(stack->data);
    stack->data = NULL;
    stack->size--;
    return value;
}

int isEmpty(struct Stack *stack) {
    if (stack->size == 0) {
        return 1;
    } else {
        return 0;
    }
}

int peek(struct Stack *stack) {
    if (stack->size == 0) {
        printf("Error: Empty stack\n");
        return -1;
    }
    return stack->data[stack->size - 1];
}
```

This is a simple implementation of a queue in C. The `enqueue` function adds an element to the end of the queue, and the `dequeue` function removes the element from the front of the queue. The `isEmpty` function checks if the queue is empty, and the `peek` function returns the element at the front of the queue without removing it.

```c
#include <stdio.h>
#include <stdlib.h>

struct Queue {
    int size;
    int *data;
};

void enqueue(struct Queue *queue, int value) {
    if (queue->size == 0) {
        queue->data = malloc(sizeof(int));
        queue->data[0] = value;
        queue->size++;
    } else {
        int *temp = realloc(queue->data, (queue->size + 1) * sizeof(int));
        if (temp == NULL) {
            printf("Error: Out of memory\n");
            return;
        }
        queue->data = temp;
        queue->data[queue->size] = value;
        queue->size++;
    }
}

int dequeue(struct Queue *queue) {
    if (queue->size == 0) {
        printf("Error: Empty queue\n");
        return -1;
    }
    int value = queue->data[0];
    for (int i = 0; i < queue->size - 1; i++) {
        queue->data[i] = queue->data[i + 1];
    }
    free(queue->data);
    queue->data = NULL;
    queue->size--;
    return value;
}

int isEmpty(struct Queue *queue) {
    if (queue->size == 0) {
        return 1;
    } else {
        return 0;
    }
}

int peek(struct Queue *queue) {
    if (queue->size == 0) {
        printf("Error: Empty queue\n");
        return -1;
    }
    return queue->data[0];
}
