  size_t num_records;
  pthread_mutex_t mutex;
};

// Define a function to serialize a collection of records
void serialize(struct collection *coll) {
  // Lock the mutex to ensure thread safety
  pthread_mutex_lock(&coll->mutex);

  // Create a temporary buffer for the serialized data
  char *buffer = (char *)malloc(sizeof(struct record) * coll->num_records);

  // Serialize each record in the collection
  for (size_t i = 0; i < coll->num_records; i++) {
    struct record *record = &coll->records[i];
    buffer[i] = (char)record->offset;
    buffer[i + 1] = (char)record->key;
    strcpy(buffer + (2 * i), record->identifier);
  }

  // Unlock the mutex to release thread safety
  pthread_mutex_unlock(&coll->mutex);
}

// Define a function to deserialize a collection of records
void deserialize(struct collection *coll) {
  // Lock the mutex to ensure thread safety
  pthread_mutex_lock(&coll->mutex);

  // Create a temporary buffer for the deserialized data
  char *buffer = (char *)malloc(sizeof(struct record) * coll->num_records);

