  for (size_t i = 0; i < coll->num_records; i++) {
    struct record *record = &coll->records[i];

    // Check if the record has been modified
    if (record->offset != buffer[i] || record->key != buffer[i + 1] || strcmp(record->identifier, buffer + (2 * i))) {
      printf("Data integrity error: Record %lu has been modified\n", i);
    }
  }

  // Unlock the mutex to release thread safety
  pthread_mutex_unlock(&coll->mutex);
}

