    // Initialize the mutex and condition variable for synchronizing access to the array
    pthread_mutex_init(&crc_indication_mutex, NULL);
    pthread_cond_init(&crc_indication_cv, NULL);

    while (1) {
        // Wait for updates from the external data source
        pthread_mutex_lock(&crc_indication_mutex);
        while (!crc_indication_new_updates) {
            pthread_cond_wait(&crc_indication_cv, &crc_indication_mutex);
        }

        // Update the CRC flags based on new data received
        for (int i = 0; i < crc_indication_array_size; i++) {
            if (crc_indication_array[i].data != NULL) {
                free(crc_indication_array[i].data);
            }
            crc_indication_array[i].data = malloc(strlen(arg->data));
            strcpy(crc_indication_array[i].data, arg->data);
        }

        // Notify other threads that the array has been updated
        crc_indication_new_updates = 0;
        pthread_cond_broadcast(&crc_indication_cv);
        pthread_mutex_unlock(&crc_indication_mutex);
    }
}

// Add a new element to the array
void add_crc_indication(NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&crc_indication_mutex);
    // Check if the array is full and resize it if necessary
    if (crc_indication_array_size == crc_indication_array.length) {
        int new_size = crc_indication_array_size * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(crc_indication_array, new_size);
        if (new_array == NULL) {
            printf("Error: unable to resize the array\n");
        } else {
            crc_indication_array = new_array;
            crc_indication_array.length = new_size;
        }
    }

    // Add the new element to the array
    crc_indication_array[crc_indication_array_size++] = *element;
    pthread_mutex_unlock(&crc_indication_mutex);
}

// Remove an element from the array by index
void remove_crc_indication(int index) {
    pthread_mutex_lock(&crc_indication_mutex);
    // Check if the index is valid and remove the corresponding element
    if (index >= 0 && index < crc_indication_array_size) {
        free(crc_indication_array[index].data);
        crc_indication_array[index] = crc_indication_array[--crc_indication_array_size];
    } else {
        printf("Error: invalid index\n");
    }
    pthread_mutex_unlock(&crc_indication_mutex);
}

// Iterate over the array and print each element's details
void print_crc_indications() {
    pthread_mutex_lock(&crc_indication_mutex);
    for (int i = 0; i < crc_indication_array_size; i++) {
        printf("Index: %d, Data: %s\n", i, crc_indication_array[i].data);
    }
    pthread_mutex_unlock(&crc_indication_mutex);
}
