typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct NFAPI_CRC_INDICATION_LIST {
    size_t capacity;  // current allocated capacity of the list
    size_t count;     // current number of elements in the list
    NFAPI_CRC_INDICATION_PDU_T* pdu;
} NFAPI_CRC_INDICATION_LIST;

// Initializes a new empty list with the given capacity. Returns NULL on failure.
NFAPI_CRC_INDICATION_LIST* nfapi_crc_indication_list_new(size_t capacity) {
    NFAPI_CRC_INDICATION_LIST* list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST));
    if (!list) {
        return NULL;
    }
    list->capacity = capacity;
    list->count = 0;
    list->pdu = calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->pdu) {
        free(list);
        return NULL;
    }
    return list;
}

// Frees the memory associated with a given list. Does nothing if the list is NULL.
void nfapi_crc_indication_list_free(NFAPI_CRC_INDICATION_LIST* list) {
    if (!list) {
        return;
    }
    free(list->pdu);
    free(list);
}

// Appends a new PDU to the end of the list. Returns 0 on success, or an error code < 0 on failure.
int nfapi_crc_indication_list_append(NFAPI_CRC_INDICATION_LIST* list, RX_UE_INFORMATION_TAG rx_ue_information_tag, uint16_t rnti, CRC_INDICATION_REL8_TAG crc_indication_rel8_tag) {
    assert(list);
    if (list->count >= list->capacity) {
        // List is full, cannot add more PDUs.
        return -1;
    }
    NFAPI_CRC_INDICATION_PDU_T* pdu = &list->pdu[list->count++];
    pdu->rx_ue_information_tag = rx_ue_information_tag;
    pdu->rnti = rnti;
    pdu->crc_indication_rel8_tag = crc_indication_rel8_tag;
    return 0;
}

// Inserts a new PDU at the given index in the list. Returns 0 on success, or an error code < 0 on failure.
int nfapi_crc_indication_list_insert(NFAPI_CRC_INDICATION_LIST* list, size_t index, RX_UE_INFORMATION_TAG rx_ue_information_tag, uint16_t rnti, CRC_INDICATION_REL8_TAG crc_indication_rel8_tag) {
    assert(list);
    if (index > list->count) {
        // Index is out of bounds.
        return -2;
    }
    if (list->count >= list->capacity) {
        // List is full, cannot add more PDUs.
        return -1;
    }
    memmove(&list->pdu[index + 1], &list->pdu[index], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->count - index));
    NFAPI_CRC_INDICATION_PDU_T* pdu = &list->pdu[index];
    pdu->rx_ue_information_tag = rx_ue_information_tag;
    pdu->rnti = rnti;
    pdu->crc_indication_rel8_tag = crc_indication_rel8_tag;
    list->count++;
    return 0;
}

// Removes the PDU at the given index from the list. Returns 0 on success, or an error code < 0 on failure.
int nfapi_crc_indication_list_remove(NFAPI_CRC_INDICATION_LIST* list, size_t index) {
    assert(list);
    if (index >= list->count) {
        // Index is out of bounds.
        return -2;
    }
    memmove(&list->pdu[index], &list->pdu[index + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->count - index - 1));
    list->count--;
    return 0;
}

// Returns a pointer to the PDU at the given index, or NULL if the index is out of bounds.
NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication_list_get(NFAPI_CRC_INDICATION_LIST* list, size_t index) {
    assert(list);
    if (index >= list->count) {
        return NULL;
    }
    return &list->pdu[index];
}
