// Struct to represent a record in the BST
struct Record {
    int key;
    float value;
    char character;
};

// Comparator function for comparing records by their keys
int compare(const void* a, const void* b) {
    return ((struct Record*)a)->key - ((struct Record*)b)->key;
}

// Function to insert a new record into the BST
void insertRecord(struct Record** root, struct Record* newRecord) {
    // If the tree is empty, set the new record as the root
    if (*root == NULL) {
        *root = newRecord;
        return;
    }

    // Find the appropriate place to insert the new record in the BST
    struct Record* current = *root;
    while (current != NULL) {
        if (newRecord->key < current->key) {
            if (current->left == NULL) {
                current->left = newRecord;
                return;
            } else {
                current = current->left;
            }
        } else {
            if (current->right == NULL) {
                current->right = newRecord;
                return;
            } else {
                current = current->right;
            }
        }
    }
}

// Function to delete a record from the BST
void deleteRecord(struct Record** root, int key) {
    // If the tree is empty, do nothing
    if (*root == NULL) {
        return;
    }

    // Find the node to delete in the BST
    struct Record* current = *root;
    while (current != NULL && current->key != key) {
        if (key < current->key) {
            current = current->left;
        } else {
            current = current->right;
        }
    }

    // If the node is found, remove it from the BST
    if (current != NULL) {
        struct Record* temp = *root;
        if (temp == current) {
            *root = NULL;
        } else {
            temp->left = current->left;
            temp->right = current->right;
        }
        free(current);
    }
}

// Function to update a record in the BST
void updateRecord(struct Record** root, int key, float value, char character) {
    // If the tree is empty, do nothing
    if (*root == NULL) {
        return;
    }

    // Find the node to update in the BST
    struct Record* current = *root;
    while (current != NULL && current->key != key) {
        if (key < current->key) {
            current = current->left;
        } else {
            current = current->right;
        }
    }

    // If the node is found, update its value and character
    if (current != NULL) {
        current->value = value;
        current->character = character;
    }
}

// Function to search for a record in the BST by key
struct Record* searchRecord(struct Record* root, int key) {
    // If the tree is empty, return NULL
    if (root == NULL) {
        return NULL;
    }

    // Find the node with the given key in the BST
    struct Record* current = root;
    while (current != NULL && current->key != key) {
        if (key < current->key) {
            current = current->left;
        } else {
            current = current->right;
        }
    }

    // Return the node if found, otherwise return NULL
    return current;
}

// Function to search for a record in the BST by value
struct Record* searchRecordByValue(struct Record* root, float value) {
    // If the tree is empty, return NULL
    if (root == NULL) {
        return NULL;
    }

    // Find the node with the given value in the BST
    struct Record* current = root;
    while (current != NULL && current->value != value) {
        if (value < current->value) {
            current = current->left;
        } else {
            current = current->right;
        }
    }

    // Return the node if found, otherwise return NULL
    return current;
}

// Function to export the records to a binary file
void exportRecords(struct Record* root) {
    // Open the output file for writing
    FILE* outFile = fopen("records.bin", "wb");
    if (outFile == NULL) {
        printf("Error opening output file\n");
        return;
    }

    // Write the number of records to the file
    int numRecords = 0;
    struct Record* current = root;
    while (current != NULL) {
        numRecords++;
        current = current->right;
    }
    fwrite(&numRecords, sizeof(int), 1, outFile);

    // Write the records to the file in order
    current = root;
    while (current != NULL) {
        struct Record record = *current;
        fwrite(&record.key, sizeof(int), 1, outFile);
        fwrite(&record.value, sizeof(float), 1, outFile);
        fwrite(&record.character, sizeof(char), 1, outFile);
        current = current->right;
    }

    // Close the output file
    fclose(outFile);
}

