#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>

// Define maximum limits for data points and NFAPI structures
#define MAX_DATA_POINTS 1000000
#define MAX_NFAPI_STRUCTS 10000

// Define data structure for storing double-precision values, float ranges, and timestamps
typedef struct {
    double value;
    float range;
    time_t timestamp;
} data_point;

// Define NFAPI structure for storing RX_UE_INFORMATION_TAG and RNTI
typedef struct {
    int valid;
    uint16_t rx_ue_information_tag;
    uint32_t rnti;
} nfapi_cr_indication_pdu_t;

// Define hash table for storing data points and NFAPI structures
typedef struct {
    int size;
    int capacity;
    data_point* data_points;
    nfapi_cr_indication_pdu_t* nfapi_structs;
} hash_table;

// Define configuration parameter for toggling data compression
#define COMPRESSION_ENABLED 1

// Define function to dynamically process continuous stream of floating-point measurements from standard input
void process_measurements(int n_meas) {
    // Initialize hash table and arrays for storing data points and NFAPI structures
    hash_table* ht = (hash_table*)malloc(sizeof(hash_table));
    data_point* data_points = (data_point*)malloc(n_meas * sizeof(data_point));
    nfapi_cr_indication_pdu_t* nfapi_structs = (nfapi_cr_indication_pdu_t*)malloc(n_meas * sizeof(nfapi_cr_indication_pdu_t));

    // Initialize hash table size and capacity to 0 and NULL, respectively
    ht->size = 0;
    ht->capacity = 0;
    ht->data_points = NULL;
    ht->nfapi_structs = NULL;

    // Iterate over each measurement and store in hash table and arrays
    for (int i = 0; i < n_meas; i++) {
        // Read floating-point measurement from standard input
        double val;
        scanf("%lf", &val);

        // Check if hash table is full and needs to be resized
        if (ht->size == ht->capacity) {
            // Double the capacity of hash table arrays
            resize_hash_table(ht, 2 * ht->capacity);
        }

        // Add measurement to data points array and NFAPI structures
        ht->data_points[ht->size] = (data_point){val, val};
        nfapi_structs[ht->size] = (nfapi_cr_indication_pdu_t){1, 0x8950, 0x2734};

        // Increment hash table size and NFAPI structure count
        ht->size++;
        ht->nfapi_structs[ht->size].valid = 1;
    }

    // Check if data points array is full and needs to be resized
    if (ht->size == MAX_DATA_POINTS) {
        // Resize data point array to maximum capacity
        resize_array(data_points, MAX_DATA_POINTS);
    }

    // Check if NFAPI structures array is full and needs to be resized
    if (ht->size == MAX_NFAPI_STRUCTS) {
        // Resize NFAPI structure array to maximum capacity
        resize_array(nfapi_structs, MAX_NFAPI_STRUCTS);
    }

    // Clean up memory allocation for hash table and arrays
    free(data_points);
    free(nfapi_structs);
}

// Define function to resize hash table arrays
void resize_hash_table(hash_table* ht, int new_capacity) {
    // Check if new capacity is valid
    if (new_capacity > 0 && new_capacity > ht->size) {
        // Reallocate memory for hash table arrays
        data_point* new_data_points = realloc(ht->data_points, new_capacity * sizeof(data_point));
        nfapi_cr_indication_pdu_t* new_nfapi_structs = realloc(ht->nfapi_structs, new_capacity * sizeof(nfapi_cr_indication_pdu_t));

        // Check if memory allocation failed
