            fprintf(stderr, "Memory allocation failure\n");
            return;
        }

        // Update hash table arrays with reallocated memory
        ht->data_points = new_data_points;
        ht->nfapi_structs = new_nfapi_structs;

        // Update capacity of hash table arrays
        ht->capacity = new_capacity;
    }
}

// Define function to resize arrays
void resize_array(void* arr, int new_size) {
    // Check if new size is valid
    if (new_size > 0 && new_size > ht->size) {
        // Reallocate memory for array
        void* new_arr = realloc(arr, new_size * sizeof(void));

        // Check if memory allocation failed
        if (new_arr == NULL) {
            fprintf(stderr, "Memory allocation failure\n");
            return;
        }

        // Update array with reallocated memory
        arr = new_arr;
    }
}

// Define function to clean up memory allocation for hash table and arrays
void free_memory(hash_table* ht) {
    // Check if hash table is not NULL
    if (ht != NULL) {
        // Free memory allocated to hash table arrays
        free(ht->data_points);
        free(ht->nfapi_structs);

        // Reset size and capacity of hash table arrays
        ht->size = 0;
        ht->capacity = 0;
    }
