} record_list;

void *allocate_and_init_records_with_crypto(size_t num_records, char *password) {
    // Validate input parameters
    if (num_records > MAX_RECORDS) {
        return NULL;
    }

    // Initialize hash table and AES-256-CBC cipher
    record_list *record_list = malloc(sizeof(record_list));
    record_list->records = malloc(num_records * sizeof(struct record));
    EVP_CIPHER_CTX *cipher_ctx = EVP_CIPHER_CTX_new();

    // Derive encryption key from password using SHA-256
    unsigned char key[32];
    SHA256(password, strlen(password), key);

    // Set IV and key lengths based on the derived key
    int iv_len = 16;
    int key_len = 32;

    // Initialize AES-256-CBC cipher with derived key and IV
    EVP_EncryptInit_ex(cipher_ctx, EVP_aes_256_cbc(), NULL, key, iv_len);

    // Initialize each record in the list with a random int value
    for (int i = 0; i < num_records; i++) {
        struct record *record = &record_list->records[i];
        record->offset = rand();
        record->key = rand();

        // Encrypt and decrypt each record using AES-256-CBC cipher
        int encrypted_len, decrypted_len;
        unsigned char *encrypted_record = malloc(sizeof(struct record));
        EVP_EncryptUpdate(cipher_ctx, encrypted_record, &encrypted_len, (unsigned char *)record, sizeof(struct record));
        EVP_DecryptInit_ex(cipher_ctx, NULL, NULL, key, iv_len);
        EVP_DecryptUpdate(cipher_ctx, (unsigned char *)record, &decrypted_len, encrypted_record, encrypted_len);

        // Free encrypted record and validate integrity using HMAC-SHA256 tag
        free(encrypted_record);
        unsigned char *hmac = malloc(32);
        SHA256((unsigned char *)record, sizeof(struct record), hmac);
        if (memcmp(hmac, (unsigned char *)&record->key, 32) != 0) {
            return NULL;
        }
    }

    // Free cipher context and return pointer to first element of records array
    EVP_CIPHER_CTX_free(cipher_ctx);
    free(hmac);
    return record_list->records;
}
