}

// Define the function for initializing NIC statistics
void init_nic_statistics(NICStatistics **stats, size_t initialSize, size_t maxEntries) {
    // Check if the input parameters are valid
    assert(stats != NULL && initialSize > 0 && maxEntries > 0);

    // Allocate memory for the NIC statistics array
    *stats = allocateMemory(initialSize * sizeof(NICStatistics));

    // Initialize the size and maximum number of entries
    size_t size = initialSize;
    size_t max = maxEntries;

    // Set the default values for the first entry in the array
    (*stats)[0].macHeader.sourceMACAddress[0] = 0x01;
    (*stats)[0].macHeader.sourceMACAddress[1] = 0x23;
    (*stats)[0].macHeader.sourceMACAddress[2] = 0x45;
    (*stats)[0].ipPacket.version = IP_VERSION_4;
    (*stats)[0].ipPacket.protocol = PROTOCOL_UDP;
    (*stats)[0].ipPacket.payloadSize = rand() % (1500 - 64 + 1) + 64;
    (*stats)[0].checksum = calculateChecksum((*stats)[0].ipPacket);

    // Initialize the rest of the entries in the array to NULL
    for (size_t i = 1; i < size; i++) {
        (*stats)[i].macHeader.sourceMACAddress[0] = 0xFF;
        (*stats)[i].ipPacket.version = IP_VERSION_4;
        (*stats)[i].ipPacket.protocol = PROTOCOL_UDP;
        (*stats)[i].ipPacket.payloadSize = rand() % (1500 - 64 + 1) + 64;
        (*stats)[i].checksum = calculateChecksum((*stats)[i].ipPacket);
    }
}

// Define the function for adding new NIC statistics entries to the array
void add_nic_statistics(NICStatistics **stats, size_t *size, size_t max) {
    // Check if the input parameters are valid
    assert(stats != NULL && size > 0 && max > 0);

    // Increase the size of the array by a factor of two when it reaches its maximum capacity
    if (*size >= max) {
        *size = *size * 2;
    }

    // Allocate memory for the new entries in the array
    NICStatistics *newStats = allocateMemory(*size * sizeof(NICStatistics));

    // Copy the existing entries to the new array
    memcpy(newStats, *stats, (*size - 1) * sizeof(NICStatistics));

    // Free the original memory allocated for the statistics array
    free(*stats);

    // Set the new statistics array as the current one
    *stats = newStats;
}

// Define the function for validating checksums
bool validateChecksum(IP_PACKET packet) {
    // Calculate the checksum of the IP packet using a simple algorithm
    uint32_t checksum = calculateChecksum(packet);

    // Verify that the calculated checksum matches the expected value
    return checksum == packet.checksum;
}

// Define the function for calculating checksums
uint32_t calculateChecksum(IP_PACKET packet) {
    // Calculate the checksum of the IP packet using a simple algorithm
    uint32_t checksum = 0;
    for (size_t i = 0; i < packet.payloadSize; i++) {
        checksum += packet.payload[i];
    }
    return checksum;
}

// Define the function for adding a new NIC statistics entry to the array
void addNicStatistics(NICStatistics **stats, size_t *size, size_t max) {
    // Check if the input parameters are valid
    assert(stats != NULL && size > 0 && max > 0);

    // Increase the size of the array by a factor of two when it reaches its maximum capacity
    if (*size >= max) {
        *size = *size * 2;
    }

    // Allocate memory for the new entry in the array
    NICStatistics *newStats = allocateMemory((*size + 1) * sizeof(NICStatistics));

    // Copy the existing entries to the new array
    memcpy(newStats, *stats, (*size - 1) * sizeof(NICStatistics));

    // Set the default values for the new entry
    newStats[*size].macHeader.sourceMACAddress[0] = 0x01;
    newStats[*size].macHeader.sourceMACAddress[1] = 0x23;
