    newStats[*size].ipPacket.payloadSize = rand() % (1500 - 64 + 1) + 64;
    newStats[*size].checksum = calculateChecksum(newStats[*size].ipPacket);

    // Free the original memory allocated for the statistics array
    free(*stats);

    // Set the new statistics array as the current one
    *stats = newStats;
}

// Define the function for printing NIC statistics entries
void printNicStatistics(NICStatistics stats) {
    // Print the MAC address of the interface
    printf("MAC Address: %X-%X-%X\n", stats.macHeader.sourceMACAddress[0], stats.macHeader.sourceMACAddress[1], stats.macHeader.sourceMACAddress[2]);

