    printf("IP Version: %d, Protocol: %d\n", stats.ipPacket.version, stats.ipPacket.protocol);

    // Print the payload size of the IP packet
    printf("Payload Size: %d bytes\n", stats.ipPacket.payloadSize);
}

// Define the function for freeing NIC statistics entries
void freeNicStatistics(NICStatistics *stats) {
    // Free the memory allocated for the statistics array
    free(stats);
}

int main() {
