#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <pthread.h>
#include <signal.h>
#include <errno.h>
#include <sys/time.h>
#include <stdbool.h>

#define MAX_INTERFACES 10
#define MAX_RETRY 5

// Structure to hold network interface statistics
struct netif_stats {
    time_t timestamp; // Timestamp of the last update
    char *interface_name; // Name of the network interface
    unsigned long rx_bytes; // Total number of received bytes
    unsigned long tx_bytes; // Total number of transmitted bytes
    bool packet_loss; // Indicates if there has been any packet loss
};

// Structure to hold the list of network interfaces and their statistics
struct netif_list {
    int count; // Number of network interfaces
    struct netif_stats *stats[MAX_INTERFACES];
};

// Global variables
struct netif_list interface_list = {0};
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
bool isRunning = true; // Flag to indicate if the program is running or not
int retry_count = 0; // Number of retries before exiting

// Function to initialize a network interface structure
void init_netif_stats(struct netif_stats *stats, char *interface_name) {
    stats->timestamp = time(NULL);
    strncpy(stats->interface_name, interface_name, MAX_INTERFACE_NAME);
    stats->rx_bytes = 0;
    stats->tx_bytes = 0;
    stats->packet_loss = false;
}

// Function to update the network interface statistics
void update_netif_stats(struct netif_stats *stats) {
    pthread_mutex_lock(&mutex);
    // Update the timestamp
    stats->timestamp = time(NULL);
    // Get the current received and transmitted bytes for the interface
    int fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (fd == -1) {
        printf("Error creating socket: %s\n", strerror(errno));
        pthread_mutex_unlock(&mutex);
        return;
    }
    struct ifreq req = {0};
    strncpy(req.ifr_name, stats->interface_name, MAX_INTERFACE_NAME);
    if (ioctl(fd, SIOCGIFHWADDR, &req) == -1) {
        printf("Error getting hardware address: %s\n", strerror(errno));
        pthread_mutex_unlock(&mutex);
        return;
    }
    close(fd);
    struct sockaddr_in *addr = (struct sockaddr_in *)&req.ifr_addr;
    stats->rx_bytes = addr->sin_addr.s_addr;
    stats->tx_bytes = addr->sin_addr.s_addr;
}

// Function to monitor network traffic and update the statistics
void *monitor_traffic(void *args) {
    while (isRunning) {
        // Update the statistics for each interface in the list
        pthread_mutex_lock(&mutex);
        for (int i = 0; i < interface_list.count; i++) {
            update_netif_stats(interface_list.stats[i]);
        }
        pthread_mutex_unlock(&mutex);
        // Sleep for a few seconds before checking the network traffic again
        sleep(5);
    }
}

// Function to handle signals sent to the program
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        isRunning = false;
    }
}

// Main function of the program
int main() {
    // Set up signal handling
    struct sigaction action;
    action.sa_handler = signal_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    // Get the list of network interfaces and initialize their statistics
    struct ifaddrs *ifaddr, *ifa;
    getifaddrs(&ifaddr);
    interface_list.count = 0;
    for (ifa = ifaddr; ifa != NULL && interface_list.count < MAX_INTERFACES; ifa = ifa->ifa_next) {
        if (ifa->ifa_addr->sa_family == AF_INET || ifa->ifa_addr->sa_family == AF_PACKET) {
            struct netif_stats *stats = malloc(sizeof(struct netif_stats));
            init_netif_stats(stats, ifa->ifa_name);
            interface_list.stats[interface_list.count++] = stats;
        }
    }
    freeifaddrs(ifaddr);

    // Start the monitoring thread to update the network statistics
    pthread_t monitor_tid;
    if (pthread_create(&monitor_tid, NULL, &monitor_traffic, NULL)) {
        printf("Error creating monitoring thread\n");
        return 1;
    }

    // Main loop to read the network statistics and print them out
    while (isRunning) {
        // Print the current timestamp
        printf("%ld", time(NULL));
        // Print the received and transmitted bytes for each interface in the list
        pthread_mutex_lock(&mutex);
        for (int i = 0; i < interface_list.count; i++) {
            printf(" %d %d\n", interface_list.stats[i]->rx_bytes, interface_list.stats[i]->tx_bytes);
        }
        pthread_mutex_unlock(&mutex);
    }

    // Clean up and exit the program
    isRunning = false;
    if (pthread_join(monitor_tid, NULL)) {
        printf("Error joining monitoring thread\n");
        return 1;
    }
    free(interface_list.stats);
    return 0;
}']

