    size_t totalBytes = numEntries * sizeof(NFAPI_CRC_INDICATION_PDU_T *);
    if (totalBytes > 1024 * 1024) {
        fprintf(stderr, "Memory allocation exceeds maximum allowed size\n");
        return NULL;
    }
    printf("Total number of allocated bytes: %zu\n", totalBytes);

