// Function to release memory for an array of NFAPI_CRC_INDICATION_PDU_T structures
void freePDUs(NFAPI_CRC_INDICATION_PDU_T **pdus, unsigned int numEntries) {
    // Check that the number of entries is valid
    if (numEntries == 0 || numEntries > 1024) {
        fprintf(stderr, "Invalid number of entries\n");
        return;
    }

    // Acquire the mutex to synchronize access to the reference counts and PDUs
    pthread_mutex_lock(&mutex);

    // Release each PDU and decrement its reference count
    for (unsigned int i = 0; i < numEntries; ++i) {
        if (pdus[i] != NULL) {
            PDU_REF_COUNT_T *refCount = &(refCounts[i]);
            refCount->refCount--;
            if (refCount->refCount == 0) {
                free(pdus[i]);
                pdus[i] = NULL;
            }
        }
    }

    // Release the mutex and signal any waiting threads
    pthread_mutex_unlock(&mutex);
    pthread_cond_broadcast(&cond);
}

// Function to increment the reference count of a PDU by one
void incRefCount(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Acquire the mutex to synchronize access to the reference counts and PDUs
    pthread_mutex_lock(&mutex);

    // Increment the reference count of the PDU
    PDU_REF_COUNT_T *refCount = &(refCounts[pdu - pdus]);
    refCount->refCount++;

    // Release the mutex and signal any waiting threads
    pthread_mutex_unlock(&mutex);
    pthread_cond_broadcast(&cond);
}

// Function to decrement the reference count of a PDU by one
void decRefCount(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Acquire the mutex to synchronize access to the reference counts and PDUs
    pthread_mutex_lock(&mutex);

    // Decrement the reference count of the PDU
    PDU_REF_COUNT_T *refCount = &(refCounts[pdu - pdus]);
    refCount->refCount--;

    // Release the mutex and signal any waiting threads
    pthread_mutex_unlock(&mutex);
    pthread_cond_broadcast(&cond);
}

// Function to free memory for a PDU when its reference count drops to zero
void freePDU(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Acquire the mutex to synchronize access to the reference counts and PDUs
    pthread_mutex_lock(&mutex);

    // Check if the reference count of the PDU is zero
