    // Release the mutex and signal any waiting threads
    pthread_mutex_unlock(&mutex);
    pthread_cond_broadcast(&cond);
}

// Function to acquire a PDU from an array of PDUs
NFAPI_CRC_INDICATION_PDU_T *acqPDU(NFAPI_CRC_INDICATION_PDU_T **pdus, unsigned int numEntries) {
