void add_request(LTE_RRC_CREATION_REQUEST_LIST_T* request_list, int UE_ID, char* frequency_band, int bandwidth_part, long cell_identity) {
  // Check if the list is full
  if (request_list->size == request_list->capacity) {
    // Increase the capacity of the list by a factor of 2
    request_list->capacity *= 2;

    // Reallocate memory for the requests array
    LTE_RRC_CREATION_REQUEST_T* new_requests = (LTE_RRC_CREATION_REQUEST_T*)realloc(request_list->requests, request_list->capacity * sizeof(LTE_RRC_CREATION_REQUEST_T));

    // Check if reallocation was successful
    if (new_requests == NULL) {
      printf("Error: Could not allocate memory for new requests\n");
      return;
    } else {
      request_list->requests = new_requests;
    }
  }

  // Add the new request to the list
  request_list->requests[request_list->size].UE_ID = UE_ID;
  request_list->requests[request_list->size].frequency_band = frequency_band;
  request_list->requests[request_list->size].bandwidth_part = bandwidth_part;
  request_list->requests[request_list->size].cell_identity = cell_identity;

  // Increment the size of the list
  ++request_list->size;
}

