  // Find the index of the request with the specified UE_ID
  int i = -1;

  for (int j = 0; j < request_list->size; ++j) {
    if (request_list->requests[j].UE_ID == UE_ID) {
      i = j;
      break;
    }
  }

  // Check if the request was found
  if (i != -1) {
    // Decrement the size of the list and shift the remaining requests to fill the gap
    --request_list->size;

    for (int j = i; j < request_list->size; ++j) {
      request_list->requests[j] = request_list->requests[j + 1];
    }
  } else {
    printf("Error: Request with UE_ID %d not found\n", UE_ID);
  }
}

