void init_populate_list(LTE_RRC_CREATION_REQUEST_T **list, int size) {
    // Allocate memory for the list
    *list = (LTE_RRC_CREATION_REQUEST_T *)malloc(sizeof(LTE_RRC_CREATION_REQUEST_T) * size);
    if (*list == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize and populate the list with external data sources
    for (int i = 0; i < size; i++) {
        // Get the configuration parameters from an external source
        int frequency_band = get_frequency_band();
        int bandwidth_part = get_bandwidth_part();
        int cell_identity = get_cell_identity();
        int power_level = get_power_level();
        int subcarrier_spacing = get_subcarrier_spacing();

        // Check for invalid inputs and handle gracefully
        if (frequency_band == -1 || bandwidth_part == -1 || cell_identity == -1) {
            printf("Invalid input received\n");
            continue;
        }

        // Initialize the structure with the configuration parameters and additional optional parameters
        (*list)[i].UE_ID = i + 1;
        (*list)[i].frequency_band = frequency_band;
        (*list)[i].bandwidth_part = bandwidth_part;
        (*list)[i].cell_identity = cell_identity;
        (*list)[i].power_level = power_level;
        (*list)[i].subcarrier_spacing = subcarrier_spacing;
    }

    // Synchronize access to the list from multiple threads
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    // Manage resources efficiently and handle memory fragmentation issues
    void *ptr = malloc(sizeof(LTE_RRC_CREATION_REQUEST_T) * size);
    if (ptr == NULL) {
        printf("Memory allocation failed\n");
        return;
    }
    memcpy(ptr, list, sizeof(LTE_RRC_CREATION_REQUEST_T) * size);
    free(*list);
    *list = ptr;

    // Allow the list to be resized dynamically without losing data
    (*list)[size].UE_ID = -1;

    pthread_mutex_unlock(&mutex);
}
