// Define the global variables for the memory pool and linked list
static void* memPool = NULL;
static MemoryNode* freeList = NULL;

// Define the mutex and condition variable for synchronization
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

// Function to dynamically manage memory allocation for an array of NFAPI_CRC_INDICATION_PDU_T structures
void* allocateMemory(size_t size) {
    // Check if the memory pool is initialized
    if (memPool == NULL) {
        // Initialize the memory pool with a specified size
        memPool = malloc(size);
        if (memPool == NULL) {
            fprintf(stderr, "Failed to allocate memory pool\n");
            exit(1);
        }
    } else {
        // Resize the memory pool if necessary
        memPool = realloc(memPool, size);
        if (memPool == NULL) {
            fprintf(stderr, "Failed to resize memory pool\n");
            exit(1);
        }
    }

    // Lock the mutex and wait for a free node in the linked list
    pthread_mutex_lock(&mutex);
    while (freeList == NULL) {
        pthread_cond_wait(&cond, &mutex);
    }

    // Pop a node from the linked list and allocate memory for the structure
    MemoryNode* current = freeList;
    void* data = current->data;
    freeList = current->next;
    current->next = NULL;
    pthread_mutex_unlock(&mutex);

