        (*list)[i].rx_ue_information.tag = RX_UE_INFORMATION_TAG;
        (*list)[i].rnti = generate_rnti();
        (*list)[i].crc_indication_rel8.tag = CRC_INDICATION_REL8_TAG;
        (*list)[i].crc_indication_rel8.crci = generate_random_crci();
    }

    // Ensure the integrity of the data structures
    for (int i = 0; i < num_ue; i++) {
        if ((*list)[i].rx_ue_information.tag != RX_UE_INFORMATION_TAG ||
            (*list)[i].rnti == 0 ||
            (*list)[i].crc_indication_rel8.tag != CRC_INDICATION_REL8_TAG) {
            printf("Data structure integrity check failed\n");
            free(*list);
            *list = NULL;
            return false;
        }
    }

    return true;
}

// Generate a random RNTI value between 0 and 65535
int generate_rnti() {
    return (rand() % 65536);
}

// Generate a random CRCI value between 0 and 1023
