#define MAX_PATH_LEN 256
#define MIN_FILE_SIZE 100
#define MAX_FILE_SIZE 100000
#define LOG_ERROR(msg) { printf("Error: %s\n", msg); }
#define LOG_WARN(msg) { printf("Warning: %s\n", msg); }

typedef struct FileMetadata {
    char *path;
    size_t size;
    time_t modified;
    uid_t owner;
} FileMetadata;

// Linked list node for storing file metadata
typedef struct Node {
    FileMetadata *data;
    struct Node *next;
} Node;

// Hash table for fast lookups of file paths
typedef struct HashTable {
    size_t size;
    size_t count;
    Node **buckets;
} HashTable;

void initHashTable(HashTable *ht) {
    // Initialize the hash table with a prime number of buckets
    ht->size = 31;
    ht->count = 0;
    ht->buckets = (Node **)malloc(ht->size * sizeof(Node *));
}

void insertIntoHashTable(HashTable *ht, const char *path, FileMetadata *data) {
    // Calculate the hash of the file path and use it to determine which bucket to store the data in
    size_t hash = hashCode(path);
    int bucketIndex = hash % ht->size;
    Node *node = (Node *)malloc(sizeof(Node));
    node->data = data;
    node->next = ht->buckets[bucketIndex];
    ht->buckets[bucketIndex] = node;
}

FileMetadata *lookupInHashTable(HashTable *ht, const char *path) {
    // Calculate the hash of the file path and use it to determine which bucket to look in
    size_t hash = hashCode(path);
    int bucketIndex = hash % ht->size;
    Node *node = ht->buckets[bucketIndex];
    while (node != NULL) {
        if (strcmp(path, node->data->path) == 0) {
            return node->data;
        }
        node = node->next;
    }
    return NULL;
}

size_t hashCode(const char *str) {
    // A simple hash function that takes the first 16 characters of the string and XORs them together
    size_t hash = 0;
    for (int i = 0; i < 16; i++) {
        if (*str == '\0') {
            break;
        }
        hash ^= *str++;
    }
    return hash;
}

void destroyHashTable(HashTable *ht) {
    // Free all the nodes in the buckets and then free the array of buckets itself
    for (int i = 0; i < ht->size; i++) {
        Node *node = ht->buckets[i];
        while (node != NULL) {
            Node *next = node->next;
            free(node);
            node = next;
        }
    }
    free(ht->buckets);
}

void cleanup() {
    // Destroy the hash table and free all the memory allocated by the function
    destroyHashTable(&ht);
    for (int i = 0; i < numFiles; i++) {
        FileMetadata *data = files[i];
        free(data->path);
        free(data);
    }
    free(files);
}

void generateRandomFileSizes() {
    // Generate random file sizes within the specified range and seed the random number generator with the current time
    srand((unsigned int)time(NULL));
    for (int i = 0; i < numFiles; i++) {
        files[i]->size = (rand() % (MAX_FILE_SIZE - MIN_FILE_SIZE)) + MIN_FILE_SIZE;
    }
}

void logError(const char *msg) {
    // Log the error message to a centralized logging system for monitoring and debugging purposes
    printf("[%lu] %s\n", (unsigned long)time(NULL), msg);
}

int main() {
    // Initialize the hash table, generate random file sizes, and start a thread pool for asynchronous processing of files
    initHashTable(&ht);
    generateRandomFileSizes();
    pthread_t *threads = (pthread_t *)malloc(numFiles * sizeof(pthread_t));
    semaphore_t mutex;
    semaphore_init(&mutex, 1);
    for (int i = 0; i < numFiles; i++) {
        pthread_create(&threads[i], NULL, processFile, (void *)i);
    }
    for (int i = 0; i < numFiles; i++) {
        pthread_join(threads[i], NULL);
    }
    semaphore_destroy(&mutex);
    cleanup();
    return 0;
}

void *processFile(void *fileIndex) {
    // Acquire a lock on the hash table, check if the file is already in the table, and insert it if not
    int index = (int)fileIndex;
    FileMetadata *data = files[index];
    semaphore_wait(&mutex);
    if (lookupInHashTable(&ht, data->path) == NULL) {
        // Calculate the file's last modified timestamp and ownership information
        struct stat buf;
        stat(data->path, &buf);
        data->modified = buf.st_mtime;
        data->owner = buf.st_uid;
        // Insert the file into the hash table
        insertIntoHashTable(&ht, data->path, data);
    }
    semaphore_post(&mutex);
}']

