    if (collection->pdcp_pdu_count < MAX_PDCP_PDUS) {
        // Copy the PDCP PDU to the collection
        memcpy(&(collection->pdcp_pdu[collection->pdcp_pdu_count]), pdcp_pdu, sizeof(LTE_PDCP_PDU));
        // Increment the count of stored PDCP PDUs
        collection->pdcp_pdu_count++;
    } else {
        // Store the PDCP PDU in the overflow buffer if necessary
        if (collection->overflow_buffer_count < OVERFLOW_BUFFER_SIZE) {
            memcpy(&(collection->overflow_buffer[collection->overflow_buffer_count]), pdcp_pdu, sizeof(LTE_PDCP_PDU));
            collection->overflow_buffer_count++;
        } else {
            // Drop the PDCP PDU if the overflow buffer is full
            printf("Overflow buffer is full, dropping PDCP PDU\n");
        }
    }
}

// Function to query the total number of valid PDCP PDUs stored in the collection
uint32_t get_pdcp_pdu_count(PDCP_PDU_COLLECTION *collection) {
    return collection->pdcp_pdu_count;
}

// Function to iterate over the stored PDCP PDUs in the collection
void for_each_pdcp_pdu(PDCP_PDU_COLLECTION *collection, void (*callback)(LTE_PDCP_PDU *)) {
    // Iterate over each stored PDCP PDU and execute the callback function
    for (uint32_t i = 0; i < collection->pdcp_pdu_count; i++) {
        LTE_PDCP_PDU *pdcp_pdu = &(collection->pdcp_pdu[i]);
        callback(pdcp_pdu);
    }
}
