#define MAX_PDU_COUNT 100

typedef struct {
    uint8_t rx_ue_information_tag;
    uint32_t rnti;
    uint8_t crc_indication_rel8_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    AES_KEY aes_key;
    EVP_CIPHER_CTX *ctx;
} CACHE_ENTRY_T;

typedef struct {
    uint8_t cache[MAX_PDU_COUNT][sizeof(NFAPI_CRC_INDICATION_PDU_T)];
    size_t cache_size;
    CACHE_ENTRY_T *cache_entries[MAX_PDU_COUNT];
} NFAPI_CACHE_T;

void init_cache(NFAPI_CACHE_T *cache) {
    for (int i = 0; i < MAX_PDU_COUNT; i++) {
        cache->cache[i][0] = '\0';
        cache->cache_entries[i] = NULL;
    }
    cache->cache_size = 0;
}

void free_cache(NFAPI_CACHE_T *cache) {
    for (int i = 0; i < MAX_PDU_COUNT; i++) {
        if (cache->cache_entries[i] != NULL) {
            AES_KEY_free(cache->cache_entries[i]->aes_key);
            EVP_CIPHER_CTX_free(cache->cache_entries[i]->ctx);
            free(cache->cache_entries[i]);
        }
    }
}

bool cache_hit(NFAPI_CACHE_T *cache, uint8_t *pdu) {
    for (int i = 0; i < MAX_PDU_COUNT; i++) {
        if (cache->cache[i][0] != '\0') {
            NFAPI_CRC_INDICATION_PDU_T *cached_pdu = (NFAPI_CRC_INDICATION_PDU_T *) cache->cache[i];
            if (memcmp(cached_pdu, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T)) == 0) {
                return true;
            }
        }
    }
    return false;
}

void cache_add(NFAPI_CACHE_T *cache, uint8_t *pdu) {
    for (int i = 0; i < MAX_PDU_COUNT; i++) {
        if (cache->cache[i][0] == '\0') {
            memcpy(cache->cache[i], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            cache->cache_entries[i] = malloc(sizeof(CACHE_ENTRY_T));
            AES_set_encrypt_key(cache->cache_entries[i]->aes_key, 256, NULL);
            cache->cache_entries[i]->ctx = EVP_CIPHER_CTX_new();
        }
    }
}

void cache_remove(NFAPI_CACHE_T *cache, uint8_t *pdu) {
    for (int i = 0; i < MAX_PDU_COUNT; i++) {
        if (cache->cache[i][0] != '\0') {
            NFAPI_CRC_INDICATION_PDU_T *cached_pdu = (NFAPI_CRC_INDICATION_PDU_T *) cache->cache[i];
            if (memcmp(cached_pdu, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T)) == 0) {
                AES_KEY_free(cache->cache_entries[i]->aes_key);
                EVP_CIPHER_CTX_free(cache->cache_entries[i]->ctx);
                free(cache->cache_entries[i]);
                cache->cache_size--;
            }
        }
    }
}

int nfapi_crc_indication_pdu_crypt(uint8_t *pdu, uint32_t length, const char *password) {
    NFAPI_CACHE_T cache;
    init_cache(&cache);

    // Check if the PDU is already cached
    bool cache_hit = cache_hit(&cache, pdu);
    if (cache_hit) {
        return 0;
    }

    // Derive encryption key from password using SHA-256
    uint8_t hash[SHA256_DIGEST_LENGTH];
    SHA256((const unsigned char *)password, strlen(password), (unsigned char *)hash);
    AES_KEY aes_key;
    AES_set_encrypt_key(aes_key, 256, NULL);
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();

    // Initialize cipher with derived key and IV
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, aes_key, hash) != 1) {
        return -1;
    }

    // Encrypt PDU using AES-CBC
    int ret = EVP_EncryptUpdate(ctx, pdu, length);
    if (ret <= 0) {
        return -1;
    }

    cache_add(&cache, pdu);
    free_cache(&cache);

    // Return success
    return 0;
}

int nfapi_crc_indication_pdu_decrypt(uint8_t *pdu, uint32_t length, const char *password) {
    NFAPI_CACHE_T cache;
    init_cache(&cache);

    // Check if the PDU is already cached
    bool cache_hit = cache_hit(&cache, pdu);
    if (cache_hit) {
        return 0;
    }

    // Derive decryption key from password using SHA-256
    uint8_t hash[SHA256_DIGEST_LENGTH];
    SHA256((const unsigned char *)password, strlen(password), (unsigned char *)hash);
    AES_KEY aes_key;
    AES_set_encrypt_key(aes_key, 256, NULL);
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();

    // Initialize cipher with derived key and IV
    if (EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, aes_key, hash) != 1) {
        return -1;
    }

    // Decrypt PDU using AES-CBC
    int ret = EVP_DecryptUpdate(ctx, pdu, length);
    if (ret <= 0) {
        return -1;
    }

    cache_add(&cache, pdu);
    free_cache(&cache);

    // Return success
