// Define a struct for holding the NIC statistics
struct nic_stats {
    u_char *mac_header;
    u_char *ip_packet;
};

// Define a hash table data structure to store the NIC statistics
struct hash_table {
    int size;
    struct nic_stats **table;
};

// Initialize the hash table with a given size
void init_hash_table(struct hash_table *ht, int size) {
    ht->size = size;
    ht->table = malloc(sizeof(struct nic_stats *) * size);
    for (int i = 0; i < size; i++) {
        ht->table[i] = NULL;
    }
}

// Insert a new NIC statistics into the hash table
void insert_nic_stats(struct hash_table *ht, struct nic_stats *ns) {
    int index = ns->mac_header % ht->size;
    if (ht->table[index] == NULL) {
        ht->table[index] = ns;
    } else {
        // Add the new NIC statistics to the list of existing ones with the same MAC address
        struct nic_stats *curr = ht->table[index];
        while (curr->next != NULL) {
            curr = curr->next;
        }
        curr->next = ns;
    }
}

// Find a NIC statistics in the hash table based on its MAC address
struct nic_stats *find_nic_stats(struct hash_table *ht, u_char *mac_header) {
    int index = mac_header % ht->size;
    struct nic_stats *ns = ht->table[index];
    if (ns == NULL) {
        return NULL;
    } else {
        while (memcmp(ns->mac_header, mac_header, 6) != 0 && ns->next != NULL) {
            ns = ns->next;
        }
        return ns;
    }
}

// Update the IP checksum of a NIC statistics
void update_ip_checksum(struct nic_stats *ns) {
    struct ip *ip_packet = (struct ip *)ns->ip_packet;
    // Calculate the new IP checksum
    uint16_t checksum = 0;
    for (int i = 0; i < PACKET_SIZE / 2; i++) {
        checksum += ((uint16_t *)ip_packet)[i];
    }
    // Update the IP checksum field in the packet
    ip_packet->checksum = htons(checksum);
}

// Handle a new NIC statistics insertion
void handle_new_nic_stats(struct hash_table *ht, u_char *mac_header) {
    struct nic_stats *ns = malloc(sizeof(struct nic_stats));
    ns->mac_header = mac_header;
    // Generate a random payload size and checksum for the IP packet
    int payload_size = rand() % 1024;
    uint16_t checksum = rand();
    ns->ip_packet = malloc(sizeof(struct ip) + payload_size);
    struct ip *ip_packet = (struct ip *)ns->ip_packet;
    // Initialize the IP header fields
    ip_packet->ip_hl = 5;
    ip_packet->ip_v = 4;
    ip_packet->ip_len = sizeof(struct ip) + payload_size;
    ip_packet->ip_id = htons(rand());
    ip_packet->ip_off = IP_DF;
    ip_packet->ip_ttl = 64;
    ip_packet->ip_p = IPPROTO_TCP;
    ip_packet->ip_sum = checksum;
    // Set the source and destination IP addresses to a randomly generated values
    for (int i = 0; i < 4; i++) {
        ip_packet->ip_src.s_addr = htonl(rand());
        ip_packet->ip_dst.s_addr = htonl(rand());
    }
    // Add the new NIC statistics to the hash table
    insert_nic_stats(ht, ns);
}

// Handle a duplicate NIC statistics insertion
void handle_duplicate_nic_stats(struct hash_table *ht, u_char *mac_header) {
    struct nic_stats *ns = find_nic_stats(ht, mac_header);
    if (ns == NULL) {
        return;
    } else {
        // Update the IP checksum of the existing NIC statistics
        update_ip_checksum(ns);
    }
}

// Handle a new or duplicate NIC statistics insertion based on the given MAC address
void handle_new_nic_stats_or_duplicate(struct hash_table *ht, u_char *mac_header) {
    struct nic_stats *ns = find_nic_stats(ht, mac_header);
    if (ns == NULL) {
        // Handle a new NIC statistics insertion
        handle_new_nic_stats(ht, mac_header);
    } else {
        // Handle a duplicate NIC statistics insertion
        handle_duplicate_nic_stats(ht, mac_header);
    }
}

// Dynamically manage a list of Network Interface Control (NIC) statistics structures
void manage_nic_stats(struct hash_table *ht, int num_packets) {
    for (int i = 0; i < num_packets; i++) {
        // Generate a randomly generated MAC address and payload size
        u_char mac_header[6];
        for (int j = 0; j < 6; j++) {
            mac_header[j] = rand() % 256;
        }
        int payload_size = rand() % PACKET_SIZE;
        // Insert the new NIC statistics into the hash table
        handle_new_nic_stats_or_duplicate(ht, mac_header);
    }
}
