struct NetworkSession {
    int session_id;
    char *peer_ip;
    bool connected;
};

// Linked list to store network sessions
typedef struct NetworkSessionList {
    struct NetworkSession *head;
    struct NetworkSession *tail;
} NetworkSessionList;

// Thread-safe linked list operations
void init_linked_list(NetworkSessionList *ll) {
    ll->head = NULL;
    ll->tail = NULL;
}

int push_back(NetworkSessionList *ll, struct NetworkSession session) {
    // Allocate memory for new node
    struct NetworkSessionNode *new_node = malloc(sizeof(struct NetworkSessionNode));
    if (new_node == NULL) {
        return 0;
    }

    // Copy session data to new node
    new_node->session = session;

    // Append new node to linked list
    pthread_mutex_lock(&ll->mutex);
    if (ll->head == NULL) {
        ll->head = new_node;
    } else {
        ll->tail->next = new_node;
    }
    ll->tail = new_node;
    pthread_mutex_unlock(&ll->mutex);

    return 1;
}

struct NetworkSession pop_front(NetworkSessionList *ll) {
    // Allocate memory for new node
    struct NetworkSessionNode *new_node = malloc(sizeof(struct NetworkSessionNode));
    if (new_node == NULL) {
        return NULL;
    }

    // Copy session data to new node
    pthread_mutex_lock(&ll->mutex);
    new_node->session = ll->head->session;

    // Remove head node from linked list
    if (ll->head == ll->tail) {
        ll->head = NULL;
        ll->tail = NULL;
    } else {
        ll->head = ll->head->next;
    }
    pthread_mutex_unlock(&ll->mutex);

    return new_node->session;
}

// Background thread to check network connectivity
void *check_network_connectivity(void *args) {
    struct NetworkSessionList *ll = (struct NetworkSessionList *) args;
    while (1) {
        // Check network connectivity for each session
        pthread_mutex_lock(&ll->mutex);
        struct NetworkSessionNode *node = ll->head;
        while (node != NULL) {
            char ip[20];
            strcpy(ip, node->session.peer_ip);
            if (check_network_connectivity(ip)) {
                // Mark session as connected
                node->session.connected = true;
            } else {
                // Mark session as disconnected
                node->session.connected = false;
            }
            node = node->next;
        }
        pthread_mutex_unlock(&ll->mutex);

        // Wait for a specified amount of time before checking again
        sleep(10);
    }
}

int main() {
    struct NetworkSessionList ll;
    init_linked_list(&ll);

    // Start background thread to check network connectivity
    pthread_t bg_thread;
    pthread_create(&bg_thread, NULL, check_network_connectivity, &ll);

    // Add new sessions to linked list
    struct NetworkSession session1 = { 0, "192.168.0.1", false };
    push_back(&ll, session1);
    struct NetworkSession session2 = { 1, "192.168.0.2", false };
    push_back(&ll, session2);

    // Pop front session from linked list
    struct NetworkSession new_session = pop_front(&ll);
    if (new_session == NULL) {
        return 0;
    }

    // Check network connectivity for new session
    char ip[20];
    strcpy(ip, new_session.peer_ip);
    bool connected = check_network_connectivity(ip);
    if (connected) {
        printf("Session %d is connected\n", new_session.session_id);
    } else {
        printf("Session %d is disconnected\n", new_session.session_id);
    }

    // Clean up linked list and background thread
    pthread_mutex_destroy(&ll.mutex);
    pthread_join(bg_thread, NULL);

    return 1;
}
