#include <arpa/inet.h>

struct network_config {
    uint8_t mac[6];
    uint16_t channel;
};

struct network_config *init_network_config(int num_interfaces) {
    struct network_config *configs = calloc(num_interfaces, sizeof(*configs));
    if (!configs) {
        perror("Failed to allocate memory for network configs");
        return NULL;
    }

    // Initialize the MAC addresses and channel frequencies
    for (int i = 0; i < num_interfaces; i++) {
        struct network_config *config = &configs[i];

        // Generate a unique MAC address for each interface
        char mac_str[18];
        sprintf(mac_str, "54:32:01:%02x:%02x:%02x", i / 256, (i % 256) / 16, i % 16);
        inet_pton(AF_INET6, mac_str, config->mac);

        // Choose a channel frequency that is compatible with the interface's capabilities and the network topology
        config->channel = choose_channel(config->mac, num_interfaces);
    }

    return configs;
}

uint16_t choose_channel(const uint8_t *mac, int num_interfaces) {
    // Use a hash function to map the MAC address to a channel frequency
    unsigned long hash = 5381;
    for (int i = 0; i < 6; i++) {
        hash = ((hash << 5) + hash) ^ mac[i];
    }
    return hash % num_interfaces + 1; // The first channel is reserved for the network controller
}

void free_network_config(struct network_config *configs) {
    free(configs);
}
```
