void nfapi_crc_indication_list_init(NFAPI_CRC_INDICATION_LIST_T* list, size_t capacity) {
    assert(capacity <= 1000000);
    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * capacity);
    list->count = 0;
}

// Add a new element to the list, checking for unique RNTI values
void nfapi_crc_indication_list_add(NFAPI_CRC_INDICATION_LIST_T* list, uint32_t rnti, uint8_t crcfalg) {
    // Check if the RNTI is already in the list
    for (size_t i = 0; i < list->count; ++i) {
        if (list->elements[i].RNTI == rnti) {
            return; // RNTI already exists, do not add it again
        }
    }

    // Add the new element to the list
    list->elements[list->count++] = (NFAPI_CRC_INDICATION_PDU_T){.RX_UE_INFORMATION_TAG = 0, .RNTI = rnti, .CRCFLAG = crcfalg};
}

// Remove an element from the list by its RNTI value
void nfapi_crc_indication_list_remove(NFAPI_CRC_INDICATION_LIST_T* list, uint32_t rnti) {
    // Find the index of the element to remove
    size_t i = 0;
    while (i < list->count && list->elements[i].RNTI != rnti) {
        ++i;
    }
    assert(i < list->count); // RNTI not found in list, do nothing

    // Shift the elements to the left and decrease the count
    for (size_t j = i; j < list->count - 1; ++j) {
        list->elements[j] = list->elements[j + 1];
    }
    --list->count;
}

// Free all allocated memory when the function completes
void nfapi_crc_indication_list_free(NFAPI_CRC_INDICATION_LIST_T* list) {
    free(list->elements);
    list->count = 0;
}
