#include <math.h>

// Define the struct for the entry
typedef struct {
    char *str;
    int value;
} entry_t;

// Define the hash table structure
typedef struct {
    int capacity; // number of buckets
    int size; // number of elements in the table
    entry_t **buckets; // array of pointers to entries
    int *offsets; // array of offsets for each bucket
} hash_table_t;

// Define the metadata structure to track dynamic allocations
typedef struct {
    size_t size; // total size of allocated memory
    size_t used; // total size of used memory
} mem_metadata_t;

// Function to generate a random string of a given length
char *generate_random_string(size_t len) {
    char *str = malloc(len + 1);
    if (!str) {
        return NULL;
    }
    for (int i = 0; i < len; ++i) {
        str[i] = rand() % ('Z' - 'A') + 'A';
    }
    str[len] = '\0';
    return str;
}

// Function to generate a random integer between a given range
int generate_random_integer(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Function to initialize the hash table
void init_hash_table(hash_table_t *ht) {
    // Initialize the capacity and size to 0
    ht->capacity = 0;
    ht->size = 0;

    // Allocate memory for the buckets array
    ht->buckets = malloc(sizeof(entry_t *) * ht->capacity);
    if (!ht->buckets) {
        printf("Error: could not allocate memory for hash table buckets\n");
        return;
    }

    // Allocate memory for the offsets array
    ht->offsets = malloc(sizeof(int) * ht->capacity);
    if (!ht->offsets) {
        printf("Error: could not allocate memory for hash table offsets\n");
        return;
    }
}

// Function to populate the hash table with random data
void populate_hash_table(hash_table_t *ht, size_t n_entries) {
    // Initialize the metadata structure
    mem_metadata_t m = {0};

    for (size_t i = 0; i < n_entries; ++i) {
        // Generate a random string of length between 1 and 20
        size_t str_len = generate_random_integer(1, 20);
        char *str = generate_random_string(str_len);
        if (!str) {
            printf("Error: could not allocate memory for string\n");
            return;
        }

        // Generate a random integer between 1 and 100
        int value = generate_random_integer(1, 100);

        // Create an entry for the hash table
        entry_t *entry = malloc(sizeof(entry_t));
        if (!entry) {
            printf("Error: could not allocate memory for hash table entry\n");
            return;
        }
        entry->str = str;
        entry->value = value;

        // Insert the entry into the hash table
        int bucket_index = hash(entry->str, ht);
        if (bucket_index < 0) {
            printf("Error: could not find bucket index for string\n");
            return;
        }
        ht->buckets[bucket_index] = entry;
        ht->size++;

        // Update the metadata structure
        m.size += sizeof(entry_t);
        m.used += strlen(str) + 1;
    }
}

// Function to handle collisions in the hash table by chaining them together
void handle_collisions(hash_table_t *ht, entry_t *entry) {
    // Find the bucket index for the string
    int bucket_index = hash(entry->str, ht);
    if (bucket_index < 0) {
        printf("Error: could not find bucket index for string\n");
        return;
    }

    // Check if there are any collisions in the bucket
    if (ht->offsets[bucket_index] != -1) {
        // If there is a collision, chain the new entry to the existing one
        entry->next = ht->buckets[bucket_index];
        ht->buckets[bucket_index] = entry;
    } else {
        // Otherwise, insert the entry into the bucket
        ht->offsets[bucket_index] = -1;
        ht->buckets[bucket_index] = entry;
    }
}

// Function to resize the hash table when it becomes full
void resize_hash_table(hash_table_t *ht, size_t new_capacity) {
    // Create a new hash table with the new capacity
    hash_table_t new_ht = {0};
    new_ht.capacity = new_capacity;
    new_ht.size = ht->size;
    new_ht.buckets = malloc(sizeof(entry_t *) * new_capacity);
    if (!new_ht.buckets) {
        printf("Error: could not allocate memory for hash table buckets\n");
        return;
    }
    new_ht.offsets = malloc(sizeof(int) * new_capacity);
    if (!new_ht.offsets) {
        printf("Error: could not allocate memory for hash table offsets\n");
        return;
    }

    // Copy the entries from the old hash table to the new one
    for (size_t i = 0; i < ht->capacity; ++i) {
        if (ht->offsets[i] != -1) {
            entry_t *entry = ht->buckets[i];
            int bucket_index = hash(entry->str, &new_ht);
            if (bucket_index < 0) {
                printf("Error: could not find bucket index for string\n");
                return;
            }
            new_ht.offsets[bucket_index] = -1;
            new_ht.buckets[bucket_index] = entry;
        }
    }

    // Update the metadata structure
    mem_metadata_t m = {0};
    for (size_t i = 0; i < new_ht.capacity; ++i) {
        if (new_ht.offsets[i] != -1) {
            entry_t *entry = new_ht.buckets[i];
            m.size += sizeof(entry_t);
            m.used += strlen(entry->str) + 1;
        }
    }
}

// Function to check if the hash table is full and needs to be resized
void check_resize(hash_table_t *ht, size_t n_entries) {
    // If the hash table is full, resize it to twice its current capacity
    if (ht->size >= ht->capacity) {
        size_t new_capacity = 2 * ht->capacity;
        resize_hash_table(ht, new_capacity);
    }
}

// Function to insert an entry into the hash table
void insert(hash_table_t *ht, char *str, int value) {
    // Create a new entry for the hash table
    entry_t *entry = malloc(sizeof(entry_t));
    if (!entry) {
        printf("Error: could not allocate memory for hash table entry\n");
        return;
    }
    entry->str = str;
    entry->value = value;

    // Check if the hash table is full and needs to be resized
    check_resize(ht, 1);

    // Insert the entry into the hash table
    int bucket_index = hash(entry->str, ht);
    if (bucket_index < 0) {
        printf("Error: could not find bucket index for string\n");
        return;
    }
    if (ht->offsets[bucket_index] != -1) {
        handle_collisions(ht, entry);
    } else {
        ht->offsets[bucket_index] = -1;
        ht->buckets[bucket_index] = entry;
    }
}

// Function to search for an entry in the hash table
entry_t *search(hash_table_t *ht, char *str) {
    // Find the bucket index for the string
    int bucket_index = hash(str, ht);
    if (bucket_index < 0) {
        printf("Error: could not find bucket index for string\n");
        return NULL;
    }

    // Check if there are any collisions in the bucket
    if (ht->offsets[bucket_index] != -1) {
        entry_t *entry = ht->buckets[bucket_index];
        while (entry != NULL && strcmp(str, entry->str) != 0) {
            entry = entry->next;
        }
        return entry;
    } else {
        // If there are no collisions, check if the string is in the bucket
        return ht->buckets[bucket_index];
    }
}

// Function to delete an entry from the hash table
void delete(hash_table_t *ht, char *str) {
    // Find the bucket index for the string
    int bucket_index = hash(str, ht);
    if (bucket_index < 0) {
        printf("Error: could not find bucket index for string\n");
        return;
    }

    // Check if there are any collisions in the bucket
    if (ht->offsets[bucket_index] != -1) {
        entry_t *entry = ht->buckets[bucket_index];
        while (entry != NULL && strcmp(str, entry->str) != 0) {
            entry = entry->next;
        }
        if (entry == NULL) {
            printf("Error: could not find string in hash table\n");
            return;
        }
        // If there is a collision, remove the entry from the list
        if (entry->prev != NULL) {
            entry->prev->next = entry->next;
        } else {
            ht->buckets[bucket_index] = entry->next;
        }
        free(entry);
    } else {
        // Otherwise, remove the entry from the bucket
        entry_t *entry = ht->buckets[bucket_index];
        if (strcmp(str, entry->str) == 0) {
            free(entry);
            ht->buckets[bucket_index] = NULL;
        } else {
            printf("Error: could not find string in hash table\n");
            return;
        }
    }
}

// Function to print the contents of the hash table
void print(hash_table_t *ht) {
    for (size_t i = 0; i < ht->capacity; i++) {
        entry_t *entry = ht->buckets[i];
        while (entry != NULL) {
            printf("%s -> %d\n", entry->str, entry->value);
            entry = entry->next;
        }
    }
}

int main() {
    hash_table_t *ht = create();
    insert(ht, "apple", 100);
    insert(ht, "banana", 200);
    insert(ht, "orange", 300);
    print(ht);
    return 0;
}
```
This code creates a linked list for each bucket in the hash table. The `insert` function first finds the appropriate bucket based on the hashed key, and then inserts the new entry into the linked list for that bucket. If there are collisions, the function uses the `handle_collisions` function to insert the new entry into the appropriate position in the linked list.

The `search` function also finds the appropriate bucket based on the hashed key, and then checks if the string is in the linked list for that bucket. If there are collisions, the function uses the `handle_collisions` function to check if the string is in the linked list.

The `delete` function first finds the appropriate bucket based on the hashed key, and then checks if the string is in the linked list for that bucket. If it is, the function removes the entry from the linked list by setting the previous node's next pointer to the current node's next pointer. If there are collisions, the function uses the `handle_collisions` function to remove the entry from the linked list.

The `print` function simply prints out all of the entries in each bucket.

This implementation has a time complexity of O(n) for insertion, search, and deletion, since it requires searching the entire linked list for collisions. However, it has a space complexity of O(n) since each bucket has a separate linked list that can get quite large.

