#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a struct to represent a task
typedef struct Task {
    char* name;
    double priority;
    size_t size;
} Task;

// Define a struct to represent the task list
typedef struct TaskList {
    Task** tasks;
    size_t count;
    size_t capacity;
} TaskList;

// Function to create a new task list with given initial capacity
TaskList* createTaskList(size_t capacity) {
    // Allocate memory for the task list struct
    TaskList* list = malloc(sizeof(TaskList));
    if (list == NULL) {
        return NULL;
    }

    // Initialize the list and its tasks array
    list->tasks = calloc(capacity, sizeof(Task*));
    if (list->tasks == NULL) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->capacity = capacity;

    return list;
}

// Function to add a new task to the task list
void addTask(TaskList* list, const char* name, double priority, size_t size) {
    // Check if the list is full and needs to be resized
    if (list->count == list->capacity) {
        // Resize the tasks array by 50%
        Task** newTasks = realloc(list->tasks, list->capacity * 2);
        if (newTasks == NULL) {
            return;
        }

        list->tasks = newTasks;
        list->capacity *= 2;
    }

    // Allocate memory for the new task struct
    Task* task = malloc(sizeof(Task));
    if (task == NULL) {
        return;
    }

    // Copy the name, priority, and size of the new task
    task->name = strdup(name);
    task->priority = priority;
    task->size = size;

    // Add the new task to the list
    list->tasks[list->count++] = task;
}

// Function to update a task in the task list by name
void updateTask(TaskList* list, const char* name, double priority) {
    // Find the index of the task with the given name
    size_t i;
    for (i = 0; i < list->count; i++) {
        if (strcmp(list->tasks[i]->name, name) == 0) {
            break;
        }
    }

    // Update the task's priority and return
    if (i < list->count) {
        list->tasks[i]->priority = priority;
    }
}

// Function to remove a task from the task list by name
void removeTask(TaskList* list, const char* name) {
    // Find the index of the task with the given name
    size_t i;
    for (i = 0; i < list->count; i++) {
        if (strcmp(list->tasks[i]->name, name) == 0) {
            break;
        }
    }

    // Remove the task from the list and free its memory
    if (i < list->count) {
        Task* task = list->tasks[i];
        free(task->name);
        free(task);

        // Shift all tasks after the removed task back by one
        for (size_t j = i; j < list->count - 1; j++) {
            list->tasks[j] = list->tasks[j + 1];
        }

        list->count--;
    }
}

// Function to free the memory used by a task list
void freeTaskList(TaskList* list) {
    for (size_t i = 0; i < list->count; i++) {
        Task* task = list->tasks[i];
        free(task->name);
        free(task);
    }

    // Free the tasks array and the task list struct itself
    free(list->tasks);
    free(list);
}
```

The above code defines a flexible task management system that supports dynamic addition, deletion, and updating of tasks. Each task consists of a `char*` name, a `double` priority, and a `size_t` size. The system uses an array-based approach for storing tasks, with each task represented as a struct containing the necessary information.

The `createTaskList()` function creates a new task list with a given initial capacity. It allocates memory for the task list struct and its tasks array, and initializes the list's count and capacity fields. The function returns a pointer to the newly created task list.

The `addTask()` function adds a new task to the task list. It checks if the list is full and needs to be resized by 50%. If it does, it reallocates the tasks array and updates the list's capacity field. Then, it allocates memory for the new task struct, copies the name, priority, and size of the new task into it, and adds the new task to the list.

The `updateTask()` function updates a task in the task list by name. It finds the index of the task with the given name using a linear search, and then updates its priority field. If no task with the given name is found, the function returns without doing anything.

The `removeTask()` function removes a task from the task list by name. It finds the index of the task with the given name using a linear search, and then frees the memory used by the task's name and struct. Finally, it shifts all tasks after the removed task back by one and decrements the list's count field.

The `freeTaskList()` function frees the memory used by a task list. It iterates through each task in the list, freeing its name and struct memory using `free()`. Then, it frees the tasks array and the task list struct itself using `free()`."]

