void allocate_arrays(size_t num_offsets, size_t num_keys, size_t num_records) {
    // Validate input parameters
    if (num_offsets == 0 || num_keys == 0 || num_records == 0) {
        printf("Error: Invalid input parameters. num_offsets, num_keys, and num_records must be greater than 0.\n");
        return;
    }

    // Allocate memory for arrays
    long *offsets = malloc(num_offsets * sizeof(long));
    int *keys = malloc(num_keys * sizeof(int));
    struct record *records = malloc(num_records * sizeof(struct record));

    if (offsets == NULL || keys == NULL || records == NULL) {
        printf("Error: Failed to allocate memory for arrays. num_offsets=%lu, num_keys=%lu, num_records=%lu\n", num_offsets, num_keys, num_records);
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    // Initialize arrays
    for (size_t i = 0; i < num_offsets; i++) {
        offsets[i] = 0;
    }
    for (size_t i = 0; i < num_keys; i++) {
        keys[i] = rand() % 100; // random value between 0 and 99
    }
    for (size_t i = 0; i < num_records; i++) {
        records[i].value = rand(); // random value between 0 and RAND_MAX
    }

    // Print arrays
    printf("Offsets: ");
    for (size_t i = 0; i < num_offsets; i++) {
        printf("%ld ", offsets[i]);
    }
    printf("\n");
    printf("Keys: ");
    for (size_t i = 0; i < num_keys; i++) {
        printf("%d ", keys[i]);
    }
    printf("\n");
    printf("Records: ");
    for (size_t i = 0; i < num_records; i++) {
        printf("%d ", records[i].value);
    }
    printf("\n");

    // Clean up memory
    free(offsets);
    free(keys);
    free(records);
}
