// Define the functions for managing the circular buffer and memory manager
void cb_init(CIRCULAR_BUFFER_T* cb, size_t capacity) {
    cb->capacity = capacity;
    cb->head = 0;
    cb->tail = 0;
    cb->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * capacity);
