    NAS_MESSAGE* nasMessage; // Pointer to a dynamically allocated NAS message structure
    NAS_TRANSACTION_ID transactionId; // Transaction ID for the NAS message
} LTE_RRC_NAS_MESSAGE;

// Define the global array of LTE_RRC_NAS_MESSAGE structures
LTE_RRC_NAS_MESSAGE* messages = NULL;
int numMessages = 0; // Number of elements in the array

// Function to add a new message to the array
int addMessage(RRC_MESSAGE_TYPE messageType, NAS_MESSAGE* nasMessage, NAS_TRANSACTION_ID transactionId) {
    // Check if the message is valid
    if (messageType == RRC_UNKNOWN || nasMessage == NULL) {
        return 0;
    }

    // Lock the mutex to prevent concurrent modifications
    pthread_mutex_lock(&messagesMutex);

    // Allocate memory for a new message structure
    LTE_RRC_NAS_MESSAGE* newMessage = malloc(sizeof(LTE_RRC_NAS_MESSAGE));
    if (newMessage == NULL) {
        pthread_mutex_unlock(&messagesMutex);
        return 0;
    }

    // Initialize the message structure
    newMessage->messageType = messageType;
    newMessage->nasMessage = nasMessage;
    newMessage->transactionId = transactionId;

    // Add the new message to the array
    messages[numMessages++] = newMessage;

    // Unlock the mutex and return success
    pthread_mutex_unlock(&messagesMutex);
    return 1;
}

// Function to remove a message from the array
int removeMessage(RRC_MESSAGE_TYPE messageType, NAS_TRANSACTION_ID transactionId) {
    // Lock the mutex to prevent concurrent modifications
    pthread_mutex_lock(&messagesMutex);

    // Find the message with the specified type and transaction ID
    LTE_RRC_NAS_MESSAGE* foundMessage = NULL;
    for (int i = 0; i < numMessages; i++) {
        if (messages[i]->messageType == messageType && messages[i]->transactionId == transactionId) {
            foundMessage = messages[i];
            break;
        }
    }

    // If the message was not found, return failure
    if (foundMessage == NULL) {
        pthread_mutex_unlock(&messagesMutex);
        return 0;
    }

    // Remove the message from the array and free its memory
    for (int i = 0; i < numMessages - 1; i++) {
        if (messages[i] == foundMessage) {
            memmove(&messages[i], &messages[i + 1], (numMessages - i - 1) * sizeof(LTE_RRC_NAS_MESSAGE*));
            break;
        }
    }
    numMessages--;
    free(foundMessage);

    // Unlock the mutex and return success
    pthread_mutex_unlock(&messagesMutex);
    return 1;
}

// Function to retrieve a message from the array by its transaction ID
LTE_RRC_NAS_MESSAGE* getMessage(NAS_TRANSACTION_ID transactionId) {
    // Lock the mutex to prevent concurrent modifications
    pthread_mutex_lock(&messagesMutex);

    // Find the message with the specified transaction ID
    LTE_RRC_NAS_MESSAGE* foundMessage = NULL;
    for (int i = 0; i < numMessages; i++) {
        if (messages[i]->transactionId == transactionId) {
            foundMessage = messages[i];
            break;
        }
    }

    // If the message was not found, return NULL
    if (foundMessage == NULL) {
        pthread_mutex_unlock(&messagesMutex);
        return NULL;
    }

    // Return a copy of the message structure
    LTE_RRC_NAS_MESSAGE* copiedMessage = malloc(sizeof(LTE_RRC_NAS_MESSAGE));
    if (copiedMessage == NULL) {
        pthread_mutex_unlock(&messagesMutex);
        return NULL;
    }
    memcpy(copiedMessage, foundMessage, sizeof(LTE_RRC_NAS_MESSAGE));

    // Unlock the mutex and return a copy of the message structure
    pthread_mutex_unlock(&messagesMutex);
    return copiedMessage;
}

// Function to handle asynchronous notifications through a signal handler
void handleSignal(int signum) {
    // Check if the signal is relevant to this thread
    if (signum != SIGUSR1 && signum != SIGUSR2) {
        return;
    }

    // Lock the mutex to prevent concurrent modifications
    pthread_mutex_lock(&messagesMutex);

    // Check if there are any messages waiting to be processed
    if (numMessages == 0) {
        // Unlock the mutex and return
        pthread_mutex_unlock(&messagesMutex);
        return;
