int initResourceBundle(struct ResourceBundle* resourceBundle) {
    createResourceBundle();
    loadResourceBundleFromFile("initial_resource_bundle.txt");
    return 1; // Success
}

// Define a function to update the resource bundle with new data from the network
int updateResourceBundle(struct ResourceBundle* resourceBundle, struct NFAPI_CRC_INDICATION_REL8_MESSAGE_T* crcIndication) {
    for (size_t i = 0; i < resourceBundle->nfapiCrcIndicationPduCount; i++) {
        if (resourceBundle->nfapiCrcIndicationPduList[i].RNTI == crcIndication->rnti) {
            resourceBundle->nfapiCrcIndicationPduList[i].CRC_INDICATION_REL8_TAG = crcIndication->crc_indication;
        }
    }

    return 1; // Success
}

// Define a function to get the current resource bundle data from the network
int getResourceBundleData(struct ResourceBundle* resourceBundle) {
    struct NFAPI_CRC_INDICATION_REL8_MESSAGE_T crcIndication = {0};
    // Get the data from the network and update the resource bundle accordingly
    updateResourceBundle(resourceBundle, &crcIndication);

    return 1; // Success
}

// Define a function to save the current resource bundle data to a file
int saveCurrentResourceBundleDataToFile(struct ResourceBundle* resourceBundle) {
    FILE* file = fopen("current_resource_bundle.txt", "w");
    if (file == NULL) {
        printf("Error: unable to open file for writing\n");
        return 0; // Failure
    }

    for (size_t i = 0; i < resourceBundle->nfapiCrcIndicationPduCount; i++) {
        fprintf(file, "%hhu %u %hhu\n", resourceBundle->nfapiCrcIndicationPduList[i].RX_UE_INFORMATION_TAG, resourceBundle->nfapiCrcIndicationPduList[i].rnti, resourceBundle->nfapiCrcIndicationPduList[i].crc_indication);
    }

    return 1; // Success
}
