#define NFAPI_CRC_INDICATION_PDU_SIZE sizeof(NFAPI_CRC_INDICATION_PDU_T)

// Define the maximum number of data points that can be stored in the hash table
#define MAX_DATA_POINTS 1024

// Define the type of data points to store in the hash table
typedef struct {
    double value;
    float range;
    long timestamp;
} data_point_t;

// Define the structure for storing CRC indication PDUs
typedef struct {
    uint16_t rx_ue_information_tag;
    uint32_t rnti;
