} NFAPI_CRC_INDICATION_PDU_T;

// Define the hash table structure
typedef struct {
    // The array of data points stored in the hash table
    data_point_t* data_points[MAX_DATA_POINTS];
    // The number of elements in the hash table
    size_t num_elements;
} hash_table_t;

// Define the lock-free or spin-lock approach for handling concurrent access to the hash table
typedef struct {
    pthread_spinlock_t lock;
    int locked;
} spin_lock_t;

// Define the logging mechanism to record the frequency and timestamps of array resizes
typedef struct {
    size_t num_resizes;
    long resize_timestamps[MAX_DATA_POINTS];
} resize_log_t;

// Initialize the hash table with a default capacity
void init_hash_table(hash_table_t* ht) {
    // Initialize the array of data points to NULL
    for (int i = 0; i < MAX_DATA_POINTS; i++) {
        ht->data_points[i] = NULL;
    }
    // Set the number of elements in the hash table to zero
    ht->num_elements = 0;
}

// Insert a new data point into the hash table, allocating memory dynamically if necessary
void insert_data_point(hash_table_t* ht, double value, float range, long timestamp) {
    // Increase the size of the array if it is full
    if (ht->num_elements == MAX_DATA_POINTS) {
        // Allocate a new array with twice the capacity of the previous one
        int new_capacity = 2 * ht->num_elements;
        data_point_t* new_data_points = (data_point_t*)malloc(new_capacity * sizeof(data_point_t));
        // Copy the existing elements to the new array
        for (int i = 0; i < ht->num_elements; i++) {
            new_data_points[i] = ht->data_points[i];
        }
        // Free the old array and replace it with the new one
        free(ht->data_points);
        ht->data_points = new_data_points;
    }
    // Allocate memory for the new data point
    size_t index = ht->num_elements++;
    data_point_t* new_data_point = (data_point_t*)malloc(sizeof(data_point_t));
    if (new_data_point == NULL) {
        // Log the allocation error to a predefined error log
        printf("Error: Failed to allocate memory for data point %zu\n", index);
    } else {
        new_data_point->value = value;
        new_data_point->range = range;
        new_data_point->timestamp = timestamp;
        ht->data_points[index] = new_data_point;
    }
}

// Remove an existing data point from the hash table, freeing its memory
void remove_data_point(hash_table_t* ht, size_t index) {
    // Check if the index is within the bounds of the array
    if (index >= ht->num_elements) {
        return;
    }
    // Decrease the number of elements in the hash table
    ht->num_elements--;
    // Free the memory allocated for the data point
    free(ht->data_points[index]);
    // Shift all subsequent elements to fill the gap
    for (int i = index; i < ht->num_elements; i++) {
        ht->data_points[i] = ht->data_points[i + 1];
    }
}

// Look up a data point in the hash table by its value and range, returning NULL if not found
data_point_t* lookup_data_point(hash_table_t* ht, double value, float range) {
    // Check if the hash table is empty
    if (ht->num_elements == 0) {
        return NULL;
    }
    // Loop over the elements in the hash table
    for (int i = 0; i < ht->num_elements; i++) {
        data_point_t* data_point = ht->data_points[i];
        if (fabs(value - data_point->value) <= range && fabs(range - data_point->range) <= range) {
            return data_point;
        }
    }
    // If the loop completes without finding a match, return NULL
    return NULL;
}

// Remove an existing data point from the hash table by its value and range, freeing its memory
void remove_data_point(hash_table_t* ht, double value, float range) {
    // Find the index of the data point to be removed
    size_t index = 0;
    for (int i = 0; i < ht->num_elements; i++) {
        data_point_t* data_point = ht->data_points[i];
        if (fabs(value - data_point->value) <= range && fabs(range - data_point->range) <= range) {
            index = i;
            break;
        }
    }
    // If a match is found, remove the data point and return
    if (index < ht->num_elements) {
        remove_data_point(ht, index);
    }
}

// Print all the elements in the hash table to the console
void print_hash_table(hash_table_t* ht) {
    // Check if the hash table is empty
    if (ht->num_elements == 0) {
        printf("The hash table is empty.\n");
        return;
    }
    // Print each element in the hash table on a new line
    for (int i = 0; i < ht->num_elements; i++) {
        data_point_t* data_point = ht->data_points[i];
        printf("Data point %zu: value=%f, range=%f, timestamp=%ld\n", i, data_point->value, data_point->range, data_point->timestamp);
    }
}

// Free the memory allocated for the hash table and its elements
void free_hash_table(hash_table_t* ht) {
    // Check if the hash table is empty
    if (ht->num_elements == 0) {
        return;
    }
    // Loop over all the elements in the hash table and free their memory
    for (int i = 0; i < ht->num_elements; i++) {
        data_point_t* data_point = ht->data_points[i];
        free(data_point);
    }
    // Free the array of data points
    free(ht->data_points);
}

// Implement a lock-free or spin-lock approach for handling concurrent access to the hash table
void lock_hash_table(spin_lock_t* sl) {
    // Initialize the locked flag to false
    sl->locked = 0;
    // Acquire the lock by setting the locked flag to true
    __atomic_store_n(&sl->locked, 1, __ATOMIC_SEQ_CST);
}

// Implement a lock-free or spin-lock approach for handling concurrent access to the hash table
void unlock_hash_table(spin_lock_t* sl) {
    // Release the lock by setting the locked flag to false
    __atomic_store_n(&sl->locked, 0, __ATOMIC_SEQ_CST);
}

