}

// Implement a logging mechanism for recording the frequency and timestamps of array resizes
void log_resize(resize_log_t* rl, size_t new_capacity) {
    // Increment the resize count by one
    __atomic_fetch_add(&rl->resize_count, 1, __ATOMIC_SEQ_CST);
    // Record the current timestamp in the resize log
    rl->resize_timestamps[rl->resize_index] = get_current_time();
    // Increment the resize index by one
    __atomic_fetch_add(&rl->resize_index, 1, __ATOMIC_SEQ_CST);
}

// Implement a logging mechanism for recording the frequency and timestamps of array resizes
void print_resize_log(resize_log_t* rl) {
    // Print the resize count and resize timestamps to the console
    printf("Resize count: %zu\n", rl->resize_count);
    for (size_t i = 0; i < rl->resize_index; i++) {
        printf("Resize timestamp %zu: %ld\n", i, rl->resize_timestamps[i]);
