```c
// lock_free_hash_table_spinlock.h

#ifndef LOCK_FREE_HASH_TABLE_SPINLOCK_H
#define LOCK_FREE_HASH_TABLE_SPINLOCK_H

#include <atomic>
#include <iostream>
#include <vector>

template<typename Key, typename Value>
class LockFreeHashTableSpinlock {
public:
    LockFreeHashTableSpinlock(size_t init_capacity);
    ~LockFreeHashTableSpinlock();

    bool insert(const Key& key, const Value& value);
    bool erase(const Key& key);
    bool find(const Key& key, Value* value);
    size_t size() const;

private:
    struct Node {
        Key key;
        Value value;
        std::atomic<Node*> next;
    };

    std::atomic<size_t> _size;
    std::atomic<Node*> _head;
    std::vector<std::atomic<Node*>> _buckets;
    std::atomic_flag _lock = ATOMIC_FLAG_INIT;
};

#endif
