```c
// lock_free_hash_table_spinlock.cpp

#include "lock_free_hash_table_spinlock.h"

template<typename Key, typename Value>
LockFreeHashTableSpinlock<Key, Value>::LockFreeHashTableSpinlock(size_t init_capacity) : _size(0), _head(nullptr) {
    _buckets.resize(init_capacity);
}

template<typename Key, typename Value>
LockFreeHashTableSpinlock<Key, Value>::~LockFreeHashTableSpinlock() {
    Node* curr = _head;
    while (curr != nullptr) {
        Node* next = curr->next.load();
        delete curr;
        curr = next;
    }
}

template<typename Key, typename Value>
bool LockFreeHashTableSpinlock<Key, Value>::insert(const Key& key, const Value& value) {
    size_t bucket_idx = key % _buckets.size();
    Node* new_node = new Node{key, value, nullptr};
    while (!_lock.test_and_set()) {} // spin lock
    Node* prev_head = _head;
    while (prev_head != nullptr) {
        if ((new_node->key % _buckets.size()) == bucket_idx) {
            new_node->next = _buckets[bucket_idx];
            _buckets[bucket_idx] = new_node;
            _lock.clear();
            break;
        } else {
            prev_head = prev_head->next.load();
            bucket_idx = (bucket_idx + 1) % _buckets.size();
        }
    }
    if (_lock.test_and_set()) { // spin lock
        _size++;
    }
    return true;
}

template<typename Key, typename Value>
bool LockFreeHashTableSpinlock<Key, Value>::erase(const Key& key) {
    size_t bucket_idx = key % _buckets.size();
    Node* prev = nullptr;
    while (!_lock.test_and_set()) {} // spin lock
    for (Node* curr = _head; curr != nullptr; curr = curr->next.load()) {
        if ((curr->key % _buckets.size()) == bucket_idx) {
            if (prev == nullptr) {
                _head = curr->next.load();
            } else {
                prev->next = curr->next.load();
            }
            delete curr;
            _lock.clear();
            break;
        } else {
            prev = curr;
            bucket_idx = (bucket_idx + 1) % _buckets.size();
        }
    }
    if (_lock.test_and_set()) { // spin lock
        _size--;
    }
    return false;
}

template<typename Key, typename Value>
bool LockFreeHashTableSpinlock<Key, Value>::find(const Key& key, Value* value) {
    size_t bucket_idx = key % _buckets.size();
    while (!_lock.test_and_set()) {} // spin lock
    for (Node* curr = _head; curr != nullptr; curr = curr->next.load()) {
        if ((curr->key % _buckets.size()) == bucket_idx) {
            *value = curr->value;
            _lock.clear();
            return true;
        } else {
            prev = curr;
            bucket_idx = (bucket_idx + 1) % _buckets.size();
        }
    }
    if (_lock.test_and_set()) { // spin lock
        _size--;
    }
    return false;
}

template<typename Key, typename Value>
size_t LockFreeHashTableSpinlock<Key, Value>::size() const {
    while (!_lock.test_and_set()) {} // spin lock
    size_t s = _size;
    _lock.clear();
    return s;
}
