    while (fgets(buffer, BUFFER_SIZE, fp)) {
        // Parse CSV line and validate transaction
        transaction_t txn = parse_csv_line(buffer);
        if (!validate_transaction(&txn)) {
            log_status("Error: invalid transaction");
            continue;
        }

        // Calculate totals for user IDs and average transaction value
        calculate_totals(&txn, 1);
    }

    fclose(fp);

    return NULL;
}

void *fetch_remote_data(void *args) {
    // Fetch remote data from API endpoint
    char *api_url = "https://example.com/api/transactions";
    FILE *fp = fopen("remote_data.txt", "w");
    if (fp == NULL) {
        log_status("Error: unable to open file for writing remote data");
        return 0;
    }

    char buffer[READ_BUFFER_SIZE];
    while (fgets(buffer, READ_BUFFER_SIZE, fp)) {
        // Parse JSON line and validate transaction
        transaction_t txn = parse_json_line(buffer);
        if (!validate_transaction(&txn)) {
            log_status("Error: invalid transaction");
            continue;
        }

        // Calculate totals for user IDs and average transaction value
        calculate_totals(&txn, 1);
    }

    fclose(fp);

    return NULL;
}

void *generate_report(void *args) {
    FILE *fp = fopen("activity_report.txt", "w");
    if (fp == NULL) {
        log_status("Error: unable to open file for writing report");
        return 0;
    }

    // Generate report data
    transaction_t *txns = malloc(sizeof(transaction_t) * MAX_TRANSACTIONS);
    int num_txns = calculate_totals(txns, MAX_TRANSACTIONS);
    generate_report_data(txns, num_txns);

    // Write report to file
    write_report(fp, txns, num_txns);

    fclose(fp);

    return NULL;
}

void *free_memory(void *args) {
    free(txns);

    return NULL;
}

int validate_transaction(transaction_t *txn) {
    // Check for invalid user ID and timestamp range
    if (txn->user_id < 0 || txn->user_id > USER_ID_RANGE) {
        return 0;
    }
    if (txn->timestamp < time(NULL) - TIMESTAMP_RANGE || txn->timestamp > time(NULL)) {
        return 0;
    }

    // Check for invalid amount range
    if (txn->amount < MIN_AMOUNT || txn->amount > MAX_AMOUNT) {
        return 0;
    }

    return 1;
}

int calculate_totals(transaction_t *txns, int num_txns) {
    for (int i = 0; i < num_txns; i++) {
        // Calculate totals for user IDs and average transaction value
        if (txns[i].user_id >= 0 && txns[i].user_id <= USER_ID_RANGE) {
            // Update totals for user ID
            int total = users[txns[i].user_id].total;
            total += txns[i].amount;
            users[txns[i].user_id].total = total;

            // Update average transaction value
            double avg = users[txns[i].user_id].avg;
            int num = users[txns[i].user_id].num;
            avg += (double)txns[i].amount / num;
            users[txns[i].user_id].avg = avg;
        }
    }

    return 0;
}

void generate_report_data(transaction_t *txns, int num_txns) {
    // Generate report data for each user ID
    for (int i = 0; i < num_txns; i++) {
        if (users[txns[i].user_id].total >= 0 && users[txns[i].user_id].total <= MAX_TOTAL) {
            // Generate report data for user ID
            printf("User ID: %d\n", txns[i].user_id);
            printf("Total: %.2f\n", users[txns[i].user_id].total);
            printf("Average transaction value: %.2f\n", users[txns[i].user_id].avg);
        }
    }
}

void write_report(FILE *fp, transaction_t *txns, int num_txns) {
    // Write report to file
    for (int i = 0; i < num_txns; i++) {
        fprintf(fp, "User ID: %d\n", txns[i].user_id);
        fprintf(fp, "Total: %.2f\n", users[txns[i].user_id].total);
        fprintf(fp, "Average transaction value: %.2f\n", users[txns[i].user_id].avg);
    }
}

void log_status(char *status) {
    // Log status messages to file
    FILE *log_file = fopen("log.txt", "a");
    if (log_file == NULL) {
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char log_message[100];
    strftime(log_message, sizeof(log_message), "%Y-%m-%d %H:%M:%S ", &tm);
    strcat(log_message, status);

    fprintf(log_file, log_message);
    fclose(log_file);
}
