// Define structure for NIC statistics
typedef struct nic_stats {
    MAC_HEADER mac_header;
    IP_PACKET ip_packet;
} nic_stats_t;

// Define array of NIC statistics structures
nic_stats_t* nic_stats_array = NULL;
size_t nic_stats_array_len = 0;

// Initialize dynamic array of NIC statistics structures
void init_nic_stats(size_t num_entries) {
    // Allocate memory for the dynamic array of NIC statistics structures
    nic_stats_array = malloc(sizeof(nic_stats_t) * num_entries);
    if (nic_stats_array == NULL) {
        printf("Error: unable to allocate memory for NIC statistics array\n");
        exit(1);
    }
    // Initialize each entry in the dynamic array with a valid MAC header and IP packet
    for (size_t i = 0; i < num_entries; i++) {
        nic_stats_array[i].mac_header.valid = true;
        nic_stats_array[i].ip_packet.checksum = ip_packet_checksum(nic_stats_array[i].ip_packet);
    }
}

// Free memory allocated for the dynamic array of NIC statistics structures
void free_nic_stats() {
    if (nic_stats_array != NULL) {
        free(nic_stats_array);
        nic_stats_array = NULL;
    }
}

// Add a new entry to the dynamic array of NIC statistics structures
void add_nic_stat(size_t index, MAC_HEADER mac_header, IP_PACKET ip_packet) {
    // Check if the index is valid
    if (index >= nic_stats_array_len) {
        printf("Error: invalid index %lu for NIC statistics array\n", index);
        return;
    }
    // Add a new entry to the dynamic array with the specified MAC header and IP packet
    nic_stats_array[index].mac_header = mac_header;
    nic_stats_array[index].ip_packet = ip_packet;
}

// Retrieve an entry from the dynamic array of NIC statistics structures
void get_nic_stat(size_t index, MAC_HEADER* mac_header, IP_PACKET* ip_packet) {
    // Check if the index is valid
    if (index >= nic_stats_array_len) {
        printf("Error: invalid index %lu for NIC statistics array\n", index);
        return;
    }
    // Retrieve the specified entry from the dynamic array
    *mac_header = nic_stats_array[index].mac_header;
    *ip_packet = nic_stats_array[index].ip_packet;
}

// Validate the integrity of the IP packet checksums in the dynamic array of NIC statistics structures
void validate_nic_stats() {
    for (size_t i = 0; i < nic_stats_array_len; i++) {
        // Calculate the expected checksum for each entry in the dynamic array
        uint16_t expected_checksum = ip_packet_checksum(nic_stats_array[i].ip_packet);
        // Compare the actual checksum with the expected checksum
        if (expected_checksum != nic_stats_array[i].ip_packet.checksum) {
            printf("Error: invalid IP packet checksum for entry %lu in NIC statistics array\n", i);
        }
    }
}

// Calculate the checksum for an IP packet
uint16_t ip_packet_checksum(IP_PACKET ip_packet) {
    // Initialize the checksum to zero
    uint32_t checksum = 0;
    // Iterate over each word in the IP header
    for (size_t i = 0; i < sizeof(ip_packet.header) / sizeof(uint16_t); i++) {
        // Calculate the sum of all words in the IP header
        checksum += htons(ip_packet.header[i]);
    }
    // Return the checksum as a 16-bit integer
    return (checksum >> 16) + (checksum & 0xffff);
}
