void allocate_and_init_network_statistics(int num_records, int payload_size) {
  // Allocate memory for the array of network statistics structures
  network_statistics **stats = malloc(sizeof(network_statistics *) * num_records);
  if (stats == NULL) {
    printf("Failed to allocate memory for network statistics\n");
    return;
  }

  // Initialize each structure with a valid MAC_HEADER and IP_PACKET
  for (int i = 0; i < num_records; i++) {
    stats[i] = malloc(sizeof(network_statistics));
    if (stats[i] == NULL) {
      printf("Failed to allocate memory for network statistics\n");
      return;
    }
    stats[i]->mac_header = malloc(sizeof(MAC_HEADER));
    if (stats[i]->mac_header == NULL) {
      printf("Failed to allocate memory for MAC header\n");
      return;
    }
    stats[i]->ip_packet = malloc(sizeof(IP_PACKET));
    if (stats[i]->ip_packet == NULL) {
      printf("Failed to allocate memory for IP packet\n");
      return;
    }
    // Initialize the MAC header and IP packet with random data
    memset(stats[i]->mac_header, 0x00, sizeof(MAC_HEADER));
    memset(stats[i]->ip_packet, 0x00, sizeof(IP_PACKET));
    // Initialize the payload size for each IP packet
    stats[i]->ip_packet->payload_size = payload_size;
    // Generate a random payload for each IP packet
    generate_random_payload(&stats[i]->ip_packet->payload, payload_size);
  }

  // Validate the integrity of the IP packet checksums upon insertion into the array
  for (int i = 0; i < num_records; i++) {
    validate_ip_checksum(&stats[i]->ip_packet);
  }
}

void free_network_statistics(network_statistics **stats, int num_records) {
  // Free the memory allocated for each network statistics structure
  for (int i = 0; i < num_records; i++) {
    if (stats[i] != NULL) {
      free(stats[i]->mac_header);
      free(stats[i]->ip_packet->payload);
      free(stats[i]);
    }
  }
  // Free the memory allocated for the array of network statistics structures
  free(stats);
}

void generate_random_payload(char **payload, int payload_size) {
  srand(time(NULL));
  *payload = malloc(sizeof(char *) * payload_size);
  if (*payload == NULL) {
    printf("Failed to allocate memory for payload\n");
    return;
  }
  // Generate a random payload of the specified size
  for (int i = 0; i < payload_size; i++) {
    (*payload)[i] = rand() % 256;
  }
}

void validate_ip_checksum(IP_PACKET *ip_packet) {
  // Validate the IP packet checksum using the appropriate library function
  int checksum = inet_checksum(ip_packet->payload, ip_packet->payload_size);
  if (checksum != ip_packet->checksum) {
    printf("IP checksum validation failed\n");
    return;
  }
}
