        for (int j = 0; j < num_states; j++) {
            // Update the state list with the new transition
            if (transition->from[j].id == current->states[j].id && transition->from[j].version == current->states[j].version) {
                states[j] = malloc(sizeof(struct state));
                if (!states[j]) {
                    fprintf(stderr, "Error: Failed to allocate memory for state\n");
                    exit(EXIT_FAILURE);
                }
                *states[j] = transition->to[j];
            } else {
                states[j] = NULL;
            }
        }
    }

    // Validate the state lists and ensure they adhere to the FSA transition rules
    if (!validate_states(states, num_states)) {
        free(states);
        return NULL;
    }

    struct state_list *next = create_state_list(fsa, states, num_states);
    free(states);
    return next;
}

// Define function to get the previous state list from a given FSA and current state list
struct state_list *get_previous_state_list(struct fsa *fsa, struct state_list *current) {
    // Initialize variables
    struct state **states = malloc(sizeof(struct state *) * fsa->num_states);
    if (!states) {
        fprintf(stderr, "Error: Failed to allocate memory for state array\n");
        exit(EXIT_FAILURE);
    }
    int num_states = fsa->num_states;

    // Iterate through the FSA transitions and update the state lists accordingly
    for (int i = 0; i < fsa->num_transitions; i++) {
        struct transition *transition = &fsa->transitions[i];
        if (!validate_states(transition->from, transition->to)) {
            free(states);
            return NULL;
        }
        for (int j = 0; j < num_states; j++) {
            // Update the state list with the new transition
            if (transition->to[j].id == current->states[j].id && transition->to[j].version == current->states[j].version) {
                states[j] = malloc(sizeof(struct state));
                if (!states[j]) {
                    fprintf(stderr, "Error: Failed to allocate memory for state\n");
                    exit(EXIT_FAILURE);
                }
                *states[j] = transition->from[j];
            } else {
                states[j] = NULL;
            }
        }
    }

    // Validate the state lists and ensure they adhere to the FSA transition rules
    if (!validate_states(states, num_states)) {
        free(states);
        return NULL;
    }

    struct state_list *previous = create_state_list(fsa, states, num_states);
    free(states);
    return previous;
}

// Define function to get the next version number from a given FSA and current state list
int get_next_version(struct fsa *fsa, struct state_list *current) {
    // Initialize variables
    int max_version = 0;
    for (int i = 0; i < fsa->num_states; i++) {
        if (max_version < current->states[i].version) {
            max_version = current->states[i].version;
        }
    }
    return max_version + 1;
}

// Define function to get the previous version number from a given FSA and current state list
int get_previous_version(struct fsa *fsa, struct state_list *current) {
    // Initialize variables
    int min_version = INT_MAX;
    for (int i = 0; i < fsa->num_states; i++) {
        if (min_version > current->states[i].version) {
            min_version = current->states[i].version;
        }
    }
    return min_version - 1;
