NetworkEventPDU* init_and_populate(int batch_size, int *count) {
    // Allocate memory for the array of NetworkEventPDU structures
    NetworkEventPDU* arr = (NetworkEventPDU*)malloc(sizeof(NetworkEventPDU) * batch_size);
    if (!arr) {
        printf("Error: Failed to allocate memory for the array of NetworkEventPDU structures\n");
