        time_t timestamp = time(NULL); // Get the current timestamp
        char DataTransmissionStatus = 'N'; // Set the default status to 'N' for not transmitted

        // Add a new NetworkEventPDU structure to the array
        arr[*count].UEContext = UEContext;
        arr[*count].timestamp = timestamp;
        arr[*count].DataTransmissionStatus = DataTransmissionStatus;

        (*count)++;
    }

    return arr;
}

// Function to handle resource throttling for the NetworkEventPDU array
void throttle_resources(NetworkEventPDU* arr, int batch_size, int *count) {
    // Check if the current count is greater than the batch size
    if (*count > batch_size) {
        // Reduce the count by 1 to prevent overflow during bursts of activity
        (*count)--;
    }
}

