    // Check if the array is full and needs to be resized
    if (arr->count == arr->capacity) {
        // Resize the array by a factor of 2
        arr->capacity *= 2;
        tcp_connection_t* new_connections = realloc(arr->connections, arr->capacity * sizeof(tcp_connection_t));
        if (new_connections == NULL) {
