    tcp_connection_t* new_conn = create_new_connection(src_ip, src_port, dest_ip, dest_port);
    if (new_conn == NULL) {
        return false;
    }
    arr->connections[arr->count++] = *new_conn;
    return true;
}

// Function to remove a connection from the array and resize if necessary
void remove_connection(tcp_connection_array_t* arr, uint32_t src_ip, uint16_t src_port, uint32_t dest_ip, uint16_t dest_port) {
    // Find the index of the connection to be removed
    size_t idx = 0;
    for (size_t i = 0; i < arr->count; i++) {
        if (arr->connections[i].src_ip == src_ip && arr->connections[i].src_port == src_port && arr->connections[i].dest_ip == dest_ip && arr->connections[i].dest_port == dest_port) {
            idx = i;
            break;
        }
    }

    // If the connection was found, remove it from the array and resize if necessary
    if (idx < arr->count) {
        arr->count--;
        for (size_t i = idx; i < arr->count; i++) {
            arr->connections[i] = arr->connections[i + 1];
        }
        // Resize the array by a factor of 2 if there are fewer than half filled slots left
        if (arr->count * 2 <= arr->capacity) {
            arr->capacity /= 2;
            tcp_connection_t* new_connections = realloc(arr->connections, arr->capacity * sizeof(tcp_connection_t));
            if (new_connections == NULL) {
                return;
            }
            arr->connections = new_connections;
        }
    }
}

