    HashMap<Integer, Integer> union_find = new HashMap<>();

    // Iterate through the array and perform union and find operations as needed
    int count = 0;
    for (int i = 0; i < arr.length - 1; i++) {
        if (!union_find.containsKey(arr[i])) {
            union_find.put(arr[i], arr[i]); // put the element in the hash map with itself as its parent
        }
        for (int j = i + 1; j < arr.length; j++) {
            if (!union_find.containsKey(arr[j])) {
