}

// C function to generate a checksum for an IP packet based on its data and payload size
unsigned short generate_checksum(char* data, int payload_size) {
    // Initialize the checksum with a random value
    unsigned short checksum = rand() % 65536;

    // Iterate through the data and calculate the checksum using the Fletcher-Checksum algorithm
    for (int i = 0; i < payload_size; i++) {
        checksum += (unsigned char)data[i];
        if (checksum > 65535) { // if the checksum overflows, reset it to 0
            checksum = 0;
        }
    }
    return checksum;
}

