// Define a hash table to store the RNTIs for quick validation
static uint32_t *rntiHashTable = NULL;

/*
 * Function to initialize the list of structures and allocate memory for the hash table
 */
void initList(size_t N) {
    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        // Handle memory allocation failure
        return;
    }

    // Initialize the structures in the array
    for (size_t i = 0; i < N; ++i) {
        list[i].RX_UE_INFORMATION_TAG = 0;
        list[i].RNTI = 0;
        list[i].CRCFLAG = 0;
    }

    // Allocate memory for the hash table and initialize it with the default value of 0
    rntiHashTable = (uint32_t *)malloc(N * sizeof(uint32_t));
    if (!rntiHashTable) {
        // Handle memory allocation failure
        return;
    }
    memset(rntiHashTable, 0, N * sizeof(uint32_t));
}

/*
 * Function to add a new structure to the list and set its CRCFLAG based on the content of the RX_UE_INFORMATION_TAG
 */
void addStructure(NFAPI_CRC_INDICATION_PDU_T *structure) {
    // Check if the list is initialized
    if (!rntiHashTable) {
        // Initialize the list and hash table if not yet done
        initList(1);
    }

    // Calculate the hash value for the RNTI to check for collisions
    uint32_t hashValue = structure->RNTI % (sizeof(rntiHashTable) / sizeof(uint32_t));

    // Check if the RNTI is already in the list and set the CRCFLAG accordingly
    while (rntiHashTable[hashValue] != 0 && rntiHashTable[hashValue] != structure->RNTI) {
        hashValue++;
        hashValue %= sizeof(rntiHashTable) / sizeof(uint32_t);
    }
    if (rntiHashTable[hashValue] == 0) {
        // The RNTI is not in the list, add it and set the CRCFLAG based on the content of the RX_UE_INFORMATION_TAG
        structure->CRCFLAG = (structure->RX_UE_INFORMATION_TAG & 0x1) ? 1 : 0;
        rntiHashTable[hashValue] = structure->RNTI;
    } else {
        // The RNTI is already in the list, set the CRCFLAG to the value stored in the previous instance
        structure->CRCFLAG = (structure->RX_UE_INFORMATION_TAG & 0x1) ? 1 : 0;
    }
}

/*
 * Function to remove a structure from the list and update the hash table accordingly
 */
void removeStructure(NFAPI_CRC_INDICATION_PDU_T *structure) {
    // Check if the list is initialized
    if (!rntiHashTable) {
        return;
    }

    // Calculate the hash value for the RNTI to check for collisions
    uint32_t hashValue = structure->RNTI % (sizeof(rntiHashTable) / sizeof(uint32_t));

    // Check if the RNTI is in the list and remove it accordingly
    while (rntiHashTable[hashValue] != 0 && rntiHashTable[hashValue] != structure->RNTI) {
        hashValue++;
        hashValue %= sizeof(rntiHashTable) / sizeof(uint32_t);
    }
    if (rntiHashTable[hashValue] == structure->RNTI) {
