// Define data structures for records and BST nodes
typedef struct {
  int key;
} Record;

typedef struct Node {
  Record record;
  struct Node *left, *right;
} Node;

// Define data structure for CRC indication PDUs
typedef struct {
  uint16_t RX_UE_INFORMATION_TAG;
  uint16_t RNTI;
  uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define data structure for encryption modes and key sizes
typedef struct {
  char *mode;
  int keysize;
} EncryptionMode;

// Define array of supported encryption modes and their corresponding key sizes
