  {"ECB", 8},
  {"EDE", 16},
  {"EDE3", 24},
  {"CFB", 32}
};

// Define function to generate random values for each record's int field within a specified range
void generateRandomInt(int *random_int) {
  srand(time(NULL));
  *random_int = rand() % 10;
}

// Define function to insert a new record into the BST and maintain balance
Node* insertRecord(Node *root, Record record) {
  if (root == NULL) {
    return new Node(record);
  } else if (record.key < root->key) {
    root->left = insertRecord(root->left, record);
  } else if (record.key > root->key) {
    root->right = insertRecord(root->right, record);
  }
  return root;
}

// Define function to delete a record from the BST and maintain balance
Node* deleteRecord(Node *root, int key) {
  if (root == NULL || key < root->key) {
    return root;
  } else if (key > root->key) {
    root->right = deleteRecord(root->right, key);
  } else {
    Node *temp = root->left;
    free(root);
    return temp;
  }
}

