NFAPI_CRC_INDICATION_PDU_T* createAndPopulateLinkedList(int numEntries) {
    // Create a pointer to the head of the linked list
    struct LinkedListNode *head = NULL;

    // Create a new node for each entry in the linked list
    for (int i = 0; i < numEntries; i++) {
        struct LinkedListNode *newNode = malloc(sizeof(struct LinkedListNode));
        newNode->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        newNode->next = NULL;

        // Initialize the data in the NFAPI_CRC_INDICATION_PDU_T structure
