        data->RX_UE_INFORMATION_TAG = i;
        data->RNTI = rand();
        data->CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2 == 0) ? true : false;

        // Add the new node to the end of the linked list
        if (head == NULL) {
            head = newNode;
        } else {
            struct LinkedListNode *current = head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = newNode;
        }
    }

    // Return the head of the linked list
    return head;
}

// Function to safely deallocate a linked list of NFAPI_CRC_INDICATION_PDU_T structures
void freeLinkedList(struct LinkedListNode *head) {
    if (head == NULL) {
        return;
    }
    struct LinkedListNode *current = head;
    while (current != NULL) {
        struct LinkedListNode *next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
}
