// Define a memory pool for dynamic allocation of arrays
struct MemoryPool {
    size_t size;
    void *memory;
};

// Function to initialize the memory pool with a specific size
void initMemoryPool(struct MemoryPool *pool, size_t size) {
    assert(pool != NULL);
    pool->size = size;
    pool->memory = malloc(size);
}

// Function to allocate memory from the memory pool
void *allocateFromPool(struct MemoryPool *pool, size_t size) {
    assert(pool != NULL && size <= pool->size);
    void *ptr = (char *)pool->memory + pool->used;
    pool->used += size;
    return ptr;
}

// Function to deallocate memory from the memory pool
void deallocateFromPool(struct MemoryPool *pool, void *ptr) {
    assert(pool != NULL && ptr >= pool->memory && (char *)ptr <= (char *)pool->memory + pool->used);
    size_t size = (char *)ptr - (char *)pool->memory;
    pool->used -= size;
}

// Function to check if a key is already present in the record array
int isKeyPresent(Record *records, int numRecords, int key) {
    for (int i = 0; i < numRecords; i++) {
        if (records[i].key == key) return 1;
    }
    return 0;
