static const char* DEFAULT_THEME_DIR = "/path/to/default/theme/directory";

int initialize_crypto(const char* password, int mode) {
    // Initialize AES-256-CBC cipher using OpenSSL library
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, NULL, NULL);

    // Hash password using SHA-256 for deriving encryption key
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, password, strlen(password));
    SHA256_Final(hash, &sha256);

    // Set encryption key and IV lengths based on cipher mode
    int key_length = 32;
    int iv_length = 16;
    if (mode == NFAPI_CRC_INDICATION_REL8_TAG) {
        key_length = 24;
        iv_length = 8;
    }

    // Set encryption key and IV using derived hash value
    EVP_EncryptInit_ex(ctx, NULL, NULL, hash, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, iv_length, NULL);
    EVP_CIPHER_CTX_set_key_length(ctx, key_length);

    // Initialize theme caching system
    char* theme_dir = getenv("THEME_DIR");
    if (theme_dir == NULL) {
        theme_dir = DEFAULT_THEME_DIR;
    }
    ThemeCache* cache = new ThemeCache(theme_dir);

