    std::vector<std::string> themes;
    if (fetch_themes(&themes)) {
        for (const auto& theme : themes) {
            cache->set(theme, NULL);
        }
    }

    // Clean up resources and handle errors gracefully
    EVP_CIPHER_CTX_free(ctx);
    delete cache;

    return 0;
}
