// NIC statistics structure
typedef struct {
    uint8_t mac_header[6]; // MAC header of the packet
    uint32_t ip_packet_size; // size of the IP packet
    uint16_t ip_checksum; // checksum of the IP packet
} nic_stats;

// dynamic array to store NIC statistics structures
typedef struct {
    nic_stats* stats; // pointer to an array of NIC statistics structures
    size_t size; // current size of the array
    size_t capacity; // maximum capacity of the array
} nic_stats_array;

// mutex for synchronizing access to the array
pthread_mutex_t array_mutex = PTHREAD_MUTEX_INITIALIZER;

// initialize a dynamic array of NIC statistics structures
void init_nic_stats_array(nic_stats_array* arr, size_t capacity) {
    // allocate memory for the array and its elements
    arr->stats = (nic_stats*)malloc(capacity * sizeof(nic_stats));
    arr->size = 0;
    arr->capacity = capacity;
}

// free a dynamic array of NIC statistics structures
void free_nic_stats_array(nic_stats_array* arr) {
    // release memory for the array and its elements
    free(arr->stats);
}

// insert a new NIC statistics structure into the array
// validate the IP checksum upon insertion
void insert_nic_stats(nic_stats_array* arr, nic_stats stats) {
    // acquire the mutex to prevent concurrent access
    pthread_mutex_lock(&array_mutex);

    // ensure that the array has enough capacity for a new element
    if (arr->size == arr->capacity) {
        // reallocate memory for the array and its elements
        arr->stats = (nic_stats*)realloc(arr->stats, 2 * arr->capacity * sizeof(nic_stats));
        arr->capacity *= 2;
    }

    // insert the new NIC statistics structure into the array
    arr->stats[arr->size] = stats;
    arr->size++;

    // release the mutex to allow other threads to access the array
    pthread_mutex_unlock(&array_mutex);
}

// remove a NIC statistics structure from the array by index
void remove_nic_stats(nic_stats_array* arr, size_t index) {
    // acquire the mutex to prevent concurrent access
    pthread_mutex_lock(&array_mutex);

    // validate that the index is within the bounds of the array
    if (index >= 0 && index < arr->size) {
        // move all elements after the removed element one position backward
        memmove(arr->stats + index, arr->stats + index + 1, (arr->size - index - 1) * sizeof(nic_stats));

        // reallocate memory for the array and its elements
        arr->stats = (nic_stats*)realloc(arr->stats, (arr->size - 1) * sizeof(nic_stats));
    }

    // release the mutex to allow other threads to access the array
    pthread_mutex_unlock(&array_mutex);
}

// validate the IP checksum of a NIC statistics structure by index
uint16_t validate_ip_checksum(nic_stats_array* arr, size_t index) {
    // acquire the mutex to prevent concurrent access
    pthread_mutex_lock(&array_mutex);

    // validate that the index is within the bounds of the array
    if (index >= 0 && index < arr->size) {
        // calculate the IP checksum for the NIC statistics structure
        uint16_t ip_checksum = calculate_ip_checksum(arr->stats[index].mac_header, arr->stats[index].ip_packet_size);

        // release the mutex to allow other threads to access the array
        pthread_mutex_unlock(&array_mutex);

        return ip_checksum;
    }

    // release the mutex to allow other threads to access the array
    pthread_mutex_unlock(&array_mutex);

    return 0;
}

// calculate IP checksum for a given MAC header and packet size
uint16_t calculate_ip_checksum(uint8_t* mac_header, uint32_t ip_packet_size) {
    // initialize the IP checksum with the initial value
    uint16_t ip_checksum = 0xffff;

    // iterate through each byte of the MAC header and add it to the IP checksum
    for (int i = 0; i < 6; i++) {
        ip_checksum += mac_header[i];
    }

    // iterate through each byte of the IP packet and add it to the IP checksum
    uint8_t* ip_packet = mac_header + 6;
    for (int i = 0; i < ip_packet_size; i++) {
        ip_checksum += *ip_packet++;
    }

    // return the final IP checksum
    return ~(ip_checksum ^ 0xffff);
}

// serialize the entire array structure for persistence
void serialize_nic_stats_array(nic_stats_array* arr, char* filename) {
    // open the file for writing
    FILE* fp = fopen(filename, "wb");

    // write the size of the array to the file
    fwrite(&arr->size, sizeof(size_t), 1, fp);

    // write each NIC statistics structure in the array to the file
    for (int i = 0; i < arr->size; i++) {
        fwrite(arr->stats[i].mac_header, 6, sizeof(uint8_t), fp);
        fwrite(&arr->stats[i].ip_packet_size, sizeof(uint32_t), 1, fp);
        fwrite(&arr->stats[i].ip_checksum, sizeof(uint16_t), 1, fp);
    }

    // close the file
    fclose(fp);
}

// deserialize the entire array structure from a file
void deserialize_nic_stats_array(char* filename) {
    // open the file for reading
    FILE* fp = fopen(filename, "rb");

    // read the size of the array from the file
    size_t size;
    fread(&size, sizeof(size_t), 1, fp);

    // allocate memory for the array and its elements
    nic_stats* stats = (nic_stats*)malloc(size * sizeof(nic_stats));

    // read each NIC statistics structure from the file into the array
    for (int i = 0; i < size; i++) {
        fread(stats[i].mac_header, 6, sizeof(uint8_t), fp);
        fread(&stats[i].ip_packet_size, sizeof(uint32_t), 1, fp);
        fread(&stats[i].ip_checksum, sizeof(uint16_t), 1, fp);
    }

    // create a new array structure and copy the contents of the deserialized array to it
    nic_stats_array* arr = (nic_stats_array*)malloc(sizeof(nic_stats_array));
    arr->size = size;
    arr->stats = stats;

    // close the file
    fclose(fp);
}
```

