void manage_memory(long* offsets, int* keys, record* records, size_t num_offsets, size_t num_keys, size_t num_records) {
    // Allocate memory for arrays
    long* offset_mem = malloc(num_offsets * sizeof(*offset_mem));
    int* key_mem = malloc(num_keys * sizeof(*key_mem));
    record* record_mem = malloc(num_records * sizeof(*record_mem));

    // Check if memory allocation failed
    assert(offset_mem != NULL && key_mem != NULL && record_mem != NULL);

    // Initialize arrays with specified range for integer values
    for (size_t i = 0; i < num_offsets; i++) {
        offset_mem[i] = rand() % (MAX_INT - MIN_INT + 1) + MIN_INT;
    }
    for (size_t i = 0; i < num_keys; i++) {
        key_mem[i] = rand() % (MAX_INT - MIN_INT + 1) + MIN_INT;
    }
    for (size_t i = 0; i < num_records; i++) {
        record_mem[i].value = rand() % (MAX_INT - MIN_INT + 1) + MIN_INT;
    }

    // Validate that no record's integer value exceeds the specified range
    for (size_t i = 0; i < num_records; i++) {
        assert(record_mem[i].value >= MIN_INT && record_mem[i].value <= MAX_INT);
    }

    // Balance memory usage efficiency by prioritizing which allocations to retain when memory constraints are exceeded
    size_t total_memory = num_offsets * sizeof(*offset_mem) + num_keys * sizeof(*key_mem) + num_records * sizeof(*record_mem);
    if (total_memory > MAX_MEMORY) {
        // Retain only the most critical allocations to avoid memory exhaustion
        offset_mem = realloc(offset_mem, MIN(MAX_MEMORY, total_memory));
        key_mem = realloc(key_mem, MIN(MAX_MEMORY, total_memory));
        record_mem = realloc(record_mem, MIN(MAX_MEMORY, total_memory));
    }

    // Free all allocated memory after usage to handle unexpected signals or crashes gracefully
    free(offset_mem);
    free(key_mem);
    free(record_mem);
}
