// Define the maximum size of the memory to be allocated
#define MAX_MEMORY (1024 * 1024) // 1 MB

// Define the cache line boundary, which is 64 bytes on most systems
#define CACHE_LINE_SIZE 64

// Define the maximum value for the integer values in the records
#define MAX_INT_VALUE INT_MAX

// Define the structure of the record to be stored
typedef struct {
    int value;
} Record;

// Define the function that allocates and initializes the memory
void initMemory(int num_offsets, int num_keys, int num_records) {
    // Calculate the total size of the arrays based on the number of records
    size_t offset_size = sizeof(long) * num_offsets;
    size_t key_size = sizeof(int) * num_keys;
    size_t record_size = sizeof(Record) * num_records;
    size_t total_size = offset_size + key_size + record_size;

    // Check if the total size exceeds the maximum allowed memory
    assert(total_size <= MAX_MEMORY);

    // Allocate memory for the arrays aligned to a cache line boundary
    void* mem = malloc(total_size + (CACHE_LINE_SIZE - 1));
    if (!mem) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }
    long* offsets = (long*)mem;
    int* keys = (int*)(offsets + num_offsets);
    Record* records = (Record*)(keys + num_keys);

    // Initialize the arrays with the specified range of integer values
    for (int i = 0; i < num_records; ++i) {
        int value = rand() % MAX_INT_VALUE;
        if (value > MAX_INT_VALUE / 2) {
            fprintf(stderr, "Value exceeds the maximum range\n");
            exit(EXIT_FAILURE);
        }
        records[i].value = value;
    }

    // Validate that no record's integer value exceeds the specified range
    for (int i = 0; i < num_records; ++i) {
        if (records[i].value > MAX_INT_VALUE / 2) {
            fprintf(stderr, "Value exceeds the maximum range\n");
            exit(EXIT_FAILURE);
        }
    }

    // Free the memory when it is no longer needed
    free(mem);
}

// Define the function that frees all allocated memory
