    // 最近未使用的项
    struct cache_entry *tail;
};

// 定义缓存条目结构体
struct cache_entry {
    // 关键字
    int key;
    // 值
    char value[MAX_VALUE_LENGTH];
    // 使用计数器
    size_t count;
    // 前驱项
    struct cache_entry *prev;
    // 后继项
    struct cache_entry *next;
};
```

在初始化时，需要传入缓存容量和最大值长度。缓存管理器负责为每个关键字分配一个对应的条目结构体，并将其插入到最近使用的项列表中。在缓存容量超过限制时，需要将最近未使用的项刷新到磁盘上，以便释放内存空间。同时，也要将无效的条目从缓存中删除。

在获取值时，如果找不到对应的关键字，则需要先向后端数据库查询该值，然后将其添加到缓存中，并更新条目结构体的使用计数器。如果缓存已经满了，则需要从最近未使用的项中选出一个进行刷新和删除操作，然后再将新的值添加到缓存中。

在更新值时，需要先查询缓存中是否有对应的条目，如果有则更新其值，并更新使用计数器；如果没有，则需要向后端数据库查询该值，然后将其添加到缓存中。同时，也要将无效的条目从缓存中删除。

在删除值时，需要先从缓存中删除对应的条目，并更新使用计数器；如果该条目是最近未使用的项，则也要将其刷新到磁盘上。

在执行完成时，需要将无效的条目从缓存中删除，并将最近未使用的项刷新到磁盘上，以便释放内存空间。

### 总结

在这个问题里，我们需要设计一个基于 LRU 算法的缓存管理器来实现缓存功能。在初始化时，需要传入缓存容量和最大值长度，并为每个关键字分配一个对应的条目结构体，将其插入到最近使用的项列表中。在缓存容量超过限制时，需要将最近未使用的项刷新到磁盘上，以便释放内存空间。同时，也要将无效的条目从缓存中删除。在获取值时，如果找不到对应的关键字，则需要先向后端数据库查询该值，然后将其添加到缓存中，并更新条目结构体的使用计数器。在更新值时，需要先查询缓存中是否有对应的条目，如果有则更新其值，并更新使用计数器；如果没有，则需要向后端数据库查询该值，然后将其添加到缓存中。同时，也要将无效的条目从缓存中删除。在删除值时，需要先从缓存中删除对应的条目，并更新使用计数器；如果该条目是最近未使用的项，则也要将其刷新到磁盘上。最后，在执行完成时，需要将无效的条目从缓存中删除，并将最近未使用的项刷新到磁盘上，以便释放内存空间。']

