#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

// Structure to represent a data entry
typedef struct {
    long timestamp;
    int priority_level;
    double value;
} data_entry;

// Function to initialize the array of data entries
void init_data_entries(data_entry **data, int capacity, int min_value, int max_value) {
    // Initialize the size of the array
    *data = (data_entry *)malloc(sizeof(data_entry) * capacity);

    // Fill the initial entries with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < capacity; ++i) {
        (*data)[i].timestamp = rand() % INT_MAX;
        (*data)[i].priority_level = rand() % 10;
        (*data)[i].value = min_value + ((double)(max_value - min_value) * (rand() % 100)) / 100.0;
    }
}

// Function to dynamically resize the array when it reaches a specified capacity threshold
void resize_array(data_entry **data, int new_capacity) {
    // Check if the new capacity is greater than the current capacity
    if (new_capacity > (*data)->capacity) {
        // Reallocate memory for the array with the new capacity
        *data = (data_entry *)realloc(*data, sizeof(data_entry) * new_capacity);
        (*data)->capacity = new_capacity;
    }
}

// Function to add a data entry to the array
void add_data_entry(data_entry **data, int capacity, long timestamp, int priority_level, double value) {
