// Function to set a data entry in the array by index
void set_data_entry(data_entry **data, int index, long timestamp, int priority_level, double value) {
    // Check if the index is valid
    if (index >= 0 && index < (*data)->size) {
        (*data)[index].timestamp = timestamp;
        (*data)[index].priority_level = priority_level;
        (*data)[index].value = value;
    }
}

// Function to remove all data entries from the array
void clear(data_entry **data) {
    // Set the size of the array to 0
    (*data)->size = 0;
}
