    return compSize;
}

int decompressData(unsigned char* compressedData, size_t size, unsigned char** data) {
    int status = Z_OK;
    *data = (unsigned char*)malloc(size);
    if (*data == NULL) {
        fprintf(stderr, "Failed to allocate memory for decompressed data\n");
        return Z_MEM_ERROR;
    }
