// Define the serialization functions for the record array
int serializeRecordArray(const void* ptr, size_t count, FILE* fp) {
    int status = Z_OK;
    unsigned char* data = (unsigned char*)malloc(sizeof(Record) * count);
    if (!data) {
        fprintf(stderr, "Failed to allocate memory for serialized data\n");
        return Z_MEM_ERROR;
    }
    memcpy(data, ptr, sizeof(Record) * count);
    size_t compSize = compressData(data, sizeof(Record) * count, &data);
    if (compSize == 0) {
        fprintf(stderr, "Compression failed\n");
        freeMemory(data);
        return Z_MEM_ERROR;
    }
    size_t written = fwrite(data, 1, compSize, fp);
    if (written != compSize) {
        fprintf(stderr, "Failed to write serialized data\n");
        freeMemory(data);
        return Z_ERRNO;
    }
    freeMemory(data);
    return written;
}

int deserializeRecordArray(void* ptr, size_t count, FILE* fp) {
    int status = Z_OK;
    unsigned char* data = (unsigned char*)malloc(sizeof(Record) * count);
    if (!data) {
        fprintf(stderr, "Failed to allocate memory for deserialized data\n");
        return Z_MEM_ERROR;
    }
    size_t read = fread(data, 1, sizeof(Record) * count, fp);
    if (read != sizeof(Record) * count) {
        fprintf(stderr, "Failed to read serialized data\n");
        freeMemory(data);
        return Z_ERRNO;
    }
    size_t decompSize = decompressData(data, read, &data);
    if (decompSize == 0) {
        fprintf(stderr, "Decompression failed\n");
        freeMemory(data);
        return Z_MEM_ERROR;
