// Define data structures for storing sensor data
typedef struct {
    double measurement;
    float range_boundary;
    uint64_t timestamp;
} data_point;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T crc_indication;
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} crc_indication_pdu;

// Define a custom hash table for efficient lookups and insertions
typedef struct {
    uint32_t capacity; // Current size of the table
    uint32_t count;    // Number of elements in the table
    uint32_t mask;     // Mask used to calculate the index of an element
    data_point* keys;  // Array of keys (data points)
    crc_indication_pdu* values; // Array of values (CRC indications)
} hash_table;

// Define a function for initializing the hash table
void init_hash_table(hash_table* ht, uint32_t capacity) {
    ht->capacity = capacity;
    ht->count = 0;
    ht->mask = capacity - 1; // Calculate the mask for efficient modulo operation
    ht->keys = (data_point*) malloc(sizeof(data_point) * capacity);
    ht->values = (crc_indication_pdu*) malloc(sizeof(crc_indication_pdu) * capacity);
}

// Define a function for inserting a key-value pair into the hash table
void insert_hash_table(hash_table* ht, data_point key, crc_indication_pdu value) {
    uint32_t index = calculate_index(ht->mask, key);
    while (ht->keys[index].timestamp != 0) { // Check for collision
        if (equal(key, ht->keys[index])) { // Update the value if there is a match
            ht->values[index] = value;
            return;
        } else { // Otherwise, linearly probe until an empty slot is found
            index = (index + 1) & ht->mask;
        }
    }
    ht->keys[index] = key; // Insert the new key-value pair into the table
    ht->values[index] = value;
    ht->count++;
}

// Define a function for searching for a key in the hash table
crc_indication_pdu* search_hash_table(hash_table* ht, data_point key) {
    uint32_t index = calculate_index(ht->mask, key);
    while (ht->keys[index].timestamp != 0) { // Check for collision
        if (equal(key, ht->keys[index])) { // Found a match
            return &ht->values[index];
        } else { // Otherwise, linearly probe until an empty slot is found
            index = (index + 1) & ht->mask;
        }
    }
    return NULL; // Key not found
}

// Define a function for calculating the hash of a key
uint32_t calculate_hash(data_point key) {
    uint32_t hash = 0;
    hash += (uint32_t)(key.measurement * 1000); // Scale the measurement by 1000 to reduce collisions
    hash += (uint32_t)(key.range_boundary * 100); // Scale the range boundary by 100 to reduce collisions
    hash += (uint32_t)(key.timestamp / 1000); // Divide the timestamp by 1000 to reduce collisions
    return hash;
}

// Define a function for calculating the index of an element in the hash table
uint32_t calculate_index(uint32_t mask, data_point key) {
    uint32_t hash = calculate_hash(key);
    return hash & mask;
}

// Define a function for checking whether two keys are equal
bool equal(data_point k1, data_point k2) {
    return (k1.measurement == k2.measurement && k1.range_boundary == k2.range_boundary && k1.timestamp == k2.timestamp);
}

// Define a function for managing memory and resources under stress conditions
void manage_memory(hash_table* ht) {
    // Check if the hash table has reached its capacity
    if (ht->count * 4 >= ht->capacity) {
        uint32_t new_capacity = ht->capacity * 2; // Double the capacity of the hash table
        data_point* new_keys = (data_point*) realloc(ht->keys, sizeof(data_point) * new_capacity);
        crc_indication_pdu* new_values = (crc_indication_pdu*) realloc(ht->values, sizeof(crc_indication_pdu) * new_capacity);
        if (new_keys == NULL || new_values == NULL) { // Check for allocation failure
            printf("Failed to allocate memory! Capacity remains at %d.\n", ht->capacity);
            return;
        } else { // Reallocate the hash table and reset the mask
            ht->keys = new_keys;
            ht->values = new_values;
            ht->mask = new_capacity - 1;
        }
    }
}

// Define a function for managing the log file
void manage_log(hash_table* ht, FILE* log) {
    fprintf(log, "Log updated with %d key-value pairs.\n", ht->count);
}

int main() {
    hash_table ht; // Initialize an empty hash table
    init_hash_table(&ht);

    FILE* log = fopen("log.txt", "a"); // Open the log file in append mode
    manage_log(&ht, log);

    data_point key = {0, 0, 0}; // Initialize a dummy key for search and insertion
    crc_indication_pdu value; // Initialize a dummy value for search and insertion
    while (true) { // Loop indefinitely to handle incoming data
        read_data(&key, &value); // Read the next incoming data point
        if (search_hash_table(&ht, key) == NULL) { // Check if the key is already in the hash table
            insert_hash_table(&ht, key, value); // Insert the new key-value pair into the hash table
            manage_memory(&ht); // Manage memory and resources under stress conditions
        } else { // Otherwise, update the existing value for the key
            ht.values[calculate_index(ht.mask, key)] = value;
        }
        manage_log(&ht, log); // Update the log file with the new key-value pair
    }
}
