// Define a struct to hold the sensor data reading information
typedef struct {
  uint64_t timestamp;
  float temperature;
  float humidity;
  int eventType;
} SensorReading;

// Define a custom hash table structure for storing sensor readings
struct HashTable {
  // Use a lock-free data structure to minimize contention
  pthread_mutex_t mutex;

  // Use a linked list to store the sensor readings, with each reading containing a timestamp and the other values as pointers to floats
  SensorReading* head;

  // Use a periodic compaction mechanism to manage memory fragmentation
  size_t capacity;
  size_t count;
};

// Define a function for adding a sensor reading to the hash table
void addSensorReading(struct HashTable* table, uint64_t timestamp, float temperature, float humidity, int eventType) {
  // Lock the mutex to ensure thread safety and prevent race conditions
  pthread_mutex_lock(&table->mutex);

  // Check if there is enough space in the hash table for the new reading
  if (table->count >= table->capacity) {
    // If not, resize the hash table to accommodate more readings
    table->capacity *= 2;
    table->head = realloc(table->head, sizeof(SensorReading) * table->capacity);
    if (!table->head) {
      printf("Error: could not allocate memory for hash table\n");
      return;
    }
  }

  // Add the new reading to the end of the linked list
  SensorReading* newReading = malloc(sizeof(SensorReading));
  if (!newReading) {
    printf("Error: could not allocate memory for new sensor reading\n");
    return;
  }
  newReading->timestamp = timestamp;
  newReading->temperature = temperature;
  newReading->humidity = humidity;
  newReading->eventType = eventType;

  table->head = addToLinkedList(table->head, newReading);
  table->count++;

  // Unlock the mutex and return
  pthread_mutex_unlock(&table->mutex);
}

// Define a function for removing a sensor reading from the hash table
void removeSensorReading(struct HashTable* table, uint64_t timestamp) {
  // Lock the mutex to ensure thread safety and prevent race conditions
  pthread_mutex_lock(&table->mutex);

  // Find the node with the matching timestamp in the linked list
  SensorReading* current = table->head;
  while (current != NULL && current->timestamp != timestamp) {
    current = current->next;
  }

  // If the reading was found, remove it from the linked list and free its memory
  if (current != NULL) {
    SensorReading* previous = current->previous;
    SensorReading* next = current->next;
    if (previous == NULL) {
      table->head = next;
    } else {
      previous->next = next;
    }
    free(current);
    table->count--;
  }

  // Unlock the mutex and return
  pthread_mutex_unlock(&table->mutex);
}

// Define a function for accessing a sensor reading from the hash table
SensorReading* getSensorReading(struct HashTable* table, uint64_t timestamp) {
  // Lock the mutex to ensure thread safety and prevent race conditions
  pthread_mutex_lock(&table->mutex);

  // Find the node with the matching timestamp in the linked list
  SensorReading* current = table->head;
  while (current != NULL && current->timestamp != timestamp) {
    current = current->next;
  }

  // If the reading was found, return a copy of it
  if (current != NULL) {
    SensorReading* reading = malloc(sizeof(SensorReading));
    memcpy(reading, current, sizeof(SensorReading));
    pthread_mutex_unlock(&table->mutex);
    return reading;
  }

  // If the reading was not found, return NULL
  pthread_mutex_unlock(&table->mutex);
  return NULL;
}

// Define a function for iterating over all sensor readings in the hash table
void iterateSensorReadings(struct HashTable* table, void (*callback)(const SensorReading*)) {
  // Lock the mutex to ensure thread safety and prevent race conditions
  pthread_mutex_lock(&table->mutex);

  // Iterate over all sensor readings in the linked list and call the callback function for each one
  SensorReading* current = table->head;
  while (current != NULL) {
    callback(current);
