        MACHeader* header = &stat->header;
        IPAddressPacket* packet = &stat->packet;

        // Generate a random payload size within the specified range
        int payloadSizeBytes = minPayloadSizeBytes + (rand() % (maxPayloadSizeBytes - minPayloadSizeBytes));
        // Allocate memory for the payload
        char* payload = (char*)malloc(payloadSizeBytes);
        if (!payload) {
            free(stats);
            return ENOMEM;
        }
        // Initialize the payload with random data
