            payload[j] = rand() % 256;
        }

        // Calculate the checksum for the IP packet
        int checksum = calculateChecksum(payload, payloadSizeBytes);
        if (!checksum) {
            free(stats);
            return ENOMEM;
        }

        // Update the IP packet with the calculated checksum
        packet->checksum = checksum;

        // Increment the total number of entries
        (*totalEntries)++;
    }

    // Clean up memory
