// Structure to represent a LTE UE context
typedef struct {
    int UE_ID; // Unique ID for the UE
    bool RRC_connected; // Status of the RRC connection
    List *PDCP_PDUs; // List of PDCP PDU buffers
} LTE_UE_Context;

// Structure to represent a PDCP PDU buffer
typedef struct {
    char *data; // Buffer for the PDCP PDU data
    size_t length; // Length of the PDCP PDU data
} PDCP_PDU_Buffer;

// List implementation to store the PDCP PDU buffers
typedef struct {
    size_t count; // Number of elements in the list
    PDCP_PDU_Buffer *elements; // Array of PDCP PDU buffers
} LTE_UE_Context_List;

// Function to initialize a new LTE UE context structure
LTE_UE_Context *init_lte_ue_context(int UE_ID, bool RRC_connected) {
    // Allocate memory for the LTE UE context structure
    LTE_UE_Context *context = malloc(sizeof(LTE_UE_Context));
    if (context == NULL) {
        fprintf(stderr, "Failed to allocate memory for LTE UE context\n");
        return NULL;
    }

    // Initialize the LTE UE context structure
    context->UE_ID = UE_ID;
    context->RRC_connected = RRC_connected;
    context->PDCP_PDUs = init_lte_ue_context_list();

    return context;
}

// Function to initialize a new list of PDCP PDU buffers for an LTE UE context
LTE_UE_Context_List *init_lte_ue_context_list() {
    // Allocate memory for the list structure
    LTE_UE_Context_List *list = malloc(sizeof(LTE_UE_Context_List));
    if (list == NULL) {
        fprintf(stderr, "Failed to allocate memory for PDCP PDU buffer list\n");
        return NULL;
    }

    // Initialize the list structure
    list->count = 0;
    list->elements = NULL;

    return list;
}

// Function to add a new PDCP PDU buffer to an LTE UE context
void add_pdcp_pdu(LTE_UE_Context *context, char *data, size_t length) {
    // Allocate memory for the new PDCP PDU buffer
    PDCP_PDU_Buffer *buffer = malloc(sizeof(PDCP_PDU_Buffer));
    if (buffer == NULL) {
        fprintf(stderr, "Failed to allocate memory for PDCP PDU buffer\n");
        return;
    }

    // Initialize the new PDCP PDU buffer
    buffer->data = data;
    buffer->length = length;

    // Add the new PDCP PDU buffer to the list of buffers for the LTE UE context
    if (context->PDCP_PDUs == NULL) {
        context->PDCP_PDUs = init_lte_ue_context_list();
    }
    context->PDCP_PDUs->elements = realloc(context->PDCP_PDUs->elements, (context->PDCP_PDUs->count + 1) * sizeof(PDCP_PDU_Buffer));
    context->PDCP_PDUs->elements[context->PDCP_PDUs->count++] = buffer;
}

// Function to remove a PDCP PDU buffer from an LTE UE context
void remove_pdcp_pdu(LTE_UE_Context *context, char *data) {
    // Find the index of the PDCP PDU buffer in the list
    size_t i;
    for (i = 0; i < context->PDCP_PDUs->count; i++) {
        if (strcmp(context->PDCP_PDUs->elements[i]->data, data) == 0) {
            break;
        }
    }

    // If the buffer was found, remove it from the list and free its memory
    if (i < context->PDCP_PDUs->count) {
        PDCP_PDU_Buffer *buffer = context->PDCP_PDUs->elements[i];
        context->PDCP_PDUs->count--;
        context->PDCP_PDUs->elements[i] = context->PDCP_PDUs->elements[context->PDCP_PDUs->count];
        free(buffer);
    }
}

// Function to update the RRC connection status of an LTE UE context
void update_rrc_status(LTE_UE_Context *context, bool connected) {
    context->RRC_connected = connected;
}

// Thread-safe function to add a new PDCP PDU buffer for an LTE UE context
void thread_add_pdcp_pdu(LTE_UE_Context *context, char *data, size_t length) {
    pthread_mutex_lock(&context->mutex);
    add_pdcp_pdu(context, data, length);
    pthread_mutex_unlock(&context->mutex);
}

// Thread-safe function to remove a PDCP PDU buffer for an LTE UE context
void thread_remove_pdcp_pdu(LTE_UE_Context *context, char *data) {
    pthread_mutex_lock(&context->mutex);
    remove_pdcp_pdu(context, data);
    pthread_mutex_unlock(&context->mutex);
}

// Thread-safe function to update the RRC connection status of an LTE UE context
void thread_update_rrc_status(LTE_UE_Context *context, bool connected) {
    pthread_mutex_lock(&context->mutex);
    update_rrc_status(context, connected);
    pthread_mutex_unlock(&context->mutex);
}
