#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <assert.h>
#include <stdint.h>
#include "NFAPI_CRC_INDICATION_PDU.h"
#include "RX_UE_INFORMATION_TAG.h"
#include "RNTI.h"
#include "CRC_INDICATION_REL8_TAG.h"
#include "crc.h"

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
};

struct DynamicArray {
    struct NFAPI_CRC_INDICATION_PDU_T **data;
    size_t count;
    size_t capacity;
};

bool isPowerOfTwo(size_t x) {
    return (x != 0) && !(x & (x - 1));
}

void resizeDynamicArray(struct DynamicArray *array, size_t newCapacity) {
    assert(newCapacity > array->count);
    struct NFAPI_CRC_INDICATION_PDU_T **newData = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T *) * newCapacity);
    memcpy(newData, array->data, sizeof(struct NFAPI_CRC_INDICATION_PDU_T *) * array->count);
    free(array->data);
    array->data = newData;
    array->capacity = newCapacity;
}

struct DynamicArray* initializeDynamicArray(size_t initialCapacity, size_t alignment) {
    if (initialCapacity == 0) {
        initialCapacity = 1;
    }
    if (!isPowerOfTwo(alignment)) {
        alignment = 64;
    }
    struct DynamicArray *array = malloc(sizeof(struct DynamicArray));
    array->data = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T *) * initialCapacity);
    memset(array->data, 0, sizeof(struct NFAPI_CRC_INDICATION_PDU_T *) * initialCapacity);
    array->count = 0;
    array->capacity = initialCapacity;
    return array;
}

void freeDynamicArray(struct DynamicArray *array) {
    if (array != NULL) {
        for (size_t i = 0; i < array->count; i++) {
            free(array->data[i]);
        }
        free(array->data);
        free(array);
    }
}

void addElementToDynamicArray(struct DynamicArray *array, struct NFAPI_CRC_INDICATION_PDU_T *element) {
    assert(array != NULL);
    if (array->count == array->capacity) {
        resizeDynamicArray(array, array->capacity << 1);
    }
    memcpy(&array->data[array->count], element, sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
    array->count++;
}

void removeElementFromDynamicArray(struct DynamicArray *array, size_t index) {
    assert(index < array->count);
    memcpy(&array->data[index], &array->data[array->count - 1], sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
    array->count--;
}

struct DynamicArray* manageDynamicArray(size_t initialCapacity, size_t alignment) {
    struct DynamicArray *array = initializeDynamicArray(initialCapacity, alignment);
    return array;
}

void populateDynamicArray(struct DynamicArray *array, int64_t N) {
    assert(N >= 0);
    for (int64_t i = 0; i < N; i++) {
        struct NFAPI_CRC_INDICATION_PDU_T *element = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
        element->rx_ue_information.rnti = rand();
        element->rnti.crcFlag = rand() % 2;
        addElementToDynamicArray(array, element);
    }
}

void processInputArray(int32_t *inputArray, size_t N) {
    struct DynamicArray *array = manageDynamicArray(N, 64);
    populateDynamicArray(array, N);
    for (size_t i = 0; i < array->count; i++) {
        crc8(&array->data[i]->rx_ue_information.rnti, sizeof(RNTI), &array->data[i]->crc_indication_rel8.crc);
    }
    freeDynamicArray(array);
}
```
