// Macros for debugging and logging
#define DEBUG(x) printf("DEBUG: %s\n", x)
#define LOG(fmt, ...) printf("LOG: " fmt "\n", __VA_ARGS__);

// Types
typedef struct {
    int type;
    void *data;
    uint64_t metadata;
} transaction_t;

typedef struct rb_node {
    transaction_t *transaction;
    struct rb_node *left, *right, *parent;
    bool red;
} rb_node_t;

// Function declarations
void insert(rb_node_t **root, transaction_t *new_transaction);
void delete(rb_node_t **root, uint64_t id);
void modify(rb_node_t **root, transaction_t *new_transaction);
rb_node_t *search(rb_node_t *root, uint64_t id);
int gen_random_metadata(int min, int max);
bool is_valid_transaction(transaction_t *tx);
void buffer_update(transaction_t *tx);
void apply_buffered_updates();
void init_external_data_source();
void update_external_data_source(transaction_t *tx);
void process_incoming_transaction(transaction_t *tx);

// Global variables
rb_node_t *root = NULL;
int buffered_updates = 0;
bool external_data_source_initialized = false;
bool thread_safety = false;

void insert(rb_node_t **root, transaction_t *new_transaction) {
    if (!is_valid_transaction(new_transaction)) {
        DEBUG("Invalid transaction");
        return;
    }

    // Generate random metadata for new transaction
    new_transaction->metadata = gen_random_metadata(1, 10);

    rb_node_t *parent = NULL, *grandparent = NULL;
    rb_node_t **parent_ptr = root;
    bool left_child = false;

    while (*parent_ptr) {
        parent = *parent_ptr;
        grandparent = parent->parent;
        int cmp = new_transaction->id - parent->transaction->id;

        if (cmp == 0) {
            DEBUG("Duplicate transaction ID");
            return;
        } else if (cmp < 0) {
            left_child = true;
            parent_ptr = &parent->left;
        } else {
            left_child = false;
            parent_ptr = &parent->right;
        }
    }

    rb_node_t *new_node = malloc(sizeof(rb_node_t));
    new_node->transaction = new_transaction;
    new_node->red = true;
    new_node->left = NULL;
    new_node->right = NULL;
    new_node->parent = grandparent;

    if (grandparent && grandparent->red) {
        // Case 1: Grandparent is red, parent and sibling are black
        rb_node_t *uncle = left_child ? grandparent->right : grandparent->left;

        if (uncle && uncle->red) {
            // Case 2: Uncle is red, recolor and rotate
            grandparent->red = false;
            parent->red = true;
            uncle->red = false;
            rb_node_t *gp_parent = grandparent->parent;
            rb_node_t **gp_ptr = gp_parent ? &gp_parent->left : root;

            if (grandparent == (*gp_ptr)->right) {
                left_child = true;
                parent_ptr = &(*gp_ptr)->right;
            } else {
                left_child = false;
                parent_ptr = &(*gp_ptr)->left;
            }
        } else {
            // Case 3: Uncle is black, recolor and rotate twice
            grandparent->red = true;
            parent->red = false;
            uncle->red = true;

            if (left_child) {
                rb_node_t *tmp = new_node;
                new_node = grandparent;
                grandparent = tmp;
            }

            left_child = !left_child;
            parent_ptr = &grandparent->parent->left;
        }
    }

    *parent_ptr = new_node;
}

void delete(rb_node_t **root, uint64_t id) {
    if (!*root) return;

    rb_node_t *current = *root;
    while (true) {
        int cmp = current->transaction->id - id;
        if (cmp == 0) break;
        else if (cmp < 0) current = current->left;
        else current = current->right;
    }

    rb_node_t *child, *sibling;
    bool left_child = false;

    if (!current->left || !current->right) {
        // Case 1: No children
        child = current;
        sibling = NULL;
    } else {
        // Case 2: One child
        child = current->left ? current->left : current->right;
        sibling = current->left ? current->right : current->left;
    }

    if (child && child->red) {
        // Case 3: Only red child
        child->red = false;
    } else {
        // Case 4: Two black children
        if (sibling) sibling->red = true;
        rb_node_t *parent = current->parent;
        bool parent_red = parent && parent->red;
        if (!parent) break;

        left_child = current == parent->left;
        rb_node_t **parent_ptr = &parent->left;
        if (current != *parent_ptr) {
            parent_ptr = &parent->right;
            left_child = !left_child;
        }

        // Case 5: Sibling is red, recolor and rotate
        sibling->red = false;
        child->red = true;
        rb_node_t *tmp = parent;
        parent = current;
        current = tmp;
    }

    if (parent && parent->red) {
        // Case 6: Parent is red, recolor and rotate
        parent->red = false;
        left_child = !left_child;
        rb_node_t **ptr = &parent->parent->left;
        if (parent == *ptr) {
            ptr = &parent->parent->right;
            left_child = !left_child;
        }
        current->red = true;
    }
}

void rb_tree_insert(rb_node_t **root, uint64_t id) {
    rb_node_t *new_node = malloc(sizeof(rb_node_t));
    new_node->id = id;
    new_node->red = true;
    new_node->left = NULL;
    new_node->right = NULL;
    new_node->parent = NULL;

    rb_tree_insert_helper(root, new_node);
}

void rb_tree_insert_helper(rb_node_t **root, rb_node_t *new_node) {
    if (!*root) {
        *root = new_node;
        return;
    }

    while (true) {
        int cmp = (*root)->id - new_node->id;
        if (cmp == 0) break;
        else if (cmp < 0) {
            if ((*root)->left == NULL) {
                (*root)->left = new_node;
                break;
            }
            *root = (*root)->left;
        } else {
            if ((*root)->right == NULL) {
                (*root)->right = new_node;
                break;
            }
            *root = (*root)->right;
        }
    }

    rb_tree_insert_fixup(root, new_node);
}

void rb_tree_delete(rb_node_t **root, uint64_t id) {
    if (!*root) return;

    while ((*root)->left || (*root)->right) {
        int cmp = (*root)->id - id;
        if (cmp == 0) break;
        else if (cmp < 0) *root = (*root)->left;
        else *root = (*root)->right;
    }

    rb_tree_delete_fixup(root);
}

void rb_tree_delete_fixup(rb_node_t **root) {
    if (!*root) return;

    rb_node_t *current = *root, *child, *sibling;
    while (true) {
        if (!current->left || !current->right) break;
        current->red = true;
        current = current->parent;
    }
}
