        array[i].ip_packet.checksum = calculate_checksum(&array[i].ip_packet);
    }
}

// Function to validate the IP packet checksums in the dynamic array
void validate_ip_checksum(struct nic_stats *array, size_t size) {
    for (int i = 0; i < size; i++) {
        if (!validate_ip_checksum(&array[i].ip_packet)) {
            printf("Invalid IP checksum at index %d\n", i);
        }
    }
}

// Function to calculate the IP packet checksum
uint16_t calculate_checksum(struct ip_packet *ip_packet) {
    // Calculate the checksum of the IP header and payload
    uint16_t checksum = 0;
    for (int i = 0; i < sizeof(struct ip_header); i++) {
        checksum += ((uint8_t *)ip_packet)[i];
    }
    return checksum;
}

// Function to validate the IP packet checksum
bool validate_ip_checksum(struct ip_packet *ip_packet) {
    // Calculate the expected checksum of the IP header and payload
    uint16_t expected_checksum = calculate_checksum(ip_packet);
    // Check if the calculated checksum matches the expected checksum
    return (expected_checksum == ip_packet->checksum);
}
