// Function to perform a binary search for an element in an array of NIC statistics
int binarySearch(struct nic_stats *array, int low, int high, struct nic_stats target) {
    // If the range is empty or the target is not found in the range, return -1
    if (low > high || !binarySearch(target, array, size)) {
        return -1;
    }

    // Calculate the midpoint of the range
    int mid = low + (high - low) / 2;

    // If the target is found at the midpoint, return its index
    if (target == array[mid]) {
        return mid;
    }

    // If the target is less than the element at the midpoint, search the left subarray
    else if (target < array[mid]) {
        return binarySearch(target, array, low, mid - 1);
    }

    // If the target is greater than the element at the midpoint, search the right subarray
    else {
        return binarySearch(target, array, mid + 1, high);
    }
}
