int* createRecords(int N, int M, int min_value, int max_value, int custom_seed) {
    // Check if N and M are valid
    if (N <= 0 || M < 0 || M > N / 2) {
        return NULL;
    }

    // Allocate memory for the offsets and keys arrays
    long* offsets = malloc(N * sizeof(long));
    int* keys = malloc(M * sizeof(int));
    if (offsets == NULL || keys == NULL) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize the keys array with unique values between 1 and 100, inclusive
    init_keys(keys, M);

    // Allocate memory for the records array
    struct record* records = malloc(N * sizeof(struct record));
    if (records == NULL) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Set the value of each record's value field to a random integer within the specified range
    srand(custom_seed > 0 ? custom_seed : (unsigned int)time(NULL));
    for (int i = 0; i < N; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    // Ensure that no two records have the same key value
    int* hashTable = malloc(N * sizeof(int));
    if (hashTable == NULL) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }
    for (int i = 0; i < N; ++i) {
        int key = records[i].key;
        while (hashTable[key] != 0) {
            key++;
        }
        hashTable[key] = 1;
        offsets[i] = key;
    }

    // Free all allocated memory at the end of the function
    free(offsets);
    free(keys);
    free(records);
    return (int*) records;
}

// Initializes the keys array with unique values between 1 and 100, inclusive
void init_keys(int* keys, int M) {
    // Initialize all elements of the keys array to 0
    for (int i = 0; i < M; ++i) {
        keys[i] = 0;
    }

    // Set the first element of the keys array to a random value between 1 and 100, inclusive
    int randKey = rand() % 100 + 1;
    keys[0] = randKey;

    // Iterate through the remaining elements of the keys array and set each element to a unique value
    for (int i = 1; i < M; ++i) {
        while (keys[i] == 0 || keys[i] == randKey) {
            keys[i] = rand() % 100 + 1;
        }
    }
}
