void init_LTE_ENB_RRC_MESSAGE_LIST(LTE_ENB_RRC_MESSAGE_LIST_T *list) {
    list->messages = NULL;
    list->capacity = 0;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_LTE_ENB_RRC_MESSAGE_LIST(LTE_ENB_RRC_MESSAGE_LIST_T *list) {
    free(list->messages);
    pthread_mutex_destroy(&list->lock);
}

int add_LTE_ENB_RRC_MESSAGE(LTE_ENB_RRC_MESSAGE_LIST_T *list, LTE_ENB_RRC_MESSAGE_T *message) {
    pthread_mutex_lock(&list->lock);
    if (list->count == list->capacity) {
        // Resize the list if necessary
        list->capacity = list->capacity > 0 ? 2 * list->capacity : 1;
        LTE_ENB_RRC_MESSAGE_T *new_messages = realloc(list->messages, sizeof(LTE_ENB_RRC_MESSAGE_T) * list->capacity);
        if (new_messages == NULL) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->messages = new_messages;
    }
    list->messages[list->count++] = *message;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_LTE_ENB_RRC_MESSAGE(LTE_ENB_RRC_MESSAGE_LIST_T *list, size_t index) {
    pthread_mutex_lock(&list->lock);
    if (index >= list->count) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    LTE_ENB_RRC_MESSAGE_T *message = &list->messages[index];
    memmove(&list->messages[index], &list->messages[index + 1], sizeof(LTE_ENB_RRC_MESSAGE_T) * (list->count - index));
    list->count--;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

