    pthread_mutex_lock(&lock);

    // Fork a new process to execute the command
    pid_t pid = fork();
    if (pid < 0) {
        fprintf(stderr, "Failed to fork a new process: %s\n", strerror(errno));
        pthread_mutex_unlock(&lock);
        return;
    } else if (pid == 0) {
