    command_status->start_time = timespec();
    clock_gettime(CLOCK_MONOTONIC, &command_status->start_time);
    command_statuses[command_status] = (struct command_status *)malloc(sizeof(struct command_status));
    if (!command_statuses) {
        fprintf(stderr, "Failed to allocate memory for command status\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    // Wait until the specified timeout before killing the process
    sleep(TIMEOUT);
    if (kill(pid, SIGKILL) < 0) {
        fprintf(stderr, "Failed to kill process %d: %s\n", pid, strerror(errno));
    } else {
        printf("Process killed successfully\n");
    }

    pthread_mutex_unlock(&lock);
}

// Function to wait for a specified number of seconds before killing a process
void wait_seconds(int seconds) {
    // Check for valid input
    if (seconds < 0) {
        fprintf(stderr, "Invalid number of seconds specified\n");
        return;
    }

    pthread_mutex_lock(&lock);

    // Fork a new process to wait for the specified number of seconds before killing the process
    pid_t pid = fork();
    if (pid < 0) {
        fprintf(stderr, "Failed to fork a new process: %s\n", strerror(errno));
        pthread_mutex_unlock(&lock);
        return;
    } else if (pid == 0) {
        // Child process: wait for the specified number of seconds and exit
        sleep(seconds);
        printf("Waited for %d seconds\n", seconds);
        exit(0);
    }

    // Parent process: store the PID and command status
    struct command_status *command_status = (struct command_status *)malloc(sizeof(struct command_status));
    if (!command_status) {
        fprintf(stderr, "Failed to allocate memory for command status\n");
        pthread_mutex_unlock(&lock);
        return;
    }
    command_status->pid = pid;
    command_status->start_time = timespec();
    clock_gettime(CLOCK_MONOTONIC, &command_status->start_time);
    command_statuses[command_status] = (struct command_status *)malloc(sizeof(struct command_status));
    if (!command_statuses) {
        fprintf(stderr, "Failed to allocate memory for command status\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    // Wait until the specified timeout before killing the process
    sleep(TIMEOUT);
    if (kill(pid, SIGKILL) < 0) {
        fprintf(stderr, "Failed to kill process %d: %s\n", pid, strerror(errno));
    } else {
        printf("Process killed successfully\n");
    }

    pthread_mutex_unlock(&lock);
}

int main() {
    init();
    execute_command("ls -l");
    wait_seconds(30);
    return 0;
}
