#define MUTEX_DESTROY { pthread_mutex_destroy(&mutex); }
#define MUTEX_LOCK { pthread_mutex_lock(&mutex); }
#define MUTEX_UNLOCK { pthread_mutex_unlock(&mutex); }

struct tcp_connection {
    int connection_id;
    char remote_ip[INET_ADDRSTRLEN];
    char local_ip[INET_ADDRSTRLEN];
    int status;
};

typedef struct tcp_connection* conn_ptr;

struct tcp_connection_array {
    size_t capacity;
    size_t count;
    conn_ptr* connections;
};

struct tcp_connection_array* create_tcp_connection_array(size_t initial_capacity) {
    struct tcp_connection_array* array = malloc(sizeof(struct tcp_connection_array));
    if (array == NULL) {
        return NULL;
    }

    array->connections = calloc(initial_capacity, CONN_STRUCT_SIZE);
    if (array->connections == NULL) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->count = 0;

    MUTEX_INIT(&mutex);

    return array;
}

int expand_tcp_connection_array(struct tcp_connection_array* array) {
    size_t new_size = array->capacity * 2;
    conn_ptr* new_connections = realloc(array->connections, new_size * CONN_STRUCT_SIZE);
    if (new_connections == NULL) {
        return -1;
    }

    array->connections = new_connections;
    array->capacity = new_size;

    return 0;
}

int add_tcp_connection(struct tcp_connection_array* array, int connection_id, char* remote_ip, char* local_ip) {
    MUTEX_LOCK();

    if (array->count == array->capacity) {
        expand_tcp_connection_array(array);
        if (array->count == array->capacity) {
            MUTEX_UNLOCK();
            return -1;
        }
    }

    conn_ptr connection = &array->connections[array->count++];
    connection->connection_id = connection_id;
    strcpy(connection->remote_ip, remote_ip);
    strcpy(connection->local_ip, local_ip);
    connection->status = ESTABLISHED;

    MUTEX_UNLOCK();

    return 0;
}

int get_tcp_connection_by_id(struct tcp_connection_array* array, int connection_id) {
    for (size_t i = 0; i < array->count; i++) {
        conn_ptr connection = &array->connections[i];
        if (connection->connection_id == connection_id) {
            return connection;
        }
    }

    return NULL;
}

void destroy_tcp_connection_array(struct tcp_connection_array* array) {
    free(array->connections);
    MUTEX_DESTROY(&mutex);
    free(array);
}
