typedef struct {
    uint16_t rx_ue_information_tag;
    uint32_t rnti;
    uint8_t crc_indication_rel8_tag;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t directory_creation_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t environment_variable_lock = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* generate_crc_indication_pdu(uint16_t rx_ue_information_tag, uint32_t rnti, uint8_t crc_indication_rel8_tag) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        perror("Failed to allocate memory for CRC indication PDU");
        return NULL;
    }

    pdu->rx_ue_information_tag = rx_ue_information_tag;
    pdu->rnti = rnti;
    pdu->crc_indication_rel8_tag = crc_indication_rel8_tag;
    pdu->crcflag = rand() % 2 ? 1 : 0;

    return pdu;
}

int create_directory(const char *path) {
    int ret = -1;
    pthread_mutex_lock(&directory_creation_lock);

    if (access(path, F_OK)) {
        // Check if the directory already exists before creating it
        ret = mkdir(path, S_IRWXU | S_IRWXG | S_IROTH | S_IXOTH);
        if (ret == -1 && errno != EEXIST) {
            perror("Failed to create directory");
            pthread_mutex_unlock(&directory_creation_lock);
            return ret;
        }
    }

    // Update the environment variable with the new directory name
    char env_var[MAX_DIRECTORY_NAME_LENGTH];
    snprintf(env_var, MAX_DIRECTORY_NAME_LENGTH, "LAST_USED_DIR=%s", path);
    pthread_mutex_lock(&environment_variable_lock);
    ret = putenv(env_var);
    pthread_mutex_unlock(&environment_variable_lock);
    if (ret == -1) {
        perror("Failed to update environment variable");
        pthread_mutex_unlock(&directory_creation_lock);
        return ret;
    }

    pthread_mutex_unlock(&directory_creation_lock);
    return 0;
}

int populate_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Generate a random RX UE information tag, RNTI and CRCFLAG
    pdu->rx_ue_information_tag = rand() % 0xFFFF;
    pdu->rnti = rand() % 0xFFFFFFFF;
    pdu->crcflag = rand() % 2 ? 1 : 0;

    return 0;
}

int generate_and_populate_crc_indication_pdu(uint16_t rx_ue_information_tag, uint32_t rnti, uint8_t crc_indication_rel8_tag) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = generate_crc_indication_pdu(rx_ue_information_tag, rnti, crc_indication_rel8_tag);
    if (!pdu) {
        return -1;
    }

    populate_crc_indication_pdu(pdu);
    return 0;
}

int main() {
    // Create a new directory with a randomly generated name
    char dir_name[MAX_DIRECTORY_NAME_LENGTH];
    snprintf(dir_name, MAX_DIRECTORY_NAME_LENGTH, "directory%d", rand() % 100);
    int ret = create_directory(dir_name);
    if (ret == -1) {
        perror("Failed to create directory");
        return ret;
    }

    // Populate the CRC indication PDUs
    NFAPI_CRC_INDICATION_PDU_T *pdu = NULL;
    for (int i = 0; i < MAX_CRC_INDICATION_PDU_COUNT; i++) {
        pdu = generate_and_populate_crc_indication_pdu(i, rand() % 0xFFFFFFFF, rand() % 0xFF);
        if (!pdu) {
            return -1;
        }
    }

    // Free the allocated memory
    free(pdu);

    return 0;
}']

