    IP_PACKET ipPacket;
} nicStatistics;

// Function to dynamically allocate memory for a new NIC structure
nicStatistics* createNicStats() {
    // Allocate memory for the NIC statistics structure
    nicStatistics* stats = (nicStatistics*)malloc(sizeof(nicStatistics));
    if (!stats) {
        return NULL;
    }

    // Initialize the MAC and IP header fields in the structure
    memset(&stats->macHeader, 0, sizeof(MAC_HEADER));
    memset(&stats->ipPacket, 0, sizeof(IP_PACKET));

    // Generate a random payload size and checksum for the IP packet
    stats->ipPacket.payloadSize = rand() % 1024;
    stats->ipPacket.checksum = generateChecksum(&stats->macHeader, &stats->ipPacket);

    return stats;
}

// Function to deallocate memory for a NIC structure
void destroyNicStats(nicStatistics* stats) {
    free(stats);
}

// Function to validate the integrity of the IP packet checksums
bool validateChecksum(MAC_HEADER* macHeader, IP_PACKET* ipPacket) {
    // Generate a new checksum for the IP packet
    uint32_t newChecksum = generateChecksum(macHeader, ipPacket);

    // Compare the generated checksum with the stored checksum in the NIC structure
    if (newChecksum == ipPacket->checksum) {
        return true;
    } else {
        return false;
    }
}

// Function to detect and log warnings for duplicate MAC headers within consecutive NIC structures
bool detectDuplicateMacHeaders(nicStatistics* stats1, nicStatistics* stats2) {
    // Compare the MAC addresses in the two NIC structures
    if (memcmp(&stats1->macHeader.destAddr, &stats2->macHeader.destAddr, sizeof(MAC_ADDRESS)) == 0) {
        // Log a warning for duplicate MAC headers
        printf("Warning: Duplicate MAC header detected between NIC structures %d and %d\n", stats1 - statsArray, stats2 - statsArray);
        return true;
    } else {
        return false;
    }
}

// Function to dynamically manage a collection of NIC statistics structures based on user-specified thresholds
void manageNicStats(nicStatistics** statsArray, int* currentSize, int* maxSize) {
    // Calculate the number of elements in the array
    int numElements = *currentSize;

    // Determine if a resize is needed based on user-specified thresholds
    if (numElements >= (*maxSize * 0.75)) {
        // Resize the array to accommodate more NIC structures
        *statsArray = (nicStatistics**)realloc(*statsArray, (*maxSize + 1) * sizeof(nicStatistics*));
        if (!*statsArray) {
            printf("Error: Could not resize NIC statistics array\n");
            return;
        }

        // Update the maximum size of the array
        *maxSize += 1;
    }
}

// Function to efficiently handle memory allocation and deallocation for a collection of NIC statistics structures
void allocateNicStats(nicStatistics** statsArray, int* currentSize, int* maxSize) {
    // Determine if the array needs to be resized based on user-specified thresholds
    manageNicStats(statsArray, currentSize, maxSize);

    // Allocate memory for a new NIC statistics structure
    nicStatistics* stats = createNicStats();
    if (!stats) {
        printf("Error: Could not allocate memory for new NIC statistics structure\n");
        return;
    }

    // Add the new NIC statistics structure to the array
    (*statsArray)[(*currentSize)] = stats;

    // Increment the current size of the array
    *currentSize += 1;
}

void deallocateNicStats(nicStatistics** statsArray, int* currentSize, int* maxSize) {
    // Determine if any NIC statistics structures can be freed based on user-specified thresholds
    manageNicStats(statsArray, currentSize, maxSize);

    // Free the memory for a NIC statistics structure
    destroyNicStats((*statsArray)[(*currentSize - 1)]);

    // Decrement the current size of the array
    *currentSize -= 1;
}
