import java.util.ArrayList;
import java.util.List;

public class NetworkInterfaceMonitor {
    private final List<NicStatistics> nicStats = new ArrayList<>();
    private int currentSize = 0;
    private int maxSize = 1024;

    public void allocateNicStats() {
        // Allocate memory for a new NIC statistics structure
        NicStatistics stats = new NicStatistics();

        // Add the new NIC statistics structure to the array
        nicStats.add(stats);

        // Increment the current size of the array
        currentSize++;
    }

    public void deallocateNicStats() {
        // Determine if any NIC statistics structures can be freed based on user-specified thresholds
        manageNicStats(nicStats, currentSize, maxSize);

        // Free the memory for a NIC statistics structure
        nicStats.remove(currentSize - 1);

        // Decrement the current size of the array
        currentSize--;
    }

    public void validateChecksum(NicStatistics stats) {
        // Generate a new checksum for the IP packet
        uint32_t newChecksum = generateChecksum(&stats.macHeader, &stats.ipPacket);

        // Compare the generated checksum with the stored checksum in the NIC structure
        if (newChecksum == stats.ipPacket.checksum) {
            return true;
        } else {
            return false;
        }
    }

    public void detectDuplicateMacHeaders(NicStatistics stats1, NicStatistics stats2) {
        // Compare the MAC addresses in the two NIC structures
        if (memcmp(&stats1.macHeader.destAddr, &stats2.macHeader.destAddr, sizeof(MAC_ADDRESS)) == 0) {
            // Log a warning for duplicate MAC headers
            System.out.println("Warning: Duplicate MAC header detected");
        }
    }

    public void manageNicStats() {
        // Calculate the number of elements in the array
        int numElements = currentSize;

        // Determine if a resize is needed based on user-specified thresholds
        if (numElements >= (maxSize * 0.75)) {
            // Resize the array to accommodate more NIC statistics structures
            NicStatistics[] newArray = new NicStatistics[maxSize + 1];
            System.arraycopy(nicStats.toArray(), 0, newArray, 0, maxSize);
            nicStats = Arrays.asList(newArray);

            // Update the maximum size of the array
            maxSize++;
        }
    }
}
