use std::sync::{Mutex, MutexGuard};
use std::sync::atomic::AtomicUsize;
use std::path::PathBuf;
use std::env::set_var;
use std::fs::create_dir;
use std::collections::HashMap;
use crate::http::Request;
use crate::http::Response;
use crate::http::StatusCode;
use crate::http::header::{self, HeaderMap};

pub fn user_profile_system(user_id: u64) -> Result<Option<UserProfile>, String> {
    let mut user_profiles = USER_PROFILES.lock().unwrap();
    match user_profiles.get(&user_id) {
        Some(profile) => Ok(Some(profile.clone())),
        None => Err(format!("No profile found for user ID {}", user_id))
    }
}

pub fn create_user_profile(user_id: u64, email: String, username: String, profile_picture_url: String) -> Result<(), String> {
    let mut user_profiles = USER_PROFILES.lock().unwrap();
    match user_profiles.get(&user_id) {
        Some(profile) => Err(format!("User ID {} already exists", user_id)),
        None => {
            let profile = UserProfile { email, username, profile_picture_url };
            user_profiles.insert(user_id, profile);
            Ok(())
        }
    }
}

pub fn update_user_profile(user_id: u64, email: Option<String>, username: Option<String>, profile_picture_url: Option<String>) -> Result<(), String> {
    let mut user_profiles = USER_PROFILES.lock().unwrap();
    match user_profiles.get(&user_id) {
        Some(profile) => {
            if let Some(email) = email {
                profile.email = email;
            }
            if let Some(username) = username {
                profile.username = username;
            }
            if let Some(profile_picture_url) = profile_picture_url {
                profile.profile_picture_url = profile_picture_url;
            }
            Ok(())
        },
        None => Err(format!("No profile found for user ID {}", user_id))
    }
}

pub fn delete_user_profile(user_id: u64) -> Result<(), String> {
    let mut user_profiles = USER_PROFILES.lock().unwrap();
    match user_profiles.remove(&user_id) {
        Some(_) => Ok(()),
        None => Err(format!("No profile found for user ID {}", user_id))
    }
}

pub fn fetch_profile(request: &Request) -> Result<Response, String> {
    let user_id = request.query_param("user_id")?;
    let profile = user_profile_system(user_id)?;
    match profile {
        Some(profile) => {
            let mut response = Response::new();
            response.set_status(StatusCode::OK);
            response.set_body(serde_json::to_string(&profile).unwrap());
            Ok(response)
        },
        None => Err(format!("No profile found for user ID {}", user_id))
    }
}

pub fn create_profile_directory() -> Result<(), String> {
    let directory = "user-profiles";
    if !PathBuf::from(directory).exists() {
        create_dir(directory)?;
    }
    set_var("USER_PROFILE_DIRECTORY", directory);
    Ok(())
}

struct UserProfile {
    email: String,
    username: String,
    profile_picture_url: String,
}

const USER_PROFILES: Mutex<HashMap<u64, UserProfile>> = Mutex::new(HashMap::new());
