                        printf("Invalid RX UE information in CRC indication PDU\n");
                        return;
                    }
                    // Print the extracted information
                    printf("RX UE: %d, RNTI: %d, C-RNTI: %d, Timing Advance: %d\n", rx_ue->rnti, rx_ue->crnti, rx_ue->timing_advance);
                }
            }
        }
    }
}
