['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define MAX_SENSORS 1024
#define MIN_TEMP -273.15
#define MAX_TEMP 10000
#define RETENTION_POLICY 60

typedef struct {
    double temperature;
    char sensor_id[10];
    int index;
} Sensor;

Sensor sensors[MAX_SENSORS];
int num_sensors = 0;

// Hash table to keep track of unique sensor IDs and indices
typedef struct {
    int id;
    int index;
} IDTable;
IDTable id_table[MAX_SENSORS];
int num_ids = 0;

void load_data_from_file(char* filename) {
    FILE *fptr = fopen(filename, "r");
    if (fptr == NULL) {
        perror("Error opening file");
        return;
    }

    // Skip the first line (header)
    char buffer[1024];
    fgets(buffer, 1024, fptr);

    while (!feof(fptr)) {
        Sensor new_sensor;

        // Read a sensor reading from file and validate it
        if (fscanf(fptr, "%lf %s %d", &new_sensor.temperature, new_sensor.sensor_id, &new_sensor.index) != 3) {
            perror("Error reading sensor data");
            continue;
        }

        // Ensure temperature is within specified range
        if (new_sensor.temperature < MIN_TEMP || new_sensor.temperature > MAX_TEMP) {
            printf("Temperature reading out of range: %lf\n", new_sensor.temperature);
            continue;
        }

        // Insert the sensor into the hash table and array, if it doesn't already exist
        int id = atoi(new_sensor.sensor_id);
        if (id >= 0 && id < num_ids) {
            if (id_table[id].id != id || id_table[id].index != new_sensor.index) {
                printf("Duplicate sensor ID or index: %s\n", new_sensor.sensor_id);
                continue;
            }
        } else {
            if (num_ids == MAX_SENSORS) {
                printf("Maximum number of sensors reached\n");
                continue;
            }

            id_table[num_ids].id = id;
            id_table[num_ids].index = new_sensor.index;
            num_ids++;
        }

        // Insert the sensor into the array and hash table
        sensors[num_sensors] = new_sensor;
        id_table[id].id = id;
        id_table[id].index = new_sensor.index;
        num_sensors++;
    }

    fclose(fptr);
}

void delete_outdated_sensors() {
    time_t current_time = time(NULL);
    for (int i = 0; i < num_sensors; i++) {
        if ((current_time - sensors[i].timestamp) / 60 > RETENTION_POLICY) {
            // Delete the sensor from the hash table and array
            int id = atoi(sensors[i].sensor_id);
            id_table[id].id = -1;
            id_table[id].index = -1;

            sensors[i] = sensors[num_sensors - 1];
            num_sensors--;
        }
    }
}

void calculate_statistics() {
    double minimum = INFINITY;
    double maximum = -INFINITY;
    double average = 0.0;

    for (int i = 0; i < num_sensors; i++) {
        minimum = fmin(sensors[i].temperature, minimum);
        maximum = fmax(sensors[i].temperature, maximum);
        average += sensors[i].temperature;
    }

    average /= num_sensors;

    printf("Minimum temperature: %.2lf\n", minimum);
    printf("Maximum temperature: %.2lf\n", maximum);
    printf("Average temperature: %.2lf\n", average);
}

void periodic_pruning() {
    time_t current_time = time(NULL);

    // Delete outdated sensors every hour
    if ((current_time - last_delete) / 60 > 60) {
        delete_outdated_sensors();
        last_delete = current_time;
    }
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        printf("Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    // Initialize the hash table and array with empty entries
    for (int i = 0; i < MAX_SENSORS; i++) {
        id_table[i].id = -1;
        id_table[i].index = -1;
    }

    // Load data from file and handle errors
    load_data_from_file(argv[1]);

    // Periodically prune outdated sensors
    while (1) {
        periodic_pruning();

        // Calculate statistics over the current set of sensors
        calculate_statistics();

        sleep(60);
    }

    return 0;
}
```
This C code provides a data management system for handling sensor readings efficiently. It uses a hash table to keep track of unique sensor IDs and indices, allowing efficient insertion and deletion of sensors based on their ID or index. The code also validates temperature readings and handles edge cases such as file read errors, malformed input lines, and potential memory leaks. Additionally, the system is designed to accommodate future scalability needs by using a fixed-size array for the hash table and dynamically allocating memory for the sensor data.']

