void initializeNetworkStatistics(size_t initialSize, size_t minPayloadSize, size_t maxPayloadSize, size_t *totalEntries, bool checksumValidation) {
    // Allocate memory for the dynamic array of network interface statistics
    networkStats = (struct NetworkInterfaceStatistics *)malloc(sizeof(struct NetworkInterfaceStatistics) * initialSize);
