#include <time.h>

// Record structure
typedef struct {
    long offset;
    int key;
    int value;
} record_t;

// Dynamic array of records
record_t* records = NULL;
int record_count = 0;
int record_capacity = 0;

// Initialize record array with memory allocation
void init_records(int capacity) {
    if (records != NULL) {
        free(records);
    }
    records = malloc(capacity * sizeof(record_t));
    record_count = 0;
    record_capacity = capacity;
}

// Fill each record's int field with a random value within the specified range
void fill_records(int min, int max) {
    srand((unsigned) time(NULL));
    for (int i = 0; i < record_count; i++) {
        records[i].value = rand() % (max - min + 1) + min;
    }
}

// Robust error handling for memory allocation failures
void handle_memory_allocation_failure(int capacity) {
    printf("Memory allocation failed. Increasing record capacity to %d.\n", capacity);
    init_records(capacity);
}

// Ensure efficient memory management to minimize cache misses
void update_record_count() {
    int new_capacity = (record_count + 1) * 2;
    if (new_capacity > record_capacity) {
        handle_memory_allocation_failure(new_capacity);
    }
}

// Add a new record to the array
void add_record(int key, int value) {
    update_record_count();
    records[record_count].key = key;
    records[record_count].value = value;
    record_count++;
}

// Calculate the sum of all int fields
int get_sum() {
    int sum = 0;
    for (int i = 0; i < record_count; i++) {
        sum += records[i].value;
    }
    return sum;
}

// Identify duplicates in the int key values
void find_duplicates() {
    int duplicate_count = 0;
    for (int i = 0; i < record_count - 1; i++) {
        for (int j = i + 1; j < record_count; j++) {
            if (records[i].key == records[j].key) {
                duplicate_count++;
            }
        }
    }
}

// Sort the records based on the int value in descending order
void sort_records() {
    for (int i = 0; i < record_count - 1; i++) {
        for (int j = i + 1; j < record_count; j++) {
            if (records[i].value > records[j].value) {
                int temp = records[i].key;
                records[i].key = records[j].key;
                records[j].key = temp;
            }
        }
    }
}

int main() {
    init_records(10);
    fill_records(1, 10);
    add_record(5, 8);
    printf("Sum of all int fields: %d\n", get_sum());
    find_duplicates();
    sort_records();
    return 0;
}
