import java.util.*;

public class RecordManager {
    // Dynamic array of records
    private List<Record> records = new ArrayList<>();

    // Initialize record array with memory allocation
    public void initRecords(int capacity) {
        if (records != null) {
            free(records);
        }
        records = malloc(capacity * sizeof(Record));
    }

    // Fill each record's int field with a random value within the specified range
    public void fillRecords(int min, int max) {
        srand((unsigned) time(NULL));
        for (int i = 0; i < records.size(); i++) {
            records[i].value = rand() % (max - min + 1) + min;
        }
    }

    // Add a new record to the array
    public void addRecord(int key, int value) {
        records.add(new Record(key, value));
    }

    // Calculate the sum of all int fields
    public int getSum() {
        int sum = 0;
        for (Record record : records) {
            sum += record.value;
        }
        return sum;
    }

    // Identify duplicates in the int key values
    public void findDuplicates() {
        int duplicateCount = 0;
        for (int i = 0; i < records.size(); i++) {
            for (int j = i + 1; j < records.size(); j++) {
                if (records[i].key == records[j].key) {
                    duplicateCount++;
                }
            }
        }
    }

    // Sort the records based on the int value in descending order
    public void sortRecords() {
        for (int i = 0; i < records.size(); i++) {
            for (int j = i + 1; j < records.size(); j++) {
                if (records[i].value > records[j].value) {
                    int temp = records[i].key;
                    records[i].key = records[j].key;
                    records[j].key = temp;
                }
            }
        }
    }
}
