        List<Record> records = new ArrayList<>();
        for (int i = 0; i < 5; i++) {
            records.add(new Record(i, randInt(min, max)));
        }

        // Then
        assertEquals(records.size(), 5);
        for (Record record : records) {
            assertTrue(record.value >= min && record.value <= max);
        }
    }

    @Test
    public void testAddRecord() {
        // Given
        int key = 10;
        int value = 20;

        // When
        List<Record> records = new ArrayList<>();
        for (int i = 0; i < 5; i++) {
            records.add(new Record(i, i));
        }
        records.add(new Record(key, value));

        // Then
        assertEquals(records.size(), 6);
        for (Record record : records) {
            if (record.key == key) {
                assertEquals(record.value, value);
            } else {
                assertTrue(record.value >= min && record.value <= max);
            }
        }
