        // Generate a random RX UE information tag
        crc_indications[i].rx_ue_information_tag = rand() % 1024;

        // Generate a random RNTI
        crc_indications[i].rnti = rand() % 65536;

        // Determine the cipher mode to use based on the environment variable
        char* cipher_mode = getenv("CIPHER_MODE");
        if (cipher_mode == NULL) {
            // Default to AES-256-CBC mode if no environment variable is set
            cipher_mode = "AES-256-CBC";
        }

        // Determine the key length based on the cipher mode
        int key_len;
        if (strcmp(cipher_mode, "AES-256-CBC") == 0) {
            key_len = 32;
        } else if (strcmp(cipher_mode, "AES-128-ECB") == 0) {
            key_len = 16;
        } else {
            // Unsupported cipher mode, fall back to AES-256-CBC
            cipher_mode = "AES-256-CBC";
            key_len = 32;
        }

        // Generate a random encryption key using SHA-256 and the password
        char password[1024];
        getenv("PASSWORD", password, sizeof(password));
        unsigned char key[key_len];
        SHA256(password, strlen(password), key);

        // Initialize the AES cipher context using the encryption key and cipher mode
        AES_KEY aes_key;
        AES_init_ctx(&aes_key, key, key_len, cipher_mode);

        // Generate a random IV for encryption
        unsigned char iv[AES_BLOCK_SIZE];
        RAND_bytes(iv, AES_BLOCK_SIZE);

        // Initialize the CRC indication structure with the generated information
        crc_indications[i].crc_indication_rel8_tag = rand() % 1024;
        crc_indications[i].rnti = rand() % 65536;

        // Encrypt the CRC indication using AES-CBC
        unsigned char* ciphertext = malloc(AES_BLOCK_SIZE);
        int len = AES_encrypt(&aes_key, iv, ciphertext);
        if (len < 0) {
            printf("Error: Failed to encrypt CRC indication\n");
            return -1;
        }

        // Write the encrypted CRC indication to disk
        FILE* f = fopen("crc_indications.bin", "ab+");
        if (f == NULL) {
            printf("Error: Failed to open file for writing\n");
            return -1;
        }
        fwrite(ciphertext, 1, len, f);
        fclose(f);
    }

    // Clean up the AES cipher context and free resources
    AES_exit_ctx(&aes_key);

    return 0;
}
```
