// Initializes the dynamic array and creates a new session
int init_session(uint32_t seq_num, uint8_t* payload, size_t payload_size) {
    // Check if we need to grow the array
    if (num_sessions >= max_sessions) {
        max_sessions *= 2;
        session_array = realloc(session_array, max_sessions * sizeof(NetworkSession));
    }

    // Create a new session and add it to the array
    NetworkSession* new_session = &session_array[num_sessions++];
    new_session->socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    new_session->seq_num = seq_num;
    new_session->payload_size = payload_size;
    new_session->payload = malloc(payload_size);
    memcpy(new_session->payload, payload, payload_size);

    // Return the index of the newly created session
    return num_sessions - 1;
}

// Deallocates a session from the dynamic array
