// Custom data structure to store session states and acknowledgment status
class SessionState {
    private int socketFd;
    private uint32_t seqNum;
    private byte[] payload;
    private boolean isAcked;
}

// Map to store all the sessions
ConcurrentHashMap<Integer, SessionState> sessionMap = new ConcurrentHashMap<>();

// Function to add a new session and return its index
int addSession(uint32_t seqNum, byte[] payload, int payloadSize) {
    // Create a new session state object and add it to the map
    SessionState newSession = new SessionState();
    newSession.socketFd = socket(AF_INET, SOCK_STREAM, 0);
    newSession.seqNum = seqNum;
    newSession.payloadSize = payloadSize;
    newSession.isAcked = false;
    sessionMap.put(newSession.socketFd, newSession);

    // Return the index of the newly created session
    return sessionMap.size() - 1;
}

// Function to destroy a session and remove it from the map
void destroySession(int index) {
    SessionState session = sessionMap.get(index);
    close(session.socketFd);
    sessionMap.remove(index);
}

// Function to check if a session has been acknowledged or not
boolean isAcked(int index) {
    SessionState session = sessionMap.get(index);
    return session.isAcked;
}
