int process_numbers(void) {
    int ret = 0;
    char buffer[4096]; // assuming a maximum of 4KB data per read() call
    L2TP_TUNNEL *tunnels[MAX_TUNNELS];
    size_t num_tunnels = 0;
    float smallest = INFINITY;

    // allocate memory for the tunnels
    if ((tunnels = malloc(sizeof(L2TP_TUNNEL) * MAX_TUNNELS)) == NULL) {
        perror("malloc");
        return 0;
    }

    // initialize the pool of tunnels
    for (size_t i = 0; i < MAX_TUNNELS; ++i) {
        tunnels[i] = calloc(1, sizeof(L2TP_TUNNEL));
        if (tunnels[i] == NULL) {
            perror("calloc");
            ret = 0;
            break;
        }
    }

    // loop until the end of the stream is reached or an error occurs
    while (1) {
        // read a chunk of data from the network stream
        ssize_t bytes_read = read(STDIN_FILENO, buffer, 4096);
        if (bytes_read <= 0) {
            break;
        }

        // validate and process each floating-point number in the chunk
        for (char *ptr = buffer; ptr < buffer + bytes_read; ++ptr) {
            float num = strtof(ptr, NULL);
            if (!isfinite(num)) {
                continue;
            }

            // validate the L2TP header and update the pap flag
            L2TP_HEADER *header = (L2TP_HEADER *) ptr;
            if (!validate_header(header)) {
                continue;
            }
            tunnels[num_tunnels]->pap_flag = get_random_pap_flag();

            // update the session ID and peer CID
            tunnels[num_tunnels]->session_id = header->session_id;
            tunnels[num_tunnels]->peer_cid = header->peer_cid;

            // determine the smallest number found so far
            if (num < smallest) {
                smallest = num;
            }

            // execute the network command asynchronously
            pthread_t thread;
            pthread_create(&thread, NULL, execute_network_command, &num);
            pthread_detach(thread);
        }
    }

    // free memory for unused tunnels and log information about the pool
    for (size_t i = 0; i < num_tunnels; ++i) {
        if (tunnels[i] == NULL) {
            continue;
        }
        free(tunnels[i]);
        printf("Tunnel %zu: session ID=%u, peer CID=%u, pap flag=%hu\n", i + 1, tunnels[i]->session_id, tunnels[i]->peer_cid, tunnels[i]->pap_flag);
    }

    // execute the network command asynchronously with the smallest number found
    pthread_t thread;
    pthread_create(&thread, NULL, execute_network_command, &smallest);
    pthread_detach(thread);

    return 1;
}

int validate_header(L2TP_HEADER *header) {
    // TODO: implement a more comprehensive header validation function
    return (header->version == 0x01 && header->type == 0x01 && header->length > 0);
}

uint16_t get_random_pap_flag() {
    uint16_t flag = 0;
    while (flag == 0 || flag >= PAP_FLAG_MAX) {
        flag = rand() % (PAP_FLAG_MAX - PAP_FLAG_MIN + 1) + PAP_FLAG_MIN;
    }
    return flag;
}

void *execute_network_command(void *args) {
