typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    Record* records;
    size_t num_records;
    pthread_mutex_t lock;
} Database;

Database* database_init(size_t initial_capacity) {
    // Initialize the database with an empty list of records and a mutex for synchronization.
    Database* db = (Database*)malloc(sizeof(Database));
    db->records = (Record*)calloc(initial_capacity, sizeof(Record));
    db->num_records = 0;
    pthread_mutex_init(&db->lock, NULL);
    return db;
}

void database_add_record(Database* db, int key, long offset) {
    // Add a new record to the end of the linked list.
    pthread_mutex_lock(&db->lock);
    if (db->num_records == 0 || db->num_records == db->records->capacity) {
        // Double the capacity of the record array when it reaches its limit.
        size_t new_capacity = db->records->capacity * 2;
        Record* new_records = (Record*)realloc(db->records, new_capacity);
        if (new_records == NULL) {
            // Handle out-of-memory condition by gracefully shutting down the system.
            fprintf(stderr, "Out of memory! Shutting down...\n");
            exit(EXIT_FAILURE);
        }
        db->records = new_records;
        db->records->capacity = new_capacity;
    }
    Record* record = &db->records[db->num_records++];
    record->key = key;
    record->offset = offset;
    pthread_mutex_unlock(&db->lock);
}

void database_delete_record(Database* db, int key) {
    // Remove a record with the given key from the list.
    bool found = false;
    for (size_t i = 0; i < db->num_records; i++) {
        if (db->records[i].key == key) {
            Record* deleted_record = &db->records[i];
            // Update the references in the linked list.
            if (i != db->num_records - 1) {
                Record* next_record = &db->records[i + 1];
                next_record->offset -= deleted_record->offset;
            }
            pthread_mutex_lock(&db->lock);
            if (found) {
                // Copy the records over the deleted record.
                memmove(deleted_record, deleted_record + 1, sizeof(Record));
            } else {
                db->num_records--;
            }
            pthread_mutex_unlock(&db->lock);
            found = true;
        }
    }
}

void database_free(Database* db) {
    // Free the memory allocated for the record array and destroy the mutex.
    free(db->records);
    pthread_mutex_destroy(&db->lock);
    free(db);
}
```
