#include <sys/types.h>
#include <netinet/in.h>

// Define structure for network interface statistics
typedef struct {
    uint8_t mac_header[6];
    uint32_t ip_packet;
    uint16_t payload_size;
    uint32_t checksum;
} nic_statistics_t;

// Define array for dynamic allocation of network interface statistics structures
nic_statistics_t **nic_statistics = NULL;
size_t nic_statistics_size = 0;

// Function to initialize the dynamic array of network interface statistics structures
void init_nic_statistics(int num_interfaces) {
    // Allocate memory for the array of pointers to network interface statistics structures
    nic_statistics = (nic_statistics_t **)malloc(num_interfaces * sizeof(nic_statistics_t));
    if (!nic_statistics) {
        printf("Error: Failed to allocate memory for network interface statistics\n");
        exit(1);
    }

    // Initialize each pointer in the array to NULL
    for (int i = 0; i < num_interfaces; i++) {
        nic_statistics[i] = NULL;
    }

    // Set the size of the dynamic array to the number of interfaces
    nic_statistics_size = num_interfaces;
}

// Function to allocate memory for a new network interface statistics structure
nic_statistics_t *allocate_nic_statistics(int interface) {
    // Check if the size of the dynamic array has been exceeded
    if (interface >= nic_statistics_size) {
        printf("Error: Too many interfaces, cannot allocate memory for new network interface statistics\n");
        exit(1);
    }

    // Allocate memory for a new network interface statistics structure
    nic_statistics[interface] = (nic_statistics_t *)malloc(sizeof(nic_statistics_t));
    if (!nic_statistics[interface]) {
        printf("Error: Failed to allocate memory for new network interface statistics\n");
        exit(1);
    }

    // Initialize the MAC header and IP packet fields of the structure to 0
    memset(nic_statistics[interface]->mac_header, 0, sizeof(uint8_t) * 6);
    nic_statistics[interface]->ip_packet = 0;

    // Generate a random payload size and checksum for the structure
    srand(time(NULL));
    int min_payload_size = 1024;
    int max_payload_size = 65535;
    nic_statistics[interface]->payload_size = rand() % (max_payload_size - min_payload_size) + min_payload_size;
    uint32_t checksum = 0;
    for (int i = 0; i < nic_statistics[interface]->payload_size; i++) {
        checksum += rand() % 256;
    }
    nic_statistics[interface]->checksum = checksum;

    // Return the pointer to the new network interface statistics structure
    return nic_statistics[interface];
}

// Function to free memory for a network interface statistics structure
void free_nic_statistics(int interface) {
    // Check if the index is valid
    if (interface >= 0 && interface < nic_statistics_size) {
        // Free the memory allocated to the structure
        free(nic_statistics[interface]);
        nic_statistics[interface] = NULL;
    } else {
        printf("Error: Invalid index for network interface statistics\n");
        exit(1);
    }
}

// Function to insert a new network interface statistics structure into the array
void insert_nic_statistics(int interface, uint8_t *mac_header, uint32_t ip_packet) {
    // Check if the index is valid
    if (interface >= 0 && interface < nic_statistics_size) {
        // Allocate memory for a new network interface statistics structure
        allocate_nic_statistics(interface);

        // Copy the MAC header and IP packet fields into the new structure
        memcpy(nic_statistics[interface]->mac_header, mac_header, sizeof(uint8_t) * 6);
        nic_statistics[interface]->ip_packet = ip_packet;
    } else {
        printf("Error: Invalid index for network interface statistics\n");
        exit(1);
    }
}

// Function to validate the checksum of a network interface statistics structure
int validate_checksum(nic_statistics_t *nic_stats) {
    // Calculate the checksum of the payload
    uint32_t checksum = 0;
    for (int i = 0; i < nic_stats->payload_size; i++) {
        checksum += nic_stats->ip_packet[i];
    }

    // Compare the calculated checksum with the stored checksum
    if (checksum == nic_stats->checksum) {
        return 1;
    } else {
        return 0;
    }
}

// Function to handle packet insertion into the array
void handle_packet_insertion(int interface, uint8_t *mac_header, uint32_t ip_packet) {
    // Check if the index is valid
    if (interface >= 0 && interface < nic_statistics_size) {
        // Insert a new network interface statistics structure into the array
        insert_nic_statistics(interface, mac_header, ip_packet);
    } else {
        printf("Error: Invalid index for network interface statistics\n");
        exit(1);
    }
}

// Function to handle packet arrival from external sources
void handle_external_packet(int interface, uint8_t *mac_header, uint32_t ip_packet) {
    // Check if the index is valid
    if (interface >= 0 && interface < nic_statistics_size) {
        // Validate the checksum of the received packet
        int checksum_valid = validate_checksum(nic_statistics[interface]);
        if (!checksum_valid) {
            printf("Error: Checksum invalid for received network interface statistics\n");
            exit(1);
        } else {
            // Insert the received packet into the array
            handle_packet_insertion(interface, mac_header, ip_packet);
        }
    } else {
        printf("Error: Invalid index for network interface statistics\n");
        exit(1);
    }
}

// Function to handle packet arrival from internal sources
void handle_internal_packet(int interface, uint8_t *mac_header, uint32_t ip_packet) {
    // Check if the index is valid
    if (interface >= 0 && interface < nic_statistics_size) {
        // Insert a new network interface statistics structure into the array
        insert_nic_statistics(interface, mac_header, ip_packet);
    } else {
        printf("Error: Invalid index for network interface statistics\n");
        exit(1);
    }
}
