// Define the array of LTE UE contexts
static lte_ue_context_t* ue_contexts = NULL;
static size_t num_ue_contexts = 0;

// Function to add a new context
void add_new_context(int rrc_connection_id, char* mac_pdu) {
    // Allocate memory for the new context
    lte_ue_context_t* new_context = (lte_ue_context_t*) malloc(sizeof(lte_ue_context_t));
    assert(new_context != NULL);

    // Initialize the fields of the new context
    new_context->rrc_connection_id = rrc_connection_id;
    new_context->mac_pdu = strdup(mac_pdu);

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&ue_contexts_mutex);

    // Check if there is enough space in the array to store the new context
    if (num_ue_contexts >= ue_contexts_size) {
        // Resize the array if necessary
        resize_array();
    }

    // Add the new context to the end of the array
    ue_contexts[num_ue_contexts] = *new_context;
    num_ue_contexts++;

    // Unlock the mutex
    pthread_mutex_unlock(&ue_contexts_mutex);
}

// Function to update an existing context
void update_context(int rrc_connection_id, char* mac_pdu) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&ue_contexts_mutex);

    // Find the index of the context to be updated
    int index = find_index(rrc_connection_id);

    // Check if the context exists
    if (index == -1) {
        pthread_mutex_unlock(&ue_contexts_mutex);
        return;
    }

    // Update the fields of the context
    ue_contexts[index].rrc_connection_id = rrc_connection_id;
    free(ue_contexts[index].mac_pdu);
    ue_contexts[index].mac_pdu = strdup(mac_pdu);

    // Unlock the mutex
    pthread_mutex_unlock(&ue_contexts_mutex);
}

// Function to remove a context by ID
void remove_context(int rrc_connection_id) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&ue_contexts_mutex);

    // Find the index of the context to be removed
    int index = find_index(rrc_connection_id);

    // Check if the context exists
    if (index == -1) {
        pthread_mutex_unlock(&ue_contexts_mutex);
        return;
    }

    // Remove the context from the array
    for (int i = index; i < num_ue_contexts - 1; i++) {
        ue_contexts[i] = ue_contexts[i + 1];
    }
    num_ue_contexts--;

    // Free the memory of the removed context
    free(ue_contexts[num_ue_contexts].mac_pdu);

    // Unlock the mutex
    pthread_mutex_unlock(&ue_contexts_mutex);
}

// Function to find the index of a context by ID
int find_index(int rrc_connection_id) {
    for (int i = 0; i < num_ue_contexts; i++) {
        if (ue_contexts[i].rrc_connection_id == rrc_connection_id) {
            return i;
        }
    }
    return -1;
}

// Function to serialize the array to a file
void serialize_array(char* filename) {
    // Open the file for writing
    FILE* fp = fopen(filename, "w");
    assert(fp != NULL);

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&ue_contexts_mutex);

    // Write the number of contexts in the file
    int num_contexts = num_ue_contexts;
    fwrite(&num_contexts, sizeof(int), 1, fp);

    // Write each context to the file
    for (int i = 0; i < num_ue_contexts; i++) {
        fwrite(&ue_contexts[i], sizeof(lte_ue_context_t), 1, fp);
    }

    // Unlock the mutex
    pthread_mutex_unlock(&ue_contexts_mutex);
}

// Function to deserialize the array from a file
void deserialize_array(char* filename) {
    // Open the file for reading
    FILE* fp = fopen(filename, "r");
    assert(fp != NULL);

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&ue_contexts_mutex);

    // Read the number of contexts from the file
    int num_contexts;
    fread(&num_contexts, sizeof(int), 1, fp);

    // Resize the array if necessary
    resize_array();

    // Read each context from the file
    for (int i = 0; i < num_ue_contexts; i++) {
        fread(&ue_contexts[i], sizeof(lte_ue_context_t), 1, fp);
    }

    // Unlock the mutex
    pthread_mutex_unlock(&ue_contexts_mutex);
}

// Function to resize the array if necessary
void resize_array() {
    int new_size = num_ue_contexts * 2;
    ue_contexts = realloc(ue_contexts, sizeof(lte_ue_context_t) * new_size);
    assert(ue_contexts != NULL);
}']

