// Define a struct to represent a connection state
struct ConnectionState {
    int sock; // Socket descriptor
    struct sockaddr_in addr; // Peer address
    int status; // Connection status (e.g., ESTABLISHED, CLOSED)
    time_t last_activity; // Last activity timestamp
    unsigned long refcount; // Reference count for concurrent access
};

// Define a doubly linked list to store all connection states
struct ConnList {
    struct ConnectionState *head;
    struct ConnectionState *tail;
};

// Initialize the connection state list
static void init_connlist(struct ConnList *list) {
    list->head = NULL;
    list->tail = NULL;
}

// Add a new connection state to the list
static void add_connstate(struct ConnList *list, int sock, struct sockaddr_in addr, int status) {
    // Create a new connection state object
    struct ConnectionState *cs = malloc(sizeof(struct ConnectionState));
    cs->sock = sock;
    memcpy(&cs->addr, &addr, sizeof(struct sockaddr_in));
    cs->status = status;
    cs->last_activity = time(NULL);
    cs->refcount = 0;

    // Add the new connection state to the list
    if (list->head == NULL) {
        list->head = cs;
        list->tail = cs;
    } else {
        list->tail->next = cs;
        cs->prev = list->tail;
        list->tail = cs;
    }
}

// Remove a connection state from the list
static void remove_connstate(struct ConnList *list, int sock) {
    // Find the connection state with the matching socket descriptor
    struct ConnectionState *cs = NULL;
    for (struct ConnectionState *cur = list->head; cur != NULL; cur = cur->next) {
        if (cur->sock == sock) {
            cs = cur;
            break;
        }
    }

    // Remove the connection state from the list
    if (cs != NULL) {
        if (cs == list->head) {
            list->head = cs->next;
        } else {
            cs->prev->next = cs->next;
        }
        if (cs == list->tail) {
            list->tail = cs->prev;
        } else {
            cs->next->prev = cs->prev;
        }
    }
}

// Accept a new incoming TCP stream and add it to the connection state list
static int accept_conn(struct ConnList *list, int sock) {
    // Create a new socket for the incoming connection
    struct sockaddr_in client;
    socklen_t client_len = sizeof(struct sockaddr_in);
    if (getsockname(sock, (struct sockaddr *)&client, &client_len) < 0) {
        return -1;
    }

    // Add the new connection state to the list
    add_connstate(list, sock, client, ESTABLISHED);
    return 0;
}

// Validate a connection and update its status in the connection state list
static int validate_conn(struct ConnList *list, int sock) {
    // Find the connection state with the matching socket descriptor
    struct ConnectionState *cs = NULL;
    for (struct ConnectionState *cur = list->head; cur != NULL; cur = cur->next) {
        if (cur->sock == sock) {
            cs = cur;
            break;
        }
    }

    // Validate the connection and update its status in the connection state list
    if (cs != NULL && cs->status == ESTABLISHED) {
        cs->last_activity = time(NULL);
        return 0;
    } else {
        return -1;
    }
}

// Close an idle connection and remove it from the connection state list
static int close_idle_conn(struct ConnList *list, int sock) {
    // Find the connection state with the matching socket descriptor
    struct ConnectionState *cs = NULL;
    for (struct ConnectionState *cur = list->head; cur != NULL; cur = cur->next) {
        if (cur->sock == sock) {
            cs = cur;
            break;
        }
    }

    // Close the idle connection and remove it from the connection state list
    if (cs != NULL && cs->last_activity + IDLE_TIMEOUT <= time(NULL)) {
        shutdown(cs->sock, SHUT_RDWR);
        close(cs->sock);
        remove_connstate(list, sock);
        return 0;
    } else {
        return -1;
    }
}

// Gracefully shut down a connection and update its status in the connection state list
static int shutdown_conn(struct ConnList *list, int sock) {
    // Find the connection state with the matching socket descriptor
    struct ConnectionState *cs = NULL;
    for (struct ConnectionState *cur = list->head; cur != NULL; cur = cur->next) {
        if (cur->sock == sock) {
            cs = cur;
            break;
        }
    }

    // Gracefully shut down the connection and update its status in the connection state list
    if (cs != NULL && cs->status != CLOSED) {
        shutdown(cs->sock, SHUT_RDWR);
        remove_connstate(list, sock);
        return 0;
    } else {
        return -1;
    }
}

// Periodically check for idle connections and close them
static void *check_idle_conns(void *data) {
    struct ConnList *list = (struct ConnList *)data;
    while (1) {
        // Sleep for a specified duration before checking for idle connections
        sleep(IDLE_TIMEOUT);

        // Close any idle connections found in the connection state list
        for (struct ConnectionState *cur = list->head; cur != NULL; cur = cur->next) {
            if (cur->last_activity + IDLE_TIMEOUT <= time(NULL)) {
                shutdown(cs->sock, SHUT_RDWR);
                close(cs->sock);
                remove_connstate(list, cs->sock);
            }
        }
    }
}

// Main function for the server
int main(int argc, char **argv) {
    // Initialize a new connection state list
    struct ConnList *list = NULL;

    // Create a socket and bind it to the specified port number
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        return -1;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(struct sockaddr_in));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(PORT);
    if (bind(sock, (struct sockaddr *)&addr, sizeof(struct sockaddr_in)) < 0) {
        return -1;
    }

    // Listen for incoming connections and add them to the connection state list
    while (1) {
        // Accept a new incoming TCP stream
        int client = accept(sock, NULL, NULL);
        if (client < 0) {
            return -1;
        }

        // Add the new connection state to the list
        add_connstate(list, client);
    }
}
