        return -1;
    }

    // Log the current usage of the memory pool and data structures
    fprintf(log, "Memory pool usage: %zu bytes\n", pool->used);

    // Log the creation of each structure and command execution status
    for (int i = 0; i < pool->used / sizeof(void*); ++i) {
        void* data = pool->data[i];
        if (data == NULL) {
            fprintf(log, "Data structure %d is empty\n", i);
        } else {
            fprintf(log, "Data structure %d contains %zu bytes of data\n", i, sizeof(void*));
