}

// Function to manage the command's lifecycle and interaction with the main process, including a timeout mechanism to terminate the command if it exceeds an allowed duration.
int manageCommand(struct MemoryPool* pool, char* command, int timeout) {
    // Validate input parameters
    if (pool == NULL || command == NULL || timeout < 0) {
        return -1;
    }

    // Fork a new process to execute the command
    pid_t pid = fork();
    if (pid < 0) {
