        return -1;
    } else if (pid == 0) {
        // Child process executes the command
        execl("/bin/sh", "sh", "-c", command, NULL);
        exit(0);
    } else {
        // Parent process waits for the command to complete or timeout
        int status;
        waitpid(pid, &status, 0);
        if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
            return 0;
        } else {
            printf("Command execution failed: %s\n", strerror(errno));
            return -1;
        }
    }
}

// Function to handle command execution failures gracefully, including signal handling and cleanup of resources.
int handleCommandError(struct MemoryPool* pool) {
    // Validate input parameters
    if (pool == NULL) {
        return -1;
    }

    // Handle any command execution errors by cleaning up resources and logging the error
    for (int i = 0; i < pool->used / sizeof(void*); ++i) {
        void* data = pool->data[i];
        if (data == NULL) {
            continue;
        }
        // Clean up any resources used by the command execution
        free(data);
    }
    printf("Command execution failed: %s\n", strerror(errno));

    return 0;
}
