typedef struct record {
    int key;
} record_t;

struct node {
    record_t *record;
    struct node *left, *right;
};

typedef struct tree {
    struct node *root;
} tree_t;

void init(tree_t *tree) {
    tree->root = NULL;
}

int insert(tree_t *tree, record_t *record) {
    if (tree->root == NULL) {
        tree->root = malloc(sizeof(struct node));
        tree->root->record = record;
        tree->root->left = NULL;
        tree->root->right = NULL;
        return 0;
    } else {
        struct node *curr = tree->root;
        while (1) {
            if (record->key < curr->record->key) {
                if (curr->left == NULL) {
                    curr->left = malloc(sizeof(struct node));
                    curr->left->record = record;
                    curr->left->left = NULL;
                    curr->left->right = NULL;
                    return 0;
                } else {
                    curr = curr->left;
                }
            } else if (record->key > curr->record->key) {
                if (curr->right == NULL) {
                    curr->right = malloc(sizeof(struct node));
                    curr->right->record = record;
                    curr->right->left = NULL;
                    curr->right->right = NULL;
                    return 0;
                } else {
                    curr = curr->right;
                }
            } else {
                return -1;
            }
        }
    }
}

int remove(tree_t *tree, int key) {
    if (tree->root == NULL) {
        return -1;
    } else {
        struct node *curr = tree->root;
        while (1) {
            if (key < curr->record->key) {
                if (curr->left == NULL) {
                    return -1;
                } else {
                    curr = curr->left;
                }
            } else if (key > curr->record->key) {
                if (curr->right == NULL) {
                    return -1;
                } else {
                    curr = curr->right;
                }
            } else {
                break;
            }
        }
        free(curr->record);
        curr->record = NULL;
        if (curr->left == NULL && curr->right == NULL) {
            tree->root = NULL;
        }
        return 0;
    }
}

void print(tree_t *tree) {
    if (tree->root != NULL) {
        printf("%d\n", tree->root->record->key);
        print(tree->root->left);
        print(tree->root->right);
    }
}

int main() {
    srand(time(NULL));
    int n = 10; // number of records to generate
    tree_t *tree = malloc(sizeof(tree_t));
    init(tree);
    for (int i = 0; i < n; i++) {
        record_t *record = malloc(sizeof(record_t));
        record->key = rand() % 100 + 1; // random key between 1 and 100
        insert(tree, record);
    }
    print(tree);
    return 0;
}
