#include <stdlib.h>
#include <pthread.h>

typedef struct {
    // Define the structure for LTE_PHY_RX_FRAME here
} LTE_PHY_RX_FRAME;

struct FrameManager {
    pthread_mutex_t mutex;
    size_t frame_count;
    LTE_PHY_RX_FRAME* frames;
};

int addFrame(struct FrameManager* manager, LTE_PHY_RX_FRAME* frame) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->frame_count >= MAX_FRAMES) {
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }
    manager->frames[manager->frame_count] = frame;
    manager->frame_count++;
    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

int updateFrame(struct FrameManager* manager, size_t index, LTE_PHY_RX_FRAME* frame) {
    if (index >= manager->frame_count) {
        return -1;
    }
    pthread_mutex_lock(&manager->mutex);
    manager->frames[index] = frame;
    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

int getFrameCount(struct FrameManager* manager) {
    size_t count;
    pthread_mutex_lock(&manager->mutex);
    count = manager->frame_count;
    pthread_mutex_unlock(&manager->mutex);
    return count;
}

int retrieveFrame(struct FrameManager* manager, size_t index, LTE_PHY_RX_FRAME** frame) {
    if (index >= manager->frame_count) {
        return -1;
    }
    pthread_mutex_lock(&manager->mutex);
    *frame = &manager->frames[index];
    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

int freeFrames(struct FrameManager* manager) {
    size_t i;
    for (i = 0; i < manager->frame_count; i++) {
        free(manager->frames[i]);
    }
    pthread_mutex_destroy(&manager->mutex);
    return 0;
}
