void populateUserSession(UserSession* sessions, int numSessions) {
    for (int i = 0; i < numSessions; i++) {
        sessions[i].sessionId = i + 1;
        sessions[i].connectionStatus = 'C';
        sessions[i].userActivityLog = malloc(1024 * 1024); // 1 MB
        if (!sessions[i].userActivityLog) {
            perror("malloc failed");
            exit(EXIT_FAILURE);
        }
        memset(sessions[i].userActivityLog, 0, 1024 * 1024);
    }
}

void insertUserSession(UserSession* sessions, int numSessions, UserSession newSession) {
    if (numSessions >= MAX_SESSIONS) {
        printf("Maximum number of sessions reached. Inserting new session failed.\n");
        return;
    }
    sessions[numSessions++] = malloc(sizeof(UserSession));
    memcpy(sessions[numSessions - 1], &newSession, sizeof(UserSession));
}

void updateUserSession(UserSession* sessions, int numSessions, int sessionId, UserSession newSession) {
    for (int i = 0; i < numSessions; i++) {
        if (sessions[i].sessionId == sessionId) {
            memcpy(sessions[i], &newSession, sizeof(UserSession));
            return;
        }
    }
    printf("Session with ID %d not found. Update failed.\n", sessionId);
}

void deleteUserSession(UserSession* sessions, int numSessions, int sessionId) {
    for (int i = 0; i < numSessions; i++) {
        if (sessions[i].sessionId == sessionId) {
            free(sessions[i]);
            memmove(sessions + i, sessions + i + 1, sizeof(UserSession) * (numSessions - i - 1));
            numSessions--;
            return;
        }
    }
    printf("Session with ID %d not found. Deletion failed.\n", sessionId);
}

void searchUserSession(UserSession* sessions, int numSessions, int sessionId) {
    for (int i = 0; i < numSessions; i++) {
        if (sessions[i].sessionId == sessionId) {
            printf("Session with ID %d found.\n", sessionId);
            return;
        }
    }
    printf("Session with ID %d not found.\n", sessionId);
}

void cleanupUserSessions(UserSession* sessions, int numSessions) {
    for (int i = 0; i < numSessions; i++) {
        free(sessions[i]);
    }
}
