// Custom allocator with fallback strategy for thread-safe initialization
void* custom_alloc(size_t size) {
    void* ptr = NULL;
    if (size > 0) {
        ptr = malloc(size);
        if (!ptr) {
            ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
