// Function to manage memory for interconnected data structures
void mange_memory(int num_records, int range_min, int range_max, char* pattern) {
    // Validate input parameters
    if (num_records <= 0 || range_min < 0 || range_max < range_min || !pattern) {
        fprintf(stderr, "Invalid input parameters\n");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for the record array
    Record* records = (Record*) custom_alloc(num_records * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for record array\n");
        exit(EXIT_FAILURE);
    }

    // Initialize the key array randomly or according to a predefined pattern
    if (strcmp(pattern, "random") == 0) {
        // Generate random keys within the specified range
        for (int i = 0; i < num_records; i++) {
            records[i].key = rand() % (range_max - range_min + 1) + range_min;
        }
    } else if (strcmp(pattern, "sequential") == 0) {
        // Generate sequential keys starting from the minimum value
        for (int i = 0; i < num_records; i++) {
            records[i].key = range_min + i;
        }
    } else {
        fprintf(stderr, "Invalid pattern\n");
        exit(EXIT_FAILURE);
    }

    // Initialize the offset array with zero values
    long* offsets = (long*) custom_alloc(num_records * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Failed to allocate memory for offset array\n");
        exit(EXIT_FAILURE);
    }
    memset(offsets, 0, num_records * sizeof(long));

    // Monitor system memory usage and adjust the record array size if necessary
    long max_memory = sysconf(_SC_PHYS_PAGES) * sysconf(_SC_PAGESIZE);
    while (num_records > 0 && get_used_memory() >= max_memory / 2) {
        num_records--;
        records[num_records].key = INT_MIN;
        offsets[num_records] = -1;
    }

    // Deallocate memory for the record array and offset array when exiting
    atexit(custom_dealloc);
}
