    int crc_indication_rel8_tag;
    char* crcfla[MAX_RECORDS];
} NFAPI_CRC_INDICATION_PDU_T;

// Define function to create and populate list of CRC indication PDUs
int create_crc_indication_pdus(NFAPI_CRC_INDICATION_PDU_T** crc_indication_pdus, int num_records) {
    // Allocate memory for the list of CRC indication PDUs
    *crc_indication_pdus = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * num_records);

    // Populate the list with random values
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        (*crc_indication_pdus)[i].rx_ue_information_tag = rand() % MAX_RECORDS;
        (*crc_indication_pdus)[i].rnti = rand() % MAX_RECORDS;
        (*crc_indication_pdus)[i].crc_indication_rel8_tag = rand() % MAX_RECORDS;
        for (int j = 0; j < MAX_RECORDS; j++) {
            (*crc_indication_pdus)[i].crcfla[j] = malloc(sizeof(char*) * MAX_RECORDS);
        }
    }

    return 1;
}

// Define function to run a given command in the background using fork and wait
int run_background_command(const char* command) {
    // Fork a new process for the command
    pid_t pid = fork();

    // Handle errors if the fork was unsuccessful
    if (pid < 0) {
        perror("fork failed");
        return 0;
    }

    // The parent process should wait for the child process to finish
    if (pid == 0) {
        execl("/bin/bash", "bash", "-c", command, (char*)NULL);
        perror("execl failed");
        return 0;
    }

    // Wait for the child process to finish
    int status;
    waitpid(pid, &status, 0);

    // Check if the command was successful
    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
        return 1;
    } else {
        printf("Background command failed with status %d\n", status);
        return 0;
    }
}

// Define function to handle error cases gracefully
int handle_error(const char* message) {
    perror(message);
    return 0;
}

int main() {
    // Create a list of CRC indication PDUs with random values
    NFAPI_CRC_INDICATION_PDU_T** crc_indication_pdus = NULL;
    if (!create_crc_indication_pdus(&crc_indication_pdus, MAX_RECORDS)) {
        handle_error("Failed to create CRC indication PDUs");
    }

    // Run a background command using fork and wait
    if (!run_background_command("echo Hello, world!")) {
        handle_error("Failed to run background command");
    }

    return 0;
}
