record** initialize_records(size_t size, size_t key_count, size_t record_count) {
    // Check for invalid input parameters
    if (size == 0 || key_count == 0 || record_count == 0) {
        return NULL;
    }

    // Dynamically allocate memory for the array of offsets and keys
    long* offsets = malloc(sizeof(long) * size);
    int* keys = malloc(sizeof(int) * key_count);
    if (offsets == NULL || keys == NULL) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize the offsets and keys arrays
    for (size_t i = 0; i < size; i++) {
        offsets[i] = i * sizeof(long);
    }
    for (size_t i = 0; i < key_count; i++) {
        keys[i] = i + 1;
    }

    // Create a hash table to map keys to indices in the array of records
    size_t* key_indices = malloc(sizeof(size_t) * key_count);
    if (key_indices == NULL) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize the hash table with a random seed and a prime number of buckets
    srand(time(NULL));
    size_t bucket_count = key_count + 10;
    for (size_t i = 0; i < key_count; i++) {
        key_indices[i] = rand() % bucket_count;
