    if (records == NULL) {
        free(offsets);
        free(keys);
        free(key_indices);
        return NULL;
    }
    for (size_t i = 0; i < record_count; i++) {
        // Get a random key from the hash table and increment its index
        size_t key_index = rand() % bucket_count;
        while (key_indices[key_index] == SIZE_MAX) {
            key_index++;
        }
        records[i].offset = &offsets[key_indices[key_index]];
        records[i].key = keys[key_index];
        records[i].value = 0;
        // Set the next index to be used for the hash table
        key_indices[key_index]++;
    }

    // Free memory allocated by the hash table and return the array of records
    free(key_indices);
    return records;
}
