// NetworkEventLogConfig structure for configuration details
typedef struct {
    int max_log_size; // maximum size of the event log in bytes
    int min_interval; // minimum interval between events in milliseconds
    int max_interval; // maximum interval between events in milliseconds
} NetworkEventLogConfig;

// NetworkEventLogEntry structure for each generated event
typedef struct {
    int event_id; // unique event ID
    time_t timestamp; // current system time
    char* event_type; // randomly selected from a predefined list of event types
} NetworkEventLogEntry;

// calculateEventHash helper function to compute SHA-256 hash of provided string
char* calculateEventHash(const char* str) {
    unsigned char digest[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)str, strlen(str), digest);
    char* hex = malloc(SHA256_DIGEST_LENGTH * 2 + 1);
    for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        sprintf(&hex[i * 2], "%02x", digest[i]);
    }
    return hex;
}

// generateNetworkEvents function to generate events
NetworkEventLogEntry* generateNetworkEvents(int n, NetworkEventLogConfig config) {
    // allocate memory for event log entries
    NetworkEventLogEntry* log = malloc(sizeof(NetworkEventLogEntry) * n);

    // fill in event log entries with unique IDs and timestamps
    for (int i = 0; i < n; ++i) {
        int event_id = i + 1;
        time_t timestamp = time(NULL);
        char* event_type = calculateEventHash("event_type"); // randomly select from predefined list of event types
        log[i] = (NetworkEventLogEntry){.event_id = event_id, .timestamp = timestamp, .event_type = event_type};
    }

    // ensure event generation rate complies with specified interval constraints
    if (config.min_interval > 0) {
        int interval = rand() % (config.max_interval - config.min_interval + 1) + config.min_interval;
        sleep(interval);
    }

    // return event log entries
    return log;
}
