#include <pthread.h>
#include <stdbool.h>
#include <stdlib.h>

// Define the structure for the linked list
struct NFAPIData {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
    struct NFAPIData *next;
};

// Define the list head
struct NFAPIDataList {
    struct NFAPIData *head;
    pthread_mutex_t mutex;
};

// Function to create a new node in the list
static void addNode(struct NFAPIDataList *list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, bool CRCFLAG) {
    struct NFAPIData *node = malloc(sizeof(struct NFAPIData));
    node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    node->RNTI = RNTI;
    node->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    node->CRCFLAG = CRCFLAG;
    node->next = NULL;

    // Add the new node to the list
    pthread_mutex_lock(&list->mutex);
    if (list->head == NULL) {
        list->head = node;
    } else {
        struct NFAPIData *current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
    }
    pthread_mutex_unlock(&list->mutex);
}

// Function to remove a node from the list
static void deleteNode(struct NFAPIDataList *list, int RX_UE_INFORMATION_TAG) {
    struct NFAPIData *node = NULL;

    // Find the node with the specified RX_UE_INFORMATION_TAG
    pthread_mutex_lock(&list->mutex);
    struct NFAPIData *current = list->head;
    while (current != NULL) {
        if (current->RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            node = current;
            break;
        }
        current = current->next;
    }

    // If the node was found, remove it from the list
    if (node != NULL) {
        struct NFAPIData *prev = NULL;
        while (current != NULL && current->RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            prev = current;
            current = current->next;
        }

        // If the node is not the first in the list, update its previous node's next pointer
        if (prev != NULL) {
            prev->next = current;
        } else {
            list->head = current;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

// Function to update a node in the list
static void updateNode(struct NFAPIDataList *list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, bool CRCFLAG) {
    struct NFAPIData *node = NULL;

    // Find the node with the specified RX_UE_INFORMATION_TAG
    pthread_mutex_lock(&list->mutex);
    struct NFAPIData *current = list->head;
    while (current != NULL) {
        if (current->RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            node = current;
            break;
        }
        current = current->next;
    }

    // If the node was found, update its fields
    if (node != NULL) {
        node->RNTI = RNTI;
        node->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
        node->CRCFLAG = CRCFLAG;
    }
    pthread_mutex_unlock(&list->mutex);
}

// Function to query the number of unique RNTIs in the list
static int getNumRNTIs(struct NFAPIDataList *list) {
    int numRNTIs = 0;

    // Count the number of unique RNTIs in the list
    pthread_mutex_lock(&list->mutex);
    struct NFAPIData *current = list->head;
    while (current != NULL) {
        if (current->RNTI != 0) {
            numRNTIs++;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);

    return numRNTIs;
}
