    mac_hash_table_t* mac_hash_table = calloc(1, sizeof(mac_hash_table_t));
    if (interfaces == NULL || mac_hash_table == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize the statistics structure
    stats->total_interfaces = 0;
    stats->total_packets = 0;
    stats->total_bytes = 0;

    // Set up periodic statistics collection and reporting
    pthread_t statistics_thread;
    pthread_create(&statistics_thread, NULL, collect_statistics, (void*)stats);

    // Handle concurrent access from multiple threads
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t condition = PTHREAD_COND_INITIALIZER;

