            return;
        }

        // Generate a random MAC address and insert the interface into the hash table
        unsigned char mac[6];
        for (int i = 0; i < 6; i++) {
            mac[i] = rand() % 255;
        }
        int index = add_interface(mac, buffer, payload_size);
        if (index == -1) {
            printf("Error: unable to add interface\n");
            return;
        }

        // Update the statistics structure
        pthread_mutex_lock(&mutex);
        stats->total_interfaces++;
        stats->total_packets++;
        stats->total_bytes += payload_size;
        pthread_cond_broadcast(&condition);
        pthread_mutex_unlock(&mutex);
    }
}

// Add an interface to the hash table and return its index
int add_interface(unsigned char mac[6], void* buffer, int payload_size) {
    // Check if the hash table is full
    if (mac_hash_table.size >= MAX_INTERFACES) {
        printf("Error: hash table is full\n");
        return -1;
    }

    // Find an empty slot in the hash table and insert the interface
