        .checksum = calculate_checksum(buffer, payload_size),
        .buffer = buffer
    };
    mac_hash_table.size++;
    return index;
}

// Find an empty slot in the hash table and return its index
int find_empty_slot() {
    for (int i = 0; i < MAX_INTERFACES; i++) {
        if (mac_hash_table.interfaces[i] == NULL) {
            return i;
        }
    }
