#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    long offset;
    int key;
    double precision;
} record_t;

// Define the hash table data structure
typedef struct {
    int size; // number of buckets in the table
    int capacity; // maximum number of records that can be stored in the table
    pthread_mutex_t* mutexes; // array of mutexes for each bucket
    record_t** records; // array of pointers to records
} hash_table_t;

// Function to generate random values within a specified range
long rand_range(long min, long max) {
    return (long)(min + ((double)rand() / RAND_MAX) * (max - min));
}

// Function to initialize the hash table with a given capacity and size
int init_hash_table(hash_table_t* table, int capacity, int size) {
    // Check if the capacity and size are valid
    if (capacity <= 0 || size <= 0) {
        return -1;
    }

    // Allocate memory for the mutexes and records
    table->mutexes = (pthread_mutex_t*)malloc(sizeof(pthread_mutex_t) * size);
    table->records = (record_t**)malloc(sizeof(record_t*) * capacity);
    if (!table->mutexes || !table->records) {
        return -1;
    }

    // Initialize the mutexes and records
    for (int i = 0; i < size; i++) {
        pthread_mutex_init(&table->mutexes[i], NULL);
        table->records[i] = NULL;
    }

    // Set the capacity and size of the hash table
    table->capacity = capacity;
    table->size = size;

    return 0;
}

// Function to add a record to the hash table
int add_record(hash_table_t* table, long offset, int key, double precision) {
    // Check if the table is empty or the key already exists in the table
    if (table->records[key] != NULL || table->size == 0) {
        return -1;
    }

    // Find an empty bucket to store the record
    int i = 0;
    while (i < table->capacity && table->records[i] != NULL) {
        i++;
    }

    // If all buckets are full, return -1
    if (i == table->capacity) {
        return -1;
    }

    // Allocate memory for the new record and initialize it
    record_t* new_record = (record_t*)malloc(sizeof(record_t));
    if (!new_record) {
        return -1;
    }
    new_record->offset = offset;
    new_record->key = key;
    new_record->precision = precision;

    // Lock the mutex for the bucket and add the record to it
    pthread_mutex_lock(&table->mutexes[i]);
    table->records[i] = new_record;
    pthread_mutex_unlock(&table->mutexes[i]);

    return 0;
}

// Function to remove a record from the hash table
int remove_record(hash_table_t* table, int key) {
    // Check if the key exists in the table
    if (table->records[key] == NULL) {
        return -1;
    }

    // Find the bucket containing the record and lock the mutex for it
    int i = 0;
    while (i < table->capacity && table->records[i] != NULL && table->records[i]->key != key) {
        i++;
    }
    pthread_mutex_lock(&table->mutexes[i]);

    // If the record is not found, return -1
    if (i == table->capacity || table->records[i] == NULL || table->records[i]->key != key) {
        pthread_mutex_unlock(&table->mutexes[i]);
        return -1;
    }

    // Free the record and set its pointer to NULL in the bucket
    free(table->records[i]);
    table->records[i] = NULL;

    pthread_mutex_unlock(&table->mutexes[i]);

    return 0;
}

// Function to find a record in the hash table by its key
record_t* find_record(hash_table_t* table, int key) {
    // Check if the key exists in the table
    if (table->records[key] == NULL) {
        return NULL;
    }

    // Find the bucket containing the record and lock the mutex for it
    int i = 0;
    while (i < table->capacity && table->records[i] != NULL && table->records[i]->key != key) {
        i++;
    }
    pthread_mutex_lock(&table->mutexes[i]);

    // If the record is not found, return NULL
    if (i == table->capacity || table->records[i] == NULL || table->records[i]->key != key) {
        pthread_mutex_unlock(&table->mutexes[i]);
        return NULL;
    }

    // Return a copy of the found record
    record_t* result = (record_t*)malloc(sizeof(record_t));
    result->offset = table->records[i]->offset;
    result->key = table->records[i]->key;
    result->precision = table->records[i]->precision;

    pthread_mutex_unlock(&table->mutexes[i]);

    return result;
}

// Function to handle memory allocation failures gracefully
void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}

// Function to handle memory deallocation failures gracefully
void safe_free(void* ptr) {
    free(ptr);
    if (ptr == NULL) {
        fprintf(stderr, "Memory deallocation failed\n");
        exit(1);
    }
}
