typedef struct node {
    double value;
    enum status {AVAILABLE, UNAVAILABLE};
    struct node* next;
} node_t;

node_t* createNode(double val) {
    node_t* new_node = (node_t*) malloc(sizeof(node_t));
    new_node->value = val;
    new_node->status = AVAILABLE;
    new_node->next = NULL;
    return new_node;
}

void addNode(node_t* head, double val) {
    node_t* current = head;
    while (current->next != NULL) {
        current = current->next;
    }
    node_t* new_node = createNode(val);
    current->next = new_node;
}

void deleteNode(node_t* node) {
    free(node);
}

