#include <stdlib.h>
#include <stdio.h>
#include <time.h>

// Define the structure for storing composite measurements
typedef struct {
    double value;
    char key[256];
    struct point coordinates;
    struct sensor metadata;
} composite_measurement;

// Define the hash table implementation to be used
#include <unordered_map>
using namespace std;
unordered_map<string, composite_measurement*> measurements;

// Define a function for inserting a new measurement record into the hash table
void insertMeasurement(char* key, double value, struct point coordinates, struct sensor metadata) {
    // Generate random values within the specified range
    srand(time(NULL));
    value = (double) rand() / RAND_MAX * 10.0;

    // Allocate memory for the new measurement record
    composite_measurement* newMeasurement = malloc(sizeof(composite_measurement));
    newMeasurement->value = value;
    strcpy(newMeasurement->key, key);
    newMeasurement->coordinates = coordinates;
    newMeasurement->metadata = metadata;

    // Insert the new measurement record into the hash table
    measurements[newMeasurement->key] = newMeasurement;
}

// Define a function for retrieving the most recent N composite measurement records
composite_measurement* getRecentMeasurements(int N) {
    // Create an array to store the most recent N measurements
    composite_measurement* recentMeasurements = malloc(sizeof(composite_measurement*) * N);

    // Iterate over the hash table and retrieve the most recent N measurements
    int i = 0;
    for (unordered_map<string, composite_measurement*>::iterator it = measurements.begin(); it != measurements.end(); ++it) {
        if (i < N) {
            recentMeasurements[i] = *(it->second);
            i++;
        } else {
            break;
        }
    }

    // Return the most recent N measurement records
    return recentMeasurements;
}

// Define a function for deleting an existing measurement record from the hash table
void deleteMeasurement(char* key) {
    // Remove the measurement record from the hash table
    measurements.erase(key);
}

// Main function for demonstrating the use of the composite measurement storage and retrieval functionality
int main() {
    // Insert some sample measurement records into the hash table
    insertMeasurement("A", 10.0, (struct point) {1, 2}, (struct sensor) {"Sensor A"});
    insertMeasurement("B", 15.0, (struct point) {3, 4}, (struct sensor) {"Sensor B"});
    insertMeasurement("C", 20.0, (struct point) {5, 6}, (struct sensor) {"Sensor C"});

    // Retrieve the most recent N measurement records from the hash table
    composite_measurement* recentMeasurements = getRecentMeasurements(3);

    // Print out the retrieved measurements
    for (int i = 0; i < 3; i++) {
        printf("Key: %s, Value: %.2f, Coordinates: (%d, %d), Metadata: %s\n", recentMeasurements[i].key, recentMeasurements[i].value, recentMeasurements[i].coordinates.x, recentMeasurements[i].coordinates.y, recentMeasurements[i].metadata.name);
    }

    // Delete one of the measurement records from the hash table
    deleteMeasurement("B");

    // Print out the updated measurements
    recentMeasurements = getRecentMeasurements(3);
    for (int i = 0; i < 3; i++) {
        printf("Key: %s, Value: %.2f, Coordinates: (%d, %d), Metadata: %s\n", recentMeasurements[i].key, recentMeasurements[i].value, recentMeasurements[i].coordinates.x, recentMeasurements[i].coordinates.y, recentMeasurements[i].metadata.name);
    }

    return 0;
}
