    NFAPI_CRC_INDICATION_PDU_T *packets[MAX_PACKETS];
} PACKET_LIST;

// Initialize a new packet list with a specified capacity
PACKET_LIST initPacketList(size_t capacity) {
    if (capacity > MAX_PACKETS) {
        // Gracefully degrade performance by dropping older entries or throttling incoming packets
        fprintf(stderr, "Invalid capacity: %zu. Maximum allowed: %d.\n", capacity, MAX_PACKETS);
        return (PACKET_LIST){0};
    }
    PACKET_LIST list;
    list.capacity = capacity;
    list.size = 0;
    // Initialize the packets array with NULL pointers
    for (int i = 0; i < MAX_PACKETS; i++) {
        list.packets[i] = NULL;
    }
    return list;
}

// Add a new packet to the list, ensuring uniqueness by RNTI and avoiding duplicates
void addPacket(PACKET_LIST *list, NFAPI_CRC_INDICATION_PDU_T packet) {
