// Dynamic array of NIC statistics structures
static NICStatistics **nicStatsArray = NULL;
static size_t nicStatsArraySize = 0; // current size of the dynamic array

// Lock for thread-safe access to the dynamic array
static pthread_mutex_t nicStatsMutex = PTHREAD_MUTEX_INITIALIZER;

// Memory allocation and deallocation functions
void *nicStatsAlloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        syslog(LOG_ERR, "Failed to allocate memory for NIC statistics");
        return NULL;
    }
    return ptr;
}

void nicStatsFree(void *ptr) {
    free(ptr);
}

// Initialization function for the dynamic array of NIC statistics structures
int initializeNicStats() {
    // Acquire lock on the mutex to avoid concurrent access
    pthread_mutex_lock(&nicStatsMutex);

    // Allocate memory for the dynamic array of NIC statistics structures
    nicStatsArray = (NICStatistics **)nicStatsAlloc(sizeof(NICStatistics *) * nicStatsArraySize);
    if (!nicStatsArray) {
        syslog(LOG_ERR, "Failed to allocate memory for NIC statistics dynamic array");
        pthread_mutex_unlock(&nicStatsMutex);
        return -1;
    }

    // Initialize each element in the dynamic array with a new NIC statistics structure
    for (size_t i = 0; i < nicStatsArraySize; i++) {
        nicStatsArray[i] = (NICStatistics *)nicStatsAlloc(sizeof(NICStatistics));
        if (!nicStatsArray[i]) {
            syslog(LOG_ERR, "Failed to allocate memory for NIC statistics structure");
            pthread_mutex_unlock(&nicStatsMutex);
            return -1;
        }
    }

    // Initialize the MAC header and IP packet fields in each NIC statistics structure
    for (size_t i = 0; i < nicStatsArraySize; i++) {
        nicStatsArray[i]->macHeader = (MAC_HEADER *)nicStatsAlloc(sizeof(MAC_HEADER));
        if (!nicStatsArray[i]->macHeader) {
            syslog(LOG_ERR, "Failed to allocate memory for MAC header");
            pthread_mutex_unlock(&nicStatsMutex);
            return -1;
        }
        nicStatsArray[i]->ipPacket = (IP_PACKET *)nicStatsAlloc(sizeof(IP_PACKET));
        if (!nicStatsArray[i]->ipPacket) {
            syslog(LOG_ERR, "Failed to allocate memory for IP packet");
            pthread_mutex_unlock(&nicStatsMutex);
            return -1;
        }
    }

    // Release lock on the mutex and return success
    pthread_mutex_unlock(&nicStatsMutex);
    return 0;
}

// Deinitialization function for the dynamic array of NIC statistics structures
int deinitializeNicStats() {
    // Acquire lock on the mutex to avoid concurrent access
    pthread_mutex_lock(&nicStatsMutex);

    // Free memory for each element in the dynamic array
    for (size_t i = 0; i < nicStatsArraySize; i++) {
        nicStatsFree(nicStatsArray[i]->macHeader);
        nicStatsFree(nicStatsArray[i]->ipPacket);
        nicStatsFree(nicStatsArray[i]);
    }

    // Free memory for the dynamic array of NIC statistics structures
    nicStatsFree(nicStatsArray);
    nicStatsArray = NULL;

    // Release lock on the mutex and return success
    pthread_mutex_unlock(&nicStatsMutex);
    return 0;
}

// Add a new NIC statistics structure to the dynamic array, growing it if necessary
int addNicStatistics(NICStatistics *newStat) {
    // Acquire lock on the mutex to avoid concurrent access
    pthread_mutex_lock(&nicStatsMutex);

    // Grow the dynamic array of NIC statistics structures if it is full
    if (nicStatsArraySize == nicStatsArray->length) {
        size_t newSize = nicStatsArraySize * 2;
        NICStatistics **newNicStatsArray = (NICStatistics **)nicStatsAlloc(sizeof(NICStatistics *) * newSize);
        if (!newNicStatsArray) {
            syslog(LOG_ERR, "Failed to allocate memory for NIC statistics dynamic array");
            pthread_mutex_unlock(&nicStatsMutex);
            return -1;
        }
        memcpy(newNicStatsArray, nicStatsArray, sizeof(NICStatistics *) * nicStatsArraySize);
        nicStatsFree(nicStatsArray);
        nicStatsArray = newNicStatsArray;
    }

    // Add the new NIC statistics structure to the dynamic array
    nicStatsArray[nicStatsArraySize] = newStat;
    nicStatsArraySize++;

    // Release lock on the mutex and return success
    pthread_mutex_unlock(&nicStatsMutex);
    return 0;
}

// Remove an existing NIC statistics structure from the dynamic array
int removeNicStatistics(size_t index) {
    // Acquire lock on the mutex to avoid concurrent access
    pthread_mutex_lock(&nicStatsMutex);

    // Check if the specified index is out of bounds
    if (index >= nicStatsArraySize) {
        syslog(LOG_ERR, "NIC statistics structure at index %zu does not exist", index);
        pthread_mutex_unlock(&nicStatsMutex);
        return -1;
    }

    // Free memory for the NIC statistics structure
    nicStatsFree(nicStatsArray[index]);

    // Shift all elements to the left of the specified index one position to the right
    for (size_t i = index; i < nicStatsArraySize - 1; i++) {
        memcpy(&nicStatsArray[i], &nicStatsArray[i + 1], sizeof(NICStatistics));
    }

    // Decrement the size of the dynamic array
    nicStatsArraySize--;

    // Release lock on the mutex and return success
    pthread_mutex_unlock(&nicStatsMutex);
    return 0;
}

// Get a reference to the NIC statistics structure at the specified index
NICStatistics *getNicStatistics(size_t index) {
    // Acquire lock on the mutex to avoid concurrent access
    pthread_mutex_lock(&nicStatsMutex);

