// Function to initialize the cache
void init_message_cache() {
    message_cache = malloc(sizeof(LTE_ENB_APINASRRC_MESSAGE_T) * MAX_ELEMENTS);
}

// Function to add a new message to the cache
int add_message(int UE_ID, int NAS_MESSAGE_TYPE, void* NAS_MESSAGE_PDU, size_t PDU_SIZE) {
    // Acquire the lock on the cache
    pthread_mutex_lock(&cache_lock);

    // Check if the cache is full
    if (message_cache == NULL || message_count >= MAX_ELEMENTS) {
        // Release the lock and return an error
        pthread_mutex_unlock(&cache_lock);
        return -1;
    }

    // Allocate memory for the new message
    LTE_ENB_APINASRRC_MESSAGE_T* new_message = malloc(sizeof(LTE_ENB_APINASRRC_MESSAGE_T));
    if (new_message == NULL) {
        // Release the lock and return an error
        pthread_mutex_unlock(&cache_lock);
        return -1;
    }

    // Initialize the new message
