    new_message->NAS_MESSAGE_TYPE = NAS_MESSAGE_TYPE;
    new_message->NAS_MESSAGE_PDU = NAS_MESSAGE_PDU;
    new_message->PDU_SIZE = PDU_SIZE;

    // Add the new message to the cache
    message_cache[message_count++] = new_message;

    // Release the lock
    pthread_mutex_unlock(&cache_lock);

    return 0;
}

// Function to get a message from the cache
int get_message(int UE_ID, LTE_ENB_APINASRRC_MESSAGE_T* message) {
    // Acquire the lock on the cache
    pthread_mutex_lock(&cache_lock);

    // Check if the cache is empty
    if (message_count == 0) {
        // Release the lock and return an error
        pthread_mutex_unlock(&cache_lock);
        return -1;
    }

    // Find the message with the matching UE ID
    int i = 0;
    for (i = 0; i < message_count; i++) {
        if (message_cache[i]->UE_ID == UE_ID) {
            break;
        }
    }

    // Check if the message was found
    if (i >= message_count) {
        // Release the lock and return an error
        pthread_mutex_unlock(&cache_lock);
        return -1;
    }

    // Update the message pointer
    *message = message_cache[i];

    // Remove the message from the cache
    message_count--;
    if (i < message_count) {
        memcpy(&message_cache[i], &message_cache[message_count], sizeof(LTE_ENB_APINASRRC_MESSAGE_T));
    }

    // Release the lock
    pthread_mutex_unlock(&cache_lock);

    return 0;
}

// Function to release a message from the cache
int release_message(LTE_ENB_APINASRRC_MESSAGE_T* message) {
    // Acquire the lock on the cache
    pthread_mutex_lock(&cache_lock);

    // Check if the cache is empty
    if (message_count == 0) {
        // Release the lock and return an error
        pthread_mutex_unlock(&cache_lock);
        return -1;
    }

    // Find the message in the cache
    int i = 0;
    for (i = 0; i < message_count; i++) {
        if (message_cache[i] == message) {
            break;
        }
    }

    // Check if the message was found
    if (i >= message_count) {
        // Release the lock and return an error
        pthread_mutex_unlock(&cache_lock);
        return -1;
    }

    // Remove the message from the cache
    message_count--;
    if (i < message_count) {
        memcpy(&message_cache[i], &message_cache[message_count], sizeof(LTE_ENB_APINASRRC_MESSAGE_T));
    }

    // Release the lock
    pthread_mutex_unlock(&cache_lock);

    return 0;
}
