// Function to create and populate a list of structures
void create_and_populate_crc_list(int N, char* bg_cmd) {
    // Allocate memory for the list of structures
    struct crc *crc_list = malloc(N * sizeof(struct crc));
    if (!crc_list) {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Populate the list of structures with data from the input file
    FILE *input_file = fopen("input.txt", "r");
    if (!input_file) {
        fprintf(stderr, "Error opening input file: %s\n", strerror(errno));
        free(crc_list);
        exit(EXIT_FAILURE);
    }

    int i;
    for (i = 0; i < N; ++i) {
        // Read the data from the input file
        fscanf(input_file, "%d %s", &crc_list[i].key, crc_list[i].value);
    }

    // Close the input file
    fclose(input_file);

    // Execute the background command if specified
    if (bg_cmd) {
        pid_t pid = fork();
        if (pid == 0) {
            // Child process: execute the background command
            system(bg_cmd);
            exit(EXIT_SUCCESS);
        } else if (pid < 0) {
            fprintf(stderr, "Error forking child process: %s\n", strerror(errno));
            free(crc_list);
            exit(EXIT_FAILURE);
        }
    }

    // Free the memory allocated for the list of structures
    free(crc_list);
}
