def file_manager(request):
  # Parse the request body and extract the required information
  id = request.get("id")
  filename = request.get("filename")
  file_size = request.get("file_size")
  access_timestamp = request.get("access_timestamp")

  # Validate the input data
  if (id != None and not isinstance(id, str)):
    return "Invalid ID", 400
  elif (filename != None and not isinstance(filename, str)):
    return "Invalid filename", 400
  elif (file_size != None and not isinstance(file_size, int)):
    return "Invalid file size", 400
  elif (access_timestamp != None and not isinstance(access_timestamp, int)):
