      file_manager.conn.commit()
      return "File created successfully", 201
    else:
      return "Invalid ID", 400
  elif (request.method == "PUT"):
    # Update an existing file metadata structure in the database
    if (id != None and id.isdigit()):
      update_file = {
        "filename": filename,
        "file_size": file_size,
        "access_timestamp": access_timestamp
      }
      cursor = file_manager.conn.cursor()
      cursor.execute("UPDATE files SET filename=%s, file_size=%s, access_timestamp=%s WHERE id=%s", update_file["filename"], update_file["file_size"], update_file["access_timestamp"], int(id))
      file_manager.conn.commit()
      return "File updated successfully", 201
    else:
      return "Invalid ID", 400
  elif (request.method == "DELETE"):
    # Delete an existing file metadata structure from the database
    if (id != None and id.isdigit()):
      cursor = file_manager.conn.cursor()
      cursor.execute("DELETE FROM files WHERE id=%s", int(id))
      file_manager.conn.commit()
      return "File deleted successfully", 201
    else:
      return "Invalid ID", 400
  else:
    # Return an error message if the request method is not supported
    return "Unsupported request method", 405
