// Function to merge sorted free blocks in a custom memory pool
static void mergeSortedFreeBlocks(memPool_t *memPool) {
    // Iterate over the list of free blocks and merge them into a single block
    while (memPool->numFreeBlocks > 1) {
        int i = 0;
        while (i < memPool->numFreeBlocks - 1) {
            if (memPool->freeBlocks[i].start + memPool->freeBlocks[i].size >= memPool->freeBlocks[i + 1].start) {
                // Merge the two free blocks into a single block
                int size = memPool->freeBlocks[i].size + memPool->freeBlocks[i + 1].size;
                memPool->freeBlocks[i] = (memPool_t *)malloc(sizeof(memPool_t));
                memPool->freeBlocks[i]->start = memPool->freeBlocks[i].start;
                memPool->freeBlocks[i]->size = size;
                memPool->numFreeBlocks--;
            } else {
                i++;
            }
        }
    }
