        uint16_t tag = json_integer_value(json_object_get(rxEntry, "tag"));
        crcFlag = json_boolean_value(json_object_get(rxEntry, "crcFlag"));

        // Create a new PDU structure and populate it with the extracted information
        crc_pdu_t *newPdu = &pduCache[i % MAX_PDU_CACHE];
        newPdu->pdu.rx_ue_information.rnti = rnti;
        newPdu->pdu.rx_ue_information.tag = tag;
