            printf("Error: Failed to encrypt the CRC indication PDU\n");
            return -1;
        }
    }

    // Release the cipher context and JSON parser resources
    EVP_CIPHER_CTX_free(ctx);
    json_decref(json);

    return 0;
}

// Define the function to handle errors during PDU creation and population
