#define NFAPI_CRC_INDICATIONS_COUNT 1024
#define NFAPI_MAX_LOG_SIZE 1024 * 1024
#define NFAPI_COMMAND_TIMEOUT 5

struct NFAPI_CRC_INDICATION_PDU {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
};

struct NFAPI_CRC_INDICATION_LIST {
    struct NFAPI_CRC_INDICATION_PDU *pdu;
    size_t count;
    size_t capacity;
};

void process_nfaapi_and_execute_command(int argc, char **argv) {
    // Initialize variables
    int i;
    struct NFAPI_CRC_INDICATION_LIST *list = NULL;
    pid_t child_pid = -1;
    sem_t sem;

    // Validate command-line arguments
    if (argc != 5) {
        printf("Usage: %s <NFAPI_CRC_INDICATIONS_COUNT> <command> <log_file> <timeout>\n", argv[0]);
        return;
    }
    int nfaapi_count = atoi(argv[1]);
    char *command = argv[2];
    char *log_file = argv[3];
    int timeout = atoi(argv[4]);

    // Create the list of structures
    list = calloc(nfaapi_count, sizeof(*list));
    if (list == NULL) {
        printf("Failed to allocate memory for NFAPI CRC Indication list\n");
        return;
    }
    list->pdu = calloc(nfaapi_count, sizeof(**list));
    if (list->pdu == NULL) {
        printf("Failed to allocate memory for NFAPI CRC Indication structures\n");
        free(list);
        return;
    }
    list->capacity = nfaapi_count;

    // Populate the list with at least NFAPI_CRC_INDICATIONS_COUNT structures
    for (i = 0; i < nfaapi_count; ++i) {
        list->pdu[i].RX_UE_INFORMATION_TAG = rand();
        list->pdu[i].RNTI = rand();
        list->pdu[i].CRC_INDICATION_REL8_TAG = rand();
        list->pdu[i].CRCFLAG = rand() % 2;
    }

    // Execute the specified command asynchronously in the background
    child_pid = fork();
    if (child_pid == -1) {
        printf("Failed to create a new process: %s\n", strerror(errno));
        free(list->pdu);
        free(list);
        return;
    } else if (child_pid == 0) {
        // In the child process, execute the command and log any discrepancies
        FILE *log = fopen(log_file, "w");
        if (log == NULL) {
            printf("Failed to open log file: %s\n", strerror(errno));
            exit(1);
        }
        for (i = 0; i < list->count; ++i) {
            struct NFAPI_CRC_INDICATION_PDU *pdu = &list->pdu[i];
            if (pdu->CRCFLAG != ((pdu->RX_UE_INFORMATION_TAG + pdu->RNTI) % 2)) {
                fprintf(log, "Discrepancy in CRCFLAG: expected %d, got %d\n", pdu->CRCFLAG, (pdu->RX_UE_INFORMATION_TAG + pdu->RNTI) % 2);
            }
        }
        fclose(log);
        exit(0);
    } else {
        // In the parent process, wait for the child to finish or time out
        if (sem_init(&sem, 0, 0) == -1) {
            printf("Failed to initialize semaphore: %s\n", strerror(errno));
            free(list->pdu);
            free(list);
            return;
        }
        if (waitpid(child_pid, NULL, WNOHANG | WUNTRACED) == -1) {
            printf("Failed to wait for child process: %s\n", strerror(errno));
            sem_destroy(&sem);
            free(list->pdu);
            free(list);
            return;
        }
        struct timespec ts = {timeout, 0};
        if (sem_timedwait(&sem, &ts) == -1) {
            printf("Timeout while waiting for child process: %s\n", strerror(errno));
            kill(child_pid, SIGKILL);
            sem_destroy(&sem);
            free(list->pdu);
            free(list);
            return;
        }
        if (waitpid(child_pid, NULL, WNOHANG | WUNTRACED) == -1) {
            printf("Failed to wait for child process: %s\n", strerror(errno));
            sem_destroy(&sem);
            free(list->pdu);
            free(list);
            return;
        } else if (WIFSIGNALED(waitpid(child_pid, NULL, WNOHANG | WUNTRACED))) {
            printf("Child process terminated with signal %d\n", WTERMSIG(waitpid(child_pid, NULL, WNOHANG | WUNTRACED)));
        } else if (WIFEXITED(waitpid(child_pid, NULL, WNOHANG | WUNTRACED))) {
            int status = WEXITSTATUS(waitpid(child_pid, NULL, WNOHANG | WUNTRACED));
            printf("Child process exited with code %d\n", status);
        }
        sem_destroy(&sem);
    }

    // Free the memory allocated for the list of structures
    free(list->pdu);
    free(list);
}']

