// Dynamic array of MAC_Transmission_T structures
typedef struct {
    MAC_PDU_Header header; // Preamble type, sequence number, transmission mode
    MAC_Scheduler_T scheduler; // Timestamped timestamp and list of RB_GRANT_T elements
} MAC_Transmission_T;

// Initialize dynamic array with given size
void init_mac_transmissions(int size) {
    int i;
    for (i = 0; i < size; i++) {
        mac_transmissions[i].header.preamble_type = INVALID_PREAMBLE;
        mac_transmissions[i].header.sequence_number = INVALID_SEQUENCE;
        mac_transmissions[i].header.transmission_mode = INVALID_TRANSMISSION;
        mac_transmissions[i].scheduler.timestamp = 0;
    }
}

// Add a MAC_Scheduler_T element to the dynamic array with given timestamp and RB_GRANT_T elements
void add_mac_transmission(MAC_Scheduler_T scheduler, int timestamp, int num_rb_grants) {
    // Check if there is enough space in the dynamic array for the new transmission
    if (num_mac_transmissions < MAX_NUM_MAC_TRANSMISSIONS) {
        mac_transmissions[num_mac_transmissions].scheduler = scheduler;
        mac_transmissions[num_mac_transmissions].timestamp = timestamp;
        int i;
        for (i = 0; i < num_rb_grants; i++) {
            // Add RB_GRANT_T elements to the dynamic array
            mac_transmissions[num_mac_transmissions].scheduler.rb_grants[i] = rb_grants[i];
        }
        num_mac_transmissions++;
    } else {
        // If there is not enough space in the dynamic array, remove the oldest transmission and add the new one
        mac_transmissions[0] = mac_transmissions[num_mac_transmissions - 1];
        num_mac_transmissions--;
        add_mac_transmission(scheduler, timestamp, num_rb_grants);
    }
}

// Retrieve a MAC_Transmission_T structure from the dynamic array with given sequence number
MAC_Transmission_T* get_mac_transmission(int sequence_number) {
    int i;
    for (i = 0; i < num_mac_transmissions; i++) {
        if (mac_transmissions[i].header.sequence_number == sequence_number) {
            return &mac_transmissions[i];
        }
    }
    return NULL; // If the sequence number is not found, return NULL
}

// Retrieve a RB_GRANT_T element from the dynamic array with given grant ID
RB_GRANT_T* get_rb_grant(int grant_id) {
    int i;
    for (i = 0; i < num_mac_transmissions; i++) {
        if (mac_transmissions[i].scheduler.num_rb_grants > 0) {
            RB_GRANT_T* grant = &mac_transmissions[i].scheduler.rb_grants[grant_id];
            if (grant->id == grant_id) {
                return grant;
            }
        }
    }
    return NULL; // If the grant ID is not found, return NULL
}
