struct OffsetArray {
    size_t length;
    long* values;
};

struct KeyArray {
    size_t length;
    int* values;
};

// Define the function to dynamically allocate memory for and initialize the arrays
void initArrays(size_t offsetSize, size_t keySize) {
    // Allocate memory for the offset array
    OffsetArray* offsets = (OffsetArray*)malloc(sizeof(OffsetArray));
    offsets->length = offsetSize;
    offsets->values = (long*)malloc(offsetSize * sizeof(long));

    // Initialize the offset values to 0
    for (int i = 0; i < offsetSize; i++) {
        offsets->values[i] = 0;
    }

    // Allocate memory for the key array
    KeyArray* keys = (KeyArray*)malloc(sizeof(KeyArray));
    keys->length = keySize;
    keys->values = (int*)malloc(keySize * sizeof(int));

    // Initialize the key values to 0
    for (int i = 0; i < keySize; i++) {
        keys->values[i] = 0;
    }
}

// Define the function to set the value of each record's int field to a random value within a specified range
void setRandomValues(OffsetArray* offsets, KeyArray* keys, int minValue, int maxValue) {
    // Generate random numbers for the offset and key arrays
    for (int i = 0; i < offsets->length; i++) {
        offsets->values[i] = rand() % (maxValue - minValue + 1) + minValue;
    }

    for (int i = 0; i < keys->length; i++) {
        keys->values[i] = rand() % (maxValue - minValue + 1) + minValue;
    }
}

// Define the sorting function to sort the records based on their key values in ascending order
void sortRecords(OffsetArray* offsets, KeyArray* keys) {
    // Sort the records based on their key values in ascending order
    for (int i = 0; i < offsets->length - 1; i++) {
        for (int j = i + 1; j < offsets->length; j++) {
            if (keys->values[i] > keys->values[j]) {
                // Swap the values of the two records
                int tempKey = keys->values[i];
                long tempOffset = offsets->values[i];

                keys->values[i] = keys->values[j];
                offsets->values[i] = offsets->values[j];

                keys->values[j] = tempKey;
                offsets->values[j] = tempOffset;
            }
        }
    }
}

// Define the function to save the sorted records to a file
void saveRecordsToFile(OffsetArray* offsets, KeyArray* keys) {
    // Open the output file in write mode
    FILE* outputFile = fopen("output.txt", "w");

    if (outputFile == NULL) {
        printf("Error opening output file\n");
        return;
    }

    // Write the sorted records to the output file
    for (int i = 0; i < offsets->length; i++) {
        fprintf(outputFile, "%d %ld\n", keys->values[i], offsets->values[i]);
    }

    // Close the output file
    fclose(outputFile);
}

// Define the function to ensure that the total memory usage does not exceed a specified limit
void checkMemoryUsage(size_t maxMemoryLimit) {
    // Calculate the current memory usage
    size_t currentMemoryUsage = 0;

    for (int i = 0; i < offsets->length; i++) {
        currentMemoryUsage += sizeof(long) * offsets->values[i];
    }

    for (int i = 0; i < keys->length; i++) {
        currentMemoryUsage += sizeof(int) * keys->values[i];
    }

    // Check if the current memory usage exceeds the maximum limit
    if (currentMemoryUsage > maxMemoryLimit) {
        printf("Error: Memory usage exceeded the specified limit\n");
        return;
    }
}

// Define the function to optimize the memory allocations and deallocations during execution
void optimizeMemoryAllocation(size_t offsetSize, size_t keySize) {
    // Allocate memory for the offset array in a single contiguous block
    OffsetArray* offsets = (OffsetArray*)malloc(sizeof(OffsetArray));

    // Initialize the offset values to 0
    for (int i = 0; i < offsets->length; i++) {
        offsets->values[i] = 0;
    }

    // Allocate memory for the key array in a single contiguous block
    KeyArray* keys = (KeyArray*)malloc(sizeof(KeyArray));

    // Initialize the key values to 0
    for (int i = 0; i < keys->length; i++) {
        keys->values[i] = 0;
    }
}

// Define the function to handle errors during execution
void errorHandler(OffsetArray* offsets, KeyArray* keys) {
    // Print an error message if memory allocation fails
    if (offsets == NULL || keys == NULL) {
        printf("Error: Memory allocation failed\n");
        return;
    }

    // Check for any errors in the sorting algorithm
