    uint16_t SRI;
    uint8_t MAC_PDU_TYPE;
    uint32_t sequenceNumber;
} MAC_PACKET_INFO_T;

void initializeAndPopulateMACPacketInfo(MAC_PACKET_INFO_T** packetArray, int* packetCount) {
    // Allocate memory for the dynamic array of MAC_PACKET_INFO_T structures
    *packetArray = (MAC_PACKET_INFO_T*)malloc(*packetCount * sizeof(MAC_PACKET_INFO_T));

    // Initialize each structure with a unique PDUSESSIONID, SRI, and MAC_PDU_TYPE
    for (int i = 0; i < *packetCount; i++) {
        (*packetArray)[i].PDUSESSIONID = rand();
        (*packetArray)[i].SRI = rand() % 65535;
        (*packetArray)[i].MAC_PDU_TYPE = (rand() & 0xFF);
        (*packetArray)[i].sequenceNumber = i;
    }
}

void trackPacketAge(MAC_PACKET_INFO_T* packet, int ageThreshold) {
    // Calculate the age of the packet in milliseconds
    double currentTime = (double)(clock() * 1000 / CLOCKS_PER_SEC);
    double packetAge = currentTime - packet->sequenceNumber;

    // If the packet is older than the threshold, set its status to "stale"
    if (packetAge > ageThreshold) {
        packet->status = "stale";
    } else {
        packet->status = "fresh";
    }
}

void handlePacket(MAC_PACKET_INFO_T* packet, int* packetCount) {
    // If the array is full, resize it to accommodate more packets
    if (*packetCount >= *packetArray->size) {
        *packetArray = (MAC_PACKET_INFO_T*)realloc(*packetArray, (*packetArray->size * 2) * sizeof(MAC_PACKET_INFO_T));
    }

    // Add the new packet to the array
    (*packetArray)[*packetCount] = *packet;
    (*packetCount)++;
}

void processPackets(MAC_PACKET_INFO_T** packetArray, int* packetCount, int ageThreshold) {
    // Iterate over the array of packets and track their age
    for (int i = 0; i < *packetCount; i++) {
        MAC_PACKET_INFO_T* packet = &(*packetArray)[i];
        trackPacketAge(packet, ageThreshold);
    }

    // Iterate over the array of packets and handle each one
    for (int i = 0; i < *packetCount; i++) {
        MAC_PACKET_INFO_T* packet = &(*packetArray)[i];
        if (packet->status == "fresh") {
            handlePacket(packet, packetCount);
        }
    }
}
