// Dynamic array of NIC statistics structures
nic_stats* nic_array = NULL;
size_t nic_array_size = 0;
size_t nic_array_capacity = 0;

// Global payload size limit to prevent excessive memory consumption
size_t global_payload_limit = 1024 * 1024; // 1 MB

// Function to initialize the dynamic array of NIC statistics structures
void init_nic_array(int num_interfaces, int mtu_sizes[], int payload_limit) {
    nic_array_size = num_interfaces;
    nic_array_capacity = nic_array_size + 1024; // Additional capacity for dynamic growth
    nic_array = malloc(sizeof(nic_stats) * nic_array_capacity);
    memset(nic_array, 0, sizeof(nic_stats) * nic_array_capacity);
    global_payload_limit = payload_limit;
}

// Function to insert a new NIC statistics structure into the dynamic array
void add_nic_statistics(int interface_index, uint8_t mac[6], int mtu) {
    if (interface_index >= nic_array_size || interface_index < 0) {
        // Check for invalid index
        return;
    }
    nic_stats* new_nic = &(nic_array[interface_index]);
    memcpy(new_nic->mac, mac, 6);
    int payload_size = (rand() % (global_payload_limit - mtu)) + mtu; // Randomly generate payload size between MTU and global limit
    new_nic->ip_packet[0] = 0x45; // Set IP header version and header length
    new_nic->ip_packet[1] = 0x00;
    new_nic->ip_packet[2] = 0x00;
    new_nic->ip_packet[3] = 0x80 + (payload_size / 4); // Set total length field to payload size plus IP header length
    new_nic->ip_packet[4] = 0x00;
    new_nic->ip_packet[5] = 0x06;
    uint16_t checksum = calculate_checksum(new_nic->ip_packet, sizeof(new_nic->ip_packet)); // Calculate IP packet checksum
    memcpy(&(new_nic->ip_packet[8]), &checksum, 2); // Store checksum in the appropriate field of the IP header
    for (int i = 0; i < payload_size; i++) {
        new_nic->ip_packet[i + 12] = rand() % 256; // Randomly generate payload data
    }
}

// Function to calculate the checksum of an IP packet
uint16_t calculate_checksum(uint8_t* packet, int size) {
    uint32_t sum = 0;
    for (int i = 0; i < size; i++) {
        sum += packet[i];
    }
    while ((sum >> 16) != 0) {
        sum = (sum & 0xffff) + (sum >> 16);
    }
    return ~(sum & 0xffff);
}

// Function to validate the integrity of an IP packet checksum
bool validate_checksum(uint8_t* packet, int size) {
    uint16_t expected = calculate_checksum(packet, size);
    uint16_t actual = *((uint16_t*) &(packet[8]));
    return (expected == actual);
}

// Function to periodically perform consistency checks on the entire data structure
void check_consistency() {
    for (int i = 0; i < nic_array_size; i++) {
        if (!validate_checksum(nic_array[i].ip_packet, sizeof(nic_array[i].ip_packet))) {
            printf("Checksum validation failed for NIC %d\n", i);
        }
    }
}

