#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <syslog.h>

// Structure to represent an LTE UE context
typedef struct {
    uint32_t ue_id;
    uint8_t rrc_state;
    void *mac_context;
} lte_ue_context_t;

// Thread-safe data structure to manage the dynamic list of LTE UE contexts
typedef struct {
    pthread_mutex_t mutex;
    lte_ue_context_t **contexts;
    size_t num_contexts;
} lte_ue_context_list_t;

// Initialize a new LTE UE context list
void lte_ue_context_list_init(lte_ue_context_list_t *list) {
    list->mutex = PTHREAD_MUTEX_INITIALIZER;
    list->num_contexts = 0;
}

// Add a new LTE UE context to the list
void lte_ue_context_add(lte_ue_context_list_t *list, uint32_t ue_id, uint8_t rrc_state, void *mac_context) {
    pthread_mutex_lock(&list->mutex);
    list->num_contexts++;
    lte_ue_context_t **new_contexts = realloc(list->contexts, list->num_contexts * sizeof(lte_ue_context_t *));
    if (new_contexts == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for new LTE UE context");
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    list->contexts = new_contexts;
    lte_ue_context_t *new_context = malloc(sizeof(lte_ue_context_t));
    if (new_context == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for new LTE UE context");
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    list->contexts[list->num_contexts - 1] = new_context;
    new_context->ue_id = ue_id;
    new_context->rrc_state = rrc_state;
    new_context->mac_context = mac_context;
    pthread_mutex_unlock(&list->mutex);
}

// Remove a LTE UE context from the list by its ID
void lte_ue_context_remove(lte_ue_context_list_t *list, uint32_t ue_id) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->num_contexts; i++) {
        if (list->contexts[i]->ue_id == ue_id) {
            free(list->contexts[i]);
            memmove(&list->contexts[i], &list->contexts[i + 1], (list->num_contexts - i - 1) * sizeof(lte_ue_context_t *));
            list->num_contexts--;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

// Update the RRC state of a LTE UE context in the list by its ID
void lte_ue_context_update(lte_ue_context_list_t *list, uint32_t ue_id, uint8_t rrc_state) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->num_contexts; i++) {
        if (list->contexts[i]->ue_id == ue_id) {
            list->contexts[i]->rrc_state = rrc_state;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

// Find a LTE UE context in the list by its ID and return it
lte_ue_context_t *lte_ue_context_find(lte_ue_context_list_t *list, uint32_t ue_id) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->num_contexts; i++) {
        if (list->contexts[i]->ue_id == ue_id) {
            lte_ue_context_t *context = malloc(sizeof(lte_ue_context_t));
            memcpy(context, list->contexts[i], sizeof(lte_ue_context_t));
            pthread_mutex_unlock(&list->mutex);
            return context;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

// Serialize the LTE UE context list to disk in a compact, efficient format
void lte_ue_context_serialize(lte_ue_context_list_t *list, char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        syslog(LOG_ERR, "Failed to open file for serialization: %s", strerror(errno));
        return;
    }
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->num_contexts; i++) {
        fwrite(list->contexts[i], sizeof(lte_ue_context_t), 1, file);
    }
    pthread_mutex_unlock(&list->mutex);
    if (fclose(file) != 0) {
        syslog(LOG_ERR, "Failed to close serialization file: %s", strerror(errno));
    }
}

// Deserialize the LTE UE context list from disk in a compact, efficient format
void lte_ue_context_deserialize(lte_ue_context_list_t *list, char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        syslog(LOG_ERR, "Failed to open file for deserialization: %s", strerror(errno));
        return;
    }
    pthread_mutex_lock(&list->mutex);
    lte_ue_context_t *new_context = NULL;
    while (fread(&new_context, sizeof(lte_ue_context_t), 1, file) == 1) {
        lte_ue_context_add(list, new_context->ue_id, new_context->rrc_state, new_context->mac_address);
    }
    pthread_mutex_unlock(&list->mutex);
    if (fclose(file) != 0) {
        syslog(LOG_ERR, "Failed to close deserialization file: %s", strerror(errno));
    }
}
```

