#define MAX_TRANSACTIONS 10000
#define MEMORY_LIMIT 5000000
#define TRANSACTION_EXPIRATION_SECONDS 3
#define TRANSACTION_WEIGHTED_SUM_THRESHOLD 100

typedef struct {
    char macHeader[6];
    char ipPacket[20];
    int payloadSize;
    int checksum;
} NetworkInterfaceControlStatistics;

int initializeAndFilterNetworkStats(NetworkInterfaceControlStatistics** stats, int numTransactions) {
    // Check if the input is valid
    if (numTransactions <= 0 || numTransactions > MAX_TRANSACTIONS) {
        return -1;
    }

    // Allocate memory for the array of structures
    *stats = (NetworkInterfaceControlStatistics*)malloc(sizeof(NetworkInterfaceControlStatistics) * numTransactions);
    if (*stats == NULL) {
        return -2;
    }

    // Initialize each structure in the array
    int i;
    for (i = 0; i < numTransactions; ++i) {
        NetworkInterfaceControlStatistics* stat = &(*stats)[i];

        // Generate a random MAC header and IP packet
        unsigned char mac[6];
        unsigned char ip[20];
        for (int j = 0; j < 6; ++j) {
            mac[j] = rand() & 0xFF;
        }
        for (int j = 0; j < 20; ++j) {
            ip[j] = rand() & 0xFF;
        }

        // Generate a random payload size and checksum
        int payloadSize = rand() % 1000;
        int checksum = 0;
        for (int j = 0; j < payloadSize; ++j) {
            checksum += rand() & 0xFF;
        }

        // Set the values in the structure
        memcpy(stat->macHeader, mac, 6);
        memcpy(stat->ipPacket, ip, 20);
        stat->payloadSize = payloadSize;
        stat->checksum = checksum;
    }

    // Filter transactions based on age and weighted sum
    int filteredTransactions = 0;
    for (i = 0; i < numTransactions; ++i) {
        NetworkInterfaceControlStatistics* stat = &(*stats)[i];

        // Check if the transaction is older than TRANSACTION_EXPIRATION_SECONDS seconds
        time_t currentTime = time(NULL);
        if (difftime(currentTime, stat->timestamp) > TRANSACTION_EXPIRATION_SECONDS) {
            continue;
        }

        // Check if the transaction's weighted sum is greater than TRANSACTION_WEIGHTED_SUM_THRESHOLD
        int weightedSum = 0;
        for (int j = 0; j < stat->payloadSize; ++j) {
            weightedSum += stat->ipPacket[j];
        }
        if (weightedSum > TRANSACTION_WEIGHTED_SUM_THRESHOLD) {
            continue;
        }

        // Increment the number of filtered transactions
        ++filteredTransactions;
    }

    // Update the metrics and return the maximum weighted sum
    int maxWeightedSum = 0;
    for (i = 0; i < numTransactions - filteredTransactions; ++i) {
        NetworkInterfaceControlStatistics* stat = &(*stats)[i];
        int weightedSum = 0;
        for (int j = 0; j < stat->payloadSize; ++j) {
            weightedSum += stat->ipPacket[j];
        }
        if (weightedSum > maxWeightedSum) {
            maxWeightedSum = weightedSum;
        }
    }

    // Free the unused memory
    for (i = numTransactions - filteredTransactions; i < numTransactions; ++i) {
        NetworkInterfaceControlStatistics* stat = &(*stats)[i];
        free(stat);
    }

    return maxWeightedSum;
}
```
