// Initialize and manage the scalable data processing pipeline
flow_record_t* initialize_pipeline(uint32_t num_records) {
    // Allocate memory for arrays of integers representing packet IDs, session identifiers, and flow metadata
    uint32_t *packet_ids = (uint32_t *)malloc(num_records * sizeof(uint32_t));
    uint16_t *session_ids = (uint16_t *)malloc(num_records * sizeof(uint16_t));
    flow_record_t *flow_metadata = (flow_record_t *)malloc(num_records * sizeof(flow_record_t));

    // Initialize the arrays with random timestamps and byte counts to simulate initial processing states
    for (int i = 0; i < num_records; i++) {
        packet_ids[i] = rand();
        session_ids[i] = rand();
        flow_metadata[i].PACKET_COUNT = rand();
        flow_metadata[i].FLOW_STATE = rand();
    }

    // Create and populate a list of FLOW_ANALYSIS_PDU_T structures containing the valid FLOW_ID, SRC_IP, DST_IP, and PACKET_COUNT fields
    flow_list_t *flows = (flow_list_t *)malloc(sizeof(flow_list_t));
    pthread_mutex_init(&flows->lock, NULL);
    flows->head = NULL;

    for (int i = 0; i < num_records; i++) {
        flow_record_t *flow = &flow_metadata[i];
        FLOW_ANALYSIS_PDU_T *pdu = (FLOW_ANALYSIS_PDU_T *)malloc(sizeof(FLOW_ANALYSIS_PDU_T));
        pdu->FLOW_ID = flow->FLOW_ID;
        pdu->SRC_IP = flow->SRC_IP;
        pdu->DST_IP = flow->DST_IP;
        pdu->PACKET_COUNT = flow->PACKET_COUNT;
        pdu->FLOW_STATE = flow->FLOW_STATE;

        // Add the PDU to the list of flows
        pthread_mutex_lock(&flows->lock);
        if (flows->head == NULL) {
            flows->head = pdu;
        } else {
            pdu->next = flows->head;
            flows->head = pdu;
        }
        pthread_mutex_unlock(&flows->lock);
    }

    // Free the temporary memory allocated for the flow metadata and return a pointer to the first element of the records array
    free(packet_ids);
    free(session_ids);
    free(flow_metadata);
    return flows->head;
}
