// Function to handle dynamic resizing of the metadata array
void resize_metadata(int new_size) {
    // Reallocate memory for the metadata array
    metadata_t *new_metadata = realloc(metadata, sizeof(metadata_t) * new_size);
    assert(new_metadata != NULL);

    // Initialize the new metadata with random values
    for (int i = 0; i < new_size; ++i) {
        new_metadata[i].offset = offsets[i];
        new_metadata[i].key = keys[i];
        new_metadata[i].entry = entries[i];
        pthread_mutex_init(&new_metadata[i].mutex, NULL);
    }
}

// Function to handle memory reclaiming when entries are removed from the data structures
void reclaim_memory(int index) {
    // Acquire lock on the entry and metadata
    pthread_mutex_lock(&entries[index]->mutex);
    pthread_mutex_lock(&metadata[index].mutex);

    // Decrement reference count of the entry
    entries[index]->ref_count--;

    // If the reference count is zero, reclaim memory for the entry and metadata
    if (entries[index]->ref_count == 0) {
        free(entries[index]);
        free(metadata[index].entry);
    }

    // Release locks on the entry and metadata
    pthread_mutex_unlock(&entries[index]->mutex);
    pthread_mutex_unlock(&metadata[index].mutex);
}

// Main function
int main() {
    // Initialize hash table, offsets, keys, entries, and metadata arrays
    int num_buckets = METADATA_ARRAY_SIZE;
    load_factor = 0.75;
    long *offsets = malloc(sizeof(long) * num_buckets);
    int *keys = malloc(sizeof(int) * num_buckets);
    entry_t **entries = malloc(sizeof(entry_t *) * num_buckets);
    metadata_t *metadata = malloc(sizeof(metadata_t) * num_buckets);
    assert(offsets != NULL && keys != NULL && entries != NULL && metadata != NULL);

    // Initialize the offsets, keys, and entries with random values
    for (int i = 0; i < num_buckets; ++i) {
        offsets[i] = rand() % OFFSET_MAX;
        keys[i] = rand() % METADATA_ARRAY_SIZE;
        entries[i] = malloc(sizeof(entry_t));
        assert(entries[i] != NULL);
        entries[i]->str = generate_random_string(rand() % (MAX_STRING_LENGTH + 1));
        entries[i]->num = rand();
        entries[i]->ref_count = 0;
    }

    // Initialize the metadata with random values
    for (int i = 0; i < num_buckets; ++i) {
        metadata[i].offset = offsets[i];
        metadata[i].key = keys[i];
        metadata[i].entry = entries[i];
        pthread_mutex_init(&metadata[i].mutex, NULL);
    }

    // Handle dynamic resizing of the hash table and metadata arrays
