// Define a mutex for synchronizing access to the dynamic array
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the dynamic array and allocate memory
void initDynamicArray(DYNAMIC_ARRAY* dynamicArray, size_t capacity) {
    dynamicArray->capacity = capacity;
    dynamicArray->count = 0;
    dynamicArray->elements = (LTE_DL_FRAMEINFO*) malloc(capacity * sizeof(LTE_DL_FRAMEINFO));
    if (dynamicArray->elements == NULL) {
        printf("Error: failed to allocate memory for dynamic array\n");
    }
}

// Function to add a new frame entry to the dynamic array
bool addFrameEntry(DYNAMIC_ARRAY* dynamicArray, uint32_t frameNumber, uint16_t numSectors, uint8_t sectorSize[]) {
    // Acquire mutex for synchronization
    pthread_mutex_lock(&mutex);

    // Check if the dynamic array is full
    if (dynamicArray->count == dynamicArray->capacity) {
        printf("Error: dynamic array is full\n");
        return false;
    }

    // Allocate memory for new frame entry
    LTE_DL_FRAMEINFO* newEntry = (LTE_DL_FRAMEINFO*) malloc(sizeof(LTE_DL_FRAMEINFO));
    if (newEntry == NULL) {
        printf("Error: failed to allocate memory for new frame entry\n");
        return false;
    }

    // Copy data from the input parameters into the new frame entry
    newEntry->frameNumber = frameNumber;
    newEntry->numSectors = numSectors;
    memcpy(newEntry->sectorSize, sectorSize, SECTOR_SIZE);

    // Add the new frame entry to the dynamic array
    dynamicArray->elements[dynamicArray->count] = newEntry;
    dynamicArray->count++;

    // Release mutex for synchronization
    pthread_mutex_unlock(&mutex);

    return true;
}

// Function to update an existing frame entry in the dynamic array
bool updateFrameEntry(DYNAMIC_ARRAY* dynamicArray, uint32_t frameNumber, uint16_t numSectors, uint8_t sectorSize[]) {
    // Acquire mutex for synchronization
    pthread_mutex_lock(&mutex);

    // Find the index of the frame entry to update
    size_t index = 0;
    while (index < dynamicArray->count && dynamicArray->elements[index]->frameNumber != frameNumber) {
        index++;
    }

    // Check if the frame entry was found
    if (index == dynamicArray->count) {
        printf("Error: frame entry not found\n");
        return false;
    }

    // Update the frame entry with new data
    LTE_DL_FRAMEINFO* updatedEntry = dynamicArray->elements[index];
    updatedEntry->numSectors = numSectors;
    memcpy(updatedEntry->sectorSize, sectorSize, SECTOR_SIZE);

    // Release mutex for synchronization
    pthread_mutex_unlock(&mutex);

    return true;
}

// Function to remove an existing frame entry from the dynamic array
bool removeFrameEntry(DYNAMIC_ARRAY* dynamicArray, uint32_t frameNumber) {
    // Acquire mutex for synchronization
    pthread_mutex_lock(&mutex);

    // Find the index of the frame entry to remove
    size_t index = 0;
    while (index < dynamicArray->count && dynamicArray->elements[index]->frameNumber != frameNumber) {
        index++;
    }

    // Check if the frame entry was found
    if (index == dynamicArray->count) {
        printf("Error: frame entry not found\n");
        return false;
    }

    // Remove the frame entry from the dynamic array
    LTE_DL_FRAMEINFO* removedEntry = dynamicArray->elements[index];
    memmove(&dynamicArray->elements[index], &dynamicArray->elements[index + 1], (dynamicArray->count - index - 1) * sizeof(LTE_DL_FRAMEINFO));
    dynamicArray->count--;

    // Release mutex for synchronization
    pthread_mutex_unlock(&mutex);

    return true;
}

// Function to retrieve a frame entry from the dynamic array by its frame number
LTE_DL_FRAMEINFO* getFrameEntry(DYNAMIC_ARRAY* dynamicArray, uint32_t frameNumber) {
    // Acquire mutex for synchronization
    pthread_mutex_lock(&mutex);

    // Find the index of the frame entry to retrieve
    size_t index = 0;
    while (index < dynamicArray->count && dynamicArray->elements[index]->frameNumber != frameNumber) {
        index++;
    }

    // Check if the frame entry was found
    if (index == dynamicArray->count) {
        printf("Error: frame entry not found\n");
        return NULL;
    }

    // Return the frame entry
