    // Lock the mutex to prevent concurrent modifications
    pthread_mutex_lock(&mutex);

    // Write the number of records to the file
    int numRecords = 0;
    Node* node = listHead;
    while (node != NULL) {
        numRecords++;
        node = node->next;
    }
    fwrite(&numRecords, sizeof(int), 1, file);

    // Write the records to the file
