    while (node != NULL) {
        Record* record = node->record;
        fwrite(&record->key, sizeof(int), 1, file);
        fwrite(&record->offset, sizeof(long), 1, file);
        size_t identifierLength = strlen(record->identifier);
        fwrite(&identifierLength, sizeof(size_t), 1, file);
        fwrite(record->identifier, identifierLength, 1, file);
        node = node->next;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// Define a function to deserialize the collection from a binary file format
void deserializeCollection(char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        perror("fopen failed");
        exit(1);
    }

    // Lock the mutex to prevent concurrent modifications
    pthread_mutex_lock(&mutex);

    // Read the number of records from the file
    int numRecords;
    fread(&numRecords, sizeof(int), 1, file);

    // Create an array of records
    Record* records = malloc(sizeof(Record) * numRecords);
    if (!records) {
        perror("malloc failed");
        exit(1);
    }

    // Read the records from the file
    for (int i = 0; i < numRecords; i++) {
        Record* record = &records[i];
        fread(&record->key, sizeof(int), 1, file);
        fread(&record->offset, sizeof(long), 1, file);
        size_t identifierLength;
        fread(&identifierLength, sizeof(size_t), 1, file);
        record->identifier = malloc(sizeof(char) * (identifierLength + 1));
        if (!record->identifier) {
            perror("malloc failed");
            exit(1);
        }
        fread(record->identifier, identifierLength, 1, file);
    }

    // Add the records to the doubly-linked list
    Node* node = NULL;
    for (int i = numRecords - 1; i >= 0; i--) {
        Record* record = &records[i];
        node = malloc(sizeof(Node));
        if (!node) {
            perror("malloc failed");
            exit(1);
        }
        node->record = record;
        node->next = listHead;
        node->prev = NULL;
        listHead = node;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

