// Define the structure to represent a task
struct Task {
    int priority;
    double start_time;
    double duration;
};

// Define the function that manages the tasks
void manage_tasks(int num_tasks, struct Task *tasks) {
    // Validate the input parameters
    if (num_tasks > MAX_TASKS || num_tasks <= 0) {
        printf("Invalid number of tasks specified: %d\n", num_tasks);
        return;
    }

    // Allocate memory for the task array
    struct Task *task_array = malloc(num_tasks * sizeof(struct Task));
    if (task_array == NULL) {
        printf("Memory allocation failed: %s\n", strerror(errno));
        return;
    }

    // Initialize the task array with random priorities and start times
