}

// Function to insert a record into the binary search tree
void insert_record(Tree* tree, int key, float value) {
    // Allocate memory for the new node using the memory pool allocator
    Node* new_node = (Node*)malloc(sizeof(Node));

    // Initialize the new node's data fields
    new_node->key = key;
    new_node->value = value;
    new_node->record = create_record();
    new_node->left = NULL;
    new_node->right = NULL;

    // Insert the new node into the binary search tree
    insert_node(tree, key, value);
}

// Function to insert a node into the binary search tree
void insert_node(Tree* tree, int key, float value) {
    // If the tree is empty, set the root node to the new node
    if (tree->root == NULL) {
        tree->root = new_node;
    } else {
        Node* current_node = tree->root;

        // While the current node is not null, loop through its children
        while (current_node != NULL) {
            if (key < current_node->key) {
                // If the new key is less than the current node's key, go left
                if (current_node->left == NULL) {
                    current_node->left = new_node;
                } else {
                    current_node = current_node->left;
                }
            } else if (key > current_node->key) {
                // If the new key is greater than the current node's key, go right
                if (current_node->right == NULL) {
                    current_node->right = new_node;
                } else {
                    current_node = current_node->right;
                }
            } else {
                // If the new key is equal to the current node's key, update the value
                current_node->value = value;
                break;
            }
        }
    }
}

// Function to create a binary search tree
Tree* create_tree() {
    Tree* tree = (Tree*)malloc(sizeof(Tree));
    tree->root = NULL;
    return tree;
}

// Function to free the memory allocated for the binary search tree
void free_tree(Tree* tree) {
    // Free the root node and all of its children
    Node* current_node = tree->root;
    while (current_node != NULL) {
        if (current_node->left != NULL) {
            free_node(current_node->left);
        }
        if (current_node->right != NULL) {
            free_node(current_node->right);
        }
        current_node = current_node->parent;
    }
}

// Function to free the memory allocated for a node and its children
void free_node(Node* node) {
    // Free the record associated with the node
    free_record(node->record);

    // Free the left and right children of the node
    if (node->left != NULL) {
        free_node(node->left);
    }
    if (node->right != NULL) {
        free_node(node->right);
    }
}

// Function to free the memory allocated for a record and its log entries
void free_record(Record* record) {
    // Free the log entries associated with the record
    LogEntry* current_log_entry = record->log_entries;
    while (current_log_entry != NULL) {
        LogEntry* next_log_entry = current_log_entry->next;
        free(current_log_entry);
        current_log_entry = next_log_entry;
    }

    // Free the record itself
    free(record);
}

