Here's an example implementation of the C function that dynamically allocates memory for an array of `long` offset values, another for `int` keys, and an array of `record` structures. The function also manages these records using a thread-safe linked list to support efficient insertion, deletion, and traversal operations. Each `record` is uniquely identified by an `int` key from the `int` keys array, and its value is initialized to a random integer within a specified range. The function optimizes memory usage, ensures concurrency, scalability, performance, and resource management:
```c
#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>
#include <errno.h>

struct record {
    int key;
    long value;
};

typedef struct record *record_t;

// Thread-safe linked list node
struct ll_node {
    record_t data;
    struct ll_node *next;
    pthread_mutex_t mutex;
};

// Thread-safe linked list head
struct ll_head {
    struct ll_node *head;
    pthread_mutex_t mutex;
};

// Memory management functions
void *alloc(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Error: failed to allocate memory\n");
        exit(1);
    }
    return ptr;
}

void free_ll_node(struct ll_node *node) {
    pthread_mutex_lock(&node->mutex);
    struct ll_node *next = node->next;
    pthread_mutex_unlock(&node->mutex);
    free(node);
    if (next != NULL)
        free_ll_node(next);
}

void free_ll_head(struct ll_head *head) {
    struct ll_node *node = head->head;
    pthread_mutex_lock(&head->mutex);
    pthread_mutex_unlock(&head->mutex);
    free(head);
    if (node != NULL)
        free_ll_node(node);
}

// Function to dynamically allocate memory for an array of long offset values
long *alloc_offset_array(size_t size) {
    long *arr = alloc(sizeof(long) * size);
    return arr;
}

// Function to dynamically allocate memory for an array of int keys
int *alloc_key_array(size_t size) {
    int *arr = alloc(sizeof(int) * size);
    return arr;
}

// Function to dynamically allocate memory for an array of record structures
struct record **alloc_record_array(size_t size) {
    struct record **arr = alloc(sizeof(struct record *) * size);
    return arr;
}

// Thread-safe linked list operations
void ll_insert(struct ll_head *head, struct ll_node *node) {
    pthread_mutex_lock(&head->mutex);
    node->next = head->head;
    head->head = node;
    pthread_mutex_unlock(&head->mutex);
}

void ll_delete(struct ll_head *head, struct ll_node *node) {
    pthread_mutex_lock(&head->mutex);
    struct ll_node *prev = NULL;
    for (struct ll_node *curr = head->head; curr != NULL && curr != node; prev = curr, curr = curr->next) {}
    if (curr == NULL) {
        pthread_mutex_unlock(&head->mutex);
        return;
    }
    if (prev == NULL)
        head->head = curr->next;
    else
        prev->next = curr->next;
    pthread_mutex_unlock(&head->mutex);
}

struct ll_node *ll_search(struct ll_head *head, int key) {
    struct ll_node *curr;
    pthread_mutex_lock(&head->mutex);
    for (curr = head->head; curr != NULL && curr->data->key != key; curr = curr->next) {}
    pthread_mutex_unlock(&head->mutex);
    return curr;
}

// Function to initialize the linked list and allocate memory for an array of records
struct ll_head *ll_init(size_t size) {
    struct ll_head *head = alloc(sizeof(struct ll_head));
    head->head = NULL;
    pthread_mutex_init(&head->mutex, NULL);
    return head;
}

// Function to insert a record into the linked list and allocate memory for it
void ll_insert_record(struct ll_head *head, int key) {
    struct record *rec = alloc(sizeof(struct record));
    rec->key = key;
    long value = (long)(rand() % 100);
    rec->value = value;
    struct ll_node *node = alloc(sizeof(struct ll_node));
    node->data = rec;
    pthread_mutex_init(&node->mutex, NULL);
    ll_insert(head, node);
}

// Function to delete a record from the linked list and free its memory
void ll_delete_record(struct ll_head *head, int key) {
    struct ll_node *node = ll_search(head, key);
    if (node == NULL)
        return;
    pthread_mutex_lock(&node->mutex);
    free(node->data->value);
    free(node->data);
    node->next = NULL;
    pthread_mutex_unlock(&node->mutex);
}

// Function to traverse the linked list and print each record's key and value
void ll_print(struct ll_head *head) {
    struct ll_node *curr = head->head;
    while (curr != NULL) {
        printf("%d -> %ld\n", curr->data->key, curr->data->value);
        curr = curr->next;
    }
}

// Function to free all memory allocated by the linked list
void ll_free(struct ll_head *head) {
    struct ll_node *node = head->head;
    while (node != NULL) {
        struct ll_node *next = node->next;
        pthread_mutex_destroy(&node->mutex);
        free(node->data->value);
        free(node->data);
        free(node);
        node = next;
    }
}
```
To use this function, you can first call `ll_init` to initialize the linked list and allocate memory for an array of records. Then, you can use `ll_insert_record` to insert new records into the linked list and `ll_delete_record` to delete existing records. Finally, you can use `ll_print` to traverse the linked list and print each record's key and value.

Here is an example of how to use this function:
