// Define the maximum pool size and timeout for queueing requests
#define MAX_POOL_SIZE 1000
#define TIMEOUT_SECS 5

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
