    pthread_cond_t cond;
    int head, tail;
    size_t pool_size;
    NFAPI_CRC_INDICATION_PDU_T *pool[MAX_POOL_SIZE];
} CRC_INDICATION_POOL_T;

void initialize_crc_indication_pool(CRC_INDICATION_POOL_T *pool) {
    // Initialize the pool and mutex
    memset(pool, 0, sizeof(*pool));
    pthread_mutex_init(&pool->mutex, NULL);
    pthread_cond_init(&pool->cond, NULL);
}

void destroy_crc_indication_pool(CRC_INDICATION_POOL_T *pool) {
    // Destroy the pool and mutex
    pthread_mutex_destroy(&pool->mutex);
    pthread_cond_destroy(&pool->cond);
}

void add_crc_indication_pdu(CRC_INDICATION_POOL_T *pool, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Add the PDU to the pool if there is space available
    if (pool->head - pool->tail < MAX_POOL_SIZE) {
        pthread_mutex_lock(&pool->mutex);
        pool->pool[pool->head] = pdu;
        pool->head++;
        pthread_cond_signal(&pool->cond);
        pthread_mutex_unlock(&pool->mutex);
    } else {
        // Queue the PDU if the pool is full
        pthread_mutex_lock(&pool->mutex);
        while (pool->head - pool->tail >= MAX_POOL_SIZE) {
            pthread_cond_wait(&pool->cond, &pool->mutex);
        }
        pool->pool[pool->head] = pdu;
        pool->head++;
        pthread_cond_signal(&pool->cond);
        pthread_mutex_unlock(&pool->mutex);
    }
}

NFAPI_CRC_INDICATION_PDU_T *get_crc_indication_pdu(CRC_INDICATION_POOL_T *pool) {
