    NFAPI_CRC_INDICATION_PDU_T *pdu = NULL;
    pthread_mutex_lock(&pool->mutex);
    while (pool->head - pool->tail < 1) {
        if (pthread_cond_timedwait(&pool->cond, &pool->mutex, TIMEOUT_SECS * CLOCKS_PER_SEC)) {
            // Timeout reached, return NULL
            pthread_mutex_unlock(&pool->mutex);
            return NULL;
        }
    }
    pool->tail++;
    pthread_cond_signal(&pool->cond);
    pthread_mutex_unlock(&pool->mutex);
    return pool->pool[pool->tail - 1];
}

