// Insertion function for thread-safe linked list
void insert(record* data) {
    pthread_mutex_lock(&head_lock);
    thread_safe_linked_list_node* new_node = (thread_safe_linked_list_node*)malloc(sizeof(thread_safe_linked_list_node));
    new_node->data = data;
    new_node->next = head;
    head = new_node;
    pthread_mutex_unlock(&head_lock);
}

