// Define the data source for RX_UE_INFORMATION_TAG and RNTI mappings
#define RX_UE_INFORMATION_DATA_SOURCE "rx_ue_information.dat"

// Define the cache size for storing recent mappings
#define CACHE_SIZE 1024

// Define the memory pool size for reusing allocated memory blocks
#define MEMORY_POOL_SIZE (512 * 1024) // 512 KB

// Define the maximum memory usage limit
#define MAX_MEMORY_USAGE (8 * 1024 * 1024) // 8 MB

// Global variables for caching and memory management
static char* cache[CACHE_SIZE];
static void* memory_pool[MEMORY_POOL_SIZE / sizeof(void*)];
static size_t memory_usage = 0;
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically generate and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void* generate_crc_indication_pdu_list(int num_entries) {
    // Validate the input parameter
    if (num_entries <= 0) {
        return NULL;
    }

    // Initialize the list and cache
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_entries);
    if (pdu_list == NULL) {
        return NULL;
    }
    memset(cache, 0, sizeof(cache));
    memset(memory_pool, 0, sizeof(memory_pool));

    // Read the RX_UE_INFORMATION_TAG and RNTI mappings from the data source
    FILE* file = fopen(RX_UE_INFORMATION_DATA_SOURCE, "r");
    if (file == NULL) {
        free(pdu_list);
        return NULL;
    }

    // Read the mapping entries and populate the list and cache
    size_t num_mappings = 0;
    while (!feof(file)) {
        char line[256];
        fgets(line, sizeof(line), file);
        if (strlen(line) == 0 || line[0] == '#') {
            continue;
        }
        // Split the mapping entry into RX_UE_INFORMATION_TAG and RNTI
        char* token = strtok(line, " ");
        uint8_t rx_ue_information_tag = (uint8_t) atoi(token);
        token = strtok(NULL, " ");
        uint16_t rnti = (uint16_t) atoi(token);
        // Check if the mapping is already in the cache or not
        bool found = false;
        for (int i = 0; i < CACHE_SIZE && !found; i++) {
            if (cache[i] != NULL && strcmp(cache[i], token) == 0) {
                found = true;
            }
        }
        // If the mapping is not in the cache, add it and populate the list
        if (!found) {
            NFAPI_CRC_INDICATION_PDU_T* pdu = &pdu_list[num_mappings];
            pdu->RX_UE_INFORMATION_TAG = rx_ue_information_tag;
            pdu->RNTI = rnti;
            // Set the CRCFLAG to a randomly generated value
            pdu->CRCFLAG = (rand() % 2) == 0;
            cache[num_mappings] = strdup(token);
            num_mappings++;
        }
    }
    fclose(file);

    // Validate the association between each RX_UE_INFORMATION_TAG and its corresponding RNTI
    for (int i = 0; i < num_entries; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &pdu_list[i];
        char key[64];
        snprintf(key, sizeof(key), "%d:%d", pdu->RX_UE_INFORMATION_TAG, pdu->RNTI);
        bool found = false;
        for (int j = 0; j < CACHE_SIZE && !found; j++) {
            if (cache[j] != NULL && strcmp(cache[j], key) == 0) {
                found = true;
            }
        }
        if (!found) {
            printf("Mismatch detected between RX_UE_INFORMATION_TAG %d and RNTI %d\n", pdu->RX_UE_INFORMATION_TAG, pdu->RNTI);
        }
    }

    // Return the populated list
    return pdu_list;
}

// Function to free the memory allocated for a given list of NFAPI_CRC_INDICATION_PDU_T structures
void free_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_T* pdu_list) {
    // Validate the input parameter
    if (pdu_list == NULL) {
        return;
    }

    // Free the list and cache
    for (int i = 0; i < num_entries; i++) {
        free(cache[i]);
    }
    free(pdu_list);
}

// Function to acquire a lock on the mutex protecting the memory usage statistics
void acquire_lock() {
    pthread_mutex_lock(&lock);
}

// Function to release the lock on the mutex protecting the memory usage statistics
void release_lock() {
    pthread_mutex_unlock(&lock);
}

// Function to update the memory usage statistics
void update_memory_usage(size_t delta) {
    // Validate the input parameter
    if (delta <= 0) {
        return;
    }

    acquire_lock();
    memory_usage += delta;
    release_lock();
}

// Function to get the current memory usage statistics
size_t get_memory_usage() {
    size_t result = 0;
    acquire_lock();
    result = memory_usage;
    release_lock();
    return result;
}']

