// Initialize the memory pool with a fixed-size buffer
void init_mempool(mempool_t* pool, size_t capacity) {
    // Allocate an array of pointers to nodes
    node_t** nodes = malloc(capacity * sizeof(node_t*));
    if (!nodes) {
        fprintf(stderr, "Failed to allocate memory for the node array\n");
        exit(1);
    }
    // Initialize each pointer in the array to NULL
    for (size_t i = 0; i < capacity; ++i) {
        nodes[i] = NULL;
    }
    // Set the pool's properties
    pool->nodes = nodes;
    pool->capacity = capacity;
    pool->used = 0;
}

// Allocate a new node in the memory pool
node_t* alloc_node(mempool_t* pool) {
    // Acquire the lock on the pool
    pthread_mutex_lock(&pool->lock);

    // Check if the pool is full
    if (pool->used >= pool->capacity) {
        // Release the lock and return NULL
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    // Allocate a new node
    size_t index = pool->used++;
    node_t* node = &pool->nodes[index];
    memset(node, 0, sizeof(node_t));

    // Release the lock and return the allocated node
    pthread_mutex_unlock(&pool->lock);
    return node;
}

// Free a node in the memory pool
void free_node(mempool_t* pool, node_t* node) {
    // Acquire the lock on the pool
    pthread_mutex_lock(&pool->lock);

    // Check if the node is NULL or not within the pool's range
    if (!node || (node < pool->nodes || node >= pool->nodes + pool->capacity)) {
        // Release the lock and return
        pthread_mutex_unlock(&pool->lock);
        return;
