    // Set the node's pointer to NULL
    node->next = NULL;

    // Release the lock and return
    pthread_mutex_unlock(&pool->lock);
}

// Update the boolean flag for a given node based on a condition
void update_node_flag(mempool_t* pool, node_t* node, bool condition) {
    // Acquire the lock on the pool
    pthread_mutex_lock(&pool->lock);

    // Check if the node is NULL or not within the pool's range
    if (!node || (node < pool->nodes || node >= pool->nodes + pool->capacity)) {
        // Release the lock and return
        pthread_mutex_unlock(&pool->lock);
        return;
    }

    // Set the node's flag based on the condition
    if (condition) {
        node->is_accessed = true;
    } else {
        node->is_accessed = false;
    }

    // Release the lock and return
    pthread_mutex_unlock(&pool->lock);
}

// Traverse the list of nodes and update their flags based on a condition
void traverse_list(mempool_t* pool, bool (*condition)(node_t*)) {
    // Acquire the lock on the pool
    pthread_mutex_lock(&pool->lock);

    // Iterate over all nodes in the list
    for (size_t i = 0; i < pool->capacity; ++i) {
        node_t* node = &pool->nodes[i];
        if (!node->next) break;
        update_node_flag(pool, node, condition(node));
    }

    // Release the lock and return
    pthread_mutex_unlock(&pool->lock);
}

// Integrate the node structures into an existing linked list API
void insert_node(mempool_t* pool, node_t* new_node) {
    // Acquire the lock on the pool
    pthread_mutex_lock(&pool->lock);

    // Check if the pool is full or the new node is NULL
    if (pool->used >= pool->capacity || !new_node) {
        // Release the lock and return
        pthread_mutex_unlock(&pool->lock);
        return;
    }

    // Calculate the index of the new node in the array
    size_t index = pool->used++;
    node_t* node = &pool->nodes[index];

    // Set the new node's properties
    memset(node, 0, sizeof(node_t));
    node->value = new_node->value;

    // Insert the new node at the end of the list
    if (pool->head) {
        pool->tail->next = node;
        pool->tail = node;
    } else {
        pool->head = node;
        pool->tail = node;
    }

    // Release the lock and return
    pthread_mutex_unlock(&pool->lock);
}

// Free a list of nodes in the memory pool
void free_list(mempool_t* pool) {
    // Acquire the lock on the pool
    pthread_mutex_lock(&pool->lock);

    // Iterate over all nodes in the list
    for (size_t i = 0; i < pool->capacity; ++i) {
        node_t* node = &pool->nodes[i];
        if (!node->next) break;
        free_node(pool, node);
    }

    // Release the lock and return
    pthread_mutex_unlock(&pool->lock);
}
