        if (!pdcp_pdus[i]) {
            printf("Error: Failed to allocate memory for LTE_PDCP_PDU structure %d\n", i);
            return NULL;
        }
    }

    // Populate the dynamic array of LTE_PDCP_PDU structures with valid PDCP data
