    for (uint32_t i = 0; i < num_pdu; i++) {
        // Generate a random PDCP sequence number
        pdcp_pdus[i]->pdcp_seq_num = rand() % 65536 + 1;

        // Allocate memory for the PDCP PDU data
        pdcp_pdus[i]->pdcp_pdu_data = malloc(sizeof(void*) * pdcp_seq_nums[i]);
        if (!pdcp_pdus[i]->pdcp_pdu_data) {
            printf("Error: Failed to allocate memory for PDCP PDU data\n");
            return NULL;
        }

        // Populate the PDCP PDU data with valid data
        for (uint16_t j = 0; j < pdcp_seq_nums[i]; j++) {
            memcpy(pdcp_pdus[i]->pdcp_pdu_data + j, "Hello World", strlen("Hello World"));
        }

        populated_pdu_count++;
    }

    // Track the number of successfully allocated and populated PDUs for debugging and resource management
    printf("Successfully initialized and populated %d out of %d LTE_PDCP_PDU structures\n", populated_pdu_count, num_pdu);

    return pdcp_pdus;
}
