#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <netinet/in.h>
#include <arpa/inet.h>

// Struct to represent network interface configurations
typedef struct {
    int id;
    char *ip_address;
    char *subnet_mask;
    char *gateway;
    char *location;
    char role[10]; // "public", "private", "backup"
} network_interface;

// Function to initialize and populate an array of structures representing network interface configurations
void init_network_interfaces(network_interface **interfaces, int num_interfaces) {
    if (interfaces == NULL || num_interfaces <= 0) {
        return;
    }

    // Allocate memory for the array of structures and initialize each structure with default values
    *interfaces = malloc(num_interfaces * sizeof(network_interface));
    memset(*interfaces, 0, num_interfaces * sizeof(network_interface));
    int i;
    for (i = 0; i < num_interfaces; i++) {
        (*interfaces)[i].id = i + 1;
        (*interfaces)[i].ip_address = "0.0.0.0";
        (*interfaces)[i].subnet_mask = "255.255.255.0";
        (*interfaces)[i].gateway = "0.0.0.0";
        (*interfaces)[i].location = "default location";
        strcpy((*interfaces)[i].role, "public");
    }
}

// Function to add a new network interface configuration to the array of structures
void add_network_interface(network_interface **interfaces, int *num_interfaces, const char *ip_address, const char *subnet_mask, const char *gateway, const char *location, const char *role) {
    if (interfaces == NULL || num_interfaces == NULL) {
        return;
    }

    // Check if the input parameters are valid
    if (!ip_address || !subnet_mask || !gateway || !location || !role) {
        printf("Invalid input parameters\n");
        return;
    }

    // Allocate memory for a new structure and initialize it with default values
    network_interface *new_interface = malloc(sizeof(network_interface));
    memset(new_interface, 0, sizeof(network_interface));
    int i;
    for (i = 0; i < *num_interfaces; i++) {
        if ((*interfaces)[i].id == -1) { // Find the first unused slot in the array
            break;
        }
    }
    if (i == *num_interfaces) { // No more slots available, reallocate the array
        (*interfaces) = realloc(*interfaces, (*num_interfaces + 1) * sizeof(network_interface));
        new_interface->id = *num_interfaces + 1;
    } else {
        new_interface->id = i + 1;
    }
    strcpy(new_interface->ip_address, ip_address);
    strcpy(new_interface->subnet_mask, subnet_mask);
    strcpy(new_interface->gateway, gateway);
    strcpy(new_interface->location, location);
    strcpy(new_interface->role, role);
    (*interfaces)[*num_interfaces] = *new_interface;
    free(new_interface); // Free the allocated memory for the new structure
    *num_interfaces += 1; // Increment the number of interfaces by 1
}

// Function to remove a network interface configuration from the array of structures
void remove_network_interface(network_interface **interfaces, int *num_interfaces, int id) {
    if (interfaces == NULL || num_interfaces == NULL) {
        return;
    }

    // Check if the input parameters are valid
    if (!id) {
        printf("Invalid input parameters\n");
        return;
    }

    int i;
    for (i = 0; i < *num_interfaces; i++) {
        if ((*interfaces)[i].id == id) { // Find the interface with the specified ID
            break;
        }
    }
    if (i == *num_interfaces) { // No such interface found, return
        printf("Interface with ID %d not found\n", id);
        return;
    }
    (*interfaces)[i].id = -1; // Mark the interface as deleted
}
