// Dynamic array to store PDCP PDUs
LTE_PDCP_PDU* pdcp_pdus;
int pdcp_pdu_count = 0;

// Memory pressure detection system
static int memory_pressure = 0;

// Function to initialize and populate dynamic array of PDCP PDUs
void init_pdcp_pdus(int capacity) {
    // Allocate memory for the dynamic array
    pdcp_pdus = (LTE_PDCP_PDU*) malloc(capacity * sizeof(LTE_PDCP_PDU));
    if (!pdcp_pdus) {
        printf("Error: Failed to allocate memory for PDCP PDUs\n");
        exit(1);
    }
}

// Function to populate a single PDCP PDU structure
void populate_pdcp_pdu(int pdcp_sn, int pdcp_seq_num, char* pdcp_pdu_data) {
    // Check if the dynamic array is full
    if (pdcp_pdu_count >= capacity) {
        // Reallocate memory for the dynamic array
        capacity *= 2;
        pdcp_pdus = (LTE_PDCP_PDU*) realloc(pdcp_pdus, capacity * sizeof(LTE_PDCP_PDU));
        if (!pdcp_pdus) {
            printf("Error: Failed to reallocate memory for PDCP PDUs\n");
            exit(1);
        }
    }

    // Add a new PDCP PDU structure to the dynamic array
    pdcp_pdus[pdcp_pdu_count].pdcp_sn = pdcp_sn;
    pdcp_pdus[pdcp_pdu_count].pdcp_seq_num = pdcp_seq_num;
    pdcp_pdus[pdcp_pdu_count].pdcp_pdu_data = strdup(pdcp_pdu_data);
    pdcp_pdu_count++;
}

// Function to manage memory pressure
void manage_memory_pressure() {
    // Check if the heap usage is critically low
    if (memory_pressure > 0) {
        // Attempt to free up resources by releasing older PDUs
        int i = 0;
        while (i < pdcp_pdu_count) {
            if (pdcp_pdus[i].pdcp_sn == 0) {
                // Release memory for the oldest PDCP PDU structure
                free(pdcp_pdus[i].pdcp_pdu_data);
                pdcp_pdus[i] = pdcp_pdus[pdcp_pdu_count - 1];
                pdcp_pdu_count--;
            } else {
                i++;
            }
        }
    }
}

// Function to retrieve a PDCP PDU structure from the dynamic array
LTE_PDCP_PDU* get_pdcp_pdu(int pdcp_sn) {
    // Iterate through the dynamic array and find the corresponding PDCP PDU structure
    for (int i = 0; i < pdcp_pdu_count; i++) {
        if (pdcp_pdus[i].pdcp_sn == pdcp_sn) {
            return &pdcp_pdus[i];
        }
    }
    return NULL;
}

// Function to update a PDCP PDU structure in the dynamic array
void update_pdcp_pdu(int pdcp_sn, int pdcp_seq_num, char* pdcp_pdu_data) {
    // Find the corresponding PDCP PDU structure in the dynamic array
