void store_inputs(Record* array, int size) {
    // Iterate through each input integer
    for (int i = 0; i < size; i++) {
        // Read an input integer from standard input
        int input;
        scanf("%d", &input);

        // Validate the input integer against the specified range
        if (input < min_input || input > max_input) {
