    ESTABLISHED,
    SYN_SENT,
    FIN_WAIT,
    CLOSED,
} connection_state_t;

// Struct for storing connection metadata
typedef struct {
    uint32_t remote_ip; // Remote IP address (in network byte order)
    uint16_t port; // Port number (in host byte order)
    connection_state_t state; // Connection state
    int32_t session_timeout; // Session timeout value (in seconds)
} connection_metadata_t;

// Struct for storing the dynamic list of connections
typedef struct {
    connection_metadata_t* metadata[MAX_CONNECTIONS]; // Array of pointers to connection metadata
    size_t count; // Number of connections in the list
} connection_list_t;

// Function prototypes
void add_connection(connection_list_t* list, uint32_t remote_ip, uint16_t port, connection_state_t state, int32_t session_timeout);
bool remove_connection(connection_list_t* list, uint32_t remote_ip, uint16_t port);
void update_connection(connection_list_t* list, uint32_t remote_ip, uint16_t port, connection_state_t state, int32_t session_timeout);
void clear_connections(connection_list_t* list);
bool validate_connection(const connection_metadata_t* metadata);

// Function implementations

/**
 * Adds a new connection to the list.
 * @param list The connection list
 * @param remote_ip The remote IP address (in network byte order)
 * @param port The port number (in host byte order)
 * @param state The connection state
 * @param session_timeout The session timeout value (in seconds)
 */
void add_connection(connection_list_t* list, uint32_t remote_ip, uint16_t port, connection_state_t state, int32_t session_timeout) {
    // Check if the number of connections exceeds the maximum capacity
    if (list->count == MAX_CONNECTIONS) {
        printf("Error: Maximum capacity reached.\n");
        return;
    }

    // Allocate memory for the new connection metadata
    connection_metadata_t* new_metadata = malloc(sizeof(connection_metadata_t));
    if (new_metadata == NULL) {
        printf("Error: Failed to allocate memory for the new connection metadata.\n");
        return;
    }

    // Set the connection state and session timeout values
    new_metadata->state = state;
    new_metadata->session_timeout = session_timeout;

    // Store the remote IP address (in network byte order) and port number (in host byte order) in the metadata
    new_metadata->remote_ip = remote_ip;
    new_metadata->port = port;

    // Add the new connection to the list
    list->metadata[list->count++] = new_metadata;
}

/**
 * Removes a connection from the list.
 * @param list The connection list
 * @param remote_ip The remote IP address (in network byte order)
 * @param port The port number (in host byte order)
 * @return True if the connection was removed, false otherwise
 */
bool remove_connection(connection_list_t* list, uint32_t remote_ip, uint16_t port) {
    // Find the connection in the list by searching for a matching remote IP address and port number
    for (size_t i = 0; i < list->count; i++) {
        if (list->metadata[i]->remote_ip == remote_ip && list->metadata[i]->port == port) {
            // Free the memory allocated for the connection metadata
            free(list->metadata[i]);

            // Remove the connection from the list by shifting all connections after it to the left
            for (size_t j = i; j < list->count - 1; j++) {
                list->metadata[j] = list->metadata[j + 1];
            }

            // Decrement the number of connections in the list
            list->count--;

            return true;
        }
    }

    return false;
}

/**
 * Updates a connection's state and session timeout values.
 * @param list The connection list
 * @param remote_ip The remote IP address (in network byte order)
 * @param port The port number (in host byte order)
 * @param state The new connection state
 * @param session_timeout The new session timeout value (in seconds)
 */
void update_connection(connection_list_t* list, uint32_t remote_ip, uint16_t port, connection_state_t state, int32_t session_timeout) {
    // Find the connection in the list by searching for a matching remote IP address and port number
    for (size_t i = 0; i < list->count; i++) {
        if (list->metadata[i]->remote_ip == remote_ip && list->metadata[i]->port == port) {
            // Update the connection state and session timeout values
            list->metadata[i]->state = state;
            list->metadata[i]->session_timeout = session_timeout;

            return;
        }
    }
}

/**
 * Clears all connections from the list.
 * @param list The connection list
 */
void clear_connections(connection_list_t* list) {
    // Free the memory allocated for each connection metadata
    for (size_t i = 0; i < list->count; i++) {
        free(list->metadata[i]);
    }

    // Reset the number of connections in the list to zero
    list->count = 0;
}

/**
 * Validates a connection's metadata against a predefined template.
 * @param metadata The connection metadata
 * @return True if the metadata is valid, false otherwise
 */
bool validate_connection(const connection_metadata_t* metadata) {
    // Check if all mandatory fields are present and correctly formatted
    if (metadata->state != ESTABLISHED && metadata->state != SYN_SENT && metadata->state != FIN_WAIT) {
        printf("Error: Invalid connection state.\n");
        return false;
    }

    if (metadata->session_timeout < 0) {
        printf("Error: Invalid session timeout value.\n");
        return false;
    }

    // Check if the remote IP address is valid
    if (inet_pton(AF_INET, metadata->remote_ip, &tmp_addr) == 0) {
        printf("Error: Invalid remote IP address.\n");
        return false;
    }

    // Check if the port number is valid
    if (metadata->port < 1 || metadata->port > 65535) {
        printf("Error: Invalid port number.\n");
        return false;
    }

    return true;
}
