```c
#include <stdlib.h>
#include <string.h>

// Define the structure for each record
typedef struct {
    int key;
    float weight;
    char tag;
} Record;

// Define the hash table structure
typedef struct {
    int size; // Size of the hash table
    int capacity; // Capacity of the hash table
    long *offsets; // Array of offsets for each record
    int *keys; // Array of keys for each record
    float **weights; // Array of weights for each record
} HashTable;

// Function to dynamically allocate memory for a new record
Record* create_record(int key, float weight, char tag) {
    Record *record = (Record *) malloc(sizeof(Record));
    if (!record) {
        return NULL;
    }
    record->key = key;
    record->weight = weight;
    record->tag = tag;
    return record;
}

// Function to dynamically allocate memory for a new hash table
HashTable* create_hashtable(int size) {
    HashTable *table = (HashTable *) malloc(sizeof(HashTable));
    if (!table) {
        return NULL;
    }
    table->size = size;
    table->capacity = size;
    table->offsets = (long *) malloc(table->capacity * sizeof(long));
    table->keys = (int *) malloc(table->capacity * sizeof(int));
    table->weights = (float **) malloc(table->capacity * sizeof(float *));
    if (!table->offsets || !table->keys || !table->weights) {
        free(table);
        return NULL;
    }
    for (int i = 0; i < table->capacity; i++) {
        table->offsets[i] = -1;
    }
    return table;
}

// Function to insert a new record into the hash table
void insert_record(HashTable *table, int key, float weight, char tag) {
    if (table->capacity == 0 || table->size == table->capacity) {
        // Resize the hash table if it is full
        table = resize_hashtable(table, 2 * table->capacity);
        if (!table) {
            return;
        }
    }
    int index = key % table->capacity;
    while (table->offsets[index] != -1 && table->keys[index] != key) {
        // Collision detection and resolution
        index = (index + 1) % table->capacity;
    }
    table->offsets[index] = table->size++;
    table->keys[index] = key;
    table->weights[index] = (float *) malloc(sizeof(float));
    *table->weights[index] = weight;
}

// Function to delete a record from the hash table
void delete_record(HashTable *table, int key) {
    if (!table || !table->offsets || !table->keys || !table->weights) {
        return;
    }
    int index = key % table->capacity;
    while (table->offsets[index] != -1 && table->keys[index] != key) {
        // Collision detection and resolution
        index = (index + 1) % table->capacity;
    }
    if (table->offsets[index] == -1) {
        return;
    }
    int deleted_index = table->offsets[index];
    table->keys[index] = NULL;
    free(table->weights[deleted_index]);
    table->weights[deleted_index] = NULL;
    // Shift the elements in the hash table to maintain a contiguous list
    for (int i = deleted_index + 1; i < table->size; i++) {
        table->offsets[i - 1] = table->offsets[i];
        table->keys[i - 1] = table->keys[i];
        table->weights[i - 1] = table->weights[i];
    }
    // Reduce the size of the hash table if necessary
    if (table->size > 0 && table->size == table->capacity / 4) {
        table = resize_hashtable(table, table->capacity / 2);
        if (!table) {
            return;
        }
    }
}

// Function to search for a record in the hash table
Record* find_record(HashTable *table, int key) {
    if (!table || !table->offsets || !table->keys || !table->weights) {
        return NULL;
    }
    int index = key % table->capacity;
    while (table->offsets[index] != -1 && table->keys[index] != key) {
        // Collision detection and resolution
        index = (index + 1) % table->capacity;
    }
    if (table->offsets[index] == -1) {
        return NULL;
    }
    return &table->weights[index];
}

// Function to resize the hash table when it is full
HashTable* resize_hashtable(HashTable *table, int new_capacity) {
    HashTable *new_table = create_hashtable(new_capacity);
    if (!new_table) {
        return NULL;
    }
    for (int i = 0; i < table->size; i++) {
        int index = table->keys[i] % new_table->capacity;
        while (new_table->offsets[index] != -1 && new_table->keys[index] != table->keys[i]) {
            // Collision detection and resolution
            index = (index + 1) % new_table->capacity;
        }
        if (new_table->offsets[index] == -1) {
            new_table->offsets[index] = i;
            new_table->keys[index] = table->keys[i];
            new_table->weights[index] = (float *) malloc(sizeof(float));
            *new_table->weights[index] = table->weights[i];
        } else {
            // Handle collisions by chaining records in the hash table
            int deleted_index = new_table->offsets[index];
            new_table->keys[deleted_index] = NULL;
            free(new_table->weights[deleted_index]);
            new_table->weights[deleted_index] = NULL;
            while (new_table->offsets[deleted_index] != -1 && new_table->keys[deleted_index] == key) {
                deleted_index = (deleted_index + 1) % new_table->capacity;
            }
            new_table->offsets[deleted_index] = i;
            new_table->keys[deleted_index] = table->keys[i];
            new_table->weights[deleted_index] = (float *) malloc(sizeof(float));
            *new_table->weights[deleted_index] = table->weights[i];
        }
    }
    return new_table;
}

// Function to generate a random integer between two given integers
int randint(int low, int high) {
    return (rand() % (high - low + 1)) + low;
}

// Main function
int main() {
    srand(time(NULL));
    // Declare and initialize the hash table
    HashTable *table = create_hashtable();
    for (int i = 0; i < 10; i++) {
        int key = randint(1, 10);
        float value = randfloat();
        insert(table, key, value);
    }
    printf("The hash table is:\n");
    print_hashtable(table);
    // Search for a random key in the hash table
    int search_key = randint(1, 10);
    Record *record = find(table, search_key);
    if (record != NULL) {
        printf("The record with key %d is found.\n", search_key);
    } else {
        printf("The record with key %d is not found.\n", search_key);
    }
    // Delete a random key from the hash table
    int delete_key = randint(1, 10);
    delete(table, delete_key);
    printf("The hash table after deleting the key %d:\n", delete_key);
    print_hashtable(table);
    return 0;
}
