// Custom allocator for managing memory efficiently
struct Allocator {
    void* (*alloc)(size_t size);
    void (*dealloc)(void* ptr);
};

// LRU cache to minimize fragmentation and improve allocation efficiency
struct Cache {
    struct CacheNode* head;
    struct CacheNode* tail;
};

struct CacheNode {
    void* data;
    size_t size;
    struct CacheNode* next;
};

// Custom deallocation function to handle edge cases and potential inconsistencies
void customDeallocate(void* ptr) {
    // Handle the case where the memory block was never fully allocated
    if (ptr == NULL) {
        return;
    }
    // Free the memory block and remove it from the cache
    free(ptr);
}

// Thread-safe initialization process to allow concurrent calls without race conditions
void* initializeRecords(size_t numRecords, size_t maxNumRecords, int minIntValue, int maxIntValue, const char* pattern) {
    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&mutex);
    // Handle input errors gracefully by logging warnings and returning a null pointer with a failure flag
    if (numRecords > maxNumRecords || minIntValue > maxIntValue) {
        fprintf(stderr, "Invalid input: %zu records, %d-%d int values\n", numRecords, minIntValue, maxIntValue);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    // Use a custom allocator with a fallback strategy to manage memory efficiently
    struct Allocator* allocator = getAllocator();
    void* data = allocator->alloc(numRecords * sizeof(struct Record));
