struct NFAPI_CRC_INDICATION_PDU_T* create_nfapi_crc_indication_pdu(size_t size) {
    // Validate the requested size against the maximum size limit
    if (size > MAX_SIZE_LIMIT) {
        fprintf(stderr, "ERROR: Requested array size exceeds maximum limit.\n");
        return NULL;
    }

    // Allocate memory for the array of structures
    struct NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T) * size);
    if (pdu == NULL) {
