    int i = 0;
    while (i < size) {
        struct NFAPI_CRC_INDICATION_PDU_T* pdu_entry = &pdu[i];
        pdu_entry->RX_UE_INFORMATION_TAG.rnti = i + 1; // Use a unique RNTI for each entry
        pdu_entry->CRC_INDICATION_REL8_TAG.crcFlag = (rand() % 2) == 0; // Set CRCFLAG based on pseudo-random value
        i++;
    }

    // Validate that each RNTI is unique across the array
    for (i = 0; i < size - 1; i++) {
        if (pdu[i].RX_UE_INFORMATION_TAG.rnti == pdu[i + 1].RX_UE_INFORMATION_TAG.rnti) {
            fprintf(stderr, "ERROR: Duplicate RNTI detected in array.\n");
            free(pdu); // Free all previously allocated memory if a duplicate is found
            return NULL;
