// Function to check bounds of memory accesses and prevent buffer overflows
void* checkBounds(void* ptr, size_t size) {
    if (ptr == NULL || size == 0) {
        return NULL;
    }
    void* alignedPtr = (void*)((uintptr_t)(ptr) + ((size - 1) & ~(sizeof(long) - 1)));
    if (alignedPtr >= ptr && alignedPtr < ptr + size) {
        return alignedPtr;
    } else {
        printf("Error: Out of bounds memory access\n");
        return NULL;
    }
}

