        memcpy(&pdu->tag, buf + i, sizeof(pdu->tag));
        memcpy(&pdu->sequence_number, buf + i + sizeof(pdu->tag), sizeof(pdu->sequence_number));
        memcpy(&pdu->payload_length, buf + i + 2 * sizeof(pdu->tag), sizeof(pdu->payload_length));

