#include <net/if_arp.h>
#include <arpa/inet.h>
#include "PHY_TASK_STRUCT.h"

struct PHY_TASK_STRUCT* allocate_phy_task_structs(int num_tasks, int max_size) {
    // Check if the requested size exceeds the maximum limit
    if (num_tasks > max_size) {
        printf("Error: Requested number of tasks exceeds maximum allowed\n");
        return NULL;
    }

    // Allocate memory for the array of PHY_TASK_STRUCT structures
    struct PHY_TASK_STRUCT* task_structs = (struct PHY_TASK_STRUCT*)malloc(sizeof(struct PHY_TASK_STRUCT) * num_tasks);
    if (!task_structs) {
        printf("Error: Failed to allocate memory for task structures\n");
        return NULL;
    }

    // Initialize each structure with valid TX/RX parameters
    int i;
    for (i = 0; i < num_tasks; i++) {
        struct PHY_TASK_STRUCT* task = &task_structs[i];

        // Generate pseudo-random MAC and IP addresses based on the current network configuration
        generate_mac_address(&task->tx_params.mac, i);
        generate_ip_address(&task->rx_params.ip, i);

        // Ensure unique port numbers for each structure
        task->rx_params.port = get_unique_port(i);
    }

    return task_structs;
}

// Generate a pseudo-random MAC address based on the current network configuration
void generate_mac_address(unsigned char* mac, int i) {
    struct ifreq ifr;
    strcpy(ifr.ifr_name, "eth0");
    ioctl(SIOCGIFHWADDR, &ifr);

    // Convert the MAC address to a pseudo-random integer
    unsigned long mac_int = 0;
    for (int i = 0; i < 6; i++) {
        mac_int <<= 8;
        mac_int |= ifr.ifr_hwaddr.sa_data[i];
    }

    // Generate a pseudo-random MAC address based on the integer
    for (int i = 0; i < 6; i++) {
        mac[i] = ((mac_int >> (i * 8)) & 0xff) + (i % 2);
    }
}

// Generate a pseudo-random IP address based on the current network configuration
void generate_ip_address(unsigned char* ip, int i) {
    struct ifreq ifr;
    strcpy(ifr.ifr_name, "eth0");
    ioctl(SIOCGIFADDR, &ifr);

    // Convert the IP address to a pseudo-random integer
    unsigned long ip_int = 0;
    for (int i = 0; i < 4; i++) {
        ip_int <<= 8;
        ip_int |= ifr.ifr_addr.sa_data[i];
    }

    // Generate a pseudo-random IP address based on the integer
    for (int i = 0; i < 4; i++) {
        ip[i] = ((ip_int >> (i * 8)) & 0xff) + (i % 2);
    }
}

// Get a unique port number based on the current network configuration
int get_unique_port(int task_index) {
    struct ifreq ifr;
    strcpy(ifr.ifr_name, "eth0");
    ioctl(SIOCGIFFLAGS, &ifr);

    // Calculate the unique port number based on the current network configuration
    int port = 1024 + task_index;
    for (int i = 0; i < ifr.ifr_addr.sa_data[3]; i++) {
        port += (i % 2) * ((port / 2) + 1);
    }

    return port;
}
```
In this implementation, the `allocate_phy_task_structs` function takes in two parameters: `num_tasks`, which is the requested number of structures to allocate, and `max_size`, which is the maximum allowed size of the array. It first checks if the requested size exceeds the maximum limit, and if so, it returns a null pointer.

