#define MAX_NFAPI_CRC_INDICATION_PDU_T 10000 // configurable maximum size limit for the array
#define MAX_RNTI 65535 // maximum value of RNTI (2^16 - 1)

typedef struct {
    uint16_t rnti;
} RX_UE_INFORMATION_TAG;

typedef struct {
    uint8_t crcFlag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rxUeInformationTag;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocateMemoryForArray(int numElements) {
    // validate the requested size against the maximum size limit
    if (numElements > MAX_NFAPI_CRC_INDICATION_PDU_T) {
        fprintf(stderr, "Error: Requested array size exceeds maximum limit of %d\n", MAX_NFAPI_CRC_INDICATION_PDU_T);
        return NULL;
    }

    // initialize the array with valid RNTIs and CRC flags
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(numElements, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < numElements; i++) {
        // generate a random RNTI between 1 and MAX_RNTI
        uint16_t rnti = rand() % (MAX_RNTI - 1) + 1;

        // set the RX_UE_INFORMATION_TAG for each element
        array[i].rxUeInformationTag.rnti = rnti;

        // set the CRC_INDICATION_REL8_TAG for each element based on a pseudo-random value derived from the current system time
        srand(time(NULL));
        uint8_t crcFlag = rand() % 2;
        array[i].crcIndicationRel8Tag.crcFlag = crcFlag;
    }

    // validate that each RNTI is unique across the array
    for (int i = 0; i < numElements - 1; i++) {
        if (array[i].rxUeInformationTag.rnti == array[i + 1].rxUeInformationTag.rnti) {
            fprintf(stderr, "Error: Duplicate RNTI detected in array\n");
            freeMemoryForArray(array);
            return NULL;
        }
    }

    // allocate memory for each element and copy the initialized data
    NFAPI_CRC_INDICATION_PDU_T* newArray = (NFAPI_CRC_INDICATION_PDU_T*)calloc(numElements, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < numElements; i++) {
        newArray[i] = array[i];
    }

    // free the previously allocated memory for the original array
    freeMemoryForArray(array);

    return newArray;
}

void freeMemoryForArray(NFAPI_CRC_INDICATION_PDU_T* array) {
    if (array != NULL) {
        free(array);
    }
}
