#include <pthread.h>

// Structure to represent a NIC statistic
typedef struct nic_statistics {
    mac_header_t mac_header;  // MAC header for the packet
    ip_packet_t ip_packet;    // IP packet with randomly generated payload size
} nic_statistics_t;

// Function to initialize a dynamic array of NIC statistics structures
void init_nic_statistics(int initial_capacity, int growth_factor) {
    // Allocate memory for the array of NIC statistics structures
    nic_statistics_t** stats = (nic_statistics_t**)malloc(sizeof(nic_statistics_t*) * initial_capacity);
    if (!stats) {
        fprintf(stderr, "Error: failed to allocate memory for NIC statistics array\n");
        exit(1);
    }

    // Initialize the memory allocation lock
    pthread_mutex_t* alloc_lock = (pthread_mutex_t*)malloc(sizeof(pthread_mutex_t));
    if (!alloc_lock) {
        fprintf(stderr, "Error: failed to allocate memory for NIC statistics array\n");
        exit(1);
    }
    pthread_mutex_init(alloc_lock, NULL);

    // Initialize the growth factor
    int grow_by = growth_factor;

    // Initialize the current size of the array
    int curr_size = initial_capacity;

    // Initialize the number of elements in the array
    int num_elems = 0;

    // Lock the mutex before modifying the array
    pthread_mutex_lock(alloc_lock);

    // Loop until all the NIC statistics structures are initialized
    while (num_elems < curr_size) {
        // Allocate memory for a new NIC statistics structure
        nic_statistics_t* stat = (nic_statistics_t*)malloc(sizeof(nic_statistics_t));
        if (!stat) {
            fprintf(stderr, "Error: failed to allocate memory for NIC statistics\n");
            exit(1);
        }

        // Initialize the MAC header and IP packet for the new structure
        memset(&stat->mac_header, 0x00, sizeof(mac_header_t));
        memset(&stat->ip_packet, 0x00, sizeof(ip_packet_t));
        stat->mac_header.payload_size = rand() % (grow_by - 1) + 1;

        // Add the new structure to the array
        stats[num_elems] = stat;
        num_elems++;
    }

    // Unlock the mutex after modifying the array
    pthread_mutex_unlock(alloc_lock);
}

// Function to insert a new NIC statistics structure into the array
void insert_nic_statistics(nic_statistics_t* stat) {
    // Check if the memory allocation lock is initialized
    if (!alloc_lock) {
        fprintf(stderr, "Error: NIC statistics array not initialized\n");
        exit(1);
    }

    // Lock the mutex before modifying the array
    pthread_mutex_lock(alloc_lock);

    // Check if the array needs to be resized
    if (num_elems == curr_size) {
        // Reallocate memory for the new size of the array
        nic_statistics_t** new_stats = (nic_statistics_t**)realloc(stats, sizeof(nic_statistics_t*) * (curr_size + grow_by));
        if (!new_stats) {
            fprintf(stderr, "Error: failed to reallocate memory for NIC statistics array\n");
            exit(1);
        }

        // Update the current size of the array and the number of elements
        curr_size += grow_by;
        stats = new_stats;
    }

    // Add the new structure to the array
    stats[num_elems] = stat;
    num_elems++;

    // Unlock the mutex after modifying the array
    pthread_mutex_unlock(alloc_lock);
}

// Function to retrieve a NIC statistics structure from the array
nic_statistics_t* get_nic_statistics(int index) {
    // Check if the memory allocation lock is initialized
    if (!alloc_lock) {
        fprintf(stderr, "Error: NIC statistics array not initialized\n");
        exit(1);
    }

    // Lock the mutex before modifying the array
    pthread_mutex_lock(alloc_lock);

    // Check if the index is within the bounds of the array
    if (index < 0 || index >= num_elems) {
        fprintf(stderr, "Error: invalid index for NIC statistics\n");
        exit(1);
    }

    // Return the requested structure from the array
    nic_statistics_t* stat = stats[index];

    // Unlock the mutex after modifying the array
    pthread_mutex_unlock(alloc_lock);

    return stat;
}
