// Define the dynamic list for efficient insertion, deletion, and modification of shapes
typedef struct {
    int size;
    geometric_shape *data;
} dynamic_list;

// Generate a random seed based on the current time
static unsigned long generate_seed() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
}

// Allocate and initialize a new array of geometric shapes
geometric_shape **allocate_shapes(int size) {
    geometric_shape **array = (geometric_shape **)malloc(sizeof(geometric_shape *) * size);
    memset(array, 0, sizeof(geometric_shape *) * size);
    return array;
}

// Initialize a new shape of the specified type
void initialize_shape(int type, void *data, metadata *metadata, timestamp *timestamp) {
    switch (type) {
        case SHAPE_TYPE_DOUBLE: {
            double *ptr = (double *)data;
            for (int i = 0; i < size; ++i) {
                ptr[i] = generate_random_value();
            }
            break;
        }
        case SHAPE_TYPE_CHAR: {
            char **ptr = (char **)data;
            for (int i = 0; i < size; ++i) {
                ptr[i] = generate_random_string();
            }
            break;
        }
        case SHAPE_TYPE_POINT: {
            point *ptr = (point *)data;
            for (int i = 0; i < size; ++i) {
                ptr[i].x = generate_random_value();
                ptr[i].y = generate_random_value();
            }
            break;
        }
        case SHAPE_TYPE_ENUM: {
            enum *ptr = (enum *)data;
            for (int i = 0; i < size; ++i) {
                ptr[i] = generate_random_value();
            }
            break;
        }
    }
}

// Add a new shape to the hash table and dynamic list
void add_shape(geometric_shape *shape, hash_table *hash_table, dynamic_list *dynamic_list) {
    // Check if the identifier already exists in the hash table
    if (lookup_shape(hash_table, shape->identifier)) {
        printf("Shape with identifier %d already exists\n", shape->identifier);
        return;
    }

    // Add the shape to the hash table and dynamic list
    geometric_shape *new_shape = malloc(sizeof(geometric_shape));
    memcpy(new_shape, shape, sizeof(geometric_shape));
    hash_table->array[shape->identifier] = new_shape;
    dynamic_list->data[dynamic_list->size++] = new_shape;
}

// Lookup a shape in the hash table by its identifier
geometric_shape *lookup_shape(hash_table *hash_table, int identifier) {
    if (identifier < 0 || identifier >= hash_table->size) {
        return NULL;
    }
    geometric_shape *shape = hash_table->array[identifier];
    return shape;
}

// Delete a shape from the hash table and dynamic list
void delete_shape(geometric_shape *shape, hash_table *hash_table, dynamic_list *dynamic_list) {
    // Check if the identifier exists in the hash table
    geometric_shape *existing_shape = lookup_shape(hash_table, shape->identifier);
    if (!existing_shape) {
        printf("Shape with identifier %d does not exist\n", shape->identifier);
        return;
    }

    // Remove the shape from the hash table and dynamic list
    int index = existing_shape - hash_table->array;
    memmove(&hash_table->array[index], &hash_table->array[index + 1], (hash_table->size - index) * sizeof(geometric_shape *));
    hash_table->size--;

    // Remove the shape from the dynamic list
    int list_index = existing_shape - dynamic_list->data;
    memmove(&dynamic_list->data[list_index], &dynamic_list->data[list_index + 1], (dynamic_list->size - list_index) * sizeof(geometric_shape *));
    dynamic_list->size--;
}

// Update a shape in the hash table and dynamic list
void update_shape(geometric_shape *shape, hash_table *hash_table, dynamic_list *dynamic_list) {
    // Check if the identifier exists in the hash table
    geometric_shape *existing_shape = lookup_shape(hash_table, shape->identifier);
    if (!existing_shape) {
        printf("Shape with identifier %d does not exist\n", shape->identifier);
        return;
    }

    // Update the shape in the hash table and dynamic list
    int index = existing_shape - hash_table->array;
    memcpy(&hash_table->array[index], shape, sizeof(geometric_shape));
    dynamic_list->data[index] = shape;
}

// Generate a random value for the given type
void *generate_random_value(int type) {
    void *ptr = NULL;
    switch (type) {
        case SHAPE_TYPE_DOUBLE: {
            double value = generate_seed();
            ptr = malloc(sizeof(double));
            memcpy(ptr, &value, sizeof(double));
            break;
        }
        case SHAPE_TYPE_CHAR: {
            char *value = generate_random_string();
            ptr = malloc(strlen(value) + 1);
            strcpy(ptr, value);
            break;
        }
        case SHAPE_TYPE_POINT: {
            point value = {generate_seed(), generate_seed()};
            ptr = malloc(sizeof(point));
            memcpy(ptr, &value, sizeof(point));
            break;
        }
        case SHAPE_TYPE_ENUM: {
            enum value = generate_seed();
            ptr = malloc(sizeof(enum));
            memcpy(ptr, &value, sizeof(enum));
            break;
        }
    }
    return ptr;
}

// Generate a random string of the given length
