#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <pthread.h>

// Define structure for TCP connection data
struct tcp_connection {
    char client_ip[16];
    unsigned short port;
    char server_ip[16];
    int status;
};

// Function to initialize TCP connections with dummy data
void init_tcp_connections(struct tcp_connection connections[], size_t num_connections) {
    for (size_t i = 0; i < num_connections; ++i) {
        strcpy(connections[i].client_ip, "127.0.0.1");
        connections[i].port = htons(80);
        strcpy(connections[i].server_ip, "localhost");
        connections[i].status = 0;
    }
}

// Function to establish TCP connections with background thread
int establish_tcp_connections(struct tcp_connection connections[], size_t num_connections, int timeout) {
    // Create array of threads for each connection
    pthread_t threads[num_connections];

    // Initialize each thread to establish a connection
    for (size_t i = 0; i < num_connections; ++i) {
        pthread_create(&threads[i], NULL, establish_connection, &connections[i]);
    }

    // Wait for all threads to finish before checking connection status
    for (size_t i = 0; i < num_connections; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Check connection status and update structures accordingly
    int success = 1;
    for (size_t i = 0; i < num_connections; ++i) {
        if (connections[i].status == 0) {
            success = 0;
            break;
        }
    }

    // Return 1 if all connections are successfully established and verified within timeout period, 0 otherwise
    return success;
}

// Function to establish a single TCP connection with retry mechanism
void *establish_connection(void *arg) {
    struct tcp_connection *conn = (struct tcp_connection *) arg;
    int sock = -1;

    // Retry up to three times if connection fails to establish within timeout period
    for (int i = 0; i < 3; ++i) {
        sock = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
        if (sock == -1) {
            perror("socket");
            continue;
        }

        struct sockaddr_in server_addr;
        memset(&server_addr, 0, sizeof(server_addr));
        server_addr.sin_family = AF_INET;
        server_addr.sin_port = htons(conn->port);
        inet_pton(AF_INET, conn->server_ip, &server_addr.sin_addr);

        if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) == -1) {
            perror("connect");
            close(sock);
            continue;
        }

        // Connection established successfully, update status and return
        conn->status = 1;
        return NULL;
    }

    // Failed to establish connection after three retries, update status and return
    conn->status = 0;
    return NULL;
}
```
