void initialize_hash_table(int N, int M) {
    // Allocate memory for the offsets array
    long *offsets = (long *)malloc((N + 1) * sizeof(long));

    // Initialize the offsets array with -1 values
    for (int i = 0; i <= N; i++) {
        offsets[i] = -1;
    }

    // Allocate memory for the keys array and initialize it with random integers within a specified range
