#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "nfapi_crc_indication_pdu_t.h"

// Define the maximum number of elements in the array
#define MAX_N 1000

// Define the size of each structure in bytes
#define SIZEOF_NFAPI_CRC_INDICATION_PDU_T 48

// Define the logging function
void log(const char* message) {
    printf("LOG: %s\n", message);
}

// Define the dynamic array of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T** elements;
    int size;
    int capacity;
} DynamicArray;

// Initialize a new dynamic array
DynamicArray* initDynamicArray(int initialCapacity) {
    // Allocate memory for the array and its elements
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->elements = (NFAPI_CRC_INDICATION_PDU_T**)malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    // Set the initial size and capacity of the array
    array->size = 0;
    array->capacity = initialCapacity;
    return array;
}

// Add a new element to the dynamic array
void addElement(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T* element) {
    // Check if the array is full
    if (array->size == array->capacity) {
        // If so, double the capacity of the array
        array->capacity *= 2;
        array->elements = (NFAPI_CRC_INDICATION_PDU_T**)realloc(array->elements, array->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    }
    // Add the new element to the end of the array
    array->elements[array->size++] = element;
}

// Free all memory allocated by the dynamic array
void freeDynamicArray(DynamicArray* array) {
    for (int i = 0; i < array->size; i++) {
        // Free each structure in the array
        free(array->elements[i]);
    }
    // Free the memory for the elements and the array itself
    free(array->elements);
    free(array);
}

// Populate the dynamic array with up to N elements, where N is a parameter passed to the function
void populateArray(DynamicArray* array, int N) {
    // Ensure that N is within a reasonable range (e.g., between 1 and 1000)
    if (N < 1 || N > MAX_N) {
        return;
    }
    // Populate the array with new elements
    for (int i = 0; i < N; i++) {
        // Allocate memory for a new structure and initialize its fields
        NFAPI_CRC_INDICATION_PDU_T* element = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        element->rx_ue_information_tag = (RX_UE_INFORMATION_TAG) malloc(sizeof(RX_UE_INFORMATION_TAG));
        element->rnti = (RNTI)malloc(sizeof(RNTI));
        element->crc_indication_rel8_tag.crcflag = rand() % 2;
        // Add the new element to the array
        addElement(array, element);
    }
}

// Manage a dynamic array of NFAPI_CRC_INDICATION_PDU_T structures
void manageArray(int N) {
    // Initialize a new dynamic array with an initial capacity of 1000 elements
    DynamicArray* array = initDynamicArray(MAX_N);
    // Populate the array with up to N elements, where N is a parameter passed to the function
    populateArray(array, N);
    // Validate the integrity of each allocated structure
    for (int i = 0; i < array->size; i++) {
        if (!array->elements[i]) {
            log("Invalid element at index %d", i);
        }
    }
    // Free all memory allocated by the dynamic array when it is no longer needed
    freeDynamicArray(array);
}

int main() {
    int N = 10; // The number of elements to add to the array
    manageArray(N);
    return 0;
}
