} MAC_PDU_T;

// Define the function to manage the array of MAC PDUs
int manage_mac_pdus(MAC_PDU_T **mac_pdu_array, int size) {
    // Check if the size is within a reasonable range
    if (size < 1 || size > MAX_SIZE) {
        fprintf(stderr, "Invalid size provided: %d\n", size);
