        mac_pdu_array[i] = (MAC_PDU_T *)malloc(sizeof(MAC_PDU_T));
        if (!mac_pdu_array[i]) {
            fprintf(stderr, "Failed to allocate memory for the %dth MAC PDU\n", i);
            return -1;
        }
    }

    // Validate that each MAC PDU contains a valid preamble type and sequence number
    for (int i = 0; i < size; i++) {
