    if (iv_len > 0) {
        if (!EVP_EncryptInit_ex(ctx, NULL, NULL, NULL, iv)) {
            printf("EVP_EncryptInit_ex failed\n");
            return -1;
        }
    }
    // Securely derive the encryption key from the password using SHA-256
    unsigned char sha_digest[SHA256_DIGEST_LENGTH];
    if (!SHA256(password, strlen(password), sha_digest)) {
        printf("SHA256 failed\n");
        return -1;
    }
    // Use the first 32 bytes of the SHA-256 digest as the encryption key
    unsigned char *key = (unsigned char *) malloc(32);
    memcpy(key, sha_digest, 32);
    // Clean up the SHA-256 digest buffer
    OPENSSL_cleanse(sha_digest, sizeof(sha_digest));
    // Allocate and initialize a cache for the NFAPI_CRC_INDICATION_PDU structures
    struct NFAPI_CRC_INDICATION_PDU_CACHE *cache = NULL;
    if (!(cache = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_CACHE)))) {
        printf("malloc failed\n");
        return -1;
    }
    cache->pdu = (struct NFAPI_CRC_INDICATION_PDU *) malloc(MAX_CRC_INDICATIONS * sizeof(struct NFAPI_CRC_INDICATION_PDU));
    if (!cache->pdu) {
        printf("malloc failed\n");
        return -1;
