        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        } else if (entry->d_type != DT_REG) {
            continue;
        }
        // Open the JSON file and parse its contents into a theme cache
        char *filename = NULL;
        FILE *fp = NULL;
        if (!(filename = malloc(strlen(root_dir) + strlen(entry->d_name) + 1))) {
            printf("malloc failed\n");
            return -1;
        }
        strcpy(filename, root_dir);
        strcat(filename, entry->d_name);
        if (!(fp = fopen(filename, "r"))) {
            printf("fopen failed\n");
            return -1;
        }
        free(filename);
        // Read the JSON file into a buffer and parse its contents
        size_t json_size = 0;
        char *json = NULL;
        if (!(json = malloc(json_size + 1))) {
            printf("malloc failed\n");
            return -1;
        }
        json[json_size] = '\0';
        while ((json_size = getline(&json, &json_size, fp)) != -1) {
            // Add the JSON to the theme cache
            if (addJSONToCache(json, theme_cache) == -1) {
                printf("addJSONToCache failed\n");
                return -1;
            }
        }
        free(json);
        fclose(fp);
    }
    closedir(dir);
    return 0;
