// Function to add a JSON string to the theme cache
int addJSONToCache(char *json, char *theme_cache) {
    // Parse the JSON into an NFAPI_CRC_INDICATION_PDU structure
    struct NFAPI_CRC_INDICATION_PDU pdu;
    if (!nfapi_parse_crc_indication(json, strlen(json), &pdu)) {
