    // Add the NFAPI_CRC_INDICATION_PDU structure to the theme cache
    if (addPDUToCache(&pdu, theme_cache) == -1) {
        printf("addPDUToCache failed\n");
        return -1;
    }
    return 0;
}

// Function to add an NFAPI_CRC_INDICATION_PDU structure to the theme cache
int addPDUToCache(struct NFAPI_CRC_INDICATION_PDU *pdu, char *theme_cache) {
    // Check if the PDU is already in the cache
    for (int i = 0; i < cache->size; ++i) {
        if (memcmp(&pdu, &cache->pdu[i], sizeof(struct NFAPI_CRC_INDICATION_PDU)) == 0) {
            return 0;
        }
    }
    // Add the PDU to the cache and update the cache size
    memcpy(&cache->pdu[cache->size++], pdu, sizeof(struct NFAPI_CRC_INDICATION_PDU));
    return 0;
}']

