struct Record {
    long offset;
    int key;
};

struct MemoryPool {
    size_t capacity;
    size_t count;
    struct Record* records;
};

void initMemoryPool(struct MemoryPool* pool) {
    pool->capacity = 0;
    pool->count = 0;
    pool->records = NULL;
}

int resizeMemoryPool(struct MemoryPool* pool, size_t newCapacity) {
    if (pool->capacity == newCapacity) {
        return 0;
    }
    struct Record* newRecords = realloc(pool->records, newCapacity * sizeof(struct Record));
    if (!newRecords) {
        return -1;
    }
    pool->capacity = newCapacity;
    pool->records = newRecords;
    return 0;
}

int addRecord(struct MemoryPool* pool, long offset, int key) {
    if (pool->count == pool->capacity) {
        size_t newCapacity = pool->capacity ? pool->capacity * 2 : 16;
        resizeMemoryPool(pool, newCapacity);
    }
    pool->records[pool->count].offset = offset;
    pool->records[pool->count].key = key;
    pool->count++;
    return 0;
}

int updateRecord(struct MemoryPool* pool, int index, long offset, int key) {
    if (index < 0 || index >= pool->count) {
        return -1;
    }
    pool->records[index].offset = offset;
    pool->records[index].key = key;
    return 0;
}

int deleteRecord(struct MemoryPool* pool, int index) {
    if (index < 0 || index >= pool->count) {
        return -1;
    }
    pool->count--;
    for (int i = index; i < pool->count; i++) {
        pool->records[i] = pool->records[i + 1];
    }
    return 0;
}

void freeMemoryPool(struct MemoryPool* pool) {
    if (!pool) {
        return;
    }
    free(pool->records);
    initMemoryPool(pool);
}
