using namespace std;

struct NetworkInterfaceControlStatistics {
    mac_header header;
    ip_packet packet;
};

class NicStatsCollection {
public:
    NicStatsCollection(size_t initial_capacity = 0) : capacity_(initial_capacity), size_(0) {}

    ~NicStatsCollection() { clear(); }

    void reserve(size_t new_capacity) {
        if (new_capacity > capacity_) {
            capacity_ = new_capacity;
            stats_.resize(capacity_);
        }
    }

    size_t size() const { return size_; }

    void clear() {
        size_ = 0;
        stats_.clear();
    }

    void add(const mac_header& header, const ip_packet& packet) {
        if (size_ == capacity_) {
            reserve(capacity_ * 2);
        }

        stats_.push_back({header, packet});
        size_++;
    }

    void remove(size_t index) {
        assert(index < size_);
        if (index == size_ - 1) {
            size_--;
        } else {
            swap(stats_[index], stats_.back());
            size_--;
        }
    }

private:
    vector<NetworkInterfaceControlStatistics> stats_;
    size_t capacity_;
    size_t size_;
};
