Java Function:
```java
import java.util.*;
import java.util.stream.*;

public class UnionFind {
    private Map<Integer, Set<Integer>> parent;
    private Map<Integer, Integer> rank;

    public UnionFind(int n) {
        this.parent = new HashMap<>();
        this.rank = new HashMap<>();
        for (int i = 0; i < n; i++) {
            this.parent.put(i, Collections.singleton(i));
            this.rank.put(i, 1);
        }
    }

    public int find(int x) {
        if (!this.parent.containsKey(x)) {
            throw new IllegalArgumentException("Element " + x + " not found");
        }
        return this.parent.get(x).stream().findFirst().orElseThrow();
    }

    public void union(int x, int y) {
        if (!this.parent.containsKey(x) || !this.parent.containsKey(y)) {
            throw new IllegalArgumentException("Element " + x + " or " + y + " not found");
        }

        int rootX = find(x);
        int rootY = find(y);

        if (rootX == rootY) {
            return;
        }

        // union by rank
        if (rank.get(rootX).compareTo(rank.get(rootY)) < 0) {
            parent.put(rootX, Collections.singleton(rootY));
        } else if (rank.get(rootX).compareTo(rank.get(rootY)) > 0) {
            parent.put(rootY, Collections.singleton(rootX));
        } else {
            parent.put(rootY, Collections.singleton(rootX));
            rank.put(rootX, rank.get(rootX).add(1));
        }
    }

    public boolean connected(int x, int y) {
        return find(x) == find(y);
    }
}
