void init_memory_pool(struct memory_pool* pool, size_t capacity) {
    pool->capacity = capacity;
    pool->blocks = calloc(capacity, sizeof(struct memory_block));
}

char* allocate_block(struct memory_pool* pool) {
    for (size_t i = 0; i < pool->capacity; i++) {
        if (!pool->blocks[i].used) {
            return &pool->blocks[i].data;
        }
    }
    return NULL;
}

void free_block(struct memory_pool* pool, char* block) {
    for (size_t i = 0; i < pool->capacity; i++) {
        if (&pool->blocks[i].data == block) {
            pool->blocks[i].used = false;
            return;
        }
    }
}

