    clock_gettime(CLOCK_MONOTONIC, &now);

    // Iterate over the array of traffic flows and remove any that are older than the specified timeout duration
    for (int i = 0; i < numEntries; i++) {
        if ((now.tv_sec - trafficFlows[i].time) > TIMEOUT) {
            // Remove the old entry from the array
            struct TrafficFlow* temp = &trafficFlows[i];
            memmove(temp, temp + 1, (numEntries - i - 1) * sizeof(struct TrafficFlow));
            numEntries--;
        }
    }
}

