// Structures for sensor readings and hash table entries
struct SensorReading {
    double temperature;
    int timestamp;
    char id[5];
};

struct HashTableEntry {
    struct SensorReading *reading;
    struct HashTableEntry *next;
};

// Global variables for hash table and memory management
int num_sensors = 0;
int max_sensors = 1000;
int num_entries = 0;
struct HashTableEntry **table;

// Function to dynamically manage memory for sensor readings
void insertReading(struct SensorReading *reading) {
    // Check if the hash table is full
    if (num_sensors >= max_sensors) {
        // Evict least recently used data or pause new data intake
        // ...
    }

    // Create a new hash table entry and store the reading
    struct HashTableEntry *new_entry = malloc(sizeof(struct HashTableEntry));
    new_entry->reading = reading;
    new_entry->next = NULL;

    // Insert the new entry into the hash table
    int index = hashCode(reading->id);
    if (table[index] == NULL) {
        table[index] = new_entry;
    } else {
        struct HashTableEntry *temp = table[index];
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_entry;
    }

    // Update the number of sensors and entries in the hash table
    num_sensors++;
    num_entries++;
}

// Function to handle sensor readings and perform statistical analysis
void handleReading(struct SensorReading *reading) {
    // Validate and format temperature reading
    if (reading->temperature > 0 && reading->temperature < 100) {
        // Store the validated reading in the hash table
        insertReading(reading);
    } else {
        // Handle missing or invalid data gracefully
        printf("Invalid temperature reading: %f\n", reading->temperature);
    }
}

// Function to perform statistical analysis on temperature data
void analyzeTemperature() {
    // Calculate minimum, maximum, and average temperatures over specified time periods
    int start_time = 0;
    int end_time = 1000;
    double min_temp = INFINITY;
    double max_temp = -INFINITY;
    double sum_temp = 0;

    // Iterate through the hash table entries in the specified time range
    for (int i = start_time; i < end_time; i++) {
        struct HashTableEntry *current = table[i];
        while (current != NULL) {
            if (current->reading->temperature < min_temp) {
                min_temp = current->reading->temperature;
            }
            if (current->reading->temperature > max_temp) {
                max_temp = current->reading->temperature;
            }
            sum_temp += current->reading->temperature;
            current = current->next;
        }
    }

    // Print the statistical analysis results
    printf("Minimum temperature: %f\n", min_temp);
    printf("Maximum temperature: %f\n", max_temp);
    printf("Average temperature: %f\n", sum_temp / num_entries);
}

// Function to handle memory leaks and data corruption
void cleanup() {
    // Free the hash table entries and sensor readings
    for (int i = 0; i < max_sensors; i++) {
        struct HashTableEntry *current = table[i];
        while (current != NULL) {
            free(current->reading);
            current = current->next;
        }
        free(table[i]);
    }

    // Free the hash table and sensor reading buffers
    free(table);
}

// Main function for testing the system
int main() {
    // Initialize the hash table and sensor reading buffers
    table = malloc(max_sensors * sizeof(struct HashTableEntry));
    memset(table, 0, max_sensors * sizeof(struct HashTableEntry));

    // Test the system with multiple sensor readings
    struct SensorReading reading1 = {50.0, 1000, "A"};
    insertReading(&reading1);
    struct SensorReading reading2 = {30.0, 1001, "B"};
    insertReading(&reading2);
    struct SensorReading reading3 = {75.0, 1002, "A"};
    insertReading(&reading3);
    analyzeTemperature();

    // Cleanup and print the final results
    cleanup();
    printf("Final number of sensors: %d\n", num_sensors);
    return 0;
}
