void calculate_checksum(struct IPAddressPacket* ip_packet) {
    // Initialize the checksum field of the IP address packet
    ip_packet->checksum = 0;

    // Calculate the checksum for each byte in the IP address packet
    int checksum = 0;
    for (int i = 0; i < sizeof(struct IPAddressPacket); i++) {
        checksum += ((char*)ip_packet)[i];
    }

    // Set the checksum field of the IP address packet to the calculated value
    ip_packet->checksum = checksum;
