import java.util.Map;

public class DisjointPairsCounter {
    private static final int MAX_ELEMENTS = 1000; // maximum number of elements in the array

    // Define a union-find data structure to keep track of disjoint sets
    private Map<Integer, Integer> parents = new HashMap<>();
    private Map<Integer, Integer> sizes = new HashMap<>();

    public DisjointPairsCounter() {
        for (int i = 0; i < MAX_ELEMENTS; i++) {
            parents.put(i, i);
            sizes.put(i, 1);
        }
    }

    public int countDisjointPairs(int[] array) {
        if (array == null || array.length < 2) {
            return 0;
        }

        int numDisjointPairs = 0;
        for (int i = 0; i < array.length - 1; i++) {
            for (int j = i + 1; j < array.length; j++) {
                // Check if the elements are disjoint
                if (!isDisjoint(array[i], array[j])) {
                    continue;
                }

                // Count the number of disjoint pairs
                numDisjointPairs++;
            }
        }

        return numDisjointPairs;
    }

    private boolean isDisjoint(int a, int b) {
        // Find the root element for each element
        int rootA = findRoot(a);
        int rootB = findRoot(b);

        // Check if the roots are different
        return rootA != rootB;
    }

    private int findRoot(int element) {
        // Find the parent of the current element
        while (element != parents.get(element)) {
            element = parents.get(element);
        }

        return element;
    }
}
