    int level;
    uint32_t refCount;
};

// Data structures for managing dynamic memory allocation and concurrent access
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

static struct LogMessage* logs = NULL;
static size_t logCount = 0;
static bool initialized = false;

// Function to initialize the logging system
void initLogging() {
    pthread_mutex_lock(&mutex);
    if (!initialized) {
        logs = (struct LogMessage*)calloc(1, sizeof(struct LogMessage));
        logCount = 0;
        initialized = true;
    }
    pthread_mutex_unlock(&mutex);
}

// Function to deinitialize the logging system
void deinitLogging() {
    pthread_mutex_lock(&mutex);
    if (initialized) {
        for (size_t i = 0; i < logCount; i++) {
            free(logs[i].message);
        }
        free(logs);
        initialized = false;
    }
    pthread_mutex_unlock(&mutex);
}

// Function to add a new log message
void addLogMessage(const char* message, int level) {
    struct LogMessage* newLog = (struct LogMessage*)calloc(1, sizeof(struct LogMessage));
    newLog->message = strdup(message);
    newLog->level = level;
    newLog->refCount = 0;

    pthread_mutex_lock(&mutex);
    if (logCount == 0) {
        logs[logCount++] = newLog;
    } else {
        bool foundSlot = false;
        for (size_t i = 0; i < logCount; i++) {
            if (logs[i].refCount == 0) {
                logs[i] = *newLog;
                foundSlot = true;
                break;
            }
        }
        if (!foundSlot) {
            struct LogMessage* newArray = (struct LogMessage*)realloc(logs, (logCount + 1) * sizeof(struct LogMessage));
            if (newArray == NULL) {
                free(newLog);
                perror("Failed to allocate memory for log message");
                return;
            }
            logs = newArray;
            logs[logCount++] = *newLog;
        }
    }
    pthread_mutex_unlock(&mutex);
}

// Function to increment the reference count of a log message
void incRefCount(struct LogMessage* log) {
    if (log == NULL) return;
    pthread_mutex_lock(&mutex);
    log->refCount++;
    pthread_mutex_unlock(&mutex);
}

// Function to decrement the reference count of a log message
void decRefCount(struct LogMessage* log) {
    if (log == NULL) return;
    pthread_mutex_lock(&mutex);
    if (log->refCount > 0) {
        log->refCount--;
    }
    pthread_mutex_unlock(&mutex);
}

// Function to get a log message by index
struct LogMessage* getLogMessage(size_t index) {
    if (index >= logCount) return NULL;
    pthread_mutex_lock(&mutex);
    struct LogMessage* log = &logs[index];
    incRefCount(log);
    pthread_mutex_unlock(&mutex);
    return log;
}

// Function to free a log message
void freeLogMessage(struct LogMessage* log) {
    if (log == NULL) return;
    pthread_mutex_lock(&mutex);
    decRefCount(log);
    if (log->refCount == 0) {
        free(log->message);
        free(log);
    }
    pthread_mutex_unlock(&mutex);
}

// Function to send a log message asynchronously to an external logging service
void sendLogMessage(struct LogMessage* log, const char* hostname, uint16_t port) {
    if (log == NULL) return;
    incRefCount(log);

    // Create a socket for sending the log message
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("Failed to create socket");
        decRefCount(log);
        return;
    }

    // Connect the socket to the logging service
    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    if (inet_pton(AF_INET, hostname, &addr.sin_addr) <= 0) {
        perror("Failed to convert IP address");
        decRefCount(log);
        return;
    }
    if (connect(sock, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
        perror("Failed to connect to logging service");
        decRefCount(log);
        return;
    }

    // Send the log message over the socket
    size_t length = strlen(log->message);
    send(sock, log->message, length, 0);

    // Close the socket and decrement the reference count of the log message
    close(sock);
    decRefCount(log);
}

// Function to handle high volumes of logs gracefully by maintaining system responsiveness and scalability
void handleLogsGracefully(struct LogMessage* log, size_t index) {
