#include <stdbool.h>

#define SESSION_QUEUE_SIZE 1024
#define SESSION_METADATA_SIZE 64
#define SESSION_ID_LENGTH 32

typedef struct {
    char session_id[SESSION_ID_LENGTH];
    unsigned long login_time;
    unsigned long last_activity;
} session_metadata_t;

typedef struct {
    bool in_use;
    session_metadata_t metadata;
} session_t;

session_t* sessions[SESSION_QUEUE_SIZE];

int allocate_session(char* session_id) {
    int i = 0;
    while (i < SESSION_QUEUE_SIZE && sessions[i] != NULL) {
        ++i;
    }
    if (i == SESSION_QUEUE_SIZE) {
        return -1;
    } else {
        sessions[i] = malloc(sizeof(session_t));
        strcpy(sessions[i]->session_id, session_id);
        sessions[i]->in_use = true;
        return i;
    }
}

int deallocate_session(char* session_id) {
    int i = 0;
    while (i < SESSION_QUEUE_SIZE && strcmp(sessions[i]->session_id, session_id) != 0) {
        ++i;
    }
    if (i == SESSION_QUEUE_SIZE) {
        return -1;
    } else {
        sessions[i]->in_use = false;
        free(sessions[i]);
        return i;
    }
}

int update_session_metadata(char* session_id, unsigned long login_time, unsigned long last_activity) {
    int i = 0;
    while (i < SESSION_QUEUE_SIZE && strcmp(sessions[i]->session_id, session_id) != 0) {
        ++i;
    }
    if (i == SESSION_QUEUE_SIZE) {
        return -1;
    } else {
        sessions[i]->metadata.login_time = login_time;
        sessions[i]->metadata.last_activity = last_activity;
        return 0;
    }
}

int retrieve_session_metadata(char* session_id, unsigned long* login_time, unsigned long* last_activity) {
    int i = 0;
    while (i < SESSION_QUEUE_SIZE && strcmp(sessions[i]->session_id, session_id) != 0) {
        ++i;
    }
    if (i == SESSION_QUEUE_SIZE) {
        return -1;
    } else {
        *login_time = sessions[i]->metadata.login_time;
        *last_activity = sessions[i]->metadata.last_activity;
        return 0;
    }
}
