Java function for categorizing sessions into active, inactive, and expired states:
```java
import java.util.*;

public class SessionStateMachine {
    private Map<String, Session> sessions;
    private List<Session> activeSessions;
    private List<Session> inactiveSessions;
    private List<Session> expiredSessions;

    public SessionStateMachine() {
        this.sessions = new HashMap<>();
        this.activeSessions = new ArrayList<>();
        this.inactiveSessions = new ArrayList<>();
        this.expiredSessions = new ArrayList<>();
    }

    public void processSession(String sessionId) {
        Session session = sessions.get(sessionId);
        if (session == null) {
            // Session does not exist, create a new one
            session = new Session();
            sessions.put(sessionId, session);
            activeSessions.add(session);
        } else {
            if (session.isExpired()) {
                expireSession(session);
            } else {
                updateSessionState(session);
            }
        }
    }

    private void updateSessionState(Session session) {
        // Check if the session is active or inactive based on its last activity time
        long currentTime = System.currentTimeMillis();
        long lastActivityTime = session.getLastActivityTime();
        if (lastActivityTime + 300000 > currentTime) {
            // Session is active, update the last activity time and add it to the active sessions list
            session.setLastActivityTime(currentTime);
            activeSessions.add(session);
        } else {
            // Session is inactive, add it to the inactive sessions list
            inactiveSessions.add(session);
        }
    }

    private void expireSession(Session session) {
        // Remove the session from the active and inactive sessions lists
        activeSessions.remove(session);
        inactiveSessions.remove(session);
        // Add the session to the expired sessions list
        expiredSessions.add(session);
    }

    public void printSummaryReport() {
        System.out.println("Total number of active sessions: " + activeSessions.size());
        System.out.println("Total number of inactive sessions: " + inactiveSessions.size());
        System.out.println("Total number of expired sessions: " + expiredSessions.size());
    }
}
