// Function to initialize TLS context with client certificate and private key
int tls_init(const char* client_certificate, const char* private_key) {
    // Create SSL_CTX object for TLS context
    SSL_CTX* ctx = SSL_CTX_new(TLS_client_method());
    if (!ctx) {
        fprintf(stderr, "Failed to create SSL_CTX object\n");
        return -1;
    }

    // Load client certificate and private key into SSL_CTX
    if (SSL_CTX_use_certificate_file(ctx, client_certificate, SSL_FILETYPE_PEM) <= 0 ||
            SSL_CTX_use_PrivateKey_file(ctx, private_key, SSL_FILETYPE_PEM) <= 0) {
        fprintf(stderr, "Failed to load client certificate and private key\n");
        SSL_CTX_free(ctx);
        return -1;
    }

    // Set TLS protocol version to TLS 1.3
    if (!SSL_CTX_set_min_proto_version(ctx, TLS1_3_VERSION) ||
            !SSL_CTX_set_max_proto_version(ctx, TLS1_3_VERSION)) {
        fprintf(stderr, "Failed to set TLS protocol version\n");
        SSL_CTX_free(ctx);
        return -1;
    }

    // Create SSL object for TLS connection
    SSL* ssl = SSL_new(ctx);
    if (!ssl) {
        fprintf(stderr, "Failed to create SSL object\n");
        SSL_CTX_free(ctx);
        return -1;
