// Function to perform TLS handshake with a specific TID and UE context ID
int do_handshake(unsigned int tid, unsigned int ue_context_id) {
    // Create SSL_CTX object for TLS context
    SSL_CTX* ctx = SSL_CTX_new(TLS_client_method());
