// Custom namespace for the Mersenne Twister algorithm
namespace my_mersenne_twister {
  // Structure to hold the state of the Mersenne Twister algorithm
  struct twister_state {
    uint32_t seed;
    uint32_t index;
    uint32_t* array;
  };

  // Function to initialize the Mersenne Twister algorithm
  void init(struct twister_state* state) {
    state->seed = 19650218UL;
    state->index = 624;
    state->array = (uint32_t*)malloc(624 * sizeof(uint32_t));
  }

  // Function to generate a random number using the Mersenne Twister algorithm
  uint32_t genrand_int32(struct twister_state* state) {
    if (state->index == 0) {
      init(state);
    }

    uint32_t y;
    const uint32_t mag01[2] = {0, MATRIX_A};
    int kk;

    if (state->index >= 624) {
      state->seed = (state->array[623] & UPPER_MASK) | (state->array[0] & LOWER_MASK);
      for (kk = 0; kk < 623; kk++) {
        state->array[kk] = state->array[kk + 1];
      }
      state->index = 624;
    }

    y = state->seed;

    for (kk = 0; kk < 97; kk++) {
      y ^= (y >> 1) & mag01[kk & 1];
      y ^= (y << 1) & mag01[(kk & 2) / 2];
      y ^= (y << 2) & mag01[(kk & 4) / 4];
      y ^= (y << 4) & mag01[(kk & 8) / 8];
      y ^= (y << 6) & mag01[(kk & 16) / 16];
      y ^= (y << 9) & mag01[(kk & 32) / 32];
      y ^= (y << 18) & mag01[(kk & 64) / 64];
      y ^= (y << 37) & mag01[(kk & 128) / 128];
    }

    state->seed = y;

    return y & MATRIX_A;
  }
}

// Custom namespace for the flexible random number generator
namespace my_random {
  // Structure to hold the state of the flexible random number generator
  struct rand_state {
    struct twister_state* twister;
    size_t array_size;
    int** arrays;
  };

  // Function to initialize the flexible random number generator
  void init(struct rand_state* state) {
    state->twister = (struct twister_state*)malloc(sizeof(struct twister_state));
    my_mersenne_twister::init(state->twister);
    state->array_size = 1024;
    state->arrays = (int**)malloc(state->array_size * sizeof(int*));
    for (size_t i = 0; i < state->array_size; i++) {
      state->arrays[i] = (int*)malloc(1024 * sizeof(int));
    }
  }

  // Function to generate a random integer within the specified range
  int genrand_int32(struct rand_state* state, int low, int high) {
    if (low == high) {
      return low;
    } else if (high < low) {
      return genrand_int32(state, high, low);
    }

    // Calculate the range of random numbers to generate
    size_t count = (size_t)(high - low + 1);

    // Generate a random index within the range
    int idx = genrand_int32(state, 0, count - 1);

    return low + idx;
  }

  // Function to generate a random integer within the specified range and store it in an array
  void genrand_int32_array(struct rand_state* state, int** array, size_t size) {
    for (size_t i = 0; i < size; i++) {
      (*array)[i] = genrand_int32(state, 0, INT_MAX);
    }
  }
}
