        return NULL;
    }
    memset(ht->nodes, 0, ht->size * sizeof(struct Node));
}

// Look-up a record in the hash table using its 'int' key
void *lookup(struct HashTable *ht, int key) {
    // Calculate the index of the node corresponding to the given key
    int index = (key % ht->size);
    struct Node *node = &(ht->nodes[index]);
    if (node->key == 0 || node->key == key) {
        return node;
    } else {
        // If no matching node is found, perform a linear search to find the next available slot
        while (node != NULL && node->key != 0) {
            node = &(ht->nodes[++index]);
            if (node->key == key) {
                return node;
            }
        }
    }
    // If no matching node is found, return NULL to indicate that the record does not exist in the hash table
    return NULL;
}

