void *add(struct HashTable *ht, int key, double value) {
    // Check if the hash table is full by comparing the current count to the size
    if (ht->count == ht->size) {
        // If the hash table is full, resize it by increasing its size by a factor of 2
        int newSize = ht->size * 2;
        struct Node *newNodes = (struct Node *)realloc(ht->nodes, newSize * sizeof(struct Node));
        if (newNodes == NULL) {
            // Handle allocation failure by returning an appropriate error code
            return NULL;
        }
        ht->size = newSize;
        memset(&(ht->nodes[ht->count]), 0, (ht->size - ht->count) * sizeof(struct Node));
    }
    // Calculate the index of the next available slot in the hash table
    int index = (key % ht->size);
    struct Node *node = &(ht->nodes[index]);
    if (node->key == 0) {
        // If an empty slot is found, assign the key and value to it and return a pointer to the node
        node->key = key;
        node->value = value;
        ht->count++;
        return node;
    } else {
        // If no available slot is found, perform a linear search to find the next available slot
        while (node != NULL && node->key != 0) {
            index++;
            node = &(ht->nodes[index]);
            if (node->key == 0) {
                node->key = key;
                node->value = value;
                ht->count++;
                return node;
            }
        }
    }
    // If no available slot is found, return NULL to indicate that the record could not be added to the hash table
    return NULL;
}

// Remove a record from the hash table using its 'int' key
void *remove(struct HashTable *ht, int key) {
    // Calculate the index of the node corresponding to the given key
    int index = (key % ht->size);
    struct Node *node = &(ht->nodes[index]);
    if (node->key == 0 || node->key == key) {
        // If a matching node is found, remove it from the hash table by shifting all subsequent nodes to fill the gap
        for (int i = index; i < ht->size - 1; i++) {
            node = &(ht->nodes[++i]);
            if (node->key == 0) {
                break;
            }
            ht->nodes[i - 1] = *node;
        }
        // Reduce the size of the hash table by a factor of 2 if it is more than half full
        int newSize = ht->size / 2;
