        devices[j].batteryLevel = 0.0f;
    }

    // Check for data quality issues and adaptively adjust processing priorities
    if (avgTemperature < -273.15f || avgHumidity > 100.0f || avgPressure > 100000.0f) {
        // Log the error and reset the device status
        printf("Data quality issue detected. Adjusting processing priorities.\n");
        devices[j].timestamp = 0;
        devices[j].isConnected = false;
        devices[j].batteryLevel = 0.0f;
    }

    // Check for sensor drift over time and incorporate adaptive calibration mechanisms
    if (avgTemperature > 100.0f || avgHumidity > 100.0f || avgPressure > 100000.0f) {
        // Log the error and reset the device status
        printf("Sensor drift detected. Incorporating adaptive calibration mechanisms.\n");
        devices[j].timestamp = 0;
        devices[j].isConnected = false;
        devices[j].batteryLevel = 0.0f;
    }

    // Check for resource exhaustion and limit the number of active sensors at each location
    if (num_readings > 50000) {
        // Log the error and reset the device status
        printf("Resource exhaustion detected. Limiting the number of active sensors at each location.\n");
        devices[j].timestamp = 0;
        devices[j].isConnected = false;
        devices[j].batteryLevel = 0.0f;
    }
}
