```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Profile structure
typedef struct {
    char *name;
    char *email;
    time_t birthday;
    time_t last_login;
    bool active;
} profile_t;

// Hash table for fast look-up of profiles based on email addresses
typedef struct {
    profile_t **buckets;
    int size;
    int count;
} hash_table_t;

// Memory pool for allocating and deallocating memory efficiently
typedef struct {
    void *memory;
    size_t size;
    int free_blocks;
    int used_blocks;
} memory_pool_t;

// Lock-free data structure for concurrent access to the profile manager
typedef struct {
    pthread_mutex_t mutex;
    hash_table_t *profile_hash;
    memory_pool_t *memory_pool;
} profile_manager_t;

// Function prototypes
void init_profile_manager(profile_manager_t *manager);
void destroy_profile_manager(profile_manager_t *manager);
int add_profile(profile_manager_t *manager, const char *name, const char *email, time_t birthday);
int update_profile(profile_manager_t *manager, int profile_id, const char *name, const char *email, time_t birthday);
int delete_profile(profile_manager_t *manager, int profile_id);
profile_t *get_profile(profile_manager_t *manager, int profile_id);
void garbage_collection(profile_manager_t *manager);

// Implementation

void init_profile_manager(profile_manager_t *manager) {
    manager->mutex = PTHREAD_MUTEX_INITIALIZER;
    manager->profile_hash = (hash_table_t *)malloc(sizeof(hash_table_t));
    manager->memory_pool = (memory_pool_t *)malloc(sizeof(memory_pool_t));
}

void destroy_profile_manager(profile_manager_t *manager) {
    free(manager->profile_hash);
    free(manager->memory_pool);
}

int add_profile(profile_manager_t *manager, const char *name, const char *email, time_t birthday) {
    // Acquire lock to avoid concurrent access
    pthread_mutex_lock(&manager->mutex);

    // Allocate memory for the new profile
    profile_t *profile = (profile_t *)malloc(sizeof(profile_t));
    if (!profile) {
        return -1; // Memory allocation failed
    }

    // Initialize the new profile
    strcpy(profile->name, name);
    strcpy(profile->email, email);
    profile->birthday = birthday;
    profile->last_login = time(NULL);
    profile->active = true;

    // Add the new profile to the hash table and memory pool
    int index = email_hash(email) % manager->profile_hash->size;
    manager->profile_hash->buckets[index] = profile;
    manager->memory_pool->used_blocks++;

    // Release lock
    pthread_mutex_unlock(&manager->mutex);

    return 0; // Success
}

int update_profile(profile_manager_t *manager, int profile_id, const char *name, const char *email, time_t birthday) {
    // Acquire lock to avoid concurrent access
    pthread_mutex_lock(&manager->mutex);

    // Find the profile with the given ID
    int index = email_hash(email) % manager->profile_hash->size;
    profile_t *profile = manager->profile_hash->buckets[index];
    if (!profile || profile->id != profile_id) {
        return -1; // Profile not found
    }

    // Update the profile's attributes
    strcpy(profile->name, name);
    strcpy(profile->email, email);
    profile->birthday = birthday;
    profile->last_login = time(NULL);

    // Release lock
    pthread_mutex_unlock(&manager->mutex);

    return 0; // Success
}

int delete_profile(profile_manager_t *manager, int profile_id) {
    // Acquire lock to avoid concurrent access
    pthread_mutex_lock(&manager->mutex);

    // Find the profile with the given ID
    int index = email_hash(email) % manager->profile_hash->size;
    profile_t *profile = manager->profile_hash->buckets[index];
    if (!profile || profile->id != profile_id) {
        return -1; // Profile not found
    }

    // Remove the profile from the hash table and memory pool
    manager->profile_hash->buckets[index] = NULL;
    free(profile);
    manager->memory_pool->used_blocks--;

    // Release lock
    pthread_mutex_unlock(&manager->mutex);

    return 0; // Success
}

profile_t *get_profile(profile_manager_t *manager, int profile_id) {
    // Acquire lock to avoid concurrent access
    pthread_mutex_lock(&manager->mutex);

    // Find the profile with the given ID
    int index = email_hash(email) % manager->profile_hash->size;
    profile_t *profile = manager->profile_hash->buckets[index];
    if (!profile || profile->id != profile_id) {
        return NULL; // Profile not found
    }

    // Release lock
    pthread_mutex_unlock(&manager->mutex);

    return profile; // Success
}

void garbage_collection(profile_manager_t *manager) {
    // Acquire lock to avoid concurrent access
    pthread_mutex_lock(&manager->mutex);

    // Iterate over the hash table and remove inactive profiles
    for (int i = 0; i < manager->profile_hash->size; i++) {
        profile_t *profile = manager->profile_hash->buckets[i];
        if (!profile || !profile->active) {
            // Remove the profile from the hash table and memory pool
            manager->profile_hash->buckets[index] = NULL;
            free(profile);
            manager->memory_pool->used_blocks--;
        }
    }

    // Release lock
    pthread_mutex_unlock(&manager->mutex);
}

int email_hash(const char *email) {
    // Calculate a hash value for the email address
    unsigned long hash = 5381;
    int c;

    while ((c = *email++)) {
        hash = ((hash << 5) + hash) + c;
    }

    return hash % manager->profile_hash->size;
}

void memory_pool_init(memory_pool_t *pool, int size) {
    // Initialize the memory pool
    pool->used_blocks = 0;
    pool->blocks = (void **)malloc(sizeof(void *) * size);
    if (!pool->blocks) {
        return -1; // Memory allocation failed
    }
}

int memory_pool_allocate(memory_pool_t *pool, int size) {
    // Allocate a block of memory from the pool
    void **new_block = (void **)malloc(sizeof(void *) * size);
    if (!new_block) {
        return -1; // Memory allocation failed
    }

    // Add the new block to the list of blocks
    pool->used_blocks++;
    pool->blocks = (void **)realloc(pool->blocks, sizeof(void *) * pool->used_blocks);
    if (!pool->blocks) {
        return -1; // Memory allocation failed
    }

    pool->blocks[pool->used_blocks - 1] = new_block;

    return 0; // Success
}

void memory_pool_free(memory_pool_t *pool) {
    // Free all blocks in the pool
    for (int i = 0; i < pool->used_blocks; i++) {
        free(pool->blocks[i]);
    }

    // Release the memory for the block list
    free(pool->blocks);
}

void *memory_pool_malloc(memory_pool_t *pool, size_t size) {
    // Allocate a block of memory from the pool
    int index = 0;

    if (pool->used_blocks > 0) {
        // Find the first unused block in the list
        for (int i = 0; i < pool->used_blocks; i++) {
            if (!pool->blocks[i]) {
                index = i;
                break;
            }
        }

        // If all blocks are used, allocate a new block
        if (index == 0) {
            memory_pool_allocate(pool, size);

            // Find the first unused block in the list
            for (int i = 0; i < pool->used_blocks; i++) {
                if (!pool->blocks[i]) {
                    index = i;
                    break;
                }
            }
        }
    } else {
        // Allocate a new block for the list
        memory_pool_allocate(pool, size);

        // Find the first unused block in the list
        for (int i = 0; i < pool->used_blocks; i++) {
            if (!pool->blocks[i]) {
                index = i;
                break;
            }
        }
    }

    // Allocate memory within the block
    void *ptr = malloc(size);
    if (!ptr) {
        return NULL; // Memory allocation failed
    }

    // Assign the pointer to the pool
    pool->blocks[index] = ptr;

    return ptr; // Success
}

void memory_pool_free(memory_pool_t *pool, void *ptr) {
    // Find the block that contains the given pointer
    for (int i = 0; i < pool->used_blocks; i++) {
        if (pool->blocks[i] == ptr) {
