public class DisjointPairs {
    public static void main(String[] args) {
        // read the integer array from a file or input stream
        List<Integer> arr = new ArrayList<>();
        for (int i = 0; i < 100; i++) {
            arr.add(i);
        }

        // find the number of disjoint pairs in the array
        long startTime = System.currentTimeMillis();
        int disjointPairs = getDisjointPairs(arr);
        long endTime = System.currentTimeMillis();

        // print the result and time taken to perform the disjointness check
        System.out.println("Number of disjoint pairs: " + disjointPairs);
        System.out.println("Time taken for disjointness check: " + (endTime - startTime) + " ms");
    }

    public static int getDisjointPairs(List<Integer> arr) {
        // use a Union-Find data structure to find the number of disjoint pairs in the array
        int[] unionFind = new int[arr.size()];
        for (int i = 0; i < arr.size(); i++) {
            unionFind[i] = i;
        }

        int disjointPairs = 0;
        for (int i = 0; i < arr.size(); i++) {
            int root1 = find(unionFind, i);
            for (int j = i + 1; j < arr.size(); j++) {
                int root2 = find(unionFind, j);
                if (root1 != root2) {
                    // merge the roots of the two trees
                    unionFind[root1] = unionFind[root2];
                    disjointPairs++;
                }
            }
        }

        return disjointPairs;
    }

    private static int find(int[] unionFind, int i) {
        if (unionFind[i] != i) {
            // path compression optimization
            unionFind[i] = find(unionFind, unionFind[i]);
        }
        return unionFind[i];
    }
}
