int capacity = 1000; // Start with a small capacity

// Add a new entry to the event log
void add_event(long timestamp, int id, char *message) {
  // Check if we need to resize the array
  if (num_events >= capacity) {
    capacity = capacity * 2;
    EventLogEntry **new_array = realloc(event_logs, sizeof(EventLogEntry *) * capacity);
    if (!new_array) {
      fprintf(stderr, "Failed to allocate memory for event log\n");
      return;
    }
    event_logs = new_array;
  }

  // Add the new entry to the array
  EventLogEntry *entry = malloc(sizeof(EventLogEntry));
  if (!entry) {
    fprintf(stderr, "Failed to allocate memory for event log entry\n");
    return;
  }
  entry->timestamp = timestamp;
  entry->id = id;
  entry->message = strdup(message);
  event_logs[num_events++] = entry;
}

// Retrieve an entry from the event log by its identifier
EventLogEntry *get_event(int id) {
  for (int i = 0; i < num_events; i++) {
    if (event_logs[i]->id == id) {
      return event_logs[i];
    }
  }
  return NULL;
}

// Free the memory associated with the event log
void free_event_log() {
  for (int i = 0; i < num_events; i++) {
    EventLogEntry *entry = event_logs[i];
    free(entry->message);
    free(entry);
  }
  free(event_logs);
}
