    char *buffer;
} record_t;

// Function to allocate and initialize a collection of records
record_t* init_records(int max_records, size_t max_key, size_t max_offset, size_t max_string_length) {
    // Calculate the maximum number of records that can be created
    int num_records = (max_records > 0) ? max_records : INT_MAX;

    // Allocate memory for the record structures
    record_t *records = malloc(num_records * sizeof(record_t));

    // Initialize each record structure with a unique key and offset value
    for (int i = 0; i < num_records; i++) {
        records[i].key = rand() % max_key + 1;
        records[i].offset = rand() % max_offset + 1;
        records[i].buffer = malloc(max_string_length);
        strncpy(records[i].buffer, "random string", max_string_length - 1);
    }

    return records;
}

// Function to deallocate memory for the record structures
void free_records(record_t *records) {
    // Free each record structure's buffer
    for (int i = 0; i < records->num_records; i++) {
        free(records[i].buffer);
    }

    // Free the memory allocated for the record structures
    free(records);
}
