    }
}

static void add_crc_indication(CRC_INDICATION_ARRAY_T *arr, const NFAPI_CRC_INDICATION_PDU_T *crc_ind) {
    if (arr->num_elements >= arr->crc_indications_size) {
        arr->crc_indications = realloc(arr->crc_indications, arr->crc_indications_size * 2);
        memset(&arr->crc_indications[arr->num_elements], 0, arr->crc_indications_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    memcpy(&arr->crc_indications[arr->num_elements], crc_ind, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    arr->crc_indications[arr->num_elements].rx_ue_information.rnti = malloc(sizeof(uint16_t));
    *arr->crc_indications[arr->num_elements].rx_ue_information.rnti = rand();
    arr->crc_indications[arr->num_elements].crc_indication_rel8.crccflag = rand() % 2;
    ++arr->num_elements;
}

static void remove_crc_indication(CRC_INDICATION_ARRAY_T *arr, size_t index) {
    if (index >= arr->num_elements) {
        return;
    }
    free(arr->crc_indications[index].rx_ue_information.rnti);
    arr->crc_indications[index].rx_ue_information.rnti = NULL;
    --arr->num_elements;
    if (index < arr->num_elements) {
        memcpy(&arr->crc_indications[index], &arr->crc_indications[arr->num_elements], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
}

static void validate_crc_indication(const NFAPI_CRC_INDICATION_PDU_T *crc_ind) {
    uint16_t checksum = 0;
    for (size_t i = 0; i < crc_ind->rx_ue_information.rnti_size; ++i) {
        checksum += crc_ind->rx_ue_information.rnti[i];
    }
    for (size_t i = 0; i < crc_ind->crc_indication_rel8.length_of_sequence_group; ++i) {
        checksum += crc_ind->crc_indication_rel8.sequence_number[i];
    }
    if (checksum != crc_ind->crc_indication_rel8.checksum) {
        fprintf(stderr, "CRC indication checksum validation failed\n");
        return;
    }
    for (size_t i = 0; i < crc_ind->rx_ue_information.rnti_size; ++i) {
        if (!isValidRNTI(crc_ind->rx_ue_information.rnti[i])) {
            fprintf(stderr, "Invalid RNTI found in CRC indication\n");
            return;
        }
    }
}

void handle_crc_indication(const NFAPI_CRC_INDICATION_PDU_T *crc_ind) {
