    if (num_records > max_records) {
        printf("Error: Too many records requested. Maximum allowed: %lu\n", max_records);
        return;
    }

    // Allocate memory for the two arrays
    long* offsets = malloc(num_records * sizeof(long));
    int* keys = malloc(num_records * sizeof(int));
    record_t* records = malloc(num_records * sizeof(record_t));

    // Handle memory allocation failures gracefully
    if (!offsets || !keys || !records) {
        printf("Error: Failed to allocate memory for arrays. Allocated %lu bytes.\n", (num_records * 3 * sizeof(long)));
        free(offsets);
        free(keys);
