        offsets[i] = rand() % 100000;
        keys[i] = rand() % 100000;
        records[i].value = rand() % 100000;
    }

    // Optimize the function for memory usage and performance
    size_t total_memory = (num_records * 3 * sizeof(long)) + (num_records * sizeof(record_t));
    printf("Allocated %lu bytes of memory.\n", total_memory);

    // Ensure proper resource management and cleanup
    atexit(free_all);

    // Provide fallback strategies for low-memory scenarios
    if (total_memory > 1024 * 1024) {
        printf("Warning: Excessive memory usage. Reducing record array size.\n");
        num_records /= 2;
        total_memory = (num_records * 3 * sizeof(long)) + (num_records * sizeof(record_t));
    }

    // Log successful and failed allocations, total memory usage, and average record size
