use std::sync::Mutex;
use std::fs::File;
use std::io::prelude::*;
use std::error::Error;
use std::env;
use std::path::PathBuf;

struct Record {
    int_value: i32,
    string_id: String,
}

struct RecordCollection {
    records: Vec<Record>,
}

impl RecordCollection {
    fn new() -> Self {
        Self {
            records: Vec::new(),
        }
    }

    fn add(&mut self, int_value: i32, string_id: String) {
        let record = Record {
            int_value,
            string_id,
        };
        self.records.push(record);
    }

    fn serialize(&self) -> Result<(), Box<dyn Error>> {
        let mut file = File::create("data.bin")?;
        for record in &self.records {
            let serialized_record = bincode::serialize(record)?;
            file.write_all(&serialized_record)?;
        }
        Ok(())
    }

    fn deserialize() -> Result<Self, Box<dyn Error>> {
        let mut file = File::open("data.bin")?;
        let mut records = Vec::new();
        loop {
            match bincode::deserialize(&mut file) {
                Ok(record) => records.push(record),
                Err(_) => break,
            }
        }
        Ok(Self { records })
    }
}

fn main() -> Result<(), Box<dyn Error>> {
    let mut collection = RecordCollection::new();
    collection.add(10, "hello".to_string());
    collection.add(20, "world".to_string());
    collection.serialize()?;
    let deserialized_collection = RecordCollection::deserialize()?;
    println!("{:?}", deserialized_collection);
    Ok(())
}
