// C function that initializes a dynamic array of NIC statistics structures
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>

struct nic_stats {
    mac_header mac_header;
    ip_packet ip_packet;
};

struct network_interface {
    struct nic_stats *nic_stats;
    size_t nic_stats_size;
    bool initialized;
};

void init_network_interface(struct network_interface *ni) {
    ni->nic_stats = NULL;
    ni->nic_stats_size = 0;
    ni->initialized = false;
}

bool init_nic_stats(struct nic_stats *nic_stats, size_t size) {
    // Allocate memory for the NIC statistics structures
    nic_stats->mac_header = malloc(size);
    if (nic_stats->mac_header == NULL) {
        return false;
    }

    nic_stats->ip_packet = malloc(size);
    if (nic_stats->ip_packet == NULL) {
        free(nic_stats->mac_header);
        return false;
    }

    // Initialize the MAC and IP packets with random payloads and checksums
    for (int i = 0; i < size; i++) {
        mac_header *mac_header = &nic_stats[i].mac_header;
        ip_packet *ip_packet = &nic_stats[i].ip_packet;

        // Generate random payload and checksum for the MAC header
        generate_random_payload(&mac_header->payload, mac_header->length);
        mac_header->checksum = calculate_checksum(mac_header->payload, mac_header->length);

        // Generate random payload and checksum for the IP packet
        generate_random_payload(&ip_packet->payload, ip_packet->length);
        ip_packet->checksum = calculate_checksum(ip_packet->payload, ip_packet->length);
    }

    return true;
}

void destroy_nic_stats(struct nic_stats *nic_stats, size_t size) {
    // Free the memory allocated for the NIC statistics structures
    free(nic_stats->mac_header);
    free(nic_stats->ip_packet);
}

bool grow_nic_stats(struct network_interface *ni) {
    // Double the size of the dynamic array
    ni->nic_stats_size = 2 * ni->nic_stats_size;

    // Allocate memory for the new NIC statistics structures
    struct nic_stats *new_nic_stats = malloc(ni->nic_stats_size);
    if (new_nic_stats == NULL) {
        return false;
    }

    // Copy the contents of the old NIC statistics structures to the new ones
    memcpy(new_nic_stats, ni->nic_stats, ni->nic_stats_size / 2);

    // Free the memory allocated for the old NIC statistics structures
    free(ni->nic_stats);

    // Update the pointer and size of the dynamic array
    ni->nic_stats = new_nic_stats;
}

bool allocate_nic_stats(struct network_interface *ni, size_t size) {
    if (size > 70 * total_system_ram()) {
        // Use a slower, but memory-efficient, allocation strategy
        ni->nic_stats = malloc(size);
        if (ni->nic_stats == NULL) {
            return false;
        }
    } else {
        // Allocate the memory for the NIC statistics structures using the default allocator
        ni->nic_stats = calloc(size, sizeof(struct nic_stats));
        if (ni->nic_stats == NULL) {
            return false;
        }
    }

    ni->nic_stats_size = size;

    return true;
}

bool deallocate_nic_stats(struct network_interface *ni) {
    // Free the memory allocated for the NIC statistics structures
    free(ni->nic_stats);

    ni->nic_stats = NULL;
    ni->nic_stats_size = 0;

    return true;
}

bool initialize_network_interface(struct network_interface *ni) {
    // Initialize the dynamic array of NIC statistics structures
    if (!allocate_nic_stats(ni, 1)) {
        return false;
    }

    // Initialize the first element in the dynamic array with random MAC and IP packets
    if (!init_nic_stats(ni->nic_stats, 1)) {
        destroy_nic_stats(ni->nic_stats, ni->nic_stats_size);
        return false;
    }

    // Set the initialized flag to true
    ni->initialized = true;

    return true;
}

void destroy_network_interface(struct network_interface *ni) {
    // Destroy the dynamic array of NIC statistics structures
    deallocate_nic_stats(ni);
}

// Java function that calculates the number of disjoint pairs of elements in an integer array
#include <java.lang.Integer>

public class UnionFind {
  private int[] parent;
  private int[] rank;
  private int count;

  public UnionFind(int size) {
    this.parent = new int[size];
    this.rank = new int[size];
    this.count = size;

    for (int i = 0; i < size; i++) {
      parent[i] = i;
      rank[i] = 1;
    }
  }

  public int find(int p) {
    while (p != parent[p]) {
      parent[p] = find(parent[p]);
      p = parent[p];
    }
    return p;
  }

  public void union(int p, int q) {
    int rootP = find(p);
    int rootQ = find(q);

    if (rootP == rootQ) {
      return;
    }

    count--;

    if (rank[rootP] < rank[rootQ]) {
      parent[rootP] = rootQ;
    } else if (rank[rootP] > rank[rootQ]) {
      parent[rootQ] = rootP;
    } else {
      parent[rootQ] = rootP;
      rank[rootP]++;
    }
  }
}

// Java function that checks whether two elements are in the same connected component or not
public boolean connected(int p, int q) {
  return find(p) == find(q);
}

// Java function that connects two elements and returns the new count of connected components
public int connect(int p, int q) {
  union(p, q);
  return count;
}
