### C++ Code: Union Find

```cpp
#include <iostream>
#include <vector>
using namespace std;

struct Node{
    int parent;
    int rank;
};

// Union Find Functions
Node* create(int size){
    Node *nodes = new Node[size];
    for(int i=0;i<size;i++){
        nodes[i].parent = i;
        nodes[i].rank = 1;
    }
    return nodes;
}

int find(Node* nodes, int p){
    if(p == nodes[p].parent)
        return p;
    else{
        nodes[p].parent = find(nodes, nodes[p].parent);
        return nodes[p].parent;
    }
}

void union(Node* nodes, int p, int q){
    int rootP = find(nodes, p);
    int rootQ = find(nodes, q);

    if(rootP == rootQ)
        return;

    else{
        if(nodes[rootP].rank < nodes[rootQ].rank)
            nodes[rootP].parent = rootQ;
        else if(nodes[rootP].rank > nodes[rootQ].rank)
            nodes[rootQ].parent = rootP;
        else{
            nodes[rootQ].parent = rootP;
            nodes[rootP].rank++;
        }
    }
}

// Main Function
int main(){
    int n, m;
    cin >> n >> m;

    Node* nodes = create(n);

    for(int i=0;i<m;i++){
        int p, q;
        cin >> p >> q;

        if(!connected(nodes, p, q)){
            union(nodes, p, q);
            cout << "New count: " << connectedComponents(nodes) << endl;
        }
    }

    delete[] nodes;
}
