    entry_t entries[NUM_ENTRIES];
    bool flags[NUM_ENTRIES];
    char* labels[NUM_ENTRIES];
} data_structures_t;

// Function to initialize the data structures and allocate memory for them
data_structures_t* init_data_structures() {
    data_structures_t* data = malloc(sizeof(data_structures_t));
    if (data == NULL) {
        printf("Error: failed to allocate memory for data structures\n");
        return NULL;
    }

    // Initialize the offset and key arrays
    data->offset = calloc(NUM_ENTRIES, sizeof(long));
    data->key = calloc(NUM_ENTRIES, sizeof(int));
    if (data->offset == NULL || data->key == NULL) {
        printf("Error: failed to allocate memory for offset and key arrays\n");
        free(data);
        return NULL;
    }

    // Initialize the entry structures and nested structures
    data->entries = calloc(NUM_ENTRIES, sizeof(entry_t));
    if (data->entries == NULL) {
        printf("Error: failed to allocate memory for entry structures\n");
        free(data->offset);
        free(data->key);
        free(data);
        return NULL;
    }
    data->flags = calloc(NUM_ENTRIES, sizeof(bool));
    if (data->flags == NULL) {
        printf("Error: failed to allocate memory for flag array\n");
        free(data->entries);
        free(data->offset);
        free(data->key);
        free(data);
        return NULL;
    }
    data->labels = calloc(NUM_ENTRIES, sizeof(char*));
    if (data->labels == NULL) {
        printf("Error: failed to allocate memory for label array\n");
        free(data->flags);
        free(data->entries);
        free(data->offset);
        free(data->key);
        free(data);
        return NULL;
    }

    // Initialize the nested structures within each entry structure
    for (int i = 0; i < NUM_ENTRIES; i++) {
        data->entries[i].nested_structures = calloc(NUM_NESTED_STRUCTURES, sizeof(complex_structure));
        if (data->entries[i].nested_structures == NULL) {
            printf("Error: failed to allocate memory for nested structures\n");
            free(data->labels);
            free(data->flags);
            free(data->entries);
            free(data->offset);
            free(data->key);
            free(data);
            return NULL;
        }
    }

    // Populate the strings within each entry structure
    for (int i = 0; i < NUM_ENTRIES; i++) {
        int string_length = rand() % MAX_STRING_LENGTH + 1;
        data->entries[i].string = malloc(string_length * sizeof(char));
        if (data->entries[i].string == NULL) {
            printf("Error: failed to allocate memory for string\n");
            free(data->labels);
            free(data->flags);
            free(data->entries);
            free(data->offset);
            free(data->key);
            free(data);
            return NULL;
        }
        for (int j = 0; j < string_length; j++) {
            data->entries[i].string[j] = 'a' + rand() % ('z' - 'a');
        }
    }

    // Initialize the flags and labels arrays
    for (int i = 0; i < NUM_ENTRIES; i++) {
        data->flags[i] = false;
        data->labels[i] = NULL;
    }

    return data;
}

// Function to free the memory allocated by the init_data_structures function
void free_data_structures(data_structures_t* data) {
    if (data == NULL) {
        return;
    }

    // Free the nested structures within each entry structure
    for (int i = 0; i < NUM_ENTRIES; i++) {
        free(data->entries[i].nested_structures);
    }

    // Free the labels array
    free(data->labels);

    // Free the flags array
    free(data->flags);

    // Free the entry structures
    free(data->entries);

    // Free the offset and key arrays
    free(data->offset);
    free(data->key);

    // Free the data_structures_t struct
    free(data);
}

// Main function to demonstrate the use of the init_data_structures and free_data_structures functions
int main() {
    // Initialize the data structures and allocate memory for them
    data_structures_t* data = init_data_structures();
    if (data == NULL) {
        printf("Error: failed to initialize data structures\n");
        return 1;
    }

    // Use the data structures concurrently in different threads
    #pragma omp parallel for num_threads(NUM_THREADS) shared(data) default(none)
    for (int i = 0; i < NUM_ENTRIES; i++) {
        // Do some work with the entry structure and nested structures
        printf("Thread %d: working on entry %d\n", omp_get_thread_num(), i);
        sleep(1);
    }

    // Free the memory allocated by the init_data_structures function
    free_data_structures(data);

    return 0;
}
```
This code will initialize an array of `NUM_ENTRIES` entry structures, each containing a string, an integer, and an array of nested complex structures. It will also allocate memory for the offset and key arrays. The function `init_data_structures()` returns a pointer to the initialized data structures if successful, or NULL otherwise.

The main function demonstrates the use of the `init_data_structures` function to initialize an array of entry structures and the nested complex structures within them. It also shows how to use OpenMP's `#pragma omp parallel for` directive to execute a loop concurrently in different threads, using the shared variable `data`. The function `free_data_structures()` frees the memory allocated by the `init_data_structures` function when it is no longer needed.

Note that this code uses OpenMP's `#pragma omp parallel for` directive to execute a loop concurrently in different threads, using the shared variable `data`. This means that multiple threads can access and modify the same data structures simultaneously. However, if you are going to use OpenMP, it is important to make sure that your data structures are thread-safe, meaning they can be accessed and modified by multiple threads without causing any problems.']

