// Custom hash table for efficient storage and retrieval of records
typedef struct {
  int size; // Size of the hash table
  int count; // Number of elements in the hash table
  Record* records[]; // Array of record pointers
} HashTable;

// Structure to hold information about a record
typedef struct {
  long offset; // Offset value for the record
  int key; // Key value for the record
  double value; // Value value for the record
  AES_CTX* ctx; // Encryption context for the record
} Record;

// Function to allocate and initialize records
Record** allocate_and_init_records(int num_records, int max_limit) {
  if (num_records > max_limit) {
    return NULL;
  }

  // Allocate memory for the record arrays
  Record** records = malloc(sizeof(Record*) * num_records);
  if (!records) {
    return NULL;
  }

  // Initialize the offset, key, and value arrays
  long* offsets = malloc(sizeof(long) * num_records);
  int* keys = malloc(sizeof(int) * num_records);
  double* values = malloc(sizeof(double) * num_records);
  if (!offsets || !keys || !values) {
    free(records);
    return NULL;
  }

  // Initialize the encryption contexts for each record
  AES_CTX** ctxs = malloc(sizeof(AES_CTX*) * num_records);
  if (!ctxs) {
    free(records);
    free(offsets);
    free(keys);
    free(values);
    return NULL;
  }

  // Initialize the hash table
  HashTable* table = malloc(sizeof(HashTable));
  if (!table) {
    free(records);
    free(offsets);
    free(keys);
    free(values);
    free(ctxs);
    return NULL;
  }

  // Initialize the hash table parameters
  table->size = num_records;
  table->count = 0;
  table->records = records;

  // Iterate over each record and initialize it
  for (int i = 0; i < num_records; i++) {
    // Allocate memory for the current record
    Record* curr = malloc(sizeof(Record));
    if (!curr) {
      free(records);
      free(offsets);
      free(keys);
      free(values);
      free(ctxs);
      return NULL;
    }

    // Initialize the current record's offset, key, and value
    curr->offset = offsets[i];
    curr->key = keys[i];
    curr->value = values[i];
    curr->ctx = ctxs[i];

    // Add the current record to the hash table
    int index = i % table->size;
    table->records[index] = curr;
  }

  return records;
}
