        struct PressureReading *reading = &readings[i];
        if (reading->sensor_index >= 0 && reading->sensor_index < num_sensors) {
            // Update the pressure reading for the specified sensor
            sensor_config[reading->sensor_index] = reading->pressure;
        } else {
            // Default value for missing or invalid data
            sensor_config[0] = -1;
        }
    }

    // Validate and format pressure readings to ensure they fall within specified ranges
    for (int i = 0; i < num_sensors; i++) {
        if (sensor_config[i] != -1) {
