#include <string.h>
#include <stdio.h>
#include <pthread.h>
#include <errno.h>
#include <math.h>

#define MAX_RECORDS 1000000 // maximum number of records allowed
#define MIN_RANGE -1000 // minimum value range for integers and floats
#define MAX_RANGE 1000 // maximum value range for integers and floats

typedef struct {
    int key;
    long offset;
} record;

struct DataStructuresManager {
    pthread_mutex_t mutex; // synchronization primitive for thread safety
    record* records; // array of records
    size_t numRecords; // number of records in the array
    int initialized; // flag indicating if the data structure has been initialized
};

void DataStructuresManager_init(struct DataStructuresManager *ds) {
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    pthread_mutex_init(&ds->mutex, &attr);
    ds->records = (record*)malloc(sizeof(record) * MAX_RECORDS);
    if (!ds->records) {
        perror("malloc");
        exit(1);
    }
    ds->numRecords = 0;
    ds->initialized = 1;
}

void DataStructuresManager_destroy(struct DataStructuresManager *ds) {
    pthread_mutex_destroy(&ds->mutex);
    free(ds->records);
    ds->numRecords = 0;
    ds->initialized = 0;
}

void DataStructuresManager_addRecord(struct DataStructuresManager *ds, int key, long offset) {
    pthread_mutex_lock(&ds->mutex);
    if (ds->numRecords >= MAX_RECORDS) {
        fprintf(stderr, "Maximum number of records exceeded\n");
        exit(1);
    }
    record* newRecord = &ds->records[ds->numRecords++];
    newRecord->key = key;
    newRecord->offset = offset;
    pthread_mutex_unlock(&ds->mutex);
}

void DataStructuresManager_removeRecord(struct DataStructuresManager *ds, int key) {
    pthread_mutex_lock(&ds->mutex);
    for (size_t i = 0; i < ds->numRecords; ++i) {
        if (ds->records[i].key == key) {
            record* removedRecord = &ds->records[i];
            --ds->numRecords;
            if (i != ds->numRecords) {
                memcpy(removedRecord, removedRecord + 1, sizeof(record));
            }
            break;
        }
    }
    pthread_mutex_unlock(&ds->mutex);
}

void DataStructuresManager_serialize(struct DataStructuresManager *ds) {
    FILE* f = fopen("data.bin", "wb");
    if (!f) {
        perror("fopen");
        exit(1);
    }
    pthread_mutex_lock(&ds->mutex);
    fwrite(&ds->numRecords, sizeof(size_t), 1, f);
    for (size_t i = 0; i < ds->numRecords; ++i) {
        fwrite(&ds->records[i].key, sizeof(int), 1, f);
        fwrite(&ds->records[i].offset, sizeof(long), 1, f);
    }
    pthread_mutex_unlock(&ds->mutex);
    fclose(f);
}

void DataStructuresManager_deserialize(struct DataStructuresManager *ds) {
    FILE* f = fopen("data.bin", "rb");
    if (!f) {
        perror("fopen");
        exit(1);
    }
    pthread_mutex_lock(&ds->mutex);
    size_t numRecords;
    fread(&numRecords, sizeof(size_t), 1, f);
    if (numRecords > MAX_RECORDS) {
        fprintf(stderr, "Deserialized data structure has more than %d records\n", MAX_RECORDS);
        exit(1);
    }
    ds->numRecords = numRecords;
    for (size_t i = 0; i < ds->numRecords; ++i) {
        int key;
        long offset;
        fread(&key, sizeof(int), 1, f);
        fread(&offset, sizeof(long), 1, f);
        record* newRecord = &ds->records[i];
        newRecord->key = key;
        newRecord->offset = offset;
    }
    pthread_mutex_unlock(&ds->mutex);
    fclose(f);
}

void DataStructuresManager_validate(struct DataStructuresManager *ds) {
    size_t numRecords = ds->numRecords;
    for (size_t i = 0; i < numRecords; ++i) {
        record* currRecord = &ds->records[i];
        if (currRecord->key > MAX_RANGE || currRecord->offset > MAX_RANGE) {
            fprintf(stderr, "Data corruption detected\n");
            exit(1);
        }
    }
}

int DataStructuresManager_generateRandomInt(struct DataStructuresManager *ds, int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

float DataStructuresManager_generateRandomFloat(struct DataStructuresManager *ds, float min, float max) {
    return (float)(min + ((double)(rand() % RAND_MAX) / RAND_MAX) * (max - min));
}

void DataStructuresManager_overrideToString(struct DataStructuresManager *ds, char* buf, size_t size) {
    snprintf(buf, size, "DataStructuresManager: %zu records\n", ds->numRecords);
}
