// Define the structure to store network interface statistics
typedef struct {
    MACHeader* mac_header;
    IPAddressPacket* ip_packet;
    char* identifier;
} NetworkInterfaceStatistics;

// Define a custom memory pool allocator for efficient memory management
struct MemoryPool {
    void* memory;
    size_t capacity;
    size_t usage;
};

// Define the synchronization primitives for concurrent access to the array
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

// Define the function to serialize and deserialize network interface statistics
void serializeNetworkData(NetworkInterfaceStatistics* stats, size_t num_stats) {
    // Create a custom memory pool allocator for efficient memory management
    struct MemoryPool* mempool = createMemoryPool();

    // Set up the serialization structure
    SerializationState state;
    state.mempool = mempool;
    state.num_stats = num_stats;

    // Serialize the network interface statistics
    for (size_t i = 0; i < state.num_stats; i++) {
        NetworkInterfaceStatistics* curr_stat = &(state.stats[i]);
        serializeNetworkInterfaceStatistics(curr_stat, mempool);
    }

    // Deserialize the network interface statistics
    for (size_t i = 0; i < state.num_stats; i++) {
        NetworkInterfaceStatistics* curr_stat = &(state.stats[i]);
        deserializeNetworkInterfaceStatistics(curr_stat, mempool);
    }

    // Clean up the memory pool allocator
    destroyMemoryPool(mempool);
}

// Define the function to dynamically resize the array to accommodate additional entries as needed
void growArray(size_t new_size) {
    pthread_mutex_lock(&mutex);
    size_t curr_size = stats.capacity;
    if (new_size > curr_size) {
        stats.capacity = new_size;
        stats.arr = realloc(stats.arr, sizeof(NetworkInterfaceStatistics) * stats.capacity);
        for (size_t i = curr_size; i < stats.capacity; i++) {
            NetworkInterfaceStatistics* curr_stat = &(stats.arr[i]);
            initNetworkInterfaceStatistics(curr_stat);
        }
    }
    pthread_mutex_unlock(&mutex);
}

// Define the function to manage the network interface statistics array
void manageArray() {
    // Set up the synchronization primitives for concurrent access
    pthread_cond_wait(&cond, &mutex);

    // Resize the array if necessary
    size_t new_size = stats.usage + 1;
    growArray(new_size);

    // Add a new entry to the array
    NetworkInterfaceStatistics* new_stat = &(stats.arr[stats.usage++]);
    initNetworkInterfaceStatistics(new_stat);

    // Update the serialization structure
    state.num_stats++;
    state.stats = realloc(state.stats, sizeof(NetworkInterfaceStatistics) * state.num_stats);
    state.stats[state.num_stats - 1] = new_stat;

    // Unlock the mutex and signal the condition variable
    pthread_mutex_unlock(&mutex);
    pthread_cond_signal(&cond);
}

// Define the function to serialize a single network interface statistics entry
void serializeNetworkInterfaceStatistics(NetworkInterfaceStatistics* stat, struct MemoryPool* mempool) {
    // Calculate the payload size for the IP packet
    size_t payload_size = randomPayloadSize();

    // Serialize the MAC header
    serializeMACHeader(&(stat->mac_header), mempool);

    // Serialize the IP address packet
    serializeIPAddressPacket(&(stat->ip_packet), payload_size, mempool);

    // Serialize the unique identifier for the statistics
    stat->identifier = serializeIdentifier(mempool);
}

// Define the function to deserialize a single network interface statistics entry
void deserializeNetworkInterfaceStatistics(NetworkInterfaceStatistics* stat, struct MemoryPool* mempool) {
    // Deserialize the MAC header
    deserializeMACHeader(&(stat->mac_header), mempool);

    // Deserialize the IP address packet
    deserializeIPAddressPacket(&(stat->ip_packet), mempool);

    // Deserialize the unique identifier for the statistics
    stat->identifier = deserializeIdentifier(mempool);
}

// Define the function to calculate a random payload size for an IP packet
size_t randomPayloadSize() {
    return rand() % (max_payload_size - min_payload_size) + min_payload_size;
}

// Define the function to initialize a network interface statistics entry
void initNetworkInterfaceStatistics(NetworkInterfaceStatistics* stat) {
    stat->mac_header = NULL;
    stat->ip_packet = NULL;
    stat->identifier = NULL;
}
