void *crcIndicationThread(void *arg) {
  NFAPI_CRC_INDICATION_PDU_T *pdu = arg;

  // Simulate a background process that takes some time to complete
  sleep(2);

  // Set the CRC indication flag value based on the integer
  pdu->crc_indication_rel8_tag = (unsigned char)((pdu->rnti * 100) % 256);
