  aes256_init(ctx->ctx, iv);
}

// Function to generate an IV for a PDCCH identifier
void generateIV(uint8_t* iv, int cellID) {
  // Generate a salted hash of the PDCCH identifier using SHA-256
  uint8_t salt[AES_BLOCK_SIZE];
  sha256(salt, (const unsigned char*)&cellID, sizeof(int));

  // XOR the salt with a random IV to generate the final IV
  for (int i = 0; i < AES_BLOCK_SIZE; ++i) {
    iv[i] = rand() ^ salt[i];
  }
}

// Function to decode a PDCCH message using a decoder context
void decodePDCCH(DecoderContext* ctx, const uint8_t* msg, int len) {
  // Decrypt the message using the decoder context
  aes256_cbc_decrypt(ctx->ctx, msg, len);

  // Parse the decrypted message and extract the control messages
  vector<ControlMessage> decodedMessages = parseDecodedMessages(msg, len);

  // Store the decoded messages in the decoding task
  PDCCHDecodingTask* task = getCurrentDecodingTask();
  task->decodedMessages.insert(task->decodedMessages.end(), decodedMessages.begin(), decodedMessages.end());
}

// Function to handle a PDCCH decoding task
void handlePDCCHDecodingTask(const PDCCHDecodingTask& task) {
  // Initialize a decoder context with an IV generated from the PDCCH identifier
  DecoderContext ctx;
  generateIV(ctx.iv, task.cellID);
  initDecoderContext(&ctx, ctx.iv);

  // Decode the PDCCH message using the decoder context
  decodePDCCH(&ctx, task.msg, task.len);
}

// Function to manage a list of PDCCH decoding tasks
void managePDCCHDecodingTasks(vector<PDCCHDecodingTask>& tasks) {
  // Create a thread-safe pool of decoder contexts
  vector<shared_ptr<DecoderContext>> ctxPool;

  // Iterate over the PDCCH decoding tasks and decode them concurrently
  for (const auto& task : tasks) {
    // Get a free decoder context from the pool or create a new one if necessary
    shared_ptr<DecoderContext> ctx;
    if (!ctxPool.empty()) {
      ctx = ctxPool.back();
      ctxPool.pop_back();
    } else {
      ctx = make_shared<DecoderContext>();
      initDecoderContext(ctx.get(), ctx->iv);
    }

    // Enqueue the decoding task and spawn a new thread to handle it
    thread t(&handlePDCCHDecodingTask, task);
    t.detach();
  }

  // Wait for all threads to complete and free their resources
  while (!ctxPool.empty()) {
    ctxPool.back()->~shared_ptr();
    ctxPool.pop_back();
  }
}

// Function to optimize memory management for PDCCH decoding tasks
void optimizePDCCHDecodingMemoryManagement(vector<PDCCHDecodingTask>& tasks) {
  // Create a smart pointer pool for the decoder contexts
  vector<unique_ptr<DecoderContext>> ctxPool;

  // Iterate over the PDCCH decoding tasks and allocate memory for their resources
  for (const auto& task : tasks) {
    // Get a free decoder context from the pool or create a new one if necessary
    unique_ptr<DecoderContext> ctx;
    if (!ctxPool.empty()) {
      ctx = move(ctxPool.back());
      ctxPool.pop_back();
    } else {
