// Define the record structure
typedef struct {
    long offset;
    int key;
    char buffer[256]; // Cap the buffer size to 256 characters
} record;

// Function to dynamically allocate memory for and initialize a variable number of records
record* init_records(int num_records, int min_key, int max_key) {
    // Validate input parameters
    if (num_records < 0 || min_key < 0 || max_key < 0) {
        return NULL;
    }

    // Allocate memory for the record array
    record* records = malloc(num_records * sizeof(record));
    if (!records) {
        fprintf(stderr, "Error: failed to allocate memory for records\n");
        return NULL;
    }

    // Initialize each record structure with a random key and buffer size
    srand(time(NULL)); // Seed the RNG for reproducible results
    for (int i = 0; i < num_records; i++) {
        records[i].offset = i * sizeof(record);
        records[i].key = rand() % (max_key - min_key + 1) + min_key;
        memset(records[i].buffer, 0, sizeof(records[i].buffer)); // Zero out the buffer
    }

    return records;
}
```
