#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    long offset;
    int key;
    double precision;
    char* string_key;
} Record;

// Define the hash table data structure
typedef struct {
    // Array of records
    Record** records;

    // Number of records in the table
    int num_records;

    // Size of the record array
    int capacity;

    // Lock for concurrent access
    pthread_mutex_t lock;
} HashTable;

// Initialize the hash table
void init_hash_table(HashTable* table) {
    // Allocate memory for the records array
    table->records = (Record**)malloc(sizeof(Record*) * 10);

    // Set the number of records to 0
    table->num_records = 0;

    // Set the capacity to 10
    table->capacity = 10;

    // Initialize the lock
    pthread_mutex_init(&table->lock, NULL);
}

// Add a record to the hash table
void add_record(HashTable* table, long offset, int key, double precision, char* string_key) {
    // Acquire the lock
    pthread_mutex_lock(&table->lock);

    // Check if the table needs to be resized
    if (table->num_records >= table->capacity) {
        // Resize the records array
        table->records = (Record**)realloc(table->records, sizeof(Record*) * 2 * table->capacity);

        // Update the capacity
        table->capacity *= 2;
    }

    // Create a new record
    Record* new_record = (Record*)malloc(sizeof(Record));
    new_record->offset = offset;
    new_record->key = key;
    new_record->precision = precision;
    new_record->string_key = string_key;

    // Add the record to the hash table
    table->records[table->num_records++] = new_record;

    // Release the lock
    pthread_mutex_unlock(&table->lock);
}

// Look up a record in the hash table by key
Record* lookup_record(HashTable* table, int key) {
    // Acquire the lock
    pthread_mutex_lock(&table->lock);

    // Search for the record
    for (int i = 0; i < table->num_records; i++) {
        if (table->records[i]->key == key) {
            // Release the lock and return the record
            pthread_mutex_unlock(&table->lock);
            return table->records[i];
        }
    }

    // Release the lock and return NULL if the record is not found
    pthread_mutex_unlock(&table->lock);
    return NULL;
}

// Look up a record in the hash table by string key
Record* lookup_record_by_string(HashTable* table, char* string_key) {
    // Acquire the lock
    pthread_mutex_lock(&table->lock);

    // Search for the record
    for (int i = 0; i < table->num_records; i++) {
        if (strcmp(table->records[i]->string_key, string_key) == 0) {
            // Release the lock and return the record
            pthread_mutex_unlock(&table->lock);
            return table->records[i];
        }
    }

    // Release the lock and return NULL if the record is not found
    pthread_mutex_unlock(&table->lock);
    return NULL;
}

// Remove a record from the hash table by key
void remove_record(HashTable* table, int key) {
    // Acquire the lock
    pthread_mutex_lock(&table->lock);

    // Search for the record to be removed
    Record** record = NULL;
    for (int i = 0; i < table->num_records; i++) {
        if (table->records[i]->key == key) {
            record = &(table->records[i]);
            break;
        }
    }

    // Check if the record was found
    if (record != NULL) {
        // Remove the record from the table
        *record = table->records[--table->num_records];

        // Release the lock
        pthread_mutex_unlock(&table->lock);
        return;
    }

    // Release the lock and return if the record was not found
    pthread_mutex_unlock(&table->lock);
}

// Remove a record from the hash table by string key
void remove_record_by_string(HashTable* table, char* string_key) {
    // Acquire the lock
    pthread_mutex_lock(&table->lock);

    // Search for the record to be removed
    Record** record = NULL;
    for (int i = 0; i < table->num_records; i++) {
        if (strcmp(table->records[i]->string_key, string_key) == 0) {
            record = &(table->records[i]);
            break;
        }
    }

    // Check if the record was found
    if (record != NULL) {
        // Remove the record from the table
        *record = table->records[--table->num_records];

        // Release the lock
        pthread_mutex_unlock(&table->lock);
        return;
    }

    // Release the lock and return if the record was not found
    pthread_mutex_unlock(&table->lock);
}

// Dump the current state of the hash table for debugging and analysis
void dump_hash_table(HashTable* table) {
    // Acquire the lock
    pthread_mutex_lock(&table->lock);

    // Print the number of records in the table
    printf("Number of records: %d\n", table->num_records);

    // Iterate over the records in the table and print their details
    for (int i = 0; i < table->num_records; i++) {
        Record* record = table->records[i];
        printf("Record %d: offset=%d, key=%d, precision=%f, string_key=%s\n", i, record->offset, record->key, record->precision, record->string_key);
    }

    // Release the lock
    pthread_mutex_unlock(&table->lock);
}

// Free the memory allocated to the hash table and its records
void free_hash_table(HashTable* table) {
    // Acquire the lock
    pthread_mutex_lock(&table->lock);

    // Iterate over the records in the table and free their memory
    for (int i = 0; i < table->num_records; i++) {
        Record* record = table->records[i];
        free(record->string_key);
        free(record);
    }

    // Free the memory allocated to the hash table itself
    free(table);

    // Release the lock
    pthread_mutex_unlock(&table->lock);
}']

