    if (num_data_points > max_data_points) {
        fprintf(stderr, "Invalid input parameters: %zu > %zu\n", num_data_points, max_data_points);
        return -1;
    }

    // Allocate memory for the floating-point number array
    float *float_array = (float *)malloc(sizeof(float) * num_data_points);
    if (!float_array) {
        fprintf(stderr, "Failed to allocate memory for floating-point number array\n");
        return -1;
    }

    // Allocate memory for the NFAPI_CRC_INDICATION_PDU_T structure array
    data_point *data_point_array = (data_point *)malloc(sizeof(data_point) * num_data_points);
    if (!data_point_array) {
        fprintf(stderr, "Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T structure array\n");
        return -1;
    }

    // Read the floating-point numbers from standard input and store them in the arrays
    size_t i = 0;
    while (i < num_data_points) {
        float current_value;
        if (scanf("%lf", &current_value) != 1) {
            break;
        }
        float_array[i] = current_value;
        data_point_array[i].value = current_value;
        i++;
    }

    // Find and print the largest number in the array
