typedef struct {
    char* string;
    int value;
} Entry;

// Define the function to manage dynamic memory allocation for the data structures
void initDataStructures(size_t numEntries, size_t* offsets, int* keys, Entry** entries) {
    // Initialize the arrays of 'offset', 'key', and 'entry' structures
    *offsets = (long*) malloc(numEntries * sizeof(long));
    *keys = (int*) malloc(numEntries * sizeof(int));
    *entries = (Entry**) malloc(numEntries * sizeof(Entry*));

    // Set the length of each string to a random value between 1 and 10 characters
    for (size_t i = 0; i < numEntries; ++i) {
        (*offsets)[i] = generateRandomLong();
        (*keys)[i] = generateRandomInt();

