        size_t len = generateRandomLength(MIN_STRING_LENGTH, MAX_STRING_LENGTH);
        char* str = (char*) malloc(len * sizeof(char));
        for (size_t j = 0; j < len; ++j) {
            str[j] = generateRandomChar();
        }

        // Store the string in an entry structure and allocate memory for it
        (*entries)[i] = (Entry*) malloc(sizeof(Entry));
        (*entries)[i]->string = str;
        (*entries)[i]->value = generateRandomInt();
    }
}

// Define the function to dynamically adjust the size of allocations based on the memory budget
void adjustAllocations(size_t numEntries, size_t* offsets, int* keys, Entry** entries) {
    // Get the current memory usage and calculate the maximum allowed allocation size
    long currentMemoryUsage = getCurrentMemoryUsage();
    size_t maxAllowedSize = MAX_MEMORY_BUDGET - currentMemoryUsage;

    // Check if the maximum allowed allocation size is greater than 0, otherwise exit the function
    if (maxAllowedSize <= 0) {
        printf("Maximum memory budget reached. Exiting...\n");
        return;
    }

    // Calculate the desired allocation size for each array based on the maximum allowed size
    size_t offsetAllocSize = numEntries * sizeof(long);
    size_t keyAllocSize = numEntries * sizeof(int);
    size_t entryAllocSize = numEntries * sizeof(Entry*);

    // Allocate memory for the arrays of 'offset', 'key', and 'entry' structures
    if (maxAllowedSize >= offsetAllocSize + keyAllocSize + entryAllocSize) {
        *offsets = (long*) malloc(offsetAllocSize);
        *keys = (int*) malloc(keyAllocSize);
        *entries = (Entry**) malloc(entryAllocSize);
    } else {
        // If the maximum allowed allocation size is not sufficient, adjust the sizes of each array accordingly
        size_t maxAllowedOffsetSize = maxAllowedSize / sizeof(long);
        size_t maxAllowedKeySize = (maxAllowedSize - offsetAllocSize) / sizeof(int);
        size_t maxAllowedEntrySize = (maxAllowedSize - offsetAllocSize - keyAllocSize) / sizeof(Entry*);

        *offsets = (long*) malloc(maxAllowedOffsetSize);
        *keys = (int*) malloc(maxAllowedKeySize);
        *entries = (Entry**) malloc(maxAllowedEntrySize);
    }
}

// Define the function to handle concurrent access from multiple threads safely
void initDataStructuresThreadSafe(size_t numEntries, size_t* offsets, int* keys, Entry** entries) {
    pthread_mutex_lock(&mutex);
    initDataStructures(numEntries, offsets, keys, entries);
    pthread_mutex_unlock(&mutex);
}

// Define the function to handle potential memory allocation failures gracefully
void initDataStructuresGraceful(size_t numEntries, size_t* offsets, int* keys, Entry** entries) {
    if (adjustAllocations(numEntries, offsets, keys, entries)) {
        printf("Memory allocation failed. Exiting...\n");
        return;
    }
}

