void init_crc_indication_list() {
    // Allocate memory for the list
    crc_indication_list = (NFAPI_CRC_INDICATION_LIST_T *) malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (!crc_indication_list) {
        return;
    }

    // Initialize the list size and data pointer to NULL
    crc_indication_list->size = 0;
    crc_indication_list->data = NULL;
}

// Function to add a CRC indication to the list
void add_crc_indication(NFAPI_CRC_INDICATION_PDU_T *crc_indication) {
    // Acquire the mutex for synchronizing access to the list
    pthread_mutex_lock(&crc_indication_list_mutex);

    // Check if the list is full, and if so, evict the least recently used entry
    if (crc_indication_list->size >= MAX_LIST_SIZE) {
        for (int i = 0; i < crc_indication_list->size - 1; ++i) {
            // Check if the current entry is the least recently used
            if (crc_indication_list->data[i].timestamp < crc_indication_list->data[i + 1].timestamp) {
                // Evict the least recently used entry and replace it with the new entry
                free(crc_indication_list->data[i].crc_indication);
                crc_indication_list->data[i] = crc_indication;
            } else {
                // The current entry is more recently used than the new entry, so break out of the loop
                break;
            }
        }
    } else {
        // Reallocate memory for the list if necessary
        if (crc_indication_list->data == NULL) {
            crc_indication_list->data = (NFAPI_CRC_INDICATION_PDU_T *) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * crc_indication_list->size);
        } else {
            crc_indication_list->data = (NFAPI_CRC_INDICATION_PDU_T *) realloc(crc_indication_list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (crc_indication_list->size + 1));
        }
    }

    // Add the new CRC indication to the list and update the size
    crc_indication_list->data[crc_indication_list->size++] = *crc_indication;

    // Release the mutex for synchronizing access to the list
    pthread_mutex_unlock(&crc_indication_list_mutex);
}

// Function to remove a CRC indication from the list
void remove_crc_indication(NFAPI_CRC_INDICATION_PDU_T *crc_indication) {
    // Acquire the mutex for synchronizing access to the list
    pthread_mutex_lock(&crc_indication_list_mutex);

    // Find the index of the CRC indication in the list
    int index = -1;
    for (int i = 0; i < crc_indication_list->size; ++i) {
        if (crc_indication == &(crc_indication_list->data[i])) {
            index = i;
            break;
        }
    }

    // Check if the CRC indication was found in the list
    if (index != -1) {
        // Remove the CRC indication from the list and update the size
        free(crc_indication_list->data[index].crc_indication);
        memmove(&(crc_indication_list->data[index]), &(crc_indication_list->data[index + 1]), sizeof(NFAPI_CRC_INDICATION_PDU_T) * (crc_indication_list->size - index));
        --crc_indication_list->size;
    }

    // Release the mutex for synchronizing access to the list
    pthread_mutex_unlock(&crc_indication_list_mutex);
}

// Function to get the CRC indication from the list by RX_UE_INFORMATION_TAG and RNTI
NFAPI_CRC_INDICATION_PDU_T *get_crc_indication(uint16_t rx_ue_information_tag, uint16_t rnti) {
    // Acquire the mutex for synchronizing access to the list
    pthread_mutex_lock(&crc_indication_list_mutex);

    // Iterate over the list and find the CRC indication with the matching RX_UE_INFORMATION_TAG and RNTI
    NFAPI_CRC_INDICATION_PDU_T *crc_indication = NULL;
    for (int i = 0; i < crc_indication_list->size; ++i) {
        if (crc_indication_list->data[i].rx_ue_information_tag == rx_ue_information_tag &&
            crc_indication_list->data[i].rnti == rnti) {
            crc_indication = &(crc_indication_list->data[i]);
            break;
        }
    }

    // Release the mutex for synchronizing access to the list
    pthread_mutex_unlock(&crc_indication_list_mutex);

    return crc_indication;
}
