#define CONFIG_FILE "/path/to/config.json"
#define MAX_THREADS 1024
#define THREAD_STACK_SIZE (1 << 20)

struct media_configuration {
    int video_codec;
    int audio_codec;
    int network_quality_threshold;
};

struct thread_pool {
    pthread_t threads[MAX_THREADS];
    struct media_configuration configs[MAX_THREADS];
    size_t num_threads;
    size_t thread_index;
};

struct thread_pool *pool = NULL;

// Read the configuration file and parse its contents into a struct media_configuration.
// Merge overlapping entries and prioritize newer sections over older ones.
int read_config(const char *file, struct media_configuration *config) {
    // Open the config file for reading.
    FILE *fp = fopen(file, "r");
    if (fp == NULL) {
        perror("fopen");
        return -1;
    }

    // Read the JSON contents of the config file.
    char buffer[4096];
    size_t num_bytes = fread(buffer, 1, sizeof(buffer), fp);
    if (num_bytes <= 0) {
        perror("fread");
        return -1;
    }

    // Parse the JSON contents into a struct media_configuration.
    json_error_t error;
    json_t *root = json_loadb(buffer, num_bytes, 0, &error);
    if (root == NULL) {
        fprintf(stderr, "JSON parsing error at line %d: %s\n", error.line, error.text);
        return -1;
    }

    // Merge overlapping entries and prioritize newer sections over older ones.
    json_t *current = root;
    while (json_is_object(current)) {
        json_t *old_config = current;
        json_object_foreach(current, key, value) {
            // Check if the key is already present in the configuration.
            if (pool->num_threads > 0 && json_object_get(pool->configs[pool->thread_index], key)) {
                continue;
            }

            // Add the new configuration to the pool.
            json_object_set(pool->configs[pool->thread_index], key, value);
            pool->num_threads++;
        }

        // Update the current section.
        current = json_object_get(current, "next");
    }

    // Clean up JSON resources.
    json_decref(root);

    return 0;
}

