    if (config->audio_codec < 0 || config->audio_codec > MAX_AUDIO_CODECS) {
        fprintf(stderr, "Invalid audio codec: %d\n", config->audio_codec);
        return -1;
    }

    // Check if the network quality threshold is valid.
    if (config->network_quality_threshold < 0 || config->network_quality_threshold > MAX_NETWORK_QUALITY) {
        fprintf(stderr, "Invalid network quality threshold: %d\n", config->network_quality_threshold);
        return -1;
    }

    // Check if the IP address is valid.
    struct in_addr ip_address;
    if (inet_pton(AF_INET, config->ip_address, &ip_address) != 1) {
        fprintf(stderr, "Invalid IP address: %s\n", config->ip_address);
        return -1;
    }

    // Check if the port number is valid.
