// Function to initialize the hash table and the semaphore
void init(HashTable* table) {
  // Initialize the size of the hash table
  table->size = 1024;

  // Allocate memory for the buckets in the hash table
  table->buckets = malloc(sizeof(Node*) * table->size);
  if (!table->buckets) {
    printf("Error: Failed to allocate memory for the buckets of the hash table\n");
    exit(1);
  }

  // Initialize each bucket in the hash table to NULL
