// Define the reference count for each structure
int32_t refcount[1024];

// Define the function to dynamically manage the array of structures
void *manageArray(size_t N) {
    // Check if the requested size exceeds the maximum allowed size
    if (N > 1024) {
        return NULL;
    }

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Initialize the array if it hasn't been initialized yet
    if (!array) {
        array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
    }

    // Increment the reference count for each structure in the array
    for (size_t i = 0; i < N; i++) {
        refcount[i]++;
    }

    // Unlock the mutex to allow other threads to access the array
    pthread_mutex_unlock(&mutex);

    // Return a pointer to the first structure in the array
    return &array[0];
}

// Define the function to release an allocated structure from the array
void release(NFAPI_CRC_INDICATION_PDU_T *structure) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Decrement the reference count for each structure in the array
    for (size_t i = 0; i < N; i++) {
        if (refcount[i] > 0) {
            refcount[i]--;
        }
    }

    // If all references have been released, free the memory
    bool freeMemory = true;
    for (size_t i = 0; i < N; i++) {
        if (refcount[i] > 0) {
            freeMemory = false;
            break;
        }
    }
    if (freeMemory) {
        free(array);
        array = NULL;
    }

    // Unlock the mutex to allow other threads to access the array
    pthread_mutex_unlock(&mutex);
}
