// Define a hash table for storing shapes
struct shape_table {
    int size;
    shape_t **buckets;
};

// Initialize the hash table with a given size
void init_shape_table(struct shape_table *table, int size) {
    // Allocate memory for the buckets
    table->size = size;
    table->buckets = (shape_t **)malloc(sizeof(shape_t *) * size);
    memset(table->buckets, 0, sizeof(shape_t *) * size);
}

// Add a new shape to the hash table
void add_shape(struct shape_table *table, shape_t *shape) {
    // Calculate the hash value for the shape's identifier
    int index = shape->id % table->size;

    // Check if there is already an entry with the same identifier
    while (table->buckets[index] != NULL && table->buckets[index]->id == shape->id) {
        index++;
        index %= table->size;
    }

    // Allocate memory for the new shape
    table->buckets[index] = (shape_t *)malloc(sizeof(shape_t));
    memcpy(table->buckets[index], shape, sizeof(shape_t));
}

// Delete a shape from the hash table by its identifier
void delete_shape(struct shape_table *table, int id) {
    // Calculate the hash value for the shape's identifier
    int index = id % table->size;

    // Check if there is an entry with the same identifier
    while (table->buckets[index] != NULL && table->buckets[index]->id == id) {
        // Free the memory for the shape
        free(table->buckets[index]);

        // Shift all remaining entries to fill the gap
        for (int i = index + 1; i < table->size; i++) {
            if (table->buckets[i] != NULL) {
                table->buckets[i - 1] = table->buckets[i];
                table->buckets[i] = NULL;
            } else {
                break;
            }
        }

        // Decrement the size of the hash table if necessary
        if (table->size > 0 && table->buckets[index] == NULL) {
            table->size--;
        }
    }
}

// Modify a shape in the hash table by its identifier
void modify_shape(struct shape_table *table, int id, double area, char type, struct point *center) {
    // Calculate the hash value for the shape's identifier
    int index = id % table->size;

    // Check if there is an entry with the same identifier
    while (table->buckets[index] != NULL && table->buckets[index]->id == id) {
        // Update the shape's properties
        table->buckets[index]->area = area;
        table->buckets[index]->type = type;
        table->buckets[index]->center = center;

        break;
    }
}

// Query a shape in the hash table by its identifier
shape_t *query_shape(struct shape_table *table, int id) {
    // Calculate the hash value for the shape's identifier
    int index = id % table->size;

    // Check if there is an entry with the same identifier
    while (table->buckets[index] != NULL && table->buckets[index]->id == id) {
        return table->buckets[index];
    }

    return NULL;
}

// Query a shape in the hash table by its type
shape_t *query_type(struct shape_table *table, char type) {
    for (int i = 0; i < table->size; i++) {
        if (table->buckets[i] != NULL && table->buckets[i]->type == type) {
            return table->buckets[i];
        }
    }

    return NULL;
}

// Iterate over all shapes in the hash table
void iterate_shapes(struct shape_table *table, void (*callback)(shape_t *)) {
    for (int i = 0; i < table->size; i++) {
        if (table->buckets[i] != NULL) {
            callback(table->buckets[i]);
        }
    }
}

// Free the memory of a hash table
void free_shape_table(struct shape_table *table) {
    for (int i = 0; i < table->size; i++) {
