            }
            curl_easy_cleanup(curl);
        }
    }
    return NULL;
}

void* periodicHealthCheckBackoff(void* arg) {
    while (true) {
        sleep(10); // check every 10 seconds
        CellularNode *node = (CellularNode*)arg;
        char url[256];
        sprintf(url, "http://%s/api/health/%d", node->location, node->node_id);
