            CURLcode res = curl_easy_perform(curl);
            if (res != CURLE_OK) {
                printf("Error: %s\n", curl_easy_strerror(res));
                sleep(10); // backoff for 10 seconds before trying again
                continue;
            } else {
                // check the response code
                long http_code = 0;
                curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
                if (http_code != 200) {
                    printf("HTTP error: %ld\n", http_code);
                    sleep(10); // backoff for 10 seconds before trying again
                    continue;
                } else {
                    // parse the JSON response and update the metrics
                    json_error_t error;
                    json_t *root = json_loadb(curl_easy_strerror(res), strlen(curl_easy_strerror(res)), 0, &error);
                    if (!root) {
                        printf("JSON error: %s\n", error.text);
                        sleep(10); // backoff for 10 seconds before trying again
                        continue;
