                            node->metrics->memory_usage = json_integer_value(memory_usage);
                        } else {
                            printf("JSON response missing fields\n");
                            sleep(10); // backoff for 10 seconds before trying again
                            continue;
                        }
                    }
                }
            }
            curl_easy_cleanup(curl);
        }
    }
    return NULL;
}

void monitorNodeHealth(CellularNode *node) {
