#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <math.h>

// Define a struct to represent a temperature reading and its timestamp
struct measurement {
  time_t timestamp;
  float temperature;
};

// Define an enum to represent the different sensor types
enum sensor_type {
  TEMPERATURE_SENSOR,
  HUMIDITY_SENSOR,
  PRESSURE_SENSOR
};

// Define a function to generate temperature readings from a normal distribution
void generate_temperature_readings(float mean, float stddev, int num_readings, enum sensor_type sensor) {
  // Allocate memory for the arrays of floats and char values
  float* temperature_values = malloc(num_readings * sizeof(float));
  char* sensor_identifiers = malloc(num_readings * sizeof(char));
  struct measurement* measurements = malloc(num_readings * sizeof(struct measurement));

  // Initialize the arrays with the specified mean and standard deviation
  for (int i = 0; i < num_readings; ++i) {
    temperature_values[i] = generate_normal_distribution(mean, stddev);
    sensor_identifiers[i] = get_sensor_identifier(sensor);
    measurements[i].timestamp = time(NULL);
    measurements[i].temperature = temperature_values[i];
  }

  // Periodically clear outdated measurement data based on a configurable time window
  int time_window = 30; // seconds
  struct measurement* current_measurement = measurements;
  while (current_measurement < measurements + num_readings) {
    if (time(NULL) - current_measurement->timestamp > time_window) {
      free(*current_measurement);
      *current_measurement = NULL;
    } else {
      ++current_measurement;
    }
  }

  // Free the memory used by the arrays and return the measurements
  free(temperature_values);
  free(sensor_identifiers);
  free(measurements);
  return measurements;
}

// Define a function to generate temperature readings from a normal distribution
float generate_normal_distribution(float mean, float stddev) {
  float result = 0.0f;
  for (int i = 0; i < 10; ++i) {
    result += ((float)rand() / RAND_MAX) * stddev + mean;
  }
  return result / 10.0f;
}

// Define a function to get the sensor identifier for a given sensor type
char get_sensor_identifier(enum sensor_type sensor) {
  char identifier = ' ';
  switch (sensor) {
    case TEMPERATURE_SENSOR:
      identifier = 'T';
      break;
    case HUMIDITY_SENSOR:
      identifier = 'H';
      break;
    case PRESSURE_SENSOR:
      identifier = 'P';
      break;
  }
  return identifier;
}
```
