        i++;
      }
    }

    // Release the semaphore
    sem_post(semaphore);

    // Check if the system load has increased and switch to a lock-based approach
    float current_load = (float)sysconf(_SC_NPROCESSORS_ONLN);
    if (current_load > 0.75 * (float)sysconf(_SC_NPROCESSORS_ONLN)) {
      // If the system load has increased, switch to a lock-based approach
      lock_free = 0;
    }
  }
}

void cleanup() {
