    list->head = NULL;
    list->tail = NULL;
}

// Define a function for adding a new LTE RRC message to the linked list
void add_LTE_RRC_msg(LTE_RRC_MSG_LIST_T *list, uint32_t UE_ID, uint8_t RRC_MESSAGE_TYPE) {
    // Allocate memory for the new message node
    LTE_RRC_MSG_NODE_T *new_node = malloc(sizeof(LTE_RRC_MSG_NODE_T));
    if (new_node == NULL) {
        return;
    }

    // Initialize the new message node
    new_node->msg.UE_ID = UE_ID;
    new_node->msg.RRC_MESSAGE_TYPE = RRC_MESSAGE_TYPE;
    new_node->msg.payload = NULL;

    // Allocate memory for the message payload
    size_t payload_size = get_LTE_RRC_message_payload_size(RRC_MESSAGE_TYPE);
    BYTE_STRING_T *payload = malloc(sizeof(BYTE_STRING_T) + payload_size);
    if (payload == NULL) {
        free(new_node);
        return;
    }

    // Generate random data for the message payload
    generate_random_data(payload->bytes, payload_size);

    // Set the message payload
    new_node->msg.payload = payload;

    // Add the new message node to the linked list
    if (list->tail == NULL) {
        list->head = new_node;
    } else {
        list->tail->next = new_node;
    }
    list->tail = new_node;
}

// Define a function for getting the size of an LTE RRC message payload based on its type
size_t get_LTE_RRC_message_payload_size(uint8_t RRC_MESSAGE_TYPE) {
    // Determine the size of the message payload based on its type
    switch (RRC_MESSAGE_TYPE) {
        case 0:  // Handover command
            return sizeof(HANDOVER_CMD);
        case 1:  // UE Capability Information
            return sizeof(UE_CAPABILITY_INFO);
        default:
            return 0;
    }
}

// Define a function for generating random data for an LTE RRC message payload
void generate_random_data(uint8_t *buf, size_t len) {
    // Fill the buffer with random bytes
    srand((unsigned int) time(NULL));
    for (size_t i = 0; i < len; ++i) {
        buf[i] = rand() % 256;
    }
}

// Define a function for cleaning up the linked list of LTE RRC messages
void free_LTE_RRC_msg_list(LTE_RRC_MSG_LIST_T *list) {
    // Free each message node in the list
    while (list->head != NULL) {
        LTE_RRC_MSG_NODE_T *node = list->head;
        free(node->msg.payload);
        free(node);
        list->head = node->next;
    }
}
