        offsets[i] = rand() % 100 + 1;
    }

    // Allocate memory for the keys array
    int *keys = malloc(M * sizeof(int));
    if (keys == NULL) {
        printf("Error: Failed to allocate memory for keys\n");
        free(offsets);
        return NULL;
    }

    // Initialize the keys array with unique values between 1 and 100, inclusive
    srand(time(NULL)); // initialize random seed
    for (int i = 0; i < M; i++) {
        int key = rand() % 100 + 1;
        while (contains_key(keys, key)) {
            key = rand() % 100 + 1;
        }
        keys[i] = key;
    }

    // Allocate memory for the records array
    struct record *records = malloc(N * sizeof(struct record));
    if (records == NULL) {
        printf("Error: Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Set the value of each record's value field to a random integer within the specified range
    srand(time(NULL)); // initialize random seed
    for (int i = 0; i < N; i++) {
        int value = rand() % (max_value - min_value + 1) + min_value;
        records[i].value = value;
    }

    // Optimize memory usage by reusing previously allocated memory structures when N remains unchanged
    if (N > 0 && offsets != NULL && keys != NULL) {
        struct record *tmp = records - offsets[N - 1];
        free(records);
        records = tmp;
    }

    // Logging mechanism to record total memory allocated and deallocated
    printf("Total memory allocated: %lu\n", sizeof(offsets) + sizeof(keys) + sizeof(records));

    // Ensure that memory is freed in a deterministic order to prevent dangling pointers and potential access violations
    free(records);
    free(keys);
    free(offsets);

    return records;
}

// Function to check if a key is already present in the keys array
bool contains_key(int *keys, int key) {
    for (int i = 0; i < M; i++) {
        if (keys[i] == key) {
            return true;
        }
    }
    return false;
}
```
