// List of network sessions
static struct network_session *sessions = NULL;
static size_t session_count = 0;
static size_t session_capacity = 0;
static pthread_mutex_t session_lock;

// Initialize session list with initial capacity
void init_sessions(size_t initial_capacity) {
    sessions = malloc(initial_capacity * sizeof(struct network_session));
    if (sessions == NULL) {
        fprintf(stderr, "Failed to allocate memory for sessions\n");
        exit(1);
    }
    session_count = 0;
    session_capacity = initial_capacity;
}

// Add a new network session to the list
void add_session(struct network_session *new_session) {
    pthread_mutex_lock(&session_lock);
    if (session_count >= session_capacity) {
        // Allocate more memory for sessions
        size_t new_capacity = session_capacity * 2;
        struct network_session *new_sessions = realloc(sessions, new_capacity * sizeof(struct network_session));
        if (new_sessions == NULL) {
            fprintf(stderr, "Failed to allocate more memory for sessions\n");
            exit(1);
        }
        sessions = new_sessions;
        session_capacity = new_capacity;
    }
    // Copy the new session into the list
    memcpy(&sessions[session_count], new_session, sizeof(struct network_session));
    session_count++;
    pthread_mutex_unlock(&session_lock);
}

// Remove a network session from the list by ID
void remove_session(int id) {
    pthread_mutex_lock(&session_lock);
    // Find the index of the session with the given ID
    size_t i;
    for (i = 0; i < session_count; i++) {
        if (sessions[i].id == id) {
            break;
        }
    }
    // If the session was found, copy the last session into its place and decrement the count
    if (i < session_count) {
        memcpy(&sessions[i], &sessions[session_count - 1], sizeof(struct network_session));
        session_count--;
    }
    pthread_mutex_unlock(&session_lock);
}

// Get a pointer to the network session with the given ID
struct network_session *get_session(int id) {
    struct network_session *result = NULL;
    pthread_mutex_lock(&session_lock);
    // Find the index of the session with the given ID
    size_t i;
    for (i = 0; i < session_count; i++) {
        if (sessions[i].id == id) {
            result = &sessions[i];
            break;
        }
    }
    pthread_mutex_unlock(&session_lock);
    return result;
}

// Get the number of network sessions in the list
size_t get_session_count() {
    size_t count = 0;
    pthread_mutex_lock(&session_lock);
    count = session_count;
    pthread_mutex_unlock(&session_lock);
    return count;
}

// Print all network sessions in the list
void print_sessions() {
    pthread_mutex_lock(&session_lock);
    for (size_t i = 0; i < session_count; i++) {
        printf("Session %d: IP address %s, state %d, error metric %.2f, timestamp %ld\n",
               sessions[i].id, sessions[i].ip, sessions[i].state, sessions[i].error_metric, sessions[i].timestamp);
    }
    pthread_mutex_unlock(&session_lock);
}

// Release resources allocated for the session list
void free_sessions() {
    free(sessions);
    sessions = NULL;
    session_count = 0;
    session_capacity = 0;
}
