// Define the function to handle the background execution of a given command using fork and wait system calls
int executeCommand(char *command) {
    pid_t childProcessId = fork();
    if (childProcessId == -1) {
        fprintf(stderr, "Error: Failed to create child process\n");
        return 0;
    }

    if (childProcessId == 0) {
        // Child process executes the command
        execl("/bin/sh", "sh", "-c", command, NULL);
        fprintf(stderr, "Error: Failed to execute command\n");
        return 0;
    } else {
        // Parent process waits for the child process to complete
        int status = wait(NULL);
        if (status == -1) {
            fprintf(stderr, "Error: Failed to wait for child process\n");
            return 0;
        }
    }

    // Return 1 if the command was executed successfully
    return 1;
}

// Define the function to compress the generated records using the gzip command
int compressRecords(char *filename) {
    char command[1024];
    sprintf(command, "gzip %s", filename);
    if (executeCommand(command)) {
        // Remove the original file after compression
        remove(filename);
        return 1;
    } else {
        fprintf(stderr, "Error: Failed to compress records\n");
        return 0;
    }
}

// Define the function to decompress the compressed records using the gunzip command
int decompressRecords(char *filename) {
    char command[1024];
    sprintf(command, "gunzip %s", filename);
    if (executeCommand(command)) {
        // Remove the original file after decompression
        remove(filename);
        return 1;
    } else {
        fprintf(stderr, "Error: Failed to decompress records\n");
        return 0;
    }
}

// Define the function to read the generated records from a compressed file
int readCompressedRecords(char *filename) {
    // Decompress the records if they are compressed
    if (strlen(filename) > 3 && strcmp(&filename[strlen(filename) - 3], ".gz") == 0) {
        if (!decompressRecords(filename)) {
            fprintf(stderr, "Error: Failed to decompress records\n");
            return 0;
        }
    }

    // Read the records from the decompressed file
    char command[1024];
    sprintf(command, "cat %s", filename);
    if (executeCommand(command)) {
        // Remove the original file after reading it
        remove(filename);
        return 1;
    } else {
        fprintf(stderr, "Error: Failed to read records\n");
        return 0;
    }
}

// Define the function to write the generated records to a compressed file
int writeCompressedRecords(char *filename) {
    // Compress the records if they are not already compressed
    if (strlen(filename) <= 3 || strcmp(&filename[strlen(filename) - 3], ".gz") != 0) {
        if (!compressRecords(filename)) {
            fprintf(stderr, "Error: Failed to compress records\n");
            return 0;
        }
    }

    // Write the records to the compressed file
    char command[1024];
    sprintf(command, "echo %s", filename);
    if (executeCommand(command)) {
        // Remove the original file after writing it
        remove(filename);
        return 1;
    } else {
        fprintf(stderr, "Error: Failed to write records\n");
        return 0;
    }
}
```

