        pdu.rx_ue_information_tag, pdu.rnti, pdu.crc_indication_rel8_tag
    )?;
    Ok(())
}

fn rotate_log() -> Result<(), Box<dyn std::error::Error>> {
    let log_settings = LogSettings::new();
    if let Some(file) = File::open(&log_settings.log_file)? {
        let mut reader = BufReader::new(file);
        let mut writer = BufWriter::new(File::create(&log_settings.log_file)?);
        for line in reader.lines() {
            if let Ok(line) = line {
                write!(writer, "{}\n", line)?;
            }
        }
    }
    Ok(())
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let log_settings = LogSettings::new();
    let pdu_vec = generate_crc_indication_pdu(10);
    for pdu in &pdu_vec {
        write_to_log(pdu)?;
    }
    rotate_log()?;
    Ok(())
}
