void initialize_nic_stats(int max_size, int payload_size, int checksum_size) {
  // Allocate memory for the NIC stats array
  struct nic_statistics **stats = malloc(max_size * sizeof(struct nic_statistics));

  // Initialize each entry in the array with a valid MAC_HEADER and IP_PACKET
  for (int i = 0; i < max_size; i++) {
    struct mac_header header = {
      .source = "11:22:33:44:55:66",
      .destination = "22:33:44:55:66:77",
      .ethertype = 0x0800, // IPv4
