      .ihl = 5,
      .tos = 0,
      .len = htons(payload_size + checksum_size),
      .id = htons(i),
      .flags = 0x10, // Don't fragment
      .ttl = 64,
      .protocol = 0x11, // UDP
      .checksum = 0,
    };

    struct udp_header udp = {
