// Function to validate the integrity of an IP packet against a checksum
int validate_checksum(struct ip_packet *packet) {
  unsigned short checksum = packet->checksum;
  // Calculate the checksum for the packet
  unsigned short calculated_checksum = calculate_checksum(packet);
  // Compare the two checksums and return true if they match, false otherwise
  return (checksum == calculated_checksum);
}

// Function to generate a randomly generated payload of the specified size
unsigned char *generate_random_payload(int size) {
  unsigned char *payload = malloc(size);
  for (int i = 0; i < size; i++) {
    payload[i] = rand() % 256;
  }
  return payload;
}

// Function to calculate the checksum of an IP packet
unsigned short calculate_checksum(struct ip_packet *packet) {
  unsigned short checksum = 0;
  // Calculate the checksum for each field in the packet
  checksum += packet->version << 12 | packet->ihl << 8 | packet->tos << 4 | packet->len >> 8;
  checksum += packet->id << 16 | packet->flags << 13 | packet->ttl << 8 | packet->protocol;
  checksum += packet->checksum << 16;
  return checksum;
}

// Function to perform DNS resolution for a given hostname using standard library functions
unsigned char **resolve_hostname(const char *hostname) {
  // Perform DNS resolution using the standard library functions
  struct addrinfo hints = {
    .ai_family = AF_INET,
    .ai_socktype = SOCK_STREAM,
    .ai_protocol = IPPROTO_TCP,
  };
  struct addrinfo *result;
  if (getaddrinfo(hostname, NULL, &hints, &result) != 0) {
    return NULL;
  }

  // Allocate memory for the IP addresses in a dynamically allocated array of `u_char`
  unsigned char **ip_addrs = malloc(result->ai_family * sizeof(unsigned char));
  int i = 0;
  for (struct addrinfo *addr = result; addr != NULL; addr = addr->ai_next) {
    ip_addrs[i++] = (unsigned char *)malloc(sizeof(unsigned char));
    memcpy(&ip_addrs[i], &(addr->ai_addr.sa_data), sizeof(struct sockaddr_in));
  }

  // Free the memory allocated by `getaddrinfo` and return the array of IP addresses
  freeaddrinfo(result);
  return ip_addrs;
}

