// Define function to initialize an array of record structures
void init_records(int size, Record* records) {
  // Initialize the record array with the given size
  for (int i = 0; i < size; i++) {
    records[i].offset = -1;
    records[i].key = -1;
  }
}

// Define function to generate random values for each record's int field within a specified range
void generate_random_values(int min, int max, Record* records) {
  // Generate random values within the specified range
  srand(time(NULL));
  for (int i = 0; i < size; i++) {
    records[i].key = rand() % (max - min + 1) + min;
  }
}

// Define function to sort the records based on their key values in ascending order
void sort_records(Record* records, int size) {
  // Use quicksort algorithm to sort the records
  for (int i = 0; i < size - 1; i++) {
    int j = i + 1;
    while (j > 0 && records[i].key > records[j].key) {
      swap(records[i], records[j]);
    }
  }
}

// Define function to compress the data before saving it to a file
void compress_data(Record* records, int size) {
  // Use LZ77 compression algorithm to compress the data
  for (int i = 0; i < size; i++) {
