    struct Node *newNode = malloc(sizeof(struct Node));
    newNode->data.offset = records[i].offset;
    newNode->data.key = records[i].key;
    newNode->next = head;
    head = newNode;
  }
  // Use a file I/O library to write the linked list to a file
  FILE *fp = fopen("records.dat", "wb");
  while (head != NULL) {
    Record record = head->data;
    fwrite(&record, sizeof(Record), 1, fp);
    struct Node *temp = head;
    head = head->next;
    free(temp);
  }
}

// Define function to validate the integrity of the saved data upon retrieval
void validate_records(Record* records, int size) {
  // Calculate checksum for each record using a hash function
  for (int i = 0; i < size; i++) {
    Record record = records[i];
    unsigned long hash = hash_function(&record);
    if (hash != record.key) {
