// Array of LTE_PHY_RX_FRAME_INFO_T structures
static LTE_PHY_RX_FRAME_INFO_T *frames = NULL;

// Number of frames in the array
static size_t num_frames = 0;

// Capacity of the frame array
static size_t capacity = 0;

// Initialization function to initialize the array with a given number of frames
void init_frames(size_t num_frames) {
    // Allocate memory for the frame array
    frames = (LTE_PHY_RX_FRAME_INFO_T *)calloc(num_frames, sizeof(LTE_PHY_RX_FRAME_INFO_T));
    if (frames == NULL) {
        fprintf(stderr, "Failed to allocate memory for the frame array\n");
        return;
    }
    capacity = num_frames;
}

// Function to populate the frame array with random RF_RX_FRAME_INFO instances and ensure unique UE identifiers
void populate_frames(size_t num_frames) {
    // Generate random UE identifiers for each frame
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < num_frames; i++) {
        frames[i].ue_id = rand() % 10000 + 1; // Generate a random UE identifier between 1 and 10000
    }
    // Populate the RF_RX_FRAME_INFO instances for each frame
    for (size_t i = 0; i < num_frames; i++) {
        frames[i].rf_rx_frame_info.channel = rand() % 10 + 1; // Generate a random channel between 1 and 10
        frames[i].rf_rx_frame_info.sub_channel = rand() % 20 + 1; // Generate a random sub-channel between 1 and 20
    }
}

// Function to add new frames to the array when the current capacity is exceeded, without disrupting existing data
void add_frames(size_t num_frames) {
    size_t new_capacity = capacity + num_frames;
    LTE_PHY_RX_FRAME_INFO_T *new_frames = (LTE_PHY_RX_FRAME_INFO_T *)calloc(new_capacity, sizeof(LTE_PHY_RX_FRAME_INFO_T));
    if (new_frames == NULL) {
        fprintf(stderr, "Failed to allocate memory for the new frame array\n");
