    retval = getaddrinfo(hostname, NULL, &hints, &res);
    if (retval != 0) {
        error = -1;
    } else {
        // allocate memory for IP addresses
        *ip_addresses = malloc(sizeof(u_char) * res->ai_addrlen);
        if (*ip_addresses == NULL) {
            error = -1;
        } else {
            // copy IP addresses into buffer
            memcpy(*ip_addresses, res->ai_addr, res->ai_addrlen);
        }
    }

    return error;
}

