struct packet_queue {
    void *packet;
    struct packet_queue *next;
};

void *process_packet(void *arg) {
    int fd = (int)(long)arg;
    while (1) {
        struct packet_queue *pkt = malloc(sizeof(struct packet_queue));
        if (!pkt) {
            printf("Error: Out of memory\n");
            return NULL;
        }
        pthread_mutex_lock(&packet_queue_lock);
        while (packet_queue_head == NULL && !shutdown_flag) {
            pthread_cond_wait(&packet_queue_cond, &packet_queue_lock);
        }
        if (shutdown_flag) {
            free(pkt);
            break;
        }
        pkt->packet = packet_queue_head;
        packet_queue_head = pkt->next;
        pthread_mutex_unlock(&packet_queue_lock);
        // process packet here
    }
}

