    pthread_mutex_lock(&mutex);

    // Allocate memory for the array of pointers
    NFAPI_CRC_INDICATION_PDU_T **elements = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T *) * arraySize);

    // Copy elements from the array to the new array of pointers
