    for (size_t i = 0; i < arraySize; i++) {
        elements[index++] = malloc(ELEMENT_SIZE);
        memcpy(elements[i], array + i, ELEMENT_SIZE);
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);

    return elements;
}
