    record_t* records = (record_t*)malloc(sizeRecord * sizeof(record_t));
    if (!records) {
        printf("Error: Failed to allocate memory for record array.\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize the offset and key arrays with unique random values
    srand(time(NULL));
    for (int i = 0; i < sizeOffset; i++) {
        offsets[i] = rand() % 1000 + 1;
    }
    for (int i = 0; i < sizeOffset / 2; i++) {
        keys[i] = i + 2; // Start at 2 to ensure unique prime numbers
    }

    // Fill the record array with unique random values
    for (int i = 0; i < sizeRecord; i++) {
        records[i].value = rand() % 1000 + 1;
    }

    // Check for duplicates in the record array and remove them if found
    for (int i = 0; i < sizeRecord - 1; i++) {
        for (int j = i + 1; j < sizeRecord; j++) {
            if (records[i].value == records[j].value) {
                records[j].value = rand() % 1000 + 1;
            }
        }
    }

    // Return a pointer to the initialized record structure
    return records;
}

// Function to free memory allocated for the data structures
void freeDataStructures(void* records) {
