#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

#define MAX_TRANSACTIONS 15000
#define TRANSACTION_SIZE 80
#define MIN_PAYLOAD_SIZE 64
#define MAX_PAYLOAD_SIZE 128
#define DEFAULT_WEIGHT 1.0
#define AGE_THRESHOLD 5

struct NetworkStats {
    MAC_HEADER macHeader;
    IP_PACKET ipPacket;
    unsigned long timestamp;
    float weight;
};

struct PriorityQueue {
    struct NetworkStats *transactions[MAX_TRANSACTIONS];
    int size;
};

struct FilterMetrics {
    float maxWeightedSum;
    char transactionId[16];
};

// Initialize and filter network stats
void initializeAndFilterNetworkStats(struct PriorityQueue *pq) {
    // Initialize priority queue with default parameters
    pq->size = 0;

    // Initialize transaction pool with default size
    struct NetworkStats *transactionPool[MAX_TRANSACTIONS];
    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        transactionPool[i] = NULL;
    }

    // Set up lock mechanism for thread-safe access
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    // Start processing incoming transactions
    while (1) {
        struct NetworkStats *transaction = receiveTransaction();

        // Lock queue and add new transaction to pool
        pthread_mutex_lock(&mutex);
        transactionPool[pq->size] = transaction;
        pq->size++;
        pthread_mutex_unlock(&mutex);

        // Update metrics based on transaction age, frequency, and weighted sum
        float weightedSum = calculateWeightedSum(transaction);
        struct FilterMetrics *metrics = &pq->metrics;
        if (weightedSum > metrics->maxWeightedSum) {
            metrics->maxWeightedSum = weightedSum;
            memcpy(metrics->transactionId, transaction->ipPacket.id, 16);
        }
    }
}

// Receive incoming transaction from network
struct NetworkStats *receiveTransaction() {
    struct NetworkStats *transaction = malloc(TRANSACTION_SIZE);
    if (transaction == NULL) {
        printf("Failed to allocate memory for transaction\n");
        return NULL;
    }

    // Randomly generate MAC header and IP packet with payload size and checksum
    transaction->macHeader.source = rand() % 256;
    transaction->ipPacket.id[0] = rand() % 16;
    transaction->ipPacket.id[1] = rand() % 16;
    transaction->ipPacket.size = rand() % (MAX_PAYLOAD_SIZE - MIN_PAYLOAD_SIZE) + MIN_PAYLOAD_SIZE;
    transaction->ipPacket.checksum = calculateChecksum(transaction);
    transaction->timestamp = time(NULL);
    transaction->weight = DEFAULT_WEIGHT;

    return transaction;
}

// Calculate weighted sum of incoming transaction based on age, frequency, and weight
float calculateWeightedSum(struct NetworkStats *transaction) {
    float weightedSum = 0.0;
    int age = time(NULL) - transaction->timestamp;
    if (age < AGE_THRESHOLD) {
        weightedSum += DEFAULT_WEIGHT;
    } else {
        float frequency = calculateFrequency(transaction);
        weightedSum += DEFAULT_WEIGHT * frequency;
    }
    return weightedSum;
}

// Calculate transaction frequency within the last five seconds
float calculateFrequency(struct NetworkStats *transaction) {
    float frequency = 0.0;
    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        if (transaction->ipPacket.id == transactionPool[i]->ipPacket.id) {
            frequency++;
        }
    }
    return frequency / AGE_THRESHOLD;
}
```
