// Define log structure
typedef struct {
  char* message;
  time_t timestamp;
  int priority;
} LogEntry;

// Define logging system interface
void appendLog(const char* message, int priority);
int getLogsInRange(time_t startTime, time_t endTime, int priority, LogEntry** logs);
int clearOlderThan(time_t duration, int priority);
void compressLogs();

// Define logging system implementation
static LogEntry* logEntries = NULL;
static size_t numLogEntries = 0;
static size_t maxLogEntries = 10000; // default maximum number of log entries
static size_t currentLogIndex = 0;

// Append new log entry to the collection
void appendLog(const char* message, int priority) {
  if (numLogEntries == maxLogEntries) {
    // resize log entry array if full
    LogEntry* newLogEntries = realloc(logEntries, 2 * maxLogEntries * sizeof(LogEntry));
    if (newLogEntries != NULL) {
      logEntries = newLogEntries;
      maxLogEntries *= 2;
    } else {
      // handle allocation failure gracefully
      return;
    }
  }

  LogEntry* entry = &logEntries[numLogEntries++];
  entry->message = strdup(message);
  entry->timestamp = time(NULL);
  entry->priority = priority;
}

// Get log entries in a given time range and priority level
int getLogsInRange(time_t startTime, time_t endTime, int priority, LogEntry** logs) {
  size_t numLogs = 0;
  for (size_t i = 0; i < numLogEntries; i++) {
    if ((logEntries[i].timestamp >= startTime && logEntries[i].timestamp <= endTime) &&
        logEntries[i].priority == priority) {
      logs[numLogs++] = &logEntries[i];
    }
  }
  return numLogs;
}

// Clear log entries older than a specified duration and priority level
int clearOlderThan(time_t duration, int priority) {
  size_t numCleared = 0;
  for (size_t i = 0; i < numLogEntries; i++) {
    if ((logEntries[i].timestamp + duration) <= time(NULL) && logEntries[i].priority == priority) {
      free(logEntries[i].message); // free message string
      logEntries[i] = logEntries[numLogEntries - 1]; // move last entry to current index
      numLogEntries--;
      numCleared++;
    }
  }
  return numCleared;
}

// Compress logs and store them in a binary archive
void compressLogs() {
  FILE* logFile = fopen("logs.bin", "wb"); // create or truncate file
  if (logFile != NULL) {
    for (size_t i = 0; i < numLogEntries; i++) {
      LogEntry entry = logEntries[i];
      fwrite(&entry, sizeof(LogEntry), 1, logFile); // write entry to file
    }
    fclose(logFile);
  } else {
    // handle file opening failure gracefully
  }
}
