#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>

// Define the data structure for a geometric shape
struct shape {
    long offset;
    int key;
    double precision;
    void* associated_data; // pointer to struct point, struct color, or any other type of data
};

// Define the hash table data structure
struct hash_table {
    size_t capacity; // total number of slots in the hash table
    size_t size; // number of elements in the hash table
    float load_factor; // ratio of used slots to total slots
    struct shape* slots[]; // array of pointers to shapes
};

// Define a linked list data structure for garbage collection
struct node {
    struct shape* shape; // pointer to the shape object
    struct node* next; // pointer to the next node in the list
};

// Global variables for garbage collection
static struct hash_table* table = NULL; // hash table for shapes
static struct node* head = NULL; // head of the linked list for garbage collection
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // mutex to protect the hash table and linked list

// Initialize the hash table and garbage collector
void init() {
    // Allocate memory for the hash table and linked list nodes
    table = malloc(sizeof(struct hash_table));
    if (table == NULL) {
        printf("Error: unable to allocate memory for the hash table\n");
        return;
    }

    head = malloc(sizeof(struct node));
    if (head == NULL) {
        printf("Error: unable to allocate memory for the linked list\n");
        free(table);
        return;
    }

    // Set the initial values for the hash table and linked list
    table->capacity = 1024;
    table->size = 0;
    table->load_factor = 0.75;
    head->next = NULL;
}

// Add a shape to the hash table and garbage collector
void add_shape(struct shape* shape) {
    // Check if the hash table is full and needs to be resized
    if (table->size >= table->capacity * table->load_factor) {
        resize();
    }

    // Calculate the index for the new shape in the hash table
    size_t index = shape->key % table->capacity;

    // Check if there is a collision and need to probe for an empty slot
    while (table->slots[index] != NULL && strcmp(shape->key, table->slots[index]->key) == 0) {
        index = (index + 1) % table->capacity;
    }

    // Add the new shape to the hash table and linked list
    struct node* node = malloc(sizeof(struct node));
    if (node == NULL) {
        printf("Error: unable to allocate memory for a new node\n");
        return;
    }

    node->shape = shape;
    node->next = head->next;
    head->next = node;

    table->slots[index] = shape;
    table->size++;
}

// Remove a shape from the hash table and garbage collector
void remove_shape(struct shape* shape) {
    // Find the index of the shape in the hash table
    size_t index = 0;
    while (table->slots[index] != NULL && strcmp(shape->key, table->slots[index]->key) == 0) {
        index++;
    }

    // Check if the shape is found in the hash table
    if (table->slots[index] == NULL) {
        printf("Error: unable to find the shape in the hash table\n");
        return;
    }

    // Remove the shape from the hash table and linked list
    struct node* node = head->next;
    while (node != NULL && node->shape != shape) {
        node = node->next;
    }

    if (node == NULL) {
        printf("Error: unable to find the shape in the linked list\n");
        return;
    }

    head->next = node->next;
    free(node);

    table->slots[index] = NULL;
    table->size--;
}

// Resize the hash table and garbage collector
void resize() {
    // Calculate the new capacity for the hash table
    size_t new_capacity = (table->capacity * 2);

    // Reallocate memory for the hash table and linked list nodes
    struct shape** old_slots = malloc(sizeof(struct shape*) * table->capacity);
    if (old_slots == NULL) {
        printf("Error: unable to allocate memory for the new hash table\n");
        return;
    }

    struct node* old_head = head;
    head = malloc(sizeof(struct node));
    if (head == NULL) {
        printf("Error: unable to allocate memory for the new linked list\n");
        free(old_slots);
        return;
    }

    // Copy the old hash table and linked list to the new ones
    memcpy(old_slots, table->slots, sizeof(struct shape*) * table->capacity);
    head->next = NULL;
    for (size_t i = 0; i < table->capacity; i++) {
        if (old_slots[i] != NULL) {
            add_shape(old_slots[i]);
            free(old_slots[i]);
        }
    }

    // Free the old memory for the hash table and linked list
    free(table);
    free(old_head);

    // Set the new values for the hash table and linked list
    table->capacity = new_capacity;
    table->size = 0;
    table->load_factor = 0.75;
}

// Garbage collector function to release resources for unreferenced shapes
void garbage_collect() {
    // Lock the mutex to prevent concurrent access to the hash table and linked list
    pthread_mutex_lock(&lock);

    // Remove all unreferenced shapes from the hash table and linked list
    struct node* node = head->next;
    while (node != NULL) {
        if (node->shape == NULL) {
            struct node* next = node->next;
            free(node);
            head->next = next;
            node = next;
        } else {
            node = node->next;
        }
    }

    // Unlock the mutex to allow concurrent access to the hash table and linked list
    pthread_mutex_unlock(&lock);
}

// Periodically release resources for unreferenced shapes using a background thread
void* garbage_collector_bg(void* arg) {
    while (true) {
        // Sleep for a certain amount of time before running the garbage collector
        sleep(arg);

        // Run the garbage collector in the background
        garbage_collect();
    }
}

// Example usage of the hash table and linked list
int main() {
    // Create a new hash table with a default capacity
    struct shape** hash = malloc(sizeof(struct shape*) * 10);
    for (size_t i = 0; i < 10; i++) {
        hash[i] = NULL;
    }

    // Create a new linked list with a default capacity
    struct node* head = malloc(sizeof(struct node));
    head->next = NULL;

    // Add some shapes to the hash table and linked list
    add_shape(&hash, &head, "square", 4);
    add_shape(&hash, &head, "circle", 3.14);
    add_shape(&hash, &head, "triangle", 6);

    // Remove a shape from the hash table and linked list
    remove_shape(hash, head, "square");

    // Print all shapes in the hash table and linked list
    for (size_t i = 0; i < 10; i++) {
        if (hash[i] != NULL) {
            printf("%s: %f\n", hash[i]->name, hash[i]->value);
        }
    }

    // Run the garbage collector in a background thread to release resources for unreferenced shapes
    pthread_create(&garbage_collector_bg, NULL);
}
```

This code creates a new hash table with a default capacity of 10 and a linked list with a default capacity of 10. It adds some shapes to the hash table and linked list, removes one of the shapes from the hash table and linked list, and prints all shapes in the hash table and linked list. The `garbage_collector_bg` function runs in a background thread and periodically releases resources for unreferenced shapes using the `garbage_collect` function.

Note that this code uses pthreads to implement a background thread that runs the garbage collector. This requires including `<pthread.h>` at the top of the file and linking against the pthread library when building the program.']

