#define BUFFER_SIZE 1024

typedef struct {
    int sock;
    char ip[INET6_ADDRSTRLEN];
    unsigned short port;
    time_t timestamp;
} connection_t;

void init_connection(connection_t *conn) {
    conn->sock = 0;
    memset(conn->ip, 0, INET6_ADDRSTRLEN);
    conn->port = 0;
    conn->timestamp = 0;
}

void connect_to_server(connection_t *conn, char *ip, unsigned short port) {
    struct sockaddr_in server_address;
    int status;

    // Set up the address structure
    memset(&server_address, 0, sizeof(server_address));
    server_address.sin_family = AF_INET;
    inet_pton(AF_INET, ip, &server_address.sin_addr);
    server_address.sin_port = htons(port);

    // Create a new socket
    conn->sock = socket(AF_INET, SOCK_STREAM, 0);
    if (conn->sock < 0) {
        printf("Socket creation failed!\n");
        return;
    }

    // Connect to the server
    status = connect(conn->sock, (struct sockaddr *)&server_address, sizeof(server_address));
    if (status < 0) {
        printf("Connection failed!\n");
        close(conn->sock);
        conn->sock = 0;
    } else {
        strcpy(conn->ip, ip);
        conn->port = port;
        conn->timestamp = time(NULL);
    }
}

void disconnect_from_server(connection_t *conn) {
    if (conn->sock > 0) {
        close(conn->sock);
        conn->sock = 0;
    }
}

int send_data(connection_t *conn, char *data, int size) {
    return send(conn->sock, data, size, 0);
}

int receive_data(connection_t *conn, char *buffer, int buffer_size) {
    return recv(conn->sock, buffer, buffer_size, 0);
}

void log_error(char *message) {
    printf("Error: %s\n", message);
}

int main() {
    connection_t connections[10]; // Limit the number of concurrent connections to 10
    int i;

    // Initialize all connections to zero
    for (i = 0; i < 10; i++) {
        init_connection(&connections[i]);
    }

    while (true) {
        char buffer[BUFFER_SIZE];
        int size, sock;
        struct sockaddr_in client_address;
        socklen_t address_size = sizeof(client_address);

        // Accept a new connection from any client
        sock = accept(listen_sock, (struct sockaddr *)&client_address, &address_size);
        if (sock < 0) {
            log_error("Accept failed!");
            continue;
        }

        // Check if there is a free slot in the connection array
        for (i = 0; i < 10; i++) {
            if (connections[i].sock == 0) {
                break;
            }
        }
        if (i == 10) {
            log_error("Maximum number of connections reached!");
            close(sock);
            continue;
        }

        // Initialize the new connection structure
        init_connection(&connections[i]);
        connections[i].sock = sock;
        strcpy(connections[i].ip, inet_ntoa(client_address.sin_addr));
        connections[i].port = ntohs(client_address.sin_port);
        connections[i].timestamp = time(NULL);

        // Read data from the client
        size = receive_data(&connections[i], buffer, BUFFER_SIZE);
        if (size < 0) {
            log_error("Receive failed!");
            disconnect_from_server(&connections[i]);
            continue;
        } else if (size == 0) {
            // Client has closed the connection
            disconnect_from_server(&connections[i]);
            continue;
        }

        // Process the received data
        process_data(&connections[i], buffer, size);
    }

    return 0;
}
