            return -1;
        }

        // Serialize the encrypted buffer using SHA-256 hash function
        unsigned char* serialized_data = serialize(encrypted, strlen(encrypted), SHA_256);
        if (serialized_data == NULL) {
            printf("Error: unable to serialize record %d\n", i + 1);
            return -1;
        }

        // Add the serialized data to the array of serialized records
        memcpy(&serialized[i * sizeof(record_t)], serialized_data, strlen(serialized_data));
    }

    // Return the allocated memory for the serialized data
    return serialized;
}

// Function to deserialize and decrypt the record data using AES-256 and SHA-256 hash function
