// Define the structure for a single transport block
typedef struct LTE_MAC_TransportBlock {
    unsigned int tag;
    unsigned short rnti;
    unsigned short transport_block_size;
} LTE_MAC_TransportBlock_t;

// Define the maximum size of the dynamic array
#define MAX_ARRAY_SIZE 1000

// Define a custom growth strategy for the dynamic array
#define GROWTH_STRATEGY(x) (x * 2)

// Define a mutex for thread safety
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to manage the dynamic array of transport blocks
int manage_transport_blocks(LTE_MAC_TransportBlock_t **arr, size_t *size) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&mutex);

    // Check if the current array is full and needs to be resized
    if (*size >= MAX_ARRAY_SIZE) {
        // Reallocate the array with a new size based on the growth strategy
        *arr = realloc(*arr, GROWTH_STRATEGY(*size));

        // Check for memory allocation failure and return error
        if (*arr == NULL) {
            pthread_mutex_unlock(&mutex);
            return -1;
        }
    }

    // Generate a new transport block with randomized size within the specified range
    LTE_MAC_TransportBlock_t *new_block = malloc(sizeof(LTE_MAC_TransportBlock_t));
    if (new_block == NULL) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }
    new_block->tag = 0xAB;
    new_block->rnti = rand() % MAX_RNTI;
    new_block->transport_block_size = rand() % (MAX_TRANSPORT_BLOCK_SIZE + 1);

    // Add the new transport block to the array
    (*arr)[*size] = new_block;
    *size += 1;

    // Release the mutex for thread safety
    pthread_mutex_unlock(&mutex);

    return 0;
}
