        return -1;
    }

    keys = malloc(key_size);
    if (!keys) {
        // handle memory allocation failure gracefully
        printf("Error: Failed to allocate key array of size %zu\n", key_size);
        free(offsets);
        return -1;
    }

    records = malloc(record_size);
