    uint32_t rnti;
    uint32_t crc_indication_rel8_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
    int num_pdus;
    NFAPI_CRC_INDICATION_PDU_T *pdu_list[MAX_PDU_COUNT];
} PDU_LIST_T;

void init_pdu_list(PDU_LIST_T *list) {
    list->mutex = (pthread_mutex_t)PTHREAD_MUTEX_INITIALIZER;
    list->num_pdus = 0;
}

int add_pdu(PDU_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->mutex);
    if (list->num_pdus >= MAX_PDU_COUNT) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // error: maximum number of PDUS reached
    }
    list->pdu_list[list->num_pdus++] = pdu;
    pthread_mutex_unlock(&list->mutex);
    return 0; // success
}

int remove_pdu(PDU_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->mutex);
    int index = -1;
    for (int i = 0; i < list->num_pdus; i++) {
        if (list->pdu_list[i] == pdu) {
            index = i;
            break;
        }
    }
    if (index >= 0) {
        for (int i = index; i < list->num_pdus - 1; i++) {
            list->pdu_list[i] = list->pdu_list[i + 1];
        }
        list->num_pdus--;
    }
    pthread_mutex_unlock(&list->mutex);
    return index; // -1 if not found, otherwise the index of the removed PDU
}

void free_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    free(pdu);
}

int main() {
