        NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdu->rx_ue_information_tag = 0;
        pdu->rnti = i + 1;
        pdu->crc_indication_rel8_tag = i * 2;
        pdu->crcflag = (i % 2) == 0; // set CRCFLAG randomly
        add_pdu(&list, pdu);
    }

    // remove a PDU
    NFAPI_CRC_INDICATION_PDU_T *removed_pdu = list.pdu_list[2];
    remove_pdu(&list, removed_pdu);
    free_pdu(removed_pdu);

    // process PDUs
    for (int i = 0; i < list.num_pdus; i++) {
