    if (!isInList(ue_id)) {
        addToList(ue_id, bearer_status, qos_params);
    }

    pthread_mutex_unlock(&context_list_lock);
}

bool isInList(uint64_t ue_id) {
    for (int i = 0; i < context_list->count; i++) {
