#include "nfapi_crc_indication.h"

// Custom random number generator for CRCFLAG values
static uint32_t crcflag_rand() {
    // Implement a reproducible random number generator using a state machine
    static uint32_t rand_state = 0;
    return rand_state += (uint32_t)(rand_r(&rand_state) % UINT32_MAX);
}

// Structure for storing RX_UE_INFORMATION_TAG and RNTI values
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T crc_indication;
    uint16_t rnti;
} nfapi_rx_ue_info_tag_t;

// Linked list node for storing elements in the list
typedef struct {
    nfapi_rx_ue_info_tag_t element;
    struct nfapi_list_node* next;
} nfapi_list_node_t;

// List head for maintaining a sorted list of RX_UE_INFORMATION_TAG and RNTI values
typedef struct {
    nfapi_list_node_t* head;
    pthread_mutex_t mutex;
} nfapi_crc_indication_list_t;

// Function for initializing the list of NFAPI_CRC_INDICATION_PDU_T structures
int32_t nfapi_crc_indication_init(nfapi_crc_indication_list_t* list, int32_t num_elements) {
    // Check input parameters
    if (list == NULL || num_elements < 0) {
        return -1;
    }

    // Initialize the mutex for thread safety
    pthread_mutex_init(&list->mutex, NULL);

    // Allocate memory for the list elements
    nfapi_list_node_t* new_element = malloc(sizeof(nfapi_list_node_t) * num_elements);
    if (new_element == NULL) {
        return -1;
    }

    // Initialize each element in the list with a valid RX_UE_INFORMATION_TAG and RNTI value
    for (int32_t i = 0; i < num_elements; i++) {
        new_element[i].element.rx_ue_information_tag = NFAPI_CRC_INDICATION_RX_UE_INFORMATION_TAG;
        new_element[i].element.rnti = rand() % UINT16_MAX + 1; // Use custom random number generator for CRCFLAG values
        new_element[i].element.crc_indication_rel8_tag = NFAPI_CRC_INDICATION_REL8_TAG;
        new_element[i].element.crcflag = crcflag_rand();
    }

    // Insert each element into the list in sorted order based on RNTI value
    nfapi_list_node_t* current = list->head;
    for (int32_t i = 0; i < num_elements; i++) {
        while (current != NULL && new_element[i].element.rnti < current->element.rnti) {
            current = current->next;
        }
        if (current == NULL) {
            list->head = &new_element[i];
