// Define the record structure
typedef struct {
  long offset;
  int key;
  double measurement;
  char status_indicator;
} record;

// Define a binary search tree node
typedef struct bst_node {
  record data;
  struct bst_node *left;
  struct bst_node *right;
} bst_node;

// Function to insert a record into the BST
bst_node* insert(record data, bst_node* root) {
  // If the tree is empty, create a new node and return it
  if (root == NULL) {
    root = malloc(sizeof(bst_node));
    root->data = data;
    root->left = NULL;
    root->right = NULL;
    return root;
  }

  // Otherwise, compare the key of the new record with the key of the current node
  int cmp = data.key - root->data.key;

  // If the new record's key is less than the current node's key, insert it to the left subtree
  if (cmp < 0) {
    root->left = insert(data, root->left);
  } else if (cmp > 0) {
    root->right = insert(data, root->right);
  }

  // If the new record's key is equal to the current node's key, replace it with a new node containing the same data and update the status indicator
  else {
    root->data.status_indicator = 'E';
    return root;
  }

  // Return the new node that contains the inserted record
  return root;
}

// Function to delete a record from the BST
bst_node* delete(int key, bst_node* root) {
  // If the tree is empty, return NULL
  if (root == NULL) return NULL;

  // Otherwise, compare the key of the new record with the key of the current node
  int cmp = key - root->data.key;

  // If the new record's key is less than the current node's key, delete it from the left subtree
  if (cmp < 0) {
    root->left = delete(key, root->left);
  } else if (cmp > 0) {
    root->right = delete(key, root->right);
  }

  // If the new record's key is equal to the current node's key, delete it and return the updated tree
  else {
    free(root);
    return NULL;
  }

  // Return the updated tree
  return root;
}

// Function to search for a record in the BST
bst_node* search(int key, bst_node* root) {
  // If the tree is empty, return NULL
  if (root == NULL) return NULL;

  // Otherwise, compare the key of the new record with the key of the current node
  int cmp = key - root->data.key;

  // If the new record's key is less than the current node's key, search in the left subtree
  if (cmp < 0) {
    return search(key, root->left);
  } else if (cmp > 0) {
    return search(key, root->right);
  }

  // If the new record's key is equal to the current node's key, return the current node
  else {
    return root;
  }
}

