void init_data(int num_entries, struct entry **entries, long **offsets, int **keys, void ***metadata) {
    // Allocate memory for the arrays of entries, offsets, keys, and metadata
    *entries = (struct entry *)malloc(num_entries * sizeof(struct entry));
    *offsets = (long *)malloc(num_entries * sizeof(long));
    *keys = (int *)malloc(num_entries * sizeof(int));
