        struct entry *entry = &(*entries)[i];
        (*offsets)[i] = entry->size;
        (*keys)[i] = i;
        (*metadata)[i] = malloc(sizeof(time_t));
        memcpy((*metadata)[i], &entry->timestamp, sizeof(time_t));
    }
}

// Function to clean up the data structures and free memory
void cleanup_data(struct entry *entries, long *offsets, int *keys, void **metadata) {
    // Free the dynamically allocated strings
    for (int i = 0; i < num_entries; i++) {
        free((*entries)[i].string);
    }

    // Free the memory allocated for the arrays of entries, offsets, keys, and metadata
    free(entries);
    free(offsets);
    free(keys);
    for (int i = 0; i < num_entries; i++) {
        free((*metadata)[i]);
    }
    free(metadata);
}
