// Define a data structure to represent the list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T **list;
    size_t count;
    pthread_mutex_t mutex;
} NFAPI_CRC_INDICATION_LIST_T;

// Define a function to create and initialize the list
NFAPI_CRC_INDICATION_LIST_T* create_crc_indication_list(size_t initial_capacity) {
    // Allocate memory for the list and its elements
    NFAPI_CRC_INDICATION_LIST_T *list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    list->list = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    memset(list->list, 0, initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    list->count = 0;

    // Initialize the mutex for thread-safe operations
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    pthread_mutex_init(&list->mutex, &attr);

    return list;
}

// Define a function to add an element to the list
void add_crc_indication(NFAPI_CRC_INDICATION_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Lock the mutex for thread-safe operations
    pthread_mutex_lock(&list->mutex);

    // Check if the list needs to be resized
    if (list->count == list->capacity) {
        // Resize the list by doubling its capacity
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T **new_list = realloc(list->list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (new_list == NULL) {
            // Reallocation failed, exit the function
            pthread_mutex_unlock(&list->mutex);
            return;
        }
        list->list = new_list;
        list->capacity = new_capacity;
    }

    // Add the element to the list
    list->list[list->count++] = pdu;

    // Unlock the mutex
    pthread_mutex_unlock(&list->mutex);
}

// Define a function to remove an element from the list
void remove_crc_indication(NFAPI_CRC_INDICATION_LIST_T *list, size_t index) {
    // Lock the mutex for thread-safe operations
    pthread_mutex_lock(&list->mutex);

    // Check if the list needs to be resized
    if (index >= list->count - 1) {
        // Reallocate the list with a reduced capacity
        size_t new_capacity = list->count - index;
        NFAPI_CRC_INDICATION_PDU_T **new_list = realloc(list->list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (new_list == NULL) {
            // Reallocation failed, exit the function
            pthread_mutex_unlock(&list->mutex);
            return;
        }
        list->list = new_list;
        list->capacity = new_capacity;
    }

    // Remove the element from the list
    memmove(list->list + index, list->list + index + 1, (list->count - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    --list->count;

    // Unlock the mutex
    pthread_mutex_unlock(&list->mutex);
}

// Define a function to retrieve an element from the list by its index
NFAPI_CRC_INDICATION_PDU_T* get_crc_indication(NFAPI_CRC_INDICATION_LIST_T *list, size_t index) {
    // Lock the mutex for thread-safe operations
    pthread_mutex_lock(&list->mutex);

    // Check if the index is within bounds
    if (index >= list->count) {
        // Return NULL if the index is out of bounds
        pthread_mutex_unlock(&list->mutex);
        return NULL;
    }

    // Retrieve the element from the list
    NFAPI_CRC_INDICATION_PDU_T *pdu = list->list[index];

    // Unlock the mutex
    pthread_mutex_unlock(&list->mutex);

    return pdu;
}

// Define a function to free the memory allocated by the list
