// Define the mutex for synchronizing access to the list
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Define a function to validate that all RNTI values are unique
void validate_rnti(NFAPI_CRC_INDICATION_LIST_T* list) {
    // Iterate over the elements in the list
    for (size_t i = 0; i < list->num_elements; i++) {
        // Check if the current RNTI value is already present in the list
        for (size_t j = i + 1; j < list->num_elements; j++) {
            if (list->elements[i].RNTI == list->elements[j].RNTI) {
                // If a duplicate is found, log an error message and terminate the function
                fprintf(stderr, "Duplicate RNTI value %d detected in NFAPI_CRC_INDICATION_PDU_T list\n", list->elements[i].RNTI);
