// Define a function to add an element to the list
void add_element(NFAPI_CRC_INDICATION_LIST_T* list, NFAPI_CRC_INDICATION_PDU_T* element) {
    // Acquire the mutex for synchronizing access to the list
    pthread_mutex_lock(&mutex);

    // Check if the list is full
    if (list->num_elements == list->capacity) {
        // If the list is full, double its capacity and reallocate memory
        list->capacity *= 2;
        list->elements = realloc(list->elements, list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    // Add the element to the end of the list
    list->elements[list->num_elements++] = *element;

    // Release the mutex for synchronizing access to the list
    pthread_mutex_unlock(&mutex);
}

// Define a function to remove an element from the list
void remove_element(NFAPI_CRC_INDICATION_LIST_T* list, uint16_t rnti) {
    // Acquire the mutex for synchronizing access to the list
    pthread_mutex_lock(&mutex);

    // Iterate over the elements in the list
    for (size_t i = 0; i < list->num_elements; i++) {
        // Check if the current element has the same RNTI value as the parameter
        if (list->elements[i].RNTI == rnti) {
            // If a match is found, remove the element from the list and break out of the loop
            memmove(&list->elements[i], &list->elements[i + 1], (list->num_elements - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list->num_elements--;
            break;
        }
    }

    // Release the mutex for synchronizing access to the list
    pthread_mutex_unlock(&mutex);
}

// Define a function to get an element from the list by its RNTI value
NFAPI_CRC_INDICATION_PDU_T* get_element(NFAPI_CRC_INDICATION_LIST_T* list, uint16_t rnti) {
