#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <sys/mman.h>
#include <unistd.h>
#include <pthread.h>
#include <errno.h>
#include <math.h>

#define SESSION_CAP 10000 // Maximum capacity of the session list
#define SESSION_TOKEN_LEN 32 // Length of a session token
#define SESSION_IP_LEN 16 // Length of an IP address string
#define SESSION_LAST_ACTIVITY_UPDATE_INTERVAL 100 // Interval (ms) for updating the last activity timestamp
#define MEMORY_USAGE_LIMIT 10 * 1024 * 1024 // Maximum memory usage limit per process (10 MB)
#define LOGGING_VERBOSITY_MAX 5 // Maximum logging verbosity level
#define LOGGING_VERBOSITY_MIN 0 // Minimum logging verbosity level

// Custom memory allocator optimized for the target hardware architecture
void* my_malloc(size_t size) {
    void *ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        printf("Error: Failed to allocate memory. %s\n", strerror(errno));
        return NULL;
    }
    return ptr;
}

// Custom free function for the custom memory allocator
void my_free(void *ptr) {
    munmap(ptr, 0);
}

// Dynamic resizing strategy for handling session growth
void dynamic_resize(session_list_t *list) {
    int new_cap = (int)(ceil(list->capacity * list->growth_factor));
    if (new_cap > MEMORY_USAGE_LIMIT / sizeof(session_t)) {
        printf("Error: Memory usage limit exceeded. %s\n", strerror(errno));
        return;
    }
    session_t *new_arr = my_malloc(new_cap * sizeof(session_t));
    memcpy(new_arr, list->arr, list->len * sizeof(session_t));
    my_free(list->arr);
    list->arr = new_arr;
    list->capacity = new_cap;
}

// Thread-safe function for adding a session to the list
void add_session(session_list_t *list, const char *token, const char *ip) {
    pthread_mutex_lock(&list->mtx);
    if (list->len == list->capacity) {
        dynamic_resize(list);
    }
    session_t *session = &list->arr[list->len++];
    memcpy(session->token, token, SESSION_TOKEN_LEN);
    memcpy(session->ip, ip, SESSION_IP_LEN);
    session->last_activity = time(NULL);
    pthread_mutex_unlock(&list->mtx);
}

// Thread-safe function for removing a session from the list
void remove_session(session_list_t *list, const char *token) {
    pthread_mutex_lock(&list->mtx);
    for (int i = 0; i < list->len; ++i) {
        if (strcmp(list->arr[i].token, token) == 0) {
            memmove(&list->arr[i], &list->arr[i + 1], (list->len - i - 1) * sizeof(session_t));
            --list->len;
            break;
        }
    }
    pthread_mutex_unlock(&list->mtx);
}

// Thread-safe function for updating the last activity timestamp of a session
void update_last_activity(session_list_t *list, const char *token) {
    pthread_mutex_lock(&list->mtx);
    for (int i = 0; i < list->len; ++i) {
        if (strcmp(list->arr[i].token, token) == 0) {
            list->arr[i].last_activity = time(NULL);
            break;
        }
    }
    pthread_mutex_unlock(&list->mtx);
}

// Thread-safe function for retrieving a session from the list by token
session_t* get_session(session_list_t *list, const char *token) {
    pthread_mutex_lock(&list->mtx);
    for (int i = 0; i < list->len; ++i) {
        if (strcmp(list->arr[i].token, token) == 0) {
            return &list->arr[i];
        }
    }
    pthread_mutex_unlock(&list->mtx);
    return NULL;
}

// Thread-safe function for retrieving all sessions from the list
session_t* get_all_sessions(session_list_t *list) {
    pthread_mutex_lock(&list->mtx);
    session_t *arr = my_malloc(list->len * sizeof(session_t));
    memcpy(arr, list->arr, list->len * sizeof(session_t));
    pthread_mutex_unlock(&list->mtx);
    return arr;
}

// Thread-safe function for serializing the session list to a file
void serialize_sessions(session_list_t *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        printf("Error: Failed to open file. %s\n", strerror(errno));
        return;
    }
    pthread_mutex_lock(&list->mtx);
    int size = list->len * sizeof(session_t);
    fwrite(&size, sizeof(int), 1, file);
    fwrite(list->arr, size, 1, file);
    pthread_mutex_unlock(&list->mtx);
    fclose(file);
}

// Thread-safe function for deserializing the session list from a file
void deserialize_sessions(session_list_t *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Error: Failed to open file. %s\n", strerror(errno));
        return;
    }
    pthread_mutex_lock(&list->mtx);
    int size = 0;
    fread(&size, sizeof(int), 1, file);
    list->arr = my_malloc(size);
    list->len = (int)(ceil(size / sizeof(session_t)));
    list->capacity = list->len;
    list->growth_factor = 2.0;
    fread(list->arr, size, 1, file);
    pthread_mutex_unlock(&list->mtx);
    fclose(file);
}

// Struct for storing a session
typedef struct {
    char token[SESSION_TOKEN_LEN];
    char ip[SESSION_IP_LEN];
    time_t last_activity;
} session_t;

// Struct for storing the list of sessions
typedef struct {
    session_t *arr;
    int len, capacity;
    double growth_factor;
    pthread_mutex_t mtx;
} session_list_t;

int main() {
    // Initialize the session list with a fixed number of slots and a growth factor for dynamic resizing
    session_list_t list;
    list.arr = my_malloc(10 * sizeof(session_t));
    list.len = 0;
    list.capacity = 10;
    list.growth_factor = 2.0;
    pthread_mutex_init(&list.mtx, NULL);

    // Add a few sessions to the list
    add_session(&list, "token1", "ip1");
    add_session(&list, "token2", "ip2");
    add_session(&list, "token3", "ip3");

    // Remove a session from the list by token
    remove_session(&list, "token2");

    // Update the last activity timestamp of a session in the list
    update_last_activity(&list, "token1");

    // Retrieve a session from the list by token
    session_t *session = get_session(&list, "token3");
    if (session != NULL) {
        printf("Session %s has IP address %s and last activity at %s\n", session->token, session->ip, ctime(&session->last_activity));
    } else {
        printf("Session not found\n");
    }

    // Retrieve all sessions from the list
    session_t *all_sessions = get_all_sessions(&list);
    for (int i = 0; i < list.len; ++i) {
        printf("Session %s has IP address %s and last activity at %s\n", all_sessions[i].token, all_sessions[i].ip, ctime(&all_sessions[i].last_activity));
    }

    // Serialize the session list to a file
    serialize_sessions(&list, "session_data.dat");

    // Deserialize the session list from a file
    deserialize_sessions(&list, "session_data.dat");

    return 0;
}
