typedef struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned int rx_ue_information_tag;
    unsigned int rnti;
    unsigned int crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct CRC_INDICATION_LIST {
    pthread_mutex_t mutex;
    struct node *head;
    int size;
} CRC_INDICATION_LIST;

struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
};

void add_crc_indication(NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&mutex);
    struct node *new_node = malloc(sizeof(struct node));
    if (new_node == NULL) {
        // Handle memory allocation failure gracefully
    }
    new_node->data = *data;
    new_node->next = head;
    head = new_node;
    size++;
    pthread_mutex_unlock(&mutex);
}

void remove_crc_indication(NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&mutex);
    struct node *prev = NULL;
    struct node *current = head;
    while (current != NULL && current->data.rnti != data->rnti) {
        prev = current;
        current = current->next;
    }
    if (current == NULL) {
        // Handle removal failure gracefully
    }
    if (prev == NULL) {
        head = current->next;
    } else {
        prev->next = current->next;
    }
    size--;
    pthread_mutex_unlock(&mutex);
}

void get_crc_indications(CRC_INDICATION_LIST *list) {
    pthread_mutex_lock(&mutex);
    list->head = head;
    list->size = size;
    pthread_mutex_unlock(&mutex);
}

void free_crc_indications(CRC_INDICATION_LIST *list) {
    struct node *current = list->head;
    while (current != NULL) {
        struct node *next = current->next;
        free(current);
        current = next;
    }
}
