// Custom allocator to minimize fragmentation and ensure prompt reclaiming of unused memory
void* custom_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        // Handle memory exhaustion or other errors
        return NULL;
    }
    memset(ptr, 0, size);
    return ptr;
}

// Custom free function to deallocate memory allocated by custom_malloc()
