// Function to initialize the record collection and periodically update the last accessed timestamp for each record
void update_records(void) {
    // Initialize the records array if it is not already initialized
    if (records == NULL) {
        records = custom_malloc(sizeof(Record) * num_records);
        memset(records, 0, sizeof(Record) * num_records);
    }

    // Update the last accessed timestamp for each record
    for (size_t i = 0; i < num_records; ++i) {
        records[i].last_accessed = time(NULL);
    }
}

// Function to add a new record to the collection
