    // Increase the number of records in the collection
    ++num_records;

    // Reallocate memory for the records array if necessary
    if (records == NULL || num_records > records->size) {
        records = custom_realloc(records, sizeof(Record) * num_records);
    }

    // Set the offset, key, and status of the new record
    records[num_records - 1].offset = offset;
    records[num_records - 1].key = key;
    records[num_records - 1].status = status;
}

// Function to remove a record from the collection
void remove_record(long offset) {
    // Find the index of the record with the matching offset
    int index = -1;
    for (size_t i = 0; i < num_records; ++i) {
        if (records[i].offset == offset) {
            index = i;
            break;
        }
    }

    // If the record was found, remove it by shifting all subsequent records to the left
    if (index != -1) {
        --num_records;
        for (size_t i = index; i < num_records; ++i) {
            records[i] = records[i + 1];
        }
        custom_free(records[num_records]);
    }
}

// Function to update the status of a record in the collection
void update_status(long offset, char status) {
    // Find the index of the record with the matching offset
    int index = -1;
    for (size_t i = 0; i < num_records; ++i) {
        if (records[i].offset == offset) {
            index = i;
            break;
        }
    }

    // If the record was found, update its status
    if (index != -1) {
        records[index].status = status;
    }
}

// Function to query the current state of the records array
void query_records(void) {
    // Output the values, timestamps, and statuses of all records in the collection
    for (size_t i = 0; i < num_records; ++i) {
        printf("Record %lu: offset=%ld, key=%d, status=%c, last accessed=%s\n",
               i + 1, records[i].offset, records[i].key, records[i].status, ctime(&records[i].last_accessed));
    }
}

// Main function to manage the record collection and periodically update the last accessed timestamp for each record
int main(void) {
    // Initialize the records array and set up periodic updates
    init_records();
    while (1) {
        update_records();
        sleep(update_interval);
    }
}
