// Structure to store NIC statistics
struct NicStat {
    MAC_HEADER macHeader;
    IP_PACKET ipPacket;
};

// Global variables for dynamic array and cache
int MAX_NICS = 10000; // Maximum number of NICs to store in the array
int CACHE_SIZE = 100; // Size of the cache for recently used structures
struct NicStat *nicArray = NULL; // Dynamic array of NIC statistics
struct NicStat *cache = NULL; // Cache of recently used structures
int nicCount = 0; // Number of NICs currently stored in the array
int cacheIndex = 0; // Index of the next available position in the cache

// Function to initialize the dynamic array and cache
void initNicArray() {
    // Allocate memory for the dynamic array and cache
    nicArray = (struct NicStat *)malloc(MAX_NICS * sizeof(struct NicStat));
    cache = (struct NicStat *)malloc(CACHE_SIZE * sizeof(struct NicStat));

    // Initialize the dynamic array with empty structures
    for (int i = 0; i < MAX_NICS; i++) {
        nicArray[i].macHeader = NULL;
        nicArray[i].ipPacket = NULL;
    }

    // Initialize the cache with empty structures
    for (int i = 0; i < CACHE_SIZE; i++) {
        cache[i].macHeader = NULL;
        cache[i].ipPacket = NULL;
    }
}

// Function to add a new NIC statistics structure to the dynamic array and cache
void addNicStat(struct NicStat nic) {
    // Check if the cache is full, if so remove the oldest entry first
    if (cacheIndex == CACHE_SIZE) {
        int oldestEntry = 0;
        for (int i = 1; i < CACHE_SIZE; i++) {
            if (cache[i].timestamp < cache[oldestEntry].timestamp) {
                oldestEntry = i;
            }
        }

        // Remove the oldest entry from the cache
        free(cache[oldestEntry].macHeader);
        free(cache[oldestEntry].ipPacket);
        nicCount--;
    }

    // Add the new NIC statistics to the dynamic array and cache
    nicArray[nicCount] = nic;
    cache[cacheIndex] = nic;
    nic.timestamp = time(NULL);
    cacheIndex++;

    // Update the number of NICs in the array
    nicCount++;
}

// Function to remove a NIC statistics structure from the dynamic array and cache
void removeNicStat(int index) {
    // Check if the index is valid
    if (index >= 0 && index < nicCount) {
        // Remove the NIC statistics from the cache
        struct NicStat *toRemove = &cache[index];
        free(toRemove->macHeader);
        free(toRemove->ipPacket);

        // Update the number of NICs in the array and shift the remaining structures
        nicCount--;
        for (int i = index; i < nicCount - 1; i++) {
            cache[i] = cache[i + 1];
        }
    }
}

// Function to update the IP_PACKET checksums in the dynamic array and cache
void validateIpPacketChecksums() {
    // Iterate over all NIC statistics structures in the array and cache
    for (int i = 0; i < nicCount; i++) {
        struct NicStat *nic = &cache[i];

        // Check if the IP_PACKET checksum is valid, if not discard the packet
        if (!validateIpChecksum(nic->ipPacket)) {
            removeNicStat(i);
            i--;
        }
    }
}

// Function to validate the IP_PACKET checksums in a given NIC statistics structure
bool validateIpChecksum(struct IpPacket *ip) {
    // Calculate the IP_PACKET checksum using the specified algorithm
    int checksum = calculateIpChecksum(ip);

    // Check if the calculated checksum matches the actual checksum in the NIC statistics structure
    return (checksum == ip->checksum);
}

// Function to calculate the IP_PACKET checksum using the specified algorithm
int calculateIpChecksum(struct IpPacket *ip) {
    // Initialize the checksum with the sum of all 16-bit words in the header
    int checksum = 0;

    // Iterate over all 16-bit words in the header, except for the checksum field itself
    for (int i = 0; i < ip->headerLength / 2 - 1; i++) {
        checksum += *(uint16_t *)((char *)ip + i);
    }

    // Return the calculated checksum
    return checksum;
}

// Function to log the number of valid and invalid packets processed
void logPacketCounts() {
    // Print the number of valid and invalid packets processed to the console
    printf("Valid packets: %d\n", nicCount);
    printf("Invalid packets: %d\n", 0);
}
