    StudentData *students = (StudentData *)malloc(numStudents * sizeof(StudentData));
    memset(students, 0, numStudents * sizeof(StudentData));

    // Initialize student data to empty
    for (int i = 0; i < numStudents; i++) {
        students[i].name = "";
        students[i].avgScore = 0.0;
        students[i].grades = NULL;
        students[i].numGrades = 0;
    }

    // Allocate memory for arrays of courses
    EnrollmentRecord *courses = (EnrollmentRecord *)malloc(numCourses * sizeof(EnrollmentRecord));
    memset(courses, 0, numCourses * sizeof(EnrollmentRecord));

    // Initialize course data to empty
    for (int i = 0; i < numCourses; i++) {
        courses[i].courseCode = "";
        courses[i].semester = 0;
        courses[i].studentIDs = NULL;
        courses[i].numStudents = 0;
    }

    // Return allocated memory
    return scores, students, courses;
}

// Define function to validate and format scores
void validateScore(double *score) {
    if (*score < 0 || *score > 100) {
        *score = 0.0;
    }
}

// Define function to handle missing or invalid data gracefully
void handleMissingData(char *name, double score) {
    // Handle missing name by setting name to empty string
    if (strcmp(name, "") == 0) {
        name = "";
    }

    // Handle missing score by setting score to zero
    if (score < 0 || score > 100) {
        score = 0.0;
    }
}

// Define function to maintain statistics on scores, including highest, lowest, and average scores over a given period
void calculateStats(double *scores, int numScores) {
    // Calculate highest score
    double highestScore = scores[0];
    for (int i = 1; i < numScores; i++) {
        if (scores[i] > highestScore) {
            highestScore = scores[i];
        }
    }

    // Calculate lowest score
    double lowestScore = scores[0];
    for (int i = 1; i < numScores; i++) {
        if (scores[i] < lowestScore) {
            lowestScore = scores[i];
        }
    }

    // Calculate average score
    double sum = 0.0;
    for (int i = 0; i < numScores; i++) {
        sum += scores[i];
    }
    double averageScore = sum / numScores;
}

// Define function to manage memory usage for a dynamic list of students, allowing efficient insertion and deletion of students based on their unique IDs, while ensuring no duplicate IDs are added to the hash table structure for average O(1) lookup times
void manageStudents(char *name, double score, StudentData **students, int *numStudents, int *nextID) {
    // Check if student ID already exists in hash table
    bool duplicate = false;
    for (int i = 0; i < *numStudents; i++) {
        if ((*students)[i].name == name) {
            duplicate = true;
            break;
        }
    }

    // If student ID does not exist, add it to hash table and increment nextID
    if (!duplicate) {
        (*students)[(*nextID)] = (StudentData){ .name = name, .avgScore = score };
        *numStudents += 1;
        *nextID += 1;
    }
}

// Define function to calculate the average grade for each course and identify courses with a passing rate below a specified threshold
void calculateAverageGrade(double **scores, int numCourses) {
    // Calculate average score for each course
    double *averageScores = (double *)malloc(numCourses * sizeof(double));
    for (int i = 0; i < numCourses; i++) {
        averageScores[i] = 0.0;
        int count = 0;
        for (int j = 0; j < (*scores)[i]; j++) {
            if ((*scores)[j] > 0) {
                averageScores[i] += (*scores)[j];
                count++;
            }
        }
        averageScores[i] /= count;
    }

    // Identify courses with a passing rate below the specified threshold
    int *passingCourses = (int *)malloc(numCourses * sizeof(int));
    for (int i = 0; i < numCourses; i++) {
        if (averageScores[i] >= 65) {
            passingCourses[i] = 1;
        } else {
            passingCourses[i] = 0;
        }
    }
}

// Define function to manage memory usage for a dynamic list of courses, allowing efficient insertion and deletion of courses, and providing a way to update enrollment records as students join or leave courses
void manageCourses(char *courseCode, int semester, StudentData **students, int *numStudents, EnrollmentRecord **courses, int *numCourses) {
    // Check if course already exists in hash table
    bool duplicate = false;
    for (int i = 0; i < *numCourses; i++) {
        if ((*courses)[i].courseCode == courseCode) {
            duplicate = true;
            break;
        }
    }

    // If course does not exist, add it to hash table and increment nextID
    if (!duplicate) {
        (*courses)[(*numCourses)] = (EnrollmentRecord){ .courseCode = courseCode, .semester = semester };
        *numCourses += 1;
    }
}

// Define function to update enrollment records as students join or leave courses
void updateEnrollmentRecords(char *name, double score, StudentData **students, int numStudents, EnrollmentRecord **courses, int numCourses) {
    // Check if student is already enrolled in course
    bool duplicate = false;
    for (int i = 0; i < *numCourses; i++) {
        if ((*students)[i].name == name && (*courses)[i].semester > semester) {
            duplicate = true;
            break;
        }
    }

    // If student is already enrolled in course, update enrollment record
    if (duplicate) {
        for (int i = 0; i < *numStudents; i++) {
            if ((*students)[i].name == name) {
                (*students)[i].score = score;
                break;
            }
        }
    } else {
        // If student is not enrolled in course, add them to the hash table and increment nextID
        manageStudents(name, score, students, numStudents);
    }
}
