// Custom hash table structure for efficient look-up of records based on their 'int' key
typedef struct {
    int size;         // Size of the hash table (number of buckets)
    int count;        // Number of records stored in the hash table
    int* keys;        // Array of unique integer keys
    void** values;    // Array of corresponding 'record' structures
} HashTable;

// Custom record structure for storing a long offset value, an int key, and a double precision value
typedef struct {
    long offset;      // Long offset value
    int key;          // Integer key
    double value;     // Double precision value
} Record;

// Hash function for generating hash values based on integer keys
int hash(int key) {
    return (key % 1000) * 7919 + (key % 32865) * 4331;
}

// Initializes a new record structure with the given long offset value, int key, and double precision value
Record* create_record(long offset, int key, double value) {
    Record* r = malloc(sizeof(Record));
    if (!r) {
        // Handle memory allocation failure gracefully
        return NULL;
    }
    r->offset = offset;
    r->key = key;
    r->value = value;
    return r;
}

// Adds a new record to the hash table, using custom hash function and separate chaining
void add_record(HashTable* ht, long offset, int key, double value) {
    // Check if the key is already present in the hash table
    for (int i = 0; i < ht->count; i++) {
        if (ht->keys[i] == key) {
            // Handle duplicate entries gracefully
            return;
        }
    }
    // Calculate the index of the new record in the hash table
    int idx = hash(key) % ht->size;
    Record* r = create_record(offset, key, value);
    if (!r) {
        // Handle memory allocation failure gracefully
        return;
    }
    // Add the new record to the corresponding bucket in the hash table
    r->next = ht->values[idx];
    ht->values[idx] = r;
    ht->keys[ht->count++] = key;
}

// Removes a record from the hash table, using custom hash function and separate chaining
void remove_record(HashTable* ht, int key) {
    // Check if the key is present in the hash table
    for (int i = 0; i < ht->count; i++) {
        if (ht->keys[i] == key) {
            // Remove the record from its corresponding bucket in the hash table
            Record** ptr = &(ht->values[hash(key) % ht->size]);
            while (*ptr != NULL && (*ptr)->key != key) {
                ptr = &((*ptr)->next);
            }
            if (*ptr == NULL) {
                // Handle non-existent keys gracefully
                return;
            }
            Record* r = *ptr;
            *ptr = r->next;
            free(r);
            ht->count--;
            return;
        }
    }
    // Handle non-existent keys gracefully
}

// Updates the value of an existing record in the hash table, using custom hash function and separate chaining
void update_record(HashTable* ht, int key, double value) {
    // Check if the key is present in the hash table
    for (int i = 0; i < ht->count; i++) {
        if (ht->keys[i] == key) {
            // Update the corresponding record's value
            Record** ptr = &(ht->values[hash(key) % ht->size]);
            while (*ptr != NULL && (*ptr)->key != key) {
                ptr = &((*ptr)->next);
            }
            if (*ptr == NULL) {
                // Handle non-existent keys gracefully
                return;
            }
            Record* r = *ptr;
            r->value = value;
            return;
        }
    }
    // Handle non-existent keys gracefully
}

// Searches for a record in the hash table, using custom hash function and separate chaining
Record* search_record(HashTable* ht, int key) {
    // Check if the key is present in the hash table
    for (int i = 0; i < ht->count; i++) {
        if (ht->keys[i] == key) {
            // Return the corresponding record from its corresponding bucket in the hash table
            Record** ptr = &(ht->values[hash(key) % ht->size]);
            while (*ptr != NULL && (*ptr)->key != key) {
                ptr = &((*ptr)->next);
            }
            if (*ptr == NULL) {
                // Handle non-existent keys gracefully
                return NULL;
            }
            Record* r = *ptr;
            return r;
        }
    }
    // Handle non-existent keys gracefully
}

// Resizes the hash table if necessary, using custom hash function and separate chaining
void resize_hash_table(HashTable* ht) {
    // Check if the load factor exceeds 0.9 or falls below 0.7
    float load_factor = (float)ht->count / (float)ht->size;
    if (load_factor > 0.9) {
        // Double the size of the hash table and rehash all records
        int new_size = ht->size * 2;
        HashTable* new_ht = malloc(sizeof(HashTable));
        new_ht->size = new_size;
        new_ht->count = ht->count;
        new_ht->keys = malloc(new_size * sizeof(int));
        new_ht->values = malloc(new_size * sizeof(void*));
        for (int i = 0; i < ht->size; i++) {
            Record** ptr = &(ht->values[i]);
            while (*ptr != NULL) {
                int key = (*ptr)->key;
                int hash_value = hash(key) % new_size;
                Record* r = create_record((*ptr)->offset, key, (*ptr)->value);
                if (!r) {
                    // Handle memory allocation failure gracefully
                    return;
                }
                r->next = new_ht->values[hash_value];
                new_ht->values[hash_value] = r;
                ptr = &((*ptr)->next);
            }
        }
        free(ht->keys);
        free(ht->values);
        ht->size = new_ht->size;
        ht->count = new_ht->count;
        ht->keys = new_ht->keys;
        ht->values = new_ht->values;
    } else if (load_factor < 0.7) {
        // Half the size of the hash table and rehash all records
        int new_size = ht->size / 2;
        HashTable* new_ht = malloc(sizeof(HashTable));
        new_ht->size = new_size;
        new_ht->count = ht->count;
        new_ht->keys = malloc(new_size * sizeof(int));
        new_ht->values = malloc(new_size * sizeof(void*));
        for (int i = 0; i < ht->size; i++) {
            Record** ptr = &(ht->values[i]);
            while (*ptr != NULL) {
                int key = (*ptr)->key;
                int hash_value = hash(key) % new_size;
                Record* r = create_record((*ptr)->offset, key, (*ptr)->value);
                if (!r) {
                    // Handle memory allocation failure gracefully
                    return;
                }
                r->next = new_ht->values[hash_value];
                new_ht->values[hash_value] = r;
                ptr = &((*ptr)->next);
            }
        }
        free(ht->keys);
        free(ht->values);
        ht->size = new_ht->size;
        ht->count = new_ht->count;
        ht->keys = new_ht->keys;
        ht->values = new_ht->values;
    }
}

// Prints the contents of a hash table, using custom hash function and separate chaining
void print_hash_table(HashTable* ht) {
    // Iterate over all records in the hash table
    for (int i = 0; i < ht->size; i++) {
        Record** ptr = &(ht->values[i]);
        while (*ptr != NULL) {
            printf("%d, %lf\n", (*ptr)->key, (*ptr)->value);
            ptr = &((*ptr)->next);
        }
    }
}

// Frees the memory allocated by a hash table, using custom hash function and separate chaining
void free_hash_table(HashTable* ht) {
    // Iterate over all records in the hash table and free their memory
    for (int i = 0; i < ht->size; i++) {
        Record** ptr = &(ht->values[i]);
        while (*ptr != NULL) {
            Record* r = *ptr;
            *ptr = r->next;
            free(r);
        }
    }
    // Free the memory allocated to the hash table's keys and values arrays
    free(ht->keys);
    free(ht->values);
}
