// Custom memory allocator
void* my_malloc(size_t size) {
    // Memory pool for the array of structures
    static void* mempool;
    // Size of the allocated memory block
    static size_t mempool_size;
    // Lock to protect concurrent access
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Acquire the lock
    pthread_mutex_lock(&lock);

    // Check if there is enough memory available in the pool
    if (mempool_size < size) {
        // Release the lock and return NULL to indicate insufficient resources
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Allocate a new block of memory from the pool
    void* ptr = mempool;
    mempool += size;
    mempool_size -= size;

    // Release the lock
    pthread_mutex_unlock(&lock);

    return ptr;
}

// Custom free function to release memory allocated by my_malloc()
void my_free(void* ptr) {
    // Lock to protect concurrent access
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Acquire the lock
    pthread_mutex_lock(&lock);

    // Release the memory block back to the pool
    mempool -= size;
    mempool_size += size;

    // Release the lock
    pthread_mutex_unlock(&lock);
}

