    // Process each file concurrently
    for (int i = 0; i < file_count; i++) {
        char *file = files[i];

        // Fork a child process to handle the file processing
        pid_t child_pid = fork();
        if (child_pid == -1) {
            fprintf(stderr, "Failed to fork child process.\n");
            return;
        } else if (child_pid == 0) {
            // Child process: Process the file and populate the structures
            int fd = open(file, O_RDONLY);
