                structs[struct_count].rnti = rnti;
                structs[struct_count].crc_indication_rel8_tag = crc_indication_rel8_tag;
                structs[struct_count].crcflag = crcflag;
                struct_count++;
            }

            // Close the file and return
            close(fd);
            return;
        } else {
            // Parent process: Wait for the child process to complete
            waitpid(child_pid, NULL, 0);
        }
    }

    // Free memory used by the files list and the NFAPI structures
